(window.GIM_TUR_P=window.GIM_TUR_P||{})["SYD.4"]={"from":300,"s":[["כֵּיוָן שֶׁנִּתְחַבֵּר הַצֶּמֶר עִם הַפִּשְׁתָּן צַד חִבּוּר בָּעוֹלָם, אָסוּר מִשּׁוּם כִּלְאַיִם. כֵּיצַד, צֶמֶר וּפִשְׁתִּים שֶׁטְּרָפָן זֶה עִם זֶה וְשַׁע אוֹתָם \u0010y0\u0011 וְעָשָׂה מֵהֶם לְבָדִים, \u0010c0\u0011 אוֹ שֶׁטְּרָפָן וְטָוָה אוֹתָם כְּאֶחָד, וְאָרַג בֶּגֶד מִטִּוּוּי זֶה, אוֹ שֶׁתָּפַר בֶּגֶד צֶמֶר בְּשֶׁל פִּשְׁתָּן, \u0010y1\u0011 אֲפִלּוּ תְּפָרָן בְּחוּטֵי מֶשִׁי וְקַנַּבּוֹס, אוֹ שֶׁתָּפַר בֶּגֶד צֶמֶר בְּחוּטֵי פִּשְׁתָּן אוֹ בֶּגֶד פִּשְׁתָּן בְּחוּטֵי צֶמֶר, אוֹ קָשַׁר חוּטֵי צֶמֶר בְּחוּטֵי פִּשְׁתָּן אוֹ גְּדָּלָן, הֲרֵי זֶה כִּלְאַיִם.\nבֶּגֶד צֶמֶר שֶׁחִבְּרוֹ עִם בֶּגֶד פִּשְׁתָּן בִּתְכִיפָה אַחַת \u0005(פי' בִּתְחִיבָה אַחַת שֶׁתָּחַב הַמַּחַט בַּבֶּגֶד)\u0006, אֵינוֹ חִבּוּר וְאֵין זֶה כִּלְאַיִם. \u0010c1\u0011 קִבֵּץ שְׁנֵי רָאשֵׁי הַחוּט כְּאֶחָד, \u0010c2\u0011 אוֹ שֶׁתָּכַף שְׁתֵּי תְּכִיפוֹת, הֲרֵי זֶה כִּלְאַיִם. \u0010c3\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּלֹא הָוֵי כִּלְאַיִם \u0010y2\u0011 אֶלָּא בְּב' תְּכִיפוֹת וְקָשַׁר ב' רָאשֵׁי הַחוּט (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nבֶּגֶד צֶמֶר שֶׁנִּפְרַם \u0005(פי' נִקְרַע)\u0006, \u0010y3\u0011 מֻתָּר לִפְרֹף \u0005(פי' לְחַבֵּר)\u0006 אוֹתוֹ בְּחוּטֵי פִּשְׁתָּן, \u0010c4\u0011 וְקוֹשֵׁר, אֲבָל לֹא יִתְפֹּר. \u0005הַגָּה: וְכֵן מֻתָּר לִתֵּן צֶמֶר בְּכַר אוֹ כֶּסֶת שֶׁל פִּשְׁתָּן, אַף עַל פִּי שֶׁתּוֹפֵר כָּל סְבִיבָיו וְאֵינוֹ יָכוֹל לְהוֹצִיא הַצֶּמֶר, \u0010c5\u0011 הָוֵי כְּשַׂק שֶׁל פִּשְׁתִּים שֶׁמְּמַלְּאוֹ צֶמֶר \u0010c6\u0011 וְתָפַר פִּיו, שֶׁאֵין בָּזֶה מִשּׁוּם כִּלְאַיִם (כֵּן הוּא בַּטּוּר)\u0006. וַאֲפִלּוּ \u0005(תָּחַב)\u0006 הַתְּפִירָה בַּצֶּמֶר עַצְמוֹ, \u0010y4\u0011 מֻתָּר, דַּהֲרֵי יָכוֹל לִקַּח הַצֶּמֶר מִשָּׁם בְּלֹא הַתָּרַת הַתְּפִירָה. \u0010c7\u0011 אֲבָל בִּבְלָאֵי בְּגָדִים שֶׁל צֶמֶר, \u0010y5\u0011 אָסוּר בִּכְהַאי גַּוְנָא, שֶׁהֲרֵי אִי אֶפְשָׁר לִקַּח מִשָּׁם הַבְּגָדִים בְּלֹא הַתָּרַת הַתְּפִירָה \u0005(ד\"ע וּמָרְדְּכַי פ' בַּמֶּה אִשָּׁה וְתּוֹס' ספ\"ק דְּבֵיצָה)\u0006. וְכֵן מֻתָּר לְחַבֵּר בָּתֵּי זְרוֹעוֹת שֶׁל צֶמֶר שֶׁיֵּשׁ בָּהֶם קְשָׁרִים, אוֹ קְרָסִים בְּבָתֵּי נֶפֶשׁ שֶׁל פִּשְׁתָּן שֶׁיֵּשׁ בּוֹ נְקָבִים, וּמַכְנִיסִים הַקְּשָׁרִים אוֹ הַקְּרָסִים תּוֹךְ הַנְּקָבִים, הוֹאִיל וְהֵם רְפוּיִים וְיָכוֹל לְהוֹצִיאָן מִשָּׁם בְּאֶצְבָּעוֹ וְאֵין צָרִיךְ לִקְרֹעַ הַנְּקָבִים, אַף עַל פִּי שֶׁמַּנִּיחָן כָּךְ תָּמִיד. אֲבָל אִם הֵם אֲדוּקִים כָּל כָּךְ שֶׁאִי אֶפְשָׁר לְהוֹצִיאָן מִשָּׁם בִּלְתִּי קְרִיעַת הַנְּקָבִים, הָוֵי חִבּוּר וְאָסוּר \u0005(ת\"ה סי' רנ\"ו)\u0006. \u0010c8\u0011\nמֻתָּר לִלְבֹּשׁ חָלוּק שֶׁל צֶמֶר עַל גַּבֵּי חָלוּק שֶׁל פִּשְׁתָּן וּלְקָשְׁרָם יַחַד, אַף עַל פִּי שֶׁאֵינוֹ יָכוֹל לְפָשְׁטָן בְּלֹא הַתָּרַת הַקֶּשֶׁר, \u0010y6\u0011 וַאֲפִלּוּ הוּא קֶשֶׁר שֶׁל קַיָּמָא, וּבִלְבַד שֶׁלֹּא יְחַבְּרֵם זֶה לָזֶה עִם הַמְּשִׁיחָה בִּשְׁתֵּי תְּכִיפוֹת. וְיֵשׁ אוֹסְרִים בְּקֶשֶׁר שֶׁל קַיָּמָא. \u0005הַגָּה: \u0010y7\u0011 וְנִרְאֶה לִי דְּאוֹתָן בָּתֵּי שׁוֹקַיִם שֶׁעוֹשִׂין בִּמְדִינוֹת אֵלּוּ וְקוֹרִין אוֹתוֹ פורטקי, דְּהַיְנוּ שֶׁעֲשׂוּיִן שֶׁל צֶמֶר וְעוֹשִׂים בָּהֶם מְשִׁיחָה שֶׁעוֹבֶרֶת בָּהֶן הֵנָּה וָהֵנָּה כְּמוֹ רְצוּעָה בְּמַעְבַּרְתָּא דִּתְפִילִּין, דְּמֻתָּר אֲפִלּוּ הַמְּשִׁיחָה שֶׁל פִּשְׁתָּן אוֹ אִפְּכָא, דְּמֵאַחַר דְּאֶפְשָׁר לְהוֹצִיא מִשָּׁם הַמְּשִׁיחָה בְּלֹא הַתָּרַת הַתְּפִירָה אֵינוֹ אֶלָּא כְּחוֹגֵר בִּמְשִׁיחָה שֶׁל פִּשְׁתָּן עַל גַּבֵּי חָלוּק שֶׁל צֶמֶר. וְאַף עַל פִּי שֶׁקּוֹשֵׁר הַמְּשִׁיחָה כְּשֶׁלְּבָשָׁן, לֹא מִקְרֵי קֶשֶׁר שֶׁל קַיָּמָא. אֲבָל אִם עוֹשֶׂה קְשָׁרִים בְּב' רָאשֵׁי הַמְּשִׁיחָה, נִרְאֶה דְּאָסוּר, דְּהָא אִי אֶפְשָׁר לְהוֹצִיא מִשָּׁם (הַכֹּל סְבָרַת הָרַב)\u0006. יֵשׁ אוֹמְרִים דְּאָסוּר \u0010y8\u0011 לִלְבֹּשׁ ב' בָּתֵּי שׁוֹקַיִם, אֶחָד שֶׁל פִּשְׁתָּן וְאֶחָד שֶׁל צֶמֶר, זוֹ עַל זוֹ \u0005(הַגָּהַת אֲשֵׁרִ\"י פ\"ק דְּבֵיצָה)\u0006, דְּמֵאַחַר דְּאִי אֶפְשָׁר לִפְשֹׁט הַתַּחְתּוֹנָה בְּלֹא הָעֶלְיוֹנָה הָוֵי כְּחִבּוּר, \u0010y9\u0011 \u0010c9\u0011 וְלֹא דָּמֵי לְב' חֲלוּקִים זוֹ עַל זוֹ עַל זוֹ דְּאֶפְשָׁר לִפְשֹׁט הַתַּחְתּוֹן בְּלֹא הָעֶלְיוֹן \u0005(כָּךְ מָצָא הַטַּעַם בְּאוֹר זָרוּעַ)\u0006 וְנָכוֹן לִזָּהֵר.\nרְצוּעָה אַחַת שֶׁל צֶמֶר וְהַשְּׁנִיָּה שֶׁל פִּשְׁתָּן, אָסוּר לַחֲגֹר בָּהּ אַף עַל פִּי שֶׁרְצוּעָה שֶׁל עוֹר בָּאֶמְצַע, מִפְּנֵי שֶׁקּוֹשֵׁר שְׁנֵי רָאשֶׁיהָ בְּיַחַד כְּשֶׁחוֹגֵר בָּהּ. אֲבָל אִם בְּאֶמְצָעִיתָהּ צֶמֶר בְּמָקוֹם אֶחָד וּפִשְׁתָּן בְּמָקוֹם אַחֵר, וְאֵינָם זֶה אֵצֶל זֶה, מֻתָּר. וּלְפִי זֶה מֻתָּר לְחַבֵּר עוֹרוֹת הַתְּפוּרוֹת בְּפִשְׁתָּן תַּחַת בִּגְדֵי צֶמֶר, \u0010y10\u0011 וְאַף עַל פִּי שֶׁאֶפְשָׁר שֶׁיַּכְנִיס חוּט הַקַּנַּבּוֹס שֶׁל הַתְּפִירָה, שֶׁמְּחַבֵּר הָעוֹר עִם הַבֶּגֶד בְּתוֹךְ חוּט שֶׁל תְּפִירַת הָעוֹר \u0005(ר' יְרוּחָם ות\"ה סי' רצ\"ז)\u0006 וּלְהָרַמְבַּ\"ם כָּל זֶה כִּלְאַיִם מִן הַתּוֹרָה, וַאֲפִלּוּ נָתַן צֶמֶר וּפִשְׁתִּים בְּשַׂק אוֹ קֻפָּה וּכְרָכָן, הָוֵי כִּלְאַיִם מִדְּאוֹרַיְתָא. \u0005וְהַמִּנְהָג כִּסְבָרָא רִאשׁוֹנָה (טוּר וְכֵן כָּתַב הָרַמְבַּ\"ן וְהָרַשְׁבָּ\"א סִימָן ש\"ס ות\"ה סִימָן רצ\"ז)\u0006.\nהַמַּנְהִיג בְּהֵמוֹת וּמַכְנִיס חֲבָלִים לְתוֹךְ יָדוֹ, מֵהֶם פִּשְׁתִּים וּמֵהֶם צֶמֶר, הֲרֵי זֶה מֻתָּר, וְאַף עַל פִּי שֶׁכּוֹרְכָן עַל יָדוֹ. \u0010c10\u0011 אֲבָל אִם קְשָׁרָם כֻּלָּם, נַעֲשׂוּ כִּלְאַיִם, \u0010y11\u0011 וְאָסוּר לוֹ לְכָרְכָם עַל יָדוֹ. \u0010y12\u0011 \u0005וְיֵשׁ מַתִּירִין, הוֹאִיל וְאֵינוֹ מִתְכַּוֵּן (הַגָּהוֹת אֲשֵׁרִ\"י וְרַבֵּנוּ יְרוּחָם ני\"ט)\u0006 וְעַיֵּן לְקַמָּן סִימָן ש\"א. \u0010c11\u0011\nהַשַּׂק \u0010y13\u0011 וְהַקֻּפָּה מִצְטָרְפִין לְכִלְאַיִם. \u0005הַגָּה: וְכֵן \u0010y14\u0011 אָב וּבְנוֹ מִצְטָרְפִים לְכִלְאַיִם, כֵּיצַד, הָיָה חֲתִיכַת צֶמֶר בְּאֶחָד מֵהֶם וַחֲתִיכַת פִּשְׁתָּן בַּשֵּׁנִי, \u0010y15\u0011 וּתְפָרָן בְּיַחַד, הָוֵי כִּלְאַיִם (טוּר)\u0006.",["\u0003ועשה מהן לבדים כו'. \u0004ורוב הפוסקים ס\"ל דלבדים אינן אסורין אלא מדרבנן ובקשין מותר לגמרי כדלקמן סי' ש\"א וע\"ש סעיף ב' בהג\"ה:","\u0003אפילו תפרן בחוטי משי וקנבוס כו'. \u0004ונראה דאף ע\"ג דהרמב\"ם למד דין זה מסברתו דלקמן סעיף ה' וכמו שהביא הב\"י סימן זה לשונו שבפירוש המשנה מ\"מ אנן קי\"ל דזה לכ\"ע אסור כיון שהפשתן והצמר הם זה אצל זה רק שמחברן ע\"י משי וקנבוס וכן מוכח להדיא בדרישה סעיף י' מה שכתב בשם מ\"ו ע\"ש וכן משמע לקמן סעיף ה' גבי ואע\"פ שאפשר שיכנס חוט הקנבוס כו' ודו\"ק:","\u0003אלא בשני כו'. \u0004כגון שמעביר המחט פעם א' ואינו מעביר כל החוט ומעביר המחט פעם שנית ונמצא שני ראשי החוטין ביחד וקושר שני ראשי החוטין. הרא\"ש וטור:","\u0003מותר לפרוף כו'. \u0004היינו שכורך חוט סביב שני ראשי הקרעים וכורכם יחד דלא הוי חבור החוט של פשתן והחלוק של צמר כיון דיכול להוציא ב' ראשי הקרעים בלא התרת הקשר. הרא\"ש והטור:","\u0003דהרי יכול ליקח הצמר משם בלא התרת התפירה. \u0004רק ע\"י קרע קטן כדאיתא בתוס':","\u0003אסור בכה\"ג. \u0004כלומר אפי' כשאינו תוחב התפירה בעצמם וכ\"כ בס' מע\"מ דף רצ\"ג ע\"א ודלא כהעט\"ז:","\u0003ואפי' הוא קשר של קיימא. \u0004לא הוי חבור לענין כלאים ומה שלמד הבית יוסף כן מתשובת הרשב\"א אינו מוכרח כלל ע\"ש ודו\"ק:","\u0003ונ\"ל כו'. \u0004כל ההג\"ה נמשכת לסברת היש אוסרים וק\"ל ולפי זה מה שנהגו העולם להקל בדברים אלו שכתב הרב אפשר משוס שסוברים כסברא הראשונה:","\u0003ב' בתי שוקיים כו'. \u0004וה\"ה אנפלאות שקורין זאקין:","\u0003ול\"ד לשני חלוקות כו'. \u0004ובעט\"ז השיג על דברי הרב אלו דהא בב' חלוקות ודאי מיירי כשיש להם בתי זרועות והיאך אפשר לפשוט התחתונים בלא עליונים כו' (והסכים עמו בזה בס' מע\"מ) ע\"ש שהאריך ואין דבריו נראין ושני חלוקות שאני דמ\"מ יכול להכניס זרועותיו לפנים ולפשוט אח\"כ החלוק ואע\"ג דהשתא הוציא ידיו גם מחלוק העליון מ\"מ החלוק העליון נשאר עדיין על גוף עצמו ודמי לדלעיל בצמר בכר וכסת דאע\"ג דמוכרח לעשות קרע קטן שרי ודו\"ק ודברי הירושלמי והא\"ז נראים עיקר כדעת הרב וכמ\"ש בד\"מ ומביאו בס' מע\"מ שם וכן הוא בהגהת סמ\"ג ובמהרש\"ל ושאר אחרוני' וכ\"כ מהרש\"ל פ\"ק דביצה סי' מ\"ז:","\u0003ואע\"פ שאפשר כו'. \u0004דכלאים אלו הן מדרבנן והולכים בספקו להקל. הרשב\"א. ובת\"ה כתוב בשם ר' שמשון הטעם שהחוטין שבהם העורות תפורים לא חשיבי ובטלים לגבי העור והואיל ואינו רק לחבר העורות אין בהם משום כלאים:","\u0003ואסור לו לכרכם על ידו. \u0004דידו מתחממת בהם והוי דומיא דלבישה:","\u0003ויש מתירין כו'. \u0004והאוסרים ס\"ל דלא דמי לדלקמן סי' ש\"א סעיף ו' דהכא הוי פסיק רישיה דמחמת אחיזתן א\"א שלא תתחמם ידו כ\"כ הב\"ח וכן הוא בשלטי גבורים פ' במה בהמה ומביאו בספר מע\"מ דף קצ\"ד ע\"א והסכים עמו ודלא כהפרישה לקמן סי' ש\"א סעיף א' שהניחו בצ\"ע:","\u0003מצטרפין כו'. \u0004כיצד חתיכת בגד פשתן מחוברת לשק וחתיכת בגד צמר מחוברת לקופה וחברן (כלומר השתי חתיכות) יחד בשתי תכיפות מצטרפין אף ע\"ג שמחוברי' בב' כלים ואסור להתכסות בשק או בקופה ולא אמרינן האי לחודיה קאי והאי לחודיה קאי. טור ושאר מפרשים. וכתב הברטנורה ושאר מפרשים דה\"ה אם מחוברים לשאר כלים דינם כשק וקופה:","\u0003אב ובנו. \u0004וה\"ה שאר ב' בני אדם:","\u0003ותפרן ביחד. \u0004וחגר חגורות עליו ועל בנו דאל\"כ שרי דכיון שהם בעלי חיים נפרדים זה מזה. הטור והרא\"ש. ומדברי הרב נראה שאפי' לא חגר חגורות אסור והיינו כמ\"ש הב\"י בשם הריטב\"א ע\"ש:"],["\u0003או שטרפן כו'. \u0004כל סעיף זה הוא לשון הרמב\"ם אלא שתיבת או הוא הגהת המחבר הש\"ע וברמב\"ם כתוב בל' ועשה מהם לבדים ה\"ז כלאים טרפן וטוה כו' ובכ\"מ האריך בביאורו ואעתיק לשון הגמרא תחילה ואח\"כ בביאור דברי רמב\"ם בנדה (דף ס\"א) אמרינן א\"ר אחא בריה דרב ייבא משמיה דמר זוטרא האי מאן דרמי חוטא דכיתנא בגלימא דעמרא ונתקיה ולא ידע אי נתיק אי לא נתיק ש\"ד מ\"ט מדאורייתא שעטנז כתיב עד שיהא שוע (פי' חלוקים יחד במסרק) טווי ונוז פירש\"י טווי יחד ונוז לשון אריגה דרבנן הוא דגזרו ביה באריגה בלא שוע וטווי וכיון דלא ידע אי נתקיה שרי מתקיף לה רב אשי אימא או שוע או טווי או נוז והלכתא כמר זוטרא מדאפקינהו רחמנא בחדא לישנא והקשו התוס' על רש\"י שפי' טווי ביחד דא\"כ כלאים בציצית היכי משכחת לה דאצטריך קרא למשרי והלא חוטי תכלת חלוקים במסרק וטווי לבדם ועוד הקשו דאי נוז היינו ארוג מאי פריך ואימא או שוע או טווי או נוז היאך יהיה שוע או טווי כלאים בלא נוז שהאריגה היא החבור נראה פירוש דבריהם דאף שנעשה איסור ע\"י שוע או טווי מ\"מ אין שם חבור בגד עליו כל זמן שלא נארג יחדיו וכיון שבגד אסרה תורה למה הוצרך ארוג וכ\"ה ברא\"ש פרק האשה וז\"ל דשוע בלא נוז לאו בגד הוא כיון דאינו ארוג עכ\"ל וע\"כ פר\"ת דמדאורייתא שוע כל אחד לבדו וכן נמי טווי וכן נמי נוז לבדו דהיינו שזורים אח\"כ יחדיו לחברם מ\"ה צריך קרא להתיר כלאים בציצית שהחוטים שזורים כ\"א לבדם והוקשה לב\"י דברי הרמב\"ם כיון דקי\"ל הלכתא בגמרא שוע וטווי ונוז ביחד דוקא למה פסק דבלבדים שאין שם אלא שוע דהוי כלאים וכ' שמשום זה הגיה הטור כאן ברמב\"ם ברישא אין זה כלאים וא\"א לומר כן דהא שנינו הלבדים אסורים מפני שהם שועים וא\"ל דאין זה כלאים דאורייתא קאמר שאין זה במשמע אלא ודאי שעיקר הנוסחא הרי זה כלאים גם ברישא וכן היתה גם נוסחת הראב\"ד ברמב\"ם ובאמת קשה מאד דממ\"ש רמב\"ם הלבדים הם כלאים דאורייתא נראה שהוא סובר שמה שאמרו עד שיהא שוע טווי ונוז או או קתני ובחד מינייהו סגי וממ\"ש בסיפא טרפן וטוה אותם כאחד וארג בגד כו' משמע דבעינן שיעשה שלשתן יחד ונ\"ל שהרמב\"ם סובר דנהי דבשוע בלבד הוי כלאים בטווי לא הוה כלאים אא\"כ הוא ארוג כו' כיון דשוע הוא בראש התיבה כו' ע\"כ דברי הכ\"מ וב\"י תמוהין הם דזה לא כמאן דלא מצינו בגמרא אלא או כולן יחד או כל אחד לבדו אבל לא באחד שיהיה לבדו ושנים הנותרים יהיו דוקא ביחד ומה שהביא ראיה ממתניתין פרק בתרא דכלאים שאמרה אין שעטנז אלא בטויה ואריגה שנאמר שעטנז שוע טוי נוז פתח בטוי ונוז וסיים גם בשוע אלא ודאי דשוע הוא חלוק משנים אחרים איני מכיר בראיה זאת ואין כאן קושיא דהתנא אקרא קאי דכתיב שעטנז ומלת שע היא נכתבת בפירוש וכדי שלא תטעה לומר דכל התיבה נגררת אחר תיבת שע ואין דרשה לאותיות האחרים ולחלק הטי\"ת מן נז להורות על טויה ואריגה וקמ\"ל דדרשינן כל התיבה דהיינו גם טוי מן הטי\"ת ונז הוא תיבה בפני עצמה ונראה דדברי הרמב\"ם הם נכונים בפי' מרווח ולא כהני מילי דחיקי והם ע\"פ דבריו בפי' המשנה כפי הנוסחא שהביא ב\"י שכ' וכל שאינן נחברים כך הוא כלאים מד\"ס כן אמרו מקצת גאונים וזה אצלי מאמר בלתי אמיתי אלא שכל אחד מהם הוא כלאים של תורה ומה שנזכר בגמרא דנדה אינו לשון התלמוד אבל הוא לשון איזה מפרש עכ\"ל הרי שתופס הרמב\"ם כרב אשי דאו שוע כו' קאמר ומה שנאמר בגמרא והלכתא כמר זוטרא אינו מלשון התלמוד דהוקשה לרמב\"ם קושיית התוספות דלעיל דא\"כ למאי דקי\"ל כמר זוטרא דבעינן כולהו יחד למה לי קרא בהיתר כלאים בציצית ובהדיא כ' הרמב\"ם הוכחה זאת שם בפירוש בהלכות כלאים אלא ודאי דקי\"ל להלכה דגם כאן בחד סגי ומר זוטרא ה\"נ דלא דריש קרא להתיר כלאים בציצית אלא דלדידן קי\"ל ג\"כ כאן כרב אשי דבחד סגי וכן מכוון בדברי הרמב\"ם ונעתיק סידור דבריו תחלה כ' כיון שנתחבר הצמר עם הפשתן צד חבור בעולם ה\"ז כלאים מן התורה כיצד צמר ופשתים שטרפן זה עם זה ושע אותן ועשה מהן לבדים ה\"ז כלאים טרפן וטוה אותן כאחד וארג בגד מטווי זה ה\"ז כלאים תפר בגד צמר בשל פשתן אפילו תפרן במשי או שתפר בגד צמר בחוטי פשתן או בגד פשתים בחוטי צמר או קשר חוטי צמר בחוטי פשתן או גדלן אפילו נתן צמר ופשתים בשק או בקופה וכרכן ה\"ז כלאים ואפילו קשר הגדיל של צמר בגדיל של פשתים אע\"פ שהרצועה באמצע וכן אם כפל בגדי צמר ופשתן וקשרן ה\"ז כלאים שנאמר צמר ופשתים יחדיו מ\"מ כיון שנתאחד נאסר עכ\"ל הרי לפניך ד' בבות בג' מהם לא הביא פסוק ובד' הביא פסוק יחדיו ואי קאי אכולם היה לו לעשות מכולם חד בבא ונראה דנקט תחילה ג' בבות מה שנלמד מתיבת שעטנז ע\"כ זכר תחילת שע ביחד ועשה לבדים ואח\"כ טווי והוסיף עליו מלת ואריג דטווי בלא אריג אין בו איסור אף על פי שנתחברו ע\"י עירוב מ\"מ בעינן שם בגד דוקא ואח\"כ כתב בבא ג' לפרש תיבת נז דענינו כל שהוא נעשה מחובר ולא מפרש כרש\"י דנוז היינו אריג אלא כר\"ת דהיינו שנעשו חיבור ע\"י שיזור וה\"נ מפרש הרמב\"ם לכל עניני החבור שישנם וכמו שהזכיר בבא ג' וא\"ל למה לי שע וטוייה כיון שתיבת נז כולל הכל יש לומר דהייתי מוקים תיבת נז על מסתבר דהיינו שנתחבר ע\"י שע או טוייה ותו לא ע\"כ כ' אלו ב' תיבות בהדיא דמוכרח לנו דנפרש נוז על שאר עניני חבור נמצא הכל נכון ולא כמ\"ש בית יוסף דאריג דנקט רמב\"ם הוא לפרש תיבת נז אלא הוא שייך לתיבת טווי וע\"כ עשה מזה בבא מיוחדת בדין הג' שגדל יחד חוטי פשתן וחוטי צמר ע\"י אריגה וכל זה הוא ברור לפי ע\"ד כביעתא בכותחא דהרמב\"ם אוסר בכל אחד מהני תלת בפני עצמו כן נלע\"ד לדעת הרמב\"ם אבל פוסקים אחרים דהיינו הראב\"ד והטור ס\"ל כמר זוטרא דעד שיהיו כולהו בעינן:","\u0003קבץ ב' ראשי החוט. \u0004פירוש וקשרם ביחד:","\u0003או שתכף שתי תכיפות כו'. \u0004זו דעת הרמב\"ם אף על גב דבהלכות שבת פרק י' כתב התופר שתי תפירות חייב והוא שיקשור ראשי החוטין מכאן ומכאן כדי שתעמוד התפירה ולא תשמט צריכין לומר דשאני חבור דכלאים דחשיב חבור אפילו בכל דהו מדכתיב יחדיו שלא יהיה להם צד חבור אפי' לפי שעה מה שאין כן בתכיפה אחת שאין שם חבור אפילו לפי שעה אע\"ג דבסוף כלאים אמרינן במשנה דבתכיפה אחת אינה כלאים והשומטו בשבת פטור ובשתי תכיפות יש כלאים ובשבת חייב משמע דשבת וכלאים שוין היינו לענין החילוק שיש בין תכיפה אחת לשנים משא\"כ לענין קשירה דבשבת צריך שיהיה דבר קיים דמלאכת מחשבת אסרה תורה:","\u0003וי\"א. \u0004הוא דעת הטור ומבואר בו כיצד הן שתי תכיפות כגון שמעביר המחט כו' עד על שפת הבגד אינו חיבור עכ\"ל. ונראה הטעם דכל שהחוט מתקשר בחוץ על שפת הבגד יתקלקל מהר כשיגיע באיזה דבר כי החוט הוא דבר דק ואין מגין עליו ובזה ניחא לי מה שקשה למה הוצרכה התורה להתיר כלאים בציצית והלא חיבור שלהם בבגד על ידי קשירה מבחוץ ולדידי ניחא דדוקא בכלאים שמחבר שני דברים להדדי ובמהרה ינתק החוט כל שהוא מבחוץ מה שאין כן בציצית) שאין שם רק דבוק החוטין להבגד ולא במהרה ינתק כנ\"ל ומדלא הביא רמ\"א הך חילוק היאך יהיו קישורי החוט משמע שדעתו לפסוק להחמיר אפילו בקשירה מבחוץ וכן נכון מאחר שהרמב\"ם אוסר כאן אפילו בלא קשירה כלל וכל שכן אם עושה קשר בראש החוט מכאן ומכאן כמו שכתב הרמב\"ם אפילו בדין שבת כמו שזכרנו:","\u0003וקושר. \u0004דהיינו שחיבר שני ראשי הקרעים וכרך החוט סביבם וקושרם יחד דלא הוה חיבור החוט של פשתן והחלק של צמר כיון שיכול להוציא שני ראשי הקרעים בלא התרת הקשר כן הוא בטור בשם הרא\"ש אלא דקשה דמשמע כאן דלהרא\"ש יש איסור בחבור על ידי קשר אם היה בענין שאינו יכול להוציא ראשי הקרעים בלא התרת הקשר ולעיל כתב הטור בשם הרא\"ש דאפילו בשתי תכיפות לא הוה חיבור בלא קשר וכן להיפך וכמו שכתב רמ\"א בשם י\"א בסעיף ב' וצריך לומר כמו שכתבתי בסמוך דלעיל לא מחבר הצמר והפשתים עצמן רק ע\"י חוט התפירה על כן בעינן תרתי ב' תפירות וגם קשרים מה שאין כן כאן דאסור היינו שאם היה קושר הבגד צמר עם הבגד פשתן עצמו ומשום הכי לא קשיא מציצית כמו שזכרתי בסמוך ועל כל פנים מודה הרא\"ש דאם עושה נקבים בבגד עצמו ומחברם בחוט ע\"י קשר קיום דאסור וזה מוכח בכמה מקומות מדבריו והרבה נכשלין בזה שקושרין הטלומ\"ק של בגד במשיחה של פשתן וקושרין בצד אחד קשר של קיום:","\u0003הוי כשק של פשתן. \u0004הא דפשוט היתר טפי בשק של פשתן משום דלא מקרי בגד כלל מה שאין כן בכסת והרמב\"ם כתב אפילו נתן צמר ופשתים בשק או קופה וכרכן הרי זה כלאים וכתב ב\"י שזה חולק על הטור:","\u0003ותפר פיו כו'. \u0004דאין חוט התפירה מחבר לבגד בתפירה זאת רק שהוא מדבק ב' בגדים החיצונות יחד:","\u0003אבל בבלאי בגדים. \u0004פירוש שנתחב המחט גם בהם כן הוא במרדכי שם ולכאורה י\"ל דלזה נתכוין רמ\"א במה שכ' בכה\"ג ומ\"מ משמע שם שאין למלאות כלל המכסה של פשתן בבלאי בגדים של צמר כיון שמצוי בהם כריכות נימא ותחוב בתוך התפירות וכן עיקר וכן משמע בתוספות פ\"ק דביצה (דף ט\"ו) ורמ\"א לא נתכוין להתיר בזה באין תוחב בתוך התפירות אלא אכולה מילתא אמר בכה\"ג דאסור בבלאי בגדים:","\u0003מותר ללבוש כו'. \u0004דבר זה צריך ביאור דלמה יהיה מותר אפילו בקשר של קיימא ותו דהא כתב ובלבד שלא יחברם בב' תכיפות וא\"כ מה שייך כאן קשר של קיימא ומשום הכי חלק מו\"ח ז\"ל על הש\"ע ופירש בו פירוש אחר בדברי הטור שעיקר החילוק בין אם רוצה לפשטן שניהם כאחת או זה בלא זה ולא נייח לי אלא דדבר זה הוא מן התוספתא הביאה הרא\"ש וז\"ל תניא בתוספתא לובש אדם ב' חלוקים אע\"פ שפונדתו חגור עליו מבחוץ ובלבד שלא יטרוף את המשיחה ויקשור בה בין כתפיו כלומר שיקשור ב' החלוקות ביחד בענין שאינו יכול להפרידן בלא התרת הקשר עכ\"ל. משמע מדבריו שמבחוץ יכול להדק החגורה כפי מה שירצה רק שלא יחבר את החלוק של צמר עם של פשתים עצמן בענין שאין יכול לפשוט זה מזה בלא קשר והיינו קשר של קיימא והטור כתב מותר ללבוש חלוק של צמר על גבי חלוק פשתן ולקשרן יחד אע\"פ שאינו יכול לפשטן בלא התרת הקשר ובלבד שלא יהא הקשר של קיימא כו' עכ\"ל וע\"כ א\"א לומר דהטור מיירי מחגורה שהיא לא תהיה מקושרת בקשר של קיום דא\"כ היאך היה מפרש דברי אביו שאוסר כל שאינו יכול להפרידן בלא התרת קשר דע\"כ בקשר של קיום מיירי דאל\"כ אין איסור כלל והרי לפניך דאביו הרא\"ש מיירי מחיבור החלוק עצמן ביחד ואפילו הכי בעינן קשר של קיימא משמע דבחגורה אפילו קשר של קיום אינו אוסר אלא פשוט לע\"ד דהטור ראה שאביו מחלק ומיקל אפילו בחיבור החלוקות באם הם אינם בקשר קיום ואוסר דוקא בקשר קיום ולא הוצרך להזכירו על כן לא זכר הטור כלל מן החגורה שזה מותר בכל גווני רק מהחיבור שבין החלוקות עצמם שלא יהיו בקשר קיום אבל בעל השלחן ערוך כתב דבריו ברישא על החגורה מדנקט בסיפא ובלבד שלא יחברם זה לזה כו' מכלל דברישא לא מיירי מחיבור זה עם זה אלא מחגורה שהיא מותרת בכל גווני והא דסיים ויש אוסרים בקשר של קיימא היינו אותן הדעות שהביא הבית יוסף בשם תשובת הרשב\"א שאסרו אפילו בחגורה דהיינו שכתב בשם רבינו יונה כשהיה לבוש בגד צמר על החלוק לא היה מהדק איזורו כו' כן נ\"ל כוונת הש\"ע אבל כבר מבואר מתשובת הרשב\"א שכבר נהגו כל ישראל בהיתר והיינו בחגורה אבל לא זכר כלום בש\"ע מחבור החלוקות עצמן וסמך על עיקר הדין שאם הם קשורים בקשר קיום פשיטא דאסור:","\u0003ולא דמי לשני חלוקות כו'. \u0004לכאורה הדברים האלה תמוהים דנהפוך הוא שהרי בשני חלוקות אי אפשר לפשוט הבית יד של התחתון כולו עד שיפשוט העליון ובבתי שוקיים יש באפשרות כשהן רחבים שיוכל להכניס ידו למטה ולהגביה את של פשתן ויכול להוריד למטה את של צמר נמצא שיהיו מופרדים זה מזה בלי שום התרת תפירה ושניהם עודם עליו וכבר תמה בלבוש על רמ\"א מכח הך סברא דשני חלוקות אי אפשר לפשוט התחתון בלא עליון וכתב שאין צריך ליזהר בדבר וסמך על מה שכתב בית יוסף דשאר פוסקים ס\"ל כרבי יוסי דמתיר בכל ענין אבל לפי האמת דברי רמ\"א כנים המה דזה ודאי כל שאינו יכול לפשוט התחתון בלא עליון יש איסור כמ\"ש בירושלמי הביאו ב\"י וז\"ל מודה רבי חליא דילבש דרדסין דעמיר ע\"ג דרדסין דכיתן דהוא אסור דלא שלח עלייהו לא שלח ארעיי' פירוש כל כמה שאינו מפשיט העליונים לא יוכל לפשוט התחתונים ובב\"י פירש דהכי קאמר שהם צרים ודחוקים שא\"א לחלוץ העליון בלא התחתון ואז חשובים כתכופים ופירוש תמוה הוא דא\"כ היה לו לירושלמי לומר דהוא אסור אם לא שלח עילייא ולמה החליט האיסור תחלה בכל גווני ואח\"כ נותן טעם לפי שהם צרים אלא ודאי הפי' כמו שהבינו רמ\"א דלא יוכל להפשיט התחתון בלא העליון והעיקר בזה דכל שצריך הפשטת העליון תחלה אפילו מקצת ממנו יש איסור כיון שא\"א להפשיט התחתון אלא א\"כ יתחיל להפשיט העליון וסתם בתי שוקיים אינם רחבים אלא כפי מדת הרגל וקצת יותר והנך בתי שוקיים שזכר רמ\"א היינו שיש להם למטה צורת מלבוש על הרגל כמו אותן של צמר נמצא שא\"א לזוז ממקומם את התחתונים כל זמן שהעליונים על מקומם מה שאין כן בשני חלוקות זה על זה אפשר להכניס ידו לתוך בית יד של החלוק התחתון ולהוליכו למעלה עד סמוך לגוף ואח\"כ יוכל להוציא גוף החלוק מאחוריו על ראשו ולא יעצור להפשיט רק אותו חלק של גופו במה ששם יש חלק מהחלוק במה שהביא שם הבית יד ויכול לגלות קצת החלוק העליון לפניו באופן שלא יהיה אותו חלק של התחתון מכוסה אבל באמת אם הבתי שוקיים עשויים באופן שאין למטה ע\"ג הרגל כלום ויוכל להושיט שם ידו ולהוליך התחתון עד למעלה באופן שלא יהיו מכוסים מן העליונים הכי נמי דמותר כן נ\"ל ליישב דברי רמ\"א ועפ\"ז נראה ששפיר כ' ליזהר בב' בתי שוקיים באופן שזכרתי:","\u0003אבל אם קשרן כו'. \u0004סתם קשר הוא קשר של קיימא דהיינו שני קשרים זה על זה וב\"י כתב דמשמע לו קשר אחד ואיני יודע מנין לו דהא סתם קשר הוא בכל סימן זה קשר של קיימא וכ\"כ מו\"ח ז\"ל ונראה דהוכחתו דלפי פי' הטור והרמב\"ם דכבר הוא נקשר קודם הכריכה קשה פשיטא שאסור אח\"כ בכריכה על ידיו ואין לומר דקא משמע לן דבר שאין מתכוין אסור האי מילתא היה יכול להשמיענו בעלמא אלא ע\"כ דחד קשר סגי כאן כיון שאח\"כ כורך אותו על ידו:","\u0003השק והקופה כו'. \u0004כיצד חתיכת בגד פשתים מחוברת לשק וחתיכת בגד צמר מחוברת לקופה וחברן יחד בב' תפירות מצטרפין אע\"פ שמחוברין בב' כלים ואסור להתכסות בשק או בקופה ולא אמרינן האי לחודיה קאי והאי לחודיה קאי כ\"ה בטור:"]],["מֻתָּר מִן הַתּוֹרָה לֵישֵׁב עַל מַצָּעוֹת שֶׁל כִּלְאַיִם, שֶׁנֶּאֱמַר: לֹא יַעֲלֶה עָלֶיךָ \u0005(וַיִּקְרָא יט, יט)\u0006 אֲבָל אַתָּה מַצִּיעוֹ תַּחְתֶּיךָ. \u0005הַגָּה: \u0010y0\u0011 וְכֵן מֻתָּר לְהַעֲלוֹתָם עָלָיו שֶׁלֹּא בְּדֶרֶךְ חִמּוּם, כְּגוֹן \u0010c0\u0011 לִפְרֹס עָלָיו אֹהֶל שֶׁל כִּלְאַיִם (טוּר)\u0006. וְכֵן לִפְרֹס בֶּגֶד כִּלְאַיִם עַל גִּיגִית שֶׁרוֹחֵץ בָּהּ, כְּדֵי לְהַעֲמִיד הַחֹם \u0005(מָרְדְּכַי פ\"ק דְּבֵיצָה וּבְהַגָּהוֹת אֲשֵׁרִי שָׁם)\u0006, דְּאֵינוֹ אָסוּר אֶלָּא דֶּרֶךְ לְבִישָׁה אוֹ לְהַעֲלוֹתָם עָלָיו דֶּרֶךְ חִמּוּם. \u0010c1\u0011 וּמִדִּבְרֵי סוֹפְרִים, אֲפִלּוּ עֶשֶׂר מַצָּעוֹת זוֹ עַל גַּבֵּי זוֹ וְהַתַּחְתּוֹן שֶׁבָּהֶם כִּלְאַיִם, אָסוּר לֵישֵׁב עַל הָעֶלְיוֹן, שֶׁמָּא תִּכָּרֵךְ נִימָא עַל בְּשָׂרוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּרַכִּין, כְּגוֹן יְרִיעוֹת וּשְׂמָלוֹת אֲבָל כָּרִים וּכְסָתוֹת שֶׁהֵם קָשִׁים וְלֵיכָּא לְמֵיחַשׁ שֶׁמָּא תִּכָּרֵךְ נִימָא עָלָיו, מֻתָּר לִישַׁן עֲלֵיהֶם וּבִלְבַד שֶׁלֹּא יְהֵא בְּשָׂרוֹ נוֹגֵעַ בָּהֶם. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהֵם רֵיקָנִים וּנְתוּנִים עַל גַּבֵּי אִצְטַבָּא שֶׁל עֵץ אוֹ שֶׁל אֶבֶן, אֲבָל אִם הֵם מְלֵאִים, אוֹ אֲפִלּוּ רֵיקָנִים אִם הֵם \u0010c2\u0011 נְתוּנִים עַל גַּבֵּי מִטָּה אוֹ עַל גַּבֵּי תֶּבֶן, אָסוּר, לְפִי שֶׁנִּכְפָּף תַּחְתָּיו וְנִכְרָךְ עַל בְּשָׂרוֹ. \u0005הַגָּה: \u0010y1\u0011 וְיֵשׁ אוֹמְרִים דְּכָל זֶה מַיְרֵי בְּכִלְאַיִם דְּאוֹרַיְתָא, אֲבָל בְּכִלְאַיִם דְּרַבָּנָן וְהֵם קָשִׁים, \u0010c3\u0011 מֻתָּר לֵישֵׁב עֲלֵיהֶם בְּכָל עִנְיָן, דְּהוֹאִיל וּכְשֶׁרַכִּים הֵם אֵינוֹ רַק דְּרַבָּנָן, בְּקָשִׁים לֹא גָּזְרוּ (רַשְׁבָּ\"א סי' תשס\"ב)\u0006. וּמִכָּל מָקוֹם לְכַתְּחִילָה לֹא יַעֲשֶׂה שֶׁל כִּלְאַיִם, \u0005(כָּל בּוֹ)\u0006.\nהָנֵי קאפאנאג\"ש דִּידָן, \u0010y2\u0011 אִם הֵם תְּפוּרִין בְּפִשְׁתָּן, יֵשׁ לִזָּהֵר מִלְּהַעֲלוֹתָם עָלָיו וַאֲפִלּוּ מִלְּהַצִּיעָן תַּחְתָּיו, עַד שֶׁיִּתְפְּרֵם בְּמֶשִׁי אוֹ בְּקַנַּבּוֹס. \u0005הַגָּה: \u0010y3\u0011 כָּל בְּגָדִים הַקָּשִׁים מֻתָּרִים בְּהַצָּעָה מִתַּחְתָּיו, וְאָסוּר לְלָבְשָׁן. וְהַלְּבַדִּים הַקָּשִׁים, מֻתָּרִים אֲפִלּוּ בִּלְבִישָׁה, הוֹאִיל וַאֲפִלּוּ רַכִּים אֵינָם אֶלָּא מִדְּרַבָּנָן (טוּר)\u0006. \u0010y4\u0011 וְיֵשׁ מַחְמִירִין בִּלְבִישַׁת הַלְּבַדִּים \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006.\nבֶּגֶד גָּדוֹל וְכִלְאַיִם מִצַּד אֶחָד, אָסוּר לְלָבְשׁוֹ אֲפִלּוּ מִצִּדּוֹ הַב', אַף עַל פִּי שֶׁהַצַּד שֶׁבּוֹ הַכִּלְאַיִם נִגְרָר עַל גַּבֵּי הַקַּרְקַע.\nאָסוּר לִלְבֹּשׁ כִּלְאַיִם אֲפִלּוּ דֶּרֶךְ עֲרַאי, כְּגוֹן טַלִּית שֶׁל קָטָן \u0010y5\u0011 \u0010c4\u0011 אַף עַל פִּי שֶׁאֵין הַגָּדוֹל יוֹצֵא בָּהּ עֲרַאי.\nלֹא יִלְבַּשׁ אָדָם כִּלְאַיִם עֲרַאי, וַאֲפִלּוּ עַל גַּבֵּי עֲשָׂרָה בְּגָדִים שֶׁאֵינוֹ מְהַנֵּהוּ כְּלוּם; \u0010y6\u0011 \u0010c5\u0011 וַאֲפִלּוּ לִגְנֹב אֶת הַמֶּכֶס.\nתּוֹפְרֵי כְּסוּת, \u0010c6\u0011 תּוֹפְרִים כְּדַרְכָּם וּבִלְבַד שֶׁלֹּא יִתְכַּוְּנוּ בַּחַמָּה מִפְּנֵי הַחַמָּה וּבַגְּשָׁמִים מִפְּנֵי הַגְּשָׁמִים. וְהַצְּנוּעִין, תּוֹפְרִין בָּאָרֶץ. \u0010y7\u0011 וְכֵן מוֹכְרֵי כְּסוּת מוֹכְרִין כְּדַרְכָּן, וּבִלְבַד שֶׁלֹּא יִתְכַּוְּנוּ בַּחַמָּה מִפְּנֵי הַחַמָּה \u0010c7\u0011 וּבַגְּשָׁמִים מִפְּנֵי הַגְּשָׁמִים. וְהַצְּנוּעִים מַפְשִׁילִין בְּמַקֵּל. \u0005הַגָּה: וְיֵשׁ מַתִּירִין אֲפִלּוּ לִלְבֹּשׁ כִּלְאַיִם, כָּל שֶׁאֵינוֹ מְכַוֵּן לַהֲנָאָתוֹ, כְּגוֹן שֶׁלּוֹבֵשׁ כִּלְאַיִם לְהַעֲבִיר בּוֹ הַמֶּכֶס אוֹ שֶׁלּוֹבְשָׁן כְּדֵי לְהַרְאוֹת מִדָּתָן אִם רוֹצֶה לְמָכְרָן וְכַדּוֹמֶה. (טוּר וְהָרֹא\"שׁ וְהַסְמַ\"ג)\u0006.\nתַּכְרִיכֵי הַמֵּת מֻתָּר לַעֲשׂוֹתָן מִכִּלְאַיִם, \u0010c8\u0011 אֲפִלּוּ לְקָבְרוֹ בָּהֶם. \u0010y8\u0011\nמַרְדַּעַת הַחֲמוֹר, מֻתָּר לַעֲשׂוֹתָהּ מִכִּלְאַיִם וְיוֹשֵׁב עָלֶיהָ, וְהוּא שֶׁלֹּא יִהְיֶה בְּשָׂרוֹ נוֹגֵעַ בָּהּ. וְלֹא יַנִּיחַ מַרְדַּעַת זוֹ עַל כְּתֵפוֹ, אֲפִלּוּ לְהוֹצִיא עָלֶיהָ אֶת הַזֶּבֶל. וְדַוְקָא שֶׁכִּלְאַיִם נִכָּרִים וִידוּעִים בַּבֶּגֶד, אֲבָל בֶּגֶד שֶׁאָבַד בּוֹ כִּלְאַיִם \u0010y9\u0011 וְאֵין מְקוֹמוֹ נִכָּר, אָסוּר לַעֲשׂוֹת מִמֶּנּוּ מַרְדַּעַת לַחֲמוֹר, דְּכֵיוָן שֶׁאֵין מְקוֹמוֹ נִכָּר שֶׁמָּא יִשְׁכַּח וְיִקַּח מִמֶּנּוּ טְלַאי לְתָפְרוֹ עַל גַּבֵּי בִּגְדּוֹ. וְלֹא יִמְכְּרֶנּוּ לְעוֹבֵד כּוֹכָבִים, שֶׁמָּא יַחֲזֹר וְיִמְכְּרֶנּוּ לְיִשְׂרָאֵל.\nמִטְפָּחוֹת שֶׁמְּקַנְּחִים בָּהֶם אֶת הַיָּדַיִם, וּמִטְפָּחוֹת שֶׁמִּסְתַּפְּגִים בָּהֶם הַכֵּלִים וְהַקַּרְקָעוֹת, וְשֶׁמִּסְתַּפְּגִים בָּהֶם אַחַר הָרְחִיצָה, וּמִטְפְּחוֹת סְפָרִים, אֲסוּרִים מִשּׁוּם כִּלְאַיִם, שֶׁהֲרֵי הַיָּדַיִם נוֹגְעוֹת בָּהֶם וְהֵם נִכְרָכִים עַל הַיָּד תָּמִיד וּמִתְחַמְּמִין. \u0005הַגָּה: וְכֵן אָסוּר לַעֲשׂוֹת מִטְפָּחוֹת שֶׁפּוֹרְסִים עַל הַשֻּׁלְחָן שֶׁאוֹכְלִין עָלָיו (הָרֹא\"שׁ כְּלָל ו' וְחִדּוּשֵׁי אֲגֻדָּה סוֹף בֵּיצָה)\u0006 אוֹ שֶׁקּוֹרִין עָלָיו בְּבֵית הַכְּנֶסֶת, מִכִּלְאַיִם \u0005(הַגָּהוֹת אֲשֵׁרִ\"י פ' בְּנֵי הָעִיר)\u0006, מִפְּנֵי שֶׁלִּפְעָמִים מְקַנֵּחַ בָּהֶם יָדָיו וּמִתְחַמֵּם בָּהֶם.\nמִטְפָּחוֹת שֶׁמִּסְתַּפְּרִין בָּהֶם, \u0010c9\u0011 אִם יֵשׁ לוֹ בֵּית רֹאשׁ וְלוֹבְשִׁין אוֹתוֹ כְּדֶרֶךְ לְבִישָׁה, אָסוּר מִשּׁוּם כִּלְאַיִם.\nוִילוֹן, אִם הוּא רַךְ, אָסוּר לַעֲשׂוֹתוֹ מִכִּלְאַיִם, מִפְּנֵי שֶׁהַשַּׁמָּשׁ מִתְחַמֵּם בּוֹ לִפְעָמִים. \u0010y10\u0011 וְאִם הָיָה קָשֶׁה, מֻתָּר. \u0005הַגָּה: אֲבָל פָּרֹכֶת שֶׁלִּפְנֵי אֲרוֹן הַקֹּדֶשׁ, אוֹ הַמַּפּוֹת שֶׁפּוֹרְסִין בָּאָרוֹן \u0010c10\u0011 אוֹ סְבִיב הַתּוֹרָה, מֻתָּר לִהְיוֹת מִכִּלְאַיִם. (שָׁם בְּהַגָּהוֹת אֲשֵׁרִ\"י)\u0006.\nלֹא יִקַּח אָדָם בֵּיצָה חַמָּה בְּבֶגֶד כִּלְאַיִם בְּיָדוֹ, שֶׁכֵּיוָן שֶׁהוּא נִצּוֹל מִלִּכָּווֹת בְּחֹם הַבֵּיצָה חֲשִׁיבָה הֲנָאָה כִּמְנִיעַת \u0010y11\u0011 \u0010c11\u0011 הַקֹּר.\nעַרְדִּילָרִין \u0005(פֵּרוּשׁ כְּלִי שֶׁלּוֹבְשִׁין אוֹתוֹ תַּחַת הַמִּנְעָל, וְיֵשׁ שֶׁעוֹשִׂין אוֹתוֹ שֶׁל צֶמֶר כְּנֶגֶד הֶעָקֵב, אֵין בָּהֶם מִשּׁוּם כִּלְאַיִם, דְּקָשִׁין הֵן)\u0006 \u0005(מִפי' רַשִׁ\"י בְּשֵׁם תְּשׁוּבַת הַגְּאוֹנִים)\u0006 אֵין בָּהֶם מִשּׁוּם כִּלְאַיִם. \u0005הַגָּה: מִנְעָל שֶׁהוּא כִּלְאַיִם וְאֵין לוֹ עָקֵב, מֻתָּר לְלָבְשׁוֹ, שֶׁעוֹר הָרֶגֶל קָשֶׁה וְאֵינוֹ נֶהֱנֶה כִּשְׁאָר עוֹר הַגּוּף (טוּר)\u0006.\nאֵין אָסוּר מִשּׁוּם כִּלְאַיִם אֶלָּא בְּגָדִים שֶׁהֵן דֶּרֶךְ חִמּוּם, כְּגוֹן הַכְּתֹנֶת וְהַמִּצְנֶפֶת וְהַמִּכְנָסַיִם וְהָאַבְנֵט וְהַשִּׂמְלָה וּבְגָדִים שֶׁמְּחַפִּין בָּהֶם הַשּׁוֹקַיִם וְאֶת הַיָּדַיִם וְכַיּוֹצֵא בָּהֶם, אֲבָל צִלְצָלִים קְטַנִּים שֶׁעוֹשִׂים אוֹתָם הָעָם בְּבֵית יָד שֶׁלָּהֶם לִצְרֹר בָּהֶם מָעוֹת אוֹ תַּבְלִין, וּסְמַרְטוּט שֶׁמַּנִּיחִים עָלָיו רְטִיָּה, אוֹ מְלוֹגְמָא אוֹ אִסְפַּלְנִית וְכַיּוֹצֵא בָּהֶם, הֲרֵי אֵלּוּ מֻתָּרִים אַף עַל פִּי שֶׁבְּשָׂרוֹ נוֹגֵעַ בָּהֶם, שֶׁאֵין דֶּרֶךְ חִמּוּם בְּכָךְ. צִיץ שֶׁל עוֹר אוֹ מֶשִׁי וְכַיּוֹצֵא בָּהֶם שֶׁתָּלָה בָּהּ חוּטֵי צֶמֶר וְחוּטֵי פִּשְׁתָּן מְדֻלְדָּלִים עַל פְּנֵי הָאָדָם כְּדֵי לְהַפְרִיחַ הַזְּבוּבִים, אֵין בּוֹ מִשּׁוּם כִּלְאַיִם, שֶׁאֵין דֶּרֶךְ חִמּוּם בְּכָךְ.\nאוֹתוֹת שֶׁעוֹשִׂים הַכּוֹבְסִים וְהַגַּרְדִּים \u0005(פי' מַעֲשֵׂה אוֹרֵג (שְׁמוֹת כח, לב, לט, כב כז)\u0006 ת\"י גִּירְדִי) בַּבְּגָדִים כְּדֵי שֶׁיִּהְיֶה מַכִּיר כָּל א' אֶת שֶׁלּוֹ, אִם הָיְתָה אוֹת שֶׁל צֶמֶר בְּפִשְׁתָּן אוֹ פִּשְׁתָּן בְּצֶמֶר הֲרֵי זֶה אָסוּר, אַף עַל פִּי שֶׁאֵינוֹ חָשׁוּב אֶצְלוֹ.",["\u0003וכן מותר כו'. \u0004בכל אלו שהזכיר הרב מותר אפי' מדרבנן מיהו נראה דהיינו שלא יגע בהן:","\u0003וי\"א כו'. \u0004צ\"ע מאי וי\"א דהא ליכא מאן דפליג בהא כמבואר בב\"י וכל הפוסקים דלכ\"ע כלאים דרבנן מותר לישב עליהם בקשים ואפי' ללבוש שרי בקשים וכן מוכח מדברי הרב גופיה בסעיף ב' דכתב הלבדים הקשים מותרים בלבישה הואיל ואפי' רכים אינם אלא מדרבנן ואפי' היש מחמירין התם בלבדים היינו משום דס\"ל דלבדים אסורים נמי מדאורייתא אבל בכלאים דרבנן שרי לכ\"ע ונראה שגם מ\"ש הכל בו שלכתחלה לא יעשה מכלאים שמא יבא לכסות בהן מיירי בכלאים דאורייתא וצ\"ע:","\u0003אם הם תפורין בפשתן כו'. \u0004ואע\"ג דאינן שוע וטווי ונוז מ\"מ אסורים מדאורייתא להרמב\"ם כמו לבדים ואפי' להרא\"ש וסייעתו מ\"מ מאן לימא לן דהקאפאנאג\"ש קשים הם הלכך אסור להציען תחתיו אפי' עשר מצעות זו ע\"ג זו והן תחתיהן כמבואר מדברי הב\"י:","\u0003כל בגדים הקשים. \u0004אע\"פ שיש בהם כלאים דאורייתא מותרים בהצעה מתחתיו. והיינו דוקא כשאין בשרו נוגע בהן כדלעיל סעיף א' והרב קיצר בדבריו גם לשונו קשה דכתב ואסור ללבשן וה\"ל למימר רבותא דאסור לישב עליהן ממש:","\u0003ויש מחמירין בלבישת הלבדים. \u0004וה\"ה להציען תחתיו כשבשרו נוגע בהן:","\u0003אע\"פ שאין כו'. \u0004אם עכשיו לובשו דרך עראי אסור:","\u0003ואפי' לגנוב כו'. \u0004ויש מתירין בזה כדלקמן סעיף ו' בהג\"ה:","\u0003וכן מוכרי כסות מוכרין כדרכן. \u0004שהרי אינו לובשו דרך מלבוש אבל בסעיף ה' לובשו דרך מלבוש כן מחלק ב\"י לדעת הרמב\"ם וקשה לי על זה מה בכך שלובש ממש מ\"מ דבר שאינו מתכוין הוא אלא נראה לי שדעתו דשאני לעיל סעיף ה' דכיון שלובשו בכוונה דרך מלבוש כדי שיפטר ע\"י כך מהמכס לפי שאין נותנין מכס ממלבושין א\"כ הוי דבר שמתכוין דעיקר כוונתו שיהא דרך מלבוש אבל הכא אין כוונתו אלא שיראו הבריות ויקנו ומתני' מתוקמא שפיר טפי לדעת הרמב\"ם דדוחק לומר דתרי מתני' בחד פירקא פליגי אהדדי ע\"ש מיהו קשה להיש מתירין בסעיף ו' אפי' בלבישת דבר שאין מתכוין אמאי אסור בסעיף ח' במרדעת להוציא עליה זבל הא דבר שאין מתכוין הוא דהא היש מתירי' אסרי נמי במרדעת להוציא זבל כדאיתא בדברי הרא\"ש וטור ורבינו ירוחם להדיא וכן בעט\"ז כתב לקמן סעיף ח' אף ע\"ג דאינו מתכוין אלא שלא ילכלך בזבל אפ\"ה אסור דהא הוי העלאה ממש עכ\"ל וא\"כ קשיא לסברת היש מתירין אפי' בהעלאה ממש כשאינו מתכוין וגם לפי מה שחילקתי לדעת הרמב\"ם קשה כן ונראה דהוצאת זבל לא הוי דבר שאין מתכוין דהא אינו נוטל המרדעת אלא כדי שלא ילכלך בגדיו ומתכוין להציל בגדיו ודמי ללא יקח אדם ביצה חמה בבגד כלאים דלקמן סעיף י\"ב ודלא כהעט\"ז דחשיב ליה דבר שאינו מתכוין ודו\"ק:","\u0003מרדעת החמור מותר כו'. \u0004כיון שהוא קשה וכדלעיל סעיף א':","\u0003ואין מקומו ניכר כו'.\u0004 ע\"ל ר\"ס ש\"ב:","\u0003ואם היה קשה מותר. \u0004משמע דאין איסור במה שהוא נהנה שפורסו מפני החמה והגשמים והרוח וכן כתב הב\"ח וכן כתב מהרש\"ל פ\"ק דביצה סי' מ\"ה דדוקא גבי מלבוש הוא דאסרינן אפי' להגן מפני החמה והגשמים אבל לא בוילון ומ\"ש הבית יוסף בכאן ודלא כהתוס' שכתבו שלא אמרו בוילון שהוא טמא אלא שאין בו איסור משום כלאים ואחריו נמשך המע\"מ דף רצ\"ג סוף ע\"א ותמה על הרא\"ש וטעות נזדקר לפניהם כמובן לכל מעיין בתוס' שם:","\u0003ערדילרין כו'. \u0004ומנעל שאין לו עקב עיין בטור וב\"י ושאר אחרונים ביאורן:"],["\u0003לפרוס עליו אהל כו'. \u0004ואע\"פ שמגין עליו מפני החמה או הצנה מ\"מ מותר כיון שאין זה דרך לבישה משא\"כ בסעיף ו' שאסור במגין מפני החמה כיון שהוא דרך לבישה:","\u0003ומדברי סופרים אסור כו'. \u0004מדכתב רמ\"א וכן בטור התיר עשיית אוהל בהיתר דאורייתא משמע דמדרבנן אסור אפילו באהל דשמא יבוא לפעמים שיתכסה באותו אהל אם הוא קרוב אליו למעלה או לצדדיו אלא דקשה דא\"כ גם גבי פריסה על הגיגית היה לו לומר דדוקא מן התורה מותר שהרי בחדא מחתא מחתינהו רמ\"א וזה מותר אפילו מדרבנן שהרי כתוב במרדכי פרק קמא דביצה דרבינו יואל התירו אלא על כרחך דהיתר דאוהל ועגלה מותר אפילו דרבנן והטור סמך עצמו כיון שכתב בסיפא איסור דרבנן גבי מצע תחתיו ממילא שאר התירים נשארו כדין תורה כיון דלא שייך שם טעם זה האיסור זה נ\"ל ברור וא\"כ אין איסור לישב על אותן העגלות שיש להם אהל תפור בגד פשתן בבגד צמר וקורין אותו פאקלי\"ט אלא שקשה מ\"ש מוילון שעל הפתח שבסעיף י\"א שיש בו משום כלאים שהשמש מתחמם בו לפעמים וה\"נ צידי זה הפאקלי\"ט היושב אצלם הוא מתחמם בהם בזמן הקור והוא איסור גמור ואינו דומה לגיגית ששם אינו נוגע כלל אותו המכסה שמכסה על הגיגית משא\"כ כאן בצידי העגלה בפרט כשרבים יושבים שם ונדחה אחד אצל צידי הפאקלי\"ט ובאמת שמעתי קצת אנשי מעשה נזהרים לישב באותן עגלות אבל רוב העולם נוהגים בו היתר ונראה דהם סומכים שירחיקו עצמן מליגע באותן הצדדין ואף שדבר קשה מליזהר בזה מ\"מ כיון שאין כאן כלאים דאורייתא דהא אינו שוע וטווי ונוז יחדיו ע\"כ די בזהירה מליגע בזה ואף אם לפעמים נוגע בו מיקרי דבר שלא מתכוין ומותר אבל עכ\"פ אזהרה בעינן בזה כל מאי דאפשר. כן נ\"ל:","\u0003נתונים ע\"ג מטה. \u0004פי' של חבלים:","\u0003מותר לישב עליהם בכל ענין. \u0004פי' אע\"ג דנכפף תחתיו והוה כמו לבישה וה\"ה לבישה ממש דשרי בלבדים קשים וכמ\"ש רמ\"א עצמו בסמוך אח\"כ וכ\"כ באשר\"י בהדיא הביאו ב\"י וכ' בפרישה ולפי זה בכובע של נשים של סמו\"ט שתופרין לבד בין סמו\"ט מותר ע\"ש. ולפמ\"ש רמ\"א שלכתחלה לא יעשה אותה כלאים היה ראוי למחות ביד האומנים בזה וכ\"ש לפי המחמירין שכ' רמ\"א בסעיף ב' דהיינו הרמב\"ם דסבירא ליה בשוע לחוד הוה דאורייתא כמ\"ש בסימן ש' אלא דכבר כתב הרשב\"א הביאו ב\"י על כיוצא בזה הנח להם מוטב יהיו שוגגים כו':","\u0003אע\"פ שאין הגדול כו'. \u0004פי' דכל שגדול אינו מתבייש ורגיל הרבה פעמים לצאת בבגד זה של קטן לשוק פשיטא דאסור דהוה בגד גמור אפילו לענין ציצית אלא דאם אינו רגיל לילך בזה לשוק מ\"מ לענין כלאים אסור כל בגד שבעולם ובטור ואשר\"י כתב כאן וגדול יוצא בו עראי לשוק וכ' ב\"י שהוא ט\"ס וצ\"ל אע\"פ שאין גדול כו') ולא דק בזה דהטור ואשר\"י קאי על לבישה דהאידנא דהיינו בגד קטן מאוד ואינו ראוי כלל ללבישה לגדול והוא מתבייש בה לילך לשוק ועכשיו אירע שיוצא בו אסור וראיה לזה שהרי בא\"ח סימן ט\"ז כ' הטור דין טלית של קטן וזכר בו שהוא מתכסה ראשו ורובו ובגדול כ' שאינו מתבייש לילך בו לשוק וכאן לא זכר כלום מזה אלא פשוט שכאן נתכוין אפילו בגד של קטן שאינו מתכסה ראשו ורובו אסור לגדול לילך בו אפילו לשוק במקום שהוא מתבייש מכל מקום בכל גווני אסרה תורה כלאים:","\u0003לגנוב את המכס. \u0004פי' מכס שהוא גזילה אפילו לדינא דמלכותא אבל מה שהוא לפי דינא דמלכותא ודאי אסור לגוזלו כיון ששכרו מן המלך ובטור כתוב כאן להתיר והטעם דהוי ליה דבר שאין מתכוין והא דאסרוה במתניתין היינו לרבי יהודה דס\"ל דבר שאין מתכוון אסור אבל אנן קייימא לן כר\"ש דס\"ל מותר ודומה למוכרי בגדים דבסמוך דמותר ובסי' ש' בסופו הביא הבית יוסף דברי רבינו ירוחם שהקשה על מה שכ' שם הרא\"ש דאסור לכרוך כלאים על ידו כשמנהיג הבהמות הא הוה דבר שאין מתכוין כמו כאן וא\"ל דמשום הכי אסור שם דהוה פסיק רישיה דאי אפשר שלא יתחמם כשיכרוך דק\"ו הכא שלובשו ממש ואפילו הכי מותר להרא\"ש וטור ונראה לי לתרץ דאף על גב דמסקינן בפרק כל שעה (פסחים דף כ\"ו) דלר\"ש מותר באפשר להבדל מן האיסור ואיהו אינו בודל אלא שאין מתכוין ליהנות ממנו ומייתי ראיה מהאי דמוכרי כסות דהכא דאפשר למיעבד כצנועים שמפשילים כו' ולא עביד ואפ\"ה מותר מ\"מ היינו דוקא שהאיסור נעשה כבר אלא שזה אין בודל ממנו לפי שעה אבל ודאי לא יעשה איסור כלאים להעלותו תמיד על סמך שלא יתכוין להלבישו רק בשביל הנהגת הבהמות דכיון שהוא עשוי לכך עד עולם זהו עיקר עליה שלו ודרך לבישה מקרי משום הכי בההיא חבלים דבהמות שעשויין מתחילת עשייתן שיכרוך על ידו בשעת הנהגת הבהמות כדרך כל אדם בזה שיהיו עליו בקשר אמיץ ודאי אסור לעשותו מכלאים משא\"כ בהנך מוכרי בגדים וכיוצא בהם שמתחלה אין עשויים להיות עליו בשעת מכירתן כי זהו אינו אלא לפי שעה ואין עיקר עשייתן לכך מש\"ה מותר שלא במתכוין ודבר זה מוכרח בגמרא שאמרו גבי כלאים דחבלים לעיל ובלבד שלא יכרוך ויקשור דקשה היה לו לתלמוד להקדים הקשירה דהא היא קודמת להכריכה אלא על כרחך דנקטינן להורות שהקשירה צורך הכריכה היא ועל כן הקדים לה הכריכה שהיא התכלית של הקשירה שכל הקושר החבלים של בהמה דעתו שאחר כך תמיד יכרוך אותם על ידיו בעת ההנהגה זהו הנראה לו נכון מאד מצד הסברא ומצד הראיה ורבים נלאו למצוא תירוץ על קושיא זאת והנראה לע\"ד ברור כתבתי לדעת הטור:","\u0003תופרין כדרכן. \u0004פי' אע\"פ שבשעת התפירה יש הבגד על ארכבותם כדרך התופרים והטעם דדבר שאין מתכוין מותר. וזהו סותר מה שפסק בסמוך דלגנוב את המכס אסור בכלאים והא הוה דבר שאין מתכוין כדאמרינן בהדיא בזה ריש פרק הגוזל בתרא דרבי עקיבא בשם ר\"ש שרי להבריח בו המכס מטעם דבר שאין מתכוין ודינים אלו הם דברי הרמב\"ם ופירש ב\"י לדעתו דדוקא שם שלובש דרך לבישה אסור אפילו שלא במתכוין מה שאין כן כאן וכן במוכרי כסות אין לובש ממש עליו אלא נושא על כתיפו ולא הבנתי החילוק הזה דהא מן התורה אסור אפילו במקצת לבישה דהיינו שכורך על ידו ולמה יהיה חמור בזה שיהיה לוקה ד\"ת כשלובש לגנוב המכס כמפורש ברמב\"ם מהך דיש לבישה במקצת הגוף ועוד קשה שהרי הטור כ' להיתר במוכרי כסות אפילו אם לובשים אותו כדי להראות מדתו והבית יוסף כ' שהרמב\"ם חולק על זה ויש לתמוה במאי קמפלגי בזה ומו\"ח ז\"ל כ' דלהרמב\"ם אסור במכס דהוה פסיק רישיה דמודה רבי שמעון דאסור ואשתמיטתיה סוגיא דהגוזל בתרא שזכרנו דאמרינן בהדיא דלרבי שמעון מותר במכס דהכי שמעינן ליה בברייתא ונראה לע\"ד דהרמב\"ם הוכיח מדשנה התנא בפרק א' דינים אלו דהיינו איסור בכלאים להבריח המכס ואח\"כ היתר במוכרי כסות אין לומר דפליגי אהדדי כמו שכ' הר\"ש דלא ניחא לרמב\"ם בכך אלא על כרחך דסביר' ליה לתנא דיש חילוק בדבר דבמכס יש לו הנאה מן הלבישה דבלא הלבישה היה חייב ליתן המכס נמצא דהלבישה היא לו הכרח והוה הנאה זאת כמו הנאת שאר לובש מלבוש כלאים שאסרה תורה ודומה למ\"ש בסעי\"ב בביצה חמה דחשיב הנאה מה שניצול מן חמימות הביצה משא\"כ במוכרי כסות שאין המכירה תלויה בזה אלא שהוא עושה כן להקל במשאו כשהוא עליו או להראות מדתו והיה אפשר לעשות בדרך אחר ע\"כ אין הלבישה הכרחית לו וכיון שאין מתכוין להנאתו מותר. כן נראה לי לדעת הרמב\"ם:","\u0003ובגשמים מפני הגשמים כו'. \u0004ברמב\"ם כתוב ברישא גבי תופרי כסות כמו שהעתיק כאן וגבי מוכרי כסות בסיפא כ' בלשון זה ובלבד שלא יתכוין בחמה שיציל להם הכלאים שעל כתיפן מן החמה ולא יתכוונו בגשמים להתחמם בו עכ\"ל. ויש לתמוה למה לא כ' ברישא כמו בסיפא ותו בסיפא גופיה למה שינה בין חמה לגשמים היה לו לומר גם בסיפא שינצל מן הגשמים ונראה דאורחא דמילתא נקט דודאי לענין דינא גם במציל עצמו מן הגשמים אסור אלא דבסיפא במוכר כסות ונשאו על כתיפו איך שייך לומר שמציל עצמו מן הגשם במה שיניח הבגד על כתיפו ונמצא שכל גופו יהיה מלוכלך בגשם וכתיפו ינצל לחוד בשלמא לענין שינצל מחמה שפיר דמגביה שם הבגד נגד השמש ויהיה לצל על כל גופו אבל באמת אין חילוק בין עושה להנצל מחמה או מגשמים בכל דבר שיתכוין בשבילו ועל כן לא זכר הטור והש\"ע כלום מזה אע\"פ שהשלחן ערוך העתיק כאן לשון הרמב\"ם לא העתיק דבר זה גבי מוכרי כסות דאין בו נפקותא לדינא כתבתי זאת לפי שבפרישה הביא דברי רמב\"ם שכ' להתחמם בהם כ' וצריך עיון היכא דלא עביד מחמת חימום כלל אלא שלא יקלקלו הגשמים בגדיו אי שרי או לאו ודוק מ\"ו וצריך עיון דלקמן גבי ביצה חמה אמרינן שנהנה מכלאים להינצל מפני החמה ומאי שנא גשמים מחמה ונ\"ל לדמות למה שכתוב בסמוך בגדים שמסתפרין בהם דאם אין להם בית קיבול ראש דמותר אף על גב דמגינים שלא יטנפו הבגדים מהשערות והוא הדין בלהציל מגשמים על בגדיו עכ\"ל ותמה אני אם יצאו דברים אלו מפיו דאדרבה מבגדים של מסתפרים מוכח להיפך שהרי כ' שם הרא\"ש הביאו בית יוסף בסמוך וז\"ל כשבני אדם מסתפרים פורסין עליהם סדין כדי שלא יתלכלכו בגדיהם בירושלמי אמרינן במתכוין לשם מלבוש כו' דהיינו שיש להם בית ראש עכ\"ל הרי דכל שיש בו בית קיבול אז אסור אע\"פ שאינו עושה אלא להציל מלכלוך ה\"נ כאן שהוא בגד גמור ומכסה בו מפני לכלוך הגשם ודאי איסור גמור הוא וכמו שמשמע לשון הטור והשלחן ערוך שזכרנו וזה ברור נראה לי ועיין בסעיף י':","\u0003אפילו לקברו. \u0004פי' וכל שכן בבגדים שעושין לו להספד דבבגדים שקוברין אותו הוא עתיד לעמוד בהם והטעם דכתיב במתים חפשי כיון שמת אדם נעשה חפשי ממצות:","\u0003אם יש לו בית ראש כו'. \u0004הטעם דמטפחת זאת שעיקר עשייתה תחילה הוא שלא לשם בגד אלא להגן מפני לכלוך השערות מפני התגלחות ומשום הכי אם אין לה בית ראש אין עליה שם מלבוש והוא עכשיו אינו מתחמם בה ע\"כ מותר מה שאין כן אם יש לה בית קבול דהוה עליה שם מלבוש ונעשה מתחילה לשם מלבוש דהיינו שהוא רך אע\"פ שאין נהנה בה אלא משום אצולי לכלוכית אסור והכלל בזה דכל שהוא מלבוש והוא רך יש בו משום כלאים אף שאין מתחמם כההיא דאפילו על י' בגדים לא יעלו עליו דאטו חימום כתיב באורייתא אלא לא יעלה עליך ודרשינן בירושלמי שלא יהיה הנאה לגוף וכל שאינו מלבוש לגוף כהנהו דמטפחות הידים כו' שזכר לפני זה יש בהם איסור מצד שלפעמים יש בהם חימום לידים וכ\"ש בבגד גמור שנותנין עליו או על כתיפו להצילו מגשמים פשיטא דאסור מן התורה:\n\u0003בדרישה \u0004כתוב בשם רש\"ל וז\"ל אם קשר כו' עד כאן לשון הר\"ח עכ\"ל. ותמהתי למה מביאו דהא לא קיימא לן כן דבהדיא התיר בסעיף ג' שלא כדבריו:","\u0003או סביב התורה. \u0004כן הוא בהגה' אשר\"י פרק בני העיר אבל מפה שפורסין בארון הקודש תחת ספרי תורה או סביב התורה אבל בפירוש המשניות להרמב\"ם פרק בתרא דכלאים מפות ספרים היינו מספר תורה שיאחז בהם ספר תורה בשעת קריאתו יש בו משום כלאים. וכן כתוב במיימוני מטפחת ספר תורה כו' וע\"כ נראה דודאי אסור לעשות המעיל של ספר תורה שקורין מענטלי' או המפה שכורכין סביב הס\"ת עצמה מכלאים דהרי אנו רואין שהשמש אוחזה הרבה פעמים בידו ויש לחוש לחימום בעת הקור ובהגהת אשר\"י לא מיירי מזה אלא שעושין בארון הקודש עצמו איזה מפה תחת הס\"ת או סביב התורה אבל אין אותם המפות נכנסות ויוצאות עם הס\"ת אלא נשארו בארון הקודש לעולם כנלע\"ד:","\u0003ערדילרין כו'. \u0004בטור כתוב וז\"ל ופירשו הגאונים רגילין ללבשן תתת מנעליהן וטולין עליהן עור של תיש מעובד תחת קרקעותיהן וכנגד העקב של רגל יש שעושין אותו של צמר אין בו משום כלאים לפי שהעקב קשה ואינו מתחמם עכ\"ל. והקשה בדרישה דהא איתא בסעיף ג' בגד גדול וכלאים מצד אחד אסור אפילו צדו השני כו' ולמה מותר כאן ליהנות שאר הרגל מזה שיש כלאים בעקב והאריך בתירוצים ולע\"ד נראה דלא קשה מידי דכל שהוא מלבוש דוקא אמרו כן כמ\"ש לעיל סעיף י' דכל מלבוש שהוא רך אסור אע\"פ שאינו מתחמם וכל שאינו מלבוש אין אסור אלא דוקא במתחמם מש\"ה כאן אין שם מלבוש על זה כיון דלמטה מוטלה בעור רק שכנגד העקב יש צמר ואי היה מחמם היה אסור מכח החימום על כן התירו בזה שאין שם חימום ואינו בגד ובזה מתורץ נמי לשון הרמב\"ם שמביא הטור והעתיקו רמ\"א כאן מנעל שהוא כלאים ואין לו עקב מותר ללבשו שעור הרגל קשה ואינו נהנה כשאר עור הגוף עכ\"ל והקשו רבים למה כתב ואין לו עקב ולפמ\"ש אתי שפיר דלפי הנראה הוא ממש כהמנעלים שלנו שקורין פאנטאפלי\"ן דהיינו שסביב העקב של הרגל אין שם עור מנעל כלל ע\"כ התירו לתת כלאים תחת העור המנעל ממעל לרגל וכן תחתיו במקום שהרגל עומד עליו והטעם הוא כדלעיל שכאן אין שם בגד על הכלאים שיש במנעל שהרי סביב העקב אין שם כלום דאלו היה שם ג\"כ בגד היה אסור מצד שהוא לבוש אבל עכשיו אין איסור אלא מכח חימום וברגל כולו אין שום חימום וכן נהגו לצאת בפאנטאפלי\"ן שיש שם בגד מבפנים בכל צדדיו אף שתפרו עובד כוכבים בחוט פשתן והוא מטעם דפרישית אבל אם עשה כן במנעל דהיינו שגם כנגד סביב העקב יש עור המנעל וגם שם תפור בבגד אסור מטעם בגד כלאים דאנו חושבין הבגד שתפור בפנים כאלו הוא בגד בפני עצמו בלא עור המנעל כנ\"ל ובדברי מו\"ח ז\"ל נשמט כאן טעות בקולמסו שכתב וקא משמע לן רבותא דאע\"פ שאין לו עקב אסור כו' דאדרבה מותר הוא ואין כאן רבותא וכך הם דברי הב\"י שכתב דכל שיש לו עקב דמחזי כמלבוש כו' ולא כתב דהוי מלבוש ממש כיון שהוא מכוסה בעור וכמו שכתבתי:"]],["בֶּגֶד צֶמֶר שֶׁאָבַד בּוֹ חוּט שֶׁל פִּשְׁתָּן אוֹ בֶּגֶד פִּשְׁתָּן שֶׁאָבַד בּוֹ חוּט שֶׁל צֶמֶר, צוֹבְעוֹ, שֶׁאֵין הַצֶּמֶר וְהַפִּשְׁתָּן עוֹלִים בְּצֶבַע אֶחָד וּמִיָּד הוּא נִכָּר לוֹ וְשׁוֹמְטוֹ, וְאִם לֹא \u0010y0\u0011 נִכָּר, הֲרֵי זֶה מֻתָּר, שֶׁמָּא נִשְׁמַט וְהָלַךְ לוֹ, \u0010c0\u0011 שֶׁהֲרֵי בָּדַק וְלֹא מְצָאוֹ. \u0010c1\u0011 \u0005בַּמֶּה דְּבָרִים אֲמוּרִים, בְּכִלְאַיִם דְּרַבָּנָן. אֲבָל בְּכִלְאַיִם דְּאוֹרַיְתָא, אֵין הוֹלְכִין לְהָקֵל בִּסְפֵקָן (טוּר)\u0006.\nהַלּוֹקֵחַ כְּלֵי צֶמֶר מֵהַגּוֹיִים, צָרִיךְ לְבָדְקָן יָפֶה יָפֶה, שֶׁמָּא הֵם תְּפוּרִים בְּפִשְׁתָּן. \u0005וְהַקּוֹנֶה בְּגָדִים מִן הָעוֹבֵד כּוֹכָבִים, צָרִיךְ לְהַתִּיר תְּפִירָתָן וּלְתָפְרָן בְּקָנַבּוֹס (טוּר)\u0006 \u0010y1\u0011 וְאֲפִלּוּ אִם הָעוֹבֵד כּוֹכָבִים מֵסִיחַ לְפִי תֻּמּוֹ שֶׁתְּפָרָן בְּקַנַּבּוֹס, \u0010c2\u0011 אֵינוֹ נֶאֱמָן. \u0010y2\u0011 וּבִמְקוֹמוֹת שֶׁהַפִּשְׁתָּן בְּיֹקֶר מִן הַקַנַּבּוֹס, \u0010c3\u0011 יֵשׁ לִסְמֹךְ לְהַתִּיר. \u0005הַגָּה: וְאָסוּר לוֹמַר לְעוֹבֵד כּוֹכָבִים לִתְפֹּר לוֹ בְּגָדִים בְּחוּטֵי קַנַּבּוֹס, אַף עַל פִּי שֶׁפִּשְׁתָּן יוֹתֵר בְּיֹקֶר, דְּנָקֵל לִתְפֹּר בְּפִשְׁתָּן מִבַּקַנַּבּוֹס (רַשְׁבָּ\"א סִימָן \u0010c4\u0011 תשס\"א)\u0006. אֲבָל אִם נוֹתֵן לוֹ חוּטֵי קַנַּבּוֹס, שָׁרֵי, \u0010y3\u0011 וְלֹא חַיְשִׁינָן לְאַחְלוּפֵי, מֵאַחַר שֶׁיֵּשׁ לַעֲמֹד עַל הַדָּבָר, שֶׁחוּטֵי פִּשְׁתָּן \u0010y4\u0011 כְּשֶׁמַּדְלִיק כָּבֵה מַהֵר, וְשֶׁל קַנַּבּוֹס הוֹלֵךְ וְשׂוֹרֵף \u0005(כֵּן מַשְׁמָע במ\"מ פ\"ח דמ\"א)\u0006. וְכֵן נוֹהֲגִין, אַף עַל פִּי שֶׁיֵּשׁ מַחְמִירִין \u0005(רַשְׁבָּ\"א הַנַּ\"ל)\u0006. וְיִשְׂרָאֵל הֶחָשׁוּד לִתְפֹּר כִּלְאַיִם, דִּינוֹ כְּעוֹבֵד כּוֹכָבִים. \u0010y5\u0011 יֵשׁ מַחְמִירִין דְּלֹא יִתְפֹּר בֶּגֶד צֶמֶר בְּקַנַּבּוֹס לָבָן, שֶׁלֹּא יַחְשְׁדוּהוּ שֶׁהוּא פִּשְׁתָּן, וְלָכֵן צוֹבְעִין הַקַנַּבּוֹס. \u0005(מהרי\"ל)\u0006.",["\u0003ה\"ז מותר כו'. \u0004והוא הדין אם ניתק ממנו חוט א' תולין להקל בכלאים דרבנן כדאיתא בטור ובפוסקים:","\u0003ואפי' אם העובד כוכבים מסיח לפי תומו כו'. \u0004כי הוא ידוע לכל העובדי כוכבים שחייטים ישראל מחזרים על הכפרים לקנות מהן מטוה של קנבוס לתפור כי אינו מצוי כמו הפשתן והלכך איכא למימר זה עובד כוכבי' להשביח מקחו הוא אומר כ\"כ הרא\"ש ועט\"ז ואין להקשות לאיזה צורך הוצרכו לזה דהא ס\"ל דאין עובד כוכבים נאמן במסל\"ת אפי' באיסור דרבנן אלא בעדות אשה וכדלעיל סוף סימן קל\"ז דכבר הוכחתי שם דהיינו דוקא היכא דאיתחזק איסור' אבל הכא דלא איתחזק איסורא והוה נאמן אם לא שידוע לכל העובדי כוכבים ולהשביח מקחו הוא אומר כן:","\u0003ובמקומות שהפשתן כו'. \u0004כלומר דוקא דיעבד יש לסמוך להתיר על טעם זה בלבד שהפשתן ביוקר מן הקנבוס אע\"פ שנקל לתפור בפשתן מקנבוס ויצא שכרו בהפסדו אבל לכתחלה אסור כו' וכדמסיק הרב וכן הוא בתשובת הרשב\"א ובב\"ח וע\"ל סי' קי\"ח סעיף ז' וי':","\u0003ולא חיישינן לאחלופי כו'. \u0004דכיון דהוא אומן לא מרעא אומנתיה מאחר שיש לו לעמוד על הדבר כן הוא בהרב המגיד ור\"ן ורבינו ירוחם ושאר מחברים טעמא דאומן והרב קיצר במובן:","\u0003כשמדליק כבה מהר כו'. \u0004ובס' מע\"מ סוף דף רצ\"ב כתב ושמעתי מחייטין ישראלים שבודקים הקנבוס בענין זה שמושכין החוט עד שנמשכין כמין שערות ואם אותן שערות מרובות (צ\"ל ארוכות) הרבה בידוע שהוא קנבוס עד כאן:","\u0003יש מחמירין כו'. \u0004דומה לדלעיל סימן רצ\"ח ע\"ש:"],["\u0003שהרי בדק ולא מצאו. \u0004בטור כתב או ינתק החוט כו' כמו שהעתקתי בסמוך והוא מן הגמרא בנדה (דף ס\"א) האי מאן דרמי חוט דכיתנא בגלימא דעמרא ונתקיה ולא ידיע אי נתיק או לא נתיק שפיר דמי מ\"ט מדאורייתא שעטנז כתיב עד שיהא שוע טווי ונוז ורבנן הוא דגזרו ביה וכיון דלא ידיע אי נתקיה שרי והקשה ב\"י דמלשון זה משמע דלא שרי לכתחלה למנתקיה והטור כתב או ינתק דמשמע דלכתחלה נמי שרי למנתקיה עכ\"ל ואני אוסיף לתמוה מ\"ש מההיא דסימן ק\"י בתערובות איסור שאינו בטיל מחמת חשיבותו דמותר בנפל אחד מהם לים דאמרינן האיסור נפל ודוקא נפל מעצמו אבל אם הפילו אדם אפילו שוגג אסור וכאן בחוטין של כלאים ג\"כ חשיבי כמ\"ש סימן רצ\"ט בב\"י בשם סמ\"ג ותו דהרי הוכחתי דכ\"ע ס\"ל דאין בטיל ע\"ש והתירו כאן אפילו הסיר חוט אחד במזיד והלא גם שם מיירי מאיסור דרבנן דמדאורייתא חד בתרי בטיל אפי' בדבר חשוב ומנא ליה לטור לחלק ביניהם ומחמת תמיה זו נראה ליישב דעת הטור שהוכיח דלכתחלה נמי שרי דאם יש איסור בעושה מזיד למה התירו בזה אם נתקו אדם אמאי לא גזרינן משום מזיד גם בזה ותו קשה יתור לשון בגמ' שאמרה ונתקיה ולא ידיע אם נתקיה היה לו לומר ולא ידיע אם נתקיה או לא ולמה לו לומר ונתקיה ואין לומר דמיירי שידוע שנתק האיסור אלא שאין ידוע אם ניתק כולו או לא הא לאו מילתא היא דמה לי ספק אם לא נתקו כלל או לא ניתק כולו דמקצת הוה בזה ככולו אלא ודאי הכי פירושו דאחר שנודע התערובות הלך והסיר חוט אחד מהם בכוון כדי לתלות בו ולא ידיע אי נתקיה לאיסור או לא ואפ\"ה שרי דמיירי כאן בכלאים דרבנן דהא כ' הטור בגד שארג חוט אחד כו' וכן הוא בש\"ס בהאי מילתא וכיון שכאן הוא הפסד מרובה שהרי אפילו למכרו לעובד כוכבים אסור על כן הקילו רבנן לסמוך על זה דאיסור ניתק משא\"כ בההיא דסי' ק\"י דמותר למכרו לעובד כוכבים הוה הפסד מועט על כן גזרו שלא לסמוך על זה אם עושה במזיד וכן מצינו בהרבה מקומות דלהפסד מרובה חששו דוקא כן נ\"ל דעת הטור ומשום הכי לא הביא הרמב\"ם הך מילתא דנתקיה דאיהו סבירא ליה שיש כאן איסור דאורייתא כמ\"ש סי' רצ\"ט סעיף א':","\u0003בד\"א בכלאים דרבנן כו'. \u0004ברמב\"ם כתוב וז\"ל וכבר ביארנו שכל איסור ספיקות מדברי סופרים ולפיכך הקילו בספק וכתב עליו הראב\"ד אמת הוא שכל הספיקות אינן של תורה מיהו קיימא לן כל ספק איסור תורה לחומרא ובדרבנן לקולא וכתב בעל כסף משנה מה שהקשה הראב\"ד דספק דאורייתא לחומרא י\"ל שחז\"ל שאמרו כן הם אמרו דספק זה יהיה לקולא משום דהיא מילתא דלא שכיחא ודבריו תמוהים דאמאי הוה מילתא דלא שכיחא בתערובת פשתן בין צמר ותו דלפי הבנתו בדברי הראב\"ד אמאי הקשה על הרמב\"ם בזה ולא על התלמוד דדין זה הוא בגמרא בברייתא ונראה דהרמב\"ם הוקשה לו במה שאמר בגמ' וכיון דלא ידיע אימר מינתר נתיר דמשמע מיניה דאין זה ודאי דנתיר אלא ספק הוא וכן ל' הפוסקים שמא נשמט ולמה נקיל בו בספק דאורייתא ע\"כ תירץ דכל ספק איסור הוא מדבריהם ואין כאן ספק דאורייתא לחומרא כיון דכבר בדק אחר זה ובדיקה מהני לביטול איסור דאורייתא אלא שיש לחוש לשמא לא בדק יפה וזה הוא ספק דרבנן והראב\"ד לא ניחא ליה בזה וע\"כ הקשה דמ\"מ קיימא לן דספק איסור דאורייתא לחומרא ודעת הראב\"ד דהאי איסור הוא ודאי ג\"כ כדאשכחן בא\"ט גבי ספק דרוסה אימור שלמא עביד וכתב הר\"ן כל הני אימור דאמרינן כאן ודאי חשבינן להו כו' ומכל זה מוכח עכ\"פ דמיירי כאן בכלאים דאורייתא שנאבד בבגד וכן מוכח בגמרא בנדה (דף ס\"א) דמדמה בדיקה זו לההיא מתני' בודק עד שמגיע לסלע והתם מיירי בכזית מן המת שיש בגל כדפרש\"י ממתניתין שם ואפ\"ה מהני הבדיקה ה\"נ בדיקה דצובע הבגד לענין כלאים אלמא אפילו במידי דאורייתא מהני הבדיקה אלא דקשה על הטור שכ' אחר דין זה בד\"א בכלאים דרבנן אבל בכלאים דאורייתא אין תולין בספיקא להקל עכ\"ל וקשה מן הגמרא שהבאתי על כן נראה ברור דמה שכ' במה דברים אמורים בכלאים דרבנן כו' לא קאי אלא אחלוקה השניה שכתב או ינתק חוט א' ממנו והוא מותר שאנו תולין לומר שהסיר חוט של כלאים כו' אבל לא אחלוקה הראשונה דהיינו הצביעה וכן מבואר בלשון הטור אבל בכלאים דאורייתא אין תולין בספיקא להקל הך לשון אין תולין הוא שייך בחלוקה השנייה שכתב בה תולין כו' אבל ברישא אין שייך בה לשון תולין דלשון תולין שייך על מעש' שנעשה בדבר ספק שבהיתר נעשה והיינו דוקא בסיפא ובזה מתורץ נמי למה הוצרך הטור להאריך ולומר אין תולין בספיקא להקל היה לו לומר אבל בכלאים דאורייתא לא ע\"כ נראה ברור כמו שכתבתי ואין שום מחלוקת בזה בין טור להרמב\"ם והראב\"ד דכולהו מודי דצביעה מהני אפילו בכלאים דאורייתא והב\"י כתב דהך בד\"א קאי נמי אצביעה ולדידיה יחלוק הטור על הרמב\"ם והראב\"ד ואחריו נמשך רמ\"א כאן שכתב בד\"א כו' ונראה לע\"ד דלא יצאו ידי חובת העיון כל הצורך במחילה מכבודם כי בגמרא מוכח להדיא דאף בדאורייתא מהני בדיקה דצביעה כמו בדיקה דטומאת מת דאורייתא כמו שהבאתי:","\u0003אינו נאמן. \u0004לפי שיודע שהישראל מבקש אחר קנבוס ע\"כ להשביח מקחו אומר כן:","\u0003יש לסמוך להתיר. \u0004בב\"י בשם הר\"ש כתב במקום שהפשתן ביוקר וטוב יותר לתפור בקנבוס לפי שהוא חוט חזק התפירה יש להתיר עכ\"ל. והקשה מו\"ח ז\"ל על הש\"ע למה פסק כאן להתיר בתנאי אחד מחמת שהפשתן ביוקר והר\"ש התנה תנאי שני עוד דהיינו שטוב לתפור בו מחמת שהוא חזק ודחק לתרץ דש\"ע מיירי בדיעבד ולעד\"נ דמאי דאמר הר\"ש שהוא חזק כו' אינו תנאי כלל דודאי בכל המקומות חזק יותר אלא העיקר באם הפשתן ביוקר אלא שלא תקשה מאי מהני מה שהוא ביוקר מ\"מ יש סברא כנגדו דהפשתן טוב יותר לתפירה מחמת שהוא חלק יותר מקנבוס כמ\"ש ב\"י בשם הר\"ן וכמ\"ש רמ\"א אח\"כ לזה כתב שהקנבוס יותר חזק לתפור ואינו נקרע בתפירה ובפשתן נקרע ויש בו טורח לאומן לתקן מחדש נמצא שסברות אלו הם מוכרעות זו כנגד זו דהיינו פשתן יש בו מעלה מצד חליקתו ויש בו גריעותא מצד חלישתו וע\"כ הדבר תלוי במה שהוא ביוקר דזהו מכריע להיתר ותלוי בנמצא במקומות אבל לענין חוזק החוט ודאי בכל המקומות הוא כן וזה פשוט לענ\"ד:","\u0003אבל אם נותן כו'. \u0004רמ\"א הכריע להתיר בזה דוקא כדעת המ\"מ מטעם דחייש לאחלופי מאחר שיש לעמוד וכו' דאם אין נותן לו יש לו לתרץ ולתקן עוותו ולומר טעיתי והייתי סבור שזה קנבוס משא\"כ בנותן לו קנבוס ואח\"כ רואה שהוא פשתן לא יוכל לתקן מעשיו שהיה לו להזהר במה שנתן לו ולייחד לו מקום מיוחד כן נראה לי טעמו ולא ס\"ל טעם דקנבוס הוא חזק כסברת הר\"ש והא דלא כתב דבריו דרך פלוגתא על הש\"ע כיון שאפשר דגם הש\"ע מיירי בדרך זה:"]],["הָרוֹאֶה כִּלְאַיִם שֶׁל תּוֹרָה עַל חֲבֵרוֹ, אֲפִלּוּ הָיָה מְהַלֵּךְ בַּשּׁוּק, הָיָה קוֹפֵץ לוֹ וְקוֹרְעוֹ מֵעָלָיו מִיָּד, \u0010y0\u0011 וַאֲפִלּוּ הָיָה רַבּוֹ. \u0010y1\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאִם הָיָה הַלּוֹבֵשׁ שׁוֹגֵג, \u0010y2\u0011 אֵין צָרִיךְ לוֹמַר בַּשּׁוּק, דְּמִשּׁוּם כְּבוֹד הַבְּרִיּוֹת יִשְׁתֹּק, וְאַל יַפְרִישֶׁנּוּ מִשּׁוֹגֵג (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וְאִם הָיָה שֶׁל דִּבְרֵיהֶם, אֵינוֹ קוֹרְעוֹ מֵעָלָיו וְאֵינוֹ פּוֹשְׁטוֹ בַּשּׁוּק, עַד שֶׁמַּגִּיעַ לְבֵיתוֹ. \u0005וְכֵן בְּבֵית הַמִּדְרָשׁ אֵין צָרִיךְ לְמַהֵר לָצֵאת (טוּר)\u0006. וְאִם הָיָה שֶׁל תּוֹרָה, פּוֹשְׁטוֹ מִיָּד. \u0010y3\u0011\nאָסוּר לְהַלְבִּישׁ אֶת חֲבֵרוֹ כִּלְאַיִם.",["\u0003ואפי' היה רבו. \u0004דבמקום שיש חילול השם אין חולקין כבוד לרב וע\"ל סי' רמ\"ב סכ\"ב:","\u0003דאם היה הלובש שוגג. \u0004דהיינו שאינו יודע כלל שהוא כלאים אבל אם אחר שמצאו ישהנו עליו נמצא שהוא משהה אותו במזיד עליו. כן משמע בטור וכ\"כ ב\"י:","\u0003אין צריך לומר לו בשוק. \u0004עד שיגיע לביתו:","\u0003אסור להלביש כו'. \u0004משום לפני עור לא תתן מכשול:"],[]],["כִּלְאֵי בְּגָדִים \u0010y0\u0011 מֻתָּר לַעֲשׂוֹתָם וּלְקַיְּמָם, וְאֵינָם אֲסוּרִים אֶלָּא בִּלְבִישָׁה.",["\u0003מותר לעשותם כו'. \u0004והא דכתב הרב לעיל סי' ש\"א ס\"ב דלכתחלה לא יעשה של כלאים היינו בדברים שיש לחוש שיתכסה בהן והיינו שעושין אותן לעצמן או לישראל אחר אבל הכא מיירי בענין שאין לחוש לזה כגון שהוא בגד של עובד כוכבים ועושין אותו לעובדי כוכבים וכה\"ג:"],[]],["\u0003הלכות פדיון בכור\u0004\nמִצְוַת עֲשֵׂה לִפְדּוֹת כָּל אִישׁ מִיִּשְׂרָאֵל בְּנוֹ, שֶׁהוּא בְּכוֹר לְאִמּוֹ הַיִּשְׂרְאֵלִית, בְּה' סְלָעִים שֶׁהֵם ק\"כ מָעִים שֶׁהֵם שְׁלֹשִׁים דֶּרְהַמִּים כֶּסֶף מְזֻקָּק. \u0005וְעַיֵּן לְעֵיל סי' רצ\"ד כַּמָּה הִיא הַמָעָה. וְיֵשׁ אוֹמְרִים שֶׁה' סְלָעִים הֵם בְּעֵרֶךְ \u0010c0\u0011 שְׁנֵי זְהוּבִים רייני\"ש, שֶׁהֵם \u0010y0\u0011 ב' זְהוּבִים פולני\"ש (פִּסְקֵי מהרא\"י סי' מ\"ח)\u0006.\nאֵין הָאִשָּׁה חַיֶּבֶת לִפְדּוֹת אֶת בְּנָהּ \u0005(ל' רַמְבַּ\"ם פ' י\"א מֵהִלְכוֹת בְּכוֹרִים ד\"ב)\u0006.\nאֵלּוּ הַחֲמִשָּׁה סְלָעִים נוֹתְנָן לַכֹּהֵן בְּכֶסֶף אוֹ בִּשְׁוֵה כֶּסֶף מִכָּל דָּבָר שֶׁיִּרְצֶה, חוּץ מִקַּרְקָעוֹת וַעֲבָדִים \u0010y1\u0011 \u0010c1\u0011 וּשְׁטָרוֹת; וְאִם פָּדָהוּ בָּהֶם, אֵינוֹ פָּדוּי.\nכָּתַב לַכֹּהֵן שֶׁהוּא חַיָּב לוֹ חֲמִשָּׁה סְלָעִים בִּשְׁבִיל פִּדְיוֹן בְּנוֹ, \u0010c2\u0011 חַיָּב לִתְּנָם לוֹ \u0010y2\u0011 וּבְנוֹ אֵינוֹ פָּדוּי \u0005(טוּר בְּשֵׁם ה\"ג)\u0006. \u0005אָמַר לַכֹּהֵן שֶׁנּוֹתֵן לוֹ לִפְדּוֹת אֶת בְּנוֹ, אָסוּר לַחֲזֹר בּוֹ. מִיהוּ אִם חָזַר, הָוֵי חֲזָרָה\u0006 \u0005(מָרְדְּכַי ס\"פ כָּל הַגֵּט)\u0006 \u0010y3\u0011 \u0010c3\u0011 \u0005וְעַיֵּן לְעֵיל סי' \u0010y4\u0011 \u0010c4\u0011 רס\"ה.\u0006\nנָתַן לוֹ כְּלִי שֶׁאֵינוֹ שָׁוֶה בַּשּׁוּק חֲמִשָּׁה סְלָעִים, וְקִבְּלוֹ הַכֹּהֵן בַּחֲמִשָּׁה סְלָעִים, הֲרֵי בְּנוֹ פָּדוּי; \u0005(רַמְבַּ\"ם שָׁם)\u0006 וְהוּא שֶׁיִּשְׁוֶה חֲמִשָּׁה סְלָעִים לְשׁוּם אָדָם.\nנָתַן לוֹ כְּלִי בְּפִדְיוֹן בְּנוֹ, סְתָם, אִם הוּא שָׁוֶה ה' סְלָעִים, אַף עַל פִּי שֶׁלֹּא שָׁמוּ אוֹתוֹ בִּתְחִלָּה, בְּנוֹ פָּדוּי. \u0005הַגָּה: וְאִם אֵינוֹ שָׁוֶה, אֵין בְּנוֹ פָּדוּי (טוּר)\u0006. וְאִם הַכֹּהֵן רוֹצֶה לְהַחֲזִיק בַּכְּלִי, אֵין צָרִיךְ לְהַחֲזִיר לוֹ, וְהוּא יַשְׁלִים לוֹ עַד ה' סְלָעִים \u0005(מהרי\"ל)\u0006.\nנָתַן ה' סְלָעִים, אֲפִלּוּ לַעֲשָׂרָה כֹּהֲנִים, בֵּין בְּבַת אַחַת בֵּין בָּזֶה אַחַר זֶה, בְּנוֹ פָּדוּי.\nאִם רָצָה הַכֹּהֵן לְהַחֲזִיר לוֹ הַפִּדְיוֹן, רַשַּׁאי \u0005(ל' רַמְבַּ\"ם שָׁם ד\"ח)\u0006 \u0010y5\u0011 \u0010c5\u0011 ; אֲבָל לֹא יִתֵּן הוּא לַכֹּהֵן עַל מְנַת שֶׁיַּחֲזִיר לוֹ, וְאִם עָשָׂה כֵן \u0010y6\u0011 וְהֶחֱזִיר לוֹ \u0005וְדַעַת הַכֹּהֵן הָיְתָה מִתְּחִלָּה שֶׁלֹּא לְקַבְּלָהּ עַל מְנַת לְהַחֲזִיר (כָּךְ מַשְׁמָע בְּבֵית יוֹסֵף)\u0006, אֵין בְּנוֹ פָּדוּי עַד שֶׁיִּגְמֹר בְּלִבּוֹ לִתֵּן לוֹ מַתָּנָה גְּמוּרָה, וְאִם רָצָה הַכֹּהֵן אַחַר כָּךְ לְהַחֲזִיר יַחֲזִיר. וְלֹא יְהֵא הַכֹּהֵן רָגִיל לְהַחֲזִיר לַכֹּל, שֶׁלֹּא לְהַפְסִיד לִשְׁאָר כֹּהֲנִים, שֶׁמִּתּוֹךְ כָּךְ לֹא יִתְּנוּ הַכֹּל פִּדְיוֹנֵי בְּכוֹרֵיהֶם אֶלָּא לוֹ. אֲבָל לַעֲנִיִּים רַשַּׁאי לְהַחֲזִיר בְּכָל פַּעַם. וְכָל שֶׁכֵּן שֶׁמִּזֶּה הַטַּעַם לֹא יְקַבְּלֵם עַל מְנַת לְהַחֲזִיר; וּמִכָּל מָקוֹם אִם עָבַר וְקִבְּלָם, וּפֵרֵשׁ שֶׁנּוֹתֵן לוֹ עַל מְנַת לְהַחֲזִיר, הַבֵּן פָּדוּי, דְּמַתָּנָה עַל מְנַת לְהַחֲזִיר שְׁמָהּ מַתָּנָה. \u0010y7\u0011 \u0005וְדַוְקָא שֶׁאָמַר: עַל מְנַת לְהַחֲזִיר, אֲבָל אִי אָמַר: הֵא לְךָ \u0010c6\u0011 ה' סְלָעִים וְתַחֲזִירֵם לִי, לֹא הָוֵי מַתָּנָה וְאֵין בְּנוֹ פָּדוּי (רַשְׁבָּ\"א סי' קצ\"ח ותשנ\"ט)\u0006.\nהִפְרִישׁ חֲמִשָּׁה סְלָעִים לְפִדְיוֹן בְּנוֹ, וְנֶאֶבְדוּ, חַיָּב בְּאַחֲרָיוּתָן עַד שֶׁיָּבוֹאוּ לְיַד כֹּהֵן. \u0010y8\u0011\nבְּשָׁעָה שֶׁנּוֹתֵן הַפִּדְיוֹן לַכֹּהֵן מְבָרֵךְ: אקב\"ו \u0010c7\u0011 עַל פִּדְיוֹן הַבֵּן, וְחוֹזֵר \u0010y9\u0011 וּמְבָרֵךְ: שֶׁהֶחֱיָנוּ, וְאַחַר כָּךְ נוֹתֵן הַפִּדְיוֹן לַכֹּהֵן, וְאִם פּוֹדֶה עַצְמוֹ, מְבָרֵךְ: אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לִפְדּוֹת הַבְּכוֹר, וּמְבָרֵךְ: שֶׁהֶחֱיָנוּ \u0005(רַמְבַּ\"ם שָׁם ד\"ה)\u0006. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאַף הַפּוֹדֶה עַצְמוֹ מְבָרֵךְ: עַל פִּדְיוֹן הַבְּכוֹר, וְכֵן נוֹהֲגִין\u0006 \u0005(טוּר וריב\"ש סי' קל\"א)\u0006. \u0005וְעַיֵּן לְעֵיל סי' רס\"ה. יֵשׁ אוֹמְרִים דְּמַיְיתֵי לֵיהּ לִבְכוֹר קָמֵיה כֹּהֵן וּמוֹדִיעַ לֵיהּ שֶׁהוּא בְּכוֹר פֶּטֶר רֶחֶם, וְהַכֹּהֵן שׁוֹאֵל אוֹתוֹ: בְּמַאי בָּעֵית טְפֵי, בְּבִנְךָ בְּכוֹרְךָ אוֹ חֲמִשָּׁה סְלָעִים דְּמִחְיַּבְתְּ לִפְדּוֹת בָּהֶן, וְהָאָב אוֹמֵר: בִּבְנִי בְּכוֹרִי וְהֵילָךְ חֲמִשָּׁה סְלָעִים בְּפִדְיוֹנוֹ, \u0010c8\u0011 וּבַהֲדֵי שֶׁנּוֹתֵן לוֹ הַמָּעוֹת מְבָרֵךְ בְּרָכוֹת הַנִּזְכָּרוֹת\u0006 \u0005(טוּר ורא\"ש בְּשֵׁם הַגְּאוֹנִים)\u0006 \u0005וְכֵן נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ, אִם הָאָב אֵצֶל הַבֵּן. אֲבָל אִם אֵינוֹ אֶצְלוֹ, פּוֹדֶה אוֹתוֹ בְּלָאו הָכֵי, אֶלָּא אוֹמֵר לַכֹּהֵן שֶׁיֵּשׁ לוֹ בְּכוֹר לִפְדּוֹתוֹ, וְהוּא אוֹמֵר: בְּמַאי בָּעֵית טְפֵי וְכו'\u0006 \u0005(כֵּן הוּא בְּהַגָּהַת מָרְדְּכַי ס\"פ הָאִשָּׁה וְכֵן כָּתַב הבֵּית יוֹסֵף בְּשֵׁם סמ\"ק)\u0006. \u0005וְאִם הָאָב הָיָה רוֹצֶה לְהַנִּיחַ הַבֵּן לַכֹּהֵן, אֵינוֹ יוֹצֵא, רַק צָרִיךְ לִפְדּוֹתוֹ\u0006 \u0005(פִּסְקֵי מהרא\"י סי' קל\"ה)\u0006. \u0005וְיֵשׁ שֶׁכָּתְבוּ שֶׁנָּהֲגוּ לַעֲשׂוֹת סְעֻדָּה בִּשְׁעַת הַפִּדְיוֹן\u0006 \u0005(שָׁם בְּהַגָּהוֹת מָרְדְּכַי ומהרי\"ל ות\"ה סי' רס\"ט)\u0006. \u0010c9\u0011 \u0005וְאִם יַיִן בָּעִיר, מְבָרֵךְ הַכֹּהֵן עַל הַיַּיִן מִיָּד אַחַר הַפִּדְיוֹן\u0006 \u0005(מהרי\"ל)\u0006. \u0005וְכֵן נוֹהֲגִין עַכְשָׁו כְּדֵי לְפִרְסוּמֵי מִלְּתָא. וְאֵין נוֹהֲגִין לְבָרֵךְ שֶׁהַשִּׂמְחָה בִּמְעוֹנוֹ\u0006 \u0005(אַבּוּדַרְהַם)\u0006. \u0010y10\u0011 \u0010c10\u0011 \u0005וְאֵין הָאָב יָכוֹל לִפְדּוֹת עַל יְדֵי שָׁלִיחַ. וְגַם אֵין בֵּית דִּין פּוֹדִין אוֹתוֹ בְּלֹא הָאָב\u0006 \u0005(ריב\"ש סי' קל\"א)\u0006.\nאֵין הַבְּכוֹר רָאוּי לְפִדְיוֹן עַד שֶׁיַּעַבְרוּ עָלָיו שְׁלֹשִׁים יוֹם; וְאַחַר שְׁלֹשִׁים יוֹם יִפְדֶּנּוּ מִיָּד, שֶׁלּא יַשְׁהֶה הַמִּצְוָה. וְאִם חָל יוֹם ל\" א לִהְיוֹת בְּשַׁבָּת, \u0010y11\u0011 אֵין פּוֹדִין אוֹתוֹ בְּשַׁבָּת, אֶלָּא יַמְתִּין עַד יוֹם א'. \u0010y12\u0011 \u0005יֵשׁ אוֹמְרִים דְּאֵין לַעֲשׂוֹת פִּדְיוֹן הַבֵּן בְּחֹל הַמּוֹעֵד (במהרי\"ו בְּשֵׁם סֵפֶר הַמִּצְוֹת \u0010y13\u0011 מִצְוָה ר\"\u0006 ךָ), וְיֵשׁ מַתִּירִין. \u0005(תּוֹסָפוֹת פ\"ק דמ\"ק)\u0006, \u0010y14\u0011 וְכֵן עִקָּר.\nמֵת הַבֵּן בְּתוֹךְ שְׁלֹשִׁים, וְאֲפִלּוּ בְּיוֹם שְׁלֹשִׁים, וְכֵן \u0010y15\u0011 אִם נַעֲשָׂה טְרֵפָה קֹדֶם שֶׁעָבְרוּ עָלָיו שְׁלֹשִׁים יוֹם, אֵינוֹ חַיָּב בְּפִדְיוֹן; וַאֲפִלּוּ הִקְדִּים וְנָתַן לַכֹּהֵן הַפִּדְיוֹן, יַחֲזִירֶנּוּ לוֹ. \u0005מֵת לְאַחַר שְׁלֹשִׁים, חַיָּב לִפְדּוֹתוֹ (טוּר)\u0006 וּלְבָרֵךְ עַל הַפִּדְיוֹן, \u0010y16\u0011 אֲבָל לֹא יְבָרֵךְ שֶׁהֶחֱיָנוּ \u0005(ד\"ע וְכֵן הוּא במהרי\"ק סוֹף שֹׁרֶשׁ מ\"ט)\u0006.\nמִי שֶׁפָּדָה בְּנוֹ בְּתוֹךְ שְׁלֹשִׁים יוֹם, אִם אָמַר לֵיהּ: \u0010y17\u0011 \u0010c11\u0011 מֵעַכְשָׁו, אֵין בְּנוֹ פָּדוּי. \u0010c12\u0011 וְאִם אָמַר לֵיהּ: לְאַחַר שְׁלֹשִׁים יוֹם, בְּנוֹ פָּדוּי \u0010c13\u0011 וְאַף עַל פִּי שֶׁאֵין הַמָּעוֹת קַיָּמִים לְאַחַר ל' יוֹם. \u0005הַגָּה: \u0010y18\u0011 וְיֵשׁ אוֹמְרִים דְּאִם אֵין הַמָּעוֹת קַיָּמִים אוֹ שֶׁהֶחֱזִירָן לְאָב תּוֹךְ ל', אֲפִלּוּ בְּדִיעֲבַד אֵין בְּנוֹ פָּדוּי (מהרא\"י בת\"ה סִימָן רס\"ד וּבִכְתָבָיו סִימָן רל\"ד)\u0006 \u0010c14\u0011 ; וְטוֹב לְהַחְמִיר לַחֲזֹר לִפְדּוֹתוֹ. מִי שֶׁהוּא סָפֵק אִם הוּא חַיָּב בְּפִדְיוֹן, פָּטוּר, שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nמֵת הָאָב בְּתוֹךְ שְׁלֹשִׁים יוֹם, הֲרֵי הַבֵּן בְּחֶזְקַת שֶׁלֹּא נִפְדָּה, עַד שֶׁיָּבִיא רְאָיָה שֶׁפְּדָאוֹ אָבִיו. וְאִם מֵת הָאָב לְאַחַר שְׁלֹשִׁים יוֹם, בְּחֶזְקַת שֶׁנִּפְדָּה עַד שֶׁיּוֹדִיעוּהוּ שֶׁצִּוָּה בִּשְׁעַת מִיתָה וְאָמַר שֶׁלֹּא נִפְדָּה.\nעָבַר הָאָב וְלֹא פָּדָה אֶת בְּנוֹ, כְּשֶׁיַּגְדִּיל, חַיָּב לִפְדּוֹת עַצְמוֹ. \u0010y19\u0011 \u0005וְיֵשׁ מִי שֶׁכָּתַב דְּכוֹתְבִין לוֹ עַל טָס שֶׁל כֶּסֶף שֶׁאֵינוֹ נִפְדֶּה וְתוֹלִין לוֹ בְּצַוָּארוֹ, כְּדֵי שֶׁיֵּדַע לִפְדּוֹת עַצְמוֹ כְּשֶׁיַּגְדִּיל (מהרי\"ל)\u0006. הָיָה הוּא לִפְדּוֹת וּבְנוֹ לִפְדּוֹת, יִפְדֶּה עַצְמוֹ תְּחִלָּה, וְאַחַר כָּךְ יִפְדֶּה אֶת בְּנוֹ. וְאִם אֵין לוֹ אֶלָּא כְּדֵי פִּדְיוֹן אֶחָד, יִפְדֶּה עַצְמוֹ.\nאִם אֵין לוֹ נְכָסִים בְּנֵי חוֹרִין כְּדֵי פִּדְיוֹן, \u0010c15\u0011 אֵין הַכֹּהֵן גּוֹבֶה \u0010y20\u0011 מֵהַמְשֻׁעְבָּדִים, אַף עַל פִּי שֶׁקָּדַם חוֹב הַפִּדְיוֹן לְחוֹב הַבַּעַל חוֹב.\nאֵין פִּדְיוֹן הַבְּכוֹר תָּלוּי אֶלָּא בְּפֶטֶר רֶחֶם, שֶׁאִם אֵינוֹ בְּכוֹר לְאֵם אַף עַל פִּי שֶׁהוּא בְּכוֹר לְאָב אֵינוֹ חַיָּב בְּפִדְיוֹן. וְאִם יֵשׁ לוֹ כַּמָּה נָשִׁים, וְיֵשׁ לוֹ בְּכוֹר מִכָּל אַחַת וְאַחַת, חַיָּב לִפְדּוֹת אֶת כֻּלָּם.\nכֹּהֲנִים וּלְוִיִּם פְּטוּרִים מִפִּדְיוֹן הַבֵּן. וַאֲפִלּוּ כֹּהֶנֶת וּלְוִיָּה נְשׂוּאָה לְיִשְׂרָאֵל, אֵין הַבֵּן חַיָּב בְּפִדְיוֹן, שֶׁאֵין הַדָּבָר תָּלוּי בָּאָב אֶלָּא בָּאֵם, שֶׁנֶּאֱמַר: פֶּטֶר רֶחֶם בְּיִשְׂרָאֵל \u0005(בַּמִּדְבָּר ג, יב)\u0006 וְאִם נִתְעַבְּרָה מֵעוֹבֵד כּוֹכָבִים, בֶּן הַלְוִיָּה פָּטוּר מִפִּדְיוֹן, \u0010y21\u0011 וּבֶן הַכֹּהֶנֶת חַיָּב בְּפִדְיוֹן, שֶׁהֲרֵי נִתְחַלְּלָה אִמּוֹ מִן הַכְּהֻנָּה בִּבְעִילַת הָעוֹבֵד כּוֹכָבִים. \u0005הַגָּה: וְאִם הִיא אוֹמֶרֶת שֶׁמִּיִּשְׂרָאֵל נִתְעַבְּרָה, וְהַיִּשְׂרָאֵל מַכְחִישָׁהּ וְאוֹמֵר שֶׁמֵּעוֹבֵד כּוֹכָבִים נִתְעַבְּרָה, \u0010y22\u0011 הַבֵּן פָּטוּר מִן הַפִּדְיוֹן (ת\"ה סִימָן רס\"ד)\u0006.\nכֹּהֵן שֶׁנוֹלַד לוֹ \u0010y23\u0011 בֵּן חָלָל, מֵת הָאָב בְּתוֹךְ שְׁלֹשִׁים יוֹם חַיָּב הַבֵּן לִפְדּוֹת אֶת עַצְמוֹ, שֶׁלֹּא זָכָה הָאָב בְּפִדְיוֹנוֹ. וְאִם מֵת הָאָב לְאַחַר שְׁלֹשִׁים יוֹם, \u0010c16\u0011 כְּבַר זָכָה הָאָב בְּפִדְיוֹנוֹ וִיְרָשׁוֹ בְּנוֹ מִמֶּנּוּ, הִלְכָּךְ יַפְרִישׁ הַפִּדְיוֹן וִיעַכְּבֶנּוּ לְעַצְמוֹ.\nהַשִּׁפְחָה שֶׁנִּשְׁתַּחְרְרָה וְכוּתִית שֶׁנִּתְגַיְּרָה כְּשֶׁהֵן מְעֻבָּרוֹת, וְיָלְדוּ, אַף עַל פִּי שֶׁהוֹרָתוֹ שֶׁלֹּא בִּקְדֻשָּׁה, הוֹאִיל וְנוֹלַד בִּקְדֻשָּׁה חַיָּב, שֶׁנֶּאֱמַר: פֶּטֶר רֶחֶם בְּיִשְׂרָאֵל \u0005(בַּמִּדְבָּר ג, יב)\u0006 וַהֲרֵי פָּטְרוּ רֶחֶם בְּיִשְׂרָאֵל. אֵין יָדוּעַ אִם קֹדֶם שֶׁנִּתְגַיְּרָה אוֹ אַחַר שֶׁנִּתְגַיְּרָה, הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nהָעוֹבֶדֶת כּוֹכָבִים וְהַשִּׁפְחָה שֶׁיָּלְדוּ וְאַחַר כָּךְ נִתְגַּיְּרָה וְנִשְׁתַּחְרְרוּ, וְיָלְדוּ אַחַר כָּךְ, פָּטוּר, \u0010c17\u0011 שֶׁאֵין זֶה פֶּטֶר רֶחֶם.\nבֶּן ח' חֳדָשִׁים שֶׁהוֹצִיא רֹאשׁוֹ וְהוּא חַי, וְהֶחֱזִירוֹ וָמֵת, אוֹ בֶּן ט' שֶׁהוֹצִיא רֹאשׁוֹ, אֲפִלּוּ אַחַר שֶׁמֵּת, וְהֻחְזַר וְאַחַר כָּךְ יָצָא אָחִיו וְיָלְדָה וְלַד קַיָּמָא, אֵינוֹ פֶּטֶר רֶחֶם, שֶׁהֲרֵי נִפְטַר בְּרֹאשׁוֹ שֶׁל רִאשׁוֹן, \u0010y24\u0011 וּמִשֶּׁתֵּצֵא פַּדַּחְתּוֹ פּוֹטֵר הַבָּא אַחֲרָיו. \u0010c18\u0011 וְכֵן הַמַּפֶּלֶת כְּמִין בְּהֵמָה, חַיָּה וָעוֹף שֶׁחֲצִי פַּרְצוּף פְּנֵיהֶם דּוֹמֶה לְצוּרַת אָדָם, אוֹ סַנְדָּל אוֹ שִׁלְיָא אוֹ שָׁפִיר מְרֻקָּם \u0005(פי' חֲתִיכָה שֶׁל בָּשָׂר כְּצוּרַת סַנְדָּל וּפי' שִׁלְיָא, הַכִּיס שֶׁהָעֻבָּר מוּנָח בְּתוֹכוֹ וּפי' שַׁפִּיר מְרֻקָם, חֲתִיכָה שֶׁל בָּשָׂר וְיֵשׁ בָּהּ צוּרַת אָדָם, עָרוּךְ)\u0006 אוֹ שֶׁיָּצָא הַוָּלָד מְחֻתָּךְ אֵיבָרִים אֵיבָרִים, הַנּוֹלָד אַחַר כָּל אֶחָד מֵאֵלּוּ אֵינוֹ פֶּטֶר רֶחֶם \u0005(לְשׁוֹן טוּר)\u0006.\nבֶּן ח' חֳדָשִׁים שֶׁהוֹצִיא רֹאשׁוֹ מֵת, וְהַמַּפֶּלֶת שַׁפִּיר מָלֵא דָּם אוֹ מָלֵא מַיִם אוֹ מָלֵא גְּוָנִים, וְהַמַּפֶּלֶת כְּמִין דָּגִים וַחֲגָבִים, שְׁקָצִים וּרְמָשִׂים, וְהַמַּפֶּלֶת לְיוֹם אַרְבָּעִים, הַנּוֹלָד אַחַר כָּל אֵלּוּ בְּכוֹר לְפִדְיוֹן. \u0005וְכָל זְמַן שֶׁאֵין אֵיבָרָיו מְרֻקָּמִים, אֵין פּוֹטֵר הַבָּא אַחֲרָיו, וַאֲפִלּוּ בַּזְּמַן הַזֶּה סוֹמְכִין עַל זֶה (מהרי\"ק שֹׁרֶשׁ קמ\"ג)\u0006.\nיוֹצֵא דֹּפֶן וְהַנּוֹלָד אַחֲרָיו כְּדַרְכּוֹ, שְׁנֵיהֶם פְּטוּרִין. הָרִאשׁוֹן, מִפְּנֵי שֶׁלֹּא יָצָא מֵהָרֶחֶם; וְהַשֵּׁנִי, \u0010c19\u0011 מִפְּנֵי שֶׁקְּדָמוֹ אַחֵר.\nמִי שֶׁלֹּא בִּכְּרָה אִשְׁתּוֹ, וְיָלְדָה זָכָר וּנְקֵבָה, וְאֵין יָדוּעַ אֵיזֶה מֵהֶם יָצָא רִאשׁוֹן, \u0010y25\u0011 אֵין כָּאן לַכֹּהֵן כְּלוּם. יָלְדָה שְׁנֵי זְכָרִים, אַף עַל פִּי שֶׁאֵין יָדוּעַ אֵיזֶה מֵהֶם הַבְּכוֹר, \u0010y26\u0011 נוֹתֵן חֲמִשָּׁה סְלָעִים לַכֹּהֵן. מֵת אֶחָד מֵהֶם \u0010y27\u0011 בְּתוֹךְ ל' יוֹם, \u0010y28\u0011 פָּטוּר, דְּשֶׁמָּא הַבְּכוֹר מֵת וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nמֵת הָאָב קֹדֶם שֶׁפְּדָאָן, \u0010y29\u0011 בֵּין מֵת תּוֹךְ ל' בֵּין מֵת לְאַחַר ל', וְהַבָּנִים קַיָּמִים, נוֹתְנִין בֵּין שְׁנֵיהֶם ה' סְלָעִים, \u0010c20\u0011 אֲפִלּוּ חָלְקוּ כְּבַר הַנְּכָסִים.\nשְׁתֵּי נָשָׁיו שֶׁלֹּא בִּכְּרוּ, וְיָלְדוּ שְׁנֵי זְכָרִים, נוֹתֵן עֶשֶׂר סְלָעִים לַכֹּהֵן. מֵת אֶחָד מֵהֶם בְּתוֹךְ ל' יוֹם, אִם לְכֹהֵן אֶחָד נָתַן, יַחֲזִיר לוֹ ה' סְלָעִים; וְאִם לִשְׁנֵי כֹּהֲנִים נָתַן, אֵינוֹ יָכוֹל לְהוֹצִיא מֵהֶם, שֶׁהֲרֵי לֹא עִיֵּן פִּדְיוֹן זֶה עַל בֵּן זֶה, וְכָל אֶחָד יֹאמַר: אֲנִי תּוֹפֵס בִּשְׁבִיל הַחַי. \u0010y30\u0011 \u0010c21\u0011 יָלְדוּ זָכָר וּנְקֵבָה, אוֹ שְׁנֵי זְכָרִים וּנְקֵבָה, נוֹתֵן ה' סְלָעִים לַכֹּהֵן. וְאִם מֵת אֶחָד מֵהַזְּכָרִים תּוֹךְ ל' יוֹם, אֵינוֹ נוֹתֵן לַכֹּהֵן כְּלוּם. יָלְדוּ שְׁתֵּי נְקֵבוֹת וְזָכָר, אוֹ שְׁנֵי זְכָרִים וּשְׁתֵּי נְקֵבוֹת, וְאֵין יָדוּעַ אֵיזֶה נוֹלַד רִאשׁוֹן, אֵין כָּאן לַכֹּהֵן כְּלוּם, שֶׁאֲנִי אוֹמֵר: נְקֵבָה נוֹלְדָה תְּחִלָּה וְאַחֲרֶיהָ זָכָר \u0005(לְשׁוֹן טוּר)\u0006.\nשְׁתֵּי נָשָׁיו, אַחַת בִּכְּרָה וְאַחַת לֹא בִּכְּרָה, וְיָלְדוּ שְׁנֵי זְכָרִים וְנִתְעָרְבוּ, \u0010y31\u0011 נוֹתֵן ה' סְלָעִים לַכֹּהֵן, וְאִם מֵת אֶחָד מֵהֶם בְּתוֹךְ ל', אֵין כָּאן לַכֹּהֵן כְּלוּם. וְאִם מֵת הָאָב, \u0010y32\u0011 נוֹתְנִים בֵּין שְׁנֵיהֶם ה' סְלָעִים. זָכָר וּנְקֵבָה, אוֹ שְׁנֵי זְכָרִים וּנְקֵבָה, אֵין כָּאן לַכֹּהֵן כְּלוּם.\nשְׁתֵּי נָשִׁים שֶׁל שְׁנֵי אֲנָשִׁים שֶׁלֹּא בִּכְּרוּ, וְיָלְדוּ שְׁנֵי זְכָרִים וְנִתְעָרְבוּ, זֶה נוֹתֵן ה' סְלָעִים וְזֶה נוֹתֵן ה' סְלָעִים. נָתְנוּ, וְאַחַר כָּךְ מֵת אֶחָד מֵהַבָּנִים בְּתוֹךְ ל' יוֹם, אִם לִשְׁנֵי כֹּהֲנִים נָתְנוּ, \u0010y33\u0011 אֵינָם יְכוֹלִים לְהוֹצִיא מִיָּדָן. וְאִם לְכֹהֵן אֶחָד נָתְנוּ, \u0010y34\u0011 \u0010y35\u0011 \u0010y36\u0011 כּוֹתֵב אֶחָד מֵהֶם הַרְשָׁאָה לַחֲבֵרוֹ, וְיֵלֵךְ זֶה בַּהַרְשָׁאָה וְיוֹצִיא מֵהַכֹּהֵן ה' סְלָעִים. וְאִם יָלְדוּ זָכָר וּנְקֵבָה, וְאֵין יָדוּעַ אֵיזוֹ יָלְדָה זָכָר וְאֵיזוֹ יָלְדָה נְקֵבָה, אוֹ שֶׁיָּלְדוּ שְׁנֵי זְכָרִים וְנִתְעָרְבוּ, וּמֵת אֶחָד מֵהֶם, \u0010c22\u0011 הָאָבוֹת פְּטוּרִים וְהַבֵּן חַיָּב לִפְדּוֹת אֶת עַצְמוֹ.\nוְכֵן מְבַכֶּרֶת שֶׁלֹּא שָׁהֲתָה אַחַר בַּעֲלָהּ ג' חֳדָשִׁים, וְנִשְּׂאָה וְיָלְדָה זָכָר, סָפֵק בֶּן ט' לָרִאשׁוֹן אוֹ בֶּן ז' לָאַחֲרוֹן, הָאָבוֹת פְּטוּרִים, וְהַבֵּן חַיָּב לִפְדּוֹת אֶת עַצְמוֹ, וְאִם \u0010c23\u0011 יָלְדוּ שְׁתֵּי נְקֵבוֹת וְזָכָר, אוֹ שֵׁנִי זְכָרִים וּשְׁתֵּי נְקֵבוֹת, אֵין כָּאן לַכֹּהֵן כְּלוּם.\nשְׁתֵּי נָשִׁים שֶׁל שְׁנֵי אֲנָשִׁים, אַחַת בִּכְּרָה וְאַחַת לֹא בִּכְּרָה, וְיָלְדוּ שְׁנֵי זְכָרִים, זֶה שֶׁלֹּא בִּכְּרָה אִשְׁתּוֹ, נוֹתֵן ה' סְלָעִים לַכֹּהֵן. זָכָר וּנְקֵבָה \u0010c24\u0011 אוֹ שְׁנֵי זְכָרִים וּנְקֵבָה, אֵין כָּאן לַכֹּהֵן כְּלוּם.",["\u0003ב' זהובים כו'. \u0004כתוב בהגהת דרישה דאינו פחות מא' רייכ\"ש טאלי\"ר וב' שלישי רייכ\"ש טאלי\"ר כפי שהיה בזמניהם הרייכ\"ש טאלי\"ר בל\"ו גדו' פו' ע\"כ והיינו עכשיו ה' זהובי' פולני\"ש ובסמ\"ע סי' פ\"ח כתב וק\"ק דשמינית מפעני\"ק יחשב ממון לקידושין לדיינים ואפשר לומר שבימיהם היו הפירות והקנינים בזול ובעד פרוטה היו קונים הרבה פירות ולכך היה הפרוטה חשוב כממון ולפ\"ז בזמנינו דאין יכולים לקנות בפרוטה כי אם מעט מזער אין קידושי אשה סגי בפרוטה ולא בפדיון הבן בשני זהובים עכ\"ל ותמהני נהי דהל\"ל דאין קדושי אשה סגי בפרוטה מ\"מ אמאי לא תיסגי פדיון הבן בשני זהובים דהא ממון חשוב הוא מיהו בספר מע\"מ דף רס\"ח ע\"א האריך בזה דבעינן ג' רייכ\"ש טאלי\"ר וכ' שאף לדברי הרב אינו עכשיו פחות משני ר\"ט ע\"ש ולכתחלה טוב לצאת ידי כולם:","\u0003ושטרות. \u0004היינו שטר חוב שיש לו על אחרים שאם נתן אותן ש\"ח אין בנו פדוי כיון דאין גופן ממון:","\u0003ובנו אין פדוי. \u0004משום גזירה שמא יאמרו פודין בשטרות:","\u0003וע\"ל סי' דצ\"ד. \u0004ט\"ס הוא כי לא נזכר שם דבר מזה אלא צ\"ל רס\"ד כי שם ס\"א בהג\"ה נתבארו דינים אלו גבי מילה:","\u0003נתן כו' עד פדוי. \u0004הוא לשון הרמב\"ם ומ\"ש והוא שישוה הוא לשון המחבר ע\"פ מה שהביא בב\"י דבריו אבל באמת דבריו דחוקים מאד גם מה שתי' הב\"ק דחוק מאד גם דברי רבינו ירוחם בזה הם דחוקים אלא צ\"ל דדעת המחבר כדעת הלכות גדולות דף קל\"ט ע\"ב דגריס אמר רבא לעולם דלא שוי ורישא דאמר אבי הבן וסיפא דקבליה כהן כי הא דרב כהנא פריק בסודרא אמר לדידי שוה ה' סלעים אמר רב אשי ולא אמרן אלא גברא רבא כרב כהנא דידע למחולי אבל כ\"ע לא ש\"מ כל היכא דקבליה כהן בנו פדוי וכן הלכה עכ\"ל והשתא אתי שפיר הא דקתני בבריית' סתמא עגל זה בה' סלעים לפדיון בני דאלו לדעת הב\"י וסייעתו ה\"ל לפרושי דמיירי במה שדרכו להתייקר וזה ברור ודוק:","\u0003אבל לא יתן הוא לכהן על מנת שיחזיר כו'. \u0004כלומר שאינו מפרש דבריו שנותן לו ע\"מ להחזיר דבכה\"ג כיון דשעה א' גמר בלבו שיהא לשם מתנה יצא ידי נתינה וכמ\"ש המחבר בסוף הסעיף אלא מיירי שאינו גומר בדעתו כלל ליתנו לו לשם מתנה אלא מיד דעתו שנותנו לו על מנת להחזיר בכה\"ג לא יצא וכן מחלק המרדכי פ\"ק דקדושין בשם ראבי\"ה ומביאו ד\"מ וכה\"ג חלק בתשובת רשב\"א סי' קצ\"ח וכך היא דעת הרמב\"ם פ' י\"א מהל' בכורים דין ח' וגם העט\"ז נראה שהבין כן ע\"כ כתב במקום מ\"ש הרב ודעת הכהן היתה מתחלה כו' אע\"פ שדעת הכהן כו' וכן נראה מהדרישה שדעת הרב כן אבל אין נ\"ל דעת הרב כן אלא נראה שהוא מפרש דעת המחבר דברישא כיון שלא פירש דבריו שנותן ע\"מ להחזיר א\"כ דעת הכהן היה לקבלם במתנה גמורה ולא ע\"מ להחזיר והאב היה דעתו שיחזירם לו הלכך אינו פדוי אבל בסיפא כיון שפירש דבריו ואמר שנותן לו ע\"מ להחזיר א\"כ כיון שגם דעת הכהן כן יצא וכן פירש הב\"ח דעת התוס' והרא\"ש כן וגם דברי הרמב\"ם יש לפרש כן וכן משמע ממה שנרשם בש\"ע אמ\"ש הרב ודעת הכהן כו' כן משמע בב\"י ובב\"י לא נזכר כלום רק הביא דברי התוס' והרא\"ש הנ\"ל מיהו אינו מוכרח דעת התוספות והרא\"ש כן דמ\"ש וי\"ל דר' חנינא לא היה רוצה לזכות אלא במתנה גמורה ר\"ל שהיה עושה כן כדי שיתנו לו הכל במתנה גמורה אבל בדיעבד פדוי בכל ענין וכן הבין ר' ירוחם נתיב א' סוף ח\"ג דבריהם ומה דקאמר בש\"ס הלכך אין בנך פדוי היינו שר' חנינא א\"ל כן כדי שיתנו במתנה גמורה מ\"מ דעת הרב נ\"ל ברור כדפי' ודעת המחבר נ\"ל ברור כדפי' דס\"ל כראבי\"ה וכתשובת הרשב\"א ודוק:","\u0003והחזיר לו כו'. \u0004הוא לשון הרמב\"ם והוא על פי לשון א' ברש\"י אבל בלשון ב' פירש\"י אפי' לא החזיר אין בנו פדוי וכן משמע מתשובת רשב\"א שהבאתי בס\"ק שאח\"ז וכ\"כ הרא\"ש ומ\"ה מוכח לכאורה שדעת הרא\"ש כמ\"ש הב\"ח ודוק:","\u0003ודוקא שאמר כו'. \u0004דבכה\"ג גומר בלבו שעה א' לשם מתנה ומה שאמר ע\"מ כאומר מעכשיו דמי כלומר מעכשיו תהא נתונה לך מיהו תחזירהו לי אח\"כ אבל כשאומר הילך ה' סלעים בפדיון בני ואתה תחזירהו לי וכיוצא בזה שלא בע\"מ אין בנו פדוי ואפי' לא אמר מידי אלא שדעתו שיחזירם הכהן כולן או מקצתן ולולי זה לא היה נותנן לכהן אפי' לא החזיר לו הכהן כלום אין בנו פדוי דגרסינן בבכורות פרק יש בכור רב כהנא הוה רגיל כו' כ\"כ בתשובת רשב\"א ור\"ל כיון דלא גמר בלבו שעה אחת לשם מתנה אין בנו פדוי ועיין בא\"א סי' תרנ\"ח סעיף ד' וה':","\u0003בשעה שנותן כו'. \u0004כלומר בשעה שהאב מחזיק בידו חמשה סלעים והושיטן לכהן קודם שיוציא מידו ליד כהן מברך ואח\"כ נותנן לו כדי שיברך עובר לעשייתן כ\"כ ב\"י והאחרונים וכן משמע מדברי הטור והרב לקמן שכתבו בהדיא שנותן לו המעות כו':","\u0003ומברך שהחיינו כו'. \u0004משמע דמברך שהחיינו לעולם ועיין לעיל סי' רס\"ה סעיף ו':","\u0003ואין האב יכול לפדות ע\"י שליח כו'. \u0004זה תמוה דהא קי\"ל בכל התורה שלוחו של אדם כמותו וכן מבואר בדברי הר\"ן פ' כל שעה דיכול לפדות ע\"י שליח וגם בספר מע\"מ סוף דף רס\"ו תמה ע\"ז שהאריך וכתב דיכול לפדות ע\"י שליח וכן בספר צדה לדרך שחבר מהר\"ר יששכר בער על פירש\"י בחומש האריך שם בתשובה אחת שהסכימו עמו כמה גדולי הדור דיכול לפדות על ידי שליח וכתב דאף הריב\"ש לא קאמר אלא דלא מצינו שום חיוב מה\"ת על אדם אחר שיעשה עצמו שליח במקום האב לפדותו אם אין האב רוצה לפדותו או אם מת האב ואפי' ב\"ד אינם מחויבים מה\"ת לעשות עצמם שלוחים במקום האב לפדותו אבל ודאי שהאב יכול לפדות ע\"י שליח וכן הב\"ד יכולים לפדותו בלא האב אם עבר האב ולא פדאו או אם מת האב קודם שנפדה וכל שכן שאבי אביו יכול לפדותו בכה\"ג עכ\"ד וע\"ש שהאריך וכ\"פ מהרש\"ל בשם מהר\"מ מ\"ץ והובא בדרישה סעיף י\"ד דיכול לפדותו ע\"י שליח. ובספר מע\"מ כתב שם דאין הב\"ד יכולים לפדותו כשמת האב כשהוא קטן דכל עוד שהוא קטן אינו בר חיובא כו' ואין דבריו מוכרחים וע\"ל ס\"ק כ':","\u0003אין פודין אותו בשבת. \u0004משום דהוי כמקח וממכר ומטעם זה גם בי\"ט אין פודין אותו וכן הוא בתשובת הריב\"ש סי' קנ\"ז. נראה דפודין נמי בלילה וכן משמע בפ\"ק דקדושין דף כ\"ט סוף ע\"א וברש\"י ותוספות שם מיהו נוהגין לפדות ביום מיהו היכא דחל יום ל\"א ביום תענית צבור יש לראות אם הגיע הבן לכ\"ט י\"ב תשצ\"ג קודם יום התענית שהוא יום ל' יש לפדותו ביום ל' אחר כ\"ט י\"ב תשצ\"ג כדלקמן סוף ס\"ק י\"ט (ואפשר לומר דמשום סעודה לחוד לא מקדמינן לפדות ביום ל') ואם לאו אז יש לפדותו בליל ל\"א של יום התענית אבל אין לפדותו ביום התענית ולעשות סעודה בליל שאחר התענית דליכא פרסומי כה\"ג וכמו שכתב מהרא\"י בת\"ה סי' רס\"ט גבי חל יום ל\"א בשבת דאם יפדוהו בערב שבת שלא יחול הפדיון עד לאחר שלשים דהיאך יעשו עם הסעודה לפרסם המצוה בעוד שאין בנו פדוי ואם יעשו הסעודה בשבת שכבר הוא פדוי מאן נימא לן דאיכא פרסומא כה\"ג שאין רואים הפדיון בשעת הסעודה ע\"כ מיהו שמעתי שנוהגין לפדות ביום התענית ולעשות הסעודה בלילה שאחר תענית ויש לחלק בהך דמהרא\"י) וק\"ל:","בתשובת ר' אליה ן' חיים סי' ע\"ט על תינוק בכור (שמל) [שחלה] ולא נתרפא עד יום ל\"א נראה דאע\"ג דמצות פדיון הבן לעשות בעיקר זמנה יש להקדים מצות המילה משום דהמילה היא אות ההכנסת ברית ואלמלא קבלת הברית אין חיוב למצות פדיון כלל ונותן לכהן ה' סלעים בתוך ל' שיהא פדוי לאחר ל' יום ולענין הברכה לא יברך קודם ל' כדכתב מהרא\"י בכתביו סי' ר\"ל בדין דהגיע יום ל\"א בשבת וז\"ל ותו דקורא אני תגר על הברכה דיברך אבי הבן בע\"ש דאכתי לאמטא זמן חיובא כו' עכ\"ד ולא נהירא דא\"כ איך יברך לאחר ל' כיון דמיד בהכנסת יום ל\"א ממילא הבן פדוי וכבר נעשה מצותו וכן כתב מהרא\"י גופיה בת\"ה סי' רס\"ט אהך דין דהגיע יום ל\"א בשבת דבע\"ש לא יברך כיון דאכתי לא מטי זמן חיובא ובשבת אין ראוי לברך דלאו מידי קא עביד השתא וממילא הבן פדוי בכניסת שבת שהוא יום ל\"א עכ\"ל ואע\"ג די\"ל דהכא כיון דמצוה עיקר זמנה ראוי לעשות כן מ\"מ נ\"ל דאין לחלק דכיון דכבר נעשה מצותו א\"כ אין לברך אח\"כ כמו שהעליתי לעיל סי' י\"ט ס\"ק ג' דכל המצות מברך עליהן עובר לעשייתן ואם לא בירך קודם לכן לא יברך אח\"כ וגם לא מסתבר כן ליתן המעות קודם ל' מכמה טעמים הלכך יש למולו בתחלה ביום ל\"א ואח\"כ לפדותו ולברך:","\u0003דאין לעשות כו'. \u0004משום דאין מערבין שמחה בשמחה:","\u0003ויש מתירין כו'. \u0004וכן כתב המחבר בא\"ח סי' תקמ\"ו סעיף ד':","\u0003וכן עיקר. \u0004וכן נוהגין דהא אין מברכין שהשמחה במעונו כן כתב העט\"ז ואין זה ראיה דהא סעודת אירוסין אסור לעשות בחולו של מועד כמו שכתב הט\"ו בא\"ח ר\"ס תקמ\"ו אע\"ג דאין מברכין שהשמחה במעונו אלא הטעם מבואר בדברי התוס' שם דלא אסור לערב שמחה בשמחה אלא בשמחת נשואין לבד ול\"ד שמחת נשואין קאמרי אלא ה\"ה סעודת אירוסין נמי דשייך בה נשואין:","\u0003אם נעשה טרפה. \u0004נראה דהיינו בודאי טריפות ובכה\"ג אפי' חי אח\"כ זמן ארוך פטור מפדיון ולא אמרי' טרפה אינה חיה (אלא) בודאי טרפה אבל בספק טרפה פטור מפדיון דהמע\"ה מיהו אם חי אחר כן יב\"ח חייב דיצא מידי ספק טרפה כיון דחי יב\"ח וכדלעיל סי' נ\"ה ס\"ק מ\"ח כנ\"ל:","\u0003אבל לא יברך שהחיינו. \u0004ולא דמי למה שנתבאר בא\"ח סי' רכ\"ג ס\"ב דאע\"ג דמת אביו מברך שהחיינו על הירושה דשאני התם כיון דזוכה לירושה משא\"כ הכא:","\u0003אין בנו פדוי. \u0004אפי' המעות עדיין בעין כיון דנפדה בתוך ל':","\u0003וי\"א דאם כו'. \u0004ולא דמי לקידושין שנתבאר באה\"ע ר\"ס מ' דמקודשת אפי' נתאכלו המעות דהתם בידו לקדשה מעכשיו אבל הכא אין בידו לפדותו מעכשיו ש\"ס דבכורות דף מ\"ט ע\"א ובתשובת מהרש\"ל סי' ז' האריך להוכיח מתוך הסמ\"ג עשין קמ\"ד דליכא מאן דפליג דאם התנה שלא יהא פדוי רק אחר ל' יום דפדוי אפי' נתאכלו המעות ומה שכתבו התוספות פרק מרובה (בבא קמא דף ע') סוף ע\"א ובא\"ז דקי\"ל כשמואל דאם נתאכלו המעות אינו פדוי היינו כשפדה סתם תוך ל' יום דאז יש חילוק בין נתאכלו המעות או לא ודלא כת\"ה סי' רס\"ט שכ' שהתוס' והא\"ז חולקים עכ\"ד והם דחוקים מאד כמובן לכל מעיין שם ועוד דא\"כ הא דפסק סמ\"ג מעיקרא דאינו פדוי הוי ליה לפרושי דבנתאכלו מיירי ועוד דדוחק גדול לחלק בסתם בין נתאכלו או לא דהא כי נימא דסתם הוי כאומר שלא יהא פדוי אלא לאחר ל' יום דמסתמא מכוין לפדות כדין תורה א\"כ אפי' נתאכלו נמי הוי פדוי אלא נראה דהסמ\"ג לא גריס בש\"ס דהלכתא כשמואל בדיני וכ\"כ מהרי\"ק שורש צ\"ו ועל השנות הפסק כו' חוששני קצת לט\"ס כו' ע\"ש וס\"ל דוקא לקמן בהך תנא דתני קמיה דרב יודא פסיק ש\"ס הלכתא כשמואל מדמשבש ר' יודא להאי תנא לאוקמא כשמואל וס\"ל כיון דהאי תנא הוי תנא סתמא קמיה דרב יודא ורב יודא משבש ליה ומאי משבש ליה הא איהו קאמר בסתם וסתם כלאחר ל' דמי אלא ודאי קים ליה לרב יודא דבהא נמי פליגי רב ושמואל דהפודה בנו סתם אי דעתו מעכשיו ואין בנו פדוי אפי' לא נתאכלו המעות ואי דעתו כלאחר ל' ופדוי למר בלא נתאכלו ולמר אפי' בנתאכלו ולכך פסק הסמ\"ג מתחלה סתם הפודה בנו תוך ל' יום אין בנו פדוי ולא חילק בין נתאכלו או לא משום דסתמא דעתיה שיהא פדוי מעכשיו וכרב יודא אליבא דשמואל ופסק ש\"ס הלכתא הכי ואח\"כ בפירש שלא יהא פדוי אלא לאחר ל' בפלוגתא דרב ושמואל בנתאכלו פסק כרב באיסורא כיון דלא פסק ש\"ס הלכתא הכי ומעתה מ\"ש הת\"ה סי' רס\"ט שהטור והא\"ז חולקים יפה כוון דלא מוכח מהסמ\"ג מידי והשתא ליכא למימר דהתוס' בסתם מיירי כיון דבסתם אינו פדוי כשנתאכלו אלא כשלא נתאכלו משום דדינו כאלו פירש שלא יהא פדוי אלא לאחר ל' יום וכשמואל לשיטת הסמ\"ג א\"כ גם באומר שלא יהא פדוי עד לאחר ל' יום אינו פדוי כשנתאכלו וזה ברור ודוק ואפשר דכל הפוסקים מודים בזה לענין דינא דהפודה בסתם דעתיה במעכשיו דהסברא מכרעת לזה אלא שהם לא דברו מזה ומ\"ש רא\"ש פרק יש בכור ומ\"ש בה\"ג בסתם מי שפדה את בנו בתוך ל' יום אין בנו פדוי צריך להעמיד דבריו בדא\"ל מעכשיו עכ\"ל ולא משני דמיירי בשפדה בסתם תוך ל' אה\"נ אלא לפי דלא אסיק אדעתיה דרב יודא מיירי בסתם וכדפי' לדעת הסמ\"ג אלא מפרש שם דברי רב יודא כדקאמר בש\"ס מעיקרא ע\"ש לכך כתב דמיירי במעכשיו דלא כמהרש\"ל שכתב שם בריש התשובה ומדמוקי לה\"ג בא\"ל מעכשיו ולא ניחא ליה לאוקמא בסתם שלא אמר ליה מידי לא מעכשיו ולא לאחר ל' יום בפרט מאחר שכתב לשם בסתם אלמא דס\"ל להרא\"ש שאין חילוק בין סתם לפירש דודאי אמדינן דעתיה שלא היה אלא שיהא פדוי לאחר ל' יום אף דלאו כ\"ע דיני גמירי מ\"מ דעתו היה שיהא פדוי כראוי באיזה יום שראוי לפדות עכ\"ל דמ\"ש הרא\"ש ומ\"ש בה\"ג בסתם כו' אין ר\"ל שכתב בה\"ג לשם בסתם אלא בבה\"ג לא כתב אלא סתמא הפודה בנו תוך ל' יום אינו פדוי ולא פירש אי מיירי שפדה תוך ל' יום שלא יהא נפדה עד אחר ל' ופסק כשמואל או מיירי דאמר מעכשיו וכרב אבל אה\"נ דאפשר דבסתם הוי כמעכשיו ולכך נקט בה\"ג סתמא דאינו פדוי ולא פירש דאמר מעכשיו משום דסתמא מעכשיו קאמר והרא\"ש לא קאמר דצ\"ל דמיירי באמר מעכשיו אלא לאפוקי אמר שלא יהא פדוי עד אחר ל' ומעתה לפ\"ז מ\"ש מהרש\"ל דהיכא דחל יום פדיון ביום שבת יש לפדות ביום ו' ולהתנות שלא יהא פדוי עד אחר ל' דאז אפי' נתאכלו פדוי לכ\"ע ליתא וכמו שנתבאר דלדעת התוס' והא\"ז אינו פדוי בנתאכלו ויש לחוש שמא יתאכלו וכמ\"ש בת\"ה שם וכן בכל נוסחאות הש\"ס שבידינו היום פסק ש\"ס הלכתא כשמואל דבנתאכלו אינו פדוי (וכן הוא בספר יראים סי' שנ\"ג) וגם הב\"ח כתב ודלא כמ\"ש מהרש\"ל בתשו' סי' ז' שכתב דפודין אותו ביום ו' שהוא יום ל' שלו עכ\"ל ולא ביאר טעם השגתו ואולי כוון למ\"ש:","כתב הב\"ח דיש לחלק בין הגיע הבן ביום ו' בהשכמה (לאו דוקא דה\"ה כל יום ו') לבן חדש שהוא כ\"ט י\"ב תשצ\"ג אז יפדהו ביום ו' לאחר שכבר הוא מבן חדש ולמעלה ואם לא הגיע מבן חדש ומעלה עד הגיע השבת אז פודין אותו ביום א' והארכתי בתשו' בס\"ד בראיות ברורות שכן פסק בספר יראים ע\"כ ודבריו נכונים שכן מבואר בספר יראים סי' שנ\"ג וממאי דאיתא בש\"ס ופוסקים סתם ל' יום אין ראיה דהכי אשכחן טובי בש\"ס ופוסקים ל' יום שהוא חדש כדלעיל סי' קפ\"ט ס\"ק ל' וגם מדברי מהרא\"י והמחבר יש לפרש כן אלא שאין נוהגין לפדות עד יום ל\"א והיינו היכא דאפשר אבל היכא דכלו כ\"ט י\"ב תשצ\"ג קודם השבת יש לפדותו ביום ו' ומהרא\"י והמחבר דקאמרי אם חל יום ל\"א בשבת היינו סוף כ\"ט י\"ב תשצ\"ג ודו\"ק:","\u0003ויש מי שכתב כו'. \u0004הל' מגומגם די\"ל גם המחבר מודה בהא מיהו לפי מ\"ש לעיל ס\"ק י\"א א\"צ לטס של כסף וגם לרוב פעמים הטס של כסף בא לידי איבוד ע\"כ טוב יותר לפדותו הב\"ד כשהוא קטן:","\u0003אע\"פ שקדם כו'. \u0004דמלוה הכתובה בתורה לאו ככתובה בשטר דמי ועי' בח\"מ סי' ק\"ד סי\"ג:","\u0003ובן הכהנת חייב בפדיון. \u0004לכשיגדיל דהכהנת אינה חייבת בפדיונו דאין האשה חייבת לפדות את בנה כדלעיל סעיף ב' והישראל בעל הכהנת פשיטא דאינו חייב בפדיונו שהרי אינו אביו שנתעברה מן העובד כוכבים ולפ\"ז אם לא נתעברה מן העובד כוכבים רק שנתחללה בביאת עובד כוכבים ואח\"כ נתעברה מישראל חייב בפדיונו:","\u0003הבן פטור מן הפדיון. \u0004אף לכשיגדל דשמא היא מכזבת והישראל אומר אמת וה\"ל הכהן המוציא מחבירו עליו הראיה עכ\"ל העט\"ז וטעות הוא דאדרבה כשהישראל אומר אמת הבן חייב לפי שנתחללה בביאת עובד כוכבים וצ\"ל דשמא הוא מכזב והיא אומרת אמת ומ\"מ משמע לכאורה לפי טעם זה דאפילו באשתו נשואה או ארוסה דינא הכי אבל בתרומת הדשן דממנו מקור דין זה לא משמע הכי שכתב דלא שדינן לה אבתריה בשום מלתא כלל אבל מ\"מ אף לדידיה לא מהמנינן אלא להך מלתא דלאו דידיה הוא אבל להאמין לכל דבריו ולומר מעובד כוכבים מיעברה כדקאמר לה איהו ודאי לא אמרינן ומשום דרבי יודא דנאמן על בן בין הבנים לומר ממזר הוא נמי לא מהימן דנראה דההוא מהימנותא ליתא אלא בבנו שנולד מאשתו בהא האמינתו תורה שיכירנו לאחרים הואיל ומאשתו ומארוסתו נולד ומסתמא דמלתא דלשדייה בתריה וכשהוא אומר דלא מיניה הוא וממזר הוא מהימן אבל הכא דלית ליה בה לא נשואין ולא קדושין היאך תיסק אדעתין דליהוי מהימן במידי על בן הנולד ממנה עכ\"ל ומדלא מחלק דשאני בהך דר' יודא דאינה מכחישתו נראה דמשמע ליה דכיון דנאמן לומר על בנו בין הבנים ממזר הוא נחמן בכל ענין וא\"כ אפי' מכחישתו כיון דנאמן לומר דלאו דידיה הוא ממילא ממזר הוא דהרי היא אשת איש ואף על גב דמסיים שם בסוף בתשובה וכל שכן לענין ה' סלעים דאית להאי ברא חזקת ממונא כו' מכל מקום משמע מדבריו דהאי וכ\"ש כו' אינו אלא סניף לפטרו מפדיון אבל לא שיחלק אפי' באשתו בין מכחישתו או לא ולפי זה באשתו כיון דנאמן לומר דלאו דידיה הוא אפי' מכחישתו ממילא ממזר הוא ונתחללה בביאת הבועלה והבן חייב בפדיון לכשיגדל ועדיין צ\"ע לדינא:","\u0003בן חלל. \u0004עיין בא\"ע סי' ו' ז' איזו נקרא חלל:","\u0003ומשתצא פדחתו כו'. \u0004עיין לעיל סי' י\"ד ס\"ק א' בזה:","\u0003אין כאן לכהן כלום. \u0004דהמע\"ה:","\u0003נותן ה' סלעים לכהן. \u0004דהא ממה נפשך אחד מהם בכור:","\u0003בתוך ל'. \u0004דאלו לאחר ל' כבר נתחייב ואע\"פ שמת צריך לפדותו כדלעיל סעיף י\"ב:","\u0003פטור. \u0004מלפדות גם השני החי:","\u0003בין מת כו'. \u0004ודעת הטור דאם מת תוך ל' יום אפי' לא חלקו פטורים ואם מת לאחר ל' אפי' לאחר שחלקו חייבים (כלומר ליתן ה' סלעים בין שניהם) וכן דעת הרמב\"ם גופיה בפי' המשנה ותימה שהרב השמיט סברא זו ובפרט שכ\"נ עיקר בש\"ס וכ\"פ הב\"ח דבתוך ל' פטורים אפי' לא חלקו דהמע\"ה:","\u0003ילדו זכר ונקבה. \u0004דהיינו שאחת ילדה זכר ואחת נקבה ונתערבו שלא נודע איזה מהן ילדה זכר הרי מ\"מ חייב ה' סלעים לכהן דהא שניהם לידה הראשונה היא להן וכן כשילדו ב' זכרים ונקבה אחת ונתערבו אין חייב אלא ה' סלעים דהא נוכל לומר זו ילדה ב' זכרים וזאת ילדה נקבה ואין כאן אלא בכור א' אע\"ג דיכול להיות ג\"כ שזו ילדה זכר וזו ילדה ג\"כ זכר תחלה ואח\"כ נקבה והרי כאן ב' בכורים מ\"מ המע\"ה הלכך כשמת א' מהזכרים תוך ל' אינו נותן לכהן כלום שיכול האב לומר הבכור מת:","\u0003נותן ה' סלעים לכהן. \u0004דהא ודאי א' מהן בכור:","\u0003נותנים בין שניהם כו'. \u0004סתם כדבריו לעיל סעיף כ\"ו אבל לפמ\"ש שם אם מת האב תוך ל' פטורים אלא כשמת אחר ל' נותנין בין שניהם ה' סלעים וכ\"כ ב\"י והאחרונים:","\u0003אינם יכולים להוציא כו'. \u0004שכל אחד יאמר של חי קבלתי והמוציא מחבירו עליו הראיה:","\u0003כותב הרשאה כו'. \u0004ה\"ה בלא כתיבת הרשאה כששניהם באים לפנינו ומצוים לתת לאחד וא\"צ הרשאה אלא אם ירצה הא' להוציא מידו בפני עצמו) וכתב בספר מעדני מלך סוף דף רס\"ה דסברא מעליתא היא:"],["\u0003שני זהובים רייני\"ש כו'. \u0004בפרישה הביא בשם רש\"ל וז\"ל וצריך לתת לכהן כסף צרוף מזוקק משקל אלף ט' מאות ועשרים שעורים ואני שקלתי פעמים בשני זמנים ובשני מיני שעורים לעולם היה בהם ה' לו\"ט וקווינ\"ט. מה\"ר מנחם מ\"ץ. עוד שמעתי שיש בחידושי מהר\"ם מריזבור\"ק שיעור פדיון חמשה לו\"ט ורביעית לו\"ט עכ\"ל. ובכתבי מהרא\"י כתב שיש קבלה בידינו שהוא שני זהובים רייני\"ש כו' וקרובים דבריהם להיות שוים שהם חמשה אוקיאות כסף צרוף כמו שכתבו הגאונים עכ\"ל. ומ\"ש רמ\"א שהם שני זהובים פולניש היינו לפי זמנו שהיו זהובי' פולניש כמו רייני\"ש אבל לא עכשיו וזה פשוט וכל הרוצה לעשות על צד המובחר יתן שוה משקל ה' לו\"ט וקווינ\"ט במשקל של מדינות קיסר ולא במשקל פולין שלפי מה ששקלנו במשקל קיסר השעורים סך הנ\"ל הוא מכוון לשיעור ה' לו\"ט וקווינ\"ט וקצת אפי' יותר ואלו בלו\"ט של פולין יהיה שיעור גדול כי זקוק של מדינות קיסר שהיא ט\"ז לו\"ט הם גדולים הרבה משל פולין באופן שי\"א לו\"ט וקווינ\"ט של קיסר הם זקוק במדינות פולין:","\u0003ושטרות. \u0004פי' שלא יתן לכהן שט\"ח שיש לו על אחר וזה אתמעט מקרא בגמרא:","\u0003חייב ליתנם לו. \u0004דמן התורה פדוי במה שמחייב עצמו בשטר לכהן בשביל הפדיון אלא דחכמים אמרו שלא יהא פדוי גזירה שמא יאמרו פודין בשטרות שיתן לכהן שט\"ח על האחרים:","\u0003וע\"ל סי' רס\"ד. \u0004כן צ\"ל דגבי מילה כתב ג\"כ דינים אלו:","\u0003נתן לו כלי כו'. \u0004סעיף זה הוא ל' הרמב\"ם עד בנו פדוי והש\"ע הוסיף וכתב והוא שישוה כו' לתרץ קושית הר\"ן על הרמב\"ם הביאם ב\"י מסוגיא דפ\"ק דקדושין (דף ח') דתניא עגל זה לפדיון בני עד להתייקר בו אם לאו עכ\"ל וכתב ב\"י דנראה לו דסבר הרמב\"ם דכל השוה ה' סלעים לשום אדם אע\"פ שלכהן הזה אינו שוה ה' סלעים יכול לקבלו בה' סלעים והא דאמר רב אשי לא אמרן אלא כגון רב כהנא כו' היינו לומר דאי לשום אדם אין שוה ה' סלעים לא מהני מאי דאמר רב כהנא לדידי שוה לי ה' סלעים והכי פירושו לא אמרן אלא כגון סודרא דלרב כהנא ודכוותיה שוה לפעמים ה' סלעים אע\"פ שלכל אדם אינו שוה כל כך יכול רב כהנא לומר לדידיה שוה ה' סלעים אבל כ\"ע כלומר מלתא דלכ\"ע אינו שוה ה' סלעים לאו כל כמיניה וזה שכתב הרמב\"ם כל שאינו שוה בשוק כלומר אבל לקצת בני אדם שוה ה' סלעים וקבלו הכהן בה' עכ\"ל וזהו שכתב כאן דאין שוה ה' סלעים לשום אדם ותמהתי על פה קדוש דמאור עינינו יאמר כן וכ\"ש לקבוע הלכה כן דלפי פירושו קשה למה ליה לתלמודא לומר דהכהן קבלה עלויה הא אפי' בשותק סגי כיון דעל כל פנים שוה לשום אדם ואין לומר דהגמ' מוכיח דצריכה אמירה כן מדאמר רב כהנא לדידי שוה ה' סלעים הא ע\"כ רב כהנא לא על עצמו אמר כן לפי פירושו של הב\"י דהא אין צריכין שיהא שוה לו ה' סלעים אלא אפי' אם אין שוה לו רק לאחרים סגי אלא ע\"כ דה\"ק לפי פירושו לדידי וכיוצא בו דהיינו גברא רבא שוה ה' סלעים א\"כ כל שידוע לנו שהוא שוה לשאר אדם בחוץ אין צריכין אמירה כלל ושום קבלה ואין ראיה מדרב כהנא שהוא לא בא אלא לגלות שדבר זה הוא לשאר אדם כמוהו ומלבד הלחץ הגדול זו הדחק שלפי פירושו במ\"ש בגמ' אבל כ\"ע דהיינו אבל אם לכ\"ע אינו שוה כו' זו דרך דרש ודחוקה היא מדרך הפשוטי הסלולה לכל ומי הכניסו לרמב\"ם לפרש כן הפשט ולזוז מן הפשוטי שיהיה שוה לו דוקא והיותר קשה לפי פירושו תירץ דברי הרמב\"ם דהיינו במה שכתב הרמב\"ם שאינו שוה בשוק נתכוין אבל שלא בשוק שוה לשום אדם ומה נעשה בדברי רבינו הטור שלא כתב כן אלא כתב ואם נתן לו חפץ בה' סלעים והכהן קבלו בכך בנו פדוי אפי' אינו שוה כל כך עכ\"ל משמע לשום אדם אינו שוה כ\"כ. ומו\"ח ז\"ל פי' דברי הרמב\"ם וטור דסבירא להו דכשהאב אומר הילך חפץ זה כו' וע\"ש ודרכו יותר דחוקה מדרך הבית יוסף דא\"כ לא היה כל משא ומתן הגמ' בזה לצורך כלל אלא דעל מה שהקשה המקשן אם אינו שוה ה' סלעים אמאי בנו פדוי כשאומר עגל זה בחמשה סלעים היה לו לומר דמש\"ה פדוי כיון שאמר האב בהדיא חמשה סלעים ולרב כהנא לא דמי שהוא היה צריך לומר לדידי שוה לי כיון שהאב לא אמר כלום משא\"כ אם האב אומר בפירוש ותו דלפי דבריו יש חילוק בין הך דעגל בחמשה סלעים ובין דרב כהנא ואנו רואין שהגמ' מייתי עלה ההיא דרב כהנא גם החילוק שבין סודר לשאר חפצים שכתב לא ניתן להכתב לפענ\"ד. ונלע\"ד דהרמב\"ם וטור הוקשה להם על מ\"ש בגמ' וכגון שקבלה הכהן היה לו לומר וחזי ליה לדידיה חמשה סלעים דהא עיקר התירוץ הוא מחמת זה כדמסיק מזה דרב כהנא וכיון שרוצה התרצן לנקוט ההיתר היה לו לנקוט כמות שהוא אלא ע\"כ דה\"ק שקבלה הכהן בה' סלעים אע\"פ שלא שוה כן מ\"מ אמר שהוא מקבלו בה' סלעים ומייתי ראיה מדרב כהנא שאמר לדידי חזי ה' סלעים וזה גרע מאומר שמקבלו אפי' אינו שוה כיון שאומר שמקבלו בשביל ששוה בעיניו על כן צריך שיהיה ודאי שוה כן לדידיה כדאמר רב אשי והא דמייתי ראיה מדרב כהנא כי היכי דהתם אע\"פ שאינו שוה ה' סלעים מ\"מ פדוי כיון ששוה לו כן ה\"נ בקבלו בפירוש אע\"פ שאינו שוה דמועיל כן נ\"ל בדעתם:","\u0003אבל לא יתן הוא לכהן על מנת כו'. \u0004פי' שלא יהיה בדעתו כן ואינו אומרו בפירוש דכל שאומרו בפירוש מבואר בסיפא דמהני אבל כאן אמר שלא יהיה במחשבתו כן דאם יחשוב כן והכהן חושב שלא להחזיר נמצא אין הדעות שוות בשעת נתינה ואין כאן פדיון אם יחזיר לו אח\"כ וכשלא יחזיר לו הוי פדוי אח\"כ בשעה שמעכב לעצמו דאז הדעות שוות בין הנותן והכהן משא\"כ כשמחזיר לו אין פדיון לא בשעת נתינה ולא אח\"כ אבל אם היה גם הכהן חושב שיחזיר לו אז דעותיהם שוות לחזרה והוה פדוי אף אם יחזיר לו אח\"כ והוה כאומר בפירוש על מנת שתחזיר לי וכן המנהג בכל יום שהאב מניח דמי הפדיון בסך הרבה והוא חושב שיחזיר לו והכהן נמי חושב כן ומחזיר לו אח\"כ לפעמים הכל או מחזיק לעצמו איזה סך קטן ובזה נתבארו ג\"כ דברי רמ\"א בסעיף זה שכתב ודעת הכהן היתה כו' ובפרישה כתוב וז\"ל דעת המחבר היא דאם נראה מה נותן כו' עד על דעת כן פדוי עכ\"ל ודבריו תמוהים מאד לעיני הרואה במה שתלה הדבר היאך חושב הכהן להחזיר אם בדרך על מנת או בדרך אחר ובאמת אין חילוק כלל בזה אלא בכל גווני שדעת שניהם שוה הוי פדוי אבל אם האב חושב שיחזיר והכהן חושב שלא יחזיר כלל לא הוי פדוי אם יחזיר וכמ\"ש בסמוך:","\u0003חמשה סלעים ותחזירם לי כו'. \u0004דבלשון זה משמע שיש כאן חזרה דמתחלה אומר הא לך חמשה סלעים משמע מתנה גמורה לעולם ואח\"כ אומר ותחזירם לי נמצא שחוזר מדבריו הראשונים ומבטלם וכהאי גוונא מצינו בפ' מי שאחזו (גיטין דף ע\"ב) בפירוש רש\"י במתני' באומר מהיום ולאחר מיתה משא\"כ באומר ע\"מ שתחזיר אין כאן חזרה אלא מפרש דבריו דהאומר ע\"מ כאומר מעכשיו דמי נמצא דהמתנה מעכשיו אינה חלה אלא בתנאי זה מה שאין כן באומר ותחזירהו לא הוה מעכשיו וביטל האחרון את הראשון דאמרי' תפוס לשון אחרון כדאיתא סוף פ' השואל כנ\"ל טעם דבר זה ובפרישה כתב הטעם דאם אמר ליה ותחזיר משמע מיד תחזיר ולא הוה מתנה משא\"כ כשנותנו על מנת דהוה כא\"ל שיהיו קנוים לך מעכשיו אלא שתחזירם לי לאחר זמן עכ\"ל ואין דבריו מובנים לי דלמה נאמר שכשאומר ותחזירם דהכוונה שתיכף יחזיר יותר מאומר על מנת איפכא מסתברא וכמו שכתבתי הדבר ברור:","\u0003על פדיון. \u0004הטעם שברכה זו בעל לפי שאינה דומה לאותן מצות שהן בלמ\"ד שהרי אפשר להעשות מצוה זו ע\"י הבן כשיגדל ואז אי אפשר לעשותו אלא ע\"י עצמו. ב\"י בשם ריב\"ש:","\u0003ובהדי שנותן לו המעות מברך כו'. \u0004פי' ולא אחר כך דבעינן ברכה עובר לעשיית המצוה ולא כמו שקצת נוהגים שכבר הניח לפני הכהן המעות ואח\"כ מברך:","\u0003ואם יין בעיר כו'. \u0004ובעיר שאין בה יין מברכין על שכר שהכל ונראה דבאותן מקומות שאין יין צריך לעשות הפדיון קודם ברכת המוציא על הסעודה דאלו בתוך הסעודה אין מברכין על השכר משא\"כ במקום שיש יין עושין אחר ברכת המוציא:","\u0003ואין האב יכול לפדות ע\"י שליח. \u0004וגם ב\"ד אין פודין אותו בלא האב זו מדברי שאלה שנשאל ריב\"ש סי' קל\"א דהיינו שהשואל שאלו וזה לשונו למה כתב הרמב\"ם בנוסח פדיון הבן על פדיון כו' כיון דמצות פדיון עיקרה על האב רמיא אלא דמדיוקא פדה תפדה ילפינן פודה את עצמו אבל ע\"י שליח או ע\"י ב\"ד לית לן עכ\"ל ובתשובה שהשיב ריב\"ש על זה לא הוזכר שום דבר מזה רק שהשיב לו תירוץ אחר על נוסח על ולא לפדות בלמ\"ד ולמד רמ\"א מזה דכיון דלא סתר הריב\"ש דבר זה ש\"מ דניחא ליה בכך ובאמת הוא תמוה דהא מצינו בפ' השואל ובנדרים (דף ע\"ב) מצינו בכל התורה כולה שלוחו של אדם כמותו ובמה יתמעט כאן שליח ששלחו האב לפדות ונתן לו ממון לזה מה שמגיע לכהן והנה כבר התעורר על זה בספר א' נדפס מחדש ושמו צדה לדרך וכתוב בו בפרשת בא איך שהוא ז\"ל תמה על זה שאוסר כאן ע\"י שליח מכח קושיא זאת ומתוך כך נחית לפסוק שם הלכה למעשה בכור שמת אביו קודם ל' יום דיש כח ביד אבי אביו או ביד הב\"ד לפדותו והאריך שם בראיות וכתב לבסוף שהעידו שכן פסק מהר\"ר ליב מפראג ז\"ל והנה כי נכון הדבר לכל מורה לחפש בדעתו בגמ' ופוסקים אחר עיקרא דמלתא ע\"כ אמרתי בזה אשר לא אשא פני איש והנלע\"ד אחר העיון אזכיר בזה דמה שפסק שיכול האב לפדות ע\"י שליח יפה כתב שכ\"כ הר\"ן בפ\"ק דפסחים וז\"ל ויש מצוה אחרת שאע\"פ שמוטלת עליו אפשר להפטר ממנה ע\"י אחר כביעור חמץ ומילה ופדיון הבן ודומיהן עכ\"ל הביאו בספר הנ\"ל וכתב עוד בשם רש\"ל בשם ספר מעיל צדק וז\"ל אם האב אינו בעיר נראה דגם אדם אחר יכול לפדות הבכור דשלוחו של אדם כמותו וגם יכול לזכות ע\"י אחר לכהן דזכין לאדם שלא בפניו וכתב רש\"ל עצמו על זה דנראה לו שכל זמן שהאב בעיר אין אדם אחר יכול לפדות בלא ידיעת האב כו' ע\"ש ועל זה אשית ידי בעזרת הש\"י בסוף ותחלה אומר מה שפסק שב\"ד יכולים לפדות הבכור כשמת אביו ולזכות להכהן הממון של הפדיון לא נ\"ל ומה שהביא הספר הנ\"ל ראיה משם נ\"ל איפכא דהיינו מסוגיא דנדרים פ' אין בין המודר (נדרים דף ל\"ו) איבעיא להו התורם משלו על של חבירו צריך דעתו או לא מי אמרי' כיון דזכות הוא לו (פי' הר\"ן דזכין לו לאדם שלא בפניו מסתמא הוה כשלוחו) או דלמא מצוה דיליה היא וניחא ליה למיעבדה הלכך צריך להודיעו ולא איפשטא ופסק בי\"ד וכן הרמב\"ם דתרומתו תרומה וא\"צ להודיעו ומזה הביא ראיה בעל הספר הנ\"ל דה\"נ גבי פדיון הבן יכול אחר לזכות ממונו דזכות הוא לקטן ולא נראה כלל אלא אדרבה מוכח להיפך דהרי התוס' פ\"ק דכתובות (דף י\"א) בפשט דגר קטן מטבילין אותו דיש שליחות לקטן בשיש קצת חובו ע\"ש כתבו מדנקטו חובה קצת ולא נקטו סתם חובה משמע דכוונתם דכיון שלא מצינו שליחות לקטן רק בהך מלת' דמטבילין את גר קטן על כן דוקא בהך גווני דאיתא גבי גר שאין שום חוב בעולם אבל אם יש אפי' קצת חוב דלגבי גדול לא חשבינן ליה כיון דיש יותר צד לזכות מ\"מ גבי קטן לא אמרי' דיכול לעשות שליח אלא בזכות גמור בלי שום קצת חוב מזה מבואר דמה שכתב בנדרים דתורם משלו על של חבירו דמהני לא מיירי מקטן דהא מסקי התוס' כל שיש צד חובה לא הוי שליחות לקטן כלל וזה קאי אתורם משל הקטן על פירות הקטן ונקטו משום שמא הקטן רוצה להעדיף דהיינו שיהיה חפץ ליתן טפי ממה שנותן אותו אחר משל הקטן בשבילו שהמצוה חביבה עליו טפי ומש\"ה אין במעשה האחר כלום ממילא כשעושה הא' תרומה משלו על הקטן דיש ג\"כ קצת חוב זה לקטן שהרי לקח ממנו המצוה דאלו היה ממתין עד שיגדיל היה מקיים המצוה בגופו ובממונו אלא פשוט דלא מהני באמת תורם משלו על של חבירו אלא בגדול ואז לא איכפת לן בהאי מלתא שלוקח ממנו זכות המצוה דאינו אלא חוב קצת אבל בקטן שאפי' חוב קצת פוסל כמו שכתבו התוס' לא הוי שלוחו מכח זכין שלא בפניו דקטן אפי' בפניו הוה כמו שלא בפניו א\"כ הוא הדין ממש בהך פדיון בכור יש לומר כך דלא הוה זה האחר הפודה אותו כמו שלוחו כיון שבזה יש חובה קצת והרב בעל הספר הנ\"ל ראה דברי תוס' ולא היה אלא כמציץ מן החרכים ולא דקדק יפה ללמוד מה לנדון דידן שיש בו קצת חובה שזכרנו והוא מפרש או דלמא כו' אע\"ג דלגבי גדול אזלינן בתר צד הראשון וזכות יחשב לו מ\"מ לא יפטור מלקרוא צד חובה קצת ועוד כתוב בספר הנ\"ל הרבה ראיות מהגמ' מפ\"ק דקידושין והמעיין שם בגמ' יראה שיש להוכיח להיפך וע\"ש ועל כן נ\"ל דכל זמן שהאב חי יכול לעשות שליח לפדותו משלו במקומו ומטעם זה אבי אביו הרי הוא כאביו ודברי השואל בתשובת ריב\"ש אינם הלכה ולאו מפיו אנו חיים והריב\"ש לא חש להשיב עליהם וכן אחר יכול לתת משלו במקום האב ולפדות הבכור דהוה כשלוחו וכמו שכתבתי בתורם משלו על של חבירו אבל אם מת האב לא יפדה עד שיגדיל וכן איתא במהרי\"ל עיין שם:","\u0003מעכשיו אין בנו פדוי. \u0004דמתנה בעלמא היא דהא בתוך ל' לא שייך פדייה. כך כתב רש\"י:","\u0003ואם אמר ליה לאחר ל' יום כו'. \u0004א\"ל א\"כ אמאי כתב בסעיף י\"א דימתין עד יום א' אמאי לא יפדה ביום ו' ויאמר יהא בני פדוי לאחר ל' תירץ בת\"ה סי' קס\"ט דא\"א לעשות אז הסעודה וברכת פדיון ורש\"ל בתשובה סי' י\"ז כתב דבאמת דיפדה ביום ו' ויאמר הילך פדיונו ויחול לאחר ל' יום ונוהגין העולם כדברי ת\"ה וכמו שכתב כאן בפרט שבמהרי\"ל כתב שבמרדכי גדול נמצא כך:","\u0003ואע\"פ שאין המעות כו'. \u0004ואם לא אמר כלום לא מעכשיו ולא לאחר ל' יום פסק רש\"ל בתשובה דלעיל דאם המעות עדיין בעין ביד הכהן הוא פדוי ואם ליתנהו אינו פדוי ומדברי מהרא\"י בפסקיו סי' רל\"ד משמע דאף בסתם הוה כאומר לאחר ל' יום ותלוי בפלוגתא דרב ושמואל כמ\"ש כאן רמ\"א על הש\"ע דהיינו דרב ושמואל פליגי בפרק יש בכור (בכורות דף מ\"ט) באומר לאחר ל' יום והמעות אינם בעין ביד הכהן דרב ס\"ל בנו פדוי מידי דהוה אקידושי אשה שהמקדש אשה לאחר ל' יום היא מקודשת ושמואל ס\"ל אינו פדוי דשאני אשה דאי בעי מקדש אותה עכשיו ואיתא בקצת גמרות דהלכתא כשמואל והרא\"ש לא גרס לה ופסק כרב דהוה פדוי וזהו דעת הטור ותימה רבה על הב\"י שכתב דהטור פוסק כשמואל דאיפסקא הלכתא כוותיה וכמדומה שלא עיין אז בגמרא ויותר תימא על מו\"ח ז\"ל שכתב ג\"כ כב\"י ולא דק בדבר זה:","\u0003וטוב להחמיר כו'. \u0004נ\"ל דהיינו בלא ברכה דודאי ספק ברכות להקל והוא הדין אם אמר סתם בשעת הפדיון שפדה ביום ל' מחמת שהיה סבור שפודין ביום ל' או שטעה במספר הימים והמעות אינם בעין ביד הכהן דיפדה בלא ברכה אח\"כ דלפי דעת מהרא\"י שזכרתי גם בהא פליגי רב ושמואל:","\u0003אין הכהן גובה כו'. \u0004דלא אמרי' מלוה הכתובה בתורה כמו שטר דמי אלא כמלוה על פה שאינו גובה מן הלקוחות:","\u0003כבר זכה האב כו'. \u0004דהוה כאלו הפריש האב ה' סלעים ופדה בהם את בנו ועכבם לעצמו שהרי הוא כהן אותו הזכות עצמו יורש הבן:","\u0003שאין זה פטר רחם. \u0004לאפוקי מר' יוסי שאמר גם בזה פטר רחם בישראל עד שיפטו' רחם ישראל ולא חשבינן לההיא פטירה הראשונה לכלום קמ\"ל דלא:","\u0003וכן המפלת כמין בהמה כו' שחצי פרצוף כו'. \u0004הב\"י לא כתב מראה מקום לזה והוא בפרק המפלת (נדה דף כ\"ג):","\u0003מפני שקדמו אחר. \u0004אע\"ג דאותו אחר לא פטר רחם מ\"מ כיון שזה הנולד אחריו לא הוה בכור לנחלה דהא לאו ראשית אונו הוא לא הוי נמי בכור לכהן דבכור לדבר א' דהיינו לרחם ולא לולדות לא הוה בכור הכי אמרינן בפרק יש בכור (בכורות דף מ\"ז:)","\u0003אפי' חלקו כבר הנכסים. \u0004ולא אמרי' דהאי מדחי ליה והאי מדחי ליה והיינו כר' יהודה בלישנא קמא בגמ' והטור חולק על זה וס\"ל כלישנא בתרא דאפי' לר' יהודה אמרי' דכל א' מדחה את הכהן על חבירו ועי' בסעיף ל' מ\"ש בזה:","\u0003ילדו זכר ונקבה. \u0004פי' במחבא ילדו ונתערבו וכן בשני זכרים ונקבה ע\"כ נותן ה' סלעים לכהן דממ\"נ חד הוא בכור אם הראשונה ילדה שני זכרים הראשון בכור ואם הראשונה ילדה זכר ונקבה נמצא החברתה ילדה זכר לבדו והוא בכור ואותו שעם הנקבה פטור שמא נקבה יצאה ראשונה:","\u0003האבות פטורים. \u0004דכל חד וחד אומר לכהן הנקבה שלי והבן חייב לפדות עצמו דמ\"מ בכור הוא:","\u0003ילדו שתי נקבות כו'. \u0004קאי אסעיף כ\"ט בשתי נשים של שני אנשים ושניהם לא בכרו וקשה לי למה כתב כאן בשני זכרים וב' נקבות דאז אין כאן בכור ודאי דכל חד יוכל לומר נקבה יצאה קודם ממני לימא רבותא אפי' בשני זכרים ונקבה אחת דאז הוה א' ודאי בכור דהרי שניהם לא בכרו ואפ\"ה פטורים הבנים לפדות עצמם דכל חד יבריח וידחה על חבירו לומר כי הוא הבכור ובאמת כתב הטור כן בזה דפטורים ונראה דסעיף זה הוא לשון הרמב\"ם ואיהו לטעמיה אזיל דס\"ל בסעיף כ\"ו דהבנים חייבים במת אביהם תוך ל' יום ולא מצי כל חד לדחות על חבירו ה\"נ כן הוא והטור לטעמיה דפוסק גם שם לדחות על חבירו אלא דקשה לי הא ברייתא ערוכה היא כאן דפטור דאמרי' רב הונא תני ב' זכרים ונקבה אין לכהן כלום ותנא דידן כיון דשני אנשים הוא דמשכחת לה ובאיש אחד ושתי נשים לא משכחת לה לא מתני ליה ופירש\"י והיינו בשתי נשים של ב' אנשים ותנא דידן דלא תנא פטור זה אלא בב' נקבות וזכר או ב' נקבות וב' זכרים משום דהך פטור דב' זכרים לא משכחת אלא בשני אנשים אבל באיש א' ושתי נשים לא משכחת לה דשם כיון דאיכא חד בכור יהיב האב חייב ה' סלעים לכהן להכי לא תני ליה הרי בהדיא דמדינא פטורים בשתי נשים של שני אנשים אפי' בשני זכרים ונקבה אחת ולמה לא פסקו הרמב\"ם והש\"ע ואם תרצה לומר דהך סוגיא אתיא כלישנא בתרא דלעיל דסבר ליה דמצי למימר כל חד לדחות על חבירו ואיהו פסיק כלישנא קמא כ\"ש יש תפיסה על הרמב\"ם כיון דסתמא דתלמודא וברייתא דר\"ה ס\"ל כלישנא בתרא היה לו לפסוק כן:","\u0003או שני זכרים ונקבה אין לכהן כלום. \u0004הטור הביא דעת הרמב\"ם שכתב בזה דאם ילדו שני זכרים ונקבה זה שלא בכרה אשתו נותן ה' סלעים לכהן כיון שאינו נפטר אלא בשני ספיקות כו' וכתב הטור ואיני מבין דבריו כו' והב\"י הקשה עוד מאי שנא משתיהן נשיו ואחת בכרה כו' דפטור מספק ונ\"ל לתרץ שני הקושיות בדרך אחד דבשני אנשים אמרי' לכל א' מהם בפני עצמו הרי לפניך ג' ילדים שני זכרים ואחת נקבה ואזלינן בתר רובא ואנו אומרים לך ודאי זכר הולדת הלכך אותו שלא בכרה אשתו הוה ג\"כ כודאי הוליד זכר רק שבאת לומר שמא הולדתי גם נקבה על זה אנו אומרים אפי' לדבריך אין לך פטור ודאי דשמא יצאה הנקבה אחרונה משא\"כ לחיוב אין כאן מטעם ס\"ס דהזכר הוה כמו ודאי לפי זה ובזה לק\"מ קושיות הב\"י ג\"כ דבשתיהן של איש אחד אין לומר לו ודאי הולדת זכר מטעם רוב דהרי זה הוליד בודאי מאחת תאומים ומאחת ולד אח' כך לנו לומר שנולדו לו תאומים מאותה שבכרה ואותה שלא בכרה ילדה נקבה כמו איפכא ואין כאן רוב גבי איש הזה כן נ\"ל ליישב דעת הרמב\"ם מחמת קושיות דלעיל והוא נכון מאד אבל עדיין קשה מהא ברייתא דרב הונא דאמרה אפי' בשני זכרים ונקבה אחת פטורין ובכ\"מ בשם הר\"י קרקוס כתב דהרמב\"ם יש לו גירסא אחרת בגמ' ולדידיה קאי הך דרב הונא ארישא דמתני' דהיינו בשתי נשים של איש א' והוא תמוה מאד דהא קודם ההיא דרב הונא מפרש תלמודא התם סיפא דמתני' שתי נשים של שני אנשים והיאך יפרש התלמוד סיפא קודם לרישא. ונ\"ל דהרמב\"ם מפרש דהך ברייתא דרב הונא ס\"ל כר\"מ דאמר כל אחד מצי מדחה על חבירו והיינו כלישנא קמא דלעיל מיניה ואנן לא קי\"ל אלא כר' יהודה דלא מצי מדחה ע\"כ כנ\"ל:"]],["\u0003הלכות בכור בהמה טהורה\u0004\nבְּכוֹר בְּהֵמָה טְהוֹרָה נוֹהֵג בִּזְכָרִים וְלֹא בִּנְקֵבוֹת. וְנוֹהֵג אֲפִלּוּ שֶׁלֹּא בִּזְמַן הַבַּיִת, בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ. וּמִצְוָה לְהַקְדִּישׁוֹ וְלוֹמַר: הֲרֵי זֶה קֹדֶשׁ, שֶׁנֶּאֱמַר: תַּקְדִּישׁ לַה' אֱלֹהֱיךָ \u0005(דְּבָרִים טו, יט)\u0006 וְאִם לֹא הִקְדִּישׁוֹ, מִתְקַדֵּשׁ מֵאֵלָיו מֵרֶחֶם. \u0010y0\u0011 \u0005נוֹתְנִין אוֹתוֹ לְכֹהֵן, וְלֹא לְכֹהֶנֶת (טוּר)\u0006.\nאֵין נוֹתְנִין הַבְּכוֹר לְכֹהֵן כְּשֶׁיִּוָּלֵד, שֶׁאֵין זוֹ גְּדֻלָּה לַכֹּהֵן, אֶלָּא יְטַפֵּל בּוֹ בְּעָלָיו עַד שֶׁיַּגְדִּיל מְעַט. וְעַד כַּמָּה יִשְׂרָאֵל חַיָּבִים לְהִטָּפֵל בּוֹ, בְּדַקָּה ל' יוֹם; וּבְגַסָה, חֲמִשִּׁים יוֹם. וְאִם אֵין לוֹ כֹּהֵן מָצוּי, חַיָּב לְהִטָּפֵל בּוֹ עַד שֶׁיִּזְדַּמֵּן לוֹ כֹּהֵן.\nאָמַר לֵיהּ הַכֹּהֵן: תְּנֵהוּ לִי תּוֹךְ זְמַן זֶה, וַאֲנִי אֲטַפֵּל לְעַצְמִי, אֵינוֹ רַשַּׁאי לִתְּנוֹ לוֹ, \u0010c0\u0011 שֶׁזֶּה כְּמוֹ מְסַיֵּעַ עַל מַתְּנוֹתָיו. וְאִם הָיָה בַּעַל מוּם וְאָמַר לֵיהּ תּוֹךְ זְמַן זֶה: תְּנֵהוּ לִי שֶׁאוֹכְלֶנּוּ עַתָּה, רַשַּׁאי לִתְּנוֹ לוֹ.\nאִם הַכֹּהֵן מְסָרֵב מִלְּקַבְּלוֹ, מִפְּנֵי שֶׁיֵּשׁ בּוֹ טֹרַח גָּדוֹל בַּזְּמַן הַזֶּה לְהִטָּפֵל בּוֹ עַד שֶׁיִּפֹּל בּוֹ מוּם, אֵינוֹ רַשַּׁאי, מִפְּנֵי שֶׁנִּרְאֶה כִּמְבַזֶּה מַתְּנוֹת כְּהֻנָּה. \u0005הַגָּה: \u0010c1\u0011 וַאֲפִלּוּ סְפֵק בְּכוֹר, \u0010y1\u0011 צָרִיךְ הַכֹּהֵן לְקַבְּלוֹ מִיַּד יִשְׂרָאֵל הַנּוֹתֵן לוֹ (פִּסְקֵי מהרא\"י סִימָן קס\"ז ומהרי\"ל סִימָן ר\"ד)\u0006. וְדַוְקָא בְּסָפֵק שֶׁבָּא מֵעַצְמוֹ, \u0010y2\u0011 אֲבָל בְּמָקוֹם שֶׁפָּשַׁע הַיִּשְׂרָאֵל, כְּגוֹן שֶׁקָּנָה פָּרָה חוֹלֶבֶת מִן הָעוֹבֵד כּוֹכָבִים, אוֹ שֶׁהָיָה יָכוֹל לִמְכֹּר הַבְּכוֹר לְעוֹבֵד כּוֹכָבִים קֹדֶם שֶׁנּוֹלַד, וְלֹא עָשָׂה, אֵין הַכֹּהֵן צָרִיךְ לְקַבְּלוֹ \u0005(שָׁם)\u0006. וַאֲפִלּוּ בְּמָקוֹם שֶׁצָּרִיךְ לְקַבְּלוֹ, אָסוּר לְיִשְׂרָאֵל לִתֵּן לוֹ \u0010y3\u0011 לְהַקְנִיטוֹ אוֹ לִנְקֹם מִמֶּנּוּ. \u0005(ג\"ז שָׁם בְּשֵׁם מוֹהֲרַ\"ם)\u0006.\nהַבְּכוֹר, בַּזְּמַן הַזֶּה, יַשְׁהֶנּוּ עַד שֶׁיִּפֹּל בּוֹ מוּם, \u0010y4\u0011 וְשׁוֹחֲטוֹ עַל פִּי \u0010y5\u0011 מֻמְחֶה, וְאוֹכְלוֹ \u0005(בְּכָל מָקוֹם)\u0006, וּמַאֲכִילוֹ \u0010y6\u0011 אֲפִלּוּ לְעוֹבֵד כּוֹכָבִים \u0010y7\u0011 \u0005אוֹ לִכְלָבִים. (הַגָּהוֹת מָרְדְּכַי פֶּרֶק הָאִשָּׁה שֶׁהָלְכָה)\u0006.\nהַבְּכוֹר, בַּזְּמַן הַזֶּה, מוֹכֵר אוֹתוֹ הַכֹּהֵן אֲפִלּוּ לְיִשְׂרָאֵל, תָּמִים חַי, וּבַעַל מוּם חַי וְשָׁחוּט, \u0010y8\u0011 וּמְקַדֵּשׁ בּוֹ אֶת הָאִשָּׁה, שֶׁהוּא כִּשְׁאָר מָמוֹנוֹ. אֲבָל אֵינוֹ נִמְכָּר בְּמָקוֹלִין, וְאֵינוֹ נִשְׁקָל בְּלִטְרָא. וּמִכָּל מָקוֹם מֻתָּר לִשְׁקֹל בּוֹ \u0010y9\u0011 \u0010c2\u0011 מָנָה כְּנֶגֶד מָנָה, וּכְנֶגֶד כְּלִי וְקוֹפִיץ \u0005(פִּי' כְּמוֹ סַכִּין גָּדוֹל וְרָחָב וְחִדּוּדוֹ בּוֹלֵט בְּאֶמְצָעִיתוֹ)\u0006. וְהָנֵי מִלֵּי, בְּשָׂרוֹ, \u0010c3\u0011 אֲבָל חֶלְבּוֹ וְדָמוֹ \u0010y10\u0011 וְגִידוֹ וְקַרְנָיו, נִמְכָּרִים בְּמָקוֹלִין וְנִשְׁקָלִין בְּלִטְרָא. וְשַׁמְנוֹ שֶׁל גִּיד \u0010c4\u0011 דִּינוֹ כְּבָשָׂר, כֵּיוָן שֶׁהוּא מֻתָּר מִן הַתּוֹרָה.\nהַבְּכוֹר, \u0010y11\u0011 אֲפִלּוּ בַּעַל מוּם, נֶאֱכָל \u0010c5\u0011 תּוֹךְ שְׁנָתוֹ. וּמֵאֵימָתַי מוֹנֶה לוֹ, אִם נוֹלַד בַּעַל מוּם מוֹנֶה לוֹ מִיּוֹם שֶׁנּוֹלַד, וְהוּא שֶׁיּוֹדֵעַ \u0010y12\u0011 שֶׁכָּלוּ לוֹ חֳדָשָׁיו, שֶׁהֲרֵי נִרְאֶה לַאֲכִילָה בְּיוֹם לֵידָתוֹ. אֲבָל אִם לֹא יָדַע בְּוַדַּאי שֶׁכָּלוּ לוֹ חֳדָשָׁיו, מוֹנֶה לוֹ \u0010c6\u0011 מִיּוֹם שְׁמִינִי.\nנוֹלַד לוֹ מוּם תּוֹךְ שְׁנָתוֹ, \u0010y13\u0011 רַשַּׁאי לְקַיְּמוֹ כָּל י\"ב חֹדֶשׁ. נוֹלַד לוֹ מוּם בְּסוֹף שְׁנָתוֹ, מֻתָּר לְקַיְּמוֹ ל' יוֹם מִיּוֹם שֶׁנָּפַל בּוֹ הַמּוּם, וְאַף עַל פִּי שֶׁהוּא מִתְּאַחֵר לְאַחַר שְׁנָתוֹ. כֵּיצַד, כְּגוֹן שֶׁנָּפַל בּוֹ מוּם בְּט\"ו יוֹם לִפְנֵי גְּמַר שְׁנָתוֹ, מַשְׁלִימִים לוֹ ט\"ו יוֹם אַחַר שְׁנָתוֹ. נוֹלַד לוֹ מוּם אַחַר שְׁנָתוֹ, אֵינוֹ רַשַּׁאי לְקַיְּמוֹ אֶלָּא עַד ל' יוֹם, וְיֹאכַל.\nהַבְּכוֹר, בַּזְּמַן הַזֶּה, \u0010y14\u0011 עַד שֶׁלֹּא נִרְאֶה לְהַרְאוֹתוֹ לְחָכָם, מְקַיְּמוֹ שְׁתַּיִם וְשָׁלֹשׁ שָׁנִים, וּמִשֶּׁנִּרְאֶה לְהַרְאוֹתוֹ לְחָכָם, אִם נוֹלַד בּוֹ מוּם בְּתוֹךְ שְׁנָתוֹ רַשַּׁאי לְקַיְּמוֹ כָּל י\"ב חֹדֶשׁ. וְאִם נוֹלַד בּוֹ מוּם לְאַחַר שְׁנָתוֹ, מְקַיְּמוֹ ל' יוֹם.\nשָׁנָה שֶׁל בְּכוֹר הִיא שְׁנַת לְבָנָה תְּמִימָה, י\"ב חֹדֶשׁ מִיּוֹם לְיוֹם. וְאִם הָיְתָה שָׁנָה מְעֻבֶּרֶת, נִתְעַבְּרָה לוֹ, וּמוֹנֶה לוֹ י\"ג חֳדָשִׁים. \u0010y15\u0011 \u0010c7\u0011\nנוֹלְדוּ לוֹ שְׁנֵי טְלָאִים, אֶחָד בְּט\"ו שֶׁל אֲדָר הָרִאשׁוֹן וְאֶחָד בְּרֹאשׁ חֹדֶשׁ אֲדָר הַשֵּׁנִי, זֶה שֶׁנּוֹלַד בְּרֹאשׁ חֹדֶשׁ אֲדָר שֵׁנִי, כֵּיוָן שֶׁהִגִּיעַ יוֹם רִאשׁוֹן בַּאֲדָר שֶׁל שָׁנָה הַבָּאָה עָלְתָה לוֹ שָׁנָה, וְזֶה שֶׁנּוֹלַד בַּחֲצִי אֲדָר הָרִאשׁוֹן לֹא עָלְתָה לוֹ שָׁנָה עַד חֲצִי אֲדָר שֶׁל שָׁנָה הַבָּאָה, הוֹאִיל וְנוֹלַד בְּחֹדֶשׁ הָעִבּוּר מוֹנִים אוֹתוֹ לוֹ.\nעָבַר וְשָׁהָה אוֹתוֹ לְאַחַר זְמַנּוֹ, אֵינוֹ נִפְסָל.",["\u0003ונותנין אותו לכהן כו'. \u0004בין אם הוא תם או בעל מום בין שנולד במומו בין שנולד בו מום אחר שנולד נותנים אותו לכהן כמו שיתבאר:","\u0003צריך הכהן לקבלו כו'. \u0004היינו שעושה הכהן איסור אם אינו מקבלו אבל מ\"מ לא כייפינן ליה כדכתב הא\"ז ומ\"ש הא\"ז במס' יו\"ט דמשמע מפירוש רש\"י דכייפינן ליה ההיא איירי כשרוצה לקבלו לאחר זמן וכן הוא בפסקי מהרא\"י סי' קס\"ז מתשובת הלוי והיא תשובת מהרי\"ל בסימן ר\"ד וכן הוא בהגהת מרדכי פרק האשה רבה ובחולבת א\"צ הכהן לקבלה דאע\"ג דקי\"ל לחומרא מ\"מ יכול הכהן לומר לנותן זיל אייתי ראיה דבכור הוא ואטפל בו כו' ע\"ש וצריך לומר לדברי מהרי\"ל דהתם קאמר שאין כופין אותו:","\u0003אבל במקום כו' כגון שקנה פרה כו'. \u0004אין זה מדוקדק וז\"ל ד\"מ ופסק מהרי\"ו סי' כ\"ז (צ\"ל קכ\"ז) דאפי' ספק בכור צריך לקבל ודוקא מישראל אבל כהן עני שיש לו בכור ונותנו לכהן עשיר א\"צ לקבלו אבל אם הישראל פשע שלא מכרו לעובד כוכבים קודם שנולד נראה דא\"צ לקבלו כו' וכ' מהרא\"י בפסקיו סי' קס\"ח דהא דכתב מהר\"מ דצריך לקבלו בספק בכור דוקא שנולד הספק מעצמו אבל הקונה מעובד כוכבים פרה חולבת א\"צ לקבלו ע\"כ עכ\"ל ד\"מ וע\"כ ערבב הרב בכאן הדברים אבל באמת לא ידעתי מה פשיעה שייך בקונה פרה חולבת אם לא היה יכול למכור הבכור וגם אם פשע מאי איריא ספק בכור אפי' ודאי בכור א\"צ לקבלו כדמשמע בתשובת מהרי\"ו סימן קכ\"ז ומ\"ש מהרא\"י בפסקיו סי' קס\"ח בקונה פרה חולבת דא\"צ לקבלו היינו מטעמ' שכתב וז\"ל דמהר\"מ לא איירי בספק דתליא בפלוגתא דרבוותא אלא בספק שנולד מעצמו כדאשכחן כמה ספיקות במס' בכורות אבל כה\"ג דאיכא כמה ספיקות דפלוגתא דרבוותא (ר\"ל אי חלב פוטר בבכורה כדלקמן סי' שי\"ו ס\"ג) אס אנו הולכין להחמיר משום איסור כרת כדי לצאת ידי כולן לא ניזול כולי האי להחמיר בשביל מתנות כהונה עכ\"ל ולא ידעתי ליישב דברי הרב אם לא שנגיה בדבריו ודוקא בספק שבא מעצמו אבל בספק שבא בפלוגתא דרבוותא כגון שקנה פרה חולבת מן העובד כוכבים או שפשע הישראל שהיה יכול למכור הבכור לעובד כוכבים קודם שנולד כו' והעט\"ז העתיק דברי הרב ולא חלי ולא הרגיש ומ\"מ צ\"ע לדינא במה שחלק מהרא\"י בין ספק שמעצמו לספק דפלוגתא דרבוותא דמתשובת הלוי שהביא שם והוא בתשובת מהרי\"ל סימן ר\"ד לא משמע הכי דבקנה פרה חולבת מן העובד כוכבים כתב דצריך הכהן לקבלה ולמד מספק בכור דמהר\"מ אע\"ג שהביא שם סברות הפוסקים אי חלב פוטר בבכורה או לא ואפשר כיון דמהרא\"י ראה תשובת מהרי\"ל הנ\"ל ואפ\"ה לא פסק כן כוותיה נקטינן דבתראה הוא וגם נראה דמהרא\"י שם לא הקיל מטעם זה לבד דדוחק לחלק בין ספק דמעצמו לספק דתליא בפלוגתא דרבוותא אם לא שנחמר דמהרא\"י סובר דבספק בכור כייפינן ליה לכהן ואשמעינן דבספק דתליא בפלוגתא דרבוותא לא כייפינן ליה דמצי למימר קים לי כהמתירים וזה דוחק דנימא דמהרא\"י פליג אתשובת מהרי\"ל דלעיל דכתב דלא כייפינן ליה אפי' בספק בכור ועוד דמשמע דבפלוגתא דרבוותא קאמר דא\"צ לקבלו כלל אפי' אי לא כייפינן ליה ואין איסור בדבר במה שאינו מקבלו אלא נראה משום דהתם בעובדא דמהרא\"י היו כמה ספיקות בפלוגתא דרבוותא שמכר לעובד כוכבים בכסף דהוי מכירה ליש פוסקים כדלקמן סי' ש\"ך סעיף ו' וכן בהיתה חולבת דפוטר בבכור ליש פוסקים לכך היקל בדבר אבל בספק אחד דפלוגתא דרבוותא לבד אין להקל אם לא שמדינא נראה עיקר כמאן דמיקל אלא שמחמירים דבכה\"ג אפשר דאין הכהן צריך לקבלו. כנ\"ל:","\u0003להקניטו או כו'. \u0004ואם נראה שעושה כן א\"צ הכהן לקבלו. מהרי\"ו שם מתשובת מהר\"מ:","\u0003ושוחטו ע\"פ מומחה כו'. \u0004והאידנא ליכא מומחין ובעינן ג' כדלקמן סי' ש\"ט סעיף ב':","\u0003ואוכלו ומאכילו כו'. \u0004וכשהוא טרפה אסור ליהנות ממנו כדלקמן סי' ש\"ז:","\u0003אפי' לעובד כוכבים כו'. \u0004וכתב מהרש\"ל פ' המקשה סי' ד' דמ\"מ איסור דרבנן איכא משום בזיון קדשים ואינו מותר להאכילו לעובד כוכבים אלא דרך זימון שיאכל העובד כוכבים עמו אבל לא למכרו לו אפי' ליתן לו חתיכה חיה וכן לכלבים נמי דרך עראי הנותר מהבשר עם העצמות אבל לא להשליכן להדיא לכלבים ע\"כ:","\u0003או לכלבים. \u0004והר\"ן כתב בפ' המקשה דדוקא לעובד כוכבים שרי אבל לכלבים אסור משום ואכלת ולא לכלביך ומהרש\"ל שם סי' ד' השיג עליו בלא טענה מוכרחת וגם מ\"ש מהרש\"ל שכן משמע מהרא\"ש פ' פסולי המוקדשין אינו מוכרח דר\"ל מ\"ש הרא\"ש בסיפא גבי טרפה דאסור לכלבים ולעובד כוכבים משמע דברישא גבי בעל מום שרי ואין זה דיוק דה\"ק ואסור לכלבים וה\"ה לעובד כוכבים דילפינן מכלבים גם דברי התוס' פ' פסולי המוקדשין דף ל\"ב ע\"ב דכתבו דשרי לעובד כוכבים ולא מיתסר מואכלת ולא לכלביך כו' משמע לכאורה דלכלבים מיהא אסור אלא דלעובד כוכבים מיהא שרי וכ\"כ הרשב\"א בחידושיו פרק המקשה דף ע\"ג וז\"ל תירצו רבותינו בעלי התוס' ז\"ל דכל היכא דשרי לישראל כגון שנפל בו מום שרי אפי' לזמן עליו העובד כוכבים דאיתקש לצבי ואיל אבל לכלבים אסור מואכלת ולא לכלביך ע\"כ וכ\"כ ר' ירוחם נתיב כ' חלק ב' שמותר להאכילו לעובד כוכבים כל זמן שמותר לישראל אבל לכלבים אסור להאכילו אף ע\"פ שמותר לישראל כדאמרי' בפסחים ואכלת ולא לכלביך ובבכור בעל מום הכתוב מדבר עכ\"ל לכן יש ליזהר בדבר:","\u0003ומקדש בו כו'. \u0004עיין בא\"ע סוף סי' כ\"ח:","\u0003מנה כנגד מנה. \u0004פירש\"י אם יש לו חתיכ' בשר חולין שנשקלה בליטרא יכול לשקול בשר בכור כנגדו והרמב\"ם פי' חלק כחלק כגון שיחלקו אותו ו' או ז' ונותנין חלק בכף מאזנים זה וחלק בכף מאזנים זה ובעט\"ז כתב בסתם כשני הפירושים וכן עיקר דהא שרינן אפי' כנגד כלי וקופיץ משום דדוקא ביו\"ט אסרינן כה\"ג בא\"ח סי' ת\"ק סעיף ב' משום דמחזי כעובדא דחול משא\"כ הכא א\"כ כל שאינו שוקל בליטרא ממש שרי וכ\"ש כיון שאיסור זה אינו אלא מדרבנן ובמע\"מ מגמגם על העט\"ז בזה ואני הנלפע\"ד כתבתי:","\u0003וגידו. \u0004בפרישה גרס וגידיו ופי' דקאי אכל הגידים שבבהמה אף המותרים לאכול דגידים אינן בכלל בשר:","\u0003אפי' בעל מום כו'. \u0004כלומר לא מבעיא תם בזמן הבית שאינו קרב אלא תוך שנתו אלא אפי' בעל מום בזמן הזה לא ישהנו יותר משנתו כדמפרש ואזיל:","\u0003שכלו לו חדשיו. \u0004דהיינו ט' לגסה וה' לדקה כדלעיל סי' ט\"ו:","\u0003רשאי לקיימו כל י\"ב חדש. \u0004ללידתו אם כלו לו חדשיו או עד שכלה לו שנה מיום הח' אם לא כלו חדשיו כ\"כ העט\"ז והוא מדברי ב\"י (וכ\"כ בפרישה) אבל באמת מדברי הרמב\"ם והסמ\"ג עשין רי\"א (שהוא כלשון המחבר) לא משמע הכי מדכתבו ברישא אם נולד בעל מום מונה לו מיום שנולד כו' שהרי נראה לאכילה ביום לידתו כו' משמע דוקא נולד בעל מום וכן מדסתמו כאן ולא חלקו בכך משמע דכיון דלא נולד בעל מום לעולם מונים לו מיום ח' ללידתו דאע\"ג דידוע שכלו לו חדשיו מ\"מ הרי לא נראה לאכילה ביום לידתו דהוה תם וכ\"כ רש\"י ותוס' אמאי דקאמרינן בש\"ס פ\"ק דר\"ה ריש דף ז' הא בתם (מונה לו מיום ח') הא בבעל מום (מונה לו מיום שנולד) בעל מום מי מצו אכיל ליה דקים ליה שכלו חדשיו ופירש\"י בעל מום שנולד במומו ועומד לשחוט בחוץ מיום שנולד ראוי הוא לכך ומונים ליה משנולד עכ\"ל וכ\"כ התוס' הא בבעל מום מעיקרו דתם ונעשה בעל מום כיון דלא חזי לאכילה מונין לו משעת הרצאה (כלומר מיום ח' שנרצה לקרבן) ע\"כ וכ\"נ דאל\"כ הדרא קושית הש\"ס לדוכתא בעל מום מי מצי אכיל ליה ובאמת לישנא דיכול להשהותו עד מלאת לו שנה ללידתו שכתב הטור כאן דחקו לב\"י וסייעתו וע\"כ כתבו כן והוה משמע להו דהא דפריך ש\"ס בעל מום מי מצי אכיל ליה היינו משום דשמא נפל הוא אבל משום דתם הוא לא חייש דהא אח\"כ נעשה בעל מום דהא בלא\"ה מונים לו מיום ח' כשנפל בו מום תוך שנתו אע\"ג דאחר ח' תם הוא אבל באמת נראה שט\"ס הוא בטור וצ\"ל יכול לשהותו עד מלאת לו שנה מיום ח' ללידתו שהרי גם הטור כתב ברישא נולד במומו אי קים לן בגויה שכלו חדשיו כו' אלמא דוקא נולד במומו ועוד דאל\"כ הוה ליה לערבינהו וליתנינהו כולהו בחד בבא ועוד דלאיזה צורך כתב כאן ללידתו הוי ליה למיסתם סתומי ועוד דהא לפי זה צ\"ל דמיירי כאן בשכלו לו חדשיו וזה אינו במשמע ואי סמך עצמו אמ\"ש ברישא א\"כ לא ה\"ל לכתוב כלל ללידתו אלא פשוט דט\"ס הוא וצ\"ל מיום ח' ללידתו ואדרבה אתא לאשמועינן דהכא אין חילוק ולעולם מונים לו שנה מיום ח' ללידתו כיון שנולד תם ואח\"כ נפל בו מום מיהו מיום ח' מונים לו אע\"ג דאז לא היה ראוי לאכילה דלא גרע בעל מום מתם דהוי מונין לו מיום ח' משום דראוי להרצאה וה\"ה הכא אבל כשאינו ראוי לא להרצאה ולא לאכילה ודאי דאפי' כלו לו חדשיו מונין לו מיום ח' וכדאמרן:","\u0003עד שלא נראה כו'. \u0004מדלא כתב בקיצור עד שלא נולד בו מום מקיימו כו' ומשנולד בו מום רשאי לקיימו י\"ב חדש משמע דה\"ק דאע\"פ שנולד בו מום כל שלא נראה להראותו לחכם דהיינו שלא נזדמן לו חכם ואין זקוק להוליכו במקום שהחכם שם וכן כתב הסמ\"ג עשין רי\"א בשם ר' שמעון והתוס' פרק עד כמה (בכורות דף כ\"ח ע\"א):","\u0003נולדו לו כו'.\u0004 ה\"ה בשאר דברים דינא הכי כמו שנתבאר בא\"ח סי' נ\"ה סעיף י' לענין שני נערים וע\"ש:"],["\u0003שזה כמו מסייע כו'. \u0004דכיון שהוא תם ובזמן הזה דאין מקריבים אותו למה נוטלו ממנו קודם זמנו אלא ודאי שכוונתו לסייע לו בשביל שיתן לו כל המתנות כהונה והוה כגוזל אחרים וזהו שכתב הטור בד\"א בתם בזמן הזה כו':","\u0003ואפי' ספק בכור כו'. \u0004איסורא איכא אבל אין כופין אותו. כן כתב מהרא\"י שם:","\u0003מנה כנגד מנה. \u0004פי' אם יש לו חתיכ' בשר חולין שידוע משקלה יוכל לשקול בשר בכור כנגדה וכן נגד כלי וקופיץ:","\u0003אבל חלבו כו'. \u0004דלא עביד רבנן מעלה אלא בבשר:","\u0003דינו כבשר. \u0004פי' לענין שלא יהיה נמכר במקולין:","\u0003תוך שנתו. \u0004ולא לאשהויי דלא ליתי לידי תקלה בגיזה ועבודה:","\u0003מיום שמיני. \u0004דאז ראוי לאכילה ואין מונין אלא מעת שנראה לאכילה:","\u0003נולדו לו שני טלאים. \u0004מזה יש ללמוד ג\"כ לענין שני ילדים שנולד א' בט\"ו באדר הראשון והשני נולד בר\"ח אדר שני ובשנת הי\"ג אין עיבור דנעשה השני בר מצוה קודם לראשון כמו כאן:"]],["אֵין מַרְגִּילִין בִּבְכוֹר, \u0010c0\u0011 דְּהַיְנוּ לְהַפְשִׁיט עוֹרוֹ שָׁלֵם דֶּרֶךְ מַרְגְּלוֹתָיו.\nשְׁחָטוֹ וְנִמְצָא טְרֵפָה, עוֹרוֹ עִם בְּשָׂרוֹ אָסוּר בַּהֲנָאָה וְטָעוּן קְבוּרָה. \u0010y0\u0011 \u0005וְלָכֵן טוֹב לְמָכְרוֹ לְעוֹבֵד כּוֹכָבִים קֹדֶם שְׁחִיטָה. (הַגָּהוֹת מָרְדְּכַי פ' הָאִשָּׁה וְכֵן כָּתַב הַבֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבָה אַשְׁכְּנַזִּית וְהִיא בִּתְשׁוּבַת מהרי\"ל)\u0006.\nצָרִיךְ הַכֹּהֵן לְהַשְׁהוֹתוֹ וּלְגַדְּלוֹ לְעוֹלָם, עַד שֶׁיִּפֹּל בּוֹ מוּם. \u0010y1\u0011 וְיָכוֹל לְמָכְרוֹ אֲפִלּוּ לְיִשְׂרָאֵל, אַף עַל פִּי שֶׁהוּא תָּמִים, וְהַלּוֹקֵחַ יִנְהֹג בּוֹ קְדֻשַּׁת בְּכוֹר. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁהַלּוֹקֵחַ קוֹנֶה אוֹתוֹ לְצָרְכּוֹ. \u0010y2\u0011 אֲבָל אָסוּר לַעֲשׂוֹת בּוֹ סְחוֹרָה, דְּהַיְנוּ לִקְנוֹתוֹ כְּדֵי לְהַרְוִיחַ. וְאִם קְנָאוֹ לְצָרְכּוֹ וְלֹא נִצְטָרֵךְ לוֹ, יָכוֹל לַחֲזֹר וּלְמָכְרוֹ.",["\u0003ולכן טוב למכרו כו'. \u0004דשמא יהיה טרפה אח\"כ ומהרש\"ל פרק המקשה סי' ד' חלק ע\"ז משום דבהמה בחזקת איסור טרפה עומדת דקי\"ל אם נאבדה הריאה בלא בדיקה טרפה וכל זמן שלא בדקה אסור למכור לעובד כוכבים עכ\"ד ואין מזה ראיה דהא כבר נתבאר לעיל סי' ל\"ט ס\"ב דרוב הפוסקים מתירין כשנאבדה הריאה בלא בדיקה ואף האוסרין כבר כתבתי שם ס\"ק ח' דטעמייהו דכיון שחז\"ל הצריכו בדיקה החמירו לאסור אף בדיעבד דאל\"כ מה הועילו בתקנתן וזה לא שייך הכא וכ\"כ בתשובת מהרי\"ל סי' ע\"ב דמותר למכרו לעובד כוכבים וכ\"כ בהגמ\"ר ס\"פ האשה רבה מיהו בתשובת מהרי\"ל שם מסיק בשם מהרי\"א דאסור למכור לעובד כוכבים וכ\"כ מהר\"מ מטיקאטי\"ן בגליון המרדכי בשם תשובת אחרונים דא\"ז ע\"ש:","\u0003ויכול למכרו אפילו לישראל. \u0004פי' ל\"מ לכהן אלא אפי' לישראל אבל לעובד כוכבים אסור כדמשמע בש\"ס:","\u0003אבל אסור לעשות בו סחורה. \u0004ע\"ל סימן קי\"ז מדברים האסורים לעשות בהם סחורה:"],["\u0003דהיינו להפשיט כו'. \u0004אפי' בעל מום דנראה כבזיון כאלו מוכרן לצורך מפוח בעודם על הקדשים:"]],["\u0010y0\u0011 הַבְּכוֹר \u0010c0\u0011 אָסוּר בְּגִזָּה וַעֲבוֹדָה. וַאֲפִלּוּ אִם עָבַר וּגְזָזוֹ, אוֹ תְּלָשׁוֹ בְּיָדוֹ, אוֹ אֲפִלּוּ נָשַׁר הַצֶּמֶר מֵעַצְמוֹ, אָסוּר בַּהֲנָאָה לְעוֹלָם, לֹא שְׁנָא מֵת מֵעַצְמוֹ לֹא שְׁנָא שְׁחָטוֹ אַחַר כָּךְ, וַאֲפִלּוּ עַל יְדֵי \u0010c1\u0011 מֻמְחֶה, אֵין הַשְּׁחִיטָה מַתֶּרֶת הַצֶּמֶר שֶׁנִּתְלַשׁ מֵחַיִּים. אֲבָל צֶמֶר הַמְחֻבָּר, הַשְּׁחִיטָה מַתִּירָתוֹ כִּבְשָׂרוֹ.\nאִם נִתְלַשׁ מֵחַיִּים וְעוֹדֶנּוּ מְסֻבָּךְ בִּשְׁאָר הַצֶּמֶר, אֶת שֶׁנִּרְאֶה כִּשְׁאָר צֶמֶר נִתָּר בַּשְּׁחִיטָה, וְאֶת שֶׁאֵינוֹ נִרְאֶה כִּשְׁאָר הַצֶּמֶר, וְהוּא \u0010c2\u0011 שֶׁעִקָּרוֹ הָפוּךְ כְּלַפֵּי רֹאשׁוֹ, אֵין הַשְּׁחִיטָה מַתִּירָתוֹ.\nכְּשֶׁבָּא לְשָׁחֲטוֹ אוֹ לִרְאוֹת מוּמוֹ, \u0010y1\u0011 \u0005מֻתָּר \u0006 לִתְלֹשׁ הַצֶּמֶר שֶׁל מְקוֹם שְׁחִיטָה, כְּדֵי לַעֲשׂוֹת מָקוֹם לַשְּׁחִיטָה. \u0005וְהַצֶּמֶר שֶׁתָּלַשׁ אָסוּר בַּהֲנָאָה (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006. וְדַוְקָא בַּיָּד, אֲבָל לֹא בִּכְלִי, כְּדֵי שֶׁלֹּא יְהֵא נִרְאֶה כְּגוֹזֵז.\nגִּזַּת בְּכוֹר, אֲפִלּוּ גִּזַּת בַּעַל מוּם, שֶׁנִּתְעָרֵב בְּגִזֵּי חֻלִּין אֲפִלּוּ אַחַת בְּכַמָּה אֲלָפִים, \u0010y2\u0011 כֻּלָּן אֲסוּרוֹת, שֶׁהֲרֵי הוּא דָּבָר חָשׁוּב וּמְקַדֵּשׁ בְּכָל שֶׁהוּא.\nהָאוֹרֵג \u0010y3\u0011 \u0010c3\u0011 מְלֹא הַסִיט מִצֶּמֶר בְּכוֹר בְּבֶגֶד, יִדָּלֵק הַבֶּגֶד \u0005הַגָּה: אוֹ יִקָּבֵר (טוּר)\u0006. וְיֵשׁ אוֹמְרִים דְּדַוְקָא שֶׁאָרַג דָּבָר חָשׁוּב, כְּגוֹן צִיּוּר בְּבֶגֶד; אֲבָל \u0010c4\u0011 אִם אֵינוֹ דָּבָר חָשׁוּב, בָּטֵל בְּרֹב \u0005(ג\"ז בַּטּוּר וְרֹא\"שׁ)\u0006.",["\u0003הבכור. \u0004בין תם בין בעל מום:","\u0003מותר לתלוש הצמר כו'. \u0004בש\"ס איתא ובלבד שלא יזיזנו ממקומו ופירש\"י הטעם מפני שלא יאמרו מום עביד בקדשים אלא יניחנו מסובך עם הצמר מכאן ומכאן:","\u0003כולן אסורות בהנאה. \u0004וע\"ל סי' ק\"י ס\"ק ב':","\u0003מלא הסיט. \u0004דוקא מלא הסיט שהוא חשוב אבל לא פחות מזה והיש אומרים סבירא להו דדוקא דבר חשוב באריגה כגון מעשה ציור בעינן ועי' בב\"י:"],["\u0003אסור בגיזה. \u0004אפי' הצמר מסובך כן מוכח בסי' שכ\"א סעיף ט':","\u0003אין השחיטה מתרת כו'. \u0004פירש\"י הטעם דחיישינן אי מתירתו אתי לאשהויי לבכור כדי שתשיר כל צמר ואתי ביה לידי תקלה בגיזה ועבודה:","\u0003שעיקרו הפוך. \u0004פירוש שכפול באמצעיתו ושני ראשיה בולטין לחוץ:","\u0003מלא הסיט. \u0004פי' שיעור שיש מאצבע לאמה כשמרחיק האצבעות מהדדי נקרא מלא הסיט והריוח שבין אצבע לגודל נקרא סיט כפול:","\u0003אם אינו דבר חשוב בטל ברוב. \u0004כתב רש\"י סוף תמורה ואי קשיא הא דאמרי' במס' נדה בגד שארג בו כלאים ה\"ז לא ימכרנו לעובד כוכבים ואמאי לא ליבטל האי חוט ברוב לאו פירכא היא דבכלאים לא אמרי' בטל ברוב דעיקר האיסור ע\"י תערובות הוא ולא שייך בהו ביטול ברוב עכ\"ל. והוא כדברי התוס' שהבאתי בסי' רצ\"ט בסעיף א' לעיל ואין להקשות דאמאי כתב הטור בסי' ש\"ג דבכלאים דרבנן הינתק חוט א' כו' ואמאי לא בטיל ברוב דהא דרבנן היא י\"ל דלענין ביטול ברוב שווינהו רבנן כדאורייתא דכל שישנו בעין אוסר כמו מן התורה דמה דתיקון רבנן כעין דאורייתא תיקון משא\"כ אם היה א' דאפשר דאינו בעולם בזה הקילו. כן נראה לי:"]],["בְּכוֹר, בַּזְּמַן הַזֶּה, אֵין בּוֹ הֶתֵּר אֶלָּא עַל יְדֵי מוּם. וַאֲפִלּוּ אִם יִרְצוּ הַבְּעָלִים אוֹ הַכֹּהֵן לְכָנְסוֹ לְכִפָּה עַד שֶׁיָּמוּת מֵעַצְמוֹ, \u0010c0\u0011 אֵינָם רַשָּׁאִים, אֶלָּא צָרִיךְ הַכֹּהֵן לְגַדְּלוֹ עַד שֶׁיִּפֹּל בּוֹ מוּם.\nאֲפִלּוּ כְּשֶׁיִּפֹּל בּוֹ מוּם בְּגָלוּי וְנִכָּר לַכֹּל, כְּגוֹן שֶׁנִּקְטְעָה יָדוֹ אוֹ רַגְלוֹ וְכַיּוֹצֵא בוֹ, אֵינוֹ רַשַּׁאי לְשָׁחֲטוֹ אֶלָּא עַל פִּי מֻמְחֶה, שֶׁיּוֹרֶה לוֹ שֶׁהוּא מוּם הָרָאוּי לִשָּׁחֵט עָלָיו. וְאִם אֵין חָכָם מֻמְחֶה, נִתָּר עַל פִּי ג' בְּנֵי הַכְּנֶסֶת, דְּהַיְנוּ חֲכָמִים קְצָת וְאֵינָם בְּקִיאִים כָּל כָּךְ. \u0010y0\u0011 \u0010c1\u0011 וְהָאִדָּנָא דְּלֵיכָּא מֻמְחִין, אֵינוֹ נִשְׁחָט עַל פִּי ג' בְּנֵי הַכְּנֶסֶת אֶלָּא בְּמוּמִין מֻבְהָקִים, כְּגוֹן נִסְמֵית עֵינוֹ וְנִקְטְעָה יָדוֹ וְכַיּוֹצֵא בָּהֶן. וּצְרִימַת הָאֹזֶן הוּא מוּם מֻבְהָק הֵיכָא דְּמִנְכָּר שַׁפִּיר \u0010c2\u0011 וְנִרְאֶה לָעֵינַיִם שֶׁהוּא יוֹתֵר מֵחֲגִירַת הַצִּפֹּרֶן. וְכֵיצַד צְרִימַת הָאֹזֶן, שֶׁנִּפְגְּמָה בְּחִסָרוֹן מִן \u0010c3\u0011 הַתְּנוּךְ, \u0010c4\u0011 וְלֹא הָעוֹר שֶׁבִּשְׂפַת הָאֹזֶן, בֵּין שֶׁנִּפְגְּמָה בִּידֵי אָדָם בֵּין שֶׁנִּפְגְּמָה בִּידֵי שָׁמַיִם. \u0005הַגָּה: \u0010y1\u0011 נֶחְתַּךְ הַזָּנָב לְמַעְלָה מִן הַחוּלְיָא, הָוֵי מוּם (פִּסְקֵי מהרא\"י סי' רמ\"ו)\u0006. \u0010y2\u0011 וְעוֹד מָנָה בַּעַל הַטּוּר כַּמָּה מוּמִין שֶׁשּׁוֹחֲטִין עֲלֵיהֶן בַּזְּמַן הַזֶּה, וְהָרַב שֶׁחִבֵּר סֵפֶר הַזֶּה נִמְשַׁךְ אַחַר דִּבְרֵי הַרַמְבַּ\"ם; וְלִי נִרְאֶה דְּהַסּוֹמֵךְ עַל דִּבְרֵי הַטּוּר הַבְּנוּיִין עַל דַּעַת הָרֹא\"שׁ לֹא הִפְסִיד.",["\u0003והאידנא דליכא מומחה. \u0004משום דמומחה צריך להיות בקי ג\"כ בראיית העין לבדקם ולבקר בהם היטב וגם מומחה היינו שנטל רשות מנשיא שבא\"י להתיר בכורות במומין והאידנא ליכא נשיא בא\"י. הרא\"ש:","\u0003נחתך הזנב למעלה מן החוליא הוי מום. \u0004אבל מן החוליות ולמטה לצד שער הזנב לא הוי מום:","\u0003ועוד מנה בעל הטור כו'. \u0004עיין בעט\"ז שהביא כל המומין שהם מומין אליבא דכ\"ע וביאורן:"],["\u0003אינם רשאים. \u0004משום הפסד קדשים שהרי יש לו היתר ע\"י נפילת מום כ\"כ הרא\"ש:","\u0003והאידנא דליכא מומחין.\u0004 משום דמומחה דאמרי' לאו דידע הלכות מומין בלחוד אלא דבקי גם בראות עין לבדקם ולבקר בהם היטב עוד טעם אחר דמומחה דהיינו שנטל רשות מנשיא שבא\"י להתיר בכורים והאידנא ליכא נשיא. אשר\"י:\n(ב) \u0003אלא במומין מובהקין כו'. \u0004בטור כתוב אבל דוקין שבעין וחורד ומים הקבועים לא פירוש חורד פירש\"י בגמ' שיש שם טפות לבנות בעין מים שעיניו נוטפות מים הקבועים קאי אתרווייהו:","\u0003ונראה לעינים שהוא יותר מחגירת צפורן. \u0004שדבר זה גלוי ונראה לכל רואה ואף ע\"ג שאח\"כ כתב הטור עד שתחגור בו הצפורן היינו לענין דינא אבל השתא דליכא מומחה לא סגי עד שיהיה ניכר שהוא יותר:","\u0003התנוך. \u0004בפרשת מצורע פירש רש\"י גדר האמצעי שבאוזן רצונו לומר הוא הגבוה שבאמצע האוזן שהוא עשוי כעין גדר בפני נקב האוזן:","\u0003ולא העור שבשפת האוזן. \u0004ששם הדר בריא והיינו באליה רכה שבאוזן שנקראת עור. כן כתב רש\"י:"]],["הַשּׁוֹחֵט אֶת הַבְּכוֹר שֶׁלֹּא עַל פִּי חָכָם, אֲפִלּוּ הֶרְאָהוּ לְחָכָם \u0010c0\u0011 אַחַר כָּךְ וּמָצָא בּוֹ מוּם, אָסוּר. וְהוּא הַדִּין בַּזְּמַן הַזֶּה, אִם לֹא הֶרְאָהוּ לִשְׁלֹשָׁה בְּנֵי הַכְּנֶסֶת.\nהַשּׁוֹחֵט הַבְּכוֹר \u0010c1\u0011 שֶׁלֹּא עַל פִּי \u0010y0\u0011 מֻמְחֶה, וּמְכָרוֹ וַאֲכָלוּהוּ, מַחֲזִיר לָהֶם הַדָּמִים; לֹא אֲכָלוּהוּ, \u0010c2\u0011 יִקָּבֵר וְיַחֲזִיר לָהֶם הַדָּמִים.\nמִי שֶׁאֵינוֹ מֻמְחֶה, וְרָאָה אֶת הַבְּכוֹר, וְנִשְׁחַט עַל פִּיו, \u0010c3\u0011 יִקָּבֵר וִישַׁלֵּם מִבֵּיתוֹ. וְכַמָּה יְשַׁלֵּם, \u0010y1\u0011 אִם הוּא בְּאֶרֶץ יִשְׂרָאֵל מְשַׁלֵּם \u0010c4\u0011 בְּגַסָה חֲצִי דָּמָיו, וּבְדַקָּה רְבִיעַ דָּמָיו; וּבְחוּץ לָאָרֶץ, בֵּין בְּדַקָּה בֵּין בְּגַסָה חֲצִי דָּמָיו. וְהָאִדָּנָא, שֶׁאַף בְּאֶרֶץ יִשְׂרָאֵל אֵין רֹב שָׂדוֹת שֶׁל יִשְׂרָאֵל, מֻתָּר לְגַדֵּל בְּהֵמָה דַּקָּה אֲפִלּוּ בְּאֶרֶץ יִשְׂרָאֵל, הִלְכָּךְ אֲפִלּוּ בְּאֶרֶץ יִשְׂרָאֵל אַף בְּדַקָּה מִשַּׁלֵּם חֲצִי דָּמִים.",["\u0003ומכרו ואכלוהו כו'. \u0004וכ\"ש לא אכלוהו שמחזיר להם הדמים וע\"ל סי' קי\"ט ס\"ק כ\"ה:","\u0003אם הוא בא\"י כו'. \u0004שאסור לגדל בהמה דקה בא\"י וכמו שנתבאר בח\"מ סי' תי\"ט הלכך קנסינן ליה דלא לשקול אלא פלגא א\"נ כיון שאסור לגדל בהמה דקה בא\"י א\"כ היה לו טורח גדול לגדלה בחורשים ובמדברות במקום שאינו ישוב הלכך די לו בחצי דמים של בהמה גסה:"],["\u0003ומצא בו מום אסור. \u0004בטור הביא קצת דעות דפסקו כרבי יהודה דדוקא בדוקין שבעין אסור מפני שהם משתנין דמפני צער מיתה משתנה העין ואע\"ג דהשתא מתחזי קבוע אי הוה חזי ליה מחיים הוה מתחזי מום עובר והרמב\"ם והרא\"ש פסקי כר\"מ דבכל מומין אסור גזירה אטו מום המשתנה:","\u0003שלא על פי מומחה. \u0004נראה דדין זה אפי' אם מראהו לחכם אח\"כ ומצא בו מום כפי מה שנזכר בסעיף א' אפ\"ה חייב להחזיר לו הדמים ואע\"ג דבזה אסור משום גזירה לחוד ובסי' קי\"ט לעיל כתב דכל שאיסורו מדברי סופרים מה שאכל אכל מ\"מ כיון שאיסור הנאה הוא אפי' בדברי סופרים מחזיר הדמים כמבואר שם:","\u0003יקבר ויחזיר כו'. \u0004נראה דיחזיר למוכר והמוכר יקברנו לא מבעיא אם המוכר חפץ בכך פשיטא דחייב לתת לו דהוא רוצה לקיים המצוה כההיא דפ' החובל (בבא קמא דף צ\"א) שורי הרגת אתה אמרת לי להורגו פטור ומוקי לה בשור העומד להריגה וקא טעין ליה אנא בעינא למיעבד מצוה בממוני ה\"נ כן הוא בבשר זה העומד לקבורה ואם אינו חפץ בכך מ\"מ הטירחא עליו כיון שהוא הגורם לזה וא\"ל דלא יתן לו כיון שהוא נחשד על כך דלא נחשד לאכלו או שימכרנו לאחר אחר שאוסרו עליו ואע\"פ שמתחלה מכרו באיסור לא דמי קודם שאסרוהו עליו דהיה סבור שיש היתר לשחוט על פי מום שלא הראה לחכם ואי ידעינן ביה דמזיד הוא נראה דבזה ודאי מכריזינן עליה שלא לקנות בשר ממנו כמבואר בסימן קי\"ט במכר דברים אסורים בסעיף ט\"ו ועל אכילה פשיטא שלא נחשד שיאכלנו דמבואר שם בסעיף ב' דחשוד למכור איסור מותר לאכול עמו דאינו נחשד על אכילה בשביל כך. כנ\"ל:","\u0003יקבר וישלם. \u0004פי' אותו האיש שראה המום ישלם:","\u0003בגסה חצי דמיו. \u0004שהרויח הכהן המזונות שהיה צריך להוציא עליו אילו לא נשחט לפיכך די בחצי דמיו ובדקה בא\"י שאסור לגדל שם דקה כי אם ביערים וכמו שכתוב בח\"מ סי' תי\"ט נמצא שהיה לו טורח גדול על כן סגי ברביע:"]],["הֶחָשׁוּד לִמְכֹּר בְּכוֹר לְשֵׁם חֻלִּין, אֵין קוֹנִים מִמֶּנּוּ \u0010y0\u0011 בְּשַׂר צְבָאִים, \u0010c0\u0011 שֶׁדּוֹמֶה לִבְשַׂר עֲגָלִים. וְאֵין לוֹקְחִים מִמֶּנּוּ עוֹרוֹת שֶׁאֵינָם עֲבוּדִים, אֲפִלּוּ שֶׁל נְקֵבָה, שֶׁמָּא יַחְתֹּךְ זִכְרוּתוֹ וְיֹאמַר: שֶׁל נְקֵבָה הוּא. וְאֵין לוֹקְחִין מִמֶּנּוּ צֶמֶר, \u0010y1\u0011 אֲפִלּוּ מְלֻבָּן. אֲבָל לוֹקְחִין מִמֶּנּוּ \u0010c1\u0011 צֶמֶר טָווּי וּלְבָדִים וְעוֹרוֹת עֲבוּדִים.",["\u0003בשר צבאים שדומה לבשר עגלים. \u0004ויש לחוש שמא מוכר בשר בכור של עגלים:","\u0003אבל לוקחים ממנו כו'. \u0004מפני שאינו עושה מלאכות אלו בשל בכור שהוא מפחד לשהות אצלו שמא ישמעו הדיינים ויקנסוהו כפי רשעו והוא מקפיד מלהפסיד טרחו:"],["\u0003שדומה לבשר עגלים. \u0004וחיישינן שימכור בשר עגל בכור תם ויאמר של צבי הוא:","\u0003צמר טווי. \u0004דטירחא גדולה יש בזה והוא לא טרח נפשיה דחושש שיוודע הדבר לחכמים ויפסידו ממנו וכל שכן אם הוא אריג שיש טירחא יותר וזהו הטעם בעורות עבודים שאינו מטריח לעבוד עור בכור תם:"]],["הַנּוֹטֵל שָׂכָר לִהְיוֹת רוֹאֶה בְּכוֹרוֹת, אֵין שׁוֹחֲטִין עַל פִּיו אֶלָּא אִם כֵּן הָיָה מֻמְחֶה גָּדוֹל וְיָדְעוּ בּוֹ חֲכָמִים שֶׁאֵין כְּמוֹתוֹ, \u0010c0\u0011 וּפָסְקוּ לוֹ שָׂכָר עַל הָרְאִיָּה וְהַבִּקּוּר. וְצָרִיךְ שֶׁיִּתְּנוּ לוֹ שְׂכָרוֹ, בֵּין יִהְיֶה הַמּוּם קָבוּעַ וְיַתִּירֶנּוּ, \u0010c1\u0011 בֵּין אִם לֹא יִהְיֶה קָבוּעַ. \u0010y0\u0011 וְלֹא יִתְּנוּ לוֹ שָׂכָר עַל הַבְּהֵמָה אֶלָּא פַּעַם אַחַת, \u0010c2\u0011 וְרוֹאֶה אוֹתָהּ לְעוֹלָם, כָּל זְמַן שֶׁמְּבִיאִין אוֹתָהּ, כְּדֵי שֶׁלֹּא יָבֹא לִידֵי חֲשָׁד. \u0010c3\u0011\nאֵין הֶחָכָם רוֹאֶה בְּכוֹר לְעַצְמוֹ. \u0010y1\u0011\nאֵין רוֹאִין מוּמִין בְּיוֹם טוֹב. אֲבָל אִם רָאָהוּ מֵעֶרֶב יוֹם טוֹב, יָכוֹל לַחֲקֹר עָלָיו בְּיוֹם טוֹב הֵיאָךְ נָפַל בּוֹ הַמּוּם.",["\u0003ולא יתנו לו שכר על הבהמה אלא פעם א' כו'. \u0004שאל\"כ כשלא היה מתירו היו אומרים זה מום קבוע הוא ואותו שלא התירו היינו כדי שיבא אליו עוד פעם אחרת וישלם לו פעם שנית:","\u0003אין רואין מומין ביו\"ט כו'. \u0004וע' מדינים אלו בא\"ח סי' תצ\"ח ס\"ט:"],["\u0003ופסקו לו שכר כו'. \u0004בטור כתוב והוא שיהיה שכר בטילתו ניכר ואם הוא פועל ומבטל ממלאכתו כדי לראות נותן לו שכרו כפועל שיש לו מלאכה כזו שבטל ממנה וכמה הוא רוצה ליקח כדי לישב בטל כן יתן לו עכ\"ל ובסי' קע\"ז לא כתב הטור כן אלא אומדין כמה אדם בטל רוצה ליקח ולעשות עסק זה ובח\"מ גבי השבת אבידה בסי' רס\"ד כתב כמה אדם רוצה ליקח לבטל ממלאכתו ולעשות מלאכה זו דהשבת אבידה וצריך טעם למה חילק בזה ביניהם והלא בגמרא אמרי' בכל הנהו תלת חד לישנא דישלם כפועל בטל של אותה מלאכה דבטיל מינה ובתוס' פ' איזהו נשך הבאתים בסי' קע\"ז כתבו דדוקא גבי אבק רבית הקילו ודי בזה שישלם לו כאדם בטל לגמרי וכמו שביארנו שם דבריהם לפי פירושו של הטור ולפי פי' ב\"י אך אסיקו שם בתוס' מ\"מ בהשבת אבידה צריך ליתן כפירש\"י דהיינו כמה אדם רוצה לפחות ממלאכה כבידה שהוא רגיל בה ולעסוק במלאכה קלה כזו וא\"כ נוטל שכר גם על השבת אבידה אע\"ג שאין ליקח שכר על זה מ\"מ כיון שהוא מתבטל ממלאכה ועל כרחך צריך ליתן לו ביטול שלו הותר לו גם ליקח שכר על ההשבה וכן לענין דן את הדין דאמרינן עליה נוטל שכרו כפועל בטל דהיינו הך שמביא הטור כאן לענין ראיית בכור ג\"כ כיון שמבטל ממלאכה יכול ליטול שכר ע\"כ וא\"כ צ\"ע על הטור למה כתב כאן כאלו יושב בטל ולא כתב שיכול ליטול שכר על הראיה עצמה כיון שמתבטל ממלאכה ונראה דהטור ס\"ל דבראיית בכור אין שייך כלל מלאכה על כן אין שייך כאן רק לומר כמה יקח וישב בטל ועל ההליכה שהולך לראות נראה פשוט שהיתר גמור ליקח שכר עליה כדאיתא בסוף פרק האיש מקדש כאן בשכר הבאה ומילוי כו':","\u0003בין אם לא יהיה קבוע. \u0004מפני החשד:","\u0003ורואה אותה לעולם. \u0004הטור כתב זה בשם הרמב\"ם ותמה הב\"י שהרי תלמוד ערוך הוא דתרי זימני לא תקינו ליה רבנן ולא קשה מידי דבגמ' (ס\"ד) [י\"ל] דלא תקינו ליה שכר אבל הוא אינו חייב לראות פעם אחרת וכן הוא באמת לחד תירוצא בתוס' שם קמ\"ל הרמב\"ם דחייב לראות לעולם:","\u0003אין החכם רואה בכור לעצמו. \u0004הטעם מפני החשד וקשה לי ממה שכתב רמ\"א [סי' י\"ח] סעיף י\"ח שנהגו בקצת מקומות שאין אדם שוחט ובודק לעצמו משמע דמדינא מותר:\n\u0003שוב \u0004ראיתי שבפרק ב' דנגעים הקשה גם הר\"ש כן וחילק בין היכא דאיתחזק איסורא כו' ובזה מתורץ נמי במה שבודק לעצמו דכיון דנשחטה הותרה ולא איתחזק איסורא וכי תימא א\"כ על השחיטה לא יהיה נאמן לעצמו דהא בהמה בחייה בחזקת איסור עומדת בזה סמכינן על רוב מצויין אצל שחיטה מומחין הן כמו שכתב המרדכי ריש חולין ע\"ש:"]],["\u0010y0\u0011 אָסוּר לְהַטִּיל מוּם בִּבְכוֹר; אֲפִלּוּ לִגְרֹם לוֹ מוּם, כְּגוֹן לִתֵּן דְּבֵלָה עַל גַּבֵּי אָזְנוֹ כְּדֵי שֶׁיִּטְּלֶנָּה הַכֶּלֶב מִשָּׁם וְיִקְטַע אָזְנוֹ עִמָּהּ וְכַיּוֹצֵא בָּזֶה, אוֹ שֶׁאוֹמֵר לְעוֹבֵד כּוֹכָבִים לְהַטִּיל בּוֹ מוּם. וְאִם עָשָׂה מוּם בְּיָדַיִם אוֹ בִּגְרָמָתוֹ, \u0010y1\u0011 אֵין שׁוֹחֲטִין אוֹתוֹ עַל יָדוֹ עַד שֶׁיִּפֹּל בּוֹ מוּם אַחֵר מֵעַצְמוֹ. וְאִם מֵת, \u0010c0\u0011 אֵין קוֹנְסִין בְּנוֹ אַחֲרָיו, אֶלָּא שׁוֹחֲטִין אוֹתוֹ עַל יָדוֹ.\nאִם עוֹבֵד כּוֹכָבִים אוֹ תִּינוֹק מַטִּיל בּוֹ מוּם מֵעַצְמוֹ, אִם לֹא כִּוֵּן לְהַתִּירוֹ, \u0010y2\u0011 \u0010c1\u0011 מֻתָּר, אֲפִלּוּ אִם שָׁאַל: לָמָּה אֵין שׁוֹחֲטִין אוֹתוֹ, וְהֵשִׁיבוּ לוֹ לְפִי תֻּמָּם שֶׁאָסוּר לְשָׁחֲטוֹ \u0010c2\u0011 עַד שֶׁיִּפֹּל בּוֹ מוּם. אֲבָל אִם כִּוֵּן לְהַתִּירוֹ, כְּגוֹן לְאַחַר שֶׁרוֹאֶה שֶׁהִתִּירוּהוּ עַל יְדֵי כָּךְ עוֹשֶׂה כֵּן לַאֲחֵרִים, אָסוּר. \u0005סָפֵק אִם כִּוֵּן לְהַתִּירוֹ אוֹ לֹא, אַזְלִינָן לְקֻלָּא (הַגָּהוֹת מָרְדְּכַי \u0010y3\u0011 דְּחֻלִּין)\u0006. וְאִם עוֹבֵד כּוֹכָבִים מֵסִיחַ לְפִי תֻּמּוֹ וְאוֹמֵר \u0010c3\u0011 שֶׁהַיִּשְׂרָאֵל צִוָּהוּ, אָסוּר \u0005(ת\"ה סי' קס\"ט)\u0006.\nאִם אָמְרוּ לְעוֹבֶדֶת כּוֹכָבִים הַמְשָׁרֶתֶת בְּבֵית יְהוּדִי, עַל הַבְּכוֹר, שֶׁאֵין לְאָכְלוֹ בְּלֹא מוּם, וְהָלְכָה וְחָתְכָה אָזְנוֹ, חָשׁוּב לָדַעַת וְאֵין שׁוֹחֲטִין אוֹתוֹ עָלָיו, \u0010y4\u0011 מִפְּנֵי שֶׁעוֹבֶדֶת כּוֹכָבִים זוֹ כִּוְּנָה לְהַתִּירוֹ, וְגַם הָאוֹמְרִים לָהּ שֶׁאֵינוֹ נֶאֱכָל בְּלֹא מוּם כִּוְּנוּ לְכָךְ שֶׁתַּטִּיל בּוֹ מוּם. \u0005הַגָּה: מֻתָּר לִתֵּן בְּכוֹר לְעוֹבֵד כּוֹכָבִים כְּדֵי לְגַדְּלוֹ, וְאִם הִטִּיל הַשּׁוֹמֵר בּוֹ מוּם, \u0010y5\u0011 \u0010c4\u0011 מֻתָּר, וְלֹא אַמְרִינָן דְּכִוֵּן לְהַתִּירוֹ, אַף עַל פִּי שֶׁיּוֹדֵעַ שֶׁנִּתָּר בְּמוּמוֹ וְשֶׁהוּא בְּכוֹר (פִּסְקֵי מהרא\"י סי' קס\"ח)\u0006.\nהָיָה הַבְּכוֹר רוֹדְפוֹ, וּבָעַט בּוֹ וְעַל יְדֵי כֵן עָשָׂה בּוֹ מוּם, מֻתָּר לְשָׁחֲטוֹ עָלָיו. \u0010y6\u0011 \u0010c5\u0011 וַאֲפִלּוּ בָּעַט בּוֹ לְאַחַר שֶׁנִּצַּל מִמֶּנּוּ.\nדְּבַר תּוֹרָה, בְּכוֹר שֶׁנָּפַל בּוֹ מוּם עוֹבֵר, \u0010c6\u0011 מֻתָּר לְהַטִּיל בּוֹ מוּם קָבוּעַ, אֲבָל חֲכָמִים אֲסָרוּהוּ.\nבְּכוֹר שֶׁאָחֲזוֹ דָּם, יַקִּיז וּבִלְבָד שֶׁלֹּא יִתְכַּוֵּן לַעֲשׂוֹת מוּם. וְאִם נַעֲשָׂה בּוֹ \u0010c7\u0011 מוּם בְּהַקָּזָה זוֹ, הֲרֵי זֶה נִשְׁחָט עָלָיו. \u0010y7\u0011\nמֻתָּר לְהַטִּיל מוּם בִּבְכוֹר בַּזְּמַן הַזֶּה \u0010c8\u0011 קֹדֶם שֶׁיָּצָא לַאֲוִיר הָעוֹלָם.",["\u0003אסור להטיל כו'. \u0004דכתיב כל מום לא יהיה בו ודרשינן לא יהיה בו. (היו\"ד הראשונה בשו\"א והה\"א בפת\"ח):","\u0003אין שוחטין אותו כו'. \u0004דחכמים קנסוהו לדידיה ולא לבנו ולפי זה נראה דאם שחטוהו בדיעבד הבשר מותר לאחרים:","\u0003אפילו אם שאל כו'. \u0004וה\"ה אפילו בלא שאלת העובד כוכבים אלא הם עצמם מסיחים לפי תומם ואומרים ראה לא ישחט זה לעולם אלא ע\"י מום ולא נתכוונו לכך שיטיל בו מום הכי אמרינן בש\"ס ורש\"י:","\u0003ואם עובד כוכבים מסיח לפי תומו כו'. \u0004ואע\"ג דלעיל סי' ט\"ז סעיף י\"א אמרינן דאין עובד כוכבים מסל\"ת נאמן לעדות אפילו לאיסור וא\"ל דשאני הכא דהוי איסור דרבנן דלהקל שייך לחלק בין איסור דאורייתא לדרבנן כדלעיל סי' צ\"ח ס\"ק ב' אבל להחמיר איפכא מסתברא דכ\"ש דבדרבנן אינו נאמן להחמיר וי\"ל דשאני הכא דכיון דאזלינן בתר אומדנא היכא דחזינן דכוון העובד כוכבים להתיר אסור א\"כ אומדן דעת הוא דהעובד כוכבים מסל\"ת אומר אמת דאל\"כ ל\"ל שהטיל בו מום:","\u0003מפני שהעובדת כוכבים זאת כוונה כו'. \u0004פירש הב\"ח דכיון דהעובדת כוכבים משרתת בבית עליה מוטל לשרת לבעל הבית בכל מה שהוא הנאתו וטובתו של בעה\"ב א\"כ מסתמא לא נתכווונה אלא להתיר וגם האומרים לה נתכוונו לכך דאל\"כ כיון שיודעים שודאי תעשה כן א\"כ היה להם ליזהר שלא יאמרו כדברים האלה לפני העובדת כוכבים ומדלא נזהרו אלמא דכל כוונתם לא היתה באמירה זו לפני העובדת כוכבים המשרתת אלא כדי שתטיל בו מום:","\u0003ולא אמרינן דכוון כו'. \u0004דהא ודאי לא כוון להתירו דאדרבה הוא רוצה שלא ישחטוהו דהא לגדלו כוונו והוא היה מקבל שכרו אם יגדלו יותר. כתוב בד\"מ שמצא בתשובת א\"ז על בכור שמסרו ישראל לשומר עובד כוכבים והודיעו שהוא בכור ולו משפט מות לקברו שלם בעורו ועובדי כוכבים חוקרים הענין ומודיעין כי במומו כשר וסופו מוכיח כי בא העובד כוכבים במרמה לבעל הבכור ואמר ליה דע כי סרסתי העגל ושתק היהודי והבין העובד כוכבים כי באמת הדבר ולא עוד אלא שבא היהודי וראה שאינו מסורס ושתק וכראות העובד כוכבים הלך וסרסו אח\"כ מיד אותו בכור מותר גמור הוא וכן משמע במתני' דבכורות עד כאן ומביאה המעדני מלך:","\u0003ואפי' כו'. \u0004לא אמרינן כדי להתירו נתכוין להטיל בו מום אלא אמרינן צעריה הוא דקא מדכר. ש\"ס:","\u0003מותר להטיל כו'. \u0004ומבואר בש\"ס דאע\"פ שיצא מקצת אבריו כל זמן שלא יצא רובו או ראשו בענין דהוי כילוד ובאופן שנתבאר לעיל סימן י\"ד ולקמן סימן שי\"ט מותר לעשות בו מום כגון גדי שאזניו ארוכים ונראים בחוץ קודם שיצא כל ראשו שעדיין אינו כילוד יכול לצרום אזנו קודם שיצא רוב ראשו וכן כל כיוצא בזה והב\"ח לקמן סוף סימן שי\"ט כתב דלהרמב\"ם דלמפרע הוא קדוש אסור להטיל בו מום בבכור אלא בפנים כשלא יצא לאויר העולם כלל ולא משמע הכא מהרמב\"ם והמחבר לקמן סימן שי\"ט וכ\"נ מדברי רש\"י פרק המקשה (דף ע' ע\"א) דאפילו למ\"ד למפרע הוא קדוש מותר להטיל בו מום קודם שיצא רובו לאויר העולם וכן כתב הרשב\"א בחידושיו שם דף ע\"ג להדיא דעד שיצא רובו אינו קדוש והלכך אינו כמטיל מום בקדשים ע\"כ:"],["\u0003אין קונסין בנו אחריו. \u0004דלדידיה קנסוהו ולא לבנו ובגמ' שם אמרי' דאפי' במידי דלאו קנסא אלא דין תורה רק שהוא היזק שאינו ניכר אין בנו חייב אחריו:","\u0003אפי' אם שאל כו'. \u0004במתני' הכי איתא מעשה בזכר של רחלים זקן ושערו מדולדל וראהו קסדור אחד ואמר מה טיבו של זה שהניחוהו נהזקין כ\"כ אמרו לו בכור הוא ואינו נשחט אא\"כ היה בו מום נטל פיגם פי' רומח וצרם אזנו ובא מעשה לפני חכמים והתירו פירש\"י שהרי אין לומר שהעובד כוכבים הזה להתירו נתכוין שהרי אינו יודע שע\"י מום שיעשה בו ישחט אא\"כ נפל מאליו ואחר שהתירו הלך וצרם באזני בכורות אחרים ואסרו העתקתי משנה זאת לעיין מה בינה לדין שכתב בסעיף ג' אם אמרו לעובד כוכבים כו' דהוא מתשובת הרא\"ש כלל כ' ואמר שם דל\"ד למתני' דבמתני' לא כוון להתיר וכאן כוונה להתיר וצ\"ע מה נשתנה מעשה זה מזה ולכאורה נראה מלשון הטור והש\"ע דשאני ההוא דהרא\"ש שהיתה העובדת כוכבים משרתת ובודאי נתכוונה לטובת אדונה זה אינו חדא דבתשובת הרא\"ש שם לא הוזכר כלל שהיתה משרתת אלא סתם עובדת כוכבים ואי הוה דבר עיקרי במה שהיא משרתת ודאי לא הוה שתיק מיניה ותו דאם נאמר דהרא\"ש היה מפרש כפירש\"י במתני' דהקסדור לא היה יודע שישחט ע\"י מום זה אא\"כ נפל מאליו למה לא נאמר גם במשרתת כך וכי בשביל שהיא משרתת היא יודעת טפי ואם נאמר שלא היה מפרש כפירש\"י קשה מה היתר היה במעשה דקסדור כיון שלפי הנראה נתכוין להתיר כיון שעשה מעשה ע\"י שאלה זאת וג\"כ א\"ל דבמעשה דהרא\"ש אמרו לעובדת כוכבים בלא שאלה שלה תחלה זה אינו דבגמ' אמרי' בהדיא שלא לדעת מותר לאתויי מסל\"ת פירש\"י שלא שאלם קסדור מה טיבו אלא הם עצמם מסיחים לפי תומם ואומרים ראה לא ישחט זה לעולם אלא ע\"י מום ולא נתכוונו לכך שיטיל בו מום א\"כ חזינן דא\"צ שאלה להיתר זה א\"כ למה אסר הרא\"ש במעשה שלו והנלע\"ד דזה תלוי על פי מה שמצינו בפרק הנזקין באגדת החורבן דאמרי' שם דוכתא דלדידן הוה מום ולדידהו לא הוה מום ופירש\"י דלדידהו לא הוה מום אלא במחוסר אבר וזה הוא ההיתר במעשה דקסדור לפי דעת הרא\"ש לא כפירש\"י אלא הטעם כיון דהקסדור לא חיסר שום אבר אלא ניקבו ברומח לאוזן והוא לא ידע שע\"י כך יתירוהו ע\"כ לא אסרו רק עד אחר שראה שהתירו בכך משא\"כ במעשה דהרא\"ש שחתכה עובדת כוכבים האוזן והוא מחוסר אבר וזה גלוי להם שהוא מום בודאי כיוונה להתיר ובטור נמי אפשר לפרש דבריו בדרך זה והיינו מה שכתבתי אבל כוון להתיר כגון לאחר שרואה שניתר ע\"י כך כן היא הגירסא וכ\"ה בש\"מ וחילוק זה נכון הוא והטור קיצר במקום שהיה לו לבאר עוד אבל האמת יורה דרכו כמו שכתבתי כנ\"ל:","\u0003עד שיפול בו מום. \u0004בגמ' איתא דאפי' אמר עד שנעשה בו מום מותר ולא אמרי' דמשמעותו שאתה תעשה בו מום שם אזלינן לקולא כיון דאינו אלא קנס דרבנן אפי' בודאי:","\u0003שהישראל צוהו כו'. \u0004משמע אפי' אם הישראל מכחישו ואומר לא צויתיך והוא תמוה דלא עדיף עובד כוכבים מסל\"ת מישראל שאינו נאמן לאסור של חבירו בכיוצא בזה כדאיתא בסי' רפ\"א באומר ס\"ת שכתבתי לא כתבתי האזכרות לשמן דאינו נאמן ושם בפסקי מהרא\"י סי' קס\"ט ששם מקור דין זה איתא בכה\"ג שאמרה העובדת כוכבים שיהודי א' צוה לאמה שתעשה צרימת אוזן בבכור ויהיה מותר בשביל כך לשחוט וכן עשתה דאסור ושם לק\"מ אפי' אם היהודי מכחישה דמ\"מ כיון שיודעת שהבכור ניתר בכך ולשם כך עשתה יש איסור מחמת שעשתה להתיר עכ\"פ אפי' אם הציווי שקר ע\"כ מהני מסל\"ת של עובד כוכבים בזה משא\"כ באין ידוע שהיא יודעת שניתר בכך רק שהאיסור מצד הציווי דהיה אסור כאלו עשאו הישראל בעצמו בזה ודאי קשה למה לא תועיל הכחשה של ישראל וע\"כ לומר דמיירי כאן באין הישראל לפנינו להכחישו כנלע\"ד:","\u0003ולא אמרינן דכוון להתירו. \u0004משמע אפי' בכהן מותר בזה וצ\"ע למה יהיה נאמן בזה והלא חשוד להטיל מום בעצמו ק\"ו שיאמר לעובד כוכבים להטיל בו מום ושם בפסקי מהרא\"י כתוב דין זה בישראל שיש לו ספק בכור ע\"כ צ\"ע גבי כהן בזה:","\u0003ואפי' בעט בו לאחר שניצל ממנו. \u0004דצעריה הוא דקא מדכר וכוונתו להנקם לחוד וזה דעת הרמב\"ם ובהרא\"ש כ\"כ בשם רמב\"ן והוא ט\"ס וצ\"ל רמב\"ם ובזה ניחא קושיית ב\"י על הטור ודעתו למחוק בטור כל דעת הרמב\"ם אלא תחלה:","\u0003מותר להטיל בו מום. \u0004שנאמר תמים יהיה לרצון להקרבה אז לא יעשה בו מום משא\"כ ביש בו מום אע\"פ שהוא עובר:","\u0003מום בהקזה זו. \u0004זהו כר' שמעון אבל הרא\"ש והתוס' פסקו כרבנן דסבירא להו באם הוא שהקזה מצילתה מן המיתה ממילא אף קודם ההקזה חשיבה כבעלת מום והיינו מום עובר כיון שיש לה רפואה ומ\"מ מהני האי מום עובר שיכול להקיזה ולהטיל עליה אפי' מום קבוע אפי' מדרבנן משום פסידא ולאחר המום שנעשה ע\"י ההקזה אע\"פ שהוא קבוע אין שוחטין עליו גזירה שמא לפעמים תוכל להתרפאות בהקזה במקום שאין עושה מום אלא צריך כאן מום קבוע אחר כדי לשחוט עליו ור\"ש לא ס\"ל גזירה זאת:","\u0003קודם שיצא לאויר העולם. \u0004דאינו נעשה קודש אלא ביציאתו מרחם ובזמן הבית היה אסור משום הפסד קדשים:"]],["\u0010y0\u0011 \u0010c0\u0011 הַכֹּהֲנִים חֲשׁוּדִים לְהַטִּיל מוּם בִּבְכוֹר. אֲפִלּוּ אִם הוּא חָכָם וְיוֹשֵׁב בִּישִׁיבָה, אִם עָשָׂה דָּבָר שֶׁנִּרְאֶה כְּמַעֲרִים, כְּגוֹן שֶׁנָּתַן לִבְכוֹר שְׂעוֹרִים בְּסַל בְּעִנְיָן שֶׁכְּשֶׁיָּבֹא לְאָכְלָם נִפְגָּם שְׂפָתוֹ אוֹ כַּיּוֹצֵא בָּזֶה, אֵין לְשָׁחֲטוֹ עַל אוֹתוֹ הַמּוּם. \u0005וּלְפִיכָךְ כָּל מוּם שֶׁרָאוּי לְבֹא בִּידֵי אָדָם, אֵין שׁוֹחֲטִין אוֹתוֹ עָלָיו, עַד שֶׁיָּעִידוּ שֶׁמֵּעַצְמוֹ נָפַל בּוֹ. (טוּר)\u0006.\nכָּל הַמּוּמִין הָרְאוּיִם לָבוֹא בִּידֵי אָדָם, נֶאֱמָן הָרוֹעֶה עֲלֵיהֶם לוֹמַר: מֵאֲלֵיהֶם נָפְלוּ וְלֹא נַעֲשׂוּ בְּכַוָּנָה, וְיִשְׁחַט עֲלֵיהֶם. \u0010y1\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיָה הָרוֹעֶה יִשְׂרָאֵל וְהַבְּכוֹר בְּיַד הַכֹּהֵן; אֲבָל אִם הָיָה הָרוֹעֶה כֹּהֵן וְהַבְּכוֹר עֲדַיִן הוּא בְּיַד בְּעָלָיו הַיִּשְׂרָאֵל, הֲרֵי זֶה אֵינוֹ נֶאֱמָן, וְחוֹשְׁדִין אוֹתוֹ שֶׁמָּא הוּא הִטִּיל בּוֹ כְּדֵי שֶׁיִּתְּנֶנּוּ לוֹ. \u0010y2\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּרוֹעֶה כֹּהֵן נֶאֱמָן עַל בְּכוֹר שֶׁל יִשְׂרָאֵל, וְיֵשׁ לְהָקֵל (טוּר בְּשֵׁם הָרֹא\"שׁ וְהָרַמְבַּ\"ן)\u0006.\nכֹּהֵן שֶׁהֵעִיד לְכֹהֵן אַחֵר שֶׁמּוּם זֶה מֵאֵלָיו נָפַל, נֶאֱמָן, וְאֵין חוֹשְׁשִׁין לָהֶם \u0010y3\u0011 שֶׁמָּא הֵם גּוֹמְלִים זֶה אֶת זֶה. \u0010c1\u0011\nאֲפִלּוּ בָּנָיו וּבְנֵי בֵּיתוֹ שֶׁל כֹּהֵן, מְעִידִין לוֹ עַל הַבְּכוֹר; אֲבָל לֹא אִשְׁתּוֹ, מִפְּנֵי שֶׁהִיא כְּגוּפוֹ.\nעֵד שֶׁהֵעִיד מִפִּי עֵד אַחֵר שֶׁמּוּם זֶה נָפַל שֶׁלֹּא לְדַעַת, נֶאֱמָן. אֲפִלּוּ אִשָּׁה נֶאֱמֶנֶת לוֹמַר: בְּפָנַי נָפַל מוּם זֶה מֵאֵלָיו, וְיִשָּׁחֵט עָלָיו.\nלֹא הָיוּ מֻחְזָקִים בּוֹ שֶׁהוּא בְּכוֹר, וְאָמַר הַכֹּהֵן: בְּכוֹר הוּא זֶה \u0010c2\u0011 וּמוּם זֶה נָפַל בּוֹ מֵעַצְמוֹ, \u0010y4\u0011 נֶאֱמָן.\nבְּכוֹר שֶׁהָיָה בְּיַד כֹּהֵן, וְנָפַל בּוֹ מוּם, \u0010y5\u0011 וְהֵעִיד עָלָיו עֵד אֶחָד שֶׁזֶּה הַמּוּם מֵאֵלָיו נָפַל, וְאֵין אָנוּ יוֹדְעִים אִם מוּם זֶה שׁוֹחֲטִין עָלָיו אֶת הַבְּכוֹר, וּבָא הַכֹּהֵן שֶׁהוּא בְּיָדוֹ וְאָמַר: \u0010y6\u0011 \u0010c3\u0011 הֶרְאֵיתִי מוּם זֶה \u0005 (לְמֻמְחֶה)\u0006 וְהִתִּירוֹ לִשְׁחִיטָה, הֲרֵי זֶה נֶאֱמָן, וְאֵין חוֹשְׁשִׁין שֶׁמָּא לֹא הֶרְאָהוּ.\nוְכֵן נֶאֱמָן הַכֹּהֵן לוֹמַר עַל בְּכוֹר בַּעַל מוּם: בְּכוֹר זֶה \u0010y7\u0011 נְתָנוֹ לִי יִשְׂרָאֵל בְּמוּמוֹ, וְאֵין חוֹשְׁשִׁין שֶׁמָּא הוּא הִטִּילוֹ, דְּמִלְּתָא דַּעֲבִידָא לְגַלּוֹיֵי לָא מְשַׁקְּרֵי בַּה אִנְשֵׁי.\nנֶאֱמָן יִשְׂרָאֵל לוֹמַר: נָתַתִּי בְּכוֹר זֶה לְכֹהֵן בְּמוּמוֹ, אֲפִלּוּ הָיָה טָלֶה וְהִגְדִּיל וְלֹא חַיְשִׁינָן שֶׁמָּא אֵינוֹ מַכִּירוֹ. \u0010y8\u0011 \u0010c4\u0011\nיִשְׂרָאֵל לֹא נֶחְשְׁדוּ עַל הַבְּכוֹרוֹת, אֲפִלּוּ שֶׁלָּהֶם. לְפִיכָךְ יִשְׂרָאֵל \u0010y9\u0011 שֶׁיֵּשׁ לוֹ סְפֵק בְּכוֹר שֶׁנֶּאֱכַל בְּמוּמוֹ לַבְּעָלִים, נֶאֱמָן לוֹמַר שֶׁנָּפַל בּוֹ מוּם מֵעַצְמוֹ.\nאֵין רוֹאִין אֶת הַבְּכוֹר לְיִשְׂרָאֵל עַד שֶׁיְּהֵא כֹּהֵן עִמּוֹ, שֶׁמָּא יֹאמַר לוֹ הַמֻּמְחֶה: מוּם הוּא וּמֻתָּר לִשְׁחֹט עָלָיו, וְיֵלֵךְ וְיִשְׁחֲטֶנּוּ לְעַצְמוֹ וְלֹא יִתְּנֶנּוּ לַכֹּהֵן, שֶׁאַף עַל פִּי שֶׁאֵינוֹ חָשׁוּד לֶאֱכֹל קָדָשִׁים בַּחוּץ, חָשׁוּד הוּא לִגְזֹל מַתְּנוֹת כְּהֻנָּה. לְפִיכָךְ אִם הָיָה חָכָם וְיָדוּעַ שֶׁהוּא מְדַקְדֵּק עַל עַצְמוֹ, רוֹאִים לוֹ. \u0005וְכֵן אִם\u0006 הָיָה הַמּוּם גָּלוּי לַכֹּל, כְּגוֹן שֶׁנִּקְטְעָה יָדוֹ אוֹ רַגְלוֹ, הוֹאִיל וֶהֱבִיאוֹ לְחָכָם הַמֻּמְחֶה הֲרֵי זֶה בְּחֶזְקַת מְדַקְדֵּק עַל עַצְמוֹ, לְפִיכָךְ רוֹאִים לוֹ אַף עַל פִּי שֶׁאֵין עִמּוֹ כֹּהֵן.",["\u0003הכהנים חשודים כו'. \u0004מפני שיש לו טורח גדול לטפלותו עד שיומם:","\u0003בד\"א כשהיה הרועה כו'. \u0004ולא חיישינן שאומר כן כדי שיאכילנו ממנו:","\u0003וי\"א כו'. \u0004דלא חיישינן שהטיל בו כדי שיתננו לו דסתם רועים עם הארץ הן ומימר אמר לא שביק צורבא מרבנן ויהיב לדידי אלא יתננו לכהן אחר ב\"ח () [צ\"ל ת\"ח. ובזה סרה תמיהת התפל\"מ]:","\u0003שמא הם גומלים כו'. \u0004שיעידנו עכשיו והוא יגמול לו כשיתן לו ישראל בכור תם ויטיל בו מום ויבא כהן זה ויעידנו שמאליו נפל בו מום:","\u0003נאמן. \u0004שהפה שאסר הוא הפה שהתיר:","\u0003והעיד עליו עד אחד כו'. \u0004כתב הב\"ח מיהו ודאי היכא דלא ידעינן דבכור זה ניתן לכהן זה בלא מום אין צריך להביא עדים שיעידו על המום דנאמן במגו דמה לו לשקר אי בעי אמר ישראל נתנו לו במומו וצל\"ע בזה למאי דפסק לקמן דצריך שיאמר ישראל פלוני דוקא אם כן אין כאן מגו דמיסתפי שמא ישאלנו ויתבדה משא\"כ הכא שאומר שמעצמו נפל אין כאן מי שיכחישנו:","\u0003הראיתי מום זה. \u0004לחכם והתירו לשחיטה אע\"פ שאינו מזכיר שם החכם נאמן ודוקא במומין שאינן מובהקין דלא חיישינן שיתיר מעצמו ויאמר החכם התיר לי דקדשים בחוץ לא אכיל ולמיסמך עלויה במומין שאינן מובהקים לא עבדי אינשי ובודאי הראהו לחכם ושרי ניהליה ולא הוה שרי ליה חכם אלא א\"כ העידו לפניו דהאי מום נפל בו מאליו עד כאן לשון הרא\"ש (וכן פסק הב\"ח) וכן כתב רבינו ירוחם סוף נתיב כ' בשם ה\"ר יונה ומביאו בב\"ה ונ\"ל להגיה גם בדברי הרא\"ש כן וכתב הר\"ר יונה וכן מה שכתב הטור בשם הר\"ר יונה שאם הוא מום מובהק נאמן אע\"פ שאינו מזכיר שם החכם צ\"ל שאם אינו מובהק כו' והשתא ניחא הא דמסיק הטור דצריך שיעידו עדי' שנפל בו מום שהרי מדברי הרא\"ש אינו מבואר דלא הוי שרי ליה חכם אלא אם כן העידו לפניו דהאי מום נפל בו מאליו ובזה נסתלקה ג\"כ קושית הב\"ח סעיף ה' וסעיף ח' על הטור ע\"ש אבל במומין מובהקין דמ\"מ צריך להראותו לחכם וכדלעיל סימן ש\"ט אם כן ליכא למימר דודאי קדשים בחוץ לא אכיל דהא יודע שאינו קדשים כיון דמום מובהק הוא והלכך יש לחוש שמא לא הראהו לחכם אבל כשמזכיר שם החכם נאמן דלא משקר דמילתא דעבידא לגלויי הוא שהרי יכולין לשואלו מיהו להמחבר לקמן סעיף ח' וסייעתו דבישראל א\"צ לומר ישראל פלוני א\"כ ה\"ה הכא בכל ענין נאמן אפי' אינו מזכיר שם חכם:","\u0003נתנו לי ישראל כו'. \u0004ודעת הרא\"ש וטור ורבינו ירוחם שצריך לומר ישראל פלוני וכתב הב\"ח דמסתבר טעמייהו ונראה שכתב כן לפי מה שתירן הב\"י לדעת הרמב\"ם שדבריו דחוקים מאד גם בספר מעדני מלך דף ר\"ס ע\"ב הקשה עליו ע\"ש אבל באמת דעת הרמב\"ם נראה נכונה שהרי ר' יהודה לא הזכיר בדבריו ישראל פלוני וברייתא דקתני קח לי ממומחה פלוני היינו כפירש\"י והרא\"ש משום דאל\"כ מצי משתמיט ולמימר אי לדידך לא מהימן לדידי מהימן וזה לא שייך בישראל דכשיאמר בעליו אני לא מסרתיו אלא כשהוא תם שוב אין לו התנצלות וכן נראה מבואר מדברי מעדני מלך שם שזהו דעת הרמב\"ם ע\"ש:","\u0003ישראל לא נחשדו כו'. \u0004דאין נהם טורח שיש לטרחותן קצבה ל' בדקה ונ' בגסה כדלעיל סי' ש\"ו ס\"ב:","\u0003שיש לו ספק בכור.\u0004 דא\"צ ליתנו לכהן משום דהמע\"ה אבל אי הוה ודאי בכור צריך ליתנו לכהן ופשיטא דהיה נאמן עליו דהרי אינו שלו:"],["\u0003הכהנים חשודים כו'. \u0004הטעם בטור לפי שיש בו טורח גדול ליטפל בו עד שיומם כו' פירוש אבל ישראל יכול ליתנו לכהן אם עשה דבר כו' פי' וכ\"ש במום שבא שלא על ידי כך דפשיטא שאין נאמן אלא אפי' להערמה חוששין וע\"כ מסיק ולפיכך כל מום כו':","\u0003אפילו בניו כו'. \u0004זה כרבי שמעון בן גמליאל דס\"ל אפי' בנו אפי' בתו ור' יוסי ס\"ל אין בני ביתו מעידין עליו ופסק רב נחמן כר' שמעון בן גמליאל ורבא כר' יוסי ואמרינן בתר הכי אמר רבא כל בעלים עומדים עמנו בחוץ ובכור נכנס שלם כו' והביא הטור דברי רבא אלו דאם עומדים בחוץ כו' ותמה ב\"י דהא רבא לטעמיה דס\"ל כר' יוסי אבל לרבי שמעון בן גמליאל אפי' היו בני ביתו שם יכולין להעיד ונאמנים הם ומש\"ה השמיט הרמב\"ם מימרא זאת ולענ\"ד דיש נפקותא לדינא מדברי רבא אפי' לדידן דקי\"ל כרשב\"ג דהא דארשב\"ג אפי' בנו אפי' בתו נאמן היינו בדליכא ריעותא דהערמה לפנינו אבל אי איכא ריעותא כי האי שהולך עם כל בני ביתו לחוץ ודוקא באותו פעם נכנס הבכור ויצא חבול אם היינו יודעים שא' מבני ביתו נשאר שם ודאי חשדינן שע\"כ הוציא השאר והשאיר זה שהוא יטיל בו מום ודאי היינו חושדין אותו אפי' לרבי שמעון בן גמליאל דהערמה גדולה יש כאן אלא דאם אין אנו יודעין שנשאר שם לא חיישינן שמא נטמן ורבותא זאת קמ\"ל אפי' לר' יוסי כנלע\"ד ומו\"ח ז\"ל תירץ דקמ\"ל הטור רבותא דאע\"פ שאין שם בני בית להעיד שהרי כולם בחוץ אפ\"ה מותר לשחוט ולא חיישינן שמא עבד או עובד כוכבים א' מבני הבית נטמן שם ואין זה מתיישב דא\"כ היה לו לומר אפי' כולם בבית רק שאין יודעין מן המום היאך נעשה מותר כיון שהבעל עצמו אינו בבית והם אינם חשודים ותו למה כתב שמא א' נטמן שם הטמנה זאת ללא צורך היא דאפי' ידענו שהוא שם למה נחוש שהרי אין חשד אלא על הבעל עצמו לרבי שמעון בן גמליאל ומה שתיקן ואמר שמא עובד כוכבים או עבד נטמן שם זה אינו במשמע לשון של א' מבני הבית ולמאי דפרישית ניחא דכל היכא דאיכא ריעותא גדולה כזו לפנינו ודאי היינו חוששים אפי' לרשב\"ג כל שידענו בבירור שנשאר שם א' אלא דלהטמנה לא חיישינן:","\u0003ומום זה נפל כו'. \u0004דהפה שאסר הוא הפה שהתיר:","\u0003הראיתי מום זה כו'. \u0004סעיף זה הוא ל' הרמב\"ם ואיתא במתני' נאמן הכהן לומר הראיתי בכור זה לחכם ובעל מום הוא פי' שאמר ליה שמום קבוע הוא אמר רב יהודה נאמן הכהן לומר בכור זה נתן לי ישראל במומו כו' עד מתיב רב שיזבא האומר למי שאינו נאמן על המעשר קח לי ממי שהוא נאמן אינו נאמן אמאי נימא כל מלתא דעבידא לגלויי כו' שאני התם דאית ליה לאשתמוטי ולמימר אי לדידך לא מהימן אנא הוה חשבינא ליה מהימן הלכך לא מרתת מעיקרא סיפא ודאי מסייע ליה מאיש פלוני ה\"ז נאמן כיון שהזכיר לו שם המשלח הנאמן ה\"ז נאמן השליח דחייש שמא יתבענו ונמצאתי משקר וזה מסייע לרב יהודה ודחינן שאני התם דאיכא תובע ומרתת פי' מרתת שליח כיון דחזי דקפיד משלח להזכיר שם האיש סבר ודאי יתבענו אבל גבי בכור לא מרתת כהן דסבר מי טריח לחפש אחר דברי ולשאול לאותו ישראל אם נתנו לי במומו. וכתב הרא\"ש דבמתני' וכן בדר' יהודה לא מהני אא\"כ מזכיר ג\"כ שם החכם המומחה דאל\"כ לא מרתת וכתב ב\"י דס\"ל להרא\"ש אע\"ג דדחי סייעתא דרב יהודה ממתני' דמעשר לא מידחיא מימריה כיון דלא מצית לאותובי מינה ומ\"מ לא מהימנינן ליה אלא בגוונא דמהימנינן במתני' דמעשר שצריך שיזכיר שם האיש והרמב\"ם ס\"ל דא\"צ שיזכיר הכהן שם החכם כפשטא דלישנא ושאני התם במעשר דאיכא איסור דאורייתא אבל בהטלת מום בבכור אפי' במזיד אינו אלא דרבנן סגי בכל דהו קשה לפי זה מאי פריך רב שיזבא ממעשר דלמא שאני התם דאיסור דאורייתא הוא לא סמכינן להקל בשביל לא משקר ותו דגם בטור משמע דלא ס\"ל כן כדברי רמב\"ם שהרי כתב תחלה כהרא\"ש שצריך להזכיר שם החכם בפרטות ואח\"כ כתב י\"א כשאומר חכם פלוני שהוא נאמן אפי' אין עדים מעידים על המום שמעצמו נפל בו אבל רש\"י פירש דוקא שיש עדים על המום וכ\"כ הרמב\"ם וקשה טובא דמשמע מדבריו אפילו לרמב\"ם בעינן שיזכיר שם החכם ואפ\"ה בעינן עדים וזה אינו דהרמב\"ם א\"צ זכרון שם חכם כמו שכתב ב\"י ודלמא מש\"ה בעינן דוקא עדים אבל כשמזכיר שם חכם דאז נאמן משום דמרתת א\"כ א\"צ עדים דמסתמא לא התיר אותו אא\"כ היו שם עדים דזה לשון הרמב\"ם פ\"ב דבכורות בכור שהיה ביד כהן ונפל בו מום והעיד עליו עד אחד שזה המום נפל ואין אנו שוחטין על מום זה אם לא יבא הכהן שהיה בידו ואמר הראיתי מום זה למומחה והתירו לשחיטה ה\"ז נאמן ואין חוששין שמא לא הראהו שלא נחשד לשחוט קדשים בחוץ מפני שהוא עון כרת וכן נאמן הכהן לומר על בכור בעל מום בכור זה נתנו לי ישראל במומו ולא נפל ברשותי ואין לחוש שמא הוא הטילו שהדבר עשוי להגלות והוא מתירא שמא ישאלו בעליו ויאמרו תמים היה בעת שנתנוהו לו עכ\"ל הרי שבסיפא נתן טעם משום דמרתת וברישא נתן טעם משום עון כרת ע\"כ דברישא מיירי שלא הזכיר שם המומחה וא\"כ קשה על הטור מנא ליה לכתוב לדעת הרמב\"ם דבעינן שם פלוני וגם עדות על שלא הטילו בידים דלמא בהא סגי בלא עדות וכמו להי\"א שמביא הטור לא הוצרך עדות אלא במקום שלא שייך מירתת כגון שלא הזכיר שם המומחה ועל הרמב\"ם עצמו קשה למה לא הזכיר בסיפא שיזכיר שם הישראל וכמ\"ש הטור דבלא\"ה לא שייך מרתת ונראה דהרמב\"ם מיירי בסיפא שידוע לנו מי הוא אותו ישראל שנתן לכהן הבכור אלא שמסופק אם נתנו בתמימות או במומו ובזה שפיר מרתת שמא ישאלוהו ובזה מכוונים דבריו בסיפא שכתב שמא ישאלו בעליו ויאמרו תמים היה משמע שדבר זה לבדו הוא ספק אבל אין לנו ספק מי הוא הנותן משא\"כ בטור מיירי שהספק הוא מי נותנו ע\"כ לא שייך מרתת מצד ספק זה וע\"כ צריך שיזכיר שם הישראל ולפ\"ז איירי הרמב\"ם בתרי מילי מתחלה קמ\"ל דיש לנו היתר מצד חומר העון ובזה א\"צ שם המומחה וצריך עדות על שנפל ממילא כי בזה הוא נחשד והיינו אוקימתא דמתני' ואע\"פ שאמרו זה בגמ' דרך דחייה מ\"מ היא סברא נכונה ואח\"כ כתב דין ההיתר מכח מירתת דשם מזכיר שם ישראל הנותנו וכמו שכתבתי וא\"כ קשה על הרמב\"ם כיון דעיקר הרבותא בסיפא להשמיענו דין מרתת וזכירת השם של ישראל היה לו לומר דבר זה גם ברישא והכי הוי ליה למכתב בסיפא וכן אם מזכיר שם המומחה נאמן הוא וא\"צ עדות על הנפילה מעצמו דמתיר כו' אלא ע\"כ דברישא לא מהני הזכרת שם המומחה לפטור אותו מעדות דאפשר שאותו המומחה לא התיר לו לגמרי אלא שאמר לו מום זה הוא מום קבוע לשחיטה אחר שיביא עדות על שנפל מאליו משא\"כ בסיפא שמהני שפיר טעם דמרתת לפטרו מעדות שנתן לו הישראל א\"כ מוכח דס\"ל לרמב\"ם כרש\"י נמצא הכל ניחא בסייעתא דשמיא ודלא כראיתי דחוקים בזה:","\u0003ישראל לא נחשדו כו'. \u0004לפי מה שכתב הטור הטעם ר\"ס זה דהכהנים חשודים משום שיש בו טורח גדול ליטפל בו עד שיומם נ\"ל דמה שכתב כאן ביש לישראל ספק בכור כו' דהיינו במקום שלא פשע בו אבל אם פשע בו דהיינו כפי מ\"ש רמ\"א בסי' ש\"ז סעיף ד' דאז א\"צ הכהן לקבלו ממילא צריך הישראל ליטפל בו אז הוה כעם ככהן ואפי' הישראל אינו נאמן לומר מום נפל בו כמו הכהן כנ\"ל:"]],["סָפֵק בְּכוֹר, אֵין הַבְּעָלִים צְרִיכִים לִתְּנוֹ לַכֹּהֵן, אֶלָּא יַשְׁהֶנּוּ עַד שֶׁיִּפֹּל בּוֹ מוּם, \u0010y0\u0011 וְיֹאכְלֶנּוּ. וְאָסוּר בְּגִזָּה וַעֲבוֹדָה. וְאִם תְּקָפוֹ כֹּהֵן, \u0010y1\u0011 אֵין מוֹצִיאִין אוֹתוֹ מִיָּדוֹ. \u0005הַגָּה: \u0010y2\u0011 \u0010c0\u0011 וְיֵשׁ אוֹמְרִים דְּמוֹצִיאִין אוֹתוֹ מִיַּד הַכֹּהֵן (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006 \u0010y3\u0011 וְכֵן הִלְכְתָא. \u0010y4\u0011 וַאֲפִלּוּ אִם נְתָנוֹ לוֹ הַיִּשְׂרָאֵל בַּטָּעוּת, שֶׁהָיָה סָבוּר שֶׁצָּרִיךְ לִתְּנוֹ לוֹ, וְאַחַר כָּךְ נוֹדַע לוֹ, צָרִיךְ הַכֹּהֵן לְהַחֲזִיר לוֹ \u0005(פִּסְקֵי מהרא\"י סִימָן קס\"ו)\u0006.\nיוֹצֵא דֹּפֶן וְשֶׁנּוֹלַד אַחֲרָיו דֶּרֶךְ רֶחֶם, \u0010y5\u0011 שְׁנֵיהֶם אֵינָם בְּכוֹר; אֲפִלּוּ יָלְדָה נְקֵבָה תְּחִלָּה דֶּרֶךְ דֹּפֶן, וְזָכָר אַחֲרֶיהָ דֶּרֶךְ רֶחֶם, כֵּיוָן שֶׁקְּדָמוֹ אַחֵר. בְּכוֹר שֶׁהוּא \u0010y6\u0011 טֻמְטוּם, הֲרֵי זֶה סְפֵק בְּכוֹר \u0010y7\u0011 וְיֵאָכֵל בְּמוּמוֹ לִבְעָלָיו. וְדַוְקָא בְּמֵטִיל מַיִם בִּמְקוֹם נַקְבוּת, אֲבָל אִם מֵטִיל מַיִם בִּמְקוֹם זַכְרוּת, בְּכוֹר וַדַּאי הוּא וְצָרִיךְ לִתְּנוֹ לַכֹּהֵן \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ וְלֹא כְּרַמְבַּ\"ם)\u0006. \u0010y8\u0011\nאַנְדְּרוֹגִינוּס הוּא סָפֵק בְּכוֹר, וְיֵאָכֵל בְּמוּמוֹ לַבְּעָלִים.\nמְבַכֶּרֶת שֶׁיָּצְאָה מְלֵאָה וְחָזְרָה רֵיקָנִית, הַבָּא אַחֲרֶיהָ בְּכוֹר, מִסָפֵק, שֶׁמָּא הִפִּילָה דָּבָר שֶׁאֵינוֹ פּוֹטֵר מֵהַבְּכוֹרָה.\nרָחֵל שֶׁיָּלְדָה כְּמִין עֵז, אוֹ עֵז שֶׁיָּלְדָה \u0010c1\u0011 כְּמִין רָחֵל, פְּטוּרָה מֵהַבְּכוֹרָה, שֶׁנֶּאֱמַר: אַךְ בְּכוֹר שׁוֹר \u0005(וַיִּקְרָא כז, כו)\u0006 עַד שֶׁיִּהְיֶה הוּא שׁוֹר וּבְכוֹרוֹ שׁוֹר. וְאִם הָיָה בּוֹ מִקְצָת סִימָנֵי אִמּוֹ, הֲרֵי זֶה בְּכוֹר וְהוּא בַּעַל מוּם קָבוּעַ, שֶׁאֵין לְךָ מוּם גָּדוֹל מִשִּׁנּוּי בְּרִיָּתוֹ \u0005(לְשׁוֹן רַמְבַּ\"ם פ\"ה מהל' בְּכוֹרוֹת ד\"ו)\u0006.\nפָּרָה שֶׁיָּלְדָה כְּמִין חֲמוֹר, וְיֵשׁ בּוֹ מִקְצָת סִימָנֵי פָּרָה, הֲרֵי זֶה בְּכוֹר לַכֹּהֵן, הוֹאִיל וּמִין הַחֲמוֹר יֵשׁ בּוֹ דִּין בְּכוֹר. אֲבָל אִם יָלְדָה מִין סוּס אוֹ גָּמָל, אַף עַל פִּי שֶׁיֵּשׁ בּוֹ מִקְצָת סִימָנֵי פָּרָה, הֲרֵי הוּא סְפֵק בְּכוֹר; \u0010c2\u0011 לְפִיכָךְ יֵאָכֵל לִבְעָלָיו, וְאִם תְּפָסוֹ כֹּהֵן אֵין מוֹצִיאִין מִיָּדוֹ. וְהוּא הַדִּין לַחֲמוֹר שֶׁיָּלְדָה כְּמִין סוּס, וְיֵשׁ בּוֹ מִקְצָת סִימָנֵי חֲמוֹר, הֲרֵי זֶה סְפֵק בְּכוֹר. \u0005וּכְבָר נִתְבָּאֵר דְּנָקְטִינַן דְּאִם תְּקָפוֹ כֹּהֵן מוֹצִיאִין מִיָּדוֹ.\u0006\nבְּהֵמָה דַּקָּה שֶׁטִּנְּפָה, דְּהַיְנוּ שֶׁנִּמּוֹחַ הָעֻבָּר וְיָצָא \u0010y9\u0011 הַמִּחוּי, פְּטוּרָה מֵהַבְּכוֹרָה. וְצָרִיךְ לְהַרְאוֹתוֹ לְרוֹעֶה חָכָם שֶׁיִּרְאֶה אִם הוּא מִחוּי וָלָד. \u0010y10\u0011 וּבְהֵמָה גַּסָה שֶׁהִפִּילָה שִׁלְיָא, פְּטוּרָה מֵהַבְּכוֹרָה; וְהַשִּׁלְיָא עַצְמָהּ אֵין בָּהּ קְדֻשָּׁה, וּמֻתָּר לְהַאֲכִילָהּ לִכְלָבִים. שָׁפְעָה חֲרָרַת דָּם, פְּטוּרָה מֵהַבְּכוֹרָה. \u0010y11\u0011 וְהַחֲרָרָה תִּקָּבֵר, \u0010c3\u0011 לְפַרְסְמָהּ שֶׁהִיא פְּטוּרָה מֵהַבְּכוֹרָה.",["\u0003ויאכלנו. \u0004מיהו חייב במתנות כהונה ממ\"נ ודוקא בספק בכור אבל כשנסתפק בשנים איזהו מהן בכור והוצרך ליתן א' מהן לכהן השני פטור מן המתנות כיון דחליפיו ביד כהן עשו שאינו זוכה כזוכה כמו שנתבאר כל זה לעיל סי' ס\"א ס\"ק (י') [י\"א]:","\u0003אין מוציאין. \u0004דהשתא ה\"ל הישראל המוציא ועליו להביא ראיה:","\u0003וי\"א דמוציאין כו'.\u0004 שכיון שהישראל יש לו עכ\"פ חזקה דטובת הנאה ליתנן למי שירצה בכל מקום שהוא הוא בחזקתו והכהן לעולם מוציא ועליו להביא ראיה:","\u0003וכן הלכתא. \u0004ולעיל סי' ס\"א סעיף כ\"ג לא כתב הרב דהכי הלכתא וע\"ש ס\"ק (י\"ב) [י\"ג] מה שכתבתי בזה:","\u0003ואפי' אם נתנו כו'. \u0004כלומר לא מבעיא תקפו בע\"כ דמוציאין מידו אלא אפילו נתנן מעצמו צריך להחזיר לו דהוה נתינה בטעות:","\u0003שניהם אינם בכור. \u0004זה מפני שלא קדש ברחם וזה אינו בכור לכל בניה:","\u0003הרי זה ספק. \u0004שהרי הוא ספק זכר ספק נקבה:","\u0003ויאכל במומו כו'. \u0004וזה שהוא טומטום לא הוי מום מפני שדרכו לקרוע:","\u0003אנדרוגינוס. \u0004אע\"ג דבעלמא קי\"ל דבריה בפ\"ע הוא ואינו לא בכלל זכר ולא בכלל נקבה ולפ\"ז לא הוי בכור כלל מכל מקום כיון דפליגי ביה הפוסקים יש פוסקים שהוא בכלל נקבה () הכא גבי בכור אזלינן לחומרא ואמרינן שהוא בספק בכור ואינו נגזז ונעבד ואינו נאכל אלא כשיולד בו מום אחר שהוא קבוע וזה שהוא אנדרוגינוס לא הוי מום ועיין לעיל סי' קצ\"ד סעיף ח':","\u0003פטורה. \u0004אח\"כ מהבכורה דהולד שהיה במיחוי זה פטור:","\u0003ובהמה גסה כו'. \u0004פטורה אח\"כ מהבכורה שאין שליא בלא ולד וכן חררת דם:","\u0003והחררה תקבר. \u0004אבל בשליא א\"צ לקברה שהכל יודעים שאין שליא בלא ולד:"],["\u0003וי\"א דמוציאין. \u0004פי' הואיל שמתחלה לא בא לידו בהיתר לא מיקרי תפיסה הואיל והוא עצמו היה לו ספק בשעת תפיסה ועיין מ\"ש מזה בסי' ס\"א סעיף כ\"א:","\u0003כמין רחל. \u0004פירש\"י לאו רחל ממש דהא נקבה לא נתקדשה בבכורה אלא מין רחל:","\u0003לפיכך יאכל לבעליו. \u0004שאין לך מום גדול משינוי ברייתא ע\"כ אין צריכין מום אחר כ\"כ ב\"י:","\u0003לפרסמה. \u0004אבל בשליא א\"נ פרסום דכ\"ע ידעי דשליא חשוב כולד לפי שאין שליא בלא ולד:"]],["הַלּוֹקֵחַ בְּהֵמָה מֵהָעוֹבֵד כּוֹכָבִים, וְאֵין יָדוּעַ אִם בִּכְּרָה וְיָלְדָה, הֲרֵי זֶה סְפֵק בְּכוֹר, וְיֵאָכֵל בְּמוּמוֹ לַבְּעָלִים, וְאֵינוֹ לַכֹּהֵן, שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. בֵּין אִם לְקָחָהּ \u0010y0\u0011 תּוֹךְ שָׁנְתָה, אוֹ אַחַר שְׁנָתָהּ, \u0010y1\u0011 וַאֲפִלּוּ אִם הָעוֹבֵד כּוֹכָבִים \u0010c0\u0011 מֵסִיחַ לְפִי תֻּמּוֹ שֶׁכְּבָר בִּכְּרָה, אֵינוֹ נֶאֱמָן. \u0010y2\u0011 \u0005וְסִימָנִים \u0010y3\u0011 שֶׁבְּחִדְקֵי קַרְנֶיהָ אֵין מַעֲלֶה וְלֹא מוֹרִיד לִסְמֹךְ עֲלֵיהֶם (הַגָּהוֹת מָרְדְּכַי פ' הָאִשָּׁה)\u0006. \u0010y4\u0011\nלָקַח בְּהֵמָה מֵינִיקָה מֵהָעוֹבֵד כּוֹכָבִים, אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא בְּנָהּ שֶׁל אַחֶרֶת הִיא \u0010y5\u0011 מֵינִיקָה, אֶלָּא הֲרֵי זוֹ בְּחֶזְקָת שֶׁיָּלְדָה. וַאֲפִלּוּ הָיָה זֶה שֶׁמֵּינִיקָה כְּמוֹ מִין אַחֵר, וַאֲפִלּוּ כְּמִין חֲזִיר, פְּטוּרָה מֵהַבְּכוֹרָה.\nוְכֵן בְּהֵמָה שֶׁהִיא חוֹלֶבֶת, פְּטוּרָה מֵהַבְּכוֹרָה, \u0010c1\u0011 שֶׁרֹב הַבְּהֵמוֹת אֵינָן חוֹלְבוֹת אֶלָּא אִם כֵּן יָלְדוּ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵין סוֹמְכִין עַל מַה שֶּׁהִיא חוֹלֶבֶת (טוּר בְּשֵׁם ה\"ג וְהַגָּהוֹת מָרְדְּכַי פֶּרֶק הָאִשָּׁה)\u0006, וְכֵן פָּסְקוּ הָאַחֲרוֹנִים \u0005(מהרא\"י בִּפְסָקָיו סִימָן קס\"ו ובת\"ה סִימָן רע\"א ומהרי\"ו סִימָן קע\"ד)\u0006, וְכֵן נוֹהֲגִין בְּכָל מְדִינוֹת אֵלּוּ. מִיהוּ \u0010c2\u0011 אִם יֵשׁ עוֹד צַד הֶתֵּר לָזֶה, \u0010c3\u0011 אוֹ שֶׁעוֹבֵד כּוֹכָבִים מֵסִיחַ לְפִי תֻּמּוֹ שֶׁלֹּא לְהַשְׁבִּיחַ מִקְּחוֹ, וְאוֹמֵר שֶׁיָּלְדָה, סוֹמְכִין לְהַתִּיר. וְדַוְקָא בְּפָרוֹת, וּבְמָקוֹם שֶׁלֹּא נִשְׁמַע שֶׁחוֹלְבוֹת בְּלֹא וָלָד; אֲבָל בְּעִזִּים, שֶׁדֶּרֶךְ שֶׁחוֹלְבוֹת בְּלֹא וָלָד, לֹא סָמְכִינַן עַל כָּךְ \u0010y6\u0011 אֲפִלּוּ בְּמָקוֹם דְּאִכָּא סְפֵק סְפֵקָא, כְּגוֹן שֶׁיָּלְדָה ב' וְאִכָּא לְמֵימַר אָכַל אֶחָד דְּאֵינוֹ בְּכוֹר, \u0010c4\u0011 אֲפִלּוּ הָכִי אָסוּר \u0005(פִּסְקֵי מהרא\"י סִימָן ק\"ל)\u0006. ונ\"ל דִּבְמָקוֹם דְּאֵין דֶּרֶךְ הָעִזִּים בְּכָךְ, אוֹ שֶׁדֶּרֶךְ הַפָּרוֹת בְּכָךְ, אֵין לְחַלֵּק, וְיֵשׁ לַחֲקֹר אַחַר זֶה.\nבְּהֵמָה שֶׁרְאִינוּהָ חוֹלֶבֶת, \u0010y7\u0011 וְיָדַעְנוּ שֶׁלֹּא יָלְדָה, אִם אַחַר כָּךְ רְאִינוּהָ מֵינִיקָה וְלֹא יָדַעְנוּ אִם יָלְדָה אוֹתוֹ וָלָד אִם לֹא, \u0010y8\u0011 הֲרֵי זֶה בְּחֶזְקָת שֶׁיְּלָדַתּוּ.\nמִי שֶׁיֵּשׁ לוֹ בְּעֶדְרוֹ מַבְכִּירוֹת, וְשֶׁאֵין מַבְכִּירוֹת, וְיָלְדוּ, וְלֹא הָיָה שָׁם אָדָם, וּמוֹצֵא מַבְכִּירוֹת מֵינִיקוֹת נְקֵבוֹת וְשֶׁאֵינָן מַבְכִּירוֹת מֵינִיקוֹת זְכָרִים, אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא בְּנָהּ שֶׁל זוֹ בָּא לוֹ אֵצֶל זוֹ וְשֶׁל זוֹ אֵצֶל זוֹ, \u0010y9\u0011 אֶלָּא הַדָּבָר בְּחֶזְקָתוֹ שֶׁכָּל אַחַת מֵינִיקָה אֶת בְּנָהּ.\nהַלּוֹקֵחַ בְּהֵמָה מִיִּשְׂרָאֵל, הֲרֵי זֶה בְּחֶזְקַת שֶׁבִּכְּרָה, \u0010c5\u0011 עַד שֶׁיּוֹדִיעוֹ הַמּוֹכֵר שֶׁעֲדַיִן לֹא יָלְדָה. \u0010y10\u0011 \u0005וְיֵשׁ אוֹמְרִים שֶׁהוּא סְפֵק בְּכוֹר (טוּר בְּשֵׁם הָרֹא\"שׁ והר\"ר יוֹנָה)\u0006.",["\u0003תוך שנתה כו'. \u0004ולא אמרי' ודאי בכור הוא כיון דעדיין אינה בת שנה אם כן לא ילדה כבר:","\u0003ואפי' אם העובד כוכבים מסיח לפי תומו כו' \u0004דלהשביח מקחו אומר כן דבהמה שבכרה קונים אותה ביוקר מפני שחלבה היא טובה יותר ממבכרת ועוד שידועים בה שתסתכן בלידה עכ\"ל עט\"ז וכ\"כ הב\"ח אבל הדרישה כתב דהיכא דאיכא משום להשביח מקחו פשיטא דלא מהימן אלא אפי' במסיח לפ\"ת אפ\"ה אינו נאמן דלא עובד כוכבים נאמן במסיח לפ\"ת אלא באיסור דרבנן עכ\"ל וכן בפסקי מהרא\"י סי' ק\"ל וז\"ל ומטעם דעובד כוכבים מסל\"ת לא מלאני לבי לסמוך עליה לחודיה ואף ע\"ג דמשמע שפיר באשר\"י פ\"ג דבכורות דהא דלא מהימנינן עובד כוכבים מסל\"ת היינו טעמא משום דתלינן להשביח מקחו קמכוון הא איכא דמוכחא מילתא דלא מכוין לכך מהימן מ\"מ בי\"ד כתב סתם מסל\"ת לא סמכינן עליה ותו דאמרינן בפרק הגוזל בתרא דאין עובד כוכבים מסל\"ת כשר במילי דאורייתא אלא בעדות אשה בלבד וצ\"ע בדבר עכ\"ל והכי משמע מדברי הרב לקמן סעיף ג' דאפילו מסל\"ת שלא להשביח מקחו לא מהני אי לאו דחולבת וע\"ל סי צ\"ח ס\"ק ב':","\u0003וסימנים כו'. \u0004ולא עוד אלא אפילו מכיר שהיא זקנה אין חלב פוטר. שם ומביאו ד\"מ:","\u0003שבחדקי קרניה. \u0004וה\"ה שאר סימנים כיוצא באלו וכן משמע בעט\"ז:","\u0003לקח בהמה מניקה כו'. \u0004היינו שידענו שהיתה חולבת אף על פי שלא ילדה כבר דאל\"כ כיון דחולבת ופוטר בבכורה לדעת המחבר דרוב בהמות אינן חולבות אא\"כ יולדות וכמ\"ש המחבר בסעיף ג' א\"כ בלאו הכי פטור מבכורה וגם זה שמניקתו היה פטור מבכורה אפי' אי הוה נולד ברשות ישראל אלא ודאי כדאמרן וכן משמע בתוספות והרא\"ש ולא הוה צריך הרב לכתבו שכבר נתבאר זה לקמן סעיף ד' אלא משום סיפא דאפי' כמין חזיר נקט לה ודוק:","\u0003אלא הרי זו בחזקת שילדה כו'. \u0004לאו למימרא שהיא בחזקת שילדה ולד זה וכדכתב בעט\"ז דהא בש\"ס פ\"ג דבכורות (דף כ\"ד) מספקא אי אמרינן יולדת מרחמת או אינה מרחמת אא\"כ יולדתו וסלקא בתיקו להכי קאמר התם דכמין חזיר אסורה באכילה דדלמא יולדת מרחמת אע\"פ שלא ילדתו וכ\"כ הפוסקים והט\"ו לעיל סי' ע\"ט סוף סעיף כ\"ד במין טמא יונק וכרוך אחר הטהורה אסור שמא מן הטמאה נולד וכרוך אחריה אלא ר\"ל דאפילו לא ילדתו מ\"מ ודאי שילדה שום ולד וא\"כ הבא אחריו פטור מבכורה. ומ\"מ צ\"ע מ\"ש הרמב\"ם והט\"ו ואפי' היה זה שמניקה כו' כמין חזיר כו' דמשמע דיותר מסתבר בחזיר דלחייב בבכורה ובש\"ס התם אמרינן אדרבה איפכא מסתברא דאדרבה בחזיר יותר מסתברא דאפילו באכילה לישתרי משום די\"ל דכיון דלאו מינה הוא אינה מרחמת אא\"כ יולדתו ונ\"ל דמכל מקום מסתבר להו דבחזיר כיון דלאו מינה הוא אינה מרחמת וא\"כ זו שמרחמת ע\"כ מרחמת אע\"פ שלא ילדה כלל וא\"כ הוה מסתבר דחייב בבכורה קמ\"ל דאפילו הכי פטור משום דאדרבה איפכא מסתברא כיון דלאו מינה הוא אם כן טפי מסתבר לומר דילדתו וכדקאמר בש\"ס ודו\"ק:","\u0003אפילו במקום דאיכא ס\"ס כו'. \u0004לאו למימרא דס\"ס גמור לא מהני דהא ודאי ס\"ס שרי בכל דוכתא אלא ר\"ל ספק ספיקא כי האי דלא הוי ס\"ס גמור לא סמכינן אמה שחולבת וכן הוא בפסקי מהרא\"י והבאתיו לעיל סימן ק\"י דין ב' ע\"ש:","\u0003וידענו שלא ילדה. \u0004כלומר שחולבת אע\"פ שלא ילדה כבר לכך דוקא כשמניקת הרי היא בחזקת שילדתו וא\"כ גם הבא אחריו פטור מבכורה הא לאו הכי בלאו הכי הבא אחריו פטור מבכורה להמחבר ולדידן אפילו בסתמא אמרינן שחלב אינו פוטר אא\"כ ראינוה מניקה דאמרינן זה שמניקתו חייב בבכורה דשמא ילדתו עכשיו הואיל והוא כרוך אחריה והבא אחריו פטור בבכורה ממ\"נ וכדלקמן:","\u0003הרי זה בחזקת שילדתו. \u0004לאו למימרא דודאי ילדתו דליתא וכדלעיל סעיף ב' ס\"ק ו' אלא קאמר בחזקת ילדתו לאשמועינן דאותו ולד שילדה אח\"כ בבית ישראל חייב בבכורה דהרי הוא בחזקת שילדתו כלומר שמא ילדתו וכ\"כ הט\"ו לעיל סימן ט\"ז סעיף ה' אם הוא כרוך אחריה חזקה שהיא אמו וע\"כ ר\"ל שמא היא אמו ולענין אותו ואת בנו אסור לכתחלה אבל ודאי אמו ולענין מלקות לא וכמ\"ש שם בס\"ק ה' ואם כן ה\"ה הכא שזה שילדתו הוא ספק בכור ויאכל במומו לבעלים וכן מוכח בש\"ס ממאי דסלקא בתיקו אליבא דרשב\"ג ע\"ש וזה שבא אחריו פטור בבכורה ממ\"נ דאפי' תימא לא ילדתו מ\"מ אינה מרחמת עליו אלא א\"כ ילדה וכדלעיל סעיף ב':","\u0003אלא הדבר בחזקתו כו'. \u0004בכאן אמרינן ודאי הוא כן ולא הוי אפילו ספק בכור ולא אמרינן שמא יולדת מרחמת ולד אחר אף על פי שלא ילדתו זה אלא אמרינן במקום דידה לא שבקה דידה ומרחמת דלאו דידה והכי אמרינן בש\"ס:","\u0003וי\"א שהוא ספק. \u0004דשמא שכח מלהזהיר דלאו אדעתיה א\"נ שמא קא סבר דלשחיטה קא בעי לה ובזה א\"ש הא דלעיל סימן ט\"ז ס\"ז דאמרינן דמסתמא שרי דאל\"כ היה מודיעו שעל המוכר להודיעו משום דהתם נמי כי נימא דלשחיטה קא בעי לה אסור משום אותו ואת בנו וק\"ל:"],["\u0003מסיח לפי תומו. \u0004עיין מה שכתבתי בסעיף ג':","\u0003שרוב הבהמות אינן חולבות כו'. \u0004בטור כתוב ואם ראינוה שהיא חולבת אע\"פ שאינה יולדת ואח\"כ ראינוה מניקה כו'. פי' אפי' למאי דקי\"ל דאין חולבת אא\"כ יולדת מ\"מ אם אנו רואין באיזה פרה שחולבת ידענו שלא ילדה עדיין ומה שכתב הטור בזה אא\"כ יולדת זה פשוט ט\"ס וצ\"ל ילדה ועיין מה שכתבתי בסעיף ח':","\u0003אם יש עוד צד היתר כו'. \u0004עיין מה שכתבתי סוף סימן ש\"ך בשם פסקי מהרא\"י סי' ק\"ל:","\u0003או שעובד כוכבים מסל\"ת שלא להשביח כו'. \u0004כדי לחדש בזה דין אחר נברר הדברים בסייעתא דשמיא במעשה שהיה בא' שהיה לו חוב אצל עובד כוכבים ותבעו ואמר שאין לו מעות לשלם רק פרה אחת והוליכו לחצר והראה לו פרה אחת ועגל עומד אצלה אבל לא הניקה אותו ואמר העובד כוכבים פרה זאת בלא ולד אתן לך בעד ח' זהובים כי הולד אגדל לעצמי אמר הישראל אני חושב שפרה זאת זקנה היא וזה ולד ששי או שביעי שלה ואני חפץ בפרה ילדה וכל שהיא ילדה ביותר אוסיף בדמיה השיבו העובד כוכבים מה אומר לך שהיא ילדה ביותר זה אינו אבל מ\"מ אינה זקינה כל כך כמו שתאמר ותאמין לי שזה הוא ולד רביעי שלה לא יותר וקבלה ממנו ואח\"כ ילדה אצל הישראל מה דינו לכאורה הוא ספק בכור מאחר דאמרי' בסעיף א' דמסל\"ת אינו נאמן אבל מצאתי להיתר בסייעתא דשמיא אמרי' פ\"ג דבכורות דף כ\"א מצינו לוקח מעובד כוכבים מה דינו כדתנן במתני' שם לוקח מישראל מאי אמר רב בכור ודאי דאם איתא דבכרה אשתבוחי היה משתבח בה פירש\"י דהמוכר היה אומר קחנה שכבר בכרה והא דלא אשבח סבר דלשחיטה בעי לה ומבואר שיש כאן ט\"ס דהאי סברא היא לשמואל ולא לרב ושמואל אמר בכור ספק סבר לשחיטה קא בעי לה ור' יוחנן אמר חולין ודאי מ\"ט אם איתא דלא בכרה כיון דאיכא איסורא אודועי הוה מודע ליה ואע\"ג דלא קי\"ל כרב כמו שיתבאר סוף סימן זה מ\"מ יש לנו לומר דע\"כ לא פליגי שמואל ור' יוחנן על רב אלא במקום שיש סברא אחרת כנגד סברא זאת דאשתבוחי הוה משתבח דהיינו כיון דאיכא איסורא מודע הוה מודעינן ליה דרב ס\"ל הך סברא דהוה מודיע אינה סברא ועל כן אזלינן בתר סברא דהוה משתבח ושמואל ס\"ל דהנך סברות שקולים הם דהיינו אשתבוחי הוה משתבח הוה לאיסור ואיכא צד כנגדו דמודע הוה מודעינן ליה הוא הוכחה להיתר או דיש סברא לומר שסבר דלשחיטה בעי לה וא\"כ אין כאן שבח על כן עושה ספק מזה ור' יוחנן אלימא ליה סברא דהוה מודיע ליה ועל כן אזל בתרה אבל במקום דאין שם אלא סברא דאשתבוחי הוה משתבח למה לא ניזול בתרה ובזה הכל מודים לרב) וא\"כ בנדון דידן דאם איתא דהאי פרה היא ילדה ולא בכרה אצל העובד כוכבים והאי ולד שעמד אצלה אינה שלה היה לו להשתבח מקחו ולומר שהיא ילדה דאין כאן סברא מתנגדת לזה ומה שזכרנו דאין מסל\"ת נאמן הוא מדברי התוס' ואשר\"י שם בדברי רב דס\"ל אשתבוחי הוה משתבח וז\"ל פירוש הקונטרס שכבר בכרה ולא תסתכן בלידה עוד אבל עובד כוכבים אי נמי א\"ל הכי אין בדבריו אמת ויש ללמוד מפירושו דעובד כוכבים אפי' מסל\"ת אינו נאמן דלהשביח מקחו אומר כן עכ\"ל ונראה פירושו דהאי אבל עובד כוכבים כו' דעובד כוכבים כיון דאם אומר השבח אינו נאמן לנו ע\"כ אינו אומרו כלל דידע בעצמו שאין מאמינים לו משא\"כ בישראל ולפ\"ז כל היכא דלא להשביח מקחו הוא נאמן במסל\"ת היינו טעמא משום דלהשביח מקחו קא מכוין הא איכא דמוכחא מלתא דלא מכוין לכך מהימן מ\"מ ביו\"ד כתב סתם מסל\"ת לא סמכינן עלייהו ותו דאמרי' פ' הגוזל בתרא דאין מסל\"ת נאמן אלא לעדות אשה בלבד וצ\"ע בדבר עכ\"ל ונ\"ל דנדון דידן עדיף ממסל\"ת ומההיא דרב שזכרנו והיינו מטעם דודאי קושטא קאמר העובד כוכבים דהך פרה אינה מבכרת דאם איתא דהיא מבכרת לא היה לו להפסידו לעצמו כיון שראה שהיהודי היה נוטל ולדה בסך יותר ודאי היה אומר האמת כדי להרויח לעצמו ואפי' למ\"ש בסמוך בשם התוס' דבעובד כוכבים לא שייך לומר דא\"כ היה משבח דהתם יש טעם שסובר שלא יאמינו לו ע\"כ הוא שותק משא\"כ כאן שהוא מדבר בשבחה של בהמה טפי הוי ליה לומר האמת ולאשבוחי טפי ובזה ודאי כ\"ע מודים לרב דאמרי' הוה משבחי ליה דסברא גדולה היא שאומר האמת ודבר זה הוא הוכחה גדולה שהאמת אתו ולאו מטעם עדות העובד כוכבים אנו באים להתיר אלא מצד ההוכחה כיון שמפסיד לעצמו ויש לי ראיה לזה מפרק הניזקין (גיטין דף נ\"ז) ההוא דאתא לקמיה דר' אמי אמר ס\"ת שכתבתי לפלוני אזכרות שלו לא כתבתי לשמן אמר ליה ס\"ת ביד מי אמר ליה ביד לוקח אמר ליה נאמן אתה להפסיד שכרך ואין אתה נאמן להפסיד ס\"ת ההוא דאתא לקמיה דר' אבהו אמר ליה ס\"ת שכתבתי לפלוני גוילין שלו לא עבדתי לשמן אמר ליה ס\"ת ביד מי אמר ליה ביד לוקח אמר ליה מתוך שאתה נאמן להפסיד שכרך אתה נאמן להפסיד ס\"ת ומאי שנא מדר' אמי דאמר אין אתה נאמן להפסיד ס\"ת התם איכא למימר דטעי וסבר שלא יפסיד אלא שכר האזכרות הכא כיון דקא מפסיד כולו אגרא ואתא ואמר אימא קושטא קאמר הרי לפניך שמצד עדות זה הסופר אין שום נאמנות לפסול הס\"ת ואין בדבריו כלום כמו במעשה הראשון שהיה לפני ר' אמי ואפ\"ה נאמן במעשה האחרון מצד ההוכחה כיון שהוא מפסיד לנפשיה ה\"נ בנדון דידן ודאי אמרי' כן ואין לומר דהכא לא דמיא למפסיד כל שכרו דהכא כיון שאנו רואין שבא להשביח היה לו להשביח טפי כמו שהוא אמת ולמה יאמר שקר ויפסיד לעצמו אפי' דבר מועט וזה ודאי עדיף מהפסד כל שכרו דהתם ואין לומר דהתם בפ' הניזקין לא מהני האי סברא דכיון דמפסיד שכרו נאמן לפסול ס\"ת אלא מטעם דמשוי ספק בדבר כמשמעות הלשון של הש\"ס שאמרה אימא קושטא קאמר זה אינו דהא גם במעשה הראשון יש ספק בדבר דאימר קושטא אמר שלא כתב האזכרות לשמן אלא דאין כח לאסור מספק כל שאין הס\"ת בידו אלא דוקא במעשה האחרון דיש הוכחה שאמר האמת ולשון אימור מתפרש שפיר גם על לשון ודאי כההיא דפ' אלו טרפות בענין ספק דרוסה דאמרי' אימור שלמא קעביד וכן הרבה שם ופירש שם הר\"ן כל הני אימור לישנא דודאי הם שהרי אנו מכשירין בשביל זה וכן הוא בכאן ונמצא שיש בנדון דידן נמי סברא זאת לומר מדאפסיד ודאי קושטא קאמר ולאו מטעם נאמנות דבורו של העובד כוכבים אנו מתירין:\n\u0003ומצאתי \u0004עד נאמן לדברי בדברי מהרי\"ק שורש קכ\"א בענין היתר עגונה שעובד כוכבים אחד אמר בפני השופט שהרג יהודי אחד שהבטיחו השופט שיגיד לו האמת ולא יזיק לו בשום דבר וכתב על זה וז\"ל ועוד דאפשר לומר דעדיף האי מעובד כוכבים מסל\"ת ויש להתיר אפילו בלא טעמא דאשה דייקא ומנסבא וגם בלא טעמא דמשום עגונה אקילו בה רבנן דהא אפילו אחזקה שצריך עדות גמור כגון להוציא ממון מחזקתו דבעינן ב' עדים סמכו אחזקה דלא מרעי נפשייהו גבי שטרות העולים בערכאות של עובדי כוכבים בשטר מכר אף בלא טעמא דדינא דמלכותא דינא כדמוכח בפ\"ק דגטין ואע\"ג דאם היה משקר לא היה מגיע לו היזק רב כי אם מעט זלזול ואפ\"ה אמרינן כיון שהוא דיין לא היה מעיד שקר ופוגם כבודו ואפילו לענין להתיר אשת איש לעלמא הוה סמכינן אחזקה זו אי לאו דלאו בני כריתות נינהו כדמוכח שם כ\"ש וק\"ו דאיכא הכא אי לאו דקושטא קאמר שהרגו דלא הוה מרעיה נפשיה להתחייב בנפשו ואפילו את\"ל שסמך הרוצח על דברי השופט שהבטיחו שלא יזיק לו כלום למיחש מיהו בעי פן יכזב בו כאשר ידוע שכן דרך הדיינים שלהם להחליק בדברים כדי שיודה האמת כו' עכ\"ל והוא ק\"ו לנדון דידן דמה התם שאנו רואים שהבטיחו השופט שלא יעשה לו כלום ומסתמא ודאי על זה סמך והודה דאטו במשוגע קמיירי שיודע שיהרג כשיודה ואפ\"ה יודה אלא ודאי שהיה סומך עצמו שלא יהרגו ואפ\"ה סבר מהרי\"ק דמקרי מפסיד לנפשיה ומהני בלא מסיח לפי תומו ק\"ו כאן שאין שום דבר מתנגד לומר שהיה סבור שלא יפסיד לנפשו שהרי בפירוש אמר לו הישראל שכל שהיא ילדה טפי הוא נותן בדמיה יותר והיה לו לומר שלא ילדה עדיין והך ולד הוא של פרה אחרת ואין לומר דמכל מקום הבין העובד כוכבים שאינו רוצה בפרה שלא בכרה עדיין מחמת שיש עליה סכנת לידה כמו שכתבו התוס' לעיל ואם כן היהודי נתכוין שעל כל פנים תהיה פרה שכבר ילדה אם כן היה לו לעובד כוכבים לומר שזה ולד ראשון שלה והיה ישראל מקבל בדמים יתרים ולמה הפסיד לנפשיה לומר שזה ולד רביעי שלה אלא ודאי דקושטא קאמר ובזה כ\"ע מודים לרב דאם איתא אשתבוחי הוה משתבח לה ועל זה סמכינן דודאי כבר ילדה אצל העובד כוכבים והך דילדה אצל הישראל לאו בכור הוא כן נראה לע\"ד:","\u0003אפ\"ה אסור. \u0004הטעם בפסקי מהרא\"י סימן ק\"ל וזה לשונו כדאיתא בשערי דורא אהא דבא זאב ודרס בהמה אחת דכ' ר\"י דאין להתיר מכח ספק ספקא שמא בשן דרס ואם תמצי לומר ביד דרס שמא אינה זאת כיון דהספק הראשון דאורייתא אינה בטלה אפי' ברוב כל שכן חד בחד עכ\"ל ויש לי מקום עיון בזה ממה שכתב בב\"י לעיל סימן נ\"ז וז\"ל מצאתי כתוב וכי פליג ר\"י על התלמוד דאמרינן ספק ספיקא בדאורייתא ותירץ שם דמיירי דנודע הספק הראשון תחילה ואף כי שדיתי ביה נרגא בסי' ק\"י סעיף ט' ותירצתי בענין אחר ע\"פ הסמ\"ג וסמ\"ק דעיקר היתר ספק ספיקא תלוי אם היה אפשר להיות נודע בינתיים אז אסור או אם שני ספיקות שוות כגון בשני תערובות ע\"ש באריכות וכל זה אינו שייך כאן בב' גדיים שנולדו אחד זכר ואחת נקבה ואיכא ספק ספיקא ספק שמא ילדה כבר קודם שנולדו אלו ואם תמצי לומר לא ילדה מ\"מ שמא הזכר הוא נולד אחרון ולמה לא נימא ספק ספיקא בהאי זכר ונימא דאין כאן בכורה כלל וכן מבואר לעיל בש\"ע סימן ק\"י סעיף ט' בפנים דדוקא ביש ספק הראשון בגופו כו' לא אמרינן ספק ספיקא ובהג\"ה כתב שם דבנודע תליא מילתא וכל זה אינו כאן על כן צריך עיון למה לא ניזול כאן בתר ספק ספיקא ודאי אם ילדה שני זכרים עכשיו ויש ספק בכל אחד מהם איזה הוא נולד ראשון דאז ודאי יש כאן אחד מהם בכור ראוי מהם להחמיר כיון שהם של אדם אחד והוה כשני שבילין בפרק קמא דפסחים בבאו לשאול בב\"א דמחמירין ביה דכאן אי אפשר לשאול אלא בבת אחת דהא עיקר ההיתר מכח ספק ספיקא מה שאין כן באחד זכר ואחת נקבה היה לנו להקל מכח ספק ספיקא ואפשר דמשום הכי נקט רמ\"א סגנון זה בספק ספיקא כגון שילדה שנים ואיכא למימר אכל אחד שאינו בכור ושינה מסגנון דנקט בפסקי מהרא\"י שם דהיינו ילדה זכר ונקבה והיינו מטעם שכתבתי כנ\"ל וצ\"ע למעשה:","\u0003עד שיודיעו המוכר. \u0004הכי אית ליה לר' יוחנן העתקתיו לעיל בסעיף ג'. ויש אומרים ס\"ל כשמואל דלעיל דהספק הוא שמא ישחטנה תיכף והקשה על זה בדרישה מהא דכתב בסעיף ט\"ז ולענין אותו ואת בנו באם שחטו אמו היום על המוכר להודיעו וכל שלא הודיעו אין חושש והיינו כרבי יוחנן דהכא ותירץ דסתם מי שקונה בהמה קונהו כדי לשחטו מיד ומש\"ה ודאי מודיע אותו מש\"ה נמי כאן אף אם לא ילדה כבר אין צריך להודיע שלא בכרה דהא מסתמא ישחטנה תיכף עכ\"ל ודברים תמוהים כתב שהרי בפרק קמא דחולין כתב לענין שחט בסכין של עובד כוכבים בהמה בריאה שאין איסור דהוה מקלקל שבהמה בחייה עומדת לגדל ולדות כו' ותו דאם כן היה קשה מאי טעמא דרב ורבי יוחנן דעל כל אחד קשה הא לשחיטה קיימא מסתמא ועיקר קושייתו נראה לתרץ דודאי התם אמרינן שפיר אם יש איסור היה מודיע שאין סברא כנגד זה על כן ודאי אזלינן בתר סברא זאת מה שאין כן כאן שיש ב' סברות מכחישות זו את זו דהיינו אם איתא שבכרה כבר הוה אשבוחי משבח וסברא כנגדה אם איתא דלא בכרה עדיין היה לו להודיע לאפרושי מאיסורא על כן נשאר הדבר בספק לשמואל) וזה ברור ופשוט לפי ע\"ד:"]],["שְׁנַיִם שֶׁהִפְקִידוּ אֵצֶל אֶחָד שְׁנֵי זְכָרִים, אֶחָד בְּכוֹר וְאֶחָד פָּשׁוּט, וּמֵת אֶחָד מֵהֶם וְאֵינוֹ יוֹדֵעַ אֵיזֶה \u0005(מֵת)\u0006, מַנִּיחַ הַנִּשְׁאָר בֵּינֵיהֶם, \u0010c0\u0011 וְהוּא בֵּין שְׁנֵיהֶם, וְדִינוֹ כִּסְפֵק בְּכוֹר.\nמִי שֶׁהִפְקִיד בְּכוֹר אֵצֶל חֲבֵרוֹ, וְלַחֲבֵרוֹ פָּשׁוּט \u0005(פי' שֶׁאֵינוֹ בְּכוֹר)\u0006, וּמֵת אֶחָד מֵהֶם, הַמּוֹצִיא מֵחֲבֵירוֹ עָלָיו הָרְאָיָה; \u0010c1\u0011 וְכֵיוָן שֶׁהַנִּפְקָד מֻחְזָק, יַחֲזִיקֶנּוּ וְיֹאכְלֶנּוּ \u0010c2\u0011 מִמּוּמוֹ.\nרוֹעֶה כֹּהֵן שֶׁנָּתַן בְּהֵמוֹת בַּחֲצַר בַּעַל הַבַּיִת, וְיָלְדָה אַחַת מֵהֶן בְּכוֹר, וְנִתְעָרְבוּ עִם שֶׁל בַּעַל הַבַּיִת, וּמֵת אֶחָד מֵהֶם, \u0010y0\u0011 \u0010c3\u0011 הָוֵי לֵיהּ בַּעַל הַבַּיִת מֻחְזָק וְיֹאכְלֶנּוּ בְּמוּמוֹ.",["\u0003הוי ליה בעל הבית מוחזק כו'. \u0004ולא אמרינן כיון שהכהן הוא רועה שלו ודאי הקנה לו חצרו כדי שיקנה הכהן את הבכור מיד כשיולד כי ניחא ליה למיעבד מצוה זו גם בממונו שיגדלו בכורותיו של כהן בחצרו וה\"ל כשנים שהפקידו דלעיל סעיף א' אלא במקום פסידא לא אמרינן דניחא למיעבד מצוה כו' והבעל הבית עדיין מוחזק בו:"],["\u0003והוא בין שניהם. \u0004רצונו לומר בין הכהן ובין מי שהפקיד הפשוט וכשיפול בו מום יחלקו בין שניהם אלו:","\u0003וכיון שהנפקד מוחזק כו'. \u0004פירוש שיכול לומר לכהן הבא להוציא ממנו שהבכור מת וזה הנשאר הוא הפשוט ועל כן הוה הכהן המוציא מחבירו ועליו הראיה:","\u0003רועה כהן. \u0004פי' רועה שהוא כהן:","\u0003הוי ליה בעל הבית מוחזק כו'. \u0004בטור כתוב לא אמרינן כיון שהוא רועה כו' פירוש על פי הגמ' דאיתא ר' טרפון סבירא ליה אקנויי מקנה ליה בחצירו וניחא ליה דליתעביד מצוה והוה ליה כשנים שהפקידו אצל רועה שמניח ביניהם ומסתלק פרש\"י אקנויי מקנה ליה בעל הבית לכהן מקום בחצרו כדי שיזכה כהן בבכורות כשיולדו מיד דתקנה ליה חצרו דניחא ליה לאינש דליתעבד מצוה בממוניה שיגדלו בכורותיו של כהן בחצרו והוה ליה חצר של שניהם וכאלו שנים הפקידו אצלו הלכך חולקין דברשות שניהם עומד קמ\"ל דלא אמרינן הכי אלא כר\"ע דאמר כיון דאית ליה פסידא לב\"ה אם מקנה ליה בחצרו לא מקנה ליה כלום והוי ליה כאחד שהפקיד אצל בעל הבית שהמוציא מחבירו עליו הראיה כ\"ה בבכורות:"]],["רָחֵל שֶׁלֹּא בִּכְּרָה וְיָלְדָה שְׁנֵי זְכָרִים, אֲפִלּוּ יָצְאוּ שְׁנֵי רָאשֵׁיהֶם כְּאֶחָד, אִי אֶפְשָׁר שֶׁלֹּא קָדַם אֶחָד, הוֹאִיל וְאֵין יָדוּעַ אֵיזֶה יָצָא רִאשׁוֹן, הַכֹּהֵן \u0010y0\u0011 נוֹטֵל אֶת הַכָּחוּשׁ \u0010c0\u0011 וְהַשֵּׁנִי \u0010y1\u0011 סְפֵק בְּכוֹר. מֵת אֶחָד מֵהֶם, אֵין לַכֹּהֵן כְּלוּם, שֶׁזֶּה הַחַי סָפֵק הוּא וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וְכֵן אִם יָלְדָה זָכָר וּנְקֵבָה, הֲרֵי הַזָּכָר סָפֵק שֶׁמָּא הַנְּקֵבָה יָצְאָה תְּחִלָּה, לְפִיכָךְ \u0010y2\u0011 אֵין לַכֹּהֵן כְּלוּם שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nשְׁתֵּי רְחֵלוֹת שֶׁלֹּא בִּכְּרוּ וְיָלְדוּ שְׁנֵי זְכָרִים, שְׁנֵיהֶם לַכֹּהֵן, זָכָר וּנְקֵבָה, הַזָּכָר לַכֹּהֵן; שְׁנֵי זְכָרִים וּנְקֵבָה, \u0010y3\u0011 הַכֹּהֵן נוֹטֵל אֶת הַכָּחוּשׁ וְהַשֵּׁנִי סְפֵק בְּכוֹר; וְאִם מֵת אֶחָד מֵהֶם, אֵין לַכֹּהֵן כְּלוּם, שֶׁזֶּה הַחַי סְפֵק בְּכוֹר הוּא וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nיָלְדוּ שְׁתֵּי נְקֵבוֹת וְזָכָר, אוֹ שְׁנֵי זְכָרִים וּשְׁתֵּי נְקֵבוֹת, הֲרֵי הַזְּכָרִים סָפֵק, שֶׁאֲנִי אוֹמֵר: שֶׁמָּא הַנְּקֵבָה נוֹלְדָה תְּחִלָּה וְאַחַר כָּךְ הַזָּכָר, לְפִיכָךְ אֵין כָּאן לַכֹּהֵן כְּלוּם, שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nאַחַת בִּכְּרָה וְאַחַת לֹא בִּכְּרָה, וְיָלְדוּ שְׁנֵי זְכָרִים, אֶחָד לוֹ וְאֶחָד לַכֹּהֵן, וְכָל אֶחָד מֵהֶם סְפֵק בְּכוֹר, וְהַכֹּהֵן נוֹטֵל הַכָּחוּשׁ. מֵת אֶחָד מֵהֶם, אֵין כָּאן לַכֹּהֵן כְּלוּם, שֶׁזֶּה הַחַי סָפֵק הוּא. וְכֵן אִם יָלְדוּ זָכָר וּנְקֵבָה, אֵין כָּאן לַכֹּהֵן כְּלוּם, שֶׁזֶּה הַזָּכָר סָפֵק בְּכוֹר הוּא.\nגֵּר שֶׁנִּתְגַּיֵּר, סָפֵק בִּכְּרָה בְּהֶמְתּוֹ קֹדֶם שֶׁנִּתְגַּיֵּר סָפֵק אַחַר כָּךְ, הָוֵי סָפֵק, וְיֵאָכֵל בְּמוּמוֹ לַבְּעָלִים.\nכָּל שֶׁהוּא סְפֵק בְּכוֹר, יִרְעֶה עַד שֶׁיִּפֹּל בּוֹ מוּם, וְיֵאָכֵל לִבְעָלָיו. וְאִם תְּפָשׂוֹ הַכֹּהֵן, אֵין מוֹצִיאִים אוֹתוֹ מִיָּדוֹ, וְאוֹכֵל אוֹתוֹ בְּמוּמוֹ. \u0005וְעַיֵּן לְעֵיל סי' שט\"ו דקי\"ל דְּמוֹצִיאִין אוֹתוֹ מִיַּד הַכֹּהֵן.\u0006",["\u0003נוטל את הכחוש. \u0004דהמע\"ה כדלקמן סעיף ד' מיהו גם הוא ספק בכור ואסור בגיזה ועבודה ויאכלנו הכהן במומו:","\u0003ספק בכור. \u0004ודינו כדלעיל ר\"ס שט\"ו ופטור מהמתנות כיון שחליפיו ביד כהן:","\u0003אין לכהן כלום. \u0004מיהו החי חייב במתנות וכן בכל הסימן ובכל מקום היכא שהוא ספק בכור מחמת שהיו ב' ולקח הכהן אחד מהן הנשאר פטור מהמתנות אבל היכא דהוי ספק בכור שלא בא חליפיו ליד כהן חייב בהמתנו' כדלעיל סי' שט\"ו ס\"ק א':","\u0003הכהן נוטל הכחוש. \u0004דהמע\"ה מיהו נוטל א' ממ\"נ דמ\"מ א' ודאי בכור הוא וזה שנוטל הכהן הוא ג\"כ אצל הכהן ספק בכור ואסור בגיזה ועבודה ויאכלנו הכהן במומו:"],["\u0003והשני ספק בכור. \u0004בטור כתוב ויאכל במומו לבעלים וחייב במתנות כהונה והטעם דאומר הכהן ממה נפשך אם בכור הוא כולו שלי ואם לא הב לי מתנות וכן בכל הני דאמרינן יאכל במומו לבעלים דינא הכי:"]],["מְבַכֶּרֶת הַמַּקְשֶׁה לֵילֵד, \u0010y0\u0011 יָכוֹל לַחְתֹּךְ אוֹתוֹ אֵבֶר אֵבֶר וּמַשְׁלִיךְ לַכְּלָבִים. \u0010y1\u0011 \u0005וּמֵרֻבּוֹ וָאֵילָךְ, צָרִיךְ קְבוּרָה (בֵּית יוֹסֵף בְּשֵׁם \u0010y2\u0011 הַתּוֹסָפוֹת)\u0006. וְהַבָּא אַחֲרָיו, בְּכוֹר. \u0010y3\u0011 \u0005וְיֵשׁ אוֹמְרִים שֶׁאֵינוֹ בְּכוֹר, (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. יָצָא רֻבּוֹ, הֲרֵי זֶה יִקָּבֵר \u0010y4\u0011 וְנִפְטְרָה מֵהַבְּכוֹרָה. וְאִם חָתַךְ אֵבֶר וְהִנִּיחוֹ, אֵבֶר וְהִנִּיחוֹ, עַד שֶׁהִשְׁלִים רֻבּוֹ, הֲרֵי כָּל הָאֵבָרִים צְרִיכִין קְבוּרָה וְנִפְטְרָה מֵהַבְּכוֹרָה, כֵּיוָן שֶׁיָּצָא רֻבּוֹ, בֵּין שָׁלֵם בֵּין מְחֻתָּךְ \u0005(וַהֲרֵי הוּא לְפָנֵינוּ)\u0006, נִתְקַדֵּשׁ לְמַפְרֵעַ. \u0010y5\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאֵינוֹ קָדוֹשׁ לְמַפְרֵעַ (טוּר)\u0006.\nיָצָא שְׁלִישׁ וּמְכָרוֹ לְעוֹבֵד כּוֹכָבִים, וְחָזַר וְיָצָא שְׁלִישׁ אַחֵר, \u0010y6\u0011 נִתְקַדֵּשׁ לְמַפְרֵעַ. \u0005וְיֵשׁ אוֹמְרִים דְּאֵינוֹ קָדוֹשׁ לְמַפְרֵעַ. (טוּר)\u0006.\nיָצָא שְׁלִישׁ דֶּרֶךְ דֹּפֶן וּשְׁנֵי שְׁלִישִׁים \u0010c0\u0011 דֶּרֶךְ רֶחֶם, \u0010y7\u0011 אֵינוֹ קָדוֹשׁ. \u0010y8\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּקָדוֹשׁ (ג\"ז טוּר)\u0006. \u0010y9\u0011\nיָצָא רֹב הָעֻבָּר עַל יְדֵי מִעוּט אֶחָד מֵהָאֵבָרִים שֶׁמַּשְׁלִימוֹ לְרֹב, חֲשֹׁב כְּיִלּוֹד אַף עַל פִּי שֶׁרֹב הָאֵבֶר מִבִּפְנִים, \u0010y10\u0011 וְאָסוּר לְמָכְרוֹ לְעוֹבֵד כּוֹכָבִים וּלְהַשְׁלִיכוֹ לַכְּלָבִים, וּפוֹטֵר הַבָּא אַחֲרָיו. וְאִם יָצָא חֶצְיוֹ שֶׁל עֻבָּר עַל יְדֵי רֹב אֶחָד מֵהָאֵבָרִים שֶׁעַל יָדוֹ נִשְׁלַם יְצִיאַת חֲצִי הָעֻבָּר, הֲרֵי זֶה סָפֵק וְאָסוּר לְמָכְרוֹ לְעוֹבֵד כּוֹכָבִים וּלְהַשְׁלִיכוֹ לַכְּלָבִים, \u0010y11\u0011 וְהַבָּא אַחֲרָיו סְפֵק בְּכוֹר.",["\u0003יכול לחתוך כו'. \u0004שכל שלא יצא רובו לא הוקדש וע\"ל ס\"ס שי\"ג:","\u0003ומרובו ואילך כו'. \u0004כלומר אף כשחתך אבר אבר והשליך לכלבים מ\"מ מה שיוצא אחר כך מרובו ואילך חייב קבורה אבל מה שיצא כבר אף שיצא אח\"כ רובו א\"צ קבורה למ\"ד להבא הוא קדוש וכן מבואר בתוס':","\u0003והבא אחריו בכור. \u0004דכיון דלא חשיב כילוד א\"כ אינו חשוב פטר רחם והבא אחריו בכור:","\u0003וי\"א כו'. \u0004דאע\"ג דלא חשוב כילוד מ\"מ חשוב פטר רחם:","\u0003ונפטרה מהבכורה. \u0004כלומר הבא אחריו:","\u0003וי\"א דאינו כו'. \u0004והלכך אפילו במחתך אבר אבר והניחו עד שהשלים רובו משליך לכלבים מה שיצא עד רובו ומרוב ואילך צריך קבורה:","\u0003נתקדש למפרע. \u0004והמכירה לעובד כוכבים אינה מכירה:","\u0003אינו קדוש. \u0004דכיון דקדוש למפרע והשליש הראשון דרך דופן נפק אינו קדוש:","\u0003וי\"א דקדוש כו'. \u0004לטעמייהו אזלי דס\"נ להבא קדוש:","\u0003יצא רוב כו'. \u0004וע\"ל סי' י\"ד ס\"ג ומ\"ש שם:","\u0003ואסור למכרו לעוכד כוכבים כו'. \u0004דשמא הוי כילוד:","\u0003והבא אחריו כו'. \u0004זהו מלשון הרמב\"ם וכן הוא בטור וברמב\"ם אתי כפשטיה דדילמא לא הוי כילוד ומיירי בחתך מה שיצא חציו ברוב אבר והלכך אפי' יצא אח\"כ כולו אינו פוטר הבא אחריו כיון שיצא חציו ע\"י חתיכה וכדלעיל סעיף א' אבל הטור דס\"ל דאפי' חתכו אבר אבר פוטר הבא אחריו דמ\"מ פטר רחם הוא וכ\"כ הרב לעיל סעיף א' א\"כ צ\"ל דמיירי הכא שלא נולד אח\"כ כולו אלא שחציו הנשאר יצא דרך דופן או כגון שהיה לה תאומים ויצא מתחלה חציו ברוב אבר וחזר ואח\"כ יצא השני ואח\"כ חזר ויצא הראשון כולו אינו נפטר השני במה שיצא הראשון מתחלה חציו ברוב אבר אבל אם אחר שיצא חציו ברוב אבר יצא כולו ואחר זמן ילדה ולד פשיטא שהוא פטור בבכורה דמה בכך שמתחלה יצא חציו ברוב אבר ס\"ס אחר כך נולד כולו וזה פשוט:"],["\u0003דרך רחם אינו קדוש. \u0004בטור כתוב כיון שיצא רוב הראשון דרך דופן ורצונו לומר רוב מרוב הראשון שהקדושה תלויה בו:"]],["כֹּהֲנִים \u0010y0\u0011 וּלְוִיִּם חַיָּבִים בִּבְכוֹר בְּהֵמָה טְהוֹרָה, \u0010c0\u0011 וְיַפְרִישֶׁנּוּ הַכֹּהֵן \u0010y1\u0011 וִיעַכְּבֶנּוּ לְעַצְמוֹ. \u0010c1\u0011\nבֶּהֱמַת הַשֻּׁתָּפִין חַיֶּבֶת בִּבְכוֹרָה.\nשֻׁתָּפוּת הָעוֹבֵד כּוֹכָבִים פּוֹטֵר, שֶׁאִם הָיָה הָעוֹבֵד כּוֹכָבִים שֻׁתָּף בַּפָּרָה אוֹ בָּעֻבָּר, אֲפִלּוּ הָיָה לוֹ \u0010c2\u0011 אֶחָד מֵאֶלֶף בָּאֵם אוֹ בַּוָּלָד, הֲרֵי זֶה פָּטוּר מֵהַבְּכוֹרָה. לְפִיכָךְ הַמְקַבֵּל בְּהֵמָה מִן הָעוֹבֵד כּוֹכָבִים לִהְיוֹת מְטַפֵּל בָּהּ וְהַוְּלָדוֹת בֵּינֵיהֶם, אוֹ עוֹבֵד כּוֹכָבִים שֶׁקִּבֵּל מִיִּשְׂרָאֵל כָּזֶה, הֲרֵי אֵלּוּ פְּטוּרִים מֵהַבְּכוֹרָה, שֶׁנֶּאֱמַר: פֶּטֶר רֶחֶם בִּבְנֵי יִשְׂרָאֵל \u0005(שְׁמוֹת יג, ב)\u0006 עַד שֶׁיִּהְיֶה הַכֹּל מִיִּשְׂרָאֵל. \u0010y2\u0011\nהָיָה לוֹ בְּאֶחָד מִשְּׁנֵיהֶם אֵבֶר אֶחָד, כְּגוֹן יָד אוֹ רֶגֶל, רוֹאִים כָּל שֶׁאִלּוּ יַחְתֹּךְ יִהְיֶה בַּעַל מוּם, הֲרֵי זֶה פָּטוּר; וְאִם אֶפְשָׁר שֶׁהָעוֹבֵד כּוֹכָבִים יַחְתֹּךְ אֵבֶר \u0010c3\u0011 וְלֹא יִפָּסֵל, חַיָּב בִּבְכוֹרָה.\nעֵדֶר שֶׁהַמֶּלֶךְ נוֹטֵל מִמֶּנָּהּ מַעֲשֵׁר, כֵּיוָן שֶׁעִשּׂוּר שֶׁל מֶלֶךְ בְּתוֹכוֹ, חֲשִׁיבָא יַד עוֹבֵד כּוֹכָבִים בָּאֶמְצַע וּפָטוּר מֵהַבְּכוֹרָה. \u0005הַגָּה: וַאֲפִלּוּ יָכוֹל לְסַלֵּק הָעוֹבֵד כּוֹכָבִים בְּמָעוֹת, חָשׁוּב יַד עוֹבֵד כּוֹכָבִים בָּאֶמְצַע, מֵאַחַר שֶׁעִקַּר שִׁעְבּוּד הָעוֹבֵד כּוֹכָבִים עַל הַבְּהֵמוֹת. (בֵּית יוֹסֵף לְהָרִי\"ף וְרֹא\"שׁ וּפִסְקֵי מהאר\"י סי' ק\"ל)\u0006 אֲבָל אִם הִתְנוּ מִתְּחִלָּה שֶׁיִּתְּנוּ לוֹ דָּמִים בְּעַד הַוְּלָדוֹת, חַיָּב בִּבְכוֹרָה \u0005(גַּם זֶה שָׁם)\u0006. \u0010c4\u0011\nבַּזְּמַן הַזֶּה, מִצְוָה לְשַׁתֵּף עִם הָעוֹבֵד כּוֹכָבִים קֹדֶם שֶׁיֵּצֵא לַאֲוִיר הָעוֹלָם, כְּדֵי לְפָטְרוֹ מֵהַבְּכוֹרָה, אַף עַל פִּי שֶׁמַּפְקִיעַ קְדֻשָּׁתוֹ, הָכִי עָדִיף טְפֵי כְּדֵי שֶׁלֹּא יָבֹא לִידֵי מִכְשׁוֹל לֵהָנוֹת מִמֶּנּוּ בְּגִזָּה וּבַעֲבוֹדָה. וְאִם יַקְנֶה לְעוֹבֵד כּוֹכָבִים חֵלֶק בָּעֻבָּר, אֵין הַקִּנְיָן חָל, \u0010y3\u0011 לְפִי שֶׁהוּא דָּבָר שֶׁלֹּא בָּא לָעוֹלָם, לְכָךְ יַקְנֶה לוֹ חֵלֶק בָּאֵם, \u0010y4\u0011 \u0005אוֹ יַקְנֶה לוֹ הָאֵם \u0010y5\u0011 כְּדֵי לְהַקְנוֹת לוֹ חֵלֶק \u0010c5\u0011 בָּעֻבָּר\u0006 וְהַקִּנְיָן יִהְיֶה \u0010y6\u0011 שֶׁיְּקַבֵּל פְּרוּטָה מֵהָעוֹבֵד כּוֹכָבִים \u0010y7\u0011 וְיַקְנֶה לוֹ הַמָּקוֹם שֶׁהַבְּהֵמָה עוֹמֶדֶת שָׁם וְהַמָּקוֹם יַקְנֶה לוֹ חֵלֶק בָּאֵם. \u0010c6\u0011 \u0010c7\u0011 \u0005אוֹ שֶׁיְּקַבֵּל מָעוֹת מִן הָעוֹבֵד כּוֹכָבִים, וְיִמְשֹׁךְ הַבְּהֵמָה לִרְשׁוּתוֹ אוֹ לְסִמְטָא דְּאָז מְשִׁיכָה קוֹנָה לוֹ עִם הַמָּעוֹת (טוּר לְדַעַת רַשִׁ\"י וְרַבֵּנוּ תָּם)\u0006.\nהַמְקַבֵּל צֹאן מִן הָעוֹבֵד כּוֹכָבִים \u0005(בְּמָמוֹן קָצוּב)\u0006, וּפָסַק עִמּוֹ שֶׁיִּהְיֶה הַשָּׂכָר בֵּינֵיהֶם וְאִם פָּחֲתוּ פָּחֲתוּ לַיִּשְׂרָאֵל, אַף עַל פִּי שֶׁבִּרְשׁוּת יִשְׂרָאֵל הֵם וַהֲרֵי הֵם כְּקִנְיָנוֹ, הוֹאִיל וְאִם לֹא יִמְצָא הָעוֹבֵד כּוֹכָבִים אֶצְלוֹ מָמוֹן לִגְבּוֹת מִמֶּנּוּ יִגְבֶּה מֵהַבְּהֵמוֹת הָאֵלּוּ וּמִוַּלְדוֹתֵיהֶם, נַעֲשָׂה כְּמִי שֶׁיֵּשׁ לוֹ אַחֲרָיוּת עֲלֵיהֶם וְעַל וַלְדוֹתֵיהֶן, וַהֲרֵי יַד הָעוֹבֵד כּוֹכָבִים בָּאֶמְצַע וּפְטוּרִים מֵהַבְּכוֹרָה הֵם וּוַלְדוֹתֵיהֶן. אֲבָל וַלְדֵי וְלָדוֹת, חַיָּבִים, שֶׁהֲרֵי שֶׁל יִשְׂרָאֵל הֵם וְאֵין לָעוֹבֵד כּוֹכָבִים רְשׁוּת עֲלֵיהֶם. וְאִם הֶעֱמִיד וְלָדוֹת תַּחַת אִמּוֹתֵיהֶן, וַלְדֵי וְלָדוֹת פְּטוּרִים. וַלְדֵי וַלְדֵי וְלָדוֹת, חַיָּבִים. \u0005הַגָּה: וְעוֹבֵד כּוֹכָבִים בַּעַל חוֹב שֶׁקִּבֵּל בְּהֵמָה מִיִּשְׂרָאֵל לְגַדְּלָהּ, וְהָיָה חָפֵץ חֵלֶק בַּוְּלָדוֹת, וְהַיִּשְׂרָאֵל אָמַר לִתֵּן לוֹ דָּמִים, וּמֵאַחֵר שֶׁיָּדוֹ הָיְתָה תַּקִּיפָה עַל בַּעַל חוֹבוֹ בֶּטַח שֶׁעַל כָּרְחוֹ שֶׁל עוֹבֵד כּוֹכָבִים יִצְטָרֵךְ לִקַּח מָעוֹת, \u0010y8\u0011 מִכָּל מָקוֹם פְּטוּרָה מֵהַבְּכוֹרָה הוֹאִיל וְהָעוֹבֵד כּוֹכָבִים לֹא רָצָה לְטַפֵּל בָּהּ רַק בְּחֵלֶק וְלָדוֹת (פִּסְקֵי מהרא\"י סִימָן ק\"ל)\u0006. עוֹבֵד כּוֹכָבִים שֶׁקִּבֵּל בֶּהֱמַת יִשְׂרָאֵל לְטַפֵּל בָּהּ, וְאֵין לוֹ חֵלֶק בָּהּ רַק קִבֵּל עָלָיו אַחֲרָיוּת שֶׁלָּהּ, חַיֶּבֶת בִּבְכוֹרָה \u0005(מהרי\"ו סִימָן קע\"ד)\u0006.",["\u0003ולוים חייבים. \u0004והלוים צריכים ליתנו לכהן. כ\"כ העט\"ז:","\u0003ויעכבנו לעצמו. \u0004ואסור בגיזה ועבודה אלא ימתין עד שיפול בו מום ויאכלנו במומו:","\u0003היה לו באחד משניהם כו'. \u0004כלומר דוקא בסעיף ג' שהיה לו לעובד כוכבים שותפות בסתם אפי' באחד מאלף שיכול להיות שחלקו הוא הלב או המוח מקום שכל חיות הבהמה תלויה בו אבל אם אין לעובד כוכבים שותפות בם אלא באבר מיוחד כגון שיש לו באחד משניהם אבר אחד כגון יד או רגל רואין כל שאלו יחתוך כו' כן פירש העט\"ז ובדרישה כתוב שצריך שיהא כל האבר לעובד כוכבים ובא\"א פירש בענין אחר ע\"ש. מיהו התוס' פ' בתרא דעבודת כוכבים כתבו שצריך להקנות לעובד כוכבים דבר שהחיות תלוי בו וכ\"כ בהגהת מרדכי פרק האשה רבה ויש להחמיר לכתחלה וכ\"כ באגודה ריש בכורות וטוב להקנות דבר שעושה נבלה או טרפה:","\u0003לפי שהוא דבר שלא בא לעולם. \u0004ואין הקנין חל כמו שנתבאר בח\"מ סימן ר\"ט ס\"ד:","\u0003או יקנה לו האם כו'. \u0004צ\"ע דמהתוס' והרא\"ש ריש בכורות והאגודה בשם ר\"ת משמע איפכא דאין לעשות כן משום דאתי למטעי דיקנה לו אוזן העובר לחוד וכן משמע בטור וכמ\"ש בפרישה ע\"ש:","\u0003כדי להקנות כו'. \u0004דהקנין חל דהוי כמו אילן לפירותיו או פרה ושפחה לעובריה דקנה כיון שהפרה בעולם וכמו שנתבאר בח\"מ שם:","\u0003שיקבל פרוטה כו'. \u0004וא\"צ שיתן העובד כוכבים מעות שוה הראש או הריאה אלא סגי שיקנה בפרוטה ואע\"פ ששוה יותר כפלים אפ\"ה אין לחוש משום ביטול מקח דאנן סהדי שהישראל גמר ומקני לעובד כוכבים כדי להפטר. תוס' פרק בתרא דעבודת כוכבים:","\u0003ויקנה לו המקום כו'. \u0004משום דיש מחלוקת בין הפוסקים ר\"ת וסייעתו סוברים דמשיכה קונה בעובד כוכבים ולא מעות ורש\"י וסייעתו סבירא להו דמעות קונות ולא משיכה ולצאת ידי ספק צריך לעשות קנין דמשיכה ומעות. ומשמע דאפי' דיעבד אם לא עשה אלא קנין אחד משיכה או מעות לא נפטר מבכורה וכ\"כ בתשו' מהרי\"ל ומביאו הדרישה וכ\"פ הב\"י ושאר אחרונים וכתב עוד הב\"ח דאפי' עביד תרוייהו משיכה ומעות אלא דלא נתן העובד כוכבים מעות מיד בשעת הקנין אלא שהבטיחו ליתן לו מעות כך וכך והאמין לו אף על פי שנתן לו העובד כוכבים אח\"כ מה שהבטיח לו אין אלו מעות קונות ואין צריך לומר אם הישראל היה חייב לעובד כוכבים ואמר ליה עובד כוכבים פרתך קנויה לי במעות כך וכך שאתה חייב לי והקנה לו הישראל דפשיטא דאין זה קנין מעות כל זה נתבאר בתשובתו ע\"כ ומשמע דה\"ה בקנה פרה מעובד כוכבים דלר\"ת משיכה דוקא קונה ולרש\"י מעות וא\"כ אי עשה הישראל משיכה או מעות וילדה חייב בבכורה מספקא דכן מבואר בתשובת מהר\"ם מינץ סי' ה' ובתשובת הרב סי' פ\"ז וכ' עוד שם שאם קנה פרה מעובד כוכבים במעות ונגנבה ונתרצה העובד כוכבים לשלם להישראל הפרה ואח\"כ הוכר הגנב וילדה הפרה דפטור מבכורה כיון דנתרצה העובד כוכבים לשלם נקנה לו הפרה בכל מקום שהיא וע\"ש שהאריך ועיין עוד בתשובת האחרונים כמה ענינים מדינים אלו:","\u0003מכל מקום פטורה מהבכורה הואיל והעובד כוכבים כו'. \u0004והיה כאן משיכה ומעות דכיון דברשות העובד כוכבים הוי בשעת התנאי כמו שנראה מלשון כתבך וקנה לו רשותו במקום משיכה ומעות נמי נתן במה שקבל עליו להאכילה ליטפל בהן כמו בכתב' מאי אית לך למימר דבר שלא בא לעולם הוא יש להביא ראיה על זה מפרק המפקיד כו' דאמרינן נעשה כאומר לו קנה בהמה לולדותיה כו' עד כאן לשון מהרא\"י שם:"],["\u0003ויפרישנו הכהן. \u0004כיון דהקדושה חלה עליו ויעכבנו עד שיפול בו מום ויאכלנו והיינו בזמן הזה אבל בזמן הבית היה מקריב אבריו ודמו ואוכל הבשר:","\u0003בהמת השותפין כו'. \u0004דכתיב בקרכם וצאנכם אבל שותפות דעובד כוכבים פוטר דכתיב כל פטר רחם בבני ישראל:","\u0003אחד מאלף. \u0004בב\"י כתוב בשם תוס' ריש בכורות דסגי אפי' באזנה אלא דבתוס' פרק בתרא דעבודת כוכבים כתבו שיש להחמיר להקנות לעובד כוכבים דבר שעושה אותה טריפה כגון הריאה והראש אמנם א\"צ שיתן העובד כוכבים מעות שוה הראש או הריאה אלא שיקנם בפרוטה אע\"פ ששוה יותר כפלים אפ\"ה אין לחוש משום ביטול מקח דאנן סהדי שהישראל גמר ואקני לעובד כוכבים כדי להפטר עכ\"ל. והקשה שם בפרישה מאי שנא מסי' ס\"א גבי מתנות כהונה שצריך שיהיה לעובד כוכבים חלק א' בכולה אפי' חלק כל שהוא ואם אין שותף עמו אלא בראש אין פטור אלא מן הלחיים וכן בזרוע וקיבה וא\"כ קשה לדעת התוס' דבעינן דוקא דבר חשוב כמו ראש ובו סגי ותירץ מה שתירץ ולי נראה דלא קשה מידי דדוקא הכא גבי בכור דכתיב פטר רחם בישראל ילפינן מזה שיהיה הכל בבני ישראל וכן בפרק מרובה לענין מכרו חוץ ממאה שבו דכתיב ומכרו ודרשינן ומכרו כולו דוקא נמצא דהכל תלוי זה בזה ואם ניטל דבר חשוב ממנו בטל הכל משא\"כ לענין מתנות דאין לימוד מקרא על זה אלא דבכל שיש לעובד כוכבים חלק בו אותו חלק פטור ממתנות ותו לא דאין אחד תלוי בחבירו כלל:","\u0003ולא יפסל. \u0004בב\"י הקשה היאך אפשר שיחתוך אבר ולא יהיה מום ותירץ דאפשר ביש לו יתרת אבר ואין צורך לזה דה\"ק שאלו יחתוך מאותו אבר עצמו ולא יהיה מום מחמת אותו החיתוך והכי קאמר הרמב\"ם אם יש לו חלק אחד באבר א' רואין אם יחתוך אותו חלק כו' ובזה מתורץ גם מה שהקשה הטור על הרמב\"ם:","\u0003בזמן הזה. \u0004לאפוקי בזמן הבית שאסור להפקיע קדושת הבכור שיכול להקריב אותו למזבח:","\u0003והקנין יהיה שיקבל פרוטה כו'. \u0004מבואר בטור הטעם דלפי' של רש\"י מעות קונות בעובד כוכבים בלא משיכה ולר\"ת דוקא משיכה קונה בו וצריך שימשוך הבהמה לרשות הרבים או לסימטא הלכך לצאת ידי שניהם יעשה כן:","\u0003או שיקבל מעות כו'. \u0004בטור כתוב שהדרך הראשון דהיינו שיקנה לו המקום הוא יותר מובחר ונראה טעמו לפי שקנין אגב המקום הוא עדיף ממשיכה כמ\"ש בח\"מ סי' קנ\"ז בדברי הרמ\"ה:","\u0003או שיקבל מעות כו'. \u0004כתב בתשובת מהרר\"י סג\"ל סי' קע\"ד דאם לא מכר רק בדרך א' במעות או במשיכה הוה ספק בכור אפי' בדיעבד כיון דלא ידעינן כמאן קי\"ל ובתשובת רמ\"א סי' פ\"ז כ' היינו דוקא לכתחלה דצריך מעות וגם משיכה אבל דיעבד ודאי קי\"ל כר\"ת מדפסקו כל הפוסקים דמעות קונות בישראל ממילא בכותי קונה משיכה כו' ועל כן אם לא משך ישראל הפרה פשיטא דהפרה עדיין ברשות כותי עומדת ואין חילוק בין כותי קונה מישראל או ישראל מן כותי עכ\"ל ועיין עוד שם ובפסקי מהרא\"י סי' ק\"ל כתוב בסופו דאף ע\"ג דאין מועיל מה שמקנה העובר לעובד כוכבים מחמת שלא בא לעולם מכל מקום יש סברא לומר דמהני אם הפרה מעוברת ועביד דאתי שתלד העובר ודמיא לההיא דריש המפקיד נעשה כאומר פרתי קנויה לך סמוך לגנבתי וכ' שם דאם יש עוד צד להיתר כההיא דראוהו חולבת מקודם מהני בצירוף וכתוב עוד בתשובת מהרא\"י הנ\"ל דמה שמתנה עם העובד כוכבים שיאכיל הפרה בעד העגל הוי כנותן מעות בעדו:"]],["\u0003הלכות פטר חמור\u0004\nבְּכוֹר בְּהֵמָה טְמֵאָה נוֹהֵג בְּכָל מָקוֹם וּבְכָל זְמַן. וְאֵינוֹ נוֹהֵג \u0010c0\u0011 אֶלָּא בַּחֲמוֹרִים. וְזֶה מִצְוָתוֹ, שֶׁכָּל יִשְׂרָאֵל שֶׁיֵּשׁ לוֹ חֲמוֹרָה שֶׁבִּכְּרָה פּוֹדֵהוּ בְּשֶׂה \u0010c1\u0011 מִן הַכְּבָשִׂים אוֹ מִן הָעִזִּים, בֵּין זָכָר בֵּין נְקֵבָה, בֵין תָּם בֵּין בַּעַל מוּם, בֵּין גָּדוֹל בֵּין קָטָן, וְיִתְּנֶנּוּ לְכֹהֵן. וּמֵאֵימָתַי חַיָּב לִפְדּוֹתוֹ, מִשֶּׁיִּוָּלֵד עַד שֶׁיָּמוּת, אֶלָּא שֶׁמִּצְוָה לִפְדּוֹתוֹ מִיָּד, שֶׁלֹּא לְהַשְׁהוֹת הַמִּצְוָה. וּלְאַחֵר שֶׁיִּפְדֶּנּוּ הוּא חֻלִּין גְּמוּרִים, וּמֻתָּר בְּגִזָּה וַעֲבוֹדָה כִּשְׁאָר חֻלִּין. וְהַכֹּהֵן יַעֲשֶׂה גַּם כֵּן בַּשֶּׂה כְּמוֹ בִּשְׁאָר \u0010y0\u0011 חֻלִּין.\nאֵין פּוֹדִין \u0010c2\u0011 לֹא בְּעֵגֶל וְלֹא בְּחַיָּה וְלֹא בְּשֶׂה שָׁחוּט וְלֹא בִּטְרֵפָה וְלֹא בְּכִלְאַיִם וְלֹא בְּכוֹי.\nאֵין פּוֹדִין בְּשֶׂה הַדּוֹמֶה לְמִין אַחֵר; \u0010c3\u0011 וְאִם פָּדָה, פָּדוּי \u0005וְיֵשׁ אוֹמְרִים דְּאִם פָּדָה בּוֹ \u0010c4\u0011 הָוֵי סָפֵק (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nפּוֹדִין בְּבֶן פְּקוּעָה. \u0005וְיֵשׁ אוֹמְרִים שֶׁאֵין פּוֹדִין בְּבֶן פְּקוּעָה (ג\"ז בִּשְׁמוֹ)\u0006.\nאִם אֵין לוֹ שֶׂה לִפְדּוֹתוֹ, פּוֹדֶהוּ בְּשָׁוְיוֹ. \u0005וְאָז יָכוֹל לִפְדּוֹת בְּכָל דָּבָר (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006, וְנוֹתֵן דָּמָיו לַכֹּהֵן. \u0010y1\u0011 לֹא אָמְרָה תּוֹרָה לְהַחְמִיר עָלָיו, אֶלָּא לְהָקֵל עָלָיו שֶׁאִם הָיָה לוֹ פֶּטֶר חֲמוֹר שֶׁשָּׁוֶה עֲשָׂרָה סְלָעִים, יֵשׁ לוֹ לִפְדּוֹתוֹ בְּשֶׂה שְׁוֵה דִּינָר. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיוּ דְּמֵי פֶּטֶר חֲמוֹר מִג' זוּזִין וָמַעְלָה, אֲבָל אִם הָיוּ דָּמָיו פָּחוֹת מִג' זוּזִין, אֵין פּוֹדִין אוֹתוֹ אֶלָּא בְּשֶׂה אוֹ בְּג' זוּזִין; וְעַיִן יָפָה לֹא יִפְחֹת מִסֶלַע, וְעַיִן רָעָה בַּחֲצִי סֶלַע, וּבֵינוֹנִית בְּג' זוּזִים. \u0005הַגָּה: וּפוֹדִין בְּשֵׂה אֶחָד כַּמָּה פְּעָמִים, כְּגוֹן אִם חָזַר וּקְנָאוֹ מִן הַכֹּהֵן, \u0010c5\u0011 אוֹ בְּמָקוֹם שֶׁיֵּשׁ לוֹ סְפֵק פֶּטֶר חֲמוֹר, \u0010y2\u0011 שֶׁדִּינוֹ שֶׁמַּפְרִישׁ עָלָיו טָלֶה וְהוּא שֶׁלּוֹ (טוּר)\u0006.\nמִיָּד כְּשֶׁהִפְרִישׁ הַטָּלֶה תַּחַת פֶּטֶר חֲמוֹר, חָזַר הַפֶּטֶר חֲמוֹר חֻלִּין, אֲפִלּוּ קֹדֶם שֶׁנְּתָנוֹ לַכֹּהֵן, וּמֻתָּר לֵהָנוֹת בּוֹ. וְאִם מֵת, לֹא יִקָּבֵר. וְהַכֹּהֵן זָכָה בַּשֶּׂה מִיָּד, וְהוּא בְּאַחֲרָיוּתוֹ, שֶׁאִם מֵת מִיָּד הַבְּעָלִים קֹדֶם שֶׁנְּתָנוּהוּ לַכֹּהֵן, פְּטוּרִים. \u0010y3\u0011 לְפִיכָךְ מִיָּד כְּשֶׁמַּפְרִישׁוֹ \u0010c6\u0011 מְבָרֵךְ: אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל פִּדְיוֹן פֶּטֶר חֲמוֹר.\nיִשְׂרָאֵל שֶׁפָּדָה פָּטַר חֲמוֹר שֶׁל חֲבֵרוֹ, הוּא פָּדוּי, וּפֶטֶר חֲמוֹר הוּא לִבְעָלָיו.\nפֶּטֶר חֲמוֹר אָסוּר בַּהֲנָאָה עַד שֶׁיִּפָּדֶה; וְאִם מְכָרוֹ קֹדֶם פִּדְיוֹן, \u0010y4\u0011 דָּמָיו אֲסוּרִין. \u0005הַגָּה: וְדַוְקָא שֶׁמְּכָרוֹ סְתָמָא, אֲבָל אִם הוֹדִיעוּ לַלּוֹקֵחַ שֶׁהוּא פֶּטֶר חֲמוֹר וְהוּא מוֹכֵר לוֹ מַה שֶּׁשָּׁוֶה יוֹתֵר מֵהַשֶּׂה שֶׁיִּפְדֶּה, דָּמָיו מֻתָּרִים, וַאֲפִלּוּ לְכַתְּחַלָּה \u0010c7\u0011 מֻתָּר לְמָכְרוֹ בִּכְהַאי גַּוְנָא (כָּךְ מַשְׁמָע בַּטּוּר)\u0006. וְאִם מֵת קֹדֶם פִּדְיוֹן, אוֹ שֶׁעֲרָפוֹ, יִקָּבֵר, מִפְּנֵי שֶׁהוּא אָסוּר בַּהֲנָאָה אַף לְאַחַר עֲרִיפָתוֹ, הוֹאִיל וְלֹא נִפְדָּה. לְפִיכָךְ, אִם לֹא פָּדָהוּ וְנָתַן פֶּטֶר הַחֲמוֹר בְּעַצְמוֹ לַכֹּהֵן, אָסוּר לַכֹּהֵן לְהִשְׁתַּמֵּשׁ בּוֹ עַד שֶׁיִּפְדֵּהוּ בְּשֶׂה וְיִקַּח הַשֶּׂה לְעַצְמוֹ, אוֹ יַעַרְפֶנּוּ וְיִקָּבֵר. \u0010y5\u0011 וְהַכֹּהֲנִים חֲשׁוּדִים עַל דָּבָר זֶה, לְפִיכָךְ אָסוּר לְיִשְׂרָאֵל לִתֵּן פֶּטֶר חֲמוֹר לַכֹּהֵן, אֶלָּא אִם כֵּן פָּדָה הַחֲמוֹר בְּפָנָיו אוֹ יַעַרְפֶנּוּ לְפָנָיו.\nפֶּטֶר חֲמוֹר, קֹדֶם שֶׁיִּפָּדֶה, אָסוּר לַעֲבֹד בּוֹ וּלְגָזְזוֹ כְּדֵי לֵהָנוֹת בִּשְׂעָרוֹ. אֲבָל אִם הָיָה \u0010c8\u0011 שְׂעָרוֹ מְסֻבָּךְ, אוֹ שֶׁיֵּשׁ לוֹ מַכָּה בִּמְקוֹם הַשֵּׂעָר, מֻתָּר לְגָזְזוֹ לַהֲנָאָתוֹ, וְהַשֵּׂעָר אָסוּר בַּהֲנָאָה, וְיִקָּבֵר.\nיִשְׂרָאֵל שֶּׁיֵּשׁ לוֹ סָפֵק פֶּטֶר חֲמוֹר, יַפְרִישׁ עָלָיו טָלֶה לְהַפְקִיעַ \u0010y6\u0011 אִסוּרוֹ, וּמְעַכֵּב הַטָּלֶה לְעַצְמוֹ. \u0005הַגָּה: לֹא רָצָה לִפְדּוֹתוֹ וְלֹא לִתְּנוֹ לַכֹּהֵן, מַכֵּהוּ בְּקוֹפִיץ בְּעָרְפּוֹ עַד שֶׁיָּמוּת, וְיִקְבְּרֶנּוּ (טוּר)\u0006.\nפֶּטֶר חֲמוֹר אֵין מְמִיתִין אוֹתוֹ לֹא בְּמַקֵּל וְלֹא בְּקָנֶה וְלֹא בְּמַגָּל וְלֹא בִּמְגֵרָה וְלֹא \u0010c9\u0011 בְּקַרְדֹּם, אֶלָּא בְּקוֹפִיץ. וְלֹא יַכְנִיסֶנּוּ בְּחֵדֶר וְיִנְעֹל בְּפָנָיו עַד שֶׁיָּמוּת, שֶׁנֶּאֱמַר: וַעֲרַפְתּוֹ. \u0005(שְׁמוֹת יג, יג, לד, כ)\u0006.\nמִצְוַת פְּדִיָּה \u0010y7\u0011 קוֹדֶמֶת לְמִצְוַת עֲרִיפָה.\nחֲמוֹרָה שֶׁלֹּא בִּכְּרָה, \u0010y8\u0011 וְיָלְדָה שְׁנֵי זְכָרִים \u0010y9\u0011 נוֹתֵן טָלֶה אֶחָד לַכֹּהֵן. זָכָר וּנְקֵבָה, סָפֵק, וּמַפְרִישׁ טָלֶה אֶחָד כְּדֵי לְהַפְקִיעַ קְדֻשָּׁה מִמֶּנּוּ עַד שֶׁיִּהְיֶה מֻתָּר בַּהֲנָאָה, שֶׁמָּא הַזָּכָר נוֹלַד תְּחַלָּה וְטָלֶה זֶה שֶׁהִפְרִישׁ, לַבְּעָלִים וְאֵינוֹ לַכֹּהֵן, שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה.\nשְׁתֵּי חֲמוֹרוֹת שֶׁלֹּא בִּכְּרוּ, וְיָלְדוּ שְׁנֵי זְכָרִים, נוֹתֵן שְׁנֵי טְלָאִים לַכֹּהֵן. זָכָר וּנְקֵבָה, הַזָּכָר לַכֹּהֵן. שְׁנֵי זְכָרִים וּנְקֵבָה, אֶחָד לַכֹּהֵן, וְעַל הַשֵּׁנִי מַפְרִישׁ טָלֶה אֶחָד וְהוּא לְעַצְמוֹ. שְׁנֵי זְכָרִים וּשְׁתֵּי נְקֵבוֹת, אוֹ שְׁתֵּי נְקֵבוֹת וְזָכָר, אֵין לַכֹּהֵן כְּלוּם. \u0010y10\u0011 \u0010c10\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּצָרִיךְ לְהַפְרִישׁ, וְהֵם לְעַצְמוֹ (טוּר)\u0006.\nאַחַת בִּכְּרָה וְאַחַת לֹא בִּכְּרָה, וְיָלְדוּ שְׁנֵי זְכָרִים, נוֹתֵן טָלֶה אֶחָד לַכֹּהֵן. זָכָר וּנְקֵבָה, מַפְרִישׁ טָלֶה וְהוּא לְעַצְמוֹ.\nהַלּוֹקֵחַ חֲמוֹרָה מֵעוֹבֵד כּוֹכָבִים, וְאֵין יָדוּעַ אִם בִּכְּרָה, וְיָלְדָה זָכָר, פּוֹדֶה אוֹתוֹ בְּשֶׂה וְהוּא לַבְּעָלִים, מִפְּנֵי שֶׁהוּא סָפֵק.\nיִשְׂרָאֵל שֶׁיָּרַשׁ מֵאֲבִי אִמּוֹ כֹּהֵן פֶּטֶר חֲמוֹר וַדַּאי, \u0010c11\u0011 וְאוֹתוֹ הַכֹּהֵן יְרָשׁוֹ מֵאֲבִי אִמּוֹ יִשְׂרָאֵל, \u0010y11\u0011 מַפְרִישׁ טָלֶה וְהוּא שֶׁלּוֹ.\nגֵּר שֶׁבִּכְּרָה חֲמוֹרָתוֹ, סָפֵק קֹדֶם שֶׁנִּתְגַּיֵּר אוֹ אַחַר כָּךְ, מַפְרִישׁ עָלָיו טָלֶה וְהוּא שֶׁלּוֹ.\nכֹּהֲנִים וּלְוִיִּים פְּטוּרִים מִבְּכוֹר בְּהֵמָה טְמֵאָה. \u0005וְהוּא הַדִּין כֹּהֶנֶת וּלְוִיָּה, אֲבָל בַּעֲלֵיהֶם חַיָּבִים בְּפֶטֶר חֲמוֹר שֶׁלָּהֶם. אֲבָל בְּנִכְסֵי מְלוֹג שֶׁלָּהּ פְּטוּרִים, שֶׁהֲרֵי יֵשׁ לָהּ שֻׁתָּפוּת בַּהֲדֵיה (תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן שס\"ו)\u0006.\nשֻׁתָּפוּת הָעוֹבֵד כּוֹכָבִים, פּוֹטֵר בּוֹ. וְכָל דִּינֵי שֻׁתָּפוּת הָעוֹבֵד כּוֹכָבִים בִּטְהוֹרָה, כֵּן דִּינוֹ בִּטְמֵאָה, אֶלָּא שֶׁאָסוּר לְהִשְׁתַּתֵּף עִמּוֹ כְּדֵי לְהַפְקִיעַ קְדֻשָּׁתוֹ, כֵּיוָן שֶׁאֶפְשָׁר בִּפְדִיָּה אוֹ בַּעֲרִיפָה.\nשֻׁתָּפוּת כֹּהֵן אוֹ לֵוִי, פּוֹטֵר בּוֹ.\nעוֹבֵד כּוֹכָבִים שֶׁהִפְרִישׁ פֶּטֶר חֲמוֹר, \u0010y12\u0011 מוֹדִיעִין אוֹתוֹ שֶׁאֵינוֹ \u0010c12\u0011 חַיָּב וַהֲרֵי הוּא מֻתָּר בְּגִזָּה וַעֲבוֹדָה.\nפָּרָה שֶׁיָּלְדָה כְּמִין חֲמוֹרָה, וַחֲמוֹרָה שֶׁיָּלְדָה כְּמִין פָּרָה, נִתְבָּאֵר בְּסִימָן שט\"ו.",["\u0003אין פודין כו'. \u0004בכל אלו אין פודין בסתמא אלא בשוייו כן הוא בטור והוא פשוט וזה שכתב הרב בסעיף ה' ואז יכול לפדותו בכל דבר:","\u0003לא אמרה תורה להחמיר עליו כו'. \u0004כלומר שהקדש ושאר דברים נפדים בכל דבר ופטר חמור לא יהא נפדה רק בשה ולא בשויו:","\u0003שדינו שמפריש עליו טלה והוא שלו. \u0004כדלקמן סעיף י' ורשאי אחר כך לחזור ולפדות עליו ודאי פטר חמור וכן כשיש לו כמה ספיקות פטרי חמור מפריש עליהן טלה א' בשביל כולן והוא שלו:","\u0003לפיכך מיד כו'. \u0004ואין להמתין עד שיתן הפדיון ליד כהן דהא פדוי הוא מעכשיו:","\u0003דמיו אסורים. \u0004אפי' מה ששוה יותר על השה דכיון שלא הודיע ללוקח שהוא פטר חמור לא יפדנו וכולו אסור:","\u0003והכהנים חשודים על דבר זה. \u0004מפני שאומרים מה אני צריך להפריש עליו טלה כיון שהוא לעצמי:","\u0003ומעכב הטלה לעצמו. \u0004שהמע\"ה:","\u0003קודמת כו'. \u0004דכתיב ואם לא תפדה וערפתו משמע שפדייה קודמת:","\u0003וילדה ב' זכרים. \u0004ואינו מכיר הבכור:","\u0003נותן טלה אחד לכהן. \u0004משום שא' מהן ודאי בכור ושניהם אסורים בהנאה עד שיפדה:","\u0003וי\"א כו'. \u0004מטעם דנהי דפטור ליתן לכהן מספק משום המע\"ה מ\"מ צריך הפרשה דאפקועי איסורייהו הלכך בב' זכרים וב' נקבות מפריש שני טלאים והם לעצמו ובזכר וב' נקבות מפריש טלה א' והוא לעצמו וטעם סברא הראשונה דבספיקות הראשונות הואיל ועל כל פנים צריך לעשות מעשה לתת דבר לכהן הטילו עליו ג\"כ לעשות הפרשה לאפקועי גם כן הספק מן האיסור אבל באלו האחרונות שא\"צ לתת לכהן כלום הקילו עליו גם כן שרבוי הספקות גם כן מן ההפרשה ועיין ב\"י:","\u0003מפריש טלה כו'. \u0004הטעם שזה הישראל היורש את הכהן אין צריך לעשות יותר ממה שהיה צריך לעשות הכהן המורישו והכהן המוריש לא היה צריך לעשות אלא להפריש עליו שה להפקיע קדושה שחלה עליו בבית ישראל הראשון המורישו והוא נוטל השה לעצמו דכהן הוא הכי נמי עושה זה הישראל היורשו דהוי כמו שהורישו הכהן השה:","\u0003מודיעים אותו כו'. \u0004כדי שלא יאמר העובד כוכבים ישראל מזלזלין בקדשים כי אין הקדשו זה הקדש ומותר בגיזה ועבודה:"],["\u0003אלא בחמורים. \u0004שנאמר פטר חמור:","\u0003מן הכשבים כו'. \u0004שהכל נקרא שה כפרש\"י בחומש:","\u0003לא בעגל כו'. \u0004פירוש בתורת פדיון שיש בשה כמ\"ש בסעיף ה' אבל בשויו פודה אפילו בעגל:","\u0003ואם פדה פדוי. \u0004ואין צריך פדיון אחר מספק כיון שאינו קדוש קדושת הגוף כמו ספק בכור:","\u0003הוי ספק. \u0004פירוש אם אחר כך מת הפטר חמור קודם שנתן זה הפדיון לכהן לא חייב ליתן אותו להכהן דיכול ישראל לומר שמא לא חל עליו הפדיון ואם אחר שנתנו לכהן מת הפטר חמור ישאר הפדיון לכהן כיון שהוא מוחזק דהא נתנו הוא עצמו לו ואין זה דומה לתקפו כהן דמוציאין מידו כדלעיל סימן שט\"ו ויש להקשות אמה שכתוב בתשובת מהרי\"ל סימן קע\"ד בספק בכור שנתנו הישראל לכהן ואחר כך נודע לו שלא היה צריך ליתנו לו מדינא ואילו ידע זה מתחלה לא היה נותנו לו הוי ליה כתקפו כהן ומוציאין מידו ומדמה אותו לשולח מעות לחבירו ליתנו ליד עובד כוכבים ושכחו העובד כוכבים דהדרי זוזי למארייהו דאדעתא דהכי לא שלח ליה והוא בח\"מ סימן קפ\"ג ולכאורה סותר הך דהכא דהא גם כן ספיקא הוה ויכול לומר אילו הייתי יודע שאין זה פדיון לא הייתי נותנו לך ויש לומר דשאני הכא דבשעת הפדיון היה לכהן על כל פנים חיובו עליו ליתן לו פדיון טוב אלא שטעה וסבר שזהו פדיון טוב ע\"כ יחזיקנו הכהן מה שאין כן בספק בכור דיש ספק אם חייב לו כלל:","\u0003או במקום שיש לו ספק כו'. \u0004פירוש ויש לו הרבה מהם פודה כולן בשה אחד כן הוא בטור:","\u0003מברך אשר קדשנו כו'. \u0004בפרישה הקשה למה לא מברכין גם כן אנתינת בכור בהמה טהורה לכהן כמו בפדיון פטר חמור ובפדיון בכור אדם ותירץ דאין מברך אלא כשנשאר בידו ממה שהיה קודש ונותן מידי אחרינא תחתיו משא\"כ בנתינת בכור דנותנו כולו לכהן ולא נשאר בידו כלום מהקדושה ואין זה מספיק לי דמכל מקום למה לא יברך על המצוה דמה לי בכך שלא נשאר בידו כיון דמכל מקום מקיים מצות השם ב\"ה ונראה לי דאין שייך ברכה אלא במה שעושה האדם משלו על זה מברך שזכה לעשות משלו רצון המקום ב\"ה משא\"כ בבכור דמעולם לא היה לישראל זכות בו דמשנולד הוא בי גזא דרחמנא והוה כאילו לא נולד לו אותו הבכור אלא כאילו נולד בבית כהן מפרתו דרחמנא זכה לו בכך כמ\"ש כל פטר רחם לי הוא ע\"כ אין שייך לברך כי הוא אינו עושה כלום מממונו משא\"כ בפדיון פטר חמור ובכור [אדם] שהוא נותן ממונו בזה ע\"כ הוא מברך שפיר על מצוה זאת כן נראה לי וסיים בטור בזה וא\"צ להמתין בברכה עד שיתן הפדיון לכהן:","\u0003מותר למכרו בכה\"ג. \u0004היינו כדעת הטור על פי הרא\"ש שכתב וז\"ל ה\"ד הנאת דמיו דאסור כגון דמזבין ליה למאן דלא ידע שהוא פטר חמור ושקיל מיניה כנגד כולו אבל למישקל מיניה מאי דשוה טפי משה קטן שהלוקח זקוק לפרוע עליו דמים שפיר דמי עכ\"ל. ולמד הטור שעיקר ההיתר במה שאינו לוקח כל המעות רק מניח אצלו בעד השה וא\"ל אם כן אמאי תלה ברישא האיסור במה שלא הודיעו הא אפילו בהודיעו אסור כד שקיל דמי כולו י\"ל אין ה\"נ אלא דאורחא דמילתא נקיט דכל שהוא מודיעו ודאי אין הלוקח נותן דמי כולו שהרי יודע שיצטרך ליתן שה לכהן אבל אי מתרמי שאחד נותן דמי כולו אע\"פ שיודע שיצטרך ליתן שה איסורא קא עביד המוכר הכי סבירא ליה לטור אבל הבית יוסף פירש דברי הרא\"ש דבהודעה תליא הכל דאם הוא מודיעו מותר לקבל כל המעות אע\"פ שאין מנכה לו דמי השה דאמרינן דהפטר חמור חביב הוא בעיני הלוקח שמוותר בזה בדמי המקח או אמרינן מתנה נתן לו אותן דמי השה ומשמע מדברי רמ\"א שפוסק כהטור ולע\"ד נראה דכיון שבשעה שמוכר לו הפטר חמור ומודיעו ודאי שניהם לא נתכוונו על מה שאסור בו רק על ההיתר ואם כן כל מה שקוצץ בעדו בשעת המכירה לא נתכוין אלא שיתן לו סך ההוא בעד ההיתר דהיינו מה ששוה אחר שיתן שה לכהן ואע\"פ שבשוק אינו שוה כן מכל מקום זה לא נתכוין אלא דוקא בסך זה וכדרך שמצינו לענין אונאה דבכלים של בעל הבית אין להם אונאה שאינו מוכר חפציו אלא ביוקר דוקא ואין איסור בזה אלא כשמפרש בהדיא שסך זה יתן לו בעד כולו ולא יתן שה לכהן. כן נראה לי:","\u0003שערו מסובך. \u0004הרא\"ש נתן טעם שלא נאסרה בו גיזה אלא בתורת הנאה אבל בלאו דלא תגוז ליתא כיון דלית ביה קדושת דמים וגרע נמי משאר קדושת דמים דפדיונן קודש וזה פדיונו חולין עכ\"ל:","\u0003אלא בקופיץ. \u0004הוא סכין גדול ודרך לערוף בו. כ\"כ רש\"י:","\u0003וי\"א דצריך להפריש. \u0004זהו דעת הטור והדעה הראשונה היא דעת הרמב\"ם דס\"ל בשני זכרים ושתי נקבות או זכר ושתי נקבות א\"צ להפריש טלה והוא לעצמו וטעמו מבואר ברמב\"ם וז\"ל לפי שיש כאן ספיקות הרבה שמא האחת ילדה זכר והשניה ילדה ב' נקבות או שמא זו ילדה נקבה והאחרת זכר ואחריו נקבה או נקבה ואחריה זכר וכן בב' זכרים וב' נקבות יש ספיקות הרבה עכ\"ל זה תמוה דמה זכות יש להפטר מהפרשה במה שכתב שמא ילדה הראשונה זכר או השניה זכר ואח\"כ נקבה בתרוייהו יש צד חיוב על הבעלים להפריש טלה ולא נשאר אלא ספק שמא תרוייהו ילדו נקבות והאחת זכר אחר הנקבה ולמה אמר שיש ספיקות הרבה וכן הקשה בדרישה ואמר שיש לישבו בדוחק ולע\"ד נראה דכך היא ההצעה במקום שאין צד לומר שהוא פטור לגמרי חייב הבעל ליתן שה להכהן אע\"פ שאין ברור בעד איזה נותן ועל כל אחת יוכל לומר לא זאת החייבת מ\"מ הבעל הוא אחד ויש ממון כהן בידו. ואם יש צד לפטור לגמרי כגון חמורה אחת וילדה זכר ונקבה מ\"מ כיון שאין כאן רק שני צדדים האחד לחיוב והשני לפטור חייב להפקיע איסור בהפרשת טלה והוא לעצמו ואפי' בב' זכרים וחד נקבה מב' חמורות דיש כאן עוד לטיבותא דהיינו שאין מבורר איזה חייבת דעל כל אחת יכול לומר שמא זאת ילדה נקבה תחילה ואח\"כ זכר מ\"מ כיון שאין צד לומר שנפטר הבעל לגמרי על כן בטלה האי מעלה מה שאין מבורר איזה החייבת וע\"כ צריך להפריש טלה אבל אם יש צד שהוא פטור לגמרי מהני האי מעלה מה שאין מבורר איזה החייבת וע\"כ אם ילדו שתי חמורות זכר ושתי נקבות דתחילה יש ספק איזה חייבת וע\"כ אמר שמא האחת ילדה זכר והיא החייבת והשניה ילדה שתי נקבות ופטורה לגמרי וי\"ל איפכא שמא זו ילדה נקבה ופטורה והשניה ילדה זכר תחילה ואח\"כ נקבה נמצא שאין מבורר איזה החייבת וכיון שיש ספק ג' שמא האחת ילדה נקבה והשניה נקבה תחילה ואח\"כ זכר שאפשר להפטר לגמרי על כן מהני המעלה הראשונה במה שאין מבורר וזה שקרא הרמב\"ם ספיקות הרבה וכן הוא ממש בשני זכרים וב' נקבות נמצא דדברי הרמב\"ם הם מרווחים בלי שום דוחק אלא שהרא\"ש והטור חולקים מ\"מ עליו כיון שאין לו היזק במה שמפריש טלה שהרי הוא לעצמו למה לא יפרישנו להפקיע את האיסור:","\u0003ואותו הכהן ירשו כו'. \u0004דאלו פטר חמור של הכהן עצמו הוא פטור וכן כ' רש\"ל ועיין בדרישה שהביא לשונו:","\u0003והרי הוא מותר. \u0004פי' אפי' לישראל. רש\"ל:"]],["\u0003הלכות חלה\u0004\nמִצְוַת עֲשֵׂה לְהַפְרִישׁ תְּרוּמָה מֵהָעִסָה וְלִתְּנָהּ לְכֹהֵן, שֶׁנֶּאֱמַר: רֵאשִׁית עֲרִסֹתֵכֶם תָּרִימוּ תְרוּמָה \u0005(בַּמִּדְבָּר טו, כ)\u0006 וְרֵאשִׁית זֶה \u0010y0\u0011 אֵין לוֹ שִׁעוּר מִן הַתּוֹרָה, אֲפִלּוּ הִפְרִישׁ כִּשְׂעוֹרָה, פָּטַר אֶת הָעִסָה. וְהָעוֹשֶׂה כָּל עִסָתוֹ חַלָּה, לֹא עָשָׂה כְּלוּם, \u0010c0\u0011 עַד שֶׁיְּשַׁיֵּר מִקְצָת. וּמִדִּבְרֵי סוֹפְרִים מַפְרִישִׁין אֶחָד מִכ\"ד מִן \u0010y1\u0011 הָעִסָה. וְהַנַּחְתּוֹם הָעוֹשֶׂה לִמְכֹּר בַּשּׁוּק, מַפְרִישׁ אֶחָד מִמ\"ח. \u0010y2\u0011 וְאִם נִטְמְאָה הָעִסָה בְּשׁוֹגֵג אוֹ בְּאֹנֶס, אַף בַּעַל הַבַּיִת מַפְרִישׁ אֶחָד מִמ\"ח.\nאֵין חַיָּבִים בְּחַלָּה מִן הַתּוֹרָה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל בִּלְבַד, שֶׁנֶּאֱמַר: וְהָיָה בַּאֲכָלְכֶם מִלֶּחֶם הָאָרֶץ \u0005(בַּמִּדְבָּר טו, יט)\u0006 וּבִזְמַן שֶׁכָּל יִשְׂרָאֵל שָׁם שֶׁנֶּאֱמַר בְּבֹאֲכֶם \u0005(בַּמִּדְבָּר טו, יח)\u0006 בִּיאַת כֻּלְּכֶם וְלֹא בִּיאַת מִקְצַתְכֶם. לְפִיכָךְ חַלָּה בַּזְּמַן הַזֶּה \u0010y3\u0011 אֲפִלּוּ בִּימֵי עֶזְרָא בְּאֶרֶץ יִשְׂרָאֵל, אֵינָהּ אֶלָּא מִדִּבְרֵיהֶם.\nמַפְרִישִׁין חַלָּה בְּחוּצָה לָאָרֶץ מִדִּבְרֵי סוֹפְרִים, כְּדֵי שֶׁלֹּא תִּשָּׁכַח תּוֹרַת חַלָּה מִיִּשְׂרָאֵל. \u0010c1\u0011\nג' דִּינִים לְחַלָּה בְּשָׁלֹשׁ אֲרָצוֹת: \u0010y4\u0011 כָּל הָאֶרֶץ שֶׁהֶחֱזִיקוּ בָּהּ עוֹלֵי בָּבֶל עַד כְּזִיב, מַפְרִישִׁין בָּהּ חַלָּה אַחַת, כַּשִּׁעוּר, וְהִיא נֶאֱכֶלֶת לַכֹּהֲנִים; וּשְׁאָר אֶרֶץ יִשְׂרָאֵל, שֶׁהֶחֱזִיקוּ בָּהּ עוֹלֵי מִצְרַיִם וְלֹא עוֹלֵי בָּבֶל, \u0010y5\u0011 שֶׁהוּא מִכְּזִיב וְעַד אֲמָנָה, מַפְרִישִׁין בָּהּ שְׁתֵּי חַלּוֹת, הָרִאשׁוֹנָה אֶחָד מִמ\"ח וְהִיא נִשְׂרֶפֶת; וְהַשְּׁנִיָּה אֵין לָהּ שִׁעוּר, וְנוֹתְנִים אוֹתָהּ לַכֹּהֵן לְאָכְלָהּ. \u0010y6\u0011 וְכָל הָאָרֶץ מֵאֲמָנָה וְלַחוּץ, בֵּין בְּסוּרְיָא בֵּין בִּשְׁאָר אֲרָצוֹת, מַפְרִישִׁין שְׁתֵּי חַלּוֹת, הָרִאשׁוֹנָה אֵין לָהּ שִׁעוּר, וְהִיא נִשְׂרֶפֶת; וְהַשְּׁנִיָּה, א' מִמ\"ח, וְנֶאֱכֶלֶת, וּמֻתֶּרֶת לִטְמֵאִים אֲפִלּוּ לְזָבִים וְזָבוֹת. וּבַזְּמַן הַזֶּה, שֶׁאֵין עִסָה טְהוֹרָה, מִפְּנֵי טֻמְאַת הַמֵּת, מַפְרִישִׁין חַלָּה אַחַת בְּכָל אֶרֶץ יִשְׂרָאֵל, אֶחָד מִמ\"ח, \u0010y7\u0011 וְשׂוֹרְפִין אוֹתָהּ, מִפְּנֵי שֶׁהִיא טְמֵאָה. וּמִכְּזִיב וְעַד אֲמָנָה, מַפְרִישִׁין שְׁנִיָּה לְכֹהֵן לַאֲכִילָה, וְאֵין לָהּ שִׁעוּר, כְּשֶׁהָיָה הַדָּבָר \u0010c2\u0011 מִקֹּדֶם.\nחַלַּת חוּצָה לָאָרֶץ, אַף עַל פִּי שֶׁהִיא טְמֵאָה, הוֹאִיל וְעִקַּר חִיּוּבָהּ מִדִּבְרֵיהֶם, אֵינָהּ אֲסוּרָה בַּאֲכִילָה אֶלָּא עַל כֹּהֵן שֶׁטֻּמְאָה יוֹצְאָה עָלָיו מִגּוּפוֹ, וְהֵם בַּעֲלֵי קְרָיִים וְזָבִים וְזָבוֹת וְנִדּוֹת וְיוֹלְדוֹת. אֲבָל שְׁאָר הַטְּמֵאִים בְּמַגַּע הַטֻּמְאוֹת, אֲפִלּוּ טִמְאֵי מֵת, מֻתָּרִים לְאָכְלָהּ. \u0010y8\u0011 לְפִיכָךְ, בֵּין בְּסוּרְיָא בֵּין בְּחוּצָה לָאָרֶץ, אִם רָצָה לְהַפְרִישׁ חַלָּה אַחַת, מַפְרִישׁ אֶחָד מִמ\"ח וְנֶאֱכֶלֶת לְקָטָן שֶׁעֲדַיִן לֹא רָאָה קֶרִי, אוֹ לִקְטַנָּה שֶׁעֲדַיִן לֹא רָאֲתָה נִדָּה, \u0010c3\u0011 וְאֵינוֹ צָרִיךְ לְהַפְרִישׁ שְׁנִיָּה. וְכֵן אִם הָיָה שָׁם כֹּהֵן גָּדוֹל שֶׁטָּבַל מִשִּׁכְבַת זַרְעוֹ אוֹ מִזִּיבָתוֹ, אַף עַל פִּי שֶׁלֹּא הֶעֱרִיב שִׁמְשׁוֹ \u0005וְיֵשׁ אוֹמְרִים שֶׁצָּרִיךְ הַעֲרֵב שֶׁמֶשׁ (הר\"ן פ' אֵלּוּ עוֹבְרִין)\u0006, הֲרֵי זֶה מֻתָּר לֶאֱכֹל חַלָּה הָרִאשׁוֹנָה, וְאֵינוֹ צָרִיךְ לְהַפְרִישׁ שְׁנִיָּה בְּחוּצָה לָאָרֶץ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים כֵּיוָן שֶׁאֵין חַלָּה נֶאֱכֶלֶת בַּזְּמַן הַזֶּה בְּאֶרֶץ יִשְׂרָאֵל, גַּם בִּשְׁאָר מְקוֹמוֹת אֵין צְרִיכִין לְהַפְרִישׁ רַק חַלָּה אַחַת, וּלְשָׂרְפָהּ (טוּר בְּשֵׁם י\"א וּשְׁאָר פּוֹסְקִים)\u0006. \u0010c4\u0011 וְכֵן הַמִּנְהָג פָּשׁוּט בְּכָל מְדִינוֹת אֵלּוּ, שֶׁאֵין מַפְרִישִׁין רַק חַלָּה אַחַת בְּלֹא שִׁעוּר, וְשׂוֹרְפִין אוֹתָהּ כְּמוֹ שֶׁהָיוּ עוֹשִׂין כְּשֶׁמַּפְרִישִׁין שְׁתֵּי חַלּוֹת, שֶׁחַלַּת הָאוּר לֹא הָיָה לָהּ שִׁעוּר. וּמִכָּל מָקוֹם נוֹהֲגִין לִטֹּל כַּזַּיִת \u0005(מהרי\"ל)\u0006. וְהָאוֹכֵל חַלָּה, אֲפִלּוּ בְּחוּצָה לָאָרֶץ, מְבָרֵךְ תְּחַלָּה עַל הַמִּין שֶׁרוֹצֶה לֶאֱכֹל, וְאַחַר כָּךְ מְבָרֵךְ: אֲשֶׁר קִדְּשָׁנוּ בִּקְדֻשָּׁתוֹ שֶׁל אַהֲרֹן וְצִוָּנוּ לֶאֱכֹל תְּרוּמָה \u0005(כָּל בּוֹ וְהוּא מל' הַרַמְבַּ\"ם סוֹף הִלְכוֹת תְּרוּמָה)\u0006. וְיֵשׁ אוֹמְרִים כְּשֶׁשּׂוֹרְפִין הַחַלָּה עוֹשִׂין לָהּ הֶסֵּק בִּפְנֵי עַצְמָהּ, דְּיִשְׂרָאֵל אָסוּר לֵהָנוֹת מִמֶּנָּהּ \u0005(מהרי\"ק וְכֵן הוּא בְּתוֹסָפוֹת פ' כָּל שָׁעָה)\u0006. וְנוֹהֲגִין לְהַשְׁלִיכָהּ לַתַּנּוּר קֹדֶם שֶׁאוֹפִין הַפַּת.",["\u0003אין לו שיעור. \u0004בין שיפריש רק מעט או הרבה פוטר העיסה כדמפרש ואזיל:","\u0003והנחתום כו'. \u0004דמשום הפסד ממכרו הקילו בו כן כ' העט\"ז אבל הרמב\"ם ר\"פ ה' מהל' בכורים כ' הטעם לפי שהנחתום עיסתו מרובה ויש בשיעור זה כדי מתנה ואפי' עושה עיסה קטנה מפריש א' ממ\"ח שלא לחלק בעיסת הנחתום וכן בע\"ה אפי' עושה עיסה מרובה כגון למשתה בנו וכה\"ג מפריש אחד מכ\"ד שלא לחלק בעיסת הבעה\"ב עכ\"ד וכ\"כ הברטנורה וכן מבואר בירושלמי ספ\"ב דחלה ומביאו ב\"י לקמן ר\"ס שכ\"ח:","\u0003ואם נטמאה כו'. \u0004הואיל ולשרפה עומדת וכב\"י לקמן ר\"ס שכ\"ח דבזמן הזה דליכא טהרות א\"כ כל עיסה טמאה א\"כ אף של בע\"ה לעולם הוי א' ממ\"ח והביא שם דברי הרשב\"א שכ' כן דעכשיו שכל העיסות אינן טהורות לעולם הוי אחת ממ\"ח ואפי' במקום שנותנין חלה לכהן:","\u0003אפילו בימי עזרא כו'. \u0004שהרי לא עלו כל ישראל עמו:","\u0003כל הארץ כו'. \u0004עד כזיב שהוא ארץ ישראל גמור והיא נאכלת לכהנים בטהרה:","\u0003שהוא מכזיב ועד אמנה. \u0004שהיא קרובה לארץ העמים ואין יכולין לשמור עצמן ופירותיהן בטהרה וחלותיהן טמאות וטעונים שרפה כתרומה טמאה ולכך מפרישין ב' חלות א' שהיא מה\"ת צריך להפריש כשיעור ולפי שהיא טמאה נשרפת והשניה תקנו רבנן כדי שלא תשתכח תורת חלה הלכך כיון שאינה אלא כדי שלא תשתכח תורת חלה אין לה שיעור דאוקמוה אדאורייתא:","\u0003וכל הארץ מאמנה ולחוץ כו'. \u0004שאינו שייך לא\"י כלל ואין שם אפי' אחת מן התורה גזרו בהן משום א\"י ותקנו ג\"כ להפריש ב' חלות והראשונ' שנשרפה אין לה שיעור הואיל ואינה מן התורה והשניה אחד ממ\"ח כיון שהיא נאכלת לכהנים ומותרת לטמאים כיון שאינה אלא מדרבנן לגמרי:","\u0003ושורפין אותה כו'. \u0004כתב מהרי\"ל בהלכות פסח וצריך לשורפה במדורת כהן או כהנת לפי' ר\"ת דפי' כן בפ' כ\"ש שכ\"כ מהר\"ם כו' ונכון לעשות לה מדורה לעצמה במקום שאין מבשלין שם או בתנור שאופין בו המצות טרם הורדו לתוכו המצות שאז ידוע לו שלא תבא לידי הנאת ישראל טרם כליא איסוריה כו' וכ\"כ מהרי\"ו בדיני פסח סי' קנ\"ג בשם תוס' פ' כל שעה ושיש לעשות כן בשאר מצות לעשות לה היסק בפני עצמה ומביאו הרב בס\"ס זה ונ\"ל דוקא הנאה דשרפה אסור לזר אבל שאר הנאה מותר לזר כדאמרי' גבי תרומה לקמן סי' של\"א סי\"ט בהג\"ה:","\u0003לפיכך בין בסוריא בין בח\"ל כו'. \u0004כלומר כיון שבשאר טמאים מותר לאכלן הלכך קטן וקטנה שאין עליהם טומאה מגופם אע\"פ שלא נזהרו מטומאת מת וכה\"ג אוכלין אותה וא\"צ להפריש אחרת כלל אבל היכא דליכא קטן או קטנה או גדול שטבל לקריו מפריש אחת לאור ואין לה שיעור ואחת לכהן ויש לה שיעור ומותרים לאכלה בטומאה לזבים וזבות ולנדות וליולדות כמו שנתבאר והי\"א בהג\"ה ס\"ל דבכל ענין אין מפרישין האידנא רק חלה אחת אפי' אין שם כהן טהור רק מי שטומאה יוצאת ממנו מגופו אין מפרישין אלא חלה אחת והטעם כתבו הפוסקים לפי שצריך לשמרה מזרים ומעובדי כוכבים וגם פעמים שנותנין אותם בקערה במרק רותח ועתה אסור זר לאכלה בקערה ומשמע דהי\"א פליגי נמי היכא דאיתא כהן קטן או גדול טהור אין ליתן להם לאכלה רק שורפין אותה וכ\"כ מהרש\"ל פ' כ\"ה סי' ס' דאין נוהגין לתת חלה כלל לקטן משום דלא מחזקינן בזמן הזה בכהן ודאי וכן כתב מהרי\"ל בהלכות פסח דדרכו לדרוש ברבים שלא להאכילה לכהן. קטן שלא יאמרו חלת ח\"ל נאכלת וכ\"כ מהרי\"ו בתשו' סימן קנ\"ג בדיני פסח דאין נוהגין לתת החלה לכהן קטן והטעם נ\"ל דחיישינן שמא יפרר ואתי לידי תקלה או משום דלא מחזקינן בזמן הזה בכהן ודאי עכ\"ל וכ\"כ הרב בא\"ח ס\"ס תנ\"ז אע\"ג דסתם שם בתחלה כסברת הטור דמאכילין אותו לכהן קטן והכי נהגינן האידנא בחלות דמצה ובחלות דכל ימות השנה לא נהגינן ליתנה לכהן קטן וצריך לחלק בין פסח לשאר ימות השנה:"],["\u0003עד שישייר מקצת. \u0004שנאמר ראשית בעינן ראשית ששיריה ניכרין:","\u0003שלשה דינים לחלה כו'. \u0004יש כאן שתי שיטות האחת היא שיטת התוס' והרא\"ש פ' כל הבשר בקיצור תנן שלש ארצות לחלה מא\"י עד כזיב חלה אחת מכזיב עד הנהר ועד אמנון ב' חלות אחת לאור ואחת לכהן של אור יש לה שיעור ושל כהן אין לה שיעור מן הנהר ועד אמנון ולפנים שתי חלות אחת לאור ואחת לכהן של אור אין לה שיעור ושל כהן יש לה שיעור וטבול יום אוכלה רבי יוסי אומר אינו צריך טבילה ואסורה לזבים ולזבות לנדות וליולדות ופירש הרא\"ש דדין שתי חלות שנזכר במציעתא במשנה זו הטעם לפי שאותו המקום הוא סמוך לארץ העמים והוא מקום טומאה ואין יכולין לשמור עצמם ופירותיהם בטהרה וחלותי' טמאות וטעונות שריפה כחלה טמאה לכך חלה אחת לאור ותקנו להפריש עוד אחרת לכהן לאכילה שלא תשתכח תורת חלה אבל אותה של אור היא מדברי תורה יש לה שיעור ומה שנזכר בסיפא דמתני' שתי החלות היינו מדברי סופרים ע\"כ חלה הנאכלת חשובה טפי ויש לה שיעור וטבול יום אוכל החלה השניה אף ע\"פ שלא העריב שמשו כיון שאינה אלא משום שלא תשתכח תורת חלה (ונראה דגם במציעתא אמרי' כן בחלה של כהן) והא דאמרינן ואסור לזבים כו' היינו בלא טבילה וקמ\"ל דאף דלר' יוסי אין צריכין טבילה בבעלי קריין מ\"מ בהנך צריך טבילה ולרבנן בטומאה שאינה יוצאה מגופו כגון טומאת מגע מת כיון שאין יוצאה מגופו ג\"כ א\"צ טבילה ויש עוד דין רביעי דהיינו מה שזכרנו בפ' עד כמה אמר רבינא הלכתא נדה קוצה חלה ואכיל כהן קטן ואי ליכא כהן קטן שקלא לה בריש מפה ושדייה לתנורא והדר מפרישה חלה אחרת כי היכי דלא לישתכח תורת חלה ואכיל לה אפילו כהן שהוא גדול נמצא היכא דאיכא כהן קטן אין צריכין להפריש חלה אחרת ואע\"ג דבדין הסיפא דמתני' חלת האור אינה נאכלת כלל כמו בחלת האור שברישא וצריך לעולם ב' חלות שאני דין הסיפא שאותן מקומות סמוכים לא\"י ומתחזי חלה דידהו כחלת א\"י גזרו טומאה שלא לאכלה אפי' כהן טהור גמור אבל הדין הרביעי איירי במקומות הרחוקים כגון בכל ולא מתחזי כחלת א\"י לא גזרו איסור מחמת טומאת עצמו ונאכלת לכהן קטן ולא הצריכו להפריש חלה אחרת וה\"ה לכהן שהוא גדול וטבל לקריו ואע\"פ שלא העריב שמשו וכמו שהקילו בדין הרביעי כשיש כהן קטן שאין צריכין להפריש חלה אחרת ולשרוף את זו כמו בדין השלישי הכי נמי הקילו שמותרת החלה הנאכלת לזבין ולזבות דלא כחלה הנאכלת בדין הג' ע\"כ והרמב\"ם יש לו שיטה אחרת דהיינו שעושה מן דין הג' והדין הד' הכל א' וחשיב הכל לח\"ל ואין מפליג בין קרוב לא\"י או רחוק דגם בקרוב הוה הדין כמו שנזכר בדין הד' ועיקר החילוק בין מציעתא לסיפא הוה בזה דברישא הוה א\"י ממש לכל דבר דהיינו שאותו הגבול כבשוהו עולי מצרים וגם עולי בבל ע\"כ אין שם אלא חלה אחת ובמציעתא הוה מקום שכבשוהו עולי מצרים ולא עולי בבל ע\"כ מפרישין ב' חלות מפני שהראשונה טמאה שהרי לא נתקדשה בימי עזרא וקדושה הראשונה בטלה משגלו והואיל והיא א\"י מפרישין חלה כשיעור ושורפין אותה ומפרישין חלה שנית לאכילת כהן כדי שלא יאמרו תרומה טהורה נשרפת ובדין השלישי והרביעי דלעיל אמרי' בשניהם מפריש שתי חנות אחת לאור כדי שלא יאמרו ראינו תרומה טמאה נאכלת ומוטב לרבות בנאכלת שתהיה כשיעור ובשני דינים האלו מהני כהן טהור שאין צריכין להפריש [רק] חלה אחת וזה מבואר בפי' המשניות להרמב\"ם שאין חילוק בין קרוב לרחוק. אכן דברי הטור אין להם ביאור דהוא דלא כמאן דכתב תחלה ובמקומות הקרובות לה דמשמע דס\"ל כדעת הרא\"ש שמפליג בין סמוכים לא\"י לרחוקים וא\"כ מה שכתב אח\"כ בד\"א כשאין שם כהן טהור כו' קאי אאותן הרחוקים וכמ\"ש בשם הרא\"ש וע\"כ כתב דמותר לזבים כו' דאלו בסמוכים אסור להרא\"ש ואח\"כ סיים ומדברי הרמב\"ם יראה דדוקא בח\"ל כו' דמשמע לפי דעה הראשונה אף בא\"י הוה מהני כהן קטן וזה אינו אליבא דכ\"ע שהרי בא\"י פשיטא דאינה נאכלת ואפי' בסמוכים לה לפי דעת הרא\"ש שזכרנו ובדוחק י\"ל דמ\"ש ומדברי הרמב\"ם כו' רצונו לומר אפי' לדברי הרמב\"ם דאין מחלק בין סמוכים לרחוקים מ\"מ מחלק בין א\"י לח\"ל ואע\"פ שכבר כתב דעכשיו ליכא טהרה בא\"י דהיינו שאין לנו מי חטאת להזאה על טמא מת ע\"כ א\"א לחלה שתהא נאכלת מ\"מ חזר וכתבו כאן שהוא לעיקר הדין מחמת טומאת החלה עצמה שטמאה מחמת מגע ולזה לא מהני טהרה דאדם ובש\"ע כאן העתיק דברי רמב\"ם ותימה על שלא הרגיש בב\"י שיש בזה מחלוקת בין הרמב\"ם להרא\"ש:","\u0003חלת ח\"ל. \u0004והיינו מה שזכר בסעיף ד' וכל הארץ מאמנה ולחוץ כו' כי אין חילוק בין ח\"ל הסמוכה לא\"י לרחוקה לדעת הרמב\"ם כמו שזכרנו:","\u0003ואינו צריך להפריש חלה שניה בח\"ל. \u0004פי' כשיש כהן טהור אבל כשאינו טהור אסור לאכול ממנו כהן שטומאה יוצאה בגופו ואז צריך להפריש שתים אחת לאור ואחת לכהן לאכלה אפילו אם טומאה יוצאה מגופו ולא טבל והטעם שכיון שכבר הפריש אחת לאור והיא העיקר רק בשביל שלא תשתכח כו' הפריש עוד אחת לכהן ע\"כ אין בה קדושה משא\"כ אם יש כהן טהור שאין מפריש רק אחת והיא העיקר ע\"כ צריכה טהרה ואסורה לבעל קרי ולזבים וע\"ז אמרו במשנה ואסור לזבין וכן מביאה בפי' המשניות להרמב\"ם והרבה תיוהות קא חזינא בלבוש כאן שהעתיק דברי הש\"ע כאן והם דעת הרמב\"ם והכניס הוא בתוכה קצת דברים מדעת הרא\"ש דהיינו שעשה חלוקות בין עיירות ח\"ל עצמן בין קרובים לרחוקים דהיינו שכתב שמן העיירות שמן אמנה ולחוץ בין בסוריא בין בשאר הוי החלה השניה דהיינו של כהן אסורה לזבים וזבות ובח\"ל הרחוק התיר לבעל קרי וזבים וזבות ובהדיא כתב הרמב\"ם והעתיקו הש\"ע סעיף א' דבזה מותר לזבים ולזבות אלא ודאי שזהו דעת הרא\"ש ואם בא לפסוק כדעת הרא\"ש לא היה לו לכתוב דבין בסוריא בין בשאר ארצות דמהני כהן קטן שאין צריכין להפריש אלא חלה אחת והרי סוריא היא סמוכה לא\"י כמ\"ש הוא עצמו תחלה ושם לא מהני כהן קטן אלא לעולם צריך להפריש ב' חלות שם כמ\"ש לעיל בשם הרא\"ש דדוקא ברחוק מא\"י מהני כהן קטן שאין צריכין להפריש שתי חלות אלא על כרחך שזהו כדעת הרמב\"ם והוא באמת לשונו ממש וכמו שהעתיק כאן בש\"ע נמצא פסקיו סותרים זה את זה:","\u0003וכן המנהג פשוט כו' ושורפין אותה כו'. \u0004כתב רש\"ל בפ' כל הבשר אין אנו נותנין עכשיו אפי' לכהן קטן וכ\"ש לגדול שטבל לקריו שאין לו היחוס ואין אנו יודעין איזה כהן אמיתי והארכתי בפ' הפרה סי' ל\"ה וכמו שכתב מהרי\"ו אותן האופין בליל י\"ט דפסח שאופין עוגה קטנה וקודם אפייתה אין קוראין לה שם חלה עד שעת הפרשתה ואחר הפרשתה לא יטלטלו אותה כלל אפי' איכא כהן קטן דאין אנו נוהגין לתת חלה לכהן קטן משום דלא מחזקינן בזמן הזה בכהן ודאי עכ\"ל:"]],["\u0010y0\u0011 חַלַּת חוּצָה לָאָרֶץ שֶׁמֻּתֶּרֶת לְכֹהֵן טָהוֹר מִקֶּרִי, רַשַּׁאי לְאָכְלָהּ עִם זָר עַל שֻׁלְחָן אֶחָד, \u0010y1\u0011 לְפִי שֶׁאֵינָהּ מְדַמַּעַת \u0005(פֵּרוּשׁ עִנְיָן דָּמוּעַ הוּא תְּרוּמָה שֶׁנָּפְלָה בְּחֻלִּין)\u0006. וַאֲפִלּוּ נִתְעָרְבָה שָׁוֶה בְּשָׁוֶה. \u0005הַגָּה: \u0010y2\u0011 וְיֵשׁ חוֹלְקִין, וּסְבִירָא לְהוּ \u0010y3\u0011 \u0010c0\u0011 דְּאוֹסֶרֶת תַּעֲרָבְתָּהּ עַד מֵאָה וְאֶחָד, אִם הוּא בְּמִינָהּ, וְשֶׁלֹּא בְּמִינָהּ עַד ס' (טוּר בְּשֵׁם ר\"י וְסֵפֶר הַתְּרוּמָה וְרֹא\"שׁ וְרוֹקֵחַ סי' שנ\"ט ומהרי\"ו סמ\"ח וְר' שִׁמְשׁוֹן)\u0006. \u0010y4\u0011 וְאִם חָזְרָה וְנִתְעָרְבָה בָּעִסָּה, וְאֵין ק\"א לְבַטְלָה, \u0010y5\u0011 אִם לֹא אָכַל \u0010c1\u0011 הָעִסָּה יִשְׁאַל לְחָכָם עָלֶיהָ \u0010y6\u0011 וְיַתִּיר לוֹ כְּנֶדֶר, \u0010y7\u0011 דְּנִשְׁאָלִין עַל הַהֶקְדֵּשׁוֹת, וְיַחֲזֹר וְיִטֹּל חַלָּה אַחֶרֶת \u0005(תְּשׁוּבַת מַיְמוֹנִי סוֹף הִלְכוֹת זְרָעִים וב\"ה בְּשֵׁם א\"ח)\u0006. \u0010y8\u0011 \u0010y9\u0011 וּמֻתָּר לְבַטְּלָהּ בְּרֹב. וְאוֹכְלָהּ בִּימֵי טֻמְאָתוֹ. וִיכוֹלִין לִתְּנָהּ לְכֹהֵן עַם הָאָרֶץ. \u0010y10\u0011 וְאֵין בָּהּ מִשּׁוּם כֹּהֵן הַמְסַיֵּעַ בְּמַתְּנוֹתָיו, שֶׁהוּא אָסוּר. וְאִם רָצָה לֶאֱכֹל תְּחִלָּה וְאַחַר כָּךְ יַפְרִישׁ הַחַלָּה, בְּחוּץ לָאָרֶץ מֻתָּר, מִפְּנֵי שֶׁאֵין עִקָּרָהּ אֶלָּא מִדִּבְרֵיהֶם. \u0005הַגָּה: וְצָרִיךְ לְשַׁיֵּר מְעַט יוֹתֵר מִשִּׁעוּר חַלָּה שֶׁמַּפְרִישׁ, כְּדֵי שֶׁיְּהֵא שִׁירַיִם בְּשָׁעָה שֶׁמַּפְרִישׁ (בֵּית יוֹסֵף בְּשֵׁם הָרֹא\"שׁ וּסְמַ\"ג ובהר\"ן דְּבֵיצָה)\u0006. \u0010y11\u0011 וְדַוְקָא לְעִסָּה שֶׁנִּתְחַיֵּב עִם חַלָּה זוֹ יָכוֹל לִפְטֹר שֶׁלֹּא מִן הַמֻּקָּף, אֲבָל עִסָּה שֶׁנִּלּוֹשָׁה בִּפְנֵי עַצְמָהּ, אֵין מַפְרִישִׁין חַלָּה מֵעִסָּה אַחֶרֶת שֶׁלֹּא מִן הַמֻּקָּף \u0005(בֵּית יוֹסֵף בְּשֵׁם סמ\"ק וְכָל בּוֹ)\u0006. אֲבָל חַלַּת אֶרֶץ יִשְׂרָאֵל לֹא יֹאכַל עַד שֶׁיַּפְרִישׁ. וְאֵינָהּ נִטֶּלֶת אֶלָּא מִן הַמֻּקָּף \u0005(פִּי' מִמַּה שֶּׁהוּא קָרוֹב וְסָמוּךְ)\u0006, כִּתְרוּמָה. וְאֵינָהּ נִטֶּלֶת מִן הַטָּהוֹר עַל הַטָּמֵא, לְכַתְּחִלָּה. וְכָל שֶׁבִּתְרוּמָה לֹא יִתְרֹם וְאִם תָּרַם אֵינָהּ תְּרוּמָה, כָּךְ בְּחַלָּה. וְכָל שֶׁבִּתְרוּמָה לֹא יִתְרֹם מִזֶּה עַל זֶה, כָּךְ בְּחַלָּה. וְכָל שֶׁאֵינוֹ אוֹכֵל תְּרוּמָה אֵינוֹ אוֹכֵל חַלָּה. וְכָל הָאוֹכֵל תְּרוּמָה אוֹכֵל חַלָּה.",["\u0003חלת חוצה לארץ כו'. \u0004דוקא חלת ח\"ל שעיקרה אינו אלא מדרבנן אבל חלת א\"י אפי' בזמן הזה אע\"פ שאינה אלא מדרבנן כיון דעיקרא מדאורייתא אינו בכלל זה וכמו שנתבאר בסימן הקודם ודוקא בחלת ח\"ל הקילו בכך אבל בשאר איסורים דדבריהם לעולם צריך ס' וכן אסור לבטלן לכתחלה כדלעיל סוף סימן צ\"ט ועיין בב\"י ס\"ס זה שהביא דברי הרשב\"א שיש לחלק בכך:","\u0003לפי שאינה מדמעת כו'. \u0004ובש\"ס פרק כ\"ה דף ק\"ד ע\"ב אמרינן דלא גזרינן העלאה אטו אכילה כיון דחלת ח\"ל אינו אלא מדרבנן ותרווייהו צריכי דטעמא דאינה מדמעת איצטריך אמאי דלא חיישינן שמא תתערב החלה במאכל וטעמא דאינו אלא מדרבנן איצטריך כדי שלא נגזור העלאה אטו אכילה ובזה נדחה מה שכתב הב\"י דממה שכתב הרא\"ש לא גזרינן העלאה אטו אכילה מוכח דס\"ל כר\"י דליתא דהא הך דלא גזרינן העלאה אטו אכילה ש\"ס ערוך הוא אלא ודאי כדפירשתי. (שוב מצאתי און לי בדברי רבינו שמשון ובמעדני מלך דף קכ\"ה ע\"ב) מ\"מ נראה דדוקא בחלה כיון דלחם הוא שכיח ביה תערובת להכי אי לאו דאינה מדמעת הוה גזרינן אבל בשאר איסורין לא חיישינן דלמא יתערבו וכמו שנתבאר לעיל סימן פ\"ח ס\"ק ב' דמותר לאכול על שולחן א' בשר כשר עם עובד כוכבים שאוכל בשר נבלה וכן שאר איסורים ובהכי ניחא האי דלא שרי נמי משום תערובות גופיה מטעמא דאינו אלא מדרבנן ונימא כי היכא דלא גזרינן העלאה אטו אכילה מטעמא דאינו אלא מדרבנן ה\"נ לא נגזר משום תערובות משום דאינו אלא מדרבנן אלא ודאי דבפת שכיח תערובות ואיכא למיגזר טפי ודוק מיהו בלאו הכי ניחא דאין לדמות הגזרות זו לזו וכמו שכתבו התוספות שם בד\"ה ומנא תימרא כו' ע\"ש:","\u0003ויש חולקין כו'. \u0004ובספר מ\"מ סוף דף קכ\"ה השיג על הטור וב\"י והרב ואמר שדעת הרא\"ש אדרבה כהרמב\"ם דבטלה ברוב אפי' לזרים מדכ' במסקנתו וז\"ל ול\"נ דחלה ב' דמתני' עלה קאמר בירושלמי דנותנה לכהן ע\"ה דהקילו בה שאינה אלא להכירא בעלמא וגם הקילו בה להתירה לישראל על ידי ביטול ברוב ולא קשה הא דקאמר תרומת עובד כוכבים בח\"ל אינה מדמעת הא דישראל מדמעת עכ\"ל ומתוך כך כתב בסוף דבריו ולכך הסומך להתיר ברובא לא הפסיד עכ\"ד ולא עמדתי על סוף דבריו דאדרבה מכאן מוכח שמסקנת הרא\"ש כר\"י דהרי כתב דאחלה ב' דמתני' עלה קאי כו' וכך הם המשך דבריו שמתחלה כתבו הביא דברי הרמב\"ם ור\"י ואח\"כ דברי הרמב\"ן דמתרץ הך דש\"ס דידן דמדמעת היינו במחצה על מחצה ולא הכריע עדיין דבר ואח\"כ הביא דברי הרא\"ש דחולק על הירושלמי דסבירא ליה דנותנה לכהן ע\"ה ואח\"כ כתב הכרעתו אכל הנ\"ל וכך הם הצעת דבריו ולי נראה דאחלה ב' דמתני' שהיו נותנים ב' חלות א' לאור והיא עיקר החלה שמדרבנן והיתה נשרפת ולא התיר לאכלה בטומאה עצמה והחלה הב' היתה נאכלת לכהן ולא היתה אלא להכירא בעלמא כדכ' הרא\"ש לעיל מינה בהדיא דהחלה הב' של ח\"ל לא היתה אלא להכירא בעלמא עלה קאמר בירושלמי דנותנה לכהן ע\"ה כיון שאינה אלא להכירא בעלמא ובאותה חלה הקילו בה להתירה לישראל ע\"י ביטול ברוב והך דבכורות מיירי אפי' לישראל והשתא לא צריך לתירוץ הרמב\"ן אלא הא דישראל מדמעת מיירי בחלה א' דח\"ל כך הם המשך דברי הרא\"ש וכן משמע בתוס' ר\"פ כל הבשר ובאגודה דבחלה ב' דח\"ל הקילו דאינה מדמעת ולא בחלה א' ועיין שם וא\"כ לדידן שאין מפרישין אלא חלה אחת א\"כ יש לה דין חלה א' כדמוכח בהרא\"ש שם טובי זימני וכל זה ברור וא\"כ ודאי צדקו דברי הרב שפסק דהאידנא החלה אינה בטלה לזרים אלא בק\"א כיון דהאידנא אין מפרישין אלא חלה אחת וכמו שנתבאר בסימן הקודם וגם דברי הטור נכונים במה שכתבתי דמסקנת הרא\"ש כר\"י דבלאו הכי א\"א ליישב דבריו דמ\"ש הב\"י משום שכ' הרא\"ש ולא גזרינן העלאה ודאי ליתא וכמ\"ש לעיל ס\"ק ב' ומ\"ש מהרש\"ל פרק כל הבשר סי' ג' שהביא דעת ר\"י באחרונה הוא תמוה דהא הביא אח\"כ דברי הרמב\"ן וסותר דברי ר\"י אלא ודאי כדפרי' אלא דק\"ק דה\"ל לפרושי דבחלה ב' בטל ברוב ונראה משום שכתב הרא\"ש דהאידנא אין מפרישין אלא חלה א' וגם הטור כתב לעיל כגון שיש כהן גדול שטבל לקריו שאין מפרישין אלא חלה א' כו' לכך סתם הדברים אלא דאי קשיא איפכא קשיא על הטור מ\"ש כל חלה שהיא מדרבנן נותנין אפי' לכהן עם הארץ משמע אפי' במקום שאין מפרישין אלא אחת כגון דאיכא כהן קטן או גדול שטבל לקריו וכן משמע מדברי ב\"י ושאר אחרונים שכן הוא דעת הטור והא ליתא כדכתב הרא\"ש דדוקא חלה ב' דח\"ל ניתנת לכהן כיון דאינה אלא להכירא בעלמא וא\"כ היכא דאין מפרישין אלא חלה אחת אינה ניתנת לכהן עם הארץ וצ\"ל דהטור בזה הוא נגד סברת הרא\"ש וסבירא ליה דחלת חוץ לארץ בכל ענין ניתנה לכהן עם הארץ ואפ\"ה לזרים אסורה עד ק\"א וכן דעת הרוקח סימן שנ\"ט דלכהן ע\"ה ניתנה בכל ענין ואסורה לזרים עד ק\"א ע\"ש מיהו לענין הלכה צ\"ע בזה כיון דנתבאר דדעת הרא\"ש דאינה ניתנה לכהן עם הארץ וכן דעת התוס' פכ\"ה דף ק\"ד ע\"ב (דאין נותנין לכהן עם הארץ אלא בדליכא כהן חבר אי נמי דאיכא כהן חבר והוא עשיר וכהן ע\"ה הוא עני דנותנין לעני) וכן דעת רבינו שמשון וכן דעת הר\"ע מברטנורה פ\"ד דחלה וכן פסק מהרש\"ל פרק כ\"ה סי' ג':","\u0003דאוסרת תערובתה כו'. \u0004וכתב סה\"ת וצריך ליזהר בה שלא יאכלם כהן בקערה במרק רותח שלא יאסור הזר מלאכול באותה קערה ומביאו הטור וכתב הב\"ח ולפי זה צריך ליזהר כשנפלה חלה בתבשיל ואין בקדרה כדי לבטל החלה התבשיל ימכר או ינתן לכהן בדאיכא רוב חולין והכלי צריך הכשר ואם כלי חרס הוא ישבר עכ\"ל. ואגב שיטפא כתב כן דודאי הכלי חרס נכשר ג\"כ בהגעלה שלש פעמים בחלת ח\"ל כדאיתא בירושל' ובעל העיטור ורשב\"א וטור לעיל סימן קכ\"א כיון שאין לו עיקר מדאורייתא וכ\"כ המחבר לעיל ס\"ס קי\"ד לענין בישולי עובדי כוכבים וה\"ה לענין חלה דחד דינא אית צהו כדאיתא ברשב\"א וכל שכן הכא דאיכא רוב חולין:","\u0003ואם חזרה ונתערבה כו'. \u0004להכי נקיט לישנא דאם חזרה ונתערבה לאפוקי אם לא הפריש חלה כלל דאז אפי' אם אין ק\"א בעיסה מותר בכל ענין וכדלקמן דאוכל והולך ואח\"כ מפריש כדכתב בד\"מ וז\"ל כתב מהרי\"ו בתשובה סימן מ\"ח על עיסה שנתבשלה ולא ניטל ממנה החלה דיש ליטול עדיין ויטול מעט שיהא בשאר העיסה ק\"א נגד החלה ולא יהא נאסר העיסה מן החלה עכ\"ל וצ\"ע דהא אמרינן חלת ח\"ל אוכל ואח\"כ מפריש ולא מחלקינן בין היה ק\"א בפת נגד החלה או לא ונראה דהואיל וחלת ח\"ל אינו אלא מדרבנן לא מחמרינן שתאסר למפרע אלא דוקא מכאן ולהבא אם נתערבה לאחר שהופרשה החלה ולכן נ\"ל דאף לדברי המחמירין שאינה בטלה אלא בק\"א היינו אם נתערבה לאחר שהופרשה הואיל והיה עליה שם חלה מעיקרא אבל בכה\"ג שלא היה עליה שם חלה מעולם אין להחמיר וכ\"ש דהרמב\"ם סובר דאפילו לערב לכתחלה שוה בשוה שרי בכה\"ג כן נ\"ל. ועוד נ\"ל דאפי' לדברי מהרי\"ו דפשוט הוא דאם היה במים שנתבשל בהן העיסה ס' דשרי מטעם סלק את מינו כמי שאינו ושאינו מינו רבה עליו ומבטלו וא\"כ יכול ליקח מעט עד שיהא במים ס' כנגדו ושרי עכ\"ל ד\"מ וכ\"פ הב\"ח לק' ס\"ס שכ\"ד:","\u0003אם לא אכל העיסה כו. \u0004ז\"ל ד\"מ ונ\"ל דוקא בכה\"ג שעדיין העיסה קיים ויכול ליטול חלה אחרת אבל אם כבר נאכל העיסה א\"א לשאול עליה דא\"כ כבר אכל למפרע טבל עכ\"ל ואע\"ג דהשתא נמי כשלא ישאל עליה אכל למפרע חלה שאסורה לזרים מ\"מ כיון דלהרבה פוסקים בטלה ברוב שרי אבל טבל אסור לכ\"ע:","\u0003ויתיר לו כנדר כו'. \u0004והא דלא אסר אפילו ביש ק\"א אלא ע\"י היתר משום דהוי דבר שיל\"מ כדלעיל סי' ק\"ב ס\"ד בהג\"ה דהכא בנדרי הקדש כיון דאינה מצוה לישאל עליהן אלא מדוחק כדלעיל סי' ר\"ג ס\"ג לא הוי דשיל\"מ והכי אמרינן בש\"ס בנדרים דף (ס\"ד) [נ\"ט] ע\"א וכ\"כ הר\"ן שם וריש ד' (ס\"ג) [נ\"ח]:","\u0003דנשאלין על ההקדשות. \u0004כדלעיל סי' רנ\"ח וכן על תרומות ומעשרות כדלקמן סי' של\"א סמ\"ח ואם כן לא עדיף הפרשתו זו שאמר תהא חלה מנדר ויתיר לו מ\"ש תהא חלה ויחזור ויטול אחרת:","\u0003ומותר לבטלה ברוב ואוכלה כו'. \u0004בזה גם החולקים מודים דדוקא לענין לאכלה זר הוא דצריך ק\"א אבל לאכלה כהן בימי טומאתו מודה דסגי ברוב כדאיתא באשר\"י וטור ופוסקים בהדיא ע\"ש:","\u0003לבטלה ברוב. \u0004משמע דרוב מיהא בעינן ואע\"ג דלעיל אפילו שוה בשוה סגי (והב\"ח סעיף ד' לדעת הטור תירץ דשאני לאכלה לזרים ולא נהירא דיציבא בארעא וגיורא בשמי שמיא דהא לאכלה לזרים חמיר טפי כדאיתא בכל הפוסקים גם בטור משמע להדיא הכי) היינו בדיעבד אבל לערבה לכתחלה צריך רוב כן תירץ ב\"י לדעת רמב\"ם אבל באמת אינו מוכרח דדוקא בתרומה כ' הרמב\"ם דמבטלה ברוב וי\"ל דמחלק בין תרומה לחלה דבחלת ח\"ל סגי שוה בשוה ולא בתרומת ח\"ל וכן מוכרח בטור דכ' לדעת הרמב\"ם דחלה יכול לערבה אפילו לכתחלה שוה בשוה אלמא דלא ס\"ל כמ\"ש ב\"י וצ\"ל דסבירא ליה כדפי' ולפי זה נראה דלאכלה לזרים אין לערבה לכתחלה לבטלה אפי' ברוב וכן למאן דאוסר אפילו דיעבד עד ק\"א אין לערבה) לכתחלה אפילו בק\"א ואפילו לאכלה בטומאתו ודעת הרמב\"ן ושאר פוסקים דאין לבטל לכתחלה משום דאין מבטלים איסור לכתחלה ונהי דהמחבר פסק בזה להקל מ\"מ לאכלה לזרים כיון דלא נתבאר זה בדברי המחבר כן להקל אין לבטלו לכתחלה וכן דעת ר' שמשון והרשב\"א וכן נראה דעת הב\"ח סעיף ד' מיהו אם עשה כן במזיד נראה דאע\"ג דנתבאר לעיל סימן צ\"ט ס\"ק י\"ח דקנסינן ליה הכא שרי כיון דבלאו הכי יש פוסקים מתירים לערב אפילו לכתחלה:","\u0003ואין בה משום כהן כו'. \u0004כלומר דאע\"ג דבעלמא קי\"ל דאסור לכהן לסייע על הגרנות בחלת ח\"ל הקילו בזה וב\"י דקדק מדברי רש\"י וטור דאע\"ג דהבעל הבית יכול ליתנו לכהן המסייעו מ\"מ אסור לכהן לסייע כדי שיתנו לו תרומת ח\"ל:","\u0003ודוקא כו'. \u0004אין מפרישין חלה מעיסה אחרת שלא מן המוקף אלא צריך להקיפן יחד:"],["\u0003דאוסרת תערובתה עד ק\"א. \u0004לכאורה נראה דהיינו אם היא בעין אלא שאינה ניכרת אבל אם הסירו החלה מן התבשיל שנפלה לתוכה אע\"פ שהתבשיל ממין החלה אין צריכין ק' וא' ובטלה בס' כשאר איסור. אבל בתוס' פ' ג\"ה דף צ\"ט דיבור המתחיל אין בהם כו' מבואר דלפירש\"י במין במינו אפי' הסיר האיסור בעינן ק' וא' לבטלו ואע\"פ שממה שכתבו אח\"כ דיש לומר בדרך אחר אין דין זה מוכרח מ\"מ כיון דלרש\"י מוכרח כן אין לנו להקל ותו דרבינו שמשון במס' ערלה דף פ\"א כתב ג\"כ כרש\"י וכתוב בד\"מ בשם רשב\"א דבדיעבד בטלה ברוב:","\u0003ישאל לחכם כו'. \u0004כן מביא תשו' מיי' הלכות זרעים בשם ספר המצות דע\"י השאלה נעקרה קדושת החלה מעיקרא וכן איתא לקמן בש\"ע סי' של\"א סעיף מ\"ח דנשאלין על תרומות ומעשרות אם ניחם עליהם כו' ותימא על מתני' דפ\"ה דתרומות סאה תרומה טמאה שנפלה לפחות ממאה חולין ירקבו משמע דאין להם תקנה דא\"כ ליתני התקנה כמו ששנה אח\"כ הרבה תקנות באותה מתני' במקום שיש קצת תקנה ואלו בזה לא תנא תקנתא ש\"מ שאין לה תקנה וכן מבואר ברמב\"ם בזה שכתב יניחם עד שירקבו וכן בפ' הנודר מן הירק שנזכיר בסמוך שכתוב שם ברש\"י ירקבו ואין להם תקנה ואמאי כו' לא אמר שישאל על התרומה שעשה ויהיה אח\"כ מותר לישראל ויפריש תרומה אחרת ואין לומר דמיירי באופן שאין שייך שאלה הא ליתא דהא בפרק הנודר מן הירק (נדרים דף נ\"ט) מייתי מתני' זאת ודייק עלה הא אם נפלה למאה תעלה הא הוה דבר שיש לו מתירין כיון שאפשר בשאלה כדאמר התם לעיל מיניה לענין נדר ומשני שאני נדר דמצוה לשיולי ביה מדרבי נתן דאמר כל המקיימו כאלו בונה במה מה שאין כן בתרומה דאין מצוה לשיולי ביה משום הכי לא הוה דבר שיש לו מתירין ממילא על כל פנים שייך ביה שאלה אלא דלא הוה מצוה וא\"כ הדרא קושיא לדוכתא אמאי ירקב בהנחה בפחות ממאה ולא אמרינן ילך אצל חכם ויתיר לו ומאי טעמא לא הוה כי הכא בחלה ועוד תימא לי במאי דמסיק בפרק הנודר שזכרנו דבתרומה לא הוה דבר שיש לו מתירין כיון דאין מצוה לשיולי מאי שנא מכל דבר שיש לו מתירין דקי\"ל בסי' ק\"ב דאם המתיר בידו לעשות בלי הפסד הוה דבר שיש לו מתירין הכי נמי בתרומה הא על כל פנים בידו לילך ולהשאיל לת\"ח אף על פי שאינה מצוה. ועוד תמיה גדולה דאי מהני שאלה מחמת הפסד התערובות של חלה או תרומה היכן מצינו כרת בשוחט קדשים בחוץ או מיתה בידי שמים בתרומ' דודאי מיראת העונש ישאל לחכם וקושיא כזו נביא בסמוך בשם הראב\"ד ובשם התוס' בגיטין ואילולי פה קדוש דסמ\"ג הייתי אומר דהא דמהני שאלה בתרומות ומעשרות היינו כשניחם מצד הנתינה עצמה שחוזר ממנה מחמת איזה טעם שיש לו אפי' בלא תערובת אבל לא מחמת התערובת כי כל פתח וחרטה צריך שיהיה עיקר הנדר נעקר כי אם יתקיים הנדר ימשך לו על פי ההכרח איזה נזק משא\"כ בזה דודאי היה אפשר לו לידור ולעשות לזה תרומה או חלה ולהזהר מן התערובת דהא אינו בהכרח שאם יהיה זו החתיכה חלה שתתערב ולא שייך זה פתח וחרטה מחמת התערובת דהא עיקר השאלה היא על גוף הדבר שמתחרט בו מחמת עצמו וכן פירש הר\"ן להדיא בנדרים שם דהא דיש שאלה בתרומות היינו ע\"י פתח וחרטה כשאר נדרים וכן פי' רשב\"ם בפרק יש נוחלין (בבא בתרא דף ק\"ך ע\"ב) וז\"ל שיש שאלה בנדרים וה\"ה לכל ההקדשות שאם שחט קדשים בחוץ ונתחייב כרת ואח\"כ הלך אל החכם להתיר לו הקדשו ומצא לו פתח של חרטה ועקר את ההקדש מעיקרו ועבדי' כהקדש טעות אגלאי מילתא למפרע דלא הוה הקדש מעולם ופטור מכרת וה\"ה לכל דבר הקדוש במוצא שפתיו כגון תרומות ומעשרות דאי בעי מתשיל עלייהו וחזרי לטיבולייהו כדאמרינן פרק הנודר מן הירק עכ\"ל הרי למד אותנו הרב דהך דהכא אין ההיתר משום התערובת שעל ידו ישאל על מה שעשאו תחילה תרומה אלא דוקא ע\"י פתח של חרטה על גוף הדבר וכההוא דשוחט קדשים בחוץ דלא יכול לעקור הקדשים כיון ששחטן בחוץ אלא מחמת גוף הדבר ובזה ודאי אמרו חכמים נשאלים על נדרים והקדשות משא\"כ כשאין לו חרטה על גוף הדבר תחלה אלא שהתערובות גורם לו להתחרט זה לא מועיל כלום משום הכי בההוא דנדרים כשאומר שם דלגבי דבר הנאסר בנדר של קונם אין בטל ברוב משום דהוה דשיל\"מ על ידי שאלה היינו באם ימצא פתח של חרטה על עיקר הדבר ופריך על זה הא במאה יעלה הא הוה דבר שיש לו מתירין ולא פריך אמאי ירקב בפחות ממאה ולא אמרינן ישאל עליו דהיאך נאמר לו שישאל שהרי אין לו פתח של חרטה על גוף הדבר על כן ירקב אלא עיקר הקושיא כי היכי דאמרת גבי נדר כיון שיש אפשרות באם יש לו פתח חרטה על עיקר הדבר מיקרי דבר שיש לו מתירין הכי נמי נימא גבי תרומה ולא תיבטל במאה ומשני דלגבי נדר שפיר הוה דבר שיש לו מתירין כיון דמסתמא לא יקיים הנדר בלא התערובת שהרי מצוה לאתשוליה עליה על כן הוה ודאי ואע\"פ שלא נשאל הוה כנשאל ועל כן אין אנו מקילין בתערובת שלו מה שאין כן בתרומה דבלאו התערובות לא קאי לשאלה על כן מהני ליה התערובות לבטל כיון שאין לו היתר בלאו הכי לא מקרי דבר שיש לו מתירין אבל ודאי אי היה בא לנו בפתח של חרטה על עיקר הדבר ודאי מועיל לו בכל השאלות אפילו על תרומה בפני עצמה אלא שאין שייך להורות לו שיתשל על התרומה כיון שאין חרטה רק מחמת התערובות על כן אמרו במשנה ירקב וזה הענין הוא ממש בחלה דכאן דודאי לא שייך להורות לו שישאל מחמת התערובת. וראיה עוד ממ\"ש ר\"ת לענין כל נדרי הביאו בית יוסף בא\"ח סי' תרי\"ט וז\"ל ועוד שאין החכם מתיר בלא חרטה עכ\"ל וזה קאי לאותן נדרים שעבר עליהם כבר דלא מועיל כל נדרי ואמאי לא נאמר שמתוך שעבר עליהם זהו עצמו ההתרה אלא צריך חרטה בעיקר הנדר מצד עצמו ואפילו להרא\"ש שחולק שם על ר\"ת וכ' וז\"ל דמה שהקשה דבעינן חרטה אנן סהדי דכל מי שעובר על נדרו הוא מתחרט מעיקרו כדי להנצל מן העונש עכ\"ל אין זה דומה לכאן דהתם על ידי שרואה שעובר ויהיה לו עונש מתחרט הוא באמת על מה שנדר כלל כי הנדר גורם לו עונש ותיכף משעת הנדר רבוצה עליו יראת העונש כיון שהוא בר הכי שאין מקיים את נדרו ע\"כ מתחרט על עיקר הנדר מה שאין כן בהפרשת תרומה וחלה שאין עומד להתערב בחולין רק שאירע לו כן במקרה נמצא אין כאן עקירת הנדר מעיקרו זה כתבתי לדעת הרא\"ש אבל לפי האמת גם דברי הרא\"ש תמוהין שדחה דברי ר\"ת שהוא עמוד העולם בדיחוי זה שהוא לכאורה גלוי אפילו להמון עם ובאמת אינו כי לפי זה לא תמצא מלקות בנזיר ולא מיתה באוכל תרומה דהם ילכו לחכם להתיר להם מיראת עונש כן מוכח עוד בדברי תוס' פרק השולח (דף צ\"א) דיבור המתחיל ואפקעינהו כו' דאוקימנא אחזקה דאל\"כ נזיר שהיה שותה יין חייב אמאי לוקה אם אומרי' לו לא תשתה דהא התראת ספק היא שמא ישאל על נזירתו עכ\"ל ואי ס\"ד דמהני שאלה משום יראת העונש אמאי קרי ליה התראת ספק הא ודאי ישאל על נזירתו והיכן מצינו נזיר לוקה ובחידושי הלכות של מהרש\"א הקשה כן ותירץ דודאי ביודעין בו שעבר על נזירתו במתכוין החכם לא יהיה נשאל לו כדי שלא ילקה אבל התראת ספק מיהא איתא דשמא זה הנזיר יבוא לחכם שלא ידע נזירתו וישאל לו עכ\"ל ודבריו חלו שלא בדקדוק דאם הדין נותן להיזקק לו לנזיר זה שעבר למה באמת לא יתיר לו החכם כיון שיש לו היתר ואם אין היתר לעובר במזיד א\"כ מה שלא יגלה לחכם שעבר במזיד ויתיר לו אין ההיתר היתר כלל והיאך תאמר על זה התראת ספק דהא אי אפשר לו להפטר מן החיוב אף אחר השאלה כיון שהיתה בטעות וזה דומה למה שאמרו בפרק השולח צריך לפרט את הנדר משום מילתא דאיסורא וכל שלא מפרט הנדר אין ההיתר היתר כלל ה\"נ ממש בזה ואפילו ק\"ו יש כאן דהך מלתא דצריך לפרט הנדר הוא מדרבנן וכאן בעובר במתכוין לא הוה היתר מן התורה אלא דבר ברור הוא דמחמת יראת העונש אין לו היתר כלל לשאול על נזירתו אלא דוקא אם יהיה לו באמת פתח וחרטה מצד עצמו של הנדר ועל זה אמרו התוס' שפיר דהוי ליה התראת ספק דשמא ימצא פתח וחרטה דכל שאומר מצד עצמו שהוא מתחרט מעיקר הנדר אף אם לא היה עובר עליו ונותן טעם לחזרה שלו ודאי אינו לוקה וכמו שמצינו בשחוטי חוץ שזכרנו וזה ברור ודברי הסמ\"ג דכאן צריכין עיון גדול ליישב ואף שאיני כדאי לחלוק עליו מכל מקום חלקי אמרה נפשי שאין לסמוך על פסק זה ולהקל בשביל זה ובאולי גם הסמ\"ג עצמו לא נתכוין אלא באם יש לו חרטה על עיקר החלה והועתק משמו בדרך זה:\n\u0003כתב \u0004מו\"ח ז\"ל צריך ליזהר כשנפלה חלה בתבשיל רותח ואין בקדירה לבטל החנה בתבשיל ימכר או ינתן לכהן בדאיכא רוב חולין והכלי אם הוא כלי חרס צריך שבירה שא\"א בהגעלה ע\"כ וכבר נתבאר דאין אנו נותנין לכהן עכשיו ומה שהחמיר בזה לא ידעתי למה לא נסמוך להקל במילתא דרבנן לבטל ברוב וכמו שזכרתי לעיל בשם דרכי משה:"]],["אֵין חַיָּב בְּחַלָּה \u0010y0\u0011 אֶלָּא חֲמֵשֶׁת מִינֵי תְּבוּאָה. וְאֵין חַיָּב אֶלָּא חֲמֵשֶׁת רְבָעִים. וּמִדָּה שֶׁמַּחֲזֶקֶת \u0010y1\u0011 מ\"ג בֵּיצִים וְחֹמֶשׁ בֵּיצָה, \u0010c0\u0011 מְמַלְּאִים אוֹתָה קֶמַח, וְאוֹתוֹ קֶמַח הוּא שִׁעוּר חַלָּה. וּכְשֶׁמְּמַלְּאִים הַמִּדָּה קֶמַח, תִּהְיֶה מְחוּקָה וְלֹא גְּדוּשָׁה. וְהֵיאַךְ יְשַׁעֲרוּ לָדַעַת שֶׁהִיא מַחֲזֶקֶת מ\"ג בֵּיצִים \u0010y2\u0011 וְחֹמֶשׁ, נִתְבָּאֵר בַּטּוּר א\"ח \u0005וְעַיֵּן בא\"ח סי' תנ\"ו\u0006 וּמִשְׁקַל חֲמֵשֶׁת רְבָעִים קֶמַח הוּא תק\"כ דרה\"ם מִקֶּמַח חִטִּים שֶׁבְּמִצְרַיִם. \u0005הַגָּה: \u0010y3\u0011 כְּלִי הַמַּחֲזִיק עֶשֶׂר אֶצְבָּעוֹת עַל עֶשֶׂר אֶצְבָּעוֹת, בְּרוּם שָׁלֹשׁ אֶצְבָּעוֹת וּתְשִׁיעִית אֶצְבַּע בְּקֵרוּב, הוּא שִׁעוּר הַחַלָּה. וְכֵן מִדָּה שֶׁיֵּשׁ בָּהּ ז' אֶצְבָּעוֹת פָּחוֹת ב' תְּשִׁיעִיּוֹת אֶצְבַּע (עַל ז' פָּחוֹת ב' תְּשִׁיעִיּוֹת אֶצְבַּע)\u0006, בְּרוּם ז' אֶצְבָּעוֹת פָּחוֹת ב' תְּשִׁיעִיּוֹת אֶצְבַּע, \u0010y4\u0011 הוּא הָעֹמֶר. וְכָל הָאֶצְבָּעוֹת אֵלּוּ הֵם רֹחַב גּוּדָל שֶׁל יָד \u0005(רַמְבַּ\"ם פֶּרֶק ו' \u0010y5\u0011 דְּבִכּוּרִים)\u0006.\nחֲמֵשֶׁת מִינֵי תְּבוּאָה מִצְטָרְפִין, שֶׁאִם אֵין בָּעִסָה אֶלָּא חֲמֵשֶׁת רְבָעִים מֵחֲמִשְׁתָּן, מִצְטָרְפִין. \u0010y6\u0011 \u0010c1\u0011 בַּמֶּה דְבָרִים אֲמוּרִים, כְּשֶׁעֵרְבָן קֶמַח. אֲבָל אִם לָשׁ כָּל אֶחָד לְבַדּוֹ, וְאֵין בּוֹ כַּשִּׁעוּר, וּמְדַבְּקוֹ לְמִין אַחֵר, אֵין מִצְטָרְפִין אֶלָּא בְּזֶה הַסֵדֶר: הַחִטִּים אֵין מִצְטָרְפִין אֶלָּא עִם הַכֻּסְמִין, וְהַכֻּסְמִין מִצְטָרְפִין עִם כָּל אֶחָד וְאֶחָד. הַשְּׂעוֹרִים מִצְטָרְפִין עִם הַכֹּל חוּץ מֵעִם הַחִטִּים. שִׁיפוֹן מִצְטָרֵף עִם שְׂעוֹרִים וְכֻסְמִין, וְלֹא עִם שִׁבֹּלֶת שׁוּעָל וְחִטִּים. שִׁבֹּלֶת שׁוּעָל מִצְטָרֵף עִם שְׂעוֹרִים וְכֻסְמִים, וְלֹא עִם חִטִּים וְשִׁיפוֹן. וּלְהָרַמְבַּ\"ם, כֻּסְמִין וְשִׁבֹּלֶת שׁוּעָל וְשִׁיפוֹן מִצְטָרְפִים. וְאִם לָשׁ כָּל מִין וָמִין לְבַדּוֹ, וְיֵשׁ בּוֹ כַּשִּׁעוּר, וְרוֹצֶה לְהַפְרִישׁ מִמִּין זֶה עַל זֶה, אֵין מַפְרִישִׁין אֶלָּא עַל מִינוֹ. כֵּיצַד, אֵין מַפְרִישִׁין חִטִּים עַל שׁוּם אֶחָד מֵהֶם, וְלֹא מִשּׁוּם אֶחָד מֵהֶם עֲלֵיהֶם. \u0010y7\u0011 \u0010c2\u0011 וְכֻסְמִין וְשִׁיפוֹן מַפְרִישִׁין מִזֶּה עַל זֶה, וְכֵן שִׁבֹּלֶת שׁוּעָל וּשְׂעוֹרִים מַפְרִישִׁים מִזֶּה עַל זֶה. \u0005הַגָּה: \u0010c3\u0011 עֵרַב קַב מֵעִסָּה עִם קַב אַחֵר מֵעִסָּה שֶׁאֵינוֹ מִינוֹ, וְחִלְּקוֹ אַחַר כָּךְ וְהוֹסִיף עַל כָּל אֶחָד רֹבַע הַקַּב מִמִּינוֹ, \u0010y8\u0011 חַיָּב בְּחַלָּה כֵּיוָן שֶׁלֹּא נִצְטָרְפוּ כְּשֶׁהָיוּ מְעֹרָבִים. אֲבָל אִם עֵרַב קַב קֶמַח עִם קַב קֶמַח מִמִּין אַחֵר עַל דַּעַת לְחַלְּקוֹ וְחִלְּקָם וְהוֹסִיף עַל כָּל אֶחָד רֹבַע הַקַּב מִמִּינוֹ, \u0010y9\u0011 פָּטוּר (טוּר)\u0006.\nחָמֵשׁ רְבָעִים הַלָּלוּ, הַשְּׂאוֹר וְהַסֻבִּין וְהַמֻּרְסָן מִצְטָרְפִין לְהַשְׁלִים, אִם לָשָׁן בְּלֹא הַרְקָדָה, אֲבָל אִם רִקֵּד וְהִפְרִישׁ מֻרְסָן מִתּוֹכָם, וְחָזַר וְעֵרְבָן עִמּוֹ, \u0010y10\u0011 אֵינוֹ מִצְטָרֵף.\nקַב חִטִּים מִצַּד זֶה וְקַב שְׂעוֹרִים מִצַּד זֶה, וְקַב \u0010y11\u0011 כֻּסְמִין בָּאֶמְצַע, מְחַבְּרָן וַהֲרֵי אֵלּוּ מִצְטָרְפִין. \u0010c4\u0011 וְצָרִיךְ לְהַפְרִישׁ מִכָּל מִין וָמִין.\nחֲצִי קַב חִטִּים מִצַּד זֶה, וַחֲצִי קַב שְׂעוֹרִים מִצַּד זֶה, וַחֲצִי קַב כֻּסְמִין בָּאֶמְצַע, \u0010y12\u0011 מִצְטָרְפִים, וְתוֹרֵם מִן הַכֻּסְמִין עַל שְׁלָשְׁתָּן.\nקַב חִטִּים מִצַּד זֶה וְקַב חִטִּים מִצַּד זֶה וְקַב אֹרֶז בָּאֶמְצַע, אוֹ קַב שֶׁל עוֹבֵד כּוֹכָבִים אוֹ קַב שֶׁל חַלָּה, \u0010y13\u0011 אֵינָם מִצְטָרְפִים. \u0005אֲבָל אִם הָיָה בֵּינֵיהֶם \u0010c5\u0011 עִסָּה שֶׁכְּבָר הוּרְמָה חַלָּתָהּ, \u0010y14\u0011 מִצְטָרְפִין (הָרֹא\"שׁ כְּלָל ב')\u0006. \u0010c6\u0011\nהָיָה בֵּינֵיהֶם קַב שֶׁל מִין אַחֵר מֵחֲמֵשֶׁת הַמִּינִים, אוֹ קַב מִשֶּׁל אִשָּׁה אַחֶרֶת, מִצְטָרְפִין.\nקַב שֶׁל תְּבוּאָה חֲדָשָׁה וְקַב שֶׁל יְשָׁנָה, \u0010y15\u0011 \u0010c7\u0011 אֵינָם מִצְטָרְפִים. הָיָה קַב שֶׁל יָשָׁן מִצַּד זֶה וְקַב יָשָׁן מִצַּד זֶה, וְחָדָשׁ בָּאֶמְצַע, מִצְטָרְפִין. \u0005וְהוּא הַדִּין אִפְּכָא, חָדָשׁ מִשְּׁנֵי הַצְּדָדִים וְיָשָׁן בָּאֶמְצַע (בֵּית יוֹסֵף וְטוּר)\u0006.\nהָעוֹשֶׂה עִסָה מֵהַחִטִּים \u0010y16\u0011 וּמֵהָאֹרֶז, אִם יֵשׁ בָּהּ טַעַם דָּגָן, חַיֶּבֶת בְּחַלָּה \u0010c8\u0011 אַף עַל פִּי שֶׁרֻבָּהּ אֹרֶז; וְאִם לָאו, פְּטוּרָה.\nנָתַן שְׂאוֹר מֵעִסַת חִטִּים לְתוֹךְ עִסַת אֹרֶז, אִם יֵשׁ בָּהּ טַעַם דָּגָן חַיֶּבֶת בְּחַלָּה. \u0010y17\u0011 \u0010c9\u0011\nנָתַן שְׂאוֹר מֵעִסָה שֶׁלֹּא הֻרְמָה חַלָּתָהּ לְתוֹךְ עִסָה שֶׁהֻרְמָה חַלָּתָהּ, וְהַכֹּל מִמִּין \u0010y18\u0011 \u0010c10\u0011 אֶחָד, אִם יֵשׁ לוֹ קֶמַח אוֹ עִסָה שֶׁלֹּא נִטַּל מִמֶּנָּהּ חַלָּה \u0010y19\u0011 מַפְרִישׁ מִמֶּנּוּ עַל זֶה הַשְּׂאוֹר לְפִי חֶשְׁבּוֹן, דְּהַיְנוּ אֶחָד ממ\"ח בַּשְּׂאוֹר \u0005וַאֲפִלּוּ אֵין בָּזֶה שִׁעוּר חַלָּה, וּבִלְבַד שֶׁיַּנִּיחֵנוּ אֵצֶל הָעִסָּה הַגְּדוֹלָה (כֵּן מַשְׁמָע בת\"ה סִימָן ק')\u0006. וְאִם לָאו, מַפְרִישׁ \u0010c11\u0011 אֶחָד ממ\"ח בְּכָל הָעִסָה, לְפִי שֶׁנַּעֲשֵׂית כֻּלָּהּ טֶבֶל. \u0010y20\u0011 \u0010c12\u0011 וְהוּא הַדִּין אִם הַשְּׂאוֹר שֶׁל פָּטוּר וְהָעִסָה שֶׁל חִיּוּב. \u0005הַגָּה: וּמִכָּל מָקוֹם לְכַתְּחַלָּה לֹא יִסְמֹךְ עַל זֶה, וְלֹא יִתֵּן שְׂאוֹר שֶׁל פְּטוּר בְּעִיסָה שֶׁל חִיּוּב (מָרְדְּכַי פ' מָקוֹם שֶׁנָּהֲגוּ)\u0006. \u0010y21\u0011 אֲבָל אִם כְּבַר עָבַר וְעָשָׂה, מֻתָּר לְכַתְּחִילָה לִקַּח מֵאוֹתָהּ עִסָּה וְלִתֵּן בְּעִסָּה אַחֶרֶת שֶׁיִּהְיֶה בּוֹ לַשְּׂאוֹר. \u0005(ת\"ה סי' ק')\u0006.\nמִי שֶׁנִּתְעָרֵב לוֹ פַּת שֶׁהִפְרִישׁ מִמֶּנּוּ חַלָּה עִם פַּת שֶׁלֹּא הֻפְרַשׁ מִמֶּנּוּ, אִם יֵשׁ לוֹ קֶמַח יַעֲשֶׂה \u0010c13\u0011 עִסָה מֵחֲמִשָּׁה רְבָעִים וִיצָרְפֶנָּה עִם הַכִּכָּרוֹת בִּכְלִי, וְיַפְרִישׁ מִמֶנָּה עַל אוֹתָם כִּכָּרוֹת שֶׁנִּתְעָרְבוּ. וְאִם רוֹצֶה לְהַפְרִישׁ מִנֵּהּ וּבֵהּ, צָרִיךְ לְהַפְרִישׁ מְעַט מִכָּל כִּכָּר וְכִכָּר, אוֹ יְצָרְפֵם כֻּלָּם בִּכְלִי אֶחָד \u0010y22\u0011 וְיַפְרִישׁ מִכָּל אֶחָד עַל כֻּלָּם, עַד שֶׁיַּפְרִישׁ מִכְּדֵי חֶשְׁבּוֹן הַכִּכָּרוֹת, וּמֵאֶחָד יוֹתֵר, כְּגוֹן אִם חָמֵשׁ שֶׁהֻפְרַשׁ עֲלֵיהֶם נִתְעָרְבוּ בְּעֶשֶׂר שֶׁלֹּא הֻפְרַשׁ עֲלֵיהֶם, יַפְרִישׁ מִשִּׁשָּׁה, שֶׁאָז וַדַּאי הִפְרִישׁ מֵאֶחָד שֶׁלֹּא הֻפְרַשׁ עָלָיו. \u0005הַגָּה: \u0010y23\u0011 \u0010c14\u0011 הָאוֹפֶה פַּשְׁטִידָ\"א מֵעִסָּה שֶׁלֹּא הֻרְמָה חַלָּתָהּ, וּבְתוֹכוֹ בָּשָׂר, מֻתָּר לְהַפְרִישׁ מֵעִסָּה אַחֶרֶת הַחַיֶּבֶת בְּחַלָּה עַל זוֹ, וְנִפְטַר גַּם כֵּן טַעַם הָעִסָּה הַנִּכְנָס בַּבָּשָׂר (בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבָה)\u0006.\nעִסָה שֶׁאֵין בָּהּ כַּשִּׁעוּר, וּבְעֵת אֲפִיָּתָהּ תָּפְחָה וְגָדְלָה עַד שֶׁנִּרְאֶה כְּאִלּוּ יֵשׁ בָּהּ \u0010c15\u0011 כַּשִּׁעוּר, פְּטוּרָה. \u0005וְהוּא הַדִּין אִם תָּפְחָה קֹדֶם אֲפִיָּה (בֵּית יוֹסֵף וּתְשׁוּבַת הָרֹא\"שׁ כְּלָל ב' וְרַשְׁבָּ\"א סִימָן תס\"א)\u0006. \u0010y24\u0011\nאָסוּר לַעֲשׂוֹת עִסָתוֹ פָּחוֹת \u0010c16\u0011 מִכַּשִּׁעוּר כְּדֵי לְהַפְקִיעַ מִמֶּנּוּ חִיּוּב חַלָּה.",["\u0003אלא ה' מיני תבואה. \u0004שהן חטין ושעורים וכוסמין ושבולת שועל ושיפון כדמפרש ואזיל:","\u0003מ\"ג ביצים וחומש ביצה כו'. \u0004כמנין חל\"ה ולרמז חומש יש ה' בסוף תיבת חלה שהרי אי אפשר לכתוב ה' במנין מ\"ג אלא בתיבת חלה שהרי מיד כשתקח בידך מנין ה' נשאר בידך מנין ל\"ח והרי חלה:","\u0003נתבאר בטור א\"ח. \u0004וע\"פ אותו השיעור שערתי והוא ג' קוואר\"ט פחות מעט וכן נהגו וכ\"כ מהרי\"ו סי' קנ\"ג בדיני פסח דשיעור חלה הוא כלי שמחזיק מעט פחות מג' זיידלי\"ך וזייד\"ל הוא קוואר\"ט:","\u0003כלי המחזיק כו'. \u0004כ' העט\"ז צ\"ע באלו המדות אם ר\"ל מרובעות או עגולות כו' והדבר פשוט שהוא מרובעות שהרי הוא מהרמב\"ם פ\"ו מהל' בכורים שלמדו מרביעית של תורה של פסח שהוא במרובע וכמו שנתבאר שם בדברי הפוסקים וע\"ל סימן ר\"א ס\"ק ו' וכ\"כ בס' מע\"מ דף קכ\"ג ע\"א:","\u0003הוא העומר. \u0004והוא החלה:","\u0003ה' מיני תבואה. \u0004כיון דשם חיוב חלה על כולן שוה הרי אלו מצטרפין:","\u0003כשערבן קמח. \u0004ולש אותן יחד דכיון דלש אותן יחד כל העיסה נראה שוה כאלו הוא ממין אחד:","\u0003וכוסמין ושיפון כו'. \u0004ושעורים מפרישים מזה על זה דמין אחד הם ואע\"ג דבשאין באחד מהך כשיעור ומדבקן יחד אמרינן הרבה יותר מצטרפים כגון חטים עם כוסמים וכוסמים עם כולם וכן השאר הכא אמרינן דחטים עם כוסמים ולא כוסמים עם שבולת שועל ולא עם שעורים וכן שעורים ושבולת שועל עם שיפון נמי לא נ\"ל דה\"ט דלענין הצטרף להתחייב בחלה כיון דבעיסה תליא רחמנא דכתיב עריסותיכם לפיכך כשאין בכל א' כשיעור אמרינן כל היכא דהעיסות דומות מצטרפות וחייב בחלה אע\"פ שאינם מין א' אבל לענין לפטור מן החלה דהיינו כשיש בכל אחד שיעור חיוב חלה ורוצה לפטור זה ולהפריש עליו ממין אחר אמרינן כיון דתרומה קרייה רחמנא הוי דומיא דתרומה שאין מפרישין ממין על שאינו מינו אע\"ג דהעיסות דומות עכ\"ל ע\"ש:","\u0003חייב בחלה. \u0004דכיון שלא נצטרפו כשהיו מעורבים לא היה להם שעת חובה עד עתה דלאחר שחלקו הוסיף כל אחד רובע הקב ממינו ואיכא ה' רביעיות לכל א' ואחד ממין אחד נתחייבה בכל אחד ואחד להפריש חלה:","\u0003פטור. \u0004כיון דבאו לידי חובה פעם אחת ונפטרו כשחולקים שוב אין חוזרין לידי חיוב חלה בהוסיף על כל אחד רובע הקב כדלקמן סימן שכ\"ו:","\u0003אינו מצטרף. \u0004דעריסותיכם אמר רחמנא ואין זה דרך עריסה לערב בו מורסן וסובין לאחר שהפרישן מן הקמח:","\u0003באמצע מחברן. \u0004להתחייב כולה בחלה כאלו היה בכל אחד שיעור חלה דאע\"ג דחטין ושעורים אין מצטרפין הכוסמין שבאמצע מצטרף עם שניהם כדלעיל סעיף ב' וא\"כ החטים חייבים בלא השעורים והשעורים חייבים בלא החטים ותורם מכל אחד ואחד בפני עצמו שהרי אין תורמין מין על שאינו מינו וגם מן הכוסמין תורם בפני עצמו והרי מפריש ג' חלות אבל אין תורם מן הכוסמין על שלשתן דאע\"פ שהכוסמים מחייבים את החטים ואת השעורים אין תורמים מן הכוסמים עליהם לפי שגם הכוסמים מתחייבים במה שנושכים בחטים ושעורים והיה די לו בצירוף אחד מהן לפיכך אם היה תורם מן הכוסמים על השעורים הוי כתורם מן החטים על השעורים דכיון דצירוף החטים מחייב הכוסמי' נגררים הכוסמים אחר החטים ונקראים על שמם וכן נמי אם היה תורם מן הכוסמים על החטים הוה כתורם מן השעורים על החטים מה\"ט וכן נמי מה\"ט גופיה אם היה תורם מן החטים על הכוסמים או מן השעורים על הכוסמים הוי כתורם מן החטים על השעורים או מן השעורים על החטים לפיכך צריך להפריש מן כל מין ומין בפני עצמו:","\u0003מצטרפים ותורם כו'. \u0004דכיון דליכא בכל אחד אלא חצי קב הרי אין כאן שיעור חלה עד שיצטרפו שלשתן ונמצא דכוסמים ששניהם מצטרפין עמה ומשלימין אותה לכשיעור וחייב וחטים ושעורים שאין מצטרפין זה עם זה פטורים:","\u0003אינם מצטרפין. \u0004כיון דהאמצע אינו בדין חלה:","\u0003מצטרפין. \u0004דאף על פי שעכשיו היא פטורה כיון שהיתה בדין חלה מצטרפת וכן בסעיף ז' כיון שהם בדין חלה מצטרפין:","\u0003אינם מצטרפים. \u0004דאף על גב דגבי כוסמין עם חטים או שעורים מצטרפים אף על גב דב' מינים הן הואיל ודומין זה לזה כ\"ש בחדש וישן דחד מין הוא שאני התם דהכל יודעים דב' מינים הן ולא שייך למטעי אבל הכא כיון דמין אחד הן גזרו בדבר שאם אתה אומר שיצטרפו יאמרו שתורמים מזה על זה ואסור לתרום מן החדש על הישן או להיפך הכי אמרינן בירושלמי ולפי זה משמע דמכל מקום צריך להפריש על כל אחד ואחד מעיסה אחרת שלא הורמה חלתה מן החדש על החדש ומן הישן על הישן וכ\"כ ר\"ש והרמב\"ם ובית יוסף וכן בדין דהא כיון דמן התורה חייבים בחלה מצטרפים וחייבים בחלה ודאי דלא אתי גזירה דרבנן לאפקועי איסורא לפטרה מחלה וקאכיל טבלא וכ\"כ העט\"ז:","\u0003אם יש בה טעם דגן חייב בחלה. \u0004דאורז גריר אחר החטין כן כתב העט\"ז ולפי זה משמע בחטין ואורז אזלינן בתר טעם וכמ\"ש הרשב\"א אבל מהטור משמע להדיא דה\"ה לכל ה' מיני דגן וכן משמע באשר\"י דתלה הטעם דכיון דטעם כעיקר דאורייתא:","\u0003נתן שאור כו'. \u0004וה\"ה אם נתערב עיסה שאינה של שאור שלא הורמה חלתה לתוך עיסה שהורמה חלתה דינא הכי דהא הך טעמא דטבל אוסר בכל שהוא בהכי נמי שייך ואדרבה בהכי שרי טפי להפריש מיניה וביה דיש בילה בדבר לח ובשיעור חלה שיפריש אי אפשר שלא יהא בו מעיסה שלא הורמה חלתה וחלה אין לה שיעור מן התורה אבל בשאור כתב בת\"ה סימן ק\"ץ דמודה הרא\"ש דאין בילה ולפ\"ז צ\"ל הא דשרי הרא\"ש בשאור לפרוש מיניה וביה היינו דוקא בשאור שלא הורמה חלתה כדמיירי התם להדיא והיינו מטעם דכתב התם דטבל אוסר בכל שהוא במינו ונעשית כולה (פסולה) [טבולה] לחלה ולפ\"ז בשאור של עובד כוכבים שנתערב בעיסה אין להפריש מיניה וביה להרא\"ש דהא אין בילה ואיכא למיחש דלמא אתי לידי שאור של עובד כוכבים ומפריש מן הפטור על החיוב והשתא ליכא למימר דנעשית כולה (פסולה) [טבולה] דהרי שאור של עובד כוכבים אינו טבל שיאסר בכל שהוא אבל בטור הביא דברי הרי\"ף דבשאור של עובד כוכבים נמי דינא הכי משמע דס\"ל דגם הרא\"ש סובר דיש בילה אף בשאור וכמ\"ש בת\"ה שם בשם סמ\"ק וזה דעת המחבר שכתב וה\"ה אם השאור של פטור כו' ולפ\"ז לא היו צריכים הרא\"ש והמחבר לטעמא לפי שנעשית כולה טבל דבלאו הכי שרי כיון דיש בילה בדבר לח ואפשר לא שרי מהך טעמא דיש בילה בדבר לח אלא כשעיקר העיסה הוא של חיוב דאי אפשר שלא יפריש משל חיוב מעט וחלה מן התורה אין לה שיעור אבל כשנתן מעט שאור שלא הורמה חלתה לעיסה אפשר שיזדמן שיפריש מעיקר העיסה שהורמה חלתה ולא יפריש משאור כלל ולא שרי הכא מטעמא דיש בילה להכי צריך לטעמא דטבל אוסר בכל שהוא ובפרישה כתב נתן שאור מעיסה שלא הורמה כו' נראה דוקא שאור אבל עיסה כל זמן שאין לה שיעור חלה אינה טובלת וק\"ל עכ\"ל ותימא דמ\"ש הא סוף סוף מה\"ת חלה היא דחלה אין לה שיעור מן התורה:","\u0003אם יש לה קמח או עיסה כו'. \u0004ויש בעיסה שניה שיעור עיסה שחייבת בחלה נותנת בכלי אצל העיסה שהורמה חלתה כדי שיהא מן המוקף וסגי כשהן סמוכות אע\"פ שאין נוגעים וליכא נמי צירוף כלי כדלקמן סי' שכ\"ה:","\u0003מפריש ממנו על זה השאור. \u0004דאין זה כמפריש מן החיוב על הפטור שאין השאור בטל בעיסה ר\"ש והרא\"ש ולכאורה קשה ל\"ל להך טעמא דאינו בטל בעיסה תיפוק ליה דנעשה כולו טבל וכ\"נ מדברי הב\"ח:","\u0003וה\"ה אם השאור של פטור כו'. \u0004כלומר שאור של עובד כוכבים וכמו שנתבאר או שאור שהורמה חלתו לעיסה שלא הורמה חלתה ובמהרי\"ל כתב בהל' פסח כששאלו למהר\"ש אחר פסח על עיסה שנתנו בה שאור של עובד כוכבים איך להפריש ממנה חלה היה מורה שיפרישו חלה נגד השאור ומעט יותר כי אמר שאם לא היו לוקחים יותר אזי יש לחוש מה שמפריש היה הכל משל עובד כוכבים ונמצא מפריש מפטור על החיוב ואמר שאחר כך כשמחמיצים עיסה אחרת עם השאור שנוטלים מתוך זאת העיסה אז אינו צריך להפריש רק מעט לחלה כו' אז הוא כמו ס\"ס וכשנוטלים לעולם מן העיסה שאור להחמיץ עיסה אחרת אז יהו נוטלים קודם שיפרישו החלה כדי שלא יהא נפטר ממה שהפרישו ונמצא בתר הכי כשמפרישים חלה מעיסה אחרת זה היה מן הפטור על החיוב ואמר שיש נוהגין שאין מפרישין מעט חלה גם בעיסה שניה שהחמיצה עם מה שנטלו מזאת העיסה אלא ג\"כ בכאן נוטלים נגד הכל שהחמיצו בו מעט יותר ומהר\"ש היה מורה אל אשתו הרבנית ללוש שתי עיסות אחת בשאור של עובד כוכבים ואחת כשיעור חלה בלא שאור ולקרב העיסות להדדי ולא יטול חלה מאותה שלא נתחמצה בשאור של עובד כוכבים על הכל עכ\"ל ואף על פי שדעת המחבר אינו כן וכמ\"ש לעיל ס\"ק י\"ח מכל מקום יש להחמיר וגם בתשב\"ץ מחמיר:","\u0003אבל אם כבר עבר ועשה כו' בעיסה אחרת שיהא בו לשאור. \u0004כלומר שבעיסה אחרת ישאור שאר עיסות ולא חיישינן דילמא בעיסה ראשונה שלקח ממנו לא לקח רק שאור של פטור והשתא נמי בבצק שני דילמא אתרמי רק אותו שאור של פטור דכולי האי לא חיישינן דמתרמי תרי זימני ממש אותו של פטור. ת\"ה שם:","\u0003ויפריש מכל אחד על כולם כו' ומא' יותר כו'. \u0004דאל\"כ דילמא מפריש מהפטור על החיוב:","\u0003האופה פשטיד\"א כו'. \u0004זה פשוט דיכול להפריש מעיסה אחרת על זו אבל המ\"כ שהביא ב\"י אשמועינן דיכול להפריש חלה על הבשר גופיה דאף על גב דבבשר ליכא אלא טעמא לחוד לא אמרינן דהוי כמפריש מחיוב על הפטור דטעם כעיקר נמי דאורייתא ע\"ש ודו\"ק:","\u0003אסור לעשות כו'. \u0004דוקא כדי לפטרה קאמר דאסור לעשותו אבל אם אין לו קמח שיעור חלה פשיטא דמותר לאפותו בלא חלה. פרישה. ומ\"מ נהגו הנשים להדר בכל ע\"ש אחר שיעור חלה ועיין בא\"ח סי' תנ\"ז נתבאר דלענין פסח יש ללוש לכתחלה עיסות קטנות פחות משיעור חלה ואח\"כ יצרפם בכלי להפריש מהן חלה:"],["\u0003ממלאין אותה קמח. \u0004זו דעת רשב\"א וחולק על הרא\"ש דס\"ל משערינן לפי התבואה כמו עומר של מן ממילא בקמח הוא צריך יותר וע\"כ כתב שיש למדוד בקמח בגודש ורשב\"א כתב דא\"כ א\"א לנו לדעת כמה ניתוסף במן אחר שנטחן ברחיים אלא ודאי אין משערינן אלא בקמח וע\"כ אין צריך גודש:","\u0003כשערבן קמח. \u0004נראה דה\"ה אם עשה מכל אחת עיסה בפני עצמה ועירב העיסות עד שנעשו גוף אחד מצטרפין כשאין בכל אחד כשיעור דהא אמר בירושל' דדוקא בדיבוק על ידי נשיכה אין הכל מצטרפין משמע דאם הם נעשו ואחד הוה בלול ומשום הכי מה שכתב רמ\"א בסמוך עירב קב מעיסה מיירי בדרך נשיכה בעלמא וכן כתב בב\"י אבל אם עירב העיסות ממש הוה כמו עירב קמח בקמח ובפרישה כתב דהאי עירב היינו אפי' בעירב העיסות וחלקן והוא תמוה מאד:","\u0003וכוסמין ושיפון כו'. \u0004פי' אע\"ג דברישא לענין צירוף ושיעור חלה מהני אפילו בכוסמין וחטין או שעורין וכוסמין התם לא איכפת לן במה שהם חלוקים לענין כלאים אלא במה שהעיסות דומות זו לזו אבל כאן שיש כשיעור לכל אחד אלא דבעינן מין במינו אזלינן בתר דין כלאים וכל שהוא כלאים הוה שלא במינו ונראה דאם יש בעיסה אחד כשיעור ובאחד אין שיעור ורוצה לצרפו לעיסה הגדולה הוה דינו כמו ברישא לצירוף חלה ונפקא מיניה אם יוסיף אח\"כ עיסת חיוב על אותו שעשה שאין בה שיעור אין לחייבו בחלה כי כבר נפטר מחמת צירוף:","\u0003עירב קב מעיסה כו'. \u0004פירוש כיון דאין מצטרפין לא באו לכלל חיוב מעולם מה שאין כן בסיפא בעירב קב קמח כו' מאחר שהיתה חייבת כבר והיה להן שעת חובה ונפטרו מאחר שעל דעת לחלק עירבן כדלקמן סי' שכ\"ו אף לאחר שהוסיפו עליהם פטורים וכתב רש\"ל אלא יפריש בלא ברכה ע\"ש:","\u0003וצריך להפריש מכל מין ומין. \u0004כיון שהכוסמין באמצע ונושכים עם החטים מצד אחד ועם השעורים מצד אחד הלכך תורם מכל אחד ואחד שאין תורמין ממין על שאינו מינו ואע\"פ שהכוסמין מחייבין את החטים ואת השעורים אין תורמין מהכוסמין עליהם לפי שגם הכוסמין מתחייבין במה שנושכים מחטים ושעורים ודי לו בצירוף עם אחד מהם הלכך אם תורם מן הכוסמים על השעורים הוה כתורם מהחטים על השעורים דכיון דצירוף החטים מחייב הכוסמין נגררים הכוסמין אחר החטים ונקראים על שמם וכן נמי על החטים מהאי טעמא אבל בסעיף שאחר זה דליכא אלא חצי קב בכל אחד ליכא שיעור עד שיצטרפו שלשתן ונמצא דכוסמין שהוא מצטרף עם שניהם חייב וחטים ושעורים דאין מצטרפין זה עם זה פטורים עכ\"ל הר\"ש והרא\"ש ובדרישה נסתפק בסעיף זה במה שכתב שצריך להפריש מכל מין ומין אם צריך להפריש גם מהכוסמין ותמיהני עליו היאך יפריש ג' חלות הא אין כאן שיעור ג' חלות אלא ברור דהכוסמין עושה החיוב ומכח זה יחייב החטים והשעורים ותו לא דהוא פטור עמהם עוד כתב בפרישה וז\"ל קב חטין מצד זה כו' לכאורה משמע דדוקא נקט קב אבל אם לא היה אלא חצי קב מכל צד ובאמצע קב כוסמין לא היה מצטרף דלא שדינן כל הכוסמין לצד זה ולצד זה אבל ממה שכתב בסיפא חצי קב חטין מצד זה משמע דלאו דוקא נקט קב ברישא עכ\"ל ודבריו תמוהים מאד הא ודאי אי ליכא אלא חצי קב בחטים וחצי קב בשעורים ממילא עם הכוסמין לא הוי שיעור שתי חלות והיאך יפריש שתי חלות אלא פשוט דבעינן שיהיה בכל אחד מן הקצוות שיעור שעם צירוף האמצעי יהיה שיעור ב' חלות ואז יפריש שתי חלות מן הקצוות אבל אם אין עם הצירוף רק שיעור חלה אחת וקצת יותר אף על פי שיש ספק לאיזה מהם נצרף הכוסמין מכל מקום כיון שמפריש על החטים ממילא נצטרפו הכוסמין עמהם ונפטרו הכוסמין כולן ממילא אין צריכין להפריש אחר כן על השעורים שהרי אין בהם שיעור וכן להיפך כנ\"ל:","\u0003שכבר הורמה חלתה. \u0004הטעם במשנה פרק ד' דחלה כיון שכבר היה נתחייב בחלה:","\u0003היה ביניהם קב. \u0004פירוש בין שני קבין חטים היה קב אחד משאר חמשה מינים שאין להם צירוף לחטין כגון שיפון או מין אחר שאין מצטרפין לחלה כדלעיל סעיף ב' מכל מקום לא חשיב כאן הפסק בין אלו שני קבין חטין כיון שעל כל פנים גם זה הוא בר חיוב חלה ע\"כ מצטרפין שפיר שני קבין חטין להדדי וכן אם מפסיק ביניהם קב משל אשה אחרת אין מבטלין הצירוף של שני הקצוות אע\"פ שאינו מצטרף לחיוב חלה:","\u0003אינם מצטרפין. \u0004זהו מדרבנן מטעם גזירה שמא יבוא להפריש מזה על זה כיון שהם מין אחד ומבואר בב\"י שצריך להפריש עליהם מצד אחר דהא מן התורה הם חייבים:","\u0003אע\"פ שרובה אורז. \u0004משמע אע\"ג דלית שיעור חלה בדגן לחוד וכתב ב\"י בשם הרשב\"א דוקא באורז אמרו כן לפי שנגררים אחר החטין אבל שאר המינים לא:","\u0003נתן שאור מעיסה. \u0004דוקא שאור אינה בטלה בעיסה אבל עיסה כל זמן שאין לה שיעור חלה לא טובלת. כן כתב ב\"י בשם הפוסקים:","\u0003אם יש לו קמח כו'. \u0004בטור כתוב או אם ירצה יביא רובע הקב מקמחו ויערבנו עם זו העיסה ויפריש ממנו עכ\"ל. והיינו מפירוש הר\"ש ומבואר שם דגם בזה אינו מפריש אלא לפי חשבון ונראה הטעם כיון שיש כאן שיעור חלה דהיינו מן השאור שבא ממקום חיוב ומה שהוא מוסיף עכשיו קמח אין צריך לחשב שאר העיסה לזה אלא מן שיעור חלה של חיוב שבו וכתב רש\"ל דאין צריכין שיערבנו בעיסה אלא אף נותן אותה בצד עיסה אם ירצה עכ\"ל:","\u0003אחד משמונה וארבעים. \u0004בשאור כל העיסה לפי שאין השאור בטל ועושה הכל טבל על כן אם מפריש ממקום אחר די בהפרשה לפי שיעור השאור לחוד דהא השאור הוא הגורם החיוב והוא מפריש עליו ממקום חיוב גמור דהיינו ממקום אחר מה שאין כן אם אין לו קמח ממקום אחר וצריך להפריש מיניה גופיה כיון שאינו מפריש ממקום שחייב בחלה רק מחמת שקבלה העיסה טעם מהשאור ונעשה כולה חייבת על כן יפריש כשיעור מן העיסה כולה דאזלינן בתר מעשה הפרשתו. כן נראה לי:","\u0003וה\"ה אם השאור של פטור כו'. \u0004והיינו כגון אחר פסח שלוקחין שאור של עובד כוכבים ונותנין אותה בעיסה יכול להפריש מיניה וביה ולא חיישינן דמתרמי בידו שאור של פטור אלא אמרינן דכולו נעשה חיוב על ידי שנבלל. ותמיה לי שהרי כתב שם בת\"ה סימן ק\"ץ דאין בילה אלא ביין ושמן לבד ומצריך להפריש חלה גדולה יותר ממה שהיה עיסה של עובד כוכבים שנתערב דממה נפשך יש באותה חלה מעיסה של ישראל וכתב דיש להחמיר כן אלא שאחר כך כתב דיש להקשות גם על זה שהרי רגילין הנשים ליקח מעט בצק מעיסה הגדולה ומשהין אותה לשאור להחמיץ בו עיסה אחרת ונוטלת אותה בצק מהעיסה קודם הפרשת חלה כדי שיהיה אותו בצק מן החיוב שאם היו נוטלין אחר הפרשה היתה כל העיסה פטורה ונמצא שאור זה ג\"כ של פטור והוה כשאור של עובד כוכבים דצריך תקנה והשתא בזה אם יטלו קודם הפרשה יש לחוש דלמא יבוא לידיה אותו שאור של עובד כוכבים שנתערבה והיא של פטור וכשתחמיץ משאור זה שנעשה מבצק זה יתערב גם כן בעיסה השניה וכשתפריש מן העיסה השניה יש לחוש ג\"כ שמא יבוא לידו בצק שניטל מעיסה הראשונה והיא של פטור וי\"ל דלא חיישינן דילמא איתרמי תרי זימני עכ\"ל וזהו שכתב רמ\"א אבל אם כבר כו' ומשום הכי יש ליזהר אחר הפסח שיקח חלה יותר משיעור השאור של עובד כוכבים כי כן מסיק שם בתה\"ד:","\u0003עיסה מחמש רבעים. \u0004כתב רש\"ל ונ\"ל דאם עושה עוגה קטנה פשיטא דמצטרף כמו שמצטרף עיסה קטנה לעיסה גדולה כדלעיל ועיין בדרישה שהביא לשון מהרש\"ל:","\u0003האופה פשטיד\"א כו'. \u0004עיקר חידוש דין זה דלא נימא דכיון דאין בבשר רק טעם דמי למפריש מחיוב על הפטור ולא מהני הפרשה עליה אלא כיון דקיי\"ל טעם כעיקר דאורייתא הוה כאלו הוא ממש עיסה ומהני הפרשה עליה ממקום אחר) אבל מעיסת הפשטיד\"א עצמה לא כיון שיש בו טעם בשר וכתב מהרי\"ו בתשובה סימן מ\"ח וז\"ל על העיסה שלא נטלו ממנו חלה ונתבשלה לא שייך הכא ביטול דכל העיסה טבל כיון שלא הורמה חלתה ומ\"מ נראה דאיכא תקנה כגון ליטול ממנה חלה לאחר שנתבשלה ויקח ממה שישער בעיסה יותר ממאה ואחת ואע\"ג דכשנתבשלה היתה הכל טבל מ\"מ כיון דאחר כך הפריש אמרינן ברירה דבדרבנן אמרינן ברירה דהכי איפסק בפ' בתרא דביצה ותו גבי חלת חוצה לארץ קי\"ל כשמואל דאמר אוכל והולך ואח\"כ מפריש אלמא דאמרי' ברירה עכ\"ל ומו\"ח ז\"ל חולק על זה דאין שייך ביטול באחת ומאה אלא כשכבר הורמה ואח\"כ נפלה לתבשיל מה שא\"כ כאן דכשיפריש יתוקן כל מה שנתבשל ולע\"ד נראה דברי מהרי\"ו נכונים דהוקשה לו כיון שיש בעיסה זו חלקו של כהן והוא מבשל כולה נבלע טעם האיסור בכולה ולא מהני ההפרשה אח\"כ וראיה לזה מזרוע בשלה בפ' גיד הנשה (חולין דף צ\"ח) דאמרינן התם דמבשל הזרוע שהיא חלקו של כהן עם הבהמה והיא בטילה בששים ומהתם ילפינן שיעור ששים לביטול וא\"כ הדברים ק\"ו דמה התם דאמרה תורה בפי' שלא יתנו לכהן רק אחר הבישול אפ\"ה אי לאו הביטול היה אוסר שאר הבהמה ולא אמרינן שאין חלק של כהן מתחיל רק אחר הבישול אלא אוסר למפרע ק\"ו כאן בחלה שהחיוב ליתן משעת הגלגול ודאי אוסרת כל העיסה אם אין שם ביטול נגדה וא\"ל שאני זרוע דאי אפשר בענין אחר משא\"כ כאן שאפשר להפריש על זה ממקום אחר ונמצא אין כאן איסור ודאי זה אינו דמ\"מ כל זמן שלא הפריש יש איסור בעיסה זו וראיה מדברי תה\"ד סימן נ\"ד שביאר דלדעת רש\"י בסאה תרומה שנפלה לאחת ומאה של חולין דבטלה וצריך להרים חלקו של כהן ואי בעי יוכל לתת לו מעות בעד חלקו ואפ\"ה אמרינן כל כמה דלא יהיב דמי אסור לאכול הכל כ\"ש כאן דודאי איסור גמור יש בכל העיסה כל זמן שלא הפריש חלה א\"כ החלה שיש בעיסה זאת אסרה הכל כל שאין ביטול נגדה כיון שאינו מפריש עד לבסוף אמאי לא אמרינן דמה שאכל תחילה היה איסור מצד שלא הפריש עדיין ואפשר שמה שאוכל הוא החלה אלא ע\"כ דבשעה שמפריש אח\"כ אמרינן ברירה למפרע שלא היה שם חלה יותר ה\"נ כן הוא לענין תערובת ונתינת טעם בעיסה ונמצא דברי מהרי\"ו נכונים מאוד וכן ראוי לנהוג במי ששכח להפריש חלה דדינו שאוכל ואחר כך מפריש שיפריש אח\"כ חלק קטן מאד עד שתהיה באותה עיסה שאפה ק\"א נגדה ואע\"פ שרמ\"א לא הביא זה מ\"מ הלכה היא ודברים נכונים הם כנלע\"ד:","\u0003פטורה. \u0004דבתר שעת הגלגול אזלינן דאז עיקר החיוב:","\u0003כדי להפקיע. \u0004אבל אם נתכוין לטעם אחר כגון בפסח שעושין עוגות קטנות כמו שמוזכר בא\"ח ומצרפין שתי עיסות להדדי בשביל שיעור חלה או שאין לו רק עיסה קטנה ודאי שרי:"]],["שְׁתֵּי עִסוֹת שֶׁאֵין בְּשׁוּם אַחַת כַּשִּׁעוּר, אִם נוֹגְעוֹת זוֹ בְּזוֹ \u0010c0\u0011 עַד שֶׁנִּדְבָּקִים מְעַט זוֹ בְּזוֹ, \u0010y0\u0011 מִצְטָרְפִים, אִם הֵם מִמִּין הָרָאוּי לְהִצְטָרֵף, כְּפִי מַה שֶּׁנִּתְבָּאֵר בְּסִימָן שכ\"ד. וְאִם אֵינָם נִדְבָּקִים, וְהֵם בְּסַל אֶחָד, הַסַל מְצָרְפָן וַאֲפִלּוּ אַחַר שֶׁנֶּאֱפָה וְנַעֲשָׂה פַּת. וְאִם נְתָנָם \u0010y1\u0011 עַל טַבְלָא שֶׁאֵין לָהּ לְבַזְבָּז, אֵינָם מִצְטָרְפִים. \u0005הַגָּה: \u0010y2\u0011 וְלָכֵן כְּשֶׁמְּצָרְפָם בִּכְלִי יִזָּהֵר שֶׁלֹּא יֵצֵא שׁוּם דָּבָר לְמַעְלָה מִדָּפְנֵי הַכְּלִי, \u0010y3\u0011 \u0010c1\u0011 דְּהַיְנוּ שֶׁיְּהֵא כָּל כִּכָּר אֶחָד אוֹ עִסָּה לְמַעְלָה מִדָּפְנֵי הַכְּלִי (טוּר)\u0006. \u0010y4\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאִם מְכַסֶה הַפַּת בְּמַפָּה חָשׁוּב כְּמוֹ כְּלִי לְצָרְפָן. \u0010y5\u0011\nאִם יֵשׁ בְּכָל עִסָה כַּשִּׁעוּר, וְרוֹצֶה לְהַפְרִישׁ מִזּוֹ עַל זוֹ, אֵין צָרִיךְ לֹא צֵרוּף כְּלִי וְלֹא נְגִיעָה, אֶלָּא כֵּיוָן שֶׁשְּׁתֵּיהֶן לְפָנָיו מַפְרִישִׁין מִזּוֹ עַל זוֹ.",["\u0003מצטרפים כו'. \u0004ודוקא שהם של אדם אחד אבל לא של שתי נשים כדבסימן שאח\"ז:","\u0003על טבלא כו'. \u0004זהו בעיא דלא איפשטא וכתב המחבר בסתם שאין מצטרפין כיון דבזמן הזה כל חלה דרבנן וכדלעיל סימן שכ\"ג אזלינן לקולא:","\u0003ולכן כשמצרפם כו'. \u0004אטבלא קאי דכשכל הככר או העיסה למעלה מדופני הכלי הוי דומיא דטבלא דאין מצטרף:","\u0003שיהא כל ככר כו'. \u0004למעלה מדופני הכלי הא מקצתה בפנים מצטרף דלא הוי דומיא דטבלא וכמ\"ש ב\"י והב\"ח חולק בדבר ע\"ש:","\u0003ויש מי שאומר כו'. \u0004לא ידעתי למה כתבו בשם יש מי שאומר שהרי אין חולק בדבר וגם הטור נקט סתמא האי דינא ומהרי\"ל בהלכות פסח כתב דאם אין לו הכלי שמחזיק את כולה יניחנה במפה ויכסה המפה גם כן עליהם ונקרא צירוף הגון:","\u0003אם יש בכל כו'. \u0004ונראה דבב' עיסות אחת יש בה כשיעור ואחת אין בה כשיעור דינן כב' עיסות שיש בכל א' מהן כשיעור דאפילו נגיעה לא בעי אלא שיהו סמוכות ומפריש מן העיסה שיש בה כשיעור שיעור חלה וגם מפריש עוד ממנה אחד ממ\"ח על העיסה שאין בה כשיעור ולא צריך צירוף סל וכיסוי וכדלעיל סי' שכ\"ד (סי\"א) . ב\"ח:"],["\u0003עד שנדבקים. \u0004בת\"ה סימן קפ\"ט כתב בשם פי' המשניות דנשיכה היינו שמדבק כל כך שכשיפרדו יתלשו אחת מחברתה מעט:","\u0003דהיינו שיהא כל ככר אחד כו'. \u0004בטור לא כתוב רק שלא יצא שום דבר למעלה מדופני הכלי ובית יוסף ורמ\"א פירשו הך דהיינו כו' ולכאורה משמע לשון הטור דקפיד אפילו על מקצת מן הככר שלא יצא אבל מכל מקום האמת כדבריהם דאי על מקצת קאמר קשה למה לא יועיל כשהככר למטה תוך אויר הכלי ונצטרף שם מידי דהוה אעיסות שנוגעים על ידי נשיכה והרי אינם מחוברים רק במקצת ואפי' הכי הוה מחובר כו':"]],["שְׁתֵּי עִסוֹת שֶׁיֵּשׁ בִּשְׁתֵּיהֶן שִׁעוּר הַחַיָּב בְּחַלָּה, וְאֵין בְּאַחַת מֵהֶן כַּשִּׁעוּר, וְנָגְעוּ זוֹ בְּזוֹ וְנָשְׁכוּ זוֹ אֶת זוֹ, \u0010y0\u0011 אִם הָיוּ שֶׁל שְׁנַיִם, אֲפִלּוּ הֵם מִמִּין אֶחָד, \u0010y1\u0011 פְּטוּרִים מִן הַחַלָּה, שֶׁסְתָם שְׁנַיִם מַקְפִּידִים. וְאִם יָדוּעַ שֶׁאֵינָם מַקְפִּידִים עַל עֵרוּב הָעִסוֹת, הֲרֵי אֵלּוּ מִצְטָרְפוֹת. \u0005וְתַלְמִידִים הַלּוֹמְדִים לִפְנֵי רַב, סְתָמָא אֵינָם מַקְפִּידִים (מָרְדְּכַי פֶּרֶק כָּל הַבָּשָׂר)\u0006, הָיוּ שְׁנֵיהֶם שֶׁל אִישׁ אֶחָד, אִם הָיוּ מִמִּין אֶחָד כְּפִי מַה שֶּׁנִּתְבָּאֵר בְּסִימָן שכ\"ד, מִצְטָרְפִין וְחַיָּבִים בְּחַלָּה. וְאִם מִשְּׁנֵי מִינִים הָיוּ, אֵין מִצְטָרְפִין, שֶׁסְתָם אֶחָד אֵינוֹ מַקְפִּיד. וְאִם הָיָה מַקְפִּיד שֶׁלֹּא תִּגַּע עִסָה זוֹ בְּזוֹ וְלֹא תִּתְעָרֵב, אֲפִלּוּ הָיוּ מִין אֶחָד אֵין מִצְטָרְפוֹת. וְאִם הָאַחַת פַּת קִבָּר וְהָאַחַת פַּת נָאָה, אֲפִלּוּ הֵן שֶׁל אָדָם אֶחָד, מִסְתָמָא מַקְפִּיד וְאֵינוֹ מִצְטָרֵף. \u0005הַגָּה: וְהוּא הַדִּין שְׁתֵּי עִסּוֹת שֶׁיֵּשׁ בְּאַחַת כַּרְכֹּם וּבַשֵּׁנִית אֵין בָּהּ. \u0010c0\u0011 וְכָל זֶה שֶׁאֵין שִׁעוּר בְּכָל אַחַת, \u0010y2\u0011 אֲבָל אִם יֵשׁ בָּהֶן שִׁעוּר, מַפְרִישׁ מֵאַחַת עַל חֲבֶרְתָּהּ אִם הֵן שֶׁל אָדָם אֶחָד (ת\"ה סִימָן קכ\"ט)\u0006.\nנַחְתּוֹם \u0010y3\u0011 שֶׁעָשָׂה עִסָה לַעֲשׂוֹתָהּ שְׂאוֹר לְחַלְּקָהּ, חַיֶּבֶת בְּחַלָּה, שֶׁאִם לֹא תִּמָּכֵר יַעֲשֶׂנָּה פַּת. \u0010y4\u0011 אֲבָל \u0005שְׁאָר אָדָם\u0006 \u0010c1\u0011 הָעוֹשֶׂה עִסָה לְחַלְּקָהּ בְּבָצֵק, פְּטוּרָה.\nשְׁנַיִם שֶׁנָּתְנוּ קֶמַח לְנַחְתּוֹם לַעֲשׂוֹת לָהֶן שְׂאוֹר, אִם אֵין בְּשֶׁל אֶחָד מֵהֶן כַּשִּׁעוּר, אַף עַל פִּי שֶׁיֵּשׁ בִּכְלָלָן \u0010y5\u0011 כַּשִּׁעוּר, פְּטוּרָה. \u0005הַגָּה: וְדַוְקָא שֶׁעֵרְבָן שֶׁלֹּא מִדַּעְתָּן, אֲבָל מִדַּעְתָּן חַיָּב שֶׁהֲרֵי אֵינָן מַקְפִּידִין (בֵּית יוֹסֵף בְּשֵׁם סְמַ\"ג)\u0006.\nשְׁנַיִם שֶׁעָשׂוּ \u0010y6\u0011 עִסָה כַּשִּׁעוּר וְחִלְּקוּהָ, וְאַחַר כָּךְ הוֹסִיף כָּל אֶחָד עַל חֶלְקוֹ עַד שֶׁהִשְׁלִימוֹ לְכַשִּׁעוּר, הֲרֵי זֶה פְּטוּרָה, שֶׁכְּבָר הָיְתָה לָהֶם שְׁעַת חוֹבָה, \u0010y7\u0011 וְהֵם הָיוּ פְּטוּרִים בְּאוֹתָהּ שָׁעָה מִפְּנֵי שֶׁעֲשָׂאוּהָ לְחַלֵּק \u0005הַגָּה: וְהוּא הַדִּין בְּאָדָם אֶחָד שֶׁעָשָׂה ב' קַבִּין \u0010y8\u0011 וְדַעְתּוֹ לְחַלְּקָם, וְחִלְּקָם. \u0010y9\u0011 אֲבָל אִם לֹא עֲשָׂאָם עַל מְנַת לְחַלְּקָם, \u0010c2\u0011 לֹא מְהָנֵי הַחֲלוּקָה אַחַר כָּךְ (טוּר)\u0006.\nהַמַּפְרִישׁ חַלָּה מֵעִסָה שֶׁאֵין בָּהּ שִׁעוּר, אֵינָהּ חַלָּה. לְפִיכָךְ שְׁתֵּי עִסוֹת שֶׁאֵין בְּשׁוּם \u0005אַחַת\u0006 מֵהֶן כַּשִּׁעוּר, וְהִפְרִישׁ מִכָּל אַחַת חַלָּה וְאַחַר כָּךְ עֵרַב הָעִסוֹת וַעֲשָׂאָן עִסָה אַחַת, חַיֶּבֶת בְּחַלָּה.",["\u0003אם היו של שנים כו'. \u0004דוקא שאינם שותפים אבל אם הם שותפים חייב בחלה כדלקמן סי' ש\"ל ס\"ב וכב\"י שכל שאין דעתו לחלק בצק אע\"פ שדעתו לחלק אחר שנאפה מצטרפים:","\u0003פטורים מן החלה. \u0004אפילו נילושו העיסות ביחד ולא נקט ברישא נגעו ונשכו אלא לרבותא דסיפא דבאינן מקפידין אפי' בנגיעה ונשיכה מצטרפין:","\u0003אבל אם יש בהן שיעור. \u0004אע\"פ שאחד פת קיבר והב' פת נאה או שיש בא' כרכום ובשני אין בו מפריש מאחד על חבירו אם הם של אדם אחד אפילו בלא נגיעה ונשיכה אלא שהם לפניו דהא ממין אחד הם וכדלעיל ס\"ס שכ\"ה:","\u0003שעשה עיסה לעשותה שאור. \u0004לחלק לחלקים קטנים שלא יהא בהם שיעור חלה חייבים בחלה שאם לא ימכר לחלקים יעשנה פת ויתחייב בחלה וכתב הב\"ח יש נוהגים לקנות מן הנחתום חלק א' מעיסה גדול' ויש באותו חלק כשיעור ומפריש ממנו חלה ומברך עליו וכך הוא מוכר מאותה עיסה להרבה בני אדם לכל אחד שיש בו כשיעור וכל אחד מפריש מחלקו ומברך עליו והדבר פשוט שזה טעות חדא דהלא מיד שגלגל הנחתום העיסה הגדולה חייב להפריש ממנה חלה אפילו היה דעתו למכרה לחלקים קטנים פחות מכשיעור כ\"ש הכא שאין דעתו למכרה אלא לחלקים בכשיעור וכיון דהמצוה חלה עליו להפריש חלה ושוב פטורה כל העיסה היאך נתיר לכתחלה למכור לחלקים ושהלוקחים יפרישו חלה ויברכו והנחתום לא יפרישולא יברך ותו דכיון דבהפרשת חלה של הנחתום פטורה כל העיסה לית לן למכרה לחלקים ושיברך כל אחד ברכה בפני עצמו משום ברכה שאינה צריכה ע\"כ. וכ' שקבל מרבותיו שאיסור גמור הוא ושהאריך בתשו' בזה אבל בתשובת משאת בנימין סי' א' כ' דלחומרא דוקא יש לחלק בין נחתום לאיש דעלמא אבל לא לקולא והלכך אין למחות ביד הנשים הקונות מן הנחתום ישראל וכל אחת נוטלת חלה משלה בפני עצמה אם הוא כשיעור חלה ואדרבה צריך לקיים ולהחזיק מנהגן כדי שבקל בלא טירחא תוכל כל אשה ליקח חלה כל ערב שבת שכבר נהגו ליקח חלה ע\"פ הירושלמי דמסכתא שבת אדם הראשון חלתו של עולם כו' וגרמה לו ' חוה מיתה לכך נמסרה מצות חלה לאשה כו' ואין דבריו מוכרחים וכ' עוד שם בתשובת מ\"ב אמנם מה שנוהגים בחתונה שעושים לחם גדול שמניחים אותו על השלחן בשעת הדרשה שממנו לוקחים חלה הרבה נשים כל אחת בפני עצמה אע\"פ שכל אשה נוטלת עיסה כדי שיעור מ\"מ לפי שמתחלה לשו הכל בבת אחת אין להפריש רק חלה א' ולכן יש למחות ביד הנשים שלא יטלו מאותו לחם רק חלה אחת עכ\"ד ודברים פשוטים הם. וכן ראיתי מהגבירה הרבנית אמי תי' ומשאר נשים צדקניות חכמניות שנזהרו בזה:","\u0003אבל שאר אדם העושה עיסה לחלקה בבצק. \u0004לאנשים הרבה שלא יהא באחת מהן שיעור חלה פטורה אבל אין דעתו לחלק בצק אע\"פ שדעתו לחלקה אחר אפיה חייבת:","\u0003פטורה. \u0004ודוקא שנים שנתנו לנחתום אבל אדם אחד שנתן לנחתום מסתמא אינו מקפיד ואפילו ערבו שלא מדעתו חייב:","\u0003וחלקוה. \u0004בעודה בצק בענין שלא היה בשום חלק כשיעור:","\u0003והם היו פטורים באותה שעה כיון שעשאוה לחלק. \u0004והואיל ונפטרה עיסה זו בעוד היה בו שיעור הוה כאילו הופרש ממנו חלה ושוב לא יחזור להתחייב ונראה דוקא שאין שיעור חלה במה שהוסיף אחר כך אלא ע\"י הצטרפות מה שנחלק אבל אם יש במה שהוסיף לבד כשיעור פשיטא שהוא חייב בלא\"ה ואין זה שנחלק ונפטר פוטר מה שהוסיף:","\u0003ודעתו לחלקם וחלקם. \u0004והוסיף עליהם דפטור כיון שהיה פטור אז כשהיה לו שעת חובה וע\"ל סי' ש\"ל ס\"ה:","\u0003אבל אם לא עשאם כו'. \u0004וה\"ה בשני בני אדם אם אינם מקפידים ולא עשאום. ע\"מ לחלקם לא מהני החלוקה אח\"כ:"],["\u0003וכל זה שאין שיעור בכל אחת. \u0004פירוש אז אין מצטרפות אפילו על ידי נגיעה או נשיכה אבל אם יש שיעור מפריש אחד על חבירו כו' פירוש ע\"י נגיעה ונשיכה ואע\"ג דבסוף סי' קכ\"ה פסק כיון ששתיהן לפניו מפריש מזו על זו ואין צריכין נשיכה ואפילו צירוף סל שאני הכא דהוי דבר שמקפיד עליו וכן מבואר בת\"ה סי' ק\"ץ וראיה ברורה מן תלמוד ערוך בשתי עיסות אחת טהורה ואחת טמאה דהוי דבר המקפיד צריך דוקא חוט בצק לחברם ועל כן כתב דהא דמבואר בי\"ד דבדבר המקפיד אין מצטרף אפי' על ידי נשיכה היינו אם אין בכל אחד כשיעור חלה אין בידינו להחשיבה כעיסה אחת לחייבה בחלה ורמ\"א שכ' כאן מפריש מאחד על חבירו ולא זכר נשיכה היינו דסמך על מ\"ש בתחלת הסי' שמיירי בנשכו ומ\"מ גרם מכשול לפני בעל הלבוש ובמחלה מכבודו שגג מאד בזה שכ' בד\"א שצריך נשיכה כשאין בכל אחד שיעור חלה ורוצה לצרפם אבל אם יש בכל אחד שיעור חלה אע\"פ שאחד פת כרכום ובשני אין בו מפריש מאחד על חבירו אם הם של אדם אחד אפילו בלא נשיכה אלא שהם לפניו דהא ממין אחד הם עכ\"ל טעה בתרתי דכ' באין שיעור מהני צירוף על ידי נשיכה וביש שיעור לא צריך נשיכה וחשיב שהך יש שיעור הוא כאותו של סוף הסי' שלפני זה ולא היא דכאן מיירי בדבר המקפיד ועל כן בדבר שאין בו שיעור לא מהני נשיכה לצרפה לשיעור חלה וביש שיעור מהני נשיכה שיפרוש מאחד על חבירו ובלי ספק לא עיין בעל הלבוש במקור הדין וזה גרם לו שכתב כן:","\u0003העושה עיסה לחלקה בצק. \u0004פירוש לכל אחד פחות מכשיעור חלה אבל אם אין דעתו לחלקה בצק אע\"פ שדעתו לחלקה אחר אפיה חייב כן כתב ב\"י ודלא כסמ\"ג:\n\u0003וכתוב \u0004בתשובת מהר\"ר בנימין ז\"ל סי' א' המנהג בקצת מקומות שנחתום ישראל עושה עיסה גדולה ובאות הנשים ולוקחות ממנו כל אחת כדי שיעור חלה וכל אחת נוטלת חלה מעיסה שלקחה מהנחתום דשפיר עבדי הכי דבדעת האדם תליא מילתא כמו דאמרינן הכא לקולא דאם דעתו לחלק בצק פטורה הכי נמי אזלינן לחומרא בתר דעתו והוה כאילו כל בצק נילוש בפני עצמו וחייב כל אחד ליטול חלה משיעור חלה שלו ומו\"ח ז\"ל חלק על זה ע\"ש וכ' שכן קיבל מרבותיו שאיסור גמור הוא ואני הצעיר אומר אם קבלה הוא נקבל ואם לדין יש תשובה דיש לי ליישב המנהג מצד אחר והוא ע\"פ הגמרא פרק כל הגט (גיטין דף ל') המלוה מעות את הכהן להיות מפריש עליו מחלקו מפריש עליו בחזקת שהוא קיים ואינו חושש שמא מת הכהן פירוש כשיפריש תרומותיו וימכור התרומה ויעכב הדמים לעצמו בפרעון החוב זה בשביל הכהן ופרכינן על זה ואף על גב דלא אתי לידיה בתמיה אע\"פ שאינו נותנו לכהן והוא יחזירם לו קתני דמפריש עליו וכיון דלא מטי לידיה מאן זכי ליה להך כהן הך תרומה שיקבלנה זה בחובו והיאך יצא ידי נתינה ומשני במכירי כהונה עסקינן שאינו רגיל לתת תרומה אלא לכהן זה הלכך כיון דמלתא דפשיטא היא דלדידיה יהיב ליה אסחו להו שאר כהנים דעתייהו והוה כמאן דמטו לידיה דמהני. ויש עוד תירוצים בגמרא דמתרצי בענין אחר מכל מקום לא פליגי על תירוץ זה מצד הדין אלא דקשיא להו הא לא קתני מתני' מכירי כהונה אלמא דלדינא הם מודים דכל שהם מכיריו הוה כאילו אתו לידייהו ה\"נ בהאי נחתום שיש לו מכירין שרגילין ליקח ממנו כל ע\"ש והם קונים על מנת כן שהם יפרישו חלה והוה להו כאילו קנו ממנו קודם שעושה העיסה ואתי לידייהו בשעת חיוב דהיינו בשעת הגלגול וזה פשוט דשנים שעושין עיסה לחלק לכל אחד שיעור חלה שאין אחד מהם יכול להפריש חלה בשביל חלק חבירו אם הוא מקפיד ע\"ז ואינו נעשה שלוחו בעל כרחו ה\"נ כן הוא דודאי דעת הנחתום לעשות בענין המועיל והוה כאילו הקנה להם הנחתום תחלה חלקם קודם שמגלגל העיסה מצד שהם מכיריו ורגילים ליקח ממנו בודאי הוא מקנה להם בשעת גלגול העיסה לכל אחד חלקו ואי אפשר לו ליקח חלה מהעיסה דהוה כאינו שלו ובשעת חלוקה נוטל כל אחד חלקו ומפריש ומברך כן נרא' לי ליישב אותו המנהג אם הוא באופן שזכרתי שיש נשים רגילין ליקח בכל ערב שבת מזה הנחתום אבל לא באופן אחר כן נראה לעניות דעתי ובנחתום עובד כוכבים פשיטא שאין שייך דבר זה דאינו מקנה רק אחר החלוקה. ובחתונה שעושות הנשים לחם אחד גדול ולוקחין הרבה נשים מאותה עיסה שיעור חלה ומפרשת כל אחת חלה ואח\"כ חוזרין ומערבין העיסה ועושין מהם לחם אחד זהו פשיטא דאסור וכ\"כ הרב שם בההיא תשובה:","\u0003לא מהני החלוקה אח\"כ. \u0004נ\"ל דאף שיחלוק אח\"כ אין צריכא ליטול כי אם חלה אחת כיון דבתר מעיקרא אזלינן כשהיה עיסה אחת אע\"פ שיש אחר החלוקה שני שיעור חלות:"]],["הַמַּפְרִישׁ חַלָּתוֹ קֶמַח, אֵינָהּ חַלָּה, \u0010y0\u0011 \u0010c0\u0011 וְגֶזֶל בְּיַד כֹּהֵן, וּשְׁאָר הָעִסָה חַיֶּבֶת בְּחַלָּה. וְאוֹתוֹ הַקֶּמַח שֶׁהִפְרִישׁ לְשֵׁם חַלָּה, \u0010y1\u0011 אִם יֵשׁ בּוֹ עֹמֶר וְעָשָׂהוּ עִסָה, הֲרֵי זֶה מַפְרִישׁ מִמֶּנָּהּ חַלָּה. וְדַוְקָא בְּאוֹמֵר שֶׁיָּחוּל עָלֶיהָ שֵׁם חַלָּה בְּעוֹדוֹ קֶמַח, אֲבָל הַמַּפְרִישׁ קֶמַח וְאוֹמֵר: כְּשֶׁתֵּעָשָׂה עִסָה יָחוּל עָלֶיהָ שֵׁם חַלָּה, דְּבָרָיו קַיָּמִים.\nאֵימָתַי מַפְרִישִׁין חַלָּה, כְּשֶׁיִּתֵּן הַמַּיִם \u0010y2\u0011 וִיעָרֵב הַקֶּמַח בַּמַּיִם. וְהוּא שֶׁלֹּא יִשָּׁאֵר שָׁם בָּעֲרֵבָה קֶמַח שֶׁלֹּא נִתְעָרֵב בַּמַּיִם שִׁעוּר עֹמֶר. וְאִם אָמַר: הֲרֵי זוֹ חַלָּה עַל הָעִסָה וְעַל הַשְּׂאוֹר וְעַל הַקֶּמַח שֶׁנִּשְׁתַּיֵּר, וְלִכְשֶׁתֵּעָשֶׂה כֻּלָּהּ עִסָה אַחַת תִּתְקַדֵּשׁ זוֹ שֶׁבְּיָדִי לְשֵׁם חַלָּה, \u0010y3\u0011 הֲרֵי זֶה מֻתָּר. וְכֵן אִם מַתְנֶה שֶׁתָּחוּל הַחַלָּה אַף עַל הַקֶּמַח שֶׁיִּתְעָרֵב אַחַר כָּךְ בִּשְׁעַת עֲרִיכָה. \u0010y4\u0011 וְטוֹב לְלַמֵּד לַנָּשִׁים לְהַתְנוֹת כֵּן \u0005אִם יֵשׁ לָחוּשׁ שֶׁיִּתְעָרְבוּ שִׁעוּר חַלָּה אַחַר כָּךְ (בֵּית יוֹסֵף בְּשֵׁם סְמַ\"ג)\u0006. וְצָרִיךְ לִזָּהֵר שֶׁלֹּא לִשְׂרֹף הַחַלָּה \u0010c1\u0011 עַד אַחַר כָּל הָעֲרִיכָה. \u0010y5\u0011\nהָאִדָּנָא טוֹב לְהַמְתִּין מִלְּהַפְרִישׁ חַלָּה עַד אַחֵר גְּמַר לִישָׁה, שֶׁתֵּעָשָׂה כָּל הָעִסָה גּוּף אֶחָד.\nאוֹכְלִים עֲרַאי מִן הָעִסָה עַד שֶׁתִּתְגַּלְגֵּל בַּחִטִּים, וְיִתְעָרֵב הַקֶּמַח בַּמַּיִם, \u0010c2\u0011 וְתִטַּמְטֵם בַּשְּׂעוֹרִים וְתֵעָשֶׂה כָּל הָעִסָה גּוּף אֶחָד.\nאִם לֹא הִפְרִישׁ הַחַלָּה בָּצֵק, אֶלָּא אָפָה הַכֹּל, הֲרֵי זֶה מַפְרִישׁ מִן הַפַּת.",["\u0003וגזל ביד כהן. \u0004כלומר שצריך להחזירה אם טעו ונתנו לו:","\u0003אם יש בו עומר. \u0004כלומר כשיעור חלה:","\u0003ויערב הקמח. \u0004היינו דוקא כשיש באותו שמתערב שיעור חלה ומ\"מ צריך שלא ישאר שם בעריבה שום קמח שלא נתערב במים כשיעור חלה מפני שאז אין החלה פוטרת מה שיתערב אח\"כ אא\"כ התנה כדמפרש ואזיל:","\u0003וכן אם מתנה וכו'. \u0004כלומר ברישא אינו מקדיש החלה מיד אלא מפרישה מיד ואומר הרי זו מוכנת לחלה ולא תתקדש זו שבידי עד שתעשה כולה עיסה א' ולכך מותר אף שנתערב אחר ההפרשה שיעור חלה דהא אינה מתקדשת אלא לאחר שנעשו כולם עיסה א' וכאן קאמר דה\"ה אם מקדישה מעכשיו אלא שמתנה שכשיתערב הקמח אח\"כ כשיעור החלה תחול החלה זו אף על הקמח מותר:","\u0003וטוב ללמד לנשים כו'. \u0004היינו כשמפרישין החלה מיד כשנותני' מים ומתערב בקמח ובשיש לחוש שיתערבו אח\"כ שיעור חלה וכמ\"ש הרב אבל עכשיו שנהגו שאין מפרישים עד אחר גמר לישה א\"צ ללמדם כן:","\u0003האידנא כו'. \u0004כלומר דבזמן הש\"ס שהיו עושין עיסתן בטהרה תקנו להם חז\"ל לנשים שיפרישו החלה מטהרה מיד שידבק הקמח מעט כי חששו שמא תטמא העיסה ויצטרכו להפריש חלה טמאה ולא תהיה ראויה לכהן אבל האידנא שכל העיסות טמאות טוב להמתין מלהפריש חלה עד אחר גמר לישה שתעשה כל העיסה גוף אחד ויפריש החלה על כולו:"],["\u0003וגזל ביד כהן. \u0004בגמרא פ' האיש מקדש (קידושין דף מ\"ו) מוכח אפי' יודע הנותן שאין מפרישין חלה קמח לא אמרינן דודאי גמר ונתן לשם מתנה דטעמא משום דאתי לידי חורבא זימנין דלא ידע כהן הדין על בוריו כדאיתא בגמ' שם ובזה מתורץ קושיא שם בגמ' למה הוצרך בגמ' לומר טעמא דחורבא ולא מתרץ בקיצור דאין אדם יודע שפיר הטעם בחלה ומוהר\"ר מאיר ז\"ל מלובלין דחק עצמו לתרץ קושיא זאת בדרך רחוק ולפי מה שכתבתי א\"ש דתנא סתמא קתני המפריש חלתו קמח דמשמע אפי' אם הוא ת\"ח אפ\"ה הוה גזל ביד כהן ואי לאו טעמא דחורבא היה קשה למה לא נימא בזה אדם יודע הדין על בוריו ונתן לשם מתנה אלא ודאי כיון שיש לחוש שיבוא לידי חורבא ויבוא לידי אסור ע\"כ לא פלוג רבנן דגזרינן באינו תלמיד חכם שיבוא לידי איסור דוק בגמ' שם ותמצא שכן הוא בלי ספק כן נראה לי:","\u0003עד אחר כל העריכה. \u0004דאל\"כ אינה חלה על המתגבל אחר כן אע\"פ שהתנה:","\u0003ותטמטם בשעורים. \u0004פי' דרך החטים ללוש ולגלגל יפה אבל השעורים כשילוש אותם עיסתו מתפרדת ואינו יכול לגלגל יפה ע\"כ מטמטמו ביד עד שידבקו קצתם בקצתם עד שיהיו גוף אחד:"]],["בְּשָׁעָה שֶׁיַּפְרִישׁ חַלָּה יְבָרֵךְ: אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהַפְרִישׁ תְּרוּמָה, \u0010y0\u0011 \u0010c0\u0011 \u0005אוֹ לְהַפְרִישׁ חַלָּה (טוּר)\u0006. לְפִיכָךְ אָסוּר לְאִישׁ לְהַפְרִישׁ חַלָּתוֹ \u0010y1\u0011 עָרֹם, מִפְּנֵי שֶׁאִי אֶפְשָׁר לוֹ לְבָרֵךְ כְּשֶׁהוּא עָרֹם. אֲבָל הָאִשָּׁה מֻתֶּרֶת, וְהוּא שֶׁיְּהוּ פָּנֶיהָ שֶׁלְּמַטָּה טוּחוֹת בַּקַּרְקַע. \u0005וּבְמָקוֹם שֶׁמַּפְרִישִׁין ב' חַלּוֹת, לֹא יְבָרֵךְ \u0010y2\u0011 רַק כְּשֶׁמַּפְרִישִׁין הָרִאשׁוֹנָה (כָּל בּוֹ)\u0006.\nהַסוּמָא וְהַשִּׁכּוֹר, \u0010y3\u0011 מַפְרִישִׁין חַלָּה לְכַתְּחַלָּה.\nאֵין מַפְרִישִׁין חַלָּה בְּלֹא רְשׁוּת בַּעַל הָעִסָה. \u0005הַגָּה: מִיהוּ אִם יָדְעִינַן דִּזְכוּת הוּא לְבַעַל הָעִסָּה, כְּגוֹן שֶׁהָיְתָה הָעִסָּה מִתְקַלְקֶלֶת, מֻתָּר לִטֹּל חַלָּה בְּלֹא רְשׁוּתוֹ, דְּזָכִין לָאָדָם שֶׁלֹּא בְּפָנָיו. \u0010y4\u0011 \u0010c1\u0011 וְכֵן מְשָׁרֶתֶת שֶׁבַּבַּיִת יְכוֹלָה לִטֹּל חַלָּה בְּלֹא רְשׁוּתוֹ, כֵּיוָן שֶׁרְגִילָה הִיא לִפְעָמִים שֶׁבַּעֲלַת הַבַּיִת נוֹתֶנֶת לָהּ רְשׁוּת (ת\"ה סי' קפ\"ח)\u0006. ב' שֻׁתָּפִין אֵין צְרִיכִין לִטֹּל רְשׁוּת זֶה מִזֶּה \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם פ\"ד דִּתְרוּמוֹת)\u0006, \u0010y5\u0011 אֲבָל אַחֵר צָרִיךְ לִטֹּל רְשׁוּת מִשְּׁנֵיהֶם \u0005(בֵּית יוֹסֵף בְּשֵׁם סְמַ\"ג)\u0006. וּמִיהוּ אִם נָתַן רְשׁוּת לְאַחֵר לְהַפְרִישׁ, אֲפִלּוּ בְּעוֹדוֹ קֶמַח, מוֹעִיל, \u0010y6\u0011 אַף עַל פִּי שֶׁעֲדַיִן לֹא נִתְחַיֵּב. וְהָאוֹרֵחַ יֹאמַר לְבַעֲלַת הַבַּיִת לְהַפְרִישׁ לוֹ חַלָּה מִכָּל עִסוֹת שֶׁתַּעֲשֶׂה לוֹ בְּעוֹד שֶׁיִּהְיֶה בְּבֵיתָהּ, כְּדֵי שֶׁלֹּא תִּצְטָרֵךְ לִטֹּל רְשׁוּת בְּכָל פַּעַם.",["\u0003או להפריש כו'. \u0004מיהו להפריש תרומה עדיף טפי כדאיתא בב\"י בשם הפוסקים ובפסח נוהגות הנשים לומר להפריש תרומה חלה וכ' הב\"ח דטועין דבכל השנה יש לברך תרומה חלה וכ\"מ בדברי מהרש\"ל ומביאו בפרישה ס\"ג דבכל השנה יש לומר תרומה חלה ועי' בדרישה סעיף ד':","\u0003ערום. \u0004אע\"פ שהוא יושב מפני שערותו בולטת משא\"כ באשה. טור:","\u0003רק כשמפרישין הראשונה. \u0004שהרי השניה אינה אלא להיכרא בעלמא כדלעיל סימן שכ\"ג:","\u0003מפרישין חלה. \u0004אע\"ג שאין תורמין תרומה לכתחלה סימן של\"א סל\"ב היינו משום דחיישינן שמא יתרמו מן הרעה על היפה אבל בחלה אין בעיסה רעה ויפה שיכוונו להפריש מן הרעה על היפה. רמב\"ם:","\u0003וכן משרתת כו'. \u0004והב\"ח השיג על הרב בזה דבדברי מהרא\"י מפורש דלא התיר לכתחלה במשרתת אפילו רגילה היא ליתן לה רשות אא\"כ דאיכא חשש קלקול והיכא דאיכא קלקול ודאי אפילו אשה שאינה משרתת נעשית שלוחה שלא מדעתה ע\"ש. ומשמע הא כל שאינה משרתת ואין כאן חשש קלקול אסור להפריש שלא מדעתה אע\"פ שהיא מגבלת העיסה והרי היא פועלת בעיסה זו וכדעת ב\"י שהשיג על הסמ\"ק וכן פסק הב\"ח מיהו כתב מכל מקום בדיעבד אם הפריש הגבל בלא רשות וניחא ליה לבעל הבית שהפריש הוי חלה ואין צריך לחזור ולהפריש אבל אחר שאינו גבל אפילו דיעבד לא הוי חלה וצריך לחזור ולהפריש ע\"ש:","\u0003אבל אחר צריך כו'. \u0004כלומר אם אחר מפריש להשותפים צריך ליטול רשות מכל בעלי העיסה:","\u0003אע\"פ שעדיין לא נתחייב. \u0004משום דמ\"מ יש בידו להביא עיסה ולומר עיסה זו תהא חלה על קמח לכשיהיה נילוש. תוספות:"],["\u0003או להפריש חלה. \u0004כ' רש\"ל ע\"כ נוהגים לומר תרומה חלה שניהם עכ\"ל ותמיהני דאכתי נימא שמא חלה היא העיקר ולא תרומה וא\"כ הוה תיבת תרומה הפסקה בין הברכה לתיבת חלה ובהדיא כ' בסמ\"ק שאין כאן קפידא ואיזה שירצה יאמר ואותן נשים שמשנות בפסח בחלה מן המצות ממה שאומרים כל השנה פשיטא שטעות הוא בידם דמה שינוי יש בזה לענין ברכה. ומשמע כאן דאין צריכין לומר מן העיסה אלא די כשאומרות להפריש חלה ואמאי נהגו לומר מן העיסה ואע\"ג דהדין הוא כן לאפוקי להפריש חלה מקמח מ\"מ אין בו צורך לענין ברכה וכי צריכין להזכיר פרטי הדינים בברכה ולעיל סי' כ\"ח בברכת כסוי שאומרים בעפר כתבנו שם הטעם למה אומרים הפרט וכאן איני יודע בו צורך:","\u0003וכן משרתת כו'. \u0004בת\"ה סי' קפ\"ח כ' תשובה זו על שפחה משרתת שלשה עיסה להאשה והלכה האשה ועכבה עד שנתחמצה כל צרכה ואם תשהה עוד תתקלקל העיסה ובשביל כך רוצה המשרתת להפריש חלה בלי רשות בעלת הבית דשפיר דמי למיעבד הכי דכיון דמתקלקלת העיסה זכות הוא לה לבעלת הבית וזכין לאדם שלא בפניו והכי נמי המשרתת נעשית שלוחה אפי' שלא מדעתה מטעם זה ואפי' אין כאן אלא חשש קלקול העיסה אמרינן דזכות הוא לה כיון דרגילות הוא לפעמים שבעלת הבית נותנת רשות להפריש חלה אפי' בפניה וכן יש לה כח לעשות שליח כדאיתא כו' ואע\"ג דבפ\"ק דחולין אמרי' אי אמר לשלוחו זיל תרום ושמע איש אחר ותרם אין תרומתו תרומה י\"ל דוקא התם לא מהני דיש קפידא דרוצה דוקא בזה דיודע ומכיר באיזה מדה רגיל ב\"ה לתרום עין יפה או רעה אבל בהפרשת חלה בזמן הזה דהכל שוין בו ליטול בכזית אין לומר כלל שיש קפידא מי יפריש ויתרום ותו דאיכא למימר מטעם שיש לחוש לקלקול העיסה ליכא קפידא כלל וכן גבי גט אם ידעינן דזכות הוא לה וניחא לה בגט לא הוה קפידא כלל מי יקבל הגט במקומה עכ\"ל. הנה מה שכתב ואפילו אין כאן אלא חשש קלקול העיסה כו' הוא דבר שאין לו פירוש דהא גם ברישא מיירי מזה ואין לומר דברישא מיירי מקלקול ודאי ובסיפא מיירי מחשש קלקול בעלמא דמ\"ש זה מזה דודאי גם בספק קלקול יש לה זכות להוציא מידי ספק ותו מאי מייתי אח\"כ כיון דרגילות הוא לפעמים שנותנת לה רשות כו' היאך שייך זה לענין ספק קלקול הא אפילו בלא ספק קלקול יש היתר בזה ואין זה תלוי בספק קלקול ותו דהא כתב אחר כך דדוקא לענין תרומה יש קפידא מי יהיה שלוחו כיון שאין כל אדם יודע מדה שלו ש\"מ אי לאו משום טעם זה היה מותר אפי' באדם אחר. ותו דהא אח\"כ מסיק וז\"ל ותו דאיכא למימר דיש לחוש לקלקול העיסה כו' משמע דמעיקרא איירי בלא חשש קלקול עיסה ותו אי נימא דבא להתיר בסיפא ולחדש דאפילו בספק קלקול מותר מאי מייתי מגט היכא דידעינן שזכות הוא לה דמשמע דדוקא ידוע שזכות הוא לה וכאן עיקר החידוש שאינו ודאי אלא פשוט הוא לענ\"ד דיש כאן ט\"ס וצ\"ל ואפילו אין כאן חשש קלקול כו' דהיינו שיש היתר בלאו הכי מצד שרגילות הוא שנותנת רשות וכן משמע שהיה גורס רמ\"א בדברי ת\"ה שהרי כ' וכן משרתת כו' דמשמע אפי' בלא שום חשש קלקול עיסה ומו\"ח ז\"ל חולק על רמ\"א ומפרש דברי ת\"ה בדרך שכתבתי דמיירי בסיפא מחשש קלקול ולא קלקול ודאי דבזה דוקא מותר למשרתת להפריש חלה והנלע\"ד כתבתי דא\"א לפרש כן ומ\"מ נראה לע\"ד דבעל ת\"ה עצמו לא סמך על זה להתיר בלא חשש קלקול עיסה שהרי לבסוף הזכיר ההיתר בשביל קלקול דוקא וכן בשאלה שסידר שם בת\"ה לא הזכיר אלא בשביל קלקול העיסה וידוע הוא דרכו של ת\"ה שהוא עצמו סידר השאלות ונלע\"ד להביא ראיה מדברי הטור ס\"ס זה ע\"פ סמ\"ק שכתב שאם המגבל הפריש בלא רשות דהוה חלה ובסמ\"ק עצמו כתב בלשון זה ונראה דאם ב\"ה אומר דניחא ליה שיפריש הגבל יפריש ואם הפריש שלא ברשות חלתו חלה כמ\"ד פועלים שהלכו שתי וערב בגת דתורמין שלא מדעת ב\"ה עכ\"ל והך מ\"ד הוא בירושלמי מביאו הר\"ש פרק ג' דתרומות על מתניתין דאמרינן התם הפועלים אין להם רשות לתרום חוץ מן הדרוכות שהן מטמאין את הגת ופירש הר\"ש דבעלים ע\"ה השכירו פועלים חברים לדרוך בענבים כדי להפריש תרומה בטהרה רשאין לתרום עד שלא יגעו בו הבעלים ויטמאו את הגת ובירושלמי אמר רבי יוחנן כיון שהלכו שתי וערב מטמאין את הבור מיד כלומר שעד אותו זמן נזהרין בעלים ליגע בהם אבל משם ואילך אין נזהרין דסבורין שכבר הפרישו תרומה הלכך אם הלכו בגת שתי וערב והניחוה יחושו שמא נגעו בו הבעלים עכ\"ל והקשה הב\"י על ראיה זאת דאינה ענין לחלה דהתם שאני שלכך השכירם להפריש לו תרומה בטהרה עכ\"ל ומכח זה דחאה מהלכה ולא הביאה בש\"ע וק\"ל לפי דברי ב\"י מאי קמ\"ל מתניתין דהדרוכות יכולים לתרום שלא ברשות פשיטא שהרי לזה השכירם ותו למה קראום שלא ברשות דכל שליח ודאי ברשות הוא ונראה דבעל הסמ\"ק הוקשה לו גם כן קושיא זאת ע\"כ פי' דאף אם לפעמים אין אומר לו בפירוש שיפריש תרומה אלא שוכרו סתם לעשות מלאכתו ודאי ניחא ליה וכן משמעות לשון הסמ\"ק שכתב תחילה אם ב\"ה אומר דניחא ליה שיפריש הגבל כו' ואח\"כ כתב ואם הפריש שלא ברשות כו' חדא שייכא בחברתא ועל הרישא קאי דכל שמתחלה גילה דעתו דניחא ליה אמרינן אח\"כ אפילו אם הפריש פעם אחת שנא מדעתו שפיר דמי ואף לשון הטור שכתב שאם הגבל הפריש כו' יש לפרש כן שרגיל להפקיד לגבל שיפריש ע\"כ מועיל אף אם הפריש פעם אחת שלא מדעתו ולעד\"נ להלכה דבערב שבת שמנהג הנשים להקפיד על זה שכל אחת תטול חלה ונחשבים בעיניהם לחיוב לעשות לחמים לכבוד שבת בשביל החלה אז לא תפריש שום משרתת בלא צווי בעלת הבית אם לא שיש חשש קלקול עיסה אבל בשאר ימי השבוע מותרת המשרתת או אחד מבני ביתה כיון שרגילה לתת להם להפריש דאינה מקפדת על זה. כן נראה לע\"ד:"]],["אֵין חִיּוּב חַלָּה \u0010y0\u0011 אֶלָּא בְּלֶחֶם. לְפִיכָךְ הַסֻפְגָּנִין, דְּהַיְנוּ רַכִּים הָעֲשׂוּיִים כִּסְפוֹג, וְהַדֻּבְשָׁנִין וְהָאִסְקָרֵיטִים, וְהֵם מְטֻגָּנִים בִּדְבַשׁ, פְּטוּרִים מִן הַחַלָּה. \u0010y1\u0011\nעִסָה שֶׁבְּלִילָתָהּ רַכָּה וַאֲפָאָהּ בְּתַנּוּר אוֹ בְּמַחֲבַת, בֵּין שֶׁהִרְתִּיחַ וְאַחַר כָּךְ הִדְבִּיק, בֵּין שֶׁהִדְבִּיק וְאַחַר כָּךְ הִרְתִּיחַ, חַיֶּבֶת בְּחַלָּה \u0010y2\u0011 \u0010c0\u0011 וּבִלְבַד שֶׁלֹּא עַל יְדֵי מַשְׁקֶה.\nעִסָה שֶׁבְּלִילָתָהּ \u0005(רַכָּה)\u0006 עָבָה, וְגִלְגְּלָהּ \u0010c1\u0011 עַל דַּעַת לְבַשְּׁלָהּ אוֹ לְטַגְּנָהּ אוֹ לַעֲשׂוֹתָהּ סֻפְגָּנִין אוֹ לְיַבְּשָׁהּ בַּחַמָּה, וְעָשָׂה כֵּן, \u0010y3\u0011 פְּטוּרָה. גִּלְגְּלָהּ לַעֲשׂוֹת מִמֶּנָּהּ לֶחֶם, וְנִמְלַךְ לְבַשְּׁלָהּ אוֹ לְטַגְּנָהּ אוֹ לַעֲשׂוֹתָהּ סֻפְגָּנִין אוֹ לְיַבְּשָׁהּ בַּחַמָּה, חַיֶּבֶת, שֶׁכְּבָר נִתְחַיְּבָה מִשְּׁעַת גִּלְגּוּל. גִּלְגְּלָהּ עַל דַּעַת סֻפְגָּנִין וְכַיּוֹצֵא בָּהֶן, וְנִמְלַךְ לַעֲשׂוֹתָהּ לֶחֶם, חַיֶּבֶת.\nאֲפִלּוּ כְּשֶׁעוֹשֶׂה אוֹתָהּ עַל דַּעַת לְבַשְּׁלָהּ וְכַיּוֹצֵא בוֹ, \u0010c2\u0011 אִם דַּעְתּוֹ לֶאֱפוֹת מִמֶּנָּהּ מְעַט, \u0010y4\u0011 \u0010c3\u0011 וַאֲפָאוֹ, אֲפִלּוּ אֵין בְּאוֹתוֹ מְעַט שִׁעוּר חַלָּה, \u0010y5\u0011 \u0010c4\u0011 כֻּלָּהּ מִתְחַיֶּבֶת עַל יָדוֹ.\nטְרִיתָא, דְּהַיְינוּ עִסָה שֶׁבְּלִילָתָהּ רַכָּה וְשׁוֹפְכִין אוֹתָהּ עַל הַכִּירָה וּמִתְפַּשֵּׁט עָלֶיהָ וְנֶאֱפֵית, פְּטוּרָה. אֲבָל אִם יֵשׁ בַּכִּירָה גֻּמָּא וְשׁוֹפְכִין אוֹתָהּ לְתוֹכָהּ, חָשׁוּב לֶחֶם וְחַיָּב. \u0005הַגָּה: בָּצֵק שֶׁאוֹפִין אוֹתוֹ בְּשִׁפּוּד וּמוֹשְׁחִים אוֹתוֹ בְּבֵיצִים אוֹ בְּשֶׁמֶן אוֹ בְּמֵי פֵּרוֹת, פָּטוּר (טוּר)\u0006.\nהָעוֹשֶׂה עִסָה לְיַבְּשָׁהּ \u0010y6\u0011 בַּחַמָּה בִּלְבַד, פְּטוּרָה. וְכֵן קָלִי שֶׁלָּשִׁין אוֹתוֹ בְּמַיִם אוֹ בִּדְבַשׁ, וְאוֹכְלִין אוֹתוֹ בְּלֹא אֲפִיָּה, פָּטוּר. וְקָלִי שֶׁלָּשׁוֹ כְּדֵי לֶאֱפוֹתוֹ, \u0010c5\u0011 חַיָּב.\nלֶחֶם הֶעָשׂוּי לְכוּתָח, מַעֲשֶׂיהָ מוֹכִיחִים עָלֶיהָ. עֲשָׂאָהּ כְּעָבִין, דְּהַיְנוּ שֶׁעֲרָכוֹ וַעֲשָׂאוֹ כְּצוּרַת לֶחֶם, חַיָּב. וְאִם לָאו, פָּטוּר. \u0010y7\u0011\nעִסָה שֶׁנִּלּוֹשָׁה בְּמַיִם רוֹתְחִין, בֵּין שֶׁנָּתַן רוֹתְחִין עַל גַּבֵּי קֶמַח בֵּין שֶׁנָּתַן קֶמַח בְּרוֹתְחִין, חַיֶּבֶת, בֵּין שֶׁאָפָה בְּתַנּוּר אוֹ בְּאִלְפָּס בְּלֹא מַשְׁקִין.\nעִסָה שֶׁנִּלּוֹשָׁה בְּמֵי פֵּרוֹת, אֲפִלּוּ בְּלֹא שׁוּם מַיִם, \u0010y8\u0011 חַיֶּבֶת בְּחַלָּה. \u0010y9\u0011\nיֵשׁ לִזָּהֵר מִלָּלוּשׁ \u0010c6\u0011 בְּמֵי פֵּרוֹת שֶׁאֵינָם מִשִּׁבְעָה מַשְׁקִים, \u0010y10\u0011 אֶלָּא אִם כֵּן יְעָרֵב עִמָּהֶם אַחַת מִשִּׁבְעָה מַשְׁקִים \u0005(סמ\"ק סִימָן רי\"ח)\u0006. \u0005הַגָּה: וְעַיֵּן בא\"ח סִי' קצ\"ח בֵּאַרְתִּי \u0010y11\u0011 מַה הֵם הַשִּׁבְעָה מַשְׁקִין. וְאִם עָבַר וְלָשׁ בְּלֹא ז' מַשְׁקִין, לֹא יִשְׂרֹף הַחַלָּה, אֶלָּא יִתֵּן אוֹתָהּ לְכֹהֵן קָטָן\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם סְמַ\"ג)\u0006, \u0005כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שכ\"ב.\u0006",["\u0003אלא בלחם כו'. \u0004כלומר בעיסה שראויה לבא לידי לחם דכתיב ראשית עריסותיכם וגו' והיה באכלכם מלחם הארץ וגו' וסתם לחם אינו אלא העשוי מקמח ומים וכה\"ג:","\u0003שבלילתה רכה כו'. \u0004דאילו בלילתה עבה בלא\"ה חייבת בחלה אלא אם כן גלגלה ע\"ד לבשלה כדבסעיף שאחר זה:","\u0003ובלבד שלא ע\"י משקה. \u0004כלומר שאפאה שלא ע\"י משקה דאילו טגנה במשקה פטורה:","\u0003פטורה. \u0004דכיון דגלגלה ע\"ד לבשלה לא חל עליה חובת חלה דבתר דעתו אזלינן מיהו הרבה פוסקים חולקים דהיכא דבלילתה עבה אפי' גלגלה ע\"ד לבשלה חייבת בחלה דמיד נתחייבה משעת גלגול כדאיתא בב\"י לכן יש להחמיר להפריש חלה בלא ברכה או לאפות מעט ממנה שע\"י כן תתחייב כולה בחלה וכדבסעיף שאחר זה וכמו שכתב הרא\"ש וטור ופוסקים בשם מהר\"ם ע\"ש:","\u0003ואפאו כו'. \u0004והב\"ח כתב דאפי' לא אפאו אלא לעולם כל שנמלך לאפות מקצתו בין לקחו ממנו ואפאו או לא מתחייב כולו על ידו ומסיק דלענין הלכה יש לדקדק דלכתחלה יפריש חלה ואחר כך יקח אותו מעט ויאפנו מיהו אם לקח תחלה אותו מעט ואפאו צריך גם כן להפריש אחר כך חלה מכל העיסה אלא שיניח אותה העיסה אפויה אצל העיסה ויפריש ממנו ומן העיסה כו' וע\"ש שהאריך ועיין בא\"ח סי' קס\"ח סי\"ב:","\u0003כולה מתחייבת כו'. \u0004דחכמים גזרו בדבר שמא ימלך ויאפה ממנו שיעור חלה וכתב הב\"ח דבהפרשתו חלה זו צריך לברך דאע\"ג שאינו אלא חששא דרבנן מ\"מ מברכים על ספק דדבריהם וע\"ש שהאריך ודלא כמהרש\"ל ומביאו בדרישה ע\"ש:","\u0003בחמה בלבד כו'. \u0004מסיק הב\"י דלישנא דבלבד אתי לאורויי לאפוקי היכא דהתחיל ליבשה בחמה וגמר לאפות כתקנה או איפכא דהוא ודאי לחם מיקרי:","\u0003שנלושה במים רותחים כו'. \u0004דאף על גב דחלטיה מעיקרא כיון דהדר אפיה בתנור בלא משקין לחם קרינן ביה:","\u0003חייבת כו'. \u0004והרא\"ש פוטר וכן הברטנורה מסתפק בדבר לכן יש להפריש בלא ברכה או אם יש לו עיסה שלא הורמה יניח עיסה זו שנלושה במי פירות אצל עיסה שלא הורמה חלתה ויפריש חלה מעיסה שלא הורמה חלתה גם על זו שנילושה במי פירות:","\u0003יש ליזהר מללוש במי פירות. \u0004או מי ביצים כל שאינו מז' משקין כו' דאע\"ג דפסק המחבר בסמוך דחייבת בחלה מכל מקום לא ידענו מה יעשה בחלתה דאע\"ג דכלנו עכשיו טמאי מת מכל מקום חלה זו טהורה דלא הוכשרה לקבל טומאה כיון שנלושה במי פירות שאין דבר מוכשר לקבל טומאה עד שיוכשר במשקה ומי פירות אינן נחשבין משקה להכשיר לקבל טומאה וא\"כ חלה זו טהורה היא ואסור לשרוף חלה טהורה ולאכלה גם כן אי אפשר כיון שהיא טהורה ואנו רובן טמאים וטמא אסור לאכול תרומה טהורה ויצטרך ליתנה לכהן קטן הלכך לכתחלה אסור ללוש רק כשיערב בהן א' מז' משקין כדי שיוכל לשרפה וכן הוא מבואר בסמ\"ק וב\"י וע' ברמב\"ם בה' טומאת אוכלין מהו הן הדברים שאין מכשירין לקבל טומאה שנלמד שבהן אסור ללוש:","\u0003אלא אם כן יערב. \u0004ונ\"ל שדוקא יערב בשעת לישה קודם שחל חיוב חלה אבל אחר שלש במי פירות ונתחייב בחלה אין לערב בו שאר משקין:","\u0003מה הם השבעה משקין. \u0004והם יין דבש שמן חלב טל דם מים וסימנך י\"ד שח\"ט ד\"ם:"],["\u0003ובלבד שלא על ידי משקה. \u0004פירוש אפילו בלא מים כי היכי דליהוי מעשה אפיה:","\u0003על דעת לבשלה. \u0004זה דעת הר\"ש והרא\"ש ורמב\"ם דלא כר\"ת דס\"ל אפילו היה בדעתו בשעת גלגול שאחר כך יבשלה מכל מקום כיון שבשעת גלגול היתה עבה חייבת אלא אזלינן בתר דעתו שהיה לו בשעת גלגול והיינו לפטור כגון שנתכוין לבשלה אבל להיפך לא אזלינן בתר דעתו כדאמרי' בסיפא גלגלה ע\"ד סופגנין כו' וכתב הרא\"ש בפרק כל שעה דמשום פלוגתא זו היה מנהג מהר\"ם לצוות לבני ביתו לאפות מעט מעיסה כזאת דהיינו שהיה בדעתו לבשלה כדי שע\"י זה יתחייב כל העיסה בחלה כמ\"ש בסמוך בסעיף שאחר זה:","\u0003אם דעתו לאפות כו'. \u0004זה הוכיח הר\"ש פ\"ק דחלה ממאי דאמרינן בכיצד מברכין לחם העשוי לכותח פטור וכמ\"ש בסמוך סעיף ז' דמעשיו מוכיחין עליו ובירושלמי אמרינן לחם העשוי לכותח חייב שמא נמלך לעשות ממנו חררה קטנה וע\"כ נ\"ל דההיא דכיצד מברכין נ\"ל דמיירי דשקלא פורתא ואפאה באור דחיישינן שמא מימלך ליקח כשיעור ומ\"ה נמי אמרינן בסעיף ז' עשעה כעבין חייב דהיינו מטעם דאתי לאחלופי בשאר עיסה:","\u0003ואפאו אפילו כו'. \u0004לכאורה משמע שלא פריש חלה מהעיסה הזאת עד אחר שאופה אותו מעט שנוטל ממנו וכ\"כ ב\"י וז\"ל נראה היינו דוקא כשאפה אותו מעט אבל אם לא אפה אותו משום שהיה בדעתו לאפותו לא מחייבה דאפי' בשאפאו לא מחייב אלא משום גזירה והבו דלא לוסיף עליה לחייבו משום שהיה בדעתו לאפות דבר מועט שאין בו שיעור חלה עכ\"ל. וע\"כ כתב כאן ואפאו כו' וכ\"כ במרדכי פרק כל שעה וז\"ל ושוב חזר הר\"ש ואמר כיון שדעתו לעשות סופגנין ולבשלה במים פטור אא\"כ עשתה ממנו חררה קטנה ואפאה ע\"ג גחלים דחיישינן שמא תימלך ותעשה ממנה חררה לבנה כדי חיוב אמרתי לאפוקי נפשי מפלוגתא לעשות חררה קטנה ולאפותה וליטול חלה ממנה ומן העיסה ביחד דנוטלין חלה מן האפוי על העיסה ומן העיסה על האפוי עכ\"ל אלא דבאשר\"י פרק כל שעה כתב בלשון זה ור\"ש היה נוהג כשלשין עיסה בביתו כדי לבשלה במים היה מצוה לאפות ממנה מעט ועל ידי כך נתחייבה העיסה בחלה קודם שיקח ממנה מעט דחיישינן שמא תימלך עכ\"ל ש\"מ שהפרשת חלה בזה תהיה קודם שיקח ממנה אותו מעט לאפות ומטעם זה השיג מו\"ח ז\"ל על הב\"י שכתב כאן לדעת הטור דדוקא בעינן שאפאו ולא סגי בדעתו לאפות וכ\"פ כאן בש\"ע דלא כן הוא לדעת הרא\"ש שחולק עם המרדכי ואני אומר לפי הבנתו של מו\"ח ז\"ל ודאי יש לתמוה על הב\"י יותר שהרי בקיצור פסקי הרא\"ש שחבר הטור כתב בהדיא מיהו אם דעתו לאפות ממנה חררה קטנה נתחייבה בחלה עכ\"ל הרי בהדיא דבדעתו סגי אלא שאני אומר דלכאורה יש לתמוה על הרא\"ש והטור בזה שאמרו דסגי בדעתו לאפותו והלא הם רוצים לצאת גם דעת הר\"ש שהיא עיקר להלכה והר\"ש כתב בהדיא בריש חלה כמה פעמים דמיירי בכבר אפה לההיא פורתא ע\"ש אלא נ\"ל דאין כאן חילוק דעות כלל דודאי אם נתכוין בשעת גלגול העיסה לבשלה במים ולאפות קצת ממנה נתחייבה כולה תכף וזה מבואר בלשון הרא\"ש שכתב שהר\"מ היה מצוה לאפות מעט כשלשו העיסה וע\"כ נתחייבה תכף ובדרך זה הוא גם כן דעת הטור והטעם שבשעת גלגול הוה החשש תכף שמא תמלך ליקח ממנה כשיעור חלה והמרדכי איירי שבשעת לישה וגלגול נתכוונה לבשלה כולה במים אלא דאח\"כ נוטלת ממנה מעט לאפות לא סגי בזה עד שתהיה אפויה ממש אע\"ג דבנמלך לעשותה לחם חייבת בחלה תכף אחר ההמלכה כמשמעות סוף סעיף ג' שהוא לשון המשנה היינו בנמלכה לעשותה מכולה לחם משא\"כ כאן שכולה תשאר לבישול במים רק שקצת תטול לאפייה ועיקר החיוב בעיסה כולה משום גזירה שמא תמלך לא סגי בזה שתתחייב תכף אחר שהפרישה קצת לאפייה דאין בזה היכר כ\"כ כיון דשאר העיסה תתבשל אלא בעינן שתאפה אותה המעט ומזה מיירי הב\"י וכן בש\"ע דבעינן אפייה דוקא ודברי הב\"י מכוונים לזה שהרי כתב דבריו על דברי הטור והטור כתב בלשון זה וכן היה מנהג הר\"ם בביתו כשהיו עושין עיסה כדי לבשלה במים לאפות ממנה מעט וע\"י כן נתחייבה בחלה כולה עכ\"ל לשון זה משמע שהיה נוהג לאפות באמת תחלה ועל ידי זה נתחייבה העיסה שהרי לא כתב שהיה מצוה לאפות דאלו היה כותב כן היה המשמעות שע\"י הצווי לאפות נתחייבה אע\"פ שלא נאפה עדיין אלא כתב שהר\"ם נהג לאפות כו' דמשמע שבאמת אפאוה תחלה והיינו בדרך שכתבתי דתרי מילי היו במהר\"ם דכשהיה מצוה לאפות סגי בכך ונתחייבה תכף וכדברי הרא\"ש אבל אם לא היה מצוה ממילא בשעת גלגול היה במחשבה לבשל כולה במים ואחר כך הפריש מעט בזה היה אופה באמת וכן הוא פסק הש\"ע כאן וכן הוא נכון לפענ\"ד בחילוק זה:\n\u0003אלא \u0004דק\"ל למה ליה למהר\"ם לתיקון באפיית מקצת הא בלאו הכי נתחייבת בחלה דהא כתבו הרב רבינו שמשון בריש חלה והרא\"ש בפ' כל שעה דיש ראיה מפרק כיצד מברכין דאם נתכוין לבשל העיסה במים פטור מדאמרי' שם לחם העשוי לכותח פטור מחלה והתניא חייב ומשני התם כדתני טעמא מעשיה מוכיחים עליה עשאה כעבין חייב כלימודין פטור ופירש\"י לחם העשוי לכותח אין אופין אותו בתנור אלא מייבשין אותו בחמה אלמא אע\"ג דמשעת גלגול אתי חיוב חלה כיון דגלגלו אדעתא לאפותו בחמה מפטר משום דסופו לבטלו מתורת לחם והא דמפליג בין עבין ללימודין משום דבעבין מיחלפא בשאר עיסה שאינה עשויה לכותח אבל לימודין מעשיה מוכיחים עליה ולא אתי לאחלופי מחמת שעשויה לכותח ובירושל' גרסינן עיסת כותח חייב בחלה שמא תמלך ותעשה חררה לבנה וכדי שלא יקשה ההיא דירושלמי לגבי דילן י\"ל ההיא דירושלמי כגון שנטלה מהעיסה מעט לאפותה באור דחיישינן שמא תמלך ותעשה חררה לבנה והיינו נמי דמפליג בגמרא דידן בין כעבין ללימודין דבעבין אתי למימלך אבל לימודין לאו אורחיה למימלך עכ\"ל ולכאורה קשה למה מוקי לההיא דירושלמי דעיסת כותח חייב דוקא בנטלה מהעיסה קצת כו' ובגמ' דידן יש חיוב זה אפי' בלא נטל ממנה כשהוא כעבין משום דאתי לאחלופי ומשמעות דברי הרא\"ש דשני הגמרות שוין הם אלא פשוט דגמרא ירושל' מיירי אפי עשאה כלימודין דחייב משום שמא תמלך אע\"ג דלאו אורחיה מ\"מ חיישינן והיינו כשדעתה לאפות קצת ממנה משא\"כ גמרא שלנו דלא מיירי במפריש קצת מהעיסה מ\"ה אין חשש שמא תמלך אלא בעבין שאז דרכה למימלך וא\"כ קשה בעיסה דמהר\"ם שעשאו בביתו כדי לבשל במים או לטגן בשמן ודאי היו עושים עיסה כדרך כל הארץ וא\"כ יש חשש שמא תמלך לאפותה והוי כההיא דעיסת כותח לכעבין דחייבת בחלה אפי' בלא אופה מקצת ממנה ונ\"ל דכשעשו עיסה לבשל במים מסתמא עשו בה תבלין או מי ביצים שלא כדרך עיסה לאפות אלא בענין אחר מ\"ה אין חשש אלא בנטל קצת ממנה לאפות והוי כההיא דירושל' כנ\"ל בזה:","\u0003כולה מתחייבת על ידו. \u0004בדרישה הביא בשם רש\"ל שכתב על דברי הרא\"ש הלשון משמע שהיה מברך עליה משום חלה דאל\"כ למה היה מצוה לאפות מעט בלא אפיה יקח חלה בלא ברכה או יעשה בלא חלה אם לא ס\"ל כר\"ת וא\"כ תימא והלא הוא גופיה כתב דלא נתחייב בחלה אלא דחיישי' שמא ימלך כו' וא\"כ בע\"כ דלא מברכין ונ\"ל דכוונת הר\"ם לא היה אלא כדי שיפריש חלה וס\"ל דאסור להפריש חלה בכדי דעובר על בל תשחית לדידן שכולה נשרפת משום הכי היה מצווה בו כדי למצוא שיתחייב בחלה ומה שלא היה מצווה לעשות בלא חלה אפשר משום כבודו של ר\"ת שפסק שחייב בחלה עכ\"ל ואני תמהתי ע\"ז דהא בלחם העשוי לכותח אמרינן בגמ' בהדיא דחייב כשהוא כעבין וכמ\"ש בסעיף ז' וסתם חייב הוא כדינו להפריש בברכה והא התם ג\"כ הטעם משום גזירה שמא תמלך וכמ\"ש בסמוך בשם הר\"ש והרא\"ש ותו דהלא תלמוד ערוך הוא בפרק במה מדליקין (שבת דף כ\"ג) דרבא ס\"ל אפילו ספק דבריהם בעי ברכה והיינו י\"ט שני שהוא ג\"כ משום מנהג וגזירה כדאיתא פ\"ק דביצה רק בדמאי אין צריך ברכה כיון שרוב ע\"ה מעשרין הן וא\"כ ה\"נ כן הוא ועוד ראיה מעיסה של ישראל ושל עובד כוכבים בסימן ש\"ל דחייבת מטעם גזירה כמ\"ש ופשוט שחייב בברכה וכן בכ\"מ שאמרו חכמים חייב סתם בגמרא ולא זכרו חילוק חייב בברכה מ\"ה לא כתב הטור שרבינו שמשון לא היה מברך על חלה כזה מספק אלא דוקא לענין המוציא שזה היה ספק של הר\"ש בפירוש דברי הגמרא וכ\"כ מהרי\"ל בהלכות פסח בהדיא בב' עיסות שהיו נילושים לעשות מהן טיגון בלא הפרשת חלה כו' שציוה להפריש מהם מעט לאפות ולהפריש אחר כך חלה בברכה וכן מסיק מו\"ח ז\"ל דודאי בעינן ברכה והביא ראיה לדבר מתשובת הרשב\"א:","\u0003לחם העשוי לכותח. \u0004כבר נתבאר בסמוך הטעם דכל שהוא כעבין יש בו חשש שמא ימלך לאפות ממנו כשיעור חלה והאי חיוב פשוט הוא דחייב לברך עליה ככל סתם חיוב בגמרא וכמ\"ש בסמוך:","\u0003במי פירות. \u0004שאינם משבעה משקין פירוש כגון מי בצים שהם אינם מכשירים את המאכל לקבל טומאה ואם ילוש שיעור אלה מה יעשה מחלתה לשרפה אינו יכול כיון שהיא טהורה ואין שורפין קדשים טהורים ולאכלה אינו יכול דרובן בחזקת טמאי מתים ומיהו יכול ליתנה לכהן קטן שלא ראה קרי כדאיתא בבכורות כ\"כ סמ\"ק ע\"כ יערב עמהם א' משבעה משקים סימנם י\"ד שח\"ט ד\"ם ואז יהיה מוכשר לקבל טומאה:"]],["עִסַת עוֹבֵד כּוֹכָבִים \u0010y0\u0011 \u0010c0\u0011 פְּטוּרָה, אֲפִלּוּ לָשָׁהּ יִשְׂרָאֵל. וְשֶׁל יִשְׂרָאֵל, \u0010y1\u0011 חַיֶּבֶת, אֲפִלּוּ לָשָׁהּ לוֹ עוֹבֵד כּוֹכָבִים. נְתָנָהּ לְיִשְׂרָאֵל בְּמַתָּנָה, אִם עַד שֶׁלֹּא גִּלְגְּלָהּ נִתְּנָה לוֹ, חַיֶּבֶת. וְאִם לְאַחַר שֶׁגִּלְגְּלָהּ נְתָנָהּ לוֹ, פְּטוּרָה. \u0005עוֹבֵד כּוֹכָבִים שֶׁהִפְרִישׁ חַלָּה, \u0010y2\u0011 אֵינוֹ כְּלוּם, וְתֵאָכֵל לְזָר (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006. \u0010y3\u0011\nעִסַת הַשֻּׁתָּפִין חַיֶּבֶת.\nיִשְׂרָאֵל \u0010y4\u0011 שֶׁהוּא שֻׁתָּף עִם הָעוֹבֵד כּוֹכָבִים, אִם אֵין בְּחֵלֶק הַיִּשְׂרָאֵל כַּשִּׁעוּר, פְּטוּרָה. \u0010y5\u0011 וְאִם יֵשׁ בָּהּ \u0010y6\u0011 כַּשִּׁעוּר, חַיֶּבֶת, וְיָכוֹל \u0010c1\u0011 לְהַפְרִישׁ מִנֵּיהּ וּבֵיהּ.\nעוֹבֵד כּוֹכָבִים שֶׁהָיְתָה לוֹ עִסָה, וְנִתְגַּיֵּר. גִּלְגְּלָהּ קֹדֶם שֶׁנִּתְגַּיֵּר, פָּטוּר. אַחַר \u0010y7\u0011 \u0010c2\u0011 שֶׁנִּתְגַּיֵּר, חַיָּב. אִם סָפֵק, חַיָּב.\nשְׁנֵי עוֹבְדֵי כּוֹכָבִים שֶׁעָשׂוּ עִסָה כַּשִּׁעוּר וְחִלְּקוּהָ, וְאַחַר כָּךְ נִתְגַּיְּרוּ, וְהוֹסִיף כָּל אֶחָד עַל חֶלְקוֹ אַחַר שֶׁנִּתְגַּיֵּר עַד שֶׁהִשְׁלִימוֹ \u0010c3\u0011 לְכַשִּׁעוּר, הֲרֵי זוֹ חַיֶּבֶת.\nהָיְתָה הָעִסָה בֵּין עוֹבֵד כּוֹכָבִים וְיִשְׂרָאֵל בְּשֻׁתָּפוּת, וְחָלְקוּ וְאַחַר כָּךְ נִתְגַּיֵּר וְהוֹסִיף כָּל אֶחָד עַל שֶׁלּוֹ עַד שֶׁהִשְׁלִים וְהוֹסִיף \u0010c4\u0011 לְכַשִּׁעוּר, שֶׁל יִשְׂרָאֵל \u0010y8\u0011 חַיֶּבֶת, וְשֶׁל עוֹבֵד כּוֹכָבִים פְּטוּרָה. \u0005הַגָּה: וְדַוְקָא שֶׁעֲשָׂאוּהָ מִתְּחִלָּה בְּשֻׁתָּפוּת עַל מְנַת שֶׁלֹּא לְחַלְּקוֹ, וְנִמְלְכוּ לְחַלְּקָהּ אַחַר כָּךְ, אֲבָל אִם עֲשָׂאוּהָ מִתְּחִלָּה עַל מְנַת לְחַלְּקָהּ, אַף שֶׁל עוֹבֵד כּוֹכָבִים חַיֶּבֶת.\u0006\nהִפְקִיר עִסָתוֹ קֹדֶם שֶׁנִּתְגַּלְגְּלָה, וְזָכָה בָּהּ וְאַחַר כָּךְ גִּלְגְּלָהּ, אוֹ הִפְקִירָהּ אַחַר שֶׁגִּלְגְּלָהּ וְחָזַר וְזָכָה בָּהּ, חַיֶּבֶת. הִפְקִירָהּ וְנִתְגַּלְגְּלָה בְּעוֹדָהּ הֶפְקֵר, וְאַחַר כָּךְ זָכָה בָּהּ, פְּטוּרָה.\nהָעוֹשֶׂה עִסָה לִבְהֵמָה וּלְחַיָּה, פָּטוּר.\nעִסַת הַכְּלָבִים, בִּזְמַן שֶׁהָרוֹעִים אוֹכְלִים מִמֶּנָּהּ, חַיֶּבֶת. וְאִם לָאו, פְּטוּרָה. וְדַוְקָא שֶׁנִּכָּר בָּהּ שֶׁהִיא לִכְלָבִים, כְּגוֹן שֶׁאֵינָהּ עֲרוּכָה וַעֲשׂוּיָה כְּצוּרַת לֶחֶם, הָא לָאו הָכִי חַיֶּבֶת.",["\u0003עיסת עובד כוכבים פטורה. \u0004דכתיב עריסותיכם ולא של עובד כוכבים וכתב הדרישה ובמקומות שהנשים קונות בצק מאופה עובד כוכבים ולוקחים ממנה חלה נראה דאסור כו' אם לא שנאמר שיש לסמוך על זה הואיל ומדאורייתא מעות קונות והם נותנין המעות קודם הגלגול עי\"ל כיון דדרכן כך אפשר בלא נתינת מעות קודם לכן מותר כיון דהעובד כוכבים יודע מנהג ישראל ואדעתא דהכי לש מתחלה ודינו כאילו נתנו לישראל במתנה קודם שגלגלו ע\"כ ובתשובת משאת בנימין סוף סימן א' כתב דלאו שפיר עבד ויש לבטל המנהג עיין שם:","\u0003אפילו לשה. \u0004דלא אזלינן בתר המגלגל לא לחיוב ולא לפטור רק מי שהיתה העיסה שלו בשעת גלגול:","\u0003אינו כלום. \u0004ומודיעין אותו שאינו צריך. רמב\"ם והטעם שלא יחשוב העובד כוכבים שהזר אוכל חלה וע\"ל סימן שכ\"א סק\"ב:","\u0003עיסת השותפים כו'. \u0004ע\"ל סימן שכ\"ו ס\"ק א':","\u0003שהוא שותף כו'. \u0004דוקא בשיש לה שותפות אבל עיסת ארנונית חייבת בחלה אע\"ג דלא מצי מסלק ליה בזוזי אפי' אין בו שיעור חלה בשל ישראל דשמא ימלוך העובד כוכבים שלא ליטלה. כן פסק הב\"ח:","\u0003ואם יש בה כשיעור חייבת. \u0004ומשמע דביש בה שיעור לעולם חייבת אפילו העובד כוכבים עומד עליו ומפורסם שיד העובד כוכבים באמצע ואפילו קנו הקמח ביחד וכ\"פ הב\"ח עיין שם:","\u0003ויכול להפריש מיניה וביה. \u0004כדלעיל סימן שכ\"ד סעיף י\"א ועיין מה שכתבתי שם.","\u0003אם ספק חייב. \u0004היינו משום דספק איסורא לחומרא וצ\"ל דהיינו דוקא מדינא אבל האידנא דכל חלה היא מדרבנן כדלעיל סימן שכ\"ב אם כן פטור מספק וצ\"ע למה כתבו האחרונים בסתם דין זה. ועל כל פנים נראה דהיכא דאיכא ספק בדבר בחלה כיון דבזמן הזה דהוה דרבנן יש להפרישה בלא ברכה:","חייבת. אף על גב דשני ישראלים שעשו שני קבים ביחד וחלקוה ואחר כן הוסיף כל אחד שלו והשלימו לכשיעור אמרינן לעיל סימן שכו ס\"ד דפטורים שאני התם שכבר היה לעיסה זו שעת חובה קודם חלוקה אלא שהיתה פטורה משום שהיה דעתם לחלם והוי זו העיסה כאלו הורמה ממנה חלתה ושוב לא תחזור לחיובה אבל הכא לא היה לזו העיסה שעת חובה לעולם בין קודם חלוקה בין אחר חלוקה הלכך עכשיו כשיושלם שיעורו חל עליו חיוב הרמת חלה וחייב להפריש חלה:"],["\u0003עיסת עובד כוכבים פטורה. \u0004דכתיב ראשית עריסותיכם:","\u0003להפריש מיניה וביה. \u0004דיש בילה בדבר לח ובשיעור חלה שיפריש א\"א שלא יהיה בו משל ישראל והחלה אין לה שיעור מן התורה. עד כאן לשון הרא\"ש:","\u0003אם ספק חייב. \u0004כתב רש\"ל דוקא בחלת ארץ ישראל שהיא דאורייתא וספיקא לחומרא אבל חלת ח\"ל שהיא דרבנן לא:","\u0003הרי זו חייבת. \u0004אין שייך לומר בה שהיא שעת חובה ונפטר שהרי לא בא החיוב עד אחר שנתגייר:","\u0003של ישראל חייבת. \u0004לפי שעיסה של ישראל כשהיתה מחוברת בחלקו של עובד כוכבים לא בא לידי חיוב מעולם עד שמוסיף אחר כן וע\"כ חייב כשמוסיף מה שאין כן חלק של עובד כוכבים שהיה מחובר לחלק ישראל שהוא בר חיוב והוה כאלו לש העובד כוכבים שיעור חלה אלא שעיקר מפני שהוא עובד כוכבים בשעת החיוב שוב אינו מועיל שום דבר להתחייב:"]],["\u0003הלכות תרומות ומעשרות ומתנות עניים וראשית הגז\u0004\nהַתְּרוּמוֹת וּמַעַשְׂרוֹת \u0010y0\u0011 אֵינָם נוֹהֲגִים מִן הַתּוֹרָה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל, בֵּין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת, וּנְבִיאִים הִתְקִינוּ שֶׁיִּהְיוּ נוֹהֲגִים אֲפִלּוּ בְּאֶרֶץ שִׁנְעָר, מִפְּנֵי שֶׁהִיא סְמוּכָה לְאֶרֶץ יִשְׂרָאֵל, וְרֹב יִשְׂרָאֵל הוֹלְכִים וְשָׁבִים שָׁם. וַחֲכָמִים הָרִאשׁוֹנִים הִתְקִינוּ שֶׁיִּהְיוּ נוֹהֲגִים אַף בְּאֶרֶץ מִצְרַיִם וּבְאֶרֶץ עַמּוֹן וּמוֹאָב, מִפְּנֵי שֶׁהֵם סְבִיבוֹת לְאֶרֶץ יִשְׂרָאֵל. \u0010y1\u0011 סוּרְיָא, הַקּוֹנֶה בָּהּ שָׂדֶה חַיֶּבֶת בִּתְרוּמוֹת וּמַעַשְׂרוֹת מִדִּבְרֵי סוֹפְרִים. וּשְׁאָר הָאֲרָצוֹת, אֵין תְּרוּמוֹת וּמַעַשְׂרוֹת נוֹהֲגוֹת בָּהֶן.\nבַּזְּמַן הַזֶּה, אֲפִלּוּ בְּמָקוֹם שֶׁהֶחֱזִיקוּ בּוֹ עוֹלֵי בָּבֶל, וַאֲפִלּוּ בִּימֵי עֶזְרָא, \u0010y2\u0011 אֵין חִיּוּב תְּרוּמוֹת וּמַעַשְׂרוֹת מִן הַתּוֹרָה, אֶלָּא מִדִּבְרֵיהֶם. מִפְּנֵי שֶׁנֶּאֱמַר: כִּי תָבֹאוּ, מַשְׁמָע בִּיאַת כֻּלְּכֶם וְלֹא בִּיאַת מִקְּצָתָן, כְּמוֹ שֶׁהָיְתָה בִּימֵי עֶזְרָא. \u0005הַגָּה: \u0010y3\u0011 \u0010c0\u0011 וְיֵשׁ חוֹלְקִין, וּסְבִירָא לְהוּ דְּחַיָּבִין עַכְשָׁו בְּאֶרֶץ יִשְׂרָאֵל בִּתְרוּמוֹת וּמַעַשְׂרוֹת מִדְּאוֹרַיְתָא, אַךְ לֹא נָהֲגוּ כֵּן (טוּר בְּשֵׁם ר\"י)\u0006.\nעוֹבֵד כּוֹכָבִים שֶׁקָּנָה קַרְקַע בְּאֶרֶץ יִשְׂרָאֵל, וְחָזַר יִשְׂרָאֵל וּלְקָחָהּ מִמֶּנּוּ, \u0010y4\u0011 מַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת. \u0010y5\u0011 מַה שֶּׁאֵין כֵּן בְּסוּרְיָא.\nפֵּרוֹת הָעוֹבֵד כּוֹכָבִים שֶׁגָּדְלוּ בְּקַרְקַע שֶׁקָּנָה בְּאֶרֶץ יִשְׂרָאֵל, אִם נִגְמְרָה מְלַאכְתָּן בְּיַד הָעוֹבֵד כּוֹכָבִים, וּמֵרְחָן הָעוֹבֵד כּוֹכָבִים, \u0010y6\u0011 פְּטוּרִין מִכֻּלָּם. וְאִם לְקָחָן יִשְׂרָאֵל אַחַר שֶׁנִּתְלְשׁוּ, קֹדֶם שֶׁתִּגָּמֵר מְלַאכְתָּן, וּגְמָרָן יִשְׂרָאֵל, \u0010y7\u0011 חַיָּבִים וּמַפְרִישׁ תְּרוּמָה וּמַעֲשֵׂר רִאשׁוֹן \u0010y8\u0011 וּתְרוּמַת מַעֲשֵׂר, וּמְשַׁיֵּר לְעַצְמוֹ מַעֲשֵׂר רִאשׁוֹן, וְהוּא שֶׁלּוֹ, \u0010y9\u0011 מִפְּנֵי שֶׁהוּא אוֹמֵר לַלֵּוִי: אֲנִי בָּאתִי מִכֹּחַ אִישׁ \u0010c1\u0011 שֶׁאֵין אַתָּה יָכוֹל לִטֹּל מִמֶּנּוּ. \u0005וְהַתְּרוּמַת מַעֲשֵׂר מוֹכֵר לַכֹּהֵן וְנוֹטֵל דָּמֶיהָ (טוּר)\u0006.\nמָכַר הָעוֹבֵד כּוֹכָבִים הַפֵּרוֹת שֶׁלּוֹ לְיִשְׂרָאֵל כְּשֶׁהֵן מְחֻבָּרִים לַקַּרְקַע, אִם עַד שֶׁלֹּא בָּאוּ \u0010y10\u0011 לְעוֹנַת הַמַּעַשְׂרוֹת, וְנִגְמְרוּ בְּיַד יִשְׂרָאֵל, \u0010y11\u0011 חַיָּב בַּכֹּל וְנוֹתֵן \u0010c2\u0011 כָּל מַעֲשֵׂר רִאשׁוֹן לַלֵּוִי. וְאִם מְכָרָן אַחַר שֶׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, מַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת וְנוֹתֵן הַמַּעֲשֵׂר לַלֵּוִי לְפִי חֶשְׁבּוֹן. כֵּיצַד, לָקַח תְּבוּאָה זְרוּעָה מִעוֹבֵד כּוֹכָבִים אַחַר שֶׁהֵבִיאָה שְׁלִישׁ, וְנִגְמְרָה בְּיַד יִשְׂרָאֵל, מַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת \u0010y12\u0011 וְנוֹתֵן לַלֵּוִי \u0010c3\u0011 שְׁנֵי שְׁלִישֵׁי הַמַּעֲשֵׂר רִאשׁוֹן.\nיִשְׂרָאֵל שֶׁמָּכַר פֵּרוֹתָיו לְעוֹבֵד כּוֹכָבִים קֹדֶם שֶׁיָּבוֹאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, וּגְמָרָן הָעוֹבֵד כּוֹכָבִים, \u0010y13\u0011 פְּטוּרִין מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת. וְאִם אַחַר שֶׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, \u0010y14\u0011 אַף עַל פִּי שֶׁגְּמָרָן הָעוֹבֵד כּוֹכָבִים, חַיָּב בַּכֹּל.\nמָכַר עוֹבֵד כּוֹכָבִים לְיִשְׂרָאֵל פֵּרוֹת מְחֻבָּרִים, אַחַר שֶׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, וּמֵרְחָן הָעוֹבֵד כּוֹכָבִים בִּרְשׁוּת יִשְׂרָאֵל, אֵינָם חַיָּבִים בִּתְרוּמָה וּמַעַשְׂרוֹת, הוֹאִיל וּבָאוּ לְעוֹנַת הַמַּעַשְׂרוֹת בִּרְשׁוּת עוֹבֵד כּוֹכָבִים וּמֵרְחָן הָעוֹבֵד כּוֹכָבִים, אַף עַל פִּי שֶׁהֵם בִּרְשׁוּת יִשְׂרָאֵל. \u0010y15\u0011 הַקּוֹנֶה פֵּרוֹת מֵעוֹבֵד כּוֹכָבִים בְּסוּרְיָא, בֵּין תְּלוּשִׁים בֵּין מְחֻבָּרִים, אֲפִלּוּ קֹדֶם שֶׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, אַף עַל פִּי שֶׁמֵּרְחָן יִשְׂרָאֵל, פְּטוּרִים. \u0010y16\u0011 וְאִם עֲדַיִן לֹא הִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת, הוֹאִיל וְקָנָה אוֹתָם עִם הַקַּרְקַע, חַיָּב לְעַשֵּׂר.\nיִשְׂרָאֵל שֶׁהָיָה אָרִיס לְעוֹבֵד כּוֹכָבִים בְּסוּרְיָא, פֵּרוֹתָיו פְּטוּרִים, \u0010y17\u0011 לְפִי שֶׁאֵין לוֹ בְּגוּף הַקַּרְקַע כְּלוּם. וְכֵן הַחוֹכֵר וְהַמְקַבֵּל וְהַשּׂוֹכֵר שָׂדֶה מֵהָעוֹבֵד כּוֹכָבִים בְּסוּרְיָא, פֵּרוֹתָיו פְּטוּרִין.\nיִשְׂרָאֵל שֶׁלָּקַח בְּסוּרְיָא שָׂדֶה מֵהָעוֹבֵד כּוֹכָבִים עַד שֶׁלֹּא הֵבִיאָה שְׁלִישׁ, וְחָזַר וּמְכָרָהּ לְעוֹבֵד כּוֹכָבִים אַחַר שֶׁהֵבִיאָה שְׁלִישׁ, אִם חָזַר יִשְׂרָאֵל וּלְקָחָהּ פַּעַם שְׁנִיָּה, חַיָּב, שֶׁהֲרֵי נִתְחַיֵּב בְּיַד יִשְׂרָאֵל.\nיִשְׂרָאֵל שֶׁהָיָה לוֹ קַרְקַע בְּסוּרְיָא, וְהוֹרִיד לָהּ אָרִיס וְשָׁלַח לוֹ הָאָרִיס פֵּרוֹת, הֲרֵי אֵלּוּ פְּטוּרִים, שֶׁאֲנִי אוֹמֵר: מֵהַשּׁוּק לְקָחָן; וְהוּא שֶׁיִּהְיֶה אוֹתוֹ הַמִּין מָצוּי בַּשּׁוּק. \u0010y18\u0011\nשֻׁתָּפוּת הָעוֹבֵד כּוֹכָבִים חַיֶּבֶת בִּתְרוּמָה וּמַעַשְׂרוֹת. כֵּיצַד, יִשְׂרָאֵל וְעוֹבֵד כּוֹכָבִים שֶׁלָּקְחוּ שָׂדֶה בְּשֻׁתָּפוּת, אֲפִלּוּ חִלְּקוּ שָׂדֶה בְּקָמָתָהּ, וְאֵין צָרִיךְ לוֹמַר אִם חִלְּקוּ גָּדִישׁ, הֲרֵי טֶבֶל וְחֻלִּין מְעֹרָבִים בְּכָל קֶלַח וְקֶלַח מֵחֶלְקוֹ שֶׁל עוֹבֵד כּוֹכָבִים, אַף עַל פִּי שֶׁמֵּרְחָן הָעוֹבֵד כּוֹכָבִים, וְחַיָּבִים מִדִּבְרֵיהֶם. בַּמֶּה דְבָרִים אֲמוּרִים, בְּאֶרֶץ יִשְׂרָאֵל, שֶׁהַמַּעַשְׂרוֹת שֶׁל תּוֹרָה, וּבְשֶׁל תּוֹרָה אֵין בְּרֵירָה. אֲבָל אִם לָקְחוּ שָׂדֶה בְּסוּרְיָא, הוֹאִיל וְהַמַּעַשְׂרוֹת שָׁם מִדִּבְרֵיהֶם, אֲפִלּוּ חִלְּקוּ הַגָּדִישׁ, חֶלְקוֹ שֶׁל עוֹבֵד כּוֹכָבִים פָּטוּר מִכְּלוּם. וְנִרְאֶה לִי דְּהָאִדָּנָא שֶׁאֵין חִיּוּב תְּרוּמוֹת וּמַעַשְׂרוֹת בְּאֶרֶץ יִשְׂרָאֵל, אֶלָּא מִדִּבְרֵיהֶם, גַּם בְּאֶרֶץ יִשְׂרָאֵל חֶלְקוֹ שֶׁל עוֹבֵד כּוֹכָבִים פָּטוּר מִכְּלוּם.\nפֵּרוֹת אֶרֶץ יִשְׂרָאֵל שֶׁיָּצְאוּ חוּצָה לָאָרֶץ, \u0010y19\u0011 פְּטוּרִים מִתְּרוּמוֹת וּמַעַשְׂרוֹת. וְאִם יָצְאוּ לְסוּרְיָא, \u0010y20\u0011 חַיָּבִים. וּפֵרוֹת חוּצָה לָאָרֶץ שֶׁנִּכְנְסוּ לָאָרֶץ, \u0010y21\u0011 חַיָּבִים, אִם נִקְבְּעוּ לְמַעֲשֵׁר \u0005(בְּיָד יִשְׂרָאֵל)\u0006 אַחֵר שֶׁנִּכְנְסוּ לְאֶרֶץ. \u0010y22\u0011\nכָּל אֹכֶל אָדָם, הַנִּשְׁמָר, שֶׁגִּדּוּלָיו מִן הָאֶרֶץ, \u0010c4\u0011 חַיָּב בִּתְרוּמָה.\nאֵין מַפְרִישִׁין תְּרוּמוֹת וּמַעַשְׂרוֹת \u0010y23\u0011 \u0010c5\u0011 מֵהַיָּרָק בְּחוּץ לָאָרֶץ, אֲפִלּוּ בִּמְקוֹמוֹת שֶׁאָמַרְנוּ שֶׁחִיְּבוּם חֲכָמִים. וְכֵן יָרָק הַבָּא מֵחוּצָה לָאָרֶץ לָאָרֶץ, אַף עַל פִּי שֶׁיֵּשׁ עָפָר בְּעִקְּרֵיהֶן, הֲרֵי זֶה פָּטוּר.\nהַתְּבוּאָה וְהַזֵּיתִים שֶׁלֹּא הֵבִיאוּ שְׁלִישׁ, \u0010y24\u0011 פְּטוּרִים מִתְּרוּמָה וּמַעַשְׂרוֹת. וּמִנַּיִן יוֹדֵעַ, כָּל שֶׁזּוֹרְעָהּ וּמַצְמַחַת, בְּיָדוּעַ שֶׁהֵבִיאָה שְׁלִישׁ. \u0010y25\u0011\nהַהֶפְקֵר פָּטוּר מִתְּרוּמָה וּמַעַשְׂרוֹת. אֲבָל הַזּוֹרֵעַ שְׂדֵה הֶפְקֵר, \u0010y26\u0011 חַיָּב בִּתְרוּמָה וּמַעַשְׂרוֹת.\nדְּבָרִים שֶׁאֵין דֶּרֶךְ רֹב בְּנֵי אָדָם לְזָרְעָם בַּגַּנּוֹת וּבַשָּׂדוֹת, אֶלָּא חֶזְקָתָן מִן הַהֶפְקֵר, פְּטוּרִין מִתְּרוּמָה וּמַעַשְׂרוֹת.\nנִתְעָרְבוּ פֵּרוֹת הַחַיָּבִים בִּתְרוּמָה וּמַעֲשֵׂר בְּפֵרוֹת הַפְּטוּרִים, \u0010y27\u0011 אִם יֵשׁ לוֹ פֵּרוֹת אֲחֵרִים הַחַיָּבִים, מוֹצִיא מֵהֶם, לְפִי חֶשְׁבּוֹן פֵּרוֹת חַיָּבִים שֶׁבַּתַּעֲרוֹבוֹת. \u0010y28\u0011 וְאִם לָאו, מוֹצִיא \u0010c6\u0011 תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר עַל הַכֹּל, וּמַפְרִישׁ מַעֲשֵׁר רִאשׁוֹן וְשֵׁנִי, לְפִי חֶשְׁבּוֹן פֵּרוֹת חַיָּבִים שֶׁבַּתַּעֲרוֹבוֹת. \u0010y29\u0011\nתְּרוּמָה גְּדוֹלָה, בַּזְּמַן הַזֶּה שֶׁהִיא עוֹמֶדֶת לִשְׂרֵפָה מִפְּנֵי הַטֻּמְאָה, שִׁעוּרָהּ כָּל שֶׁהוּא. \u0005הַגָּה: וְנוֹתְנָה בַּזְּמַן הַזֶּה לְכָל כֹּהֵן שֶׁיִּרְצֶה, בֵּין חָבֵר בֵּין עַם הָאָרֶץ, וַאֲפִלּוּ אֵינוֹ מְיֻחָס רַק שֶׁמֻּחְזָק בְּכֹהֵן, וְהוּא שׂוֹרְפָהּ, \u0010y30\u0011 \u0010c7\u0011 וְיָכוֹל לְהַנִּיחָהּ וּלְשָׂרְפָהּ, עַד שֶׁיָּכוֹל לֵהָנוֹת מִמֶּנָּהּ בִּשְׁעַת שְׂרֵפָתָהּ. אֲבָל זָר אָסוּר לֵהָנוֹת מִמֶּנָּהּ בִּשְׁעַת שְׂרֵפָתָהּ, אִם לֹא שֶׁכֹּהֵן נֶהֱנֶה עִמּוֹ. אֲבָל שְׁאָר הֲנָאוֹת שֶׁאֵינוֹ מְכַלֶּה אוֹתָהּ, מֻתֶּרֶת אֲפִלּוּ לְזָרִים (טוּר)\u0006. כֹּהֵן שֶׁאוֹכֵל אֵצֶל יִשְׂרָאֵל, \u0010y31\u0011 נוֹתֵן בַּנֵּר שֶׁמֶן שֶׁל תְּרוּמָה, וְאַף עַל פִּי שֶׁעוֹמֵד הַכֹּהֵן וְהוֹלֵךְ לוֹ, \u0010y32\u0011 אֵין צָרִיךְ לְכַבּוֹתוֹ עַד שֶׁיִּכְבֶּה מֵעַצְמוֹ \u0005(מָרְדְּכַי פ' אַלְמָנָה לכה\"ג)\u0006. וְכָל זֶה \u0010y33\u0011 מַיְרֵי בִּתְרוּמָה שֶׁהֻכְשְׁרָה, דְּאָז נִטְמֵאת וּמֻתָּר לְשָׂרְפָהּ. \u0010c8\u0011 אֲבָל אִם לֹא הֻכְשְׁרָה, שֶׁלֹּא נִטְמֵאת, אָסוּר לְשָׂרְפָהּ. וְטוֹב לְהַכְשִׁיר \u0010y34\u0011 אוֹתָם קֹדֶם מֵרוּחַ, כְּדֵי שֶׁתְּקַבֵּל טֻמְאָה וִיהֵא מֻתָּר לְשָׂרְפָהּ \u0005(טוּר)\u0006. וְאַחַר כָּךְ מַפְרִישׁ מִן הַשְּׁאָר אֶחָד מֵעֲשָׂרָה, וְהוּא נִקְרָא מַעֲשֵׁר רִאשׁוֹן \u0010y35\u0011 \u0010c9\u0011 וְנוֹתְנוֹ לְלֵוִי. \u0010y36\u0011 \u0005וְיֵשׁ אוֹמְרִים אַף לְכֹהֵן (טוּר)\u0006. וְעַל זֶה נֶאֱמַר בְּתוֹרָה: כִּי אֶת מַעְשַּׂר בְּנֵי יִשְׂרָאֵל וְגו' \u0005(בַּמִּדְבָּר יח, כד)\u0006 וְלִבְנֵי לֵוִי הִנֵּה נָתַתִּי אֶת כָּל מַעֲשֵׁר בְּיִשְׂרָאֵל וְגו' \u0005(בְּמִדְבָּר יח, כא)\u0006 וְאַחַר כָּךְ מַפְרִישׁ מֵהַשְּׁאָר אֶחָד מֵעֲשָׂרָה, וְהוּא נִקְרָא מַעֲשֵׂר שֵׁנִי, וְהוּא לִבְעָלָיו, וּבְסִימָן זֶה יִתְבָּאֲרוּ מִשְׁפָּטָיו, וְעָלָיו נֶאֱמַר: עַשֵּׂר תְּעַשֵּׂר \u0005(דְּבָרִים יד, כב)\u0006 וְעַל הַסֵדֶר הַזֶּה מַפְרִישִׁין בְּשָׁנָה רִאשׁוֹנָה \u0010y37\u0011 מֵהַשָּׁבוּעַ, וּבַשְּׁנִיָּה וּבָרְבִיעִית וּבַחֲמִישִׁית. אֲבָל בַּשְּׁלִישִׁית וּבַשִּׁשִּׁית מֵהַשָּׁבוּעַ, אַחַר שֶׁמַּפְרִישִׁין מַעֲשֵׂר רִאשׁוֹן, מַפְרִישִׁין מֵהַשְּׁאָר מַעֲשֵׂר אַחֵר, וְנוֹתְנִים לַעֲנִיִּים, וְהוּא נִקְרָא מַעֲשֵׂר עָנִי. וְאֵין בִּשְׁתֵּי שָׁנִים אֵלּוּ מַעֲשֵׂר שֵׁנִי אֶלָּא מַעֲשַׂר עָנִי, \u0010y38\u0011 וְעָלָיו נֶאֱמַר: מִקְצֵה שָׁלֹשׁ שָׁנִים תּוֹצִיא אֶת כָּל מַעְשַּׂר תְּבוּאָתְךָ וגו' וּבָא הַלֵּוִי וגו' \u0010y39\u0011 \u0005(דְּבָרִים יד, כח כט)\u0006 שְׁנַת הַשְּׁמִטָּה כֻּלָּהּ הֶפְקֵר וְאֵין בָּהּ לֹא תְּרוּמָה וְלֹא מַעַשְׂרוֹת כְּלָל. וּבְחוּצָה לָאָרֶץ שֶׁאֵין בָּהּ שְׁמִטַּת קַרְקַע, מַפְרִישִׁין בִּשְׁנַת הַשְּׁמִטָּה בְּאֶרֶץ מִצְרַיִם \u0010y40\u0011 וּבְעַמּוֹן וּמוֹאָב מַעֲשֵׂר רִאשׁוֹן וּמַעֲשַׂר עָנִי. \u0010y41\u0011 וּבְאֶרֶץ שִׁנְעָר, מַפְרִישִׁין בָּהּ מַעֲשֵׂר שֵׁנִי, כְּמוֹ בְּרֹב הַשָּׁנִים. וּשְׁנַת הַשְּׁמִטָּה הָאֲמִתִּית הָיְתָה \u0010y42\u0011 שְׁנַת השי\"ג \u0005וְיֵשׁ אוֹמְרִים אִם עוֹבֵד כּוֹכָבִים מָכַר פֵּרוֹת בַּשְּׁבִיעִית לְיִשְׂרָאֵל, וּגְמַר מְלַאכְתּוֹ בְּיַד יִשְׂרָאֵל, חַיָּבִים בִּתְרוּמָה וּמַעֲשֵׂר, וּמַפְרִישׁ מַעֲשַׂר עָנִי כְּדִין עַמּוֹן וּמוֹאָב (בֵּית יוֹסֵף וְכֵן כָּתַב כַּפְתּוֹר וָפֶרַח)\u0006.\nמַעֲשֵׂר רִאשׁוֹן שֶׁלּוֹקֵחַ הַלֵּוִי, מַפְרִישׁ מִמֶּנּוּ אֶחָד מֵעֲשָׂרָה וְנוֹתְנוֹ לַכֹּהֵן, וְהוּא נִקְרָא תְּרוּמַת מַעֲשֵׂר, וְעָלָיו נֶאֱמַר: וְאֶל הַלְוִיִּם תְּדַבֵּר וגו' \u0005(בַּמִּדְבָּר יח, כו)\u0006 \u0005וְדִין תְּרוּמַת מַעֲשֵׂר כְּדִין תְּרוּמָה גְּדוֹלָה; מִיהוּ אֲפִלּוּ הָאִדָּנָא בָּעֵינָן לִתֵּן כַּשִּׁעוּר\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006.\nהַמַּרְבֶּה בִּתְרוּמָה, הוֹאִיל וְשִׁיֵּר מִקְצָת חֻלִּין, הֲרֵי זֶה תְּרוּמָה. אֲבָל אִם אָמַר: כָּל הַפֵּרוֹת הָאֵלּוּ תְּרוּמָה, \u0010c10\u0011 לֹא אָמַר כְּלוּם.\nהָאוֹמֵר: תְּרוּמַת הַכֶּרִי לְתוֹכוֹ, אִם אָמַר: בִּצְפוֹנוֹ, אוֹ בִּדְרוֹמוֹ, קָרָא שֵׁם וְחַיָּב לְהַפְרִישׁ מִמֶּנּוּ תְּרוּמָתוֹ; וְאִם \u0010y43\u0011 לֹא צִיֵּן הַמָּקוֹם, \u0010y44\u0011 לֹא אָמַר כְּלוּם.\nאָמַר: \u0010c11\u0011 תְּרוּמַת הַכֶּרִי הַזֶּה בָּזֶה וְהַכֶּרִי הַזֶּה בָּזֶה, \u0010y45\u0011 מָקוֹם שֶׁנִּסְתַּיְּמָה תְּרוּמָתוֹ שֶׁל הָרִאשׁוֹן שָׁם נִסְתַּיְּמָה תְּרוּמָתוֹ שֶׁל שֵׁנִי.\nתְּרוּמַת מַעֲשֵׂר \u0010y46\u0011 אֵין מַפְרִישִׁין אוֹתָהּ בְּאֹמֶד, אֶלָּא מְדַקְדֵּק בְּשִׁעוּרָהּ, וַאֲפִלּוּ בַּזְּמַן הַזֶּה; דָּבָר שֶׁדַּרְכּוֹ לִמְדֹּד, מוֹדֵד. וְדָבָר הַנִּשְׁקָל, שׁוֹקֵל. וְדָבָר שֶׁאֶפְשָׁר לִמְנוֹתוֹ, מוֹנֶה. הָיָה אֶפְשָׁר לִמְנוֹתוֹ וּלְשָׁקְלוֹ וְלִמְדָדוֹ, הַמּוֹנֶה מְשֻׁבָּח, וְהַמּוֹדֵד מְשֻׁבָּח מִמֶּנּוּ, וְהַשּׁוֹקֵל מְשֻׁבָּח מִשְּׁנֵיהֶם. \u0005וְנִטֶּלֶת שֶׁלֹּא מִן \u0010y47\u0011 הַמֻּקָּף. וְתַלְמִידֵי חֲכָמִים אֵין תּוֹרְמִין אֶלָּא מִן הַמֻּקָּף (הַרַמְבַּ\"ם פ\"ג)\u0006.\nאֵין תּוֹרְמִין תְּרוּמָה גְּדוֹלָה \u0010y48\u0011 אֶלָּא מִן הַמֻּקָּף. כֵּיצַד, הָיוּ לוֹ חֲמִשִּׁים סְאָה בְּבַיִת זֶה וַחֲמִשִּׁים סְאָה בְּבַיִת אַחֵר, לֹא יַפְרִישׁ מֵאֶחָד מֵהֶם עַל שְׁנֵיהֶם, וְאִם הִפְרִישׁ שֶׁלֹּא מִן \u0010y49\u0011 הַמֻּקָּף, תְּרוּמָתוֹ תְּרוּמָה, וְהוּא שֶׁיִּהְיֶה הַמֻּפְרָשׁ שָׁמוּר. אֲבָל אִם הָיָה טָעוּן כַּדֵּי יַיִן אוֹ שֶׁמֶן, וְרָאָה שֶׁמִּשְׁתַּבְּרִין, וְאָמַר: הֲרֵי הֵם תְּרוּמָה עַל פֵּרוֹת שֶׁבְּבֵיתִי, \u0010y50\u0011 לֹא אָמַר כְּלוּם. ונ\"ל דְּבַזְּמַן הַזֶּה לְאִבּוּד אָזְלָא מִפְּנֵי הַטֻּמְאָה, תְּרוּמָתוֹ תְּרוּמָה.\nפֵּרוֹת הַמְפֻזָּרִים בְּתוֹךְ הַבַּיִת, אוֹ שְׁתֵּי מְגוּרוֹת \u0005(פי' מְקוֹמוֹת שֶׁמַּכְנִיסִים בָּהֶן פֵּרוֹת מֵעִנְיַן יְגֹרֵהוּ בְחֶרְמוֹ)\u0006 \u0005(חֲבַקוּק א, טו)\u0006 שֶׁבְּבַיִת אֶחָד, \u0010y51\u0011 תּוֹרֵם מֵאֶחָד עַל הַכֹּל. \u0005(שַׂקֵי תְּבוּאָה וְעִגּוּלֵי דְּבֵלָה וְחָבִיּוֹת שֶׁל גְּרוֹגָרוֹת, אִם הָיוּ בְּהֶקֵפָה אַחַת, תּוֹרֵם מֵאֶחָד עַל הַכֹּל)\u0006. חָבִיּוֹת שֶׁלֹּא סָתַם אֶת פִּיהֶם, תּוֹרֵם מֵאֶחָד עַל הַכֹּל; מִשֶּׁיִּסָתֵם, תּוֹרֵם מִכָּל אֶחָד וְאֶחָד. \u0010y52\u0011\nהַמַּקְדִּים מַעֲשֵׂר שֵׁנִי לְרִאשׁוֹן, אוֹ מַעֲשֵׂר רִאשׁוֹן לִתְרוּמָה, אַף עַל פִּי שֶׁעָבַר \u0010c12\u0011 בְּלֹא תַּעֲשֶׂה, מַה שֶּׁעָשָׂה עָשׂוּי.\nהָרוֹצֶה לְהַפְרִישׁ תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר כְּאֶחָד, \u0010c13\u0011 מַפְרִישׁ \u0010y53\u0011 אֶחָד מִמֵּאָה וּמְעַט יוֹתֵר, וְאוֹמֵר: אֶחָד מִמֵּאָה שֶׁיֵּשׁ כָּאן, הֲרֵי הוּא בְּצַד זֶה שֶׁהִפְרַשְׁתִּי \u0010y54\u0011 וַהֲרֵי הוּא חֻלִּין; וְהַנִּשְׁאָר מִזֶּה שֶׁהִפְרַשְׁתִּי, שֶׁהוּא הַמְּעַט הַיָּתֵר עַל אֶחָד מִמֵּאָה, הוּא תְּרוּמָה עַל הַכֹּל; \u0010y55\u0011 וְהַמַּעֲשֵׂר שֶׁרָאוּי לִהְיוֹת לְמֵאָה חֻלִּין אֵלּוּ, הֲרֵי הוּא בְּצַד זֶה שֶׁהִפְרַשְׁתִּי; וְזֶה הַנִּשְׁאָר יוֹתֵר עַל הַתְּרוּמָה מִמַּה שֶּׁהִפְרַשְׁתִּי הֲרֵי הוּא תְּרוּמַת מַעֲשֵׂר עַל הַכֹּל. \u0010y56\u0011\nעוֹשֶׂה אָדָם שָׁלִיחַ לְהַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת.\nחֲמִשָּׁה אִם תָּרְמוּ, אֵין תְּרוּמָתָן תְּרוּמָה; חֵרֵשׁ, שׁוֹטֶה וְקָטָן וְעוֹבֵד כּוֹכָבִים שֶׁתָּרַם שֶׁל יִשְׂרָאֵל, אֲפִלּוּ בִּרְשׁוּתוֹ, וְהַתּוֹרֵם שֶׁאֵינוֹ שֶׁלּוֹ שֶׁלֹּא בִּרְשׁוּת הַבְּעָלִים; אֲבָל הַתּוֹרֵם מִשֶּׁלוֹ עַל שֶׁל אֲחֵרִים, הֲרֵי זֶה תְּרוּמָה וְתִקֵּן פֵּרוֹתֵיהֶם, וְטוֹבַת הֲנָאָה שֶׁלּוֹ שֶׁנּוֹתְנָהּ לְכָל כֹּהֵן שֶׁיִּרְצֶה. \u0010c14\u0011\nהַתּוֹרֵם שֶׁלֹּא בִּרְשׁוּת, אוֹ שֶׁיָּרַד לְתוֹךְ שְׂדֵה חֲבֵרוֹ וְלִקֵּט פֵּרוֹת שֶׁלֹּא בִּרְשׁוּת, כְּדֵי שֶׁיִּקָּחֵם, וְתָרַם; אִם בָּא בַּעַל הַבַּיִת וְאָמַר לֵיהּ: כַּלֵּךְ אֵצֶל יָפוֹת, אִם הָיוּ שָׁם יָפוֹת מִמַּה שֶּׁתָּרַם, \u0010y57\u0011 תְּרוּמָתוֹ תְּרוּמָה. \u0010c15\u0011 וְאִם לָאו, \u0010y58\u0011 אֵין תְּרוּמָתוֹ תְּרוּמָה. \u0010y59\u0011 וְאִם לִקֵּט בַּעַל הַבַּיִת וְהוֹסִיף, בֵּין כָּךְ וּבֵין כָּךְ תְּרוּמָתוֹ תְּרוּמָה. \u0010c16\u0011\nהַמְדַבֵּר וְאֵינוֹ שׁוֹמֵעַ, אוֹ שֶׁשּׁוֹמֵעַ וְאֵינוֹ מְדַבֵּר, וְהֶעָרֹם, וְהַשִּׁכּוֹר, וְהַסוּמָא, \u0010y60\u0011 לֹא יִתְרְמוּ; וְאִם תָּרְמוּ, תְּרוּמָתָן תְּרוּמָה. וּבַזְּמַן הַזֶּה, דְּלִשְׂרֵפָה אָזְלָא מִפְּנֵי הַטֻּמְאָה, תּוֹרְמִים שִׁכּוֹר וְסוּמָא \u0010y61\u0011 וַאֲפִלּוּ לְכַתְּחַלָּה, תְּרוּמָה, אֲבָל לֹא מַעֲשַׂר לֵוִי.\nקָטָן שֶׁהִגִּיעַ \u0010c17\u0011 לְעוֹנַת נְדָרִים, אַף עַל פִּי שֶׁלֹּא הֵבִיא שְׁתֵּי שְׂעָרוֹת וְלֹא נַעֲשָׂה גָּדוֹל, אִם תָּרַם \u0010y62\u0011 תְּרוּמָתוֹ תְּרוּמָה.\nהָאוֹמֵר לִשְׁלוּחוֹ: צֵא וּתְרֹם לִי, וְהָלַךְ לִתְרֹם, וְאֵינוֹ יוֹדֵעַ אִם תָּרַם, וּבָא וּמָצָא כֶּרִי תָּרוּם, אֵין חֶזְקָתוֹ תָּרוּם; חוֹשְׁשִׁין, \u0010c18\u0011 שֶׁמָּא אַחֵר תָּרַם בְּלֹא רְשׁוּת. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּבִכְהַאי גַּוְנָא חֶזְקָתוֹ תָּרוּם, דְּאָמְרִינַן: חֲזָקָה שָׁלִיחַ עוֹשֶׂה שְׁלִיחוּתוֹ, \u0010y63\u0011 אֲפִלּוּ בְּאִסּוּר דְּאוֹרַיְתָא. אֲבָל אִם אֵינוֹ יוֹדֵעַ אִם כֶּרִי תָּרוּם אוֹ לֹא, אָסוּר לֶאֱכֹל מִמֶּנּוּ, דְּהַשָּׁלִיחַ אוֹמֵר: וַדַּאי לֹא יִגַּע בּוֹ עַד שֶׁיֵּדַע שֶׁהוּא תָּרוּם. (טוּר בְּשֵׁם הָרֹא\"שׁ והר\"ש)\u0006. \u0010y64\u0011\nפֵּרוֹת הַשֻּׁתָּפִין חַיָּבִים בִּתְרוּמָה וּמַעַשְׂרוֹת, וְאֵינָם צְרִיכִים לִטֹּל רְשׁוּת זֶה מִזֶּה, אֶלָּא כָּל הַתּוֹרֵם מֵהֶם תְּרוּמָתוֹ תְּרוּמָה. תָּרַם אֶחָד מֵהֶם וְלֹא יָדַע חֲבֵרוֹ, וּבָא הוּא וְתָרַם, אִם הָיוּ \u0010c19\u0011 מְמַחִין זֶה עַל זֶה, אֵין תְּרוּמַת הַשֵּׁנִי תְּרוּמָה; וְאִם לָאו, אִם תָּרַם הָרִאשׁוֹן כַּשִּׁעוּר, אֵין תְּרוּמַת הַשֵּׁנִי תְּרוּמָה. וְאִם לֹא תָּרַם הָרִאשׁוֹן כַּשִּׁעוּר, תְּרוּמַת שְׁנֵיהֶם תְּרוּמָה. וְנִרְאֶה לִי שֶׁבַּזְּמַן הַזֶּה, ה\"ה בְּמַעֲשֵׂר. אֲבָל לִתְרוּמָה, כֵּיוָן שֶׁאֵין לִתְרוּמָה שִׁעוּר, בֵּין כָּךְ וּבֵין כָּךְ אֵין תְּרוּמַת הַשֵּׁנִי תְּרוּמָה.\nהָאוֹמֵר לְאֶחָד לִתְרֹם, וְהָלַךְ \u0010y65\u0011 לִתְרֹם, וּבִטֵּל שְׁלִיחוּתוֹ \u0010c20\u0011 קֹדֶם שֶׁיִּתְרֹם, אִם שִׁנָּה הַשָּׁלִיחַ שְׁלִיחוּתוֹ כְּגוֹן שֶׁאָמַר לוֹ: תְּרֹם מִן הַצָּפוֹן, וְתָרַם מִן הַדָּרוֹם, אֵין תְּרוּמָתוֹ תְּרוּמָה. וְאִם לָאו, תְּרוּמָתוֹ תְּרוּמָה. \u0005וְיֵשׁ חוֹלְקִין וס\"ל דְּכָל שֶׁבִּטֵּל הַשְּׁלִיחוּת, אֲפִלּוּ לֹא שִׁנָּה, לֹא הָוֵי תְּרוּמָתוֹ תְּרוּמָה (טוּר)\u0006.\nאָרִיס שֶׁתָּרַם, וּבָא בַּעַל הַבַּיִת וְעִכֵּב, אִם עַד שֶׁלֹּא תָּרַם עִכֵּב, אֵין תְּרוּמָתוֹ תְּרוּמָה. וְאִם מִשֶּׁתָּרַם \u0010y66\u0011 עִכֵּב, תְּרוּמָתוֹ תְּרוּמָה.\nאַפּוֹטְרוֹפְּסִין \u0010y67\u0011 תּוֹרְמִין \u0010c21\u0011 נִכְסֵי יְתוֹמִים. \u0010c22\u0011\nהַגַּנָּב וְהַגַּזְלָן וְהָאַנָּס, \u0010y68\u0011 תְּרוּמָתָן תְּרוּמָה. וְאִם הָיוּ הַבְּעָלִים רוֹדְפִין אַחֲרֵיהֶם, \u0010y69\u0011 אֵין תְּרוּמָתָן תְּרוּמָה.\nהַבֵּן וְהַשָּׂכִיר וְהָעֶבֶד וְהָאִשָּׁה, תּוֹרְמִין \u0010y70\u0011 עַל מַה שֶּׁהֵם אוֹכְלִין, אֲבָל לֹא עַל הַשְּׁאָר.\nהַבֵּן, כְּשֶׁאוֹכֵל אִם אָבִיו, וְהָאִשָּׁה בְּעִסָתָהּ, תּוֹרְמִין, מִפְּנֵי שֶׁהֵן בִּרְשׁוּת.\nהַפּוֹעֲלִים, אֵין לָהֶם רְשׁוּת לִתְרֹם שֶׁלֹּא מִדַּעַת בַּעַל הַבַּיִת.\nפּוֹעֵל שֶׁאָמַר לֵיהּ בַּעַל הַבַּיִת: כְּנֹס לִי גָּרְנִי \u0010c23\u0011 וּתְרֹם, וְתָרַם, וְאַחַר כָּךְ כָּנַס, \u0010y71\u0011 תְּרוּמָתוֹ תְּרוּמָה.\nעוֹבֵד כּוֹכָבִים שֶׁהִפְרִישׁ תְּרוּמָה מִשֶּׁלּוֹ, \u0010y72\u0011 \u0010c24\u0011 גָּזְרוּ חֲכָמִים שֶׁתְּהֵא תְּרוּמָתוֹ תְּרוּמָה אִם הוּא בְּאֶרֶץ יִשְׂרָאֵל. \u0005הַגָּה: וּבוֹדְקִין אוֹתוֹ, אִם אָמַר: בְּדַעַת יִשְׂרָאֵל הִפְרַשְׁתִּי, תִּנָּתֵן לַכֹּהֵן; וְאִם לָאו, \u0010y73\u0011 \u0010c25\u0011 טְעוּנָה גְּנִיזָה (טוּר)\u0006.\nהַמִּתְכַּוֵּן לוֹמַר: תְּרוּמָה, וְאָמַר: מַעֲשֵׂר; מַעֲשֵׂר, וְאָמַר: תְּרוּמָה, \u0010y74\u0011 לֹא אָמַר כְּלוּם, עַד שֶׁיִּהְיוּ פִּיו וְלִבּוֹ שָׁוִים.\nהִפְרִישׁ תְּרוּמָה בְּמַחֲשַׁבְתּוֹ וְלֹא הוֹצִיא בִּשְׂפָתָיו כְּלוּם, \u0010y75\u0011 הֲרֵי זֶה תְּרוּמָה, שֶׁנֶּאֱמַר וְנֶחְשַׁב לָכֶם תְּרוּמַתְכֶם \u0005(בַּמִּדְבָּר יח, כז)\u0006.\nהַמַּפְרִישׁ תְּרוּמָה עַל תְּנַאי, אִם נִתְקַיֵּם הַתְּנַאי \u0010y76\u0011 הֲרֵי זֶה תְּרוּמָה.\nהַמַּפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת, וְנִחַם עֲלֵיהֶם, הֲרֵי זֶה נִשְׁאָל לְחָכָם וּמַתִּיר לוֹ, כְּדֶרֶךְ שֶׁמַּתִּירִין שְׁאָר נְדָרִים, \u0010y77\u0011 וְתַחֲזֹר חֻלִּין כְּמוֹ שֶׁהָיְתָה.\nהָאוֹמֵר: שֶׁל מַעְלָה תְּרוּמָה וְשֶׁל מַטָּה חֻלִּין, אוֹ בְּהֶפֶךְ, \u0010y78\u0011 דְּבָרָיו קַיָּמִים.\nהַתּוֹרֵם אֶת הַגֹּרֶן, צָרִיךְ שֶׁיְּכַוֵּן אֶת לִבּוֹ שֶׁתִּהְיֶה תְּרוּמָה עַל הַכֶּרִי וְעַל מַה שֶׁבַּקֻּטָּעִין \u0005(פי' שִׁבֳּלִים קְטוּעִים שֶׁלֹּא נִדּוֹשׁוּ)\u0006 וְעַל מַה שֶּׁבַּצְּדָדִים וְעַל מַה שֶּׁבְּתוֹךְ הַתֶּבֶן. הַתּוֹרֵם אֶת הַיֶּקֶב, צָרִיךְ שֶׁיְּכַוֵּן אֶת לִבּוֹ לִתְרֹם עַל מַה שֶׁבַּחַרְצַנִּים וְעַל מַה שֶּׁבַּזַּגִּים. הַתּוֹרֵם אֶת הַבּוֹר שֶׁל שֶׁמֶן, צָרִיךְ שֶׁיְּכַוֵּן אֶת לִבּוֹ עַל מַה שֶּׁבַּגֶּפֶת \u0005(פי' פְּסֹלֶת שֶׁל זֵיתִים)\u0006 ; וְאִם לֹא נִתְכַּוֵּן, אֶלָּא תָּרַם סְתָם, נִפְטָר הַכֹּל, שֶׁתְּנַאי בֵּית דִּין הוּא שֶׁתְּרוּמָה עַל הַכֹּל.\nהַתּוֹרֵם כַּלְכָּלָה שֶׁל תְּאֵנִים, וְנִמְצְאוּ תְּאֵנִים בְּצַד הַכַּלְכָּלָה, הֲרֵי אֵלּוּ פְּטוּרִים, מִפְּנֵי שֶׁבְּלִבּוֹ לִתְרֹם עַל הַכֹּל.\nאֵין תּוֹרְמִין אֶלָּא מִן הַיָּפֶה. וְנִרְאֶה לִי דְּהַשְׁתָּא דִּלְאִבּוּד אָזְלָא מִפְּנֵי הַטֻּמְאָה, אֵין לְהַקְפִּיד בְּכָךְ; וּמִיהוּ בְּמַעֲשֵׂר הַנִּתָּן לְלֵוִי וּלְעָנִי, יֵשׁ לְהַקְפִּיד בְּכָךְ.\nאֵין תּוֹרְמִין מִמִּין עַל שֶׁאֵינוֹ מִינוֹ; וְאִם תָּרַם, אֵין תְּרוּמָתוֹ תְּרוּמָה. הַקִּשּׁוּת וְהַמְּלָפְפוֹת מִין אֶחָד. כָּל מִין חִטִּים מִין אֶחָד. כָּל מִין תְּאֵנִים וּגְרוֹגָרוֹת וּדְבֵלָה מִין אֶחָד, וְתוֹרֵם מִזֶּה עַל זֶה. וְכָל שֶׁהוּא כִּלְאַיִם בַּחֲבֵרוֹ לֹא יִתְרֹם מִזֶּה עַל זֶה, אֲפִלּוּ מִן הַיָּפָה עַל הָרָעָה; וְאִם תָּרַם, אֵין תְּרוּמָתוֹ תְּרוּמָה. וְכָל שֶׁאֵינוֹ כִּלְאַיִם בַּחֲבֵרוֹ, תּוֹרֵם מִן הַיָּפֶה עַל הָרַע, אֲבָל לֹא מִן הָרַע עַל הַיָּפֶה, וְאִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה, חוּץ מִן הַזּוֹנִין \u0005(פי' זֶרְעוֹנִים שְׁחֹרִים הַנִּמְצָא בֵּין הַחִטִּים)\u0006 עַל הַחִטִּים, מִפְּנֵי שֶׁאֵינָם אֹכֶל אָדָם. \u0010y79\u0011\nאֵין תּוֹרְמִין מִדָּבָר שֶׁנִּגְמְרָה מְלַאכְתּוֹ עַל דָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ; וְלֹא מִדָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ עַל דָּבָר שֶׁנִּגְמְרָה מְלַאכְתּוֹ; וְאִם תָּרַם, תְּרוּמָתוֹ תְּרוּמָה.\nאֵין תּוֹרְמִין מֵהַמְחֻבָּר עַל הַתָּלוּשׁ וְלֹא מִן הַתָּלוּשׁ עַל הַמְחֻבָּר, וְאִם תָּרַם, \u0010y80\u0011 אֵין תְּרוּמָתוֹ תְּרוּמָה. אֲבָל אִם אָמַר: פֵּרוֹת עֲרוּגָה זוֹ תְּלוּשִׁים יִהְיוּ תְּרוּמָה עַל פֵּרוֹת עֲרוּגָה זֶה לִכְשֶׁיִּתָּלְשׁוּ, \u0010y81\u0011 וְנִתְלְשׁוּ, דְּבָרָיו קַיָּמִין. וְהוּא שֶׁהֵבִיאוּ שְׁנֵיהֶם שְׁלִישׁ בְּעֵת שֶׁאָמַר. \u0010y82\u0011\nאֵין תּוֹרְמִין מִן הַלַּח עַל הַיָּבֵשׁ, וְלֹא מִן הַיָּבֵשׁ עַל הַלַּח; וְאִם תָּרַם, תְּרוּמָתוֹ תְּרוּמָה.\nאֵין תּוֹרְמִין מִפֵּרוֹת שָׁנָה זוֹ עַל פֵּרוֹת שָׁנָה שֶׁעָבְרָה, וְלֹא מִפֵּרוֹת שָׁנָה שֶׁעָבְרָה עַל פֵּרוֹת שָׁנָה זוֹ; וְאִם תָּרַם, אֵינָהּ תְּרוּמָה, שֶׁנֶּאֱמַר: שָׁנָה שָׁנָה \u0005(דְּבָרִים יד, כב)\u0006. לִקֵּט יָרָק עֶרֶב רֹאשׁ הַשָּׁנָה עַד שֶׁלֹּא בָּא הַשֶּׁמֶשׁ, וְחָזַר וְלִקֵּט אַחַר שֶׁבָּא הַשֶּׁמֶשׁ, אֵין תּוֹרְמִין מִזֶּה עַל זֶה, שֶׁזֶּה חָדָשׁ וְזֶה יָשָׁן. וְכֵן אִם לִקֵּט אֶתְרוֹג בְּעֶרֶב ט\"וּ בִּשְׁבָט עַד שֶׁלֹּא בָּא הַשֶּׁמֶשׁ, וְחָזַר וְלִקֵּט אֶתְרוֹג אַחֵר מִשֶּׁבָּאָה הַשֶּׁמֶשׁ, אֵין תּוֹרְמִין מִזֶּה עַל זֶה, מִפְּנֵי שֶׁאֶחָד בְּתִשְׁרֵי רֹאשׁ הַשָּׁנָה לַמַּעַשְׂרוֹת תְּבוּאָה וְקִטְנִיּוֹת וִירָקוֹת, וְט\"וּ בִּשְׁבָט רֹאשׁ הַשָּׁנָה לְמַעַשְׂרוֹת הָאִילָן.\nאֵין תּוֹרְמִין מִפֵּרוֹת הָאָרֶץ עַל פֵּרוֹת חוּצָה לָאָרֶץ, וְלֹא מִפֵּרוֹת חוּצָה לָאָרֶץ עַל פֵּרוֹת הָאָרֶץ, וְלֹא מִפֵּרוֹת הַפְּטוּרִים עַל הַחַיָּבִים, וְלֹא מֵהַחַיָּבִים עַל הַפְּטוּרִים; וְאִם תָּרְמוּ, אֵין תְּרוּמָתָן תְּרוּמָה. \u0010y83\u0011\nתָּרַם מִדְּמַאי \u0005(פי' דָּא מַאי, כְּלוֹמַר פֵּרוֹת אוֹ תְּבוּאָה שֶׁנִּלְקְחָה מֵעַם הָאָרֶץ שֶׁאֵין יָדוּעַ אִם הֵרִים הַמַּעֲשֵׂר כָּרָאוּי, וְחַיָּב בְּמַעַשְׂרוֹת מִדְּרַבָּנָן)\u0006. עַל דְּמַאי, אוֹ עַל וַדַּאי, \u0010y84\u0011 תְּרוּמָתוֹ תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם מִכָּל אֶחָד מִפְּנֵי עַצְמוֹ. \u0010y85\u0011\nתָּרַם מִוַּדַּאי עַל דְּמַאי, \u0010y86\u0011 תְּרוּמָתוֹ תְּרוּמָה, וְלֹא תֵּאָכֵל \u0010y87\u0011 עַד שֶׁיּוֹצִיא עָלֶיהָ תְּרוּמָה וּמַעַשְׂרוֹת. \u0010y88\u0011\nאֵין תּוֹרְמִין מִן הַלָּקוּחַ עַל מַה שֶּׁגָּדַל בְּתוֹךְ שָׂדֵהוּ, וְלֹא הַלָּקוּחַ מֵעוֹבֵד כּוֹכָבִים עַל הַלָּקוּחַ מִיִּשְׂרָאֵל, אוֹ בְּהֶפֶךְ. \u0010y89\u0011\nאֵין תּוֹרְמִין שִׁבֳּלִים עַל חִטִּים, וְזֵיתִים עַל שֶׁמֶן, וַעֲנָבִים עַל יַיִן; \u0010y90\u0011 אֲבָל תּוֹרְמִים שֶׁמֶן עַל זֵיתִים הַנִּכְבָּשִׁים, וְיַיִן עַל עֲנָבִים לַעֲשׂוֹת צִמּוּקִים.\nתּוֹרְמִים זֵיתֵי שֶׁמֶן עַל זֵיתֵי כֶּבֶשׁ, אֲבָל לֹא מִזֵּיתֵי כֶּבֶשׁ עַל זֵּיתֵי שֶׁמֶן; מִיַּיִן שֶׁאֵינוֹ מְבֻשָּׁל עַל הַמְּבֻשָּׁל, אֲבָל לֹא מִן הַמְּבֻשָּׁל עַל שֶׁאֵינוֹ מְבֻשָּׁל; מִן הַצָּלוּל עַל שֶׁאֵינוֹ צָלוּל, אֲבָל לֹא מִשֶּׁאֵינוֹ צָלוּל עַל הַצָּלוּל; מִתְּאֵנִים עַל גְּרוֹגָרוֹת בְּמִנְיָן מִגְּרוֹגָרוֹת עַל תְּאֵנִים בְּמִדָּה, אֲבָל לֹא תְּאֵנִים עַל גְּרוֹגָרוֹת בְּמִדָּה וְלֹא גְּרוֹגָרוֹת עַל תְּאֵנִים בְּמִנְיָן, כְּדֵי שֶׁיִּתְרֹם לְעוֹלָם בְּעַיִן יָפָה. וְתוֹרְמִים חִטִּים עַל הַפַּת, אֲבָל לֹא מִן הַפַּת עַל חִטִּים לְפִי חֶשְׁבּוֹן; וּבְכָל אֵלּוּ אִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה. ונ\"ל דְּהָאִידָּנָא דִּתְרוּמָה לְאִבּוּד אָזְלָא, אֵין לְהַקְפִּיד בְּכָךְ וְכֵן בִּשְׁאָר דְּבָרִים כַּיּוֹצֵא בָּהֶם; \u0010y91\u0011 וּמִיהוּ בְּמַעֲשֵׂר הַנִּתָּן לְלֵוִי וּלְעָנִי, יֵשׁ לְהַקְפִּיד בְּכָךְ. \u0010y92\u0011\nאֵין תּוֹרְמִין חֹמֶץ עַל יַיִן, \u0010y93\u0011 אֲבָל תּוֹרְמִין יַיִן עַל \u0010y94\u0011 חֹמֶץ.\nהַתּוֹרֵם חָבִית שֶׁל יַיִן עַל הַיַיִן, וְנִמְצֵאת חֹמֶץ, אִם יָדוּעַ שֶׁהָיְתָה שֶׁל חֹמֶץ עַד שֶׁלֹּא תְּרָמָהּ, אֵינָהּ תְּרוּמָה; וְאִם אַחַר שֶׁתְּרָמָהּ הֶחְמִיצָה, הֲרֵי זוֹ תְּרוּמָה. \u0010y95\u0011 אִם סָפֵק, תְּרוּמָה וְיַחֲזֹר וְיִתְרֹם. וְכֵן הַתּוֹרֵם קִשּׁוּת וְנִמְצֵאת מָרָה, אֲבַטִּיחַ וְנִמְצָא סָרוּחַ.\nאַחַר שֶׁמַּפְרִישִׁין תְּרוּמָה גְּדוֹלָה \u0010y96\u0011 מַפְרִישׁ אֶחָד מֵעֲשָׂרָה מֵהַנִּשְׁאָר, וְהוּא הַנִּקְרָא מַעֲשֵׂר רִאשׁוֹן. \u0010y97\u0011\nמַעֲשֵׂר רִאשׁוֹן מֻתָּר בַּאֲכִילָה לְיִשְׂרָאֵל, וּמֻתָּר לְאָכְלוֹ בְּטֻמְאָה. לְפִיכָךְ בַּת לֵוִי שֶׁנִּבְעֲלָה בְּעִילַת זְנוּת, נוֹתְנִין לָהּ מַעֲשֵׂר וְאוֹכֶלֶת. אֲבָל מִי שֶׁשָּׁמְעָה שֶׁמֵּת בַּעֲלָהּ, אוֹ הֵעִיד לָהּ עֵד אֶחָד, וְנִשֵּׂאת וְאַחַר כָּךְ בָּא בַּעֲלָהּ, קָנְסוּ אוֹתָהּ חֲכָמִים שֶׁתִּהְיֶה אֲסוּרָה בְּמַעֲשֵׂר.\nלְוִיִּם וְכֹהֲנִים \u0010y98\u0011 מַפְרִישִׁין מַעֲשֵׂר רִאשׁוֹן כְּדֵי לְהַפְרִישׁ מִמֶּנּוּ תְּרוּמַת מַעֲשֵׂר, וְכֵן הַכֹּהֲנִים מַפְרִישִׁין שְׁאָר תְּרוּמוֹת וּמַעַשְׂרוֹת \u0010y99\u0011 וְהֵם לְעַצְמָם.\nאֵין מוֹצִיאִין מַעֲשֵׂר מִיַּד הַכֹּהֲנִים. וְכֵן כָּל מַתְּנוֹת כְּהֻנָּה אֵין מוֹצִיאִין אוֹתָם מִכֹּהֵן לְכֹהֵן.\nהָאוֹכֵל פֵּירוֹתָיו טְבָלִים, וְכֵן לֵוִי שֶׁאָכַל הַמַּעֲשֵׂר בְּטִבְלוֹ, אַף עַל פִּי שֶׁהֵם חַיָּבִים מִיתָה בִּידֵי שָׁמַיִם, אֵין מְשַׁלְּמִין הַמַּתָּנוֹת לְבַעֲלֵיהֶם, שֶׁנֶּאֱמַר: אֲשֶׁר יָרִימוּ לַה' \u0005(בַּמִּדְבָּר יח, כד)\u0006 אֵין לְךָ בָּהֶם כְּלוּם עַד שֶׁיָּרִימוּ אוֹתָם. וּבְחוּץ לָאָרֶץ מֻתָּר לְאָדָם לִהְיוֹת אוֹכֵל וְהוֹלֵךְ תְּחִלָּה וְאַחַר כָּךְ מַפְרִישׁ תְּרוּמָה וּמַעַשְׂרוֹת.\nמְעַשְּׂרִין מִמָּקוֹם זֶה עַל מָקוֹם אַחֵר, \u0010y100\u0011 וְאֵינוֹ צָרִיךְ לְעַשֵּׂר מִן הַמֻּקָּף. אֲבָל אֵין מְעַשְּׂרִין מִמִּין עַל שֶׁאֵינוֹ מִינוֹ; וְלֹא מִן הַחִיּוּב עַל הַפְּטוּר; וְלֹא מִן הַפְּטוּר עַל הַחִיּוּב; וְאִם עִשֵּׂר, אֵינוֹ מַעֲשֵׂר.\nכָּל שֶׁאָמַרְנוּ בִּתְרוּמָה אֵין תּוֹרְמִין מִזֶּה עַל זֶה, כָּךְ בְּמַעֲשֵׂר אֵין מְעַשְּׂרִין מִזֶּה עַל זֶה וְכָל שֶׁאָמַרְנוּ בִּתְרוּמָה אִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה, כָּךְ בְּמַעֲשֵׂר אִם הִפְרִישׁ מַעַשְׂרוֹתָיו מַעַשְׂרוֹת. וְכָל שֶׁהוּא פָּטוּר מִן הַתְּרוּמָה פָּטוּר מִן הַמַּעֲשֵׂר. וְכָל הַתּוֹרֵם מְעַשֵּׂר.\nכָּל שֶׁאָמַרְנוּ בָּהֶם לֹא יִתְרֹמוּ וְאִם תָּרְמוּ תְּרוּמָתָן תְּרוּמָה, כָּךְ אִם עִשְּׂרוּ מַעַשְׂרוֹתֵיהֶם מַעַשְׂרוֹת. וְכָל שֶׁאֵין תְּרוּמָתָן תְּרוּמָה, כָּךְ אֵין מַעַשְׂרוֹתֵיהֶן מַעַשְׂרוֹת.\nהַשְּׁקֵדִים הַמָּרִים, בֵּין בְּגָדְלָן בֵּין בְּקָטְנָן, פְּטוּרִים, לְפִי שֶׁאֵינָן אֹכֶל.\nאֵין מְעַשְּׂרִין \u0010y101\u0011 אֶלָּא מִן הַמֻּבְחָר.\nאֵין מְעַשְּׂרִין \u0010y102\u0011 בְּאֹמֶד, אֶלָּא בְּמִדָּה אוֹ בְּמִשְׁקָל אוֹ בְּמִנְיָן. וְכָל הַמְדַקְדֵּק \u0010y103\u0011 בַּשִּׁעוּר מְשֻׁבָּח. וְהַמַּרְבֶּה בְּמַעַשְׂרוֹת, מַעַשְׂרוֹתָיו מְקֻלְקָלִין שֶׁהֲרֵי הַטֶּבֶל מְעֹרָב בָּהֶן, וּפֵירוֹתָיו מְתֻקָּנִין.\nהַמַּפְרִישׁ מִקְצָת מַעֲשֵׂר, אֵינוֹ מַעֲשֵׂר אֶלָּא כְּמוֹ שֶׁחִלֵּק אֶת הָעֲרֵמָה, אֲבָל צָרִיךְ מִזֶּה הַחֵלֶק שֶׁיּוֹצִיא מַעֲשֵׂר שֶׁלּוֹ. כֵּיצַד, הָיוּ לוֹ מֵאָה סְאָה, הִפְרִישׁ מֵהֶם חֲמִשָּׁה לְשֵׁם מַעֲשֵׂר, \u0010y104\u0011 אֵינוֹ מַעֲשֵׂר, \u0010y105\u0011 וְאֵינוֹ יָכוֹל לְהַפְרִישׁ עַל הַחֲמֵשׁ סְאִין מַעֲשֵׂר בְּמָקוֹם אַחֵר, \u0010c26\u0011 אֶלָּא מֵהֶם, חֲצִי סְאָה, שֶׁהוּא הַמַּעֲשֵׂר שֶׁלָּהֶם.\nהַמַּפְרִישׁ תְּרוּמָה גְּדוֹלָה אוֹ תְּרוּמַת מַעֲשֵׂר, מְבָרֵךְ \u0010y106\u0011 קֹדֶם שֶׁיַּפְרִישׁ: אקב\"ו לְהַפְרִישׁ תְּרוּמָה. וְכֵן הַמַּפְרִישׁ מַעֲשֵׂר רִאשׁוֹן, מְבָרֵךְ קֹדֶם: לְהַפְרִישׁ מַעֲשֵׂר, וְכֵן מְבָרֵךְ עַל מַעֲשֵׂר שֵׁנִי. וְאִם הִפְרִישׁ הַכֹּל זֶה אַחַר זֶה מִיָּד, וְלֹא סָח בֵּינֵיהֶם, כּוֹלְלָן בִּבְרָכָה אַחַת וּמְבָרֵךְ: לְהַפְרִישׁ תְּרוּמוֹת וּמַעַשְׂרוֹת.\nכָּל פְּרִי שֶׁמִּקַּטְנוּתוֹ הוּא רָאוּי לַאֲכִילָה וְאֵינוֹ מַנִּיחַ אוֹתוֹ אֶלָּא כְּדֵי לְהוֹסִיף בְּגוּפוֹ, מִיָּד הוּא חַיָּב בְּמַעַשְׂרוֹת. \u0010y107\u0011 וְכָל פְּרִי שֶׁאֵינוֹ רָאוּי לַאֲכִילָה בְּקָטְנוֹ, אֵינוֹ חַיָּב בְּמַעַשְׂרוֹת עַד שֶׁיַּגִּיעַ לְעוֹנַת הַמַּעַשְׂרוֹת.\nאֶשְׁכּוֹל שֶׁהִגִּיעַ בּוֹ אֲפִלּוּ גַּרְגִּיר יְחִידִי, כֻּלּוֹ חִבּוּר לְמַעַשְׂרוֹת, וּכְאִלּוּ הִגִּיעַ כֻּלּוֹ, וְלֹא אוֹתוֹ אֶשְׁכּוֹל בִּלְבַד, אֶלָּא כָּל הָרוּחַ שֶׁיֵּשׁ בָּהּ אוֹתָהּ הַגֶּפֶן שֶׁיֵּשׁ בָּהּ הָאֶשְׁכּוֹל. וְכֵן רִמּוֹן שֶׁהִגִּיעַ בָּהּ אֲפִלּוּ פְּרִידָה אַחַת, כֻּלָּהּ חִבּוּר.\nשִׁמְרֵי יַיִן שֶׁנָּתַן עֲלֵיהֶם מַיִם וְסִנְּנָן, אִם נָתַן ג' וּמָצָא ד', מוֹצִיא מַעֲשֵׂר מִזֶּה הַיָּתֵר \u0010y108\u0011 \u0010c27\u0011 מִמָּקוֹם אַחֵר, וְאֵינוֹ מַפְרִישׁ עָלָיו תְּרוּמָה, שֶׁהַתּוֹרֵם מִתְּחִלָּה בְּלִבּוֹ עַל הַכֹּל. וְאִם מָצָא פָּחוֹת מֵאַרְבַּע, אַף עַל פִּי שֶׁמָּצָא יָתֵר עַל מִדָּתוֹ, וְאַף עַל פִּי שֶׁיֵּשׁ בָּהֶם טַעַם יַיִן, \u0010y109\u0011 פָּטוּר.\nפֵּרוֹת שֶׁהִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת וְנִתְלְשׁוּ, וַעֲדַיִן לֹא נִגְמְרָה מְלָאכְתָן, כְּגוֹן תְּבוּאָה שֶׁקְּצָרָהּ וְדָשָׁהּ, וַעֲדַיִן לֹא זָרָה אוֹתָהּ וְלֹא מֵרְחָהּ, מֻתָּר לֶאֱכֹל מֵהֶם אֲכִילַת עֲרַאי עַד שֶׁתִּגָּמֵר מְלָאכְתָן, וּמִשֶּׁתִּגָּמֵר מְלָאכְתָן אָסוּר לֶאֱכֹל מֵהֶם עֲרַאי. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּגוֹמֶר פֵּירוֹתָיו לְמָכְרָן בַּשּׁוּק. אֲבָל אִם הָיְתָה כַּוָנָתוֹ לְהוֹלִיכָן לַבַּיִת, הֲרֵי זֶה מֻתָּר לֶאֱכֹל מֵהֶם עֲרַאי אַחַר שֶׁנִּגְמְרָה מְלָאכְתָן, \u0010y110\u0011 עַד שֶׁיִּקָּבְעוּ לְמַעֲשֵׂר.\nאֶחָד מִו' דְּבָרִים קוֹבֵעַ הַפֵּרוֹת לְמַעַשְׂרוֹת: \u0010y111\u0011 הֶחָצֵר, וְהַמִּקָּח, וְהָאֵשׁ, וְהַמֶּלַח, וְהַתְּרוּמָה, וְהַשַּׁבָּת. וְכֻלָּם אֵין קוֹבְעִין אֶלָּא בְּדָבָר שֶׁנִּגְמְרָה מְלַאכְתָּם. כֵּיצַד, פֵּרוֹת שֶׁדַּעְתּוֹ לְהוֹלִיכָן לַבַּיִת, אַף עַל פִּי שֶׁנִּגְמְרָה מְלָאכְתָן, אוֹכֵל מֵהֶם אֲכִילַת עֲרַאי עַד שֶׁיִּכָּנְסוּ לַבַּיִת שֶׁלּוֹ. נִכְנְסוּ לַבַּיִת שֶׁלּוֹ, נִקְבְּעוּ לְמַעַשְׂרוֹת \u0010y112\u0011 וְאָסוּר לֶאֱכֹל מֵהֶם עַד שֶׁיְּעַשֵּׂר. וּכְשֵׁם שֶׁהַבַּיִת קוֹבֵעַ לְמַעֲשֵׂר, כָּךְ הֶחָצֵר קוֹבֵעַ לְמַעֲשֵׂר, שֶׁאִם נִכְנְסוּ הַפֵּרוֹת לֶחָצֵר דֶּרֶךְ הַשַּׁעַר, נִקְבְּעוּ אַף עַל פִּי שֶׁלֹּא נִכְנְסוּ לְתוֹךְ הַבַּיִת. וְכֵן אִם מְכָרָן, אוֹ בִּשְּׁלָן בְּאוּר, אוֹ כְּבָשָׁן בְּמֶלַח, אוֹ הִפְרִישׁ בָּהֶם תְּרוּמָה, אוֹ נִכְנְסָה שַׁבָּת עֲלֵיהֶם, לֹא יֹאכַל עַד שֶׁיְּעַשֵּׂר, אַף עַל פִּי שֶׁלֹּא הִגִּיעוּ לַבַּיִת. הִכְנִיסָן לַבַּיִת קֹדֶם שֶׁתִּגָּמֵר מְלָאכְתָן, הֲרֵי זֶה אוֹכֵל מֵהֶם עֲרַאי. הִתְחִיל \u0005(לִגְמֹר)\u0006 מְלָאכְתָן, מֵאַחַר שֶׁנִּכְנְסוּ לַבַּיִת, חַיָּב לְעַשֵּׂר הַכֹּל. כֵּיצַד, הִכְנִיס קִשּׁוּאִין וְדִילוּעִין קֹדֶם שֶׁיְּשַׁפְשֵׁף, מִשֶּׁיַּתְחִיל לְשַׁפְשֵׁף אַחַת נִקְבְּעוּ הַכֹּל לְמַעֲשֵׂר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן הַתּוֹרֵם פֵּרוֹת שֶׁלֹּא נִגְמְרָה מְלָאכְתָן, מֻתָּר לֶאֱכֹל מֵהֶם עֲרַאי, חוּץ מִכַּלְכָּלַת תְּאֵנִים, שֶׁאִם תְּרָמָהּ קֹדֶם שֶׁתִּגָּמֵר מְלַאכְתָּהּ נִקְבְּעָה לְמַעֲשֵׂר. \u0010y113\u0011\nמֻתָּר לְהַעֲרִים עַל הַתְּבוּאָה לְהַכְנִיסָהּ בְּמוֹץ, כְּדֵי שֶׁתִּהְיֶה בְּהֶמְתּוֹ אוֹכֶלֶת וּפְטוּרָה מִן הַמַּעֲשֵׂר. וְזוֹרֶה מְעַט מְעַט אַחַר שֶׁהִכְנִיס לַבַּיִת, וּפָטוּר לְעוֹלָם מִן הַתְּרוּמָה וּמִן הַמַּעַשְׂרוֹת, שֶׁהֲרֵי אֵינוֹ מַתְחִיל לִגְמֹר הַכֹּל. \u0010y114\u0011\nהַגּוֹמֵר פֵּירוֹתָיו שֶׁל חֲבֵרוֹ שֶׁלֹּא מִדַּעְתּוֹ, הֲרֵי אֵלּוּ טָבְלוּ לְמַעֲשֵׂר.\nאֵיזֶהוּ גְּמַר מְלֶאכֶת הַיַּיִן, מִשֶּׁיַּנִּיחֶנּוּ בְּחָבִית וְיִשְׁלֶה הַחַרְצַנִּין וְהַזַּגִּין מֵעַל פִּי הֶחָבִית. אֲבָל כְּשֶׁהוּא בְּתוֹךְ הַבּוֹר, כְּשֶׁיַּגְבִּיהֶנּוּ לְהַעֲמִידוֹ בֶּחָבִית, שׁוֹתֶה עֲרַאי וְקוֹלֵט מִן הַגַּת הַעֶלְיוֹנָה וּמִן הַצִּנּוֹר וּמִכָּל מָקוֹם, וְשׁוֹתֶה.\nכֵּיצַד הִיא אֲכִילַת עֲרַאי, כְּגוֹן שֶׁהָיָה מְקַלֵּף שְׂעוֹרִים וְאוֹכֵל, מְקַלֵּף אַחַת אַחַת וְאִם קִלֵּף וְכִנֵּס לְתוֹךְ יָדוֹ, חַיָּב לְעַשֵּׂר. \u0005(הָיָה מוֹלֵל מְלִילוֹת שֶׁל חִטִּים, מְנַפֶּה מִיָּד לְיָד וְאוֹכֵל וְאִם נִפָּה לְתוֹךְ חֵיקוֹ, חַיָּב לְעַשֵּׂר)\u0006. וְכֵן נוֹטֵל מִן הַיַּיִן וְנוֹתֵן לִקְעָרָה לְתוֹךְ תַּבְשִׁיל צוֹנֵן, וְאוֹכֵל; אֲבָל לֹא לְתוֹךְ הַקְּדֵרָה, אַף עַל פִּי שֶׁהִיא צוֹנֶנֶת, מִפְּנֵי שֶׁהִיא כְּבוֹר קָטָן. וְכֵן סוֹחֵט זֵיתִים עַל בְּשָׂרוֹ, אֲבָל לֹא לְתוֹךְ יָדוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה.\nכְּשֵׁם שֶׁמֻּתָּר לֶאֱכֹל עֲרַאי מִפֵּרוֹת שֶׁלֹּא נִגְמְרָה מְלָאכְתָן, כָּךְ מֻתָּר לְהַאֲכִיל מֵהֶם לְחַיָּה, לִבְהֵמָה וּלְעוֹפוֹת, כָּל מַה שֶּׁיִּרְצֶה, וּמַפְקִיר מֵהֶם כָּל מַה שֶּׁיִּרְצֶה, קֹדֶם שֶׁיְּעַשֵּׂר. וְאִם גָּמְרוּ, אַף עַל פִּי שֶׁלֹּא נִקְבְּעוּ לְמַעֲשֵׂר, \u0010y115\u0011 לֹא יַפְקִיר וְלֹא יַאֲכִיל לִבְהֵמָה וּלְחַיָּה וּלְעוֹפוֹת אֲכִילַת קֶבַע, עַד שֶׁיְּעַשֵּׂר. וּמֻתָּר לְהַאֲכִיל לִבְהֵמָה עֲרַאי מִן הַטֶּבֶל, וַאֲפִלּוּ בְּתוֹךְ הַבַּיִת, וּמַאֲכִילָה פְּקִיעֵי \u0005(פֵּרוּשׁ עֳמָרִים שֶׁל תְּבוּאָה הַמֻּנָּחִים בְּקַשׁ)\u0006 עָמִיר עַד שֶׁיַּעֲשֵׂם חֲבִילוֹת.\nתְּאֵנָה הָעוֹמֶדֶת בְּחָצֵר, אוֹכֵל מִמֶּנָּהּ אַחַת אַחַת, וּפָטוּר. וְאִם צֵרֵף, חַיָּב בְּמַעֲשֵׂר. בַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיָה עוֹמֵד בַּקַּרְקַע. אֲבָל אִם עָלָה לְרֹאשׁ הַתְּאֵנָה, מְמַלֵּא חֵיקוֹ וְאוֹכֵל שָׁם, שֶׁאֵין אֲוִיר חָצֵר קוֹבֵעַ לְמַעֲשֵׂר.\nהָיְתָה עוֹמֶדֶת בֶּחָצֵר וְנוֹטָה לַגִּנָּה, הֲרֵי זֶה אוֹכֵל מִמֶּנָּהּ בַּגִּנָּה כְּדַרְכּוֹ, כְּאִלּוּ הָיְתָה נְטוּעָה בַּגִּנָּה. הָיְתָה נְטוּעָה בַּגִּנָּה וְנוֹטָה לֶחָצֵר, הֲרֵי זֶה כִּנְטוּעָה בְּחָצֵר שֶׁאֵינוֹ אוֹכֵל שָׁם אֶלָּא אַחַת אַחַת.\nגֶּפֶן שֶׁנְּטוּעָה בֶּחָצֵר, לֹא יִטֹּל אֶת כָּל הָאֶשְׁכּוֹל כְּאֶחָד וְיֹאכַל, אֶלָּא מְגַרְגֵּר אַחַת אַחַת. וְכֵן בְּרִמּוֹן, לֹא יִטֹּל אֶת כָּל הָרִמּוֹן, אֶלָּא פּוֹרֵט אֶת הָרִמּוֹן בָּאִילָן, וְאוֹכֵל הַפֶּרֶט מִשָּׁם. וְכֵן בַּאֲבַטִּיחַ, סוֹפְתוֹ \u0005(פי' חוֹתְכוֹ)\u0006 בַּקַּרְקַע, וְאוֹכְלוֹ שָׁם.\nהָיָה אוֹכֵל בְּאֶשְׁכּוֹל בַּגִּנָּה, וְנִכְנַס מִן הַגִּנָּה לֶחָצֵר, אַף עַל פִּי שֶׁיָּצָא מִן הֶחָצֵר לֹא יִגְמֹר עַד שֶׁיְּעַשֵּׂר.\nכֻּסְבָּר הַזָּרוּעַ בְּחָצֵר, מְקַרְסֵם עָלֶה עָלֶה וְאוֹכְלוֹ; וְאִם צֵרֵף, חַיָּב לְעַשֵּׂר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0010y116\u0011\nהַלּוֹקֵחַ פֵּרוֹת תְּלוּשִׁין לְאָכְלָן, נִקְבְּעוּ לְמַעֲשֵׂר, כְּמוֹ שֶׁנִּתְבָּאֵר. וּמֵאֵימָתַי יִקָּבְעוּ, מִשֶּׁיִּתֵּן דָּמִים, \u0010y117\u0011 אַף עַל פִּי שֶׁלֹּא מָשַׁךְ.\nהֲרֵי שֶׁלֹּא נָתַן דָּמִים וְהָיָה בּוֹרֵר וּמַנִּיחַ, בּוֹרֵר וּמַנִּיחַ, אֲפִלּוּ כָּל הַיּוֹם כֻּלּוֹ, וְאַף עַל פִּי שֶׁגָּמַר בְּלִבּוֹ לִקַּח, לֹא נִתְחַיֵּב לְעַשֵּׂר. וְאִם הָיָה יְרֵא שָׁמַיִם, מִשֶּׁגָּמַר בְּלִבּוֹ מְעַשֵּׂר וְאַחַר כָּךְ יַחֲזִיר לַמּוֹכֵר, אִם רָצָה לְהַחֲזִיר.\nהַלּוֹקֵחַ בִּמְחֻבָּר לַקַּרְקַע, אוֹ שֶׁלָּקַח תָּלוּשׁ \u0010y118\u0011 לִשְׁלֹחַ לַחֲבֵרוֹ, לֹא נִקְבְּעוּ, וְיֵשׁ לוֹ לֶאֱכֹל מֵהֶם עֲרַאי.\nהָאוֹמֵר לַחֲבֵרוֹ: הֵא לְךָ אִיסָר זֶה וְתֵן לִי בּוֹ ה' תְּאֵנִים, הֲרֵי זֶה אוֹכֵל אַחַת אַחַת, וּפָטוּר. וְאִם צֵרֵף, חַיָּב לְעַשֵּׂר. הֵא לְךָ אִיסָר זֶה בְּעֶשְׂרִים תְּאֵנִים שֶׁאָבֹר לִי, בּוֹרֵר אַחַת אַחַת, וְאוֹכֵל. בְּאֶשְׁכּוֹל שֶׁאָבֹר לִי, מְגֻרְגָּר מִמֶּנּוּ בָּאִילָן, וְאוֹכֵל. בְּרִמּוֹן שֶׁאָבֹר לִי, פּוֹרְטוֹ בָּאִילָן, וְאוֹכֵל. בַּאֲבַטִּיחַ שֶׁאָבֹר לִי, סוֹפֵת בַּקַּרְקַע, וְאוֹכֵל. וְאִם קָצַץ אֶת הַתְּאֵנִים וְצֵרְפָם, אוֹ שֶׁקָּצַץ הָאֶשְׁכּוֹל אוֹ הָאֲבַטִּיחַ, חַיָּב לְעַשֵּׂר, שֶׁהֲרֵי לֹא קָנָה אֶלָּא הַנִּתְלָשׁ. אֲבָל אִם אָמַר לֵיהּ: הֵא לְךָ אִיסָר בְּעֶשְׂרִים תְּאֵנִים אֵלּוּ, בִּשְׁנֵי אֶשְׁכּוֹלוֹת אֵלּוּ, בִּשְׁנֵי רִמּוֹנִים אֵלּוּ, בִּשְׁנֵי אֲבַטִּיחִים אֵלּוּ קוֹצֵץ כְּדַרְכּוֹ, וְאוֹכֵל עֲרַאי, וּפָטוּר; שֶׁלֹּא נִקְבְּעוּ בַּמִּקָּח, \u0010y119\u0011 שֶׁהֲרֵי לְקָחָן בִּמְחֻבָּר.\nהַמַּחֲלִיף עִם חֲבֵרוֹ, זֶה לֶאֱכֹל וְזֶה לֶאֱכֹל, שְׁנֵיהֶם נִקְבְּעוּ לְמַעַשְׂרוֹת, שֶׁהֲרֵי לָקְחוּ בְּתָלוּשׁ. \u0010y120\u0011 זֶה לַקְצוֹת וְזֶה לַקְצוֹת, שְׁנֵיהֶם לֹא נִקְבְּעוּ, שֶׁאֵין הַמֶּכֶר קוֹבֵעַ דָּבָר שֶׁלֹּא נִגְמְרָה מְלַאכְתּוֹ. לָקַח הָאֶחָד פֵּרוֹת שֶׁהֶחֱלִיף, לַאֲכִילָה, וְלָקַח הָאֶחָד חֲלִיפֵיהֶן לְהַקְצוֹתָן, זֶה שֶׁלָּקַח לַאֲכִילָה חַיָּב לְעַשֵּׂר, וְזֶה שֶׁלָּקַח לְהַקְצוֹת לֹא נִקְבַּע לְמַעֲשֵׂר.\nעַם הָאֶרֶץ שֶׁהָיָה עוֹבֵר בַּשּׁוּק וְאָמַר: טְלוּ לָכֶם תְּאֵנִים, אוֹכְלִים \u0010y121\u0011 וּפְטוּרִים, שֶׁאֵין הַמַּתָּנָה קוֹבַעַת.\nהַשּׂוֹכֵר אֶת הַפּוֹעֲלִים לַעֲשׂוֹת עִמּוֹ בַּפֵּרוֹת, בֵּין בִּתְלוּשִׁין בֵּין בִּמְחֻבָּרִין, הוֹאִיל וְיֵשׁ לָהֶם לֶאֱכֹל מִן הַתּוֹרָה בַּמֶּה שֶׁהֵם עוֹשִׂים, הֲרֵי אֵלּוּ אוֹכְלִים \u0010y122\u0011 וּפְטוּרִין מִן הַמַּעֲשֵׂר. וְאִם הִתְנָה עִמָּהֶם שֶׁיֹּאכְלוּ מַה שֶּׁלֹּא זִכְּתָה לָהֶם תּוֹרָה, כְּגוֹן שֶׁהִתְנָה הַפּוֹעֵל שֶׁיֹּאכְלוּ בָּנָיו עִמּוֹ, אוֹ שֶׁיֹּאכַל בְּנוֹ בִּשְׂכָרוֹ, אוֹ שֶׁיֹּאכַל אַחַר גְּמַר מְלַאכְתּוֹ בְּתָלוּשׁ, הֲרֵי זֶה אָסוּר לֶאֱכֹל עַד שֶׁיְּעַשֵּׂר, הוֹאִיל וְאוֹכֵל מִפְּנֵי הַתְּנַאי הֲרֵי זֶה כְּלוֹקֵחַ.\nהַמּוֹצִיא פּוֹעֲלִים לַעֲשׂוֹת לוֹ מְלָאכָה בַּשָּׂדֶה, \u0010y123\u0011 בִּזְמַן שֶׁאֵין לָהֶם עָלָיו מְזוֹנוֹת, אוֹכְלִים מִפֵּרוֹת שֶׁבַּשָּׂדֶה \u0010y124\u0011 וּפְטוּרִים מִן הַמַּעֲשֵׂר. וְהוּא שֶׁלֹּא נִגְמְרָה מְלָאכְתָן. אֲבָל אִם יֵשׁ לָהֶם עָלָיו מְזוֹנוֹת, לֹא יֹאכְלוּ, וְאַף עַל פִּי שֶׁלֹּא נִגְמְרָה מְלָאכְתָן, שֶׁאֵין פּוֹרְעִין חוֹב מִן הַטֶּבֶל. \u0005(אֲבָל)\u0006 אוֹכְלִים אַחַת אַחַת מֵהַתְּאֵנָה, אֲבָל לֹא מִן הַסַל וְלֹא מִן הַקֻּפָּה וְלֹא מִן הַמֻּקְצֶה.\nאֶחָד הַמְבַשֵּׁל וְאֶחָד הַשּׁוֹלֵק וְאֶחָד הַכּוֹבֵשׁ, קוֹבֵעַ לְמַעֲשֵׂר. אֲבָל הַמְעַשֵּׁן אֶת הַפֵּרוֹת עַד שֶׁהִכְשִׁירָן, \u0010y125\u0011 הֲרֵי זֶה סָפֵק.\nהַטּוֹמֵן פֵּרוֹת בָּאֲדָמָה, אוֹ בַּזֶּבֶל, אוֹ בַּתֶּבֶן, עַד שֶׁהִכְשִׁירָם לַאֲכִילָה לֹא נִקְבְּעוּ לְמַעֲשֵׂר.\nהַנּוֹתֵן יַיִן לְתַבְשִׁיל חַם, אוֹ שֶׁנָּתַן שֶׁמֶן לִקְדֵרָה בְּאִלְפָּס, כְּשֶׁהֵן מְרֻתָּחִין, נִקְבְּעוּ לְמַעֲשֵׂר.\nמָזַג יַיִן בְּמַיִם חַמִּין, נִקְבַּע. וְאֵין צָרִיךְ לוֹמַר אִם בִּשֵּׁל הַיַּיִן. וַאֲפִלּוּ בְּגַת אָסוּר לִשְׁתּוֹת מִמֶּנּוּ עַד שֶׁיְּעַשֵּׂר.\nהַסוֹחֵט אֶשְׁכּוֹל לְתוֹךְ הַכּוֹס, נִקְבָּע. לְתוֹךְ הַתַּמְחוּי, אֵינוֹ נִקְבָּע.\nהַמּוֹלֵחַ פֵּרוֹת בַּשָּׂדֶה, נִקְבְּעוּ. טָבַל הַזֵּיתִים אַחַת אַחַת בְּמֶלַח וְאָכַל, פָּטוּר.\nהַפּוֹצֵעַ זֵיתִים כְּדֵי שֶׁיֵּצֵא הַשָּׂרָף מֵהֶם, פָּטוּר.\nהַנּוֹטֵל זֵיתִים מֵהַמַּעֲטָן, טוֹבֵל אַחַת אַחַת בְּמֶלַח וְאוֹכֵל. וְאִם מָלַח וְנָתַן לְפָנָיו, חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה.\nהַתּוֹרֵם פֵּרוֹת תְּרוּמָה שֶׁצָּרִיךְ לִתְרֹם אַחֲרֶיהָ שְׁנִיָּה, נִקְבָּע לְמַעֲשֵׂר, וְלֹא יֹאכַל מֵהֶם עֲרַאי עַד שֶׁיּוֹצִיא הַתְּרוּמָה שְׁנִיָּה וִיעַשֵּׂר.\nפֵּרוֹת שֶׁנִּגְמְרָה מְלָאכְתָן וְחָשְׁכָה עֲלֵיהֶם לֵיל שַׁבָּת, \u0010y126\u0011 נִקְבְּעוּ, וְלֹא יֹאכַל מֵהֶם, אֲפִלּוּ לְאַחַר הַשַּׁבָּת, עַד שֶׁיְּעַשֵּׂר.\nתִּינוֹקוֹת שֶׁטָּמְנוּ תְּאֵנִים לְשַׁבָּת וְשָׁכְחוּ לְעַשְּׂרָן, \u0010y127\u0011 לֹא יֹאכְלוּ לְמוֹצָאֵי שַׁבָּת עַד שֶׁיְּעַשְּׂרוּ.\nתְּאֵנָה שֶׁהָיְתָה מְיֻחֶדֶת לוֹ לֶאֱכֹל פֵּירוֹתֶיהָ בְּשַׁבָּת, וְלִקֵּט מִמֶּנָּהּ כַּלְכָּלָה, \u0010y128\u0011 לֹא יֹאכַל עַד שֶׁיְּעַשֵּׂר, הוֹאִיל וּפֵרוֹת אֵלּוּ מְיֻחָדִים לְשַׁבָּת וְהַשַּׁבָּת קוֹבַעַת.\nהָיָה אוֹכֵל בָּאֶשְׁכּוֹל וְחָשְׁכָה עָלָיו לֵיל שַׁבָּת, לֹא יִגְמֹר אֲכִילָתוֹ בְּשַׁבָּת עַד שֶׁיְּעַשֵּׂר. וְאִם הִנִּחָן לְאַחַר הַשַּׁבָּת, \u0010y129\u0011 הֲרֵי זֶה גּוֹמְרוֹ.\nכָּל שֶׁאָסוּר לְזָרִים לֶאֱכֹל בִּתְרוּמָה, כְּגוֹן הַגַּרְעִינִין וְכַיּוֹצֵא בָּהֶן, כָּךְ אָסוּר לְאָכְלוֹ מֵהַטֶּבֶל וְהַמַּעֲשֵׂר שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ וּמַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ. וְכָל שֶׁמֻּתָּר לְזָרִים לְאָכְלוֹ בִּתְרוּמָה, מִדְּבָרִים אֵלּוּ, כָּךְ מֻתָּר בְּטֶבֶל וּמַעֲשֵׂר שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ וּמַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ.\nאֵין מַּדְלִיקִין \u0010y130\u0011 בְּטֶבֶל טָמֵא. אֵין מְחַפִּין בַּטֶּבֶל. וְאֵין זוֹרְעִין אֶת הַטֶּבֶל. וַאֲפִלּוּ פֵּרוֹת שֶׁלֹּא נִגְמְרָה מְלָאכְתָן אָסוּר לִזְרֹעַ מֵהֶם עַד שֶׁיְּעַשֵּׂר. \u0010y131\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, בִּתְבוּאָה וְקִטְנִיּוֹת וְכַיּוֹצֵא בָּהֶן, אֲבָל הָעוֹקֵר שְׁתָלִים שֶׁיֵּשׁ בָּהֶם פֵּרוֹת מִמָּקוֹם לְמָקוֹם בְּתוֹךְ שָׂדֵהוּ, הֲרֵי זֶה מֻתָּר, וְאֵינוֹ כְּזוֹרֵעַ טֶבֶל, שֶׁהֲרֵי לֹא אָסַף הַפֵּרוֹת. וְכֵן הָעוֹקֵר לֶפֶת וּצְנוֹנוֹת וּשְׁתָלָם בְּמָקוֹם אַחֵר, \u0010y132\u0011 אִם נִתְכַּוֵּן לְהוֹסִיף בְּגוּפָן, מֻתָּר. וְאִם שְׁתָלָם כְּדֵי שֶׁיִּקְשׁוּ וְיִקַּח הַזֶּרַע שֶׁלָּהֶם, \u0010y133\u0011 אָסוּר, מִפְּנֵי שֶׁהוּא כְּזוֹרֵעַ חִטִּים אוֹ שְׂעוֹרִים שֶׁל טֶבֶל. \u0010y134\u0011\nאֵין מוֹכְרִין טֶבֶל אֶלָּא לְצֹרֶךְ, וּלְחָבֵר. וְאָסוּר לִשְׁלֹח טֶבֶל, וַאֲפִלּוּ חָבֵר לְחָבֵר, שֶׁמָּא יִסְמְכוּ זֶה עַל זֶה וְיֹאכַל טֶבֶל.\nהַמּוֹכֵר פֵּרוֹת לַחֲבֵרוֹ, מוֹכֵר אוֹמֵר: עַל מְנַת שֶׁהֵם טֶבֶל מָכַרְתִּי, וְלוֹקֵחַ אָמַר: לֹא לָקַחְתִּי מִמְּךָ אֶלָּא \u0010y135\u0011 מְעֻשָּׂרוֹת, כּוֹפִין אֶת הַמּוֹכֵר לְתַקֵּן; קְנָס הוּא לוֹ, מִפְּנֵי שֶׁמָּכַר טֶבֶל.\nאֵין פּוֹרְעִין חוֹב מֵהַטֶּבֶל, מִפְּנֵי שֶׁהוּא כְּמוֹכְרוֹ.\nהַלּוֹקֵחַ טֶבֶל מִשְּׁנֵי מְקוֹמוֹת, מְעַשֵּׂר \u0010y136\u0011 מִזֶּה עַל זֶה. \u0010y137\u0011\nהַחוֹכֵר שָׂדֶה מֵהָעוֹבֵד כּוֹכָבִים, מְעַשֵּׂר וְנוֹתֵן לוֹ. וְהַמְקַבֵּל שְׂדֵה אֲבוֹתָיו מֵהָעוֹבֵד כּוֹכָבִים, מְעַשֵּׂר וְנוֹתֵן לוֹ.\nכֹּהֵן אוֹ לֵוִי שֶׁלָּקְחוּ פֵּרוֹת מִיִּשְׂרָאֵל אַחֵר שֶׁנִּגְמְרָה מְלָאכְתָן, \u0010y138\u0011 מוֹצִיאִין הַתְּרוּמָה וְהַמַּעַשְׂרוֹת מִידֵיהֶם וְנוֹתְנִים אוֹתָם לְכֹהֲנִים וְלִלְוִיִּם אֲחֵרִים.\nכֹּהֵן אוֹ לֵוִי שֶׁמָּכְרוּ פֵּרוֹת תְּלוּשִׁים, קֹדֶם שֶׁתִּגָּמֵר מְלָאכְתָן, וְאֵין צָרִיךְ לוֹמַר אִם מָכַר \u0010y139\u0011 בִּמְחֻבָּר, הֲרֵי הַתְּרוּמָה וְהַמַּעֲשֵׂר שֶׁלָּהֶם. \u0010y140\u0011\nהַנּוֹתֵן שָׂדֵהוּ בְּקַבָּלָה לְעוֹבֵד כּוֹכָבִים אוֹ לְמִי שֶׁאֵינוֹ נֶאֱמָן עַל הַמַּעַשְׂרוֹת, אַף עַל פִּי שֶׁלֹּא בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת \u0010y141\u0011 צָרִיךְ לְעַשֵּׂר עַל יָדָם. נְתָנָהּ לְעַם הָאָרֶץ, עַד שֶׁלֹּא בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת אֵינוֹ צָרִיךְ לְעַשֵּׂר עַל יָדָם. וּמִשֶּׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת, צָרִיךְ לְעַשֵּׂר עַל יָדָם. כֵּיצַד הוּא עוֹשֶׂה, עוֹמֵד עַל הַגֹּרֶן וְנוֹטֵל, וְאֵינוֹ חוֹשֵׁשׁ לְמַה שֶּׁאָכְלוּ, שֶׁאֵין אָנוּ אַחְרָאִים לָהֶם.\nבְּאֶחָד בְּתִשְׁרֵי הוּא רֹאשׁ הַשָּׁנָה לְמַעֲשַׂר תְּבוּאָה וְקִטְנִיּוֹת וִירָקוֹת. וּבְט\"וּ בִּשְׁבָט, הוּא רֹאשׁ הַשָּׁנָה לְמַעֲשַׂר הָאִילָנוֹת. כֵּיצַד, תְּבוּאָה וְקִטְנִיּוֹת שֶׁהִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת לִפְנֵי רֹאשׁ הַשָּׁנָה שֶׁל שְׁלִישִׁית, אַף עַל פִּי שֶׁנִּגְמְרוּ וְנֶאֶסְפוּ בַּשְּׁלִישִׁית, מַפְרִישִׁין מֵהֶן מַעֲשֵׂר שֵׁנִי. וְכֵן פֵּרוֹת הָאִילָן שֶׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת קֹדֶם ט\"וּ בִּשְׁבָט שֶׁל שְׁלִישִׁית, אַף עַל פִּי שֶׁנִּגְמְרוּ וְנֶאֶסְפוּ אַחַר כָּךְ בְּסוֹף שָׁנָה שְׁלִישִׁית, מִתְעַשְּׂרִין לְשֶׁעָבַר וּמַפְרִישִׁין מֵהֶם מַעֲשֵׂר שֵׁנִי. וְכֵן אִם בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת קֹדֶם ט\"וּ בִּשְׁבָט שֶׁל רְבִיעִית, אַף עַל פִּי שֶׁנִּגְמְרוּ וְנֶאֶסְפוּ בָּרְבִיעִית, מַפְרִישִׁין מֵהֶם מַעֲשֵׂר עָנִי. וְאִם בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת אַחַר ט\"וּ בִּשְׁבָט, מִתְעַשְּׂרִין לְהַבָּא. \u0010y142\u0011\nהַיָּרָק, בִּשְׁעַת לְקִיטָתוֹ עִשּׂוּרוֹ, כֵּיצַד, אִם נִלְקַט בְּיוֹם רֹאשׁ הַשָּׁנָה שֶׁל שְׁלִישִׁית, אַף עַל פִּי שֶׁבָּא לְעוֹנַת הַמַּעַשְׂרוֹת וְנִגְמַר בַּשְּׁנִיָּה, מַפְרִישִׁין מִמֶּנּוּ מַעֲשַׂר עָנִי. \u0010y143\u0011 וְאִם נִלְקַט בָּרְבִיעִית, מַעֲשֵׂר שֵׁנִי. וְכֵן הָאֶתְרוֹג, בִּלְבַד מִשְּׁאָר פֵּרוֹת הָאִילָן, \u0010y144\u0011 הֲרֵי הוּא כְּיָרָק וְהוֹלְכִין אַחַר לְקִיטָתוֹ, בֵּין לְמַעֲשֵׂר בֵּין לִשְׁבִיעִית. כֵּיצַד, אִם נִלְקַט בַּשְּׁלִישִׁית אַחַר ט\"וּ בִּשְׁבָט, מַפְרִישִׁין מִמֶּנּוּ מַעֲשַׂר עָנִי \u0010y145\u0011 אַף עַל פִּי שֶׁנִּגְמְרָה בַּשְּׁנִיָּה. וְכֵן אִם נִלְקַט בָּרְבִיעִית קֹדֶם ט\"וּ בִּשְׁבָט, מַפְרִישִׁין מִמֶּנּוּ מַעֲשַׂר עָנִי. נִלְקַט בָּהּ אַחַר ט\"וּ בִּשְׁבָט, מַפְרִישִׁין מִמֶּנּוּ מַעֲשֵׂר שֵׁנִי. וְאַף עַל פִּי שֶׁהוֹלְכִין אַחַר לְקִיטָתוֹ, אֶתְרוֹג בַּת שִׁשִּׁית \u0010c28\u0011 שֶׁנִּכְנְסָה לַשְּׁבִיעִית, אֲפִלּוּ הָיְתָה כַּזַּיִת וְנַעֲשֵׂית כַּכִּכָּר, חַיֶּבֶת בְּמַעַשְׂרוֹת. \u0010c29\u0011\nהָאֶבְיוֹנוֹת שֶׁל צָלָף נוֹתְנִין עֲלֵיהֶם חָמְרֵי הָאִילָן וְחָמְרֵי זְרָעִים, שֶׁאִם הָיוּ מִשָּׁנָה שְׁנִיָּה שֶׁנִּכְנְסָה לַשְּׁלִישִׁית וְנִלְקְטוּ קֹדֶם ט\"וּ בִּשְׁבָט, מַפְרִישִׁין מַעֲשֵׂר רִאשׁוֹן וְאַחַר כָּךְ מַפְרִישׁ מַעֲשֵׂר אַחֵר וּפוֹדֶהוּ, \u0010y146\u0011 וְאַחֵר שֶׁפּוֹדֶהוּ נוֹתְנוֹ לַעֲנִיִּים.\nפֵּרוֹת שָׁנָה שְׁנִיָּה שֶׁנִּתְעָרְבוּ בְּפֵרוֹת שְׁלִישִׁית, אוֹ שֶׁל שְׁלִישִׁית בָּרְבִיעִית, הוֹלְכִים אַחַר הָרֹב. מֶחֱצָה לְמֶחֱצָה, מַפְרִישִׁין מַעֲשֵׂר שֵׁנִי מִן הַכֹּל, אֲבָל לֹא מַעֲשַׂר עָנִי, שֶׁמַּעֲשֵׂר שֵׁנִי חָמוּר, שֶׁהֲרֵי הוּא קָדוֹשׁ, וּמַעֲשַׂר עָנִי חֹל. וְכֵן פֵּרוֹת שֶׁהֵן סָפֵק אִם פֵּרוֹת שְׁנִיָּה הֵם אוֹ פֵּרוֹת שְׁלִישִׁית, מַפְרִישׁ מֵהֶם מַעֲשֵׂר שֵׁנִי.\nכָּל הַפָּטוּר מִמַּעֲשֵׂר רִאשׁוֹן, פָּטוּר מִמַּעֲשֵׂר שֵׁנִי וּמִן הֶעָנִי. וְכָל שֶׁחַיָּב בָּרִאשׁוֹן, חַיָּב בִּשְׁנֵיהֶם. וְכָל הַתּוֹרֵם מוֹצִיא מַעֲשֵׂר. וְכָל שֶׁאֵינוֹ תּוֹרֵם, אֵינוֹ מוֹצִיא מַעֲשֵׂר. וְכָל מִי שֶׁאִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה, כָּךְ אִם עִשֵּׂר הֲרֵי הוּא מַעֲשֵׂר. וְכָל מִי שֶׁאֵין תְּרוּמָתוֹ תְּרוּמָה, כָּךְ אִם הוֹצִיא מַעֲשֵׂר אֵינוֹ מַעֲשֵׂר.\nפֵּרוֹת שֶׁהוֹצִיא מֵהֶם מַעֲשֵׂר רִאשׁוֹן קֹדֶם שֶׁיִּקָּבְעוּ לְמַעֲשֵׂר, הֲרֵי זֶה אוֹכֵל מֵהֶם עֲרַאי קֹדֶם שֶׁיּוֹצִיא מַעֲשֵׂר שֵׁנִי, שֶׁאֵין הָרִאשׁוֹן קוֹבֵעַ לַשֵּׁנִי. אֲבָל מִשֶּׁנִּקְבְּעוּ לְמַעֲשֵׂר, אַף עַל פִּי שֶׁהוֹצִיא אֶת הָרִאשׁוֹן, אָסוּר לֶאֱכֹל מֵהֶם עֲרַאי עַד שֶׁיּוֹצִיא אֶת הַשֵּׁנִי אוֹ אֶת מַעֲשַׂר עָנִי. \u0010y147\u0011\nלֹא חִיְּבוּ לְהַפְרִישׁ מַעֲשֵׂר שֵׁנִי בְּסוּרְיָא.\nמַעֲשֵׂר שֵׁנִי נֶאֱכָל לִבְעָלָיו לִפְנִים מֵחוֹמַת יְרוּשָׁלַיִם, שֶׁנֶּאֱמַר: וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךָ בַּמָּקוֹם אֲשֶׁר יִבְחַר וגו' \u0005(דְּבָרִים יד, כג)\u0006 וְנוֹהֵג בִּפְנֵי הַבַּיִת וְשֶׁלֹּא בִּפְנֵי הַבַּיִת, אֲבָל אֵינוֹ נֶאֱכָל בִּירוּשָׁלַיִם אֶלָּא בִּפְנֵי הַבַּיִת, שֶׁנֶּאֱמַר: מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ וּבְכֹרֹת בְּקָרְךָ וְצֹאנֶךָ \u0005(דְּבָרִים יד, כג)\u0006. מִפִּי הַשְּׁמוּעָה לָמְדוּ, מַה בְּכוֹר אֵינוֹ נֶאֱכָל אֶלָּא בִּפְנֵי הַבַּיִת, אַף מַעֲשֵׂר שֵׁנִי לֹא יֵאָכֵל אֶלָּא בִּפְנֵי הַבַּיִת. \u0010y148\u0011\nבַּזְּמַן הַזֶּה, אִם רָצָה לִפְדּוֹת מַעֲשֵׂר שֵׁנִי שְׁוֵה מָנֶה בִּפְרוּטָה, לְכַתְּחִלָּה, פּוֹדֶה וּמַשְׁלִיךְ הַפְּרוּטָה לַיָּם הַגָּדוֹל; אֲבָל לִשְׁאָר נְהָרוֹת צָרִיךְ לְשָׁחֲקָהּ תְּחִלָּה. וְכֵן אִם חִלֵּל \u0005(פֵּרוּשׁ אִם עֲשָׂאוֹ חֻלִּין עַל יְדֵי פִּדְיוֹן)\u0006 מַעֲשֵׂר שְׁוֵה מָנֶה עַל שְׁוֵה פְּרוּטָה מִפֵּרוֹת אֲחֵרוֹת, הֲרֵי זֶה מְחֻלָּל, וְשׂוֹרֵף אֶת הַפֵּרוֹת שֶׁחִלֵּל עֲלֵיהֶם, כְּדֵי שֶׁלֹּא יִהְיוּ תַּקָּלָה לַאֲחֵרִים.\nוְשִׁעוּר פְּרוּטָה, כַּחֲצִי שְׂעוֹרָה כֶּסֶף מְזֻקָּק, שֶׁהוּא חֵלֶק מִל\"ב בְּמָעָה כֶּסֶף שֶׁהוּא אשפיר\"ו עוטומאני שֶׁמִּשְׁקָלוֹ רְבִיעִית דִּרְהֶ\"ם, נִמְצָא שֶׁהַפְּרוּטָה חֵלֶק מִמ\"ח בְּקִטְעָא וְיוֹתֵר מְעַט. וְצָרִיךְ לְדַקְדֵּק שֶׁהַפֵּרוֹת שֶׁמְּחַלֵּל עֲלֵיהֶם מַעֲשֵׂר שֵׁנִי שֶׁיִּשְׁווּ כָּךְ לְפָחוֹת. \u0010y149\u0011 \u0005וְעַיֵּן לְעֵיל סִימָן רצ\"ד (סָעִיף ו')\u0006. \u0010y150\u0011\nכְּשֵׁם שֶׁאֵין אוֹכְלִים מַעֲשֵׂר שֵׁנִי בַּזְּמַן הַזֶּה בִּירוּשָׁלַיִם, כָּךְ אֵין פּוֹדִין אוֹתוֹ שָׁם, וְאֵין מְחַלְּלִין אוֹתוֹ, וְאֵין מוֹכְרִים אוֹתוֹ. וְאִם נִכְנָס בִּירוּשָׁלַיִם, אַף בַּזְּמַן הַזֶּה, אֵין מוֹצִיאִין אוֹתוֹ מִשָּׁם וּמַנִּיחִים אוֹתוֹ שָׁם עַד שֶׁיֵּרָקֵב. \u0005(וְכֵן אִם עָבַר וְהוֹצִיאוֹ מִשָּׁם, מַנִּיחִין אוֹתוֹ עַד שֶׁיֵּרָקֵב)\u0006. לְפִיכָךְ אֵין מַפְרִישִׁין מַעֲשֵׂר שֵׁנִי בִּירוּשָׁלַיִם בַּזְּמַן הַזֶּה, אֶלָּא מוֹצִיאִין אֶת הַפֵּרוֹת בְּטִבְלָן חוּץ לָעִיר, וּמַפְרִישִׁין אוֹתוֹ שָׁם, וּפוֹדֶהוּ. וְאִם הִפְרִישָׁן שָׁם בַּזְּמַן הַזֶּה, יֵרָקֵב. \u0010c30\u0011 בַּמֶּה דְּבָרִים אֲמוּרִים, בְּמַעֲשֵׂר שֵׁנִי שֶׁלֹּא נִטְמָא. אֲבָל אִם נִטְמָא, פּוֹדִין אוֹתוֹ בִּירוּשָׁלַיִם. \u0005וְיֵשׁ לְהַכְשִׁירוֹ כְּדֵי שֶׁיְּקַבֵּל טֻמְאָה וִיהֵא לוֹ הֶתֵּר בַּפִּדְיוֹן (טוּר)\u0006.\nהַפּוֹדֶה מַעֲשֵׂר שֵׁנִי אוֹמֵר: הַפֵּרוֹת הָאֵלּוּ מְחֻלָּלוֹת עַל מָעוֹת אֵלּוּ. וְאִם לֹא פֵּרֵשׁ, אֶלָּא הִפְרִישׁ מָעוֹת בִּלְבַד כְּנֶגֶד הַפֵּרוֹת, דַּיּוֹ, \u0010y151\u0011 וְאֵינוֹ צָרִיךְ לְפָרֵשׁ, \u0010y152\u0011 וְיֵצְאוּ הַפֵּרוֹת לְחֻלִּין.\nהַפּוֹדֶה מַעֲשֵׂר שֵׁנִי, מְבָרֵךְ: אקב\"ו עַל פִּדְיוֹן מַעֲשֵׂר שֵׁנִי. וְאִם חִלְּלָן עַל פֵּרוֹת אֲחֵרוֹת, מְבָרֵךְ: עַל חִלּוּל מַעֲשֵׂר שֵׁנִי. וְהַפּוֹדֶה אוֹ מְחַלֵּל מַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי, אֵינוֹ צָרִיךְ בְּרָכָה.\nאֵין פּוֹדִין מַעֲשֵׂר שֵׁנִי \u0010y153\u0011 אֶלָּא בְּכֶסֶף. וְכֵן אִם פָּדָה מַעֲשֵׂר שֵׁנִי שֶׁלּוֹ, שֶׁהוּא מוֹסִיף חֹמֶשׁ, לֹא יִהְיֶה הַחֹמֶשׁ אֶלָּא כֶּסֶף, כְּקֶרֶן. וְאֵין פּוֹדֶה בְּכֶסֶף שֶׁאֵינוֹ מַטְבֵּעַ, אֶלָּא בְּכֶסֶף \u0010y154\u0011 מְפֻתָּח שֶׁיֵּשׁ עָלָיו צוּרָה אוֹ כְּתָב; וְאִם פָּדָה בְּלָשׁוֹן שֶׁל כֶּסֶף וְכַיּוֹצֵא בוֹ, וְהוּא הַנִּקְרָא אֲסִימוֹן, לֹא עָשָׂה כְּלוּם. וְאֵין פּוֹדִין בְּפָחוֹת מִפְּרוּטָה, מִפְּנֵי שֶׁהוּא כְּפוֹדֶה בַּאֲסִימוֹן. \u0010y155\u0011 וְאֵין פּוֹדִין בְּמַטְבֵּעַ שֶׁאֵינוֹ יוֹצֵא בְּאוֹתוֹ זְמַן וּבְאוֹתוֹ מָקוֹם. \u0010y156\u0011 וְאֵינוֹ פּוֹדֶה בְּמָעוֹת שֶׁאֵינָם בִּרְשׁוּתוֹ. וְאֶפְשָׁר שֶׁאֵין דְּבָרִים אֵלּוּ אֲמוּרִים אֶלָּא בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם, אֲבָל עַכְשָׁו שֶׁאֵין מַעֲשֵׂר שֵׁנִי נֶאֱכָל, אֵין לְהַקְפִּיד בְּכָךְ. וּמִכָּל מָקוֹם יֵשׁ לָחוּשׁ בַּדָּבָר, וְאַף בַּזְּמַן הַזֶּה לֹא יִפְדֶּה מַעֲשֵׂר שֵׁנִי אֶלָּא עַל כֶּסֶף שֶׁיֵּשׁ בּוֹ מַטְבֵּעַ הַיּוֹצֵא, וְהוּא בִּרְשׁוּתוֹ, אוֹ יְחַלֵּל עַל פֵּרוֹת אֲחֵרִים.\nהַפּוֹדֶה מַעֲשֵׂר שֵׁנִי קֹדֶם שֶׁיַּפְרִישֶׁנּוּ, כְּגוֹן שֶׁאָמַר: מַעֲשֵׂר שֵׁנִי שֶׁל פֵּרוֹת פָּדוּי בְּמָעוֹת אֵלּוּ, לֹא אָמַר כְּלוּם, וְלֹא קָבַע מַעֲשֵׂר. אֲבָל אִם קָבַע וְאָמַר: מַעֲשֵׂר שֶׁהוּא בַּצָּפוֹן, אוֹ בַּדָּרוֹם, מְחֻלָּל עַל מָעוֹת אֵלּוּ, הֲרֵי זֶה פָּדוּי.\nמִצְוַת עֲשֵׂה לְהִתְוַדּוֹת לִפְנֵי ה' אַחַר שֶׁמּוֹצִיאִין כָּל הַמַּתָּנוֹת שֶׁבְּזֶרַע הָאֶרֶץ, וְזֶהוּ הַנִּקְרָא וִדּוּי מַעֲשֵׂר. \u0010y157\u0011 וְאֵין מִתְוַדִּין וִדּוּי זֶה אֶלָּא אַחַר הַשָּׁנָה שֶׁמַּפְרִישִׁין בָּהּ מַעֲשַׂר עָנִי.\nאֵימָתַי מִתְוַדִּין, בְּמִנְחָה, \u0010y158\u0011 בְּיוֹם טוֹב הָאַחֲרוֹן שֶׁל פֶּסַח שֶׁל רְבִיעִית, וּשְּׁבִיעִית.\nאֵין מִתְוַדִּין \u0010y159\u0011 אֶלָּא בַּיּוֹם. וְכָל הַיּוֹם כָּשֵׁר לְוִדּוּי הַמַּעֲשֵׂר. וּבֵין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת חַיָּב לְבַעֵר וּלְהִתְוַדּוֹת.\nוִדּוּי זֶה נֶאֱמָר בְּכָל לָשׁוֹן. \u0010y160\u0011 וְאִם רָצוּ רַבִּים לְהִתְוַדּוֹת כְּאֶחָד, מִתְוַּדִּים. \u0010y161\u0011\nאֵינוֹ מִתְוַדֶּה עַד שֶׁלֹּא יִשָּׁאֵר אֶצְלוֹ אַחַת מֵהַמַּתָּנוֹת. וְעֶרֶב יוֹם טוֹב הָאַחֲרוֹן הָיָה הַבִּעוּר, וּלְמָחָר מִתְוַדִּין, וּפֵרוֹת שֶׁלֹּא הִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת בִּשְׁעַת הַבִּעוּר, אֵין מְעַכְּבִין אוֹתוֹ לְהִתְוַדּוֹת, \u0010y162\u0011 וְאֵינוֹ חַיָּב לְבַעֲרָן. \u0010y163\u0011\nמִי שֶׁהָיוּ פֵּירוֹתָיו רְחוֹקִים מִמֶּנּוּ, וְהִגִּיעַ יוֹם הַבִּעוּר, הֲרֵי זֶה קוֹרֵא שֵׁם לַמַּתָּנוֹת וּמְזַכֶּה לָהֶן לְבַעֲלֵיהֶן עַל גַּבֵּי קַרְקַע, אוֹ לְמִי שֶׁזּוֹכֶה לָהֶן לְבַעֲלֵיהֶן, וּמִתְוַדֶּה לְמָחָר.\nאִם הִפְרִישׁ הַמַּתָּנוֹת שֶׁלֹּא עַל הַסֵדֶר, אוֹ אִם נִשְׂרַף טִבְלוֹ, אוֹ אִם הִפְרִישׁ מַעֲשֵׂר \u0010y164\u0011 בְּטֻמְאָה, אֵינוֹ מִתְוַדֶּה. \u0005הַגָּה: הָרַב הַמְחַבֵּר הַזֶּה הִשְׁמִיט כָּל דִּינֵי מַעֲשַׂר עָנִי, שֶׁכָּתַב הַטּוּר שֶׁיֵּשׁ לִלְמֹד מֵהֶם \u0010c31\u0011 הַרְבֵּה דִּינֵי צְדָקָה הַנּוֹהֲגִים הָאִדָּנָא, וְאֶפְשָׁר שֶׁסָּמַךְ עַצְמוֹ עַל מַה שֶּׁנִּתְבָּאֵר בְּדִינֵי צְדָקָה. אַךְ גַּם בְּדִינֵי תְּרוּמוֹת וּמַעַשְׂרוֹת הִשְׁמִיט כַּמָּה דִּינִים שֶׁכָּתַב הַטּוּר, וְהִכְנִיס אֲחֵרִים תַּחְתֵּיהֶם, וְכָל זֶה גָּרַם לוֹ שֶׁהֶעְתִּיק דִּבְרֵי הַרַמְבַּ\"ם הִלְכוֹת תְּרוּמוֹת וּמַעַשְׂרוֹת כִּכְתָבָם וְכִלְשׁוֹנָם, וְלֹא שָׁת לִבּוֹ לִדְבָרִים אֲחֵרִים, \u0010y165\u0011 וְהָרוֹצֶה לַעֲמֹד עַל עִקְּרֵי הַדִּינִים יְעַיֵּן בִּפְנִים. \u0006",["\u0003אינם נוהגין כו'. \u0004שכל מצוה שהיא חובת קרקע אינה נוהגת אלא בארץ:","\u0003סוריא כו'. \u0004לשון הרמב\"ם סוריא יש דברים שהיא בהן כארץ ישראל ויש דברים שהיא כח\"ל וכן מתבאר והולך:","\u0003אין חיוב בתרומות ומעשרות מן התורה. \u0004ובכל מקום שהזכירו הרמב\"ם והמחבר חיוב מן התורה היינו בזמן שהיו ישראל כולם ביחד על אדמתן ולא בזמן הזה:","\u0003ויש חולקין. \u0004טעמייהו דלא שייך האי טעמא דביאת כולכם אלא גבי חלה לעיל סימן שכ\"ב סעיף ב' דכתיב בבואכם בביאת כולכם אבל לענין תרומות ומעשרות לא בעינן שיהו כל ישראל עליה:","\u0003מפריש כו'. \u0004דקנין העובד כוכבים אינו מפקיע קדושת הקרקע בארץ ישראל אלא היא בקדושתה ומה שלקחה הישראל לא הוי ככבוש יחיד:","\u0003מה שאין כן בסוריא. \u0004דיש קנין לעובד כוכבים בסוריא להפקיע מן המעשרות ומן השביעית:","\u0003פטורים מכולם. \u0004דכיון שנעשה המירוח ומדגן ביד העובד כוכבים שהוא הזמן שחלה עליו חיובם נפטרו שנאמר דגנך ולא דגון עובד כוכבים:","\u0003ומפריש תרומה. \u0004היינו תרומה גדולה:","\u0003ותרומת מעשר. \u0004מוכר לכהן ולוקח דמיה כדאיתא ברמב\"ם:","\u0003מפני שהוא אומר ללוי. \u0004במעשר ולכהן בתרומת מעשר אני באתי מכח איש שאין אתם יכולים ליטול ממנו כלום ומפני מה אמרו לא יתן תרומת מעשר לכהן כתרומה גדולה לפי שנאמר בתרומת מעשר כי תקחו מאת בני ישראל את המעשר טבל שאתה לוקח מישראל אתה מפריש ממנו תרומת מעשר ונותן לכהן אבל טבל שאתה לוקח מן העובד כוכבים אין אתה נותן לכהן תרומת מעשר שהפריש ממנה אלא מוכר לכהן ולוקח דמיו. רמב\"ם. והא דמוכרה לכהן היינו משום דבתרומת מעשר יש בה קדושה ואסורה לזרים ומוכרה לכהן:","\u0003לעונת המעשרות כו'. \u0004ע\"ל סעיף ע\"ט ופ' עונת המעשרות:","\u0003חייב בכל. \u0004כדינו דהיינו שנותן תרומות ומעשרות לבעלים:","\u0003ונותן ללוי ב' שלישי המעשר הראשון. \u0004וב' שלישים מתרומת המעשר נותן לכהן ומותר השליש של מעשר ראשון הוא שלו ותרומת המעשר מאותו השליש מוכר לכהן וכתבתי הטעם בסעיף הקודם:","\u0003פטורים. \u0004אפילו מדרבנן ואע\"ג דקי\"ל אין קנין לעובד כוכבים להפקיע מידי מעשרות הני מילי כשחזר ולקחה מישראל כמו שנתבאר בסעיף ג' אבל כל זמן שהם ביד עובד כוכבים בשעת מירוח וקנאם קודם שהגיע לעונת המעשרות פטורים לגמרי:","\u0003אף על פי שגמרן העובד כוכבים. \u0004ומרחן דמן התורה פטור משום דגנך ולא דיגון עובד כוכבים חייב בכל מדרבנן דכיון שהגיעו ביד ישראל לעונת המעשר ונתחייב מדבריהם אין חוזרין ונפטרים וכ' הרמב\"ם וכן עובד כוכבים השומר פירות הישראל הואיל ודיגונן ביד עובד כוכבים אינן חייבים בתרומות ומעשרות אלא מדרבנן ועי' בכסף משנה שם באריכות:","\u0003הקונה פירות מעובד כוכבים בסוריא כו'. \u0004דבסוריא קיל טפי כיון דאפילו הקונה שדה שם אינו חייב בתרומות ומעשרות אלא מדבריהם:","\u0003ואם עדיין לא הגיעו כו'. \u0004כלומר ואם קנה קרקע מן העובד כוכבים בסוריא ופירות מחוברים אם הגיעו לעונת המעשר ביד עובד כוכבים פטורים ואם עדיין לא הגיעו לעונת המעשרות חייב לעשר מדרבנן הואיל וקנה אותם עם הקרקע:","\u0003לפי שאין לו בגוף הקרקע כלום. \u0004ויש לעובד כוכבים קנין בסוריא להפקיע מן המעשרות וכמו שנתבאר:","\u0003שותפו' העובד כוכבים חייבת. \u0004ואף על גב דעודנו ביד עובד כוכבים ובעודנו ביד עובד כוכבים אמרינן דיש קנין לעובד כוכבים בא\"י להפקיע מיד מעשרות דכתיב דגנך ולא דגן עובד כובבים וה\"ה דגנך המיוחד ולא שיש לעובד כוכבים שותפות בה לא פטרינן משום זה של שותפות דנימא דבכל קלח וקלח יש לו חלק לעובד כוכבים בו ויפטור דהדגן כמאן דפליג דמי שהרי חולקין אותו במדה וקרינו ביה דגנך בחלקו של ישראל אלא משום דקי\"ל דבשל תורה אזלינן לחומרא ולא אמרינן ברירה ואפילו חלקו ולא אמרינן הוברר הדבר שזהו חלקו של עובד כוכבים וזהו חלקו של ישראל:","\u0003פטורים. \u0004שנאמר אשר אני מביא אתכם שמה שמה אתם חייבים אבל בח\"ל פטורים אפילו מפירות של א\"י דאי מפירות של ח\"ל פשיטא דהא חובת קרקע היא:","\u0003חייבים. \u0004מדבריהם:","\u0003חייבים אם נקבעו כו'. \u0004שנאמר שמה אתם חייבים מ\"מ בין בפירות הארץ בין בפירות ח\"ל. וכתוב בכ\"מ דבפירות ח\"ל כשנכנסו לארץ קודם שנקבעו למעשר חייבים בתרומות ומעשרות מן התורה אבל אם נקבעו למעשרות בח\"ל ואח\"כ נכנסו לארץ מאחר שבשעת קביעותם למעשרות היו בח\"ל פרח מהן חיוב תרומות ומעשרות ופטורים מן התורה ואינן חייבים אלא מדבריהם וכ\"כ העט\"ז:","\u0003כל אוכל אדם כו' חייב בתרומה. \u0004דהיינו שמחויב ונפרשים ממנו ראשית לכהן שנאמר ראשית דגנך תירושך ויצהרך תתן לו הרי בנין אב מה דגן ותירוש ויצהר מאכל בני אדם וגידוליו מן הארץ ויש לו בעלים שנאמר דגנך ותירושך אף כל כיוצא בהן דהיינו שהוא מאכל בני אדם וגידוליו מן הארץ ויש לו בעלים חייב בתרומה וכן במעשרות דשוין הם:","\u0003מהירק כו'. \u0004לפי שגם בא\"י אין מעשר ירק אלא מדבריהם לפי שנאמר במעשר תבואת זרעך תבואה וכיוצא בה אבל ירקות אינן בכלל תבואה וה\"ה שאין חייבין בתרומה שהרי נאמר בה דגנך ותירושך ויצהרך כל הדומה לאלו הלכך בח\"ל הירק פטור אפילו מדרבנן והתבואה והקטנית שזרעם לירק בטלה דעתו אצל כל אדם והירק שלהן פטור והזרע חייב בתרומה ומעשרות:","\u0003פטורים. \u0004שעדיין אינו נקרא תבואה:","\u0003ההפקר פטור כו'. \u0004כיון דאין לו בעלים:","\u0003חייב כו'. \u0004דאף עלפי שהשדה הפקר הדגן אינו הפקר דהא יש לו בעלים:","\u0003אם יש לו כו' מוציא מהם לפי חשבון כו'. \u0004לא יפריש מן העירוב מיניה וביה שמא יפריש מן הפטור על החיוב:","\u0003ואם לאו כו' על הכל. \u0004כאלו כולן חייבין ומעשר ראשון ושני או מעשר עני מפריש לפי חשבון פירות החייבים שבתערובות ופי' לפי חשבון לא שיפריש אלא לפי חשבון דהא אי אפשר להפריש תרומת מעשר על הכל עד שיפריש תחלה מעשר ראשון על הכל ועוד שכל מעשרותיו טבלים ואם לא היה מעשרן על הכל א\"כ אין פירותיו מתוקנים שכל מה שמעשר יש בהן חולין לפי חשבון ונמצא מפריש מן הפטור על החיוב אלא מפריש תחלה כל המעשרות על הכל כאלו כולן חייבין ולפי חשבון היינו שאין צריך ליתן ללוי ולעני אלא לפי חשבון והשאר חוזר ומערב עם פירותיו אבל תרומה ותרומת מעשר כשמפריש על הכל נמצאו שם חולין מדומעין דאסורין ונותן הכל לכהן או מוכר לו היתר לפי חשבון:","\u0003תרומה גדולה בזמן הזה כו'. \u0004לפי שתרומה גדולה מן התורה אין לה שיעור דראשית כתיב אפי' חטה אחת פוטרת את כל הכרי וחכמים נתנו בו שיעור עין יפה אחד ממ' ועין רעה א' מס' ובינונית א' מנ' ודוקא בתרומה שהיתה נאכלת לכהנים אבל לא בתרומה טמאה והלכך בזמן הזה שהיא טמאה ואינה עומדת אלא לשריפה נמי שיעורה בכל שהוא דאוקמוה אדאורייתא:","\u0003ויכול להניחה. \u0004להשהותה ולשרפה אימת שירצה ולא חיישינן שיבא לידי מכשול בה שהכהנים נזהרין בזה כיון שידוע לכל שאין עכשיו שום תרומה נאכלת:","\u0003נותן שמן של תרומה בנר. \u0004שנהנה הוא עם הכהן:","\u0003א\"צ לכבותו. \u0004הואיל ובהיתר הודלק:","\u0003בתרומה שהוכשרה. \u0004לקבל טומאה שבאו עליה מים שאז עכשיו היא ודאי טמאה ומותר לשרפה:","\u0003קודם מירוח כו'. \u0004אבל אחר מירוח שכבר נתחייב בתרומה אסור להכשירה לקבל טומאה שאסור לגרום טומאה לתרומה טהורה:","\u0003ונותנו ללוי כו'. \u0004כמו שנאמר ולבני לוי הנה נתתי כל מעשר בישראל וגו':","\u0003וי\"א כו'. \u0004שקנסו הלוים בימי עזרא על שלא עלו:","\u0003מהשבוע. \u0004כלומר מהשמטה:","\u0003ועליו נאמר מקצה שלש שנים תוציא את כל מעשר תבואתך וגו' ובא הלוי וגו'. \u0004ויטול מעשר ראשון ואח\"כ והגר והיתום והאלמנה דסתמן עניים ויטלו את המעשר שני של שנה זו שהוא לעניים ולא תאכלנו אותו בירושלים כדרך שנזקקת לאכול מעשר שני בשאר השנים אלא הם יאכלו ושבעו:","\u0003שנת השמטה. \u0004שהיא שנת השביעית:","\u0003ובעמון ומואב מעשר ראשון ומעשר עני. \u0004לפי שהם סמוכים לא\"י תקנו במקום מעשר שני מעשר עני כדי שיבאו שם עניי א\"י ויסמכו עליהם ויתפרנסו ממנו:","\u0003ובארץ שנער. \u0004שהיא רחוקה מא\"י ואין עניי א\"י יכולים לבוא שם מפרישין מעשר שני כמו ברוב השנים:","\u0003שנת ה' אלפים שי\"ג. \u0004וכן ימנה לעולם ז' שנים אחר ז' דקי\"ל שנת חמשים עולה לכאן ולכאן:","\u0003לא אמר כלום. \u0004שאין נקרא ראשית אלא בשיש לו שיריים:","\u0003לא אמר כלום. \u0004שלא פירש הראשית:","\u0003מקום. \u0004שסיים שם תרומתו של ראשון כן מסיים מקום תרומה של אחרים:","\u0003אין מפרישין אותה באומד. \u0004דדוקא תרומה גדולה סגי בכל שהוא אבל תרומות מעשר צריכה שיעור:","\u0003ות\"ח כו'. \u0004אלא מן המוקף שהיא מצוה מן המובחר:","\u0003אלא מן המוקף. \u0004דכיון שאין צריכין שיעור מן התורה אין מפרישין אותה במדה אלא באומד לכוון השיעור שנתנו בו חכמים) ואין יכולים לאמד אלא במוקף יחד:","\u0003תרומתו תרומה דהא מן התורה אפילו בחטה אחת סגי:\u0004 ","\u0003לא אמר כלום. \u0004שהרי אינו יכול לקיים מתנות כהונה:","\u0003תורם מאחד כו'. \u0004דחשיב כמוקף וכן חביות שלא סתם את פיהם חשבי כמוקפים אבל משיסתם את פיהם אינן כמוקפין ואפי' הן בבית א' תורם מכל אחד ואחד:","\u0003המקדים כו'. \u0004לפי שצריך להפריש בכורים תחלה לכל ואח\"כ תרומה גדולה שקראה התורה ראשית ואח\"כ מעשר ראשון שיש בו תרומת מעשר וסתם תרומה נקראת ראשית בפסוק ואח\"כ מעשר שני או מעשר עני ואם הקדים אחד לחבירו עובר בלא תעשה דמלאתך ודמעך לא תאחר ומה שעשה עשוי:","\u0003א' ממאה ומעט יותר. \u0004שהא' ממאה הוא מעשר מן המעשר והמעט יותר הוא תרומה גדולה ששיעורה בזמן הזה בכל שהוא:","\u0003והרי הוא עכשיו חולין. \u0004עד שיפריש התרומה:","\u0003והמעשר. \u0004שראוי להיות למאה חולין אלו הרי הוא בכרי הגדול בצד זה שהפרשתי:","\u0003עושה אדם כו'. \u0004שנאמר כן תרימו גם אתם לרבות שלוחכם:","\u0003תרומתו תרומה. \u0004דכיון שיש שם יפות והוא אומר לו כלך אצל יפות משמעות לשונו הוא גלוי דעתא דניחא ליה במה שזה עושה ואינו מקפיד וה\"ז כשלוחו:","\u0003אין תרומתו תרומה. \u0004דכיון שאין שם יפות והוא אומר לו כלך אצל יפות משמעות לשונו הוא לשון הקפדה כאילו מוחה בו ולא ניחא ליה ואינו שלוחו:","\u0003ואם לקט כו'. \u0004גילה דעתו בזה דניחא ליה:","\u0003לא יתרומו. \u0004מפני שצריך לברך כדלקמן סעיף ע\"ח ואלו אין יכולין לברך כהוגן דהמדבר ואינו שומע צריך לשמוע הברכה והשומע ואינו מדבר הרי אינו יכול לברך וערום אסור לברך והשכור והסומא אינן יכולין לכוין להפריש את היפה:","\u0003אפילו לכתחלה. \u0004תרומה שאינה צריכה שיעור אבל לא מעשר לוי שצריכה שיעור ומדידה ואלו אינם יכולים לכוין המדידה:","\u0003תרומתו תרומה. \u0004אפי' בתרומה. של תורה הואיל ונדריהן והקדישן קיימין מן התורה כדלעיל סי' רל\"ג:","\u0003אבל אם אינו יודע. \u0004אם כרי זה תרום או לא כו':","\u0003פירות השותפים כו'. \u0004ז\"ל העט\"ז פירות השותפים חייבים בתרומות ומעשרות דגבי תרומה כתיב תרומותיכם וגבי מעשר כתיב מעשרותיכם לשון רבים של שנים משמע ואין צריכים ליטול רשות זה מזה אלא כל התורם מהם תרומתו תרומה דמסתמא כל אחד שליחות חבירו עושה בשותפות ואם תרם א' מהן בלא דעת חבירו ובא חבירו ותרם תרומה שנייה מפני שלא ידע שחבירו תרם אם ידוע בענינם שדרכם לסמוך זה ע\"ז ואחד מחזיק מה שחבירו עושה ואם ידע זה שחבירו תרם לא היה הוא תורם והיה סומך על חבירו אפי' היה יודע שחבירו לא תרם כשיעור עין שלו או רעה או יפה או בינונית לא היה משנהו אין תרומת השני תרומה שהרי חברו שדרכו לסמוך עליו תרם והוי כשלוחו ואפי' לא תרם הראשון אותו השיעור שהיה הוא תורם כגון שתרם הראשון כשיעור עין רעה והוא עין יפה אפ\"ה תרומת הראשון תרומה ותרומת השני אינה תרומה ואם לאו שאינו ידוע אם דרכן לסמוך זה על זה אם לא אלמא הם שותפין סתמא אע\"ג דאמרינן שותפין סתמא אין צריכין ליטול רשות זה מזה וכל התורם מהם תרומתו תרומה ה\"מ כשאין השני מגלה דעתו אם הוא עין רעה או יפה או בינונית אז אמרינן אם תרם הראשון כשיעור שתרם חבירו אין תרומת השני תרומה שהרי הראשון עשה שליחותו וכוון דעתו אבל אם לא תרם הראשון כשיעור שתרם חבירו אלא פחות ממנו הא חזינן שלא היה שלוחו של השני שהרי לא כוון דעתו ותרומת שניהם תרומה כל אחד בעד חלקו כן נ\"ל לפרש דעת הרמב\"ם בפ\"ד דתרומו' לפי מה שהבין שם הכל בכ\"מ ומעתה תמיהני על מה שסיים דבריו בש\"ע כאן ונראה שבזמן הזה במעשר כו' בשלמא בתרומה טהורה איכא למימר עין רעה ועין יפה ושייך לומר אם תרם הראשון כשיעור שתרם חבירו כו' אבל במעשר מאי כשיעור שתרם חבירו כו' הלא לעולם צריך להפריש המעשר במדה שלא יגרע ולא יוסיף מדינו לכך כ\"ל דבזמן הזה בין במעשר בין בתרומה תרומת השני אינה תרומה דבמעשר כיון שהפריש הא' מעשר כראוי הרי הפירות מתוקנים ואין בתרומת השני כלום ובתרומה נמי בזמן הזה כיון דשיעורה בכל שהוא וזה שהפריש הראשון הרי הפירות מתוקנים ואין בתרומת השני כלום. נ\"ל:","\u0003וביטל המשלח שליחותו קודם שידע. \u0004וזה לא ידע ותרם:","\u0003תרומתו תרומה. \u0004דמסתמא שליח שוייה:","\u0003תורמין כו'. \u0004ודוקא להאכיל אבל לא להניח שלא נעשו אפוטרופסים לעשות שליחות היתומים אלא לפרנסה הכי אמרינן בגיטין דף נ\"ב וכ\"כ העט\"ז:","\u0003תרומתן תרומה. \u0004דקנאן ביאוש והוי הם הבעלים:","\u0003אין תרומתן תרומה. \u0004דכיון דרודפין אחריהם הא חזינן דלא מייאשו:","\u0003על מה שהם אוכלין. \u0004שהרי אוכלין ברשות בעה\"ב אבל לא על השאר שאין אדם תורם דבר שאינו שלו:","\u0003תרומתו תרומה. \u0004ואין זה שינוי שליחות דכנוס שאמר בעה\"ב ע\"כ לאו דוקא שיכנוס ואח\"כ יתרום שהרי אין דרך להכניס אא\"כ נתרם:","\u0003גזרו חכמים כו'. \u0004משום בעלי כיסים שיתלו ממונם בעובד כוכבים כדי לפטרם:","\u0003טעונה גניזה. \u0004שמא בלבול שמים בד\"א בא\"י אבל עובד כוכבים שהפריש תרומה בח\"ל לא גזרו עליהן ומודיעין אותו שא\"צ לתרום ואינה תרומה כלל. הרמב\"ם וכ\"כ העט\"ז:","\u0003לא אמר כלום. \u0004שהרי מקדיש הוא כמו נדר ובנדר בעינן פיו ולבו שוין כדלעיל סי' ר\"י:","\u0003ה\"ז תרומה כו'. \u0004דדוקא בסעיף מ\"ה שכוון לומר תרומה ואמר מעשר שבטל בדבור פיו מה שהיה במחשבתו אין תרומתו תרומה משא\"כ הכא:","\u0003ה\"ז תרומה. \u0004ואם לאו אינה תרומה:","\u0003ותחזור חולין כמו שהיתה. \u0004והפירות טבלים עד שיפריש פעם שניה אותם שהפריש תחלה או פירות אחרות:","\u0003דבריו קיימים. \u0004שהדבר תלוי בדעת התורם:","\u0003אין תורמין כו' ולא מדבר שלא נגמרה מלאכתו על דבר שנגמרה מלאכתו. \u0004שנאמר כדגן מן הגורן וכמלאה מן היקב מן הגמור על הגמור מיהו היינו מדרבנן וקרא אסמכתא בעלמא הוא ועיקרו למין על שאינו מינו הוא דאתא הלכך בדיעבד תרומתו תרומה:","\u0003אין תרומתו כו'. \u0004דק\"ו הוא ממין על שאינו מינו שזה וזה חייב בתרומה לא ק\"ו לזה שאינו חייב בתרומה עדיין:","\u0003ונתלשו דבריו קיימין. \u0004דהואיל ובידו לתלוש אינו מחוסר מעשה:","\u0003אין תורמין כו'. \u0004משום דדומה לב' מינים מש\"ה גזרו ביה הלכך בדיעבד הוי תרומה:","\u0003תרם כו'. \u0004דוקא תרם אבל לכתחלה לא יתרום מן הדמאי על הדמאי דשניהם ספק ושמא א' תרם והב' אינו תרם וה\"ל מן הפטור על החיוב או מן החיוב על הפטור וכל שכן שאין תורמין מן הדמאי על הודאי:","\u0003תרומתו תרומה. \u0004מן הספק:","\u0003תרם כו'. \u0004אבל לכתחלה לא דה\"ל מן ודאי חיוב על ספק פטור:","\u0003תרומתו תרומה. \u0004מספק:","\u0003עד שיוציא כו'. \u0004דשמא הדמאי כבר נתרם וה\"ל תרומתו זו עדיין טבל:","\u0003אין תורמין מן הלקוח כו'. \u0004מפני שהלקוח אפי' מישראל אינו חייב מן התורה אלא מדרבנן והגדל בתוך שדהו חייב מה\"ת שנאמר תבואת זרעך ולא הלקוח וה\"ל כמו מן הפטור על החיוב או איפכא וכן הלקוח מן העובד כוכבים אין חיובו כמו בלקוח מישראל:","\u0003אין תורמין שבלים כו'. \u0004גזירה שמא יטריח הכהן לדרוך ולכתוש והחמירו בגזירה זו ואמרו שאפילו אם תרם אינה תרומה:","\u0003אבל תורמין כו'. \u0004דדמי לתורם משני מינים שאינם כלאים זה בזה מן היפה על הרע דשפיר קעביד:","\u0003ומיהו במעשר כו'. \u0004שלעולם צריכין לתת במדה יש להקפיד בכך:","\u0003אין תורמין כו'.\u0004 דה\"ל מן הרע על היפה:","\u0003אבל תורמין כו'. \u0004שהיין והחומץ מין א' הם וה\"ל מן היפה על הרע:","\u0003התורם כו'. \u0004והתורם חבית של חומץ על חומץ ונמצא החומץ שתרם יין תרומתו תרומה אע\"ג דתרומה בטעות הוי כיון דהטעות הוא לעלויה שעלה בידו מן היפה על הרע הוי תרומה:","\u0003אם ספק הוי תרומה. \u0004שאסור לזרים ויחזור ויתרום:","\u0003מפריש א' מעשרה כו'. \u0004ובו נאמר כי את מעשר בני ישראל אשר ירימו לה' וגו' והמעשר הזה הוא ללוים זכרים ונקבו' שנאמר ולבני לוי הנה נתתי כל מעשר בני ישראל לנחלה:","\u0003מעשר ראשון. \u0004אחר שהוציא ממנו תרומת מעשר חולין הוא ומותר באכילה לישראל כו' שנאמר ונחשב לכם תרומתכם כדגן מן הגורן וכמלאה מן היקב מה גורן ויקב חולין לכל דבר אף מעשר ראשון שנטלה תרומתו חולין לכל דבר וכל מקום שנאמר במעשרות קודש או פדיה אינו אלא מעשר שני:","\u0003מפרישין מעשר ראשון מתבואה שלהם. \u0004כדי להפריש ממנו תרומת מעשר שהוא טובל את התרומה והלוי נותן התרומת מעשר לכהן:","\u0003והם לעצמם. \u0004אלא שמפרישים אותם כדי שלא יאכלום בטבלם שכן למדו חז\"ל מדכתיב כן תרימו גם אתם אתם אלו הלוים גם לרבות הכהנים:","\u0003ואין צריך לעשר כו'. \u0004כמו שנתבאר לעיל סעיף כ\"ד:","\u0003אלא מן המובחר. \u0004שנאמר בהרימכם את חלבו ונחשב לכם כתרומת גורן וכתרומת יקב כשם שהמעשר שמפרישין הלוים מן החלב שבו כך מעשר שמפרישין ישראל מן החלב שבו יהיה מה שמפריש מן הגורן ומן היקב:","\u0003אלא במדה כו'. \u0004כל מין לפי מה שרגילין בו מדה או משקל או מנין:","\u0003והמרבה כו'. \u0004ואם ימעט גם פירותיו טבלים הלכך ידקדק בשיעורם:","\u0003אינו מעשר. \u0004שיחול על נ' סאה שבכרי אלא הכל עודנו בטבלו כיון שלא הוציא ממנו מעשרותיו:","\u0003ואינו יכול להפריש כו'. \u0004שכיון שכבר קראן כולן מעשר לא יפריש מטבל שיש לו במקום אחר עליהם מפני שנראה כמפריש מטבל על תרומה:","\u0003קודם שיפריש כו'. \u0004דכל המצות מברך עליהן עובר לעשייתן:","\u0003וכל פרי כו' עד שיגיע לעונת המעשרות. \u0004דהיינו שיגדלו ויעשו פרי שנאמר מזרע הארץ מפרי הארץ עד שיהיה פרי וכן התבואה והקטנית שנאמר את כל תבואת זרעך עד שתעשה תבואה וזו היא עונת המעשרות וקודם שתגיע התבואה אפי' לעונה זו מותר לאכול מהן כל מה שירצה ובכל דרך שירצה:","\u0003ממקום אחר. \u0004ולא מיניה וביה שמא יפריש מים ולא יין:","\u0003פטור. \u0004דבטל הוא במים:","\u0003עד שיקבעו למעשר. \u0004בכניסתן לבית כמו שיתבאר בסמוך ומה בין המוכר לשוק למוליך לביתו כשהוא מוליך לביתו בדעתו הדבר תלוי וכשהוא מוליך לשוק בדעת הלקוחות הדבר תלוי שמא ימצא לקוחות ויטבלו מיד שהרי המקח קובע כמו שיתבאר בסמוך:","\u0003החצר. \u0004ובית קובע מן התורה כמו שיתבאר והשאר מדרבנן שנאמר בערתי הקדש מן הבית וכיון שהביעור צריך להיות מן הבית ממילא שמעינן שאינו נקבע עד שיכניסו לבית והחצר דכתיב ואכלו בשעריך ושבעו ואסור לאכול וכ\"ת א\"כ בית למה לי דכל שכן הוא מבעי ליה לומר חצר דומיא דבית מה בית משתמר אף חצר המשתמרת:","\u0003ואסור לאכול מהם. \u0004אפי' עראי עד שיעשר:","\u0003מותר כו'. \u0004שאין הבית קובע מה\"ת אלא משנגמרה בכרי אבל לפני מירוח אין ראיית הבית קובעתו דגבי תרומה ומעשר כתיב דגן ראשית דגנך והוא המירוח לפיכך כשמכניסם לבית קודם מירוח לא הוקבע למעשר מן התורה ורבנן הוא דאסרו באכילת קבע בדבר שלא נגמרה מלאכתו אבל אכילת עראי לא אסרו מ\"מ אסור לאדם להערים להכניס תבואתו לבית בעודו במוץ קודם מירוח כדי שיאכל ממנה הרבה פעמים מעט מעט כדי שתפטר תבואה זו לעולם מן התרומה ומן המעשרות אבל להאכילה לבהמתו עראי אפילו כמה פעמים לא גזרו:","\u0003הגומר כו'. \u0004וכן הקובע פירותיו של חבירו בא' מן הו' דברים שקובעו למעשר שלא מדעתו הרי אלו טבלו למעשר:","\u0003לא יפקיר. \u0004להפקיע מהם תרומות ומעשרות שגוזל השבט:","\u0003הלוקח פירות כו'. \u0004שאין חייבין לעשר מן התורה אלא הגומר פירותיו לאכלן לעצמו אבל הגומרן למכרן פטור מן התורה שנאמר עשר תעשר תבואת זרעך וגו' ואכלת וגו' אינו חייב אלא הגומר לאכלן אבל חייב מדרבנן וכן הלוקח פטור מן התורה שנאמר תבואת זרעך וחייב דרבנן בד\"א שלקחן אחר שנגמרה מלאכתן ביד מוכר אבל אם נגמרו ביד לוקח חייב לעשר מן התורה וכבר נתבאר שהמקח קובע למעשר בדבר שנגמרה מלאכתן הלכך הלוקח פירות תלושים לאכול נגמרו מלאכתן ביד מוכר נקבעו למעשר מדרבנן מיד:","\u0003אף ע\"פ שלא משך. \u0004שהרי דמים קונות מן התורה:","\u0003לא נקבעו כו'. \u0004שאין המקח קובע אלא כשלוקח דבר שנגמרה מלאכתו לאכלו בעצמו דומיא דהגומר פירות של שדהו דכל מה דתיקון רבנן כעין דאורייתא תיקון:","\u0003שהרי לקחן במחובר. \u0004ואין המקח קובע אלא בתלושים כמו שנתבאר בסעיף צ\"ד:","\u0003זה לקצות וזה לקצות. \u0004פירוש ששניהם אינם מחליפים לאכול אלא לעשות מהם קציעות:","\u0003ופטורים כו'. \u0004ולא חיישינן שמא העם הארץ כבר הכניסם לביתו ונתחייבו בידו שכיון שנמצאו בשוק מחזקינן להו שלא ראו פני הבית מעולם ואינם מתחייבים במה שנותן להם:","\u0003ופטורין מן המעשר. \u0004שהתורה זכתה להם ולא דמי למקח:","\u0003בזמן שאין להם עליו מזונות כו'. \u0004כגון שאינו שוכרן ללקט תאנים אלא לחרישה וכה\"ג:","\u0003ופטורים מן המעשר. \u0004שכיון שעכשיו אין להם מזונות והוא נותן להם אע\"פ שלא פסק עמהן ועדיין לא נגמרה מלאכתן לא הוי פורע חובו מטבל אבל אי נגמרה מלאכתן ביד בעל הבית ומסתמא לא גמרן למכרן אלא לאכלן והרי כבר נטבלו ואסורים לפועלים:","\u0003הרי זה ספק. \u0004דמספקינן בש\"ס אי הוי בכלל מבשל שאמרו חכמים שקובע למעשר:","\u0003נקבעו. \u0004שכיון שנעשו ראויים לאכילת שבת ואם היה אוכלה בהן בשבת הוי ליה קבע משום דכתיב וקראת לשבת עונג הלכך אסור לאכול מהם אפילו אחר השבת עד שיעשר דכיון שנקבעו בשבת נקבעו ולא פקע:","\u0003לא יאכלם כו'. \u0004שהרי יחדום לשבת:","\u0003לא יאכל מהם. \u0004אפי' קודם השבת:","\u0003ה\"ז גומרו. \u0004באכילת עראי ואינו מעשר שכיון שהניחו מידו ופסק מן האכילה כדי שלא לאכלו בשבת היאך יקבענו שבת שהרי גלה דעתו שלא לאכול ממנו בשבת:","\u0003בטבל טמא. \u0004וכ\"ש בטהור ובחול ואצ\"ל בשבת שנאמר משמרת תרומותי בשמירות ב' תרומות הכתוב מדבר בין בטהורה בין בטמאה מה תרומה טהורה אין לך בה אלא משעת הרמתה אף תרומה טמאה אין לך ליהנות בה אלא משעת הרמתה ואילך:","\u0003בד\"א בתבואה. \u0004שכבר תלשה מהקרקע:","\u0003אם נתכוון להוסיף בגופן מותר. \u0004שהרי יעשר מהם לכשיגדלו:","\u0003אסור. \u0004שהרי מפקיען מיד מעשר מכל וכל וה\"ל כזורע חטים או שעורים של טבל:","\u0003אין מוכרין כו'. \u0004שמא יבא הלוקח לידי מכשול שלא ידע שטבל הוא:","\u0003כופין את המוכר כו'. \u0004וישלם ללוקח החולין:","\u0003מזה על זה. \u0004והוא שיודע בודאי ששניהם לא עשרו שהם הודיעוהו:","\u0003החוכר כו'. \u0004פי' שחוכר הקרקע מהעובד כוכבים לזרוע ולתת לו כך וכך סאה בין תעשה הרבה בין תעשה מעט לא יתן לעובד כוכבים קצבתו עד שיעשר הכל ואח\"כ יתן לו מה שקצב עמו:","\u0003מוציאין התרומה כו'. \u0004דקנס הוא להם שקנסו אותם כדי שלא יקפצו לגתות ולגרנות ויקנו טבלים כדי להפקיע מתנות אחיהם הכהנים ודוקא כשקנו אחר שנגמרה מלאכתן שחל עליהם חיוב הפרשה ביד ישראל אבל אם קנו אותם קודם שתגמר מלאכתן אין מוציאין מידם:","\u0003הרי התרומה והמעשר שלהם. \u0004ולא אמרי' שמכרו זכותם לישראל שמכרום לו שכיון שמכרו קודם גמר מלאכתן עדיין לא היה להם זכות בתרומות ומעשרות שבהן שימכרוהו לישראל אבל אם מכרוהו לאחר גמר מלאכתן כבר היה להם זכות שהרי יכולין להפרישן לעכבן לעצמן אמרינן כל זכות שיש לו באותה תבואה מכר לישראל והישראל נותנה לכל כהן שירצה וכאן לא שייך קנס:","\u0003הנותן שדהו. \u0004זרוע לעובד כוכבים בקבלה שקבל עליו העובד כוכבים לעבדה ולתת לישראל שנתנו לו מן התבואה ממה שיעשה הן רב או מעט חציו או שלישית או מה שיתנו ביניהם:","\u0003צריך לעשר על ידם. \u0004דהא הם ודאי לא עשרו אבל אם נתנו לסתם ישראל אפי' הוא ע\"ה כו' אין צריך לעשר דסמך על רוב ע\"ה מעשרים הם:","\u0003הירק בשעת לקיטתו עישורו. \u0004שהוא גדל על כל מים ויונק לחות בכל עת עד שלוקטין אותו:","\u0003ואם נלקט ברביעית. \u0004מפרישין ממנו מעשר שני:","\u0003הרי הוא בירק. \u0004שהרי הוא דר באילן משנה לשנה ויונק בכל עת:","\u0003ואע\"פ כו' חייבת במעשרות. \u0004דלענין שביעית בתר חנטה אזלינן כמו שהוא הדין בשאר כל האילנות וזה כיון דלא נחשב של שביעית שהרי נחנט בששית חשבינן לזה כולה של ששית:","\u0003ואחר שפודהו נותנו לעניים. \u0004ואוכל פדיונו בתורת מעשר שני ונמצא כמי שהפריש מעשר שני ומעשר עני:","\u0003לא חייבו כו'. \u0004לפי שמעשר שני הואיל וטעון הבאת מקום אין מביאין אותה מח\"ל שהרי אינו נוהג בחוץ לארץ ואינו קדוש אם הפריש הלכך לא חייבו להפרישו בסוריא:","\u0003בזמן הזה. \u0004הואיל ולאבוד אזלא:","\u0003וע\"ל סימן רצ\"ד. \u0004שם נתבאר כמה היא הפרוטה:","\u0003כשם שאין כו'. \u0004ולפי שמעשר שני טהור בארץ ישראל היו צריכים להביאו לירושלים ולאכלו שם כמו שנתבאר לעיל סעיף קל\"ב ואחר שהובא לשם ונכנס לחומה היו צריכים לאכלו תוך החומה ושלא להוציאו חוץ לחומת ירושלים שנאמר לא תוכל לאכול בשעריך וגו' ואכלת לפני ה' אלהיך וגו' כיון שנכנס למקום אכילתו לא תוכל להוציאו לאכלו חוצה לו ואם אכלו בחוץ לוקה אלא אם לא היה רוצה להביאו שם היה יכול לפדותו ולהביא הכסף לירושלים שנאמר ונתתה בכסף וגו' ויצא המעשר שני לחולין ואוכלו בביתו אבל אחר שהביאו לירושלים והכניסו לחומה היו צריכים לאכלו שם דוקא ושלא לפדותו שנאמר כי ירחק ממך המקום וגו' ונתתה בכסף וגו' בריחוק מקום הוא נפדה ואינו נפדה בקירוב מקום וכל זה במעשר שני טהור אבל מעשר שני טמא אסור לאכלו שנאמר לא בערתי ממנו בטמא פי' בין שהוא היה טמא ואני טהור או שאני הייתי טמא והוא טהור והיכן מוזהרים על שניהם טומאת הגוף דכתיב נפש אשר תגע בו וטמא עד הערב לא יאכל וגו' ומעשר שני קדוש מיקרי וטומאת עצמו ג\"כ דכתיב גבי בכור בעל מום בשעריך תאכלנו הטמא והטהור כלומר אפי' טמא וטהור אוכלין ממנו בקערה אחת ואין חוששין והכא במעשר שני כתיב לא תוכל לאכול בשעריך ודרשינן דהכי קאמר רחמנא הא דשראי לך גבי בכור בעל מום דכתיב ביה בשעריך ושרי ליה לאכלו בטומאה בין בטומאת עצמו בין בטומאת הגוף דהא הטמא טומאת הגוף אוכלו ומטמא אותו והטהור אוכל עמו היינו טומאת עצמו וכל זה לא תוכל לאכול בשעריך גבי מעשר הרי שמעשר שני טמא אינו נאכל אבל מותר לפדותו אפי' בירושלים דכתיב לא תוכל שאתו ואמרו חז\"ל אין שאת אלא אכילה שנא' וישא משאת מאת פניו דה\"ק קרא כי ירחק שיהא מעשר טהור חוץ לירושלים או אפי' הוא בירושלים אלא שאי אתה יכול לאכלו שנטמא ונתתה בכסף וגו' כן היה דיניו בארץ ישראל אבל בזמן הזה כשם שאין אוכלין אותו טהור בירושלים דאינו נפדה בקרוב מקום כיון שהוא טהור אע\"פ שאין אוכלין אותו ואין מחללין אותו ואין מוכרין אותו ואם נכנס בירושלים אף בזמן הזה אין מוציאין אותו משם אלא מניחין אותו שם עד שירקב לפיכך אין מפרישין מעשר שני בירושלים בזמן הזה אלא מוליכין הפירות בטבלן חוץ לא\"י ומפרישו שם ופודהו שם ואם הפרישן בעיר בזמן הזה ירקב בד\"א במעשר שני שלא נטמא אבל אם נטמא פודין אותו בירושלים ויכול להכשירו לקבל טומאה כדי שיטמא מיד שיגע בו דהא אנחנו טמאים ויהא לו היתר בפדיון שם בירושלים:","\u0003ואינו צריך לפרש. \u0004דהא אנו רואין שעוסק בפדיון:","\u0003ויצאו הפירות לחולין. \u0004ובזמן הבית מעלין המעות לירושלים ומוציאין אותו שם שנאמר וכי ירבה ממך הדרך כי לא תוכל שאתו וגו':","\u0003אלא בכסף. \u0004דכתיב ונתתה בכסף וגו':","\u0003שיש עליו צורה כו'. \u0004דכתיב וצרת הכסף דבר שיש בו צורה:","\u0003ואין פודין במטבע שאינו יוצא כו'. \u0004שנאמר ונתתה הכסף בכל אשר תאוה נפשך שיהא ראוי להוציאה:","\u0003ואינו פודה. \u0004שנאמר וצרת הכסף בידך:","\u0003ואין מתודים וידוי זה כו'. \u0004שנאמר כי תכלה לעשר וגו' ואמרת לפני ה' אלהיך בערתי הקדש מן הבית:","\u0003בי\"ט האחרון כו'. \u0004שנאמר כי תכלה לעשר ברגל שכל המעשרות כלין בו שזהו פסח של שנה רביעית ושביעית דבסכות עדיין הרבה פירות של שלישית מחוברים ולא הגיעו למעשרות עד הפסח:","\u0003אלא ביום כו'. \u0004דכתיב ואמרת לפני ה' אלהיך בערתי הקדש מן הבית וסמיך ליה היום ה' אלהיך מצוך:","\u0003ואם רצו כו'. \u0004אבל מצוה מן המובחר שכל אחד אומרו בפני עצמו:","\u0003אינו מתודה כו'. \u0004שכן הוא בוידוי בערתי הקדש מן הבית ועי\"ט האחרון של פסח היה הביעור וכ\"ת למה לא היו מבערין ערב י\"ט של פסח קודם החג שכל המעשרות כלין בו כדי שיהיה לו מה לאכול ברגל שהיה אוכל מן המעשר שני שהביא לשם לכך לא היו מבערין עד קרוב לכלות הרגל דהיינו בעי\"ט האחרון ולמחר מתודין כו':","\u0003ואינו חייב לבערן. \u0004כיון שלא הגיע זמנם:","\u0003מי שהיו כו'. \u0004ומתודה למחר שנתינת המטלטלין ע\"ג קרקע אינו אלא מתנה שיש בו חיזוק אבל לא יקנה להם המתנות בחליפין מפני שנראה כמכירה ותרומות ומעשרות ושאר מתנות נאמר בהן נתינה לא מכירה:","\u0003אינו מתודה. \u0004מפני שבפרשת וידוי כתובים כל המתנות כסדרן שמתודה לפניו יתברך שקיים כולם כמו שכתובים בפרשה דהיינו כסדרן כמו שדרשו הקדש זה מע\"ש מן הבית זה חלה כו' ע\"ש ברמב\"ם פי\"א מהל' מע\"ש ואם לא קיימם כסדר או שנשרף א' מהם הרי לא קיימם כולם והיה משקר לפניו יתברך וכתיב דובר שקרים לא יכון:","\u0003והרוצה לעמוד על עיקרי הדינים יעיין בפנים. \u0004ואעתיק בקיצור מן הטור עם תוספת טעמים וכמ\"ש העט\"ז מעשר שני של שנה שלישית וששית נקרא מעשר עני שנותנים לעניים כמו שנתבאר והיא ממונם לעשות בו כל מה שירצו אפילו בטומאה כמו שירצו ואם באו העניים בשבילו לשדה צריך ליתן לכל אחד כדי שבעו דכתיב ואכלו בשעריך ושבעו ואם אין לו ליתן לכל א' כדי שבעו נותן לפניהם והן מחלקים ביניהם ואם הביאו לביתו מחלק כמו שירצה ואפילו אין מגיע לכל אחד אלא כזית לא נאמר ושבעו אלא בשדה שמצאו שם ואכל מעצמו ושבע אבל בבית לא שייך לומר ואכל ושבע שהרי אינו מוציא שם ליקח באו איש ואשה לשאול נותנין לאשה תחלה ופוטרים אותה שאין כבודה להמתין שם הרבה ואחר כך נותנים לאיש כשהוא מחלקו בשדה אין בו טובת הנאה לבעלים אלא העניים באים ונוטלים אותו בע\"כ דכתיב ואכלו וגו' מעצמן ואפי' בע\"כ של בע\"ה ואפילו עני שבישראל מוציאין אותו מידו אבל המחלק בבית יש בו טובת הנאה לבעלים ונותנו לכל עני שירצה דבחד קרא כתיב תוציא את כל מעשר משמע דבבע\"ה תליא להוציא ולחלק לכל מי שירצה והיינו מה שהביא לביתו שלא היה יכול להניחו בגורן מחמת גשמים אב ובנו וב' אחין וב' שותפין שהיה א' מהן עני השני נותן לו מעשר עני שלו ב' עניים שקבלו שדה באריסות זה מפריש מעשר עני של חלקו ונותן לחבירו וכן מפריש חבירו מחלקו ונותן לו מעשר עני של חלקו ולפי שאמרה תורה ובא הלוי והגר וגו' ואכלו וגו' משמע שיאכלנו בחנם כי הוא שלהם לפיכך אמרו חז\"ל אין פורעין בו המלוה ולא משלמין בו את תגמולין כגון שחברו עשה עמו חסד וזה בא לשלם לו גמולו אל ישלם לו ממעשר עני שהוא כמו פורע בו את חובו ולא פודין בו את השבויין שזה ג\"כ מוטל עליו לעשותו בלא מצות המעשר עני והוי כמו פורע חובו ולא עושין בו שושבינות ואין נותנים ממנו צדקה כגון שפסקו עליו בני העיר צדקה לא יתן אותו ממעשר עני שנמצא פורע חובו במ\"ע אבל משלמין ממנו דבר של גמילות חסדים של מצוה וצריך להודיע שהוא מעשר עני כיצד כגון אם גמל עמו חבירו חסד באבל שאירעו ואח\"כ אירע אבל לחבירו לזה מותר לשלם לו גמול חסדו ממעשר עני כדי שלא יתבטל לגמול חסד של מצוה וצריך להודיעו לחבירו שהוא מעשר עני כדי שלא יחשוב זה שפורע לו חובו שקדם לו הגמול וה\"ל פורע חובו במ\"ע ומה שאמרנו למעלה שאין משלמין בו את התגמולין היינו לשלם תגמולין של דבר הרשות לא התירו לו אע\"פ שהוא מודיעו שהוא מ\"ע ונותנים אותו לחבר עיר בטובת הנאה פי' חכם המתעסק בצרכי צבור ומפרנסין אותו מחמת טובה שעושה להם שמתעסק בצרכיהם נותנים לו מעשר עני בטובה ושולחים לו מחמת דורון וכבוד אף על גב דאין שולחין לו צדקה מן הכיס כדאיתא לעיל בהלכות צדקה היינו משום דגנאי הוא לבני העיר לפרנס חכם שמתעסק בצרכיהם מן הצדקה אבל מעשר עני ששולחין לו מן הגורן לא מינכר דמעשר עני הוא אלא מחזי כמנחה ודורון דרך כבוד ואין מוציאין אותו מא\"י לח\"ל דכתיב והנחתו בשעריך וכתיב ואכלו בשעריך ושבעו וכל התרומות והמעשרות אפי' מ\"ע טובלין שאסור לאכול בתרומה קודם הפרשתן אע\"ג דמ\"ע אין בו קדושה שהרי נאכל לזרים אפ\"ה טובל דילפינן מ\"ע מבשעריך דכתיב גבי מעשר שני אבל אין חייבים על טבל זה מיתה ועל כולם מברך בשעת הפרשתן ואפילו על מעשר עני דהא מצוה להפרישו כיון. שטובל את התבואה:"],["\u0003ויש חולקין כו'. \u0004דעת הטור שכתב על הרמב\"ם דס\"ל גבי תרומה נמי דרשינן ביאת כולכם דוקא דזה אינו דדוקא גבי חלה אמרינן כן דגבה כתיב בבואכם ואיני יודע מה קושיא דהא דדרשינן כן בפרק שני דכתובות גבי חלה הא אמרינן בלשון זה אפילו למאן דאמר תרומה בזמן הזה דאורייתא חלה דרבנן דכתיב בבואכם בביאת כולכם וכיון דלמאן דאמר תרומה דאורייתא אנו מוכרחים לחלק בזה בין תרומה לחלה ואמרי' דדוקא גבי חלה הקפידה תורה על ביאת כולכם ממילא למאן דאמר תרומה בזמן הזה דרבנן כדקיימא לן להלכה הוה תרומה וחלה שוין בזה וצ\"ע על הטור בזה:","\u0003שאין אתה יכול ליטול ממנו. \u0004וסיים שם ברמב\"ם בלשון זה ומפני מה אמרו לא יתן תרומת מעשר לכהן כתרומה גדולה לפי שנאמר בתרומת מעשר כי תקחו מאת בני ישראל את המעשר טבל שאתה לוקח מישראל אתה מפריש ממנו תרומת מעשר ונותנה לכהן אבל טבל שאתה לוקח מעובד כוכבים אין אתה נותן לכהן תרומת מעשר שהפריש אלא מוכרה לכהן:","\u0003כל מעשר ראשון ללוי. \u0004והלוי יפריש אחר כך תרומת מעשר לכהן ונראה פשוט דחייב ג\"כ במעשר שני ועני דהא חייב בכל קאמר:","\u0003שני שלישי המעשר הראשון. \u0004כי כל מה שגדל בחלקו הוה כאלו היה שלו מעולם ובטור מסיים ומוכר לו השליש וכתב רש\"ל ופשיטא דתרומה גדולה נותן:","\u0003חייב בתרומה. \u0004שנאמר ראשית דגנך תירושך ויצהרך מה דגן תירוש ויצהר מאכל בני אדם וגידולו מן הארץ ויש לו בעלים אף כל כיוצא בהן חייב בתרומה ומעשר כן כ' רמב\"ם משמע שמן התורה חייב אבל רש\"י פירש בפ\"ק דקדושין (דף ג') דמעשר אילן הוא מדרבנן והכי אמרינן להדיא בפרק כיצד מברכין דמעשר אילן בארץ גופיה הוא מדרבנן וכן כתב הראב\"ד פרק ג' דתרומות וז\"ל שתרומת שאר הפירות דרבנן חוץ מדגן תירוש ויצהר:","\u0003מהירק בחוצה לארץ כו'. \u0004לפי שגם בא\"י אינו אלא מדבריהם שנאמר תבואת זרעך וירק לאו תבואה היא:","\u0003תרומה ותרומת מעשר על הכל ומפריש כו'. \u0004זה ודאי שצריך להפריש מעשר מן הכל שהרי א\"א להפריש תרומת מעשר מן הכל אא\"כ מפריש תחילה מעשר מן הכל אלא הא דאמרינן בסיפא לפי חשבון היינו שא\"צ ליתן ללוי ולעני אלא לפי חשבון והשאר מערב עם פירותיו אבל תרומה ותרומת מעשר דאסורים לזרים נותן הכל לכהן. כ\"כ הר\"ש פ\"ג דחלה:","\u0003ויכול להניחה ולשרפה. \u0004ולא חיישינן שמא יבא ליהנות ממנה אפי' אם מניחה בכלי שאינו מאוס כיון שאין שום תרומה נאכלת כ\"כ הטור פי' דבריו דבפ' כל שעה אמרי' דצריך להניח תרומה טמאה בכלי מאוס שלא יבא לידי תקלה שיאכלנה דיסבור שהיא טהורה ועכשיו שאין אוכלין אפילו טהורה אין חשש תקלה זו ואין לחוש לזר שיאכלנה שכל כהן מייחד מקום לתרומה בפני עצמה כנ\"ל:","\u0003אבל אם לא הוכשרה כו'. \u0004בטור כתוב בלשון זה אינה ראויה לקבל טומאה והרי היא טהורה וא\"א לאכלה שהרי הכל טמאים וטמא אסור לאכול תרומה טהורה וא\"א לשרפה כיון שהיא טהורה אלא תקבר וטוב יותר להכשירה קודם מירוח שעדיין לא חל עליה חיוב תרומה כדי שתטמא וישרפנה מיד פן יבא לידי מכשול ליהנות ממנה עכ\"ל. והקשה ב\"י שהרי בסמוך כתב שאין חשש תקלה עכשיו כיון שאין תרומה נאכלת ויש מתרצים דבמקום שיש היתר בשריפה אין חשש שהרי לא יעכב הרבה בשריפה והוא שיבוש שהרי יכול להניחה כל זמן שירצה. וראיתי עוד הרבה דוחקים בתירוצים על קושיא זאת ונלע\"ד ברור דתיבת מיד הוא ט\"ס בדברי הטור וכוונתו היתה שאם לא יטמאנה ויצטרך לקברה יש לחוש שמתוך שהיא טהורה לא יניחנה בכלי שמחזיק שם תרומה טמאה שהיא מצוה לשרפה בשעה שירצה אלא יניחנה כך ושמא יטעה לאכלה ע\"כ טוב יותר שיטמא אותה ויוכל לשרפה ממילא לא יבא לידי מכשול כי תיכף יניחנה בכלים טמאים המיוחדים לכך וכן משמע מדברי רמ\"א שלא העתיק כאן תיבת מיד:","\u0003ונותנו ללוי. \u0004ואע\"ג דקנס עזרא את הלוים בזה בשביל שלא עלו עמו היינו לבני דורו דוקא כן כתב ב\"י לדעת רמב\"ם:","\u0003לא אמר כלום. \u0004דכתיב ראשית דגנך בעינן ראשית ששיריה ניכרים:","\u0003תרומת הכרי הזה כו'. \u0004פירוש אם אמר כו' שסיים בו מקום לתרומה בצפונו או בדרומו ואמר על הכרי השני הזה כזה:","\u0003בלא תעשה. \u0004שנא' מלאתך ודמעך לא תאחר לא תאחר דבר שראוי להקדימו מלאתך היינו ביכורים ודמעך זו תרומה:","\u0003מפריש א' ממאה. \u0004פי' הדברים שהא' מק' הוא מעשר מן המעשר והיינו תרומת מעשר ומה שנשאר עוד מעט הוא לתרומה גדולה שעכשיו מפרישין מעט תרומה גדולה כמ\"ש בסעיף י\"ט ואומר א' מק' שיש כאן בין הכל הרי הוא במה שהפרשתי ועדיין הוא חולין עד שיפריש התרומה גדולה והנשאר מזה שהפרשתי שהוא המעט היתר על א' מק' הוא תרומה גדולה על הכל ומה שאני חייב לתת מעשר מן כל הק' של חולין אלו הרי הם בכרי הגדול בצד זה שהפרשתי ממנו וזה א' מק' שהפרשתי ועדיין הוא חולין הוא יהיה עכשיו תרומת מעשר על הכל וצריך לעשות דוקא כסדר זה דהא צריך להפריש תחלה תרומה גדולה ואחר כך מעשר ואח\"כ תרומת מעשר:","\u0003התורם שלא ברשות. \u0004טובא יש לתמוה על ל' הרמב\"ם הזה דבריש פרק אלו מציאות מביא ברייתא דתנא דין במי שלקט משדה חבירו שלא ברשות ותרם אם חושש משום גזל אין תרומתו תרומה ואם אין חושש משום גזל תרומתו תרומה ומנין הוא יודע אם חושש כו' אם אמר לו כלך אצל יפות כו' ופריך מזה לאביי דאמר התם יאוש שלא מדעת לא הוי יאוש דהא הכא אמרינן כיון דעכשיו ניחא ליה לבעל הבית במה שתרם זה ודאי הוה ניחא ליה גם מעיקרא תרגמא רבא אליבא דאביי הב\"ע דשוייה שליח ה\"נ מסתברא דאי לא שוייה שליח אמאי הוה תרומה הא בעינן לדעתכם כו' וכיון דקי\"ל כאביי בזה ממילא לא הוה תרומה אלא אם כן שוייה שליח ואמאי פסק הרמב\"ם כאן דאפילו לקט מתחלה כדי שיקח לעצמו א\"כ לא הוי שליח כלל ואמאי הוי תרומה בשלמא על הטור שכ' ג\"כ דין זה אלא שלא העתיק הך חלוקה שניה או שירד לתוך שדה כו' אלא חלוקה ראשונה לחוד דהיינו התורם שלא ברשות ובזה נוכל ליישב דה\"ק התרומה היתה שלא ברשות מאיזה מין יקח אבל מ\"מ עשאו תחילה שליח וכן פי' רש\"ל דברי הטור אלא על הרמב\"ם קשה וכבר הקשה כן ב\"י ותירץ דרמב\"ם ס\"ל דלא קיימא לן כהך תירוצא דמיירי בשוייה שליח וטעמו מדאיתא התם בגמרא אחר זה דמרי בר איסק אמר לאריסיה אמאי לא אייתית לרבנן מהנך שפירתא ואפ\"ה לא אכל מר זוטרא א\"ל רב אשי ואמימר מ\"ט לא אכלת האידנא אמר רבא לא אמרו כלך אצל יפות אלא בתרומה דמצוה היא ובפ\"ב דקדושין (דף נ\"ב) ההוא סרסיא דקדיש בפרוזמא דשיכרא אתא ב\"ה ואמר אמאי לא אייתית מהאי חריפא אמר רבא לא אמרו כלך אצל יפות אלא גבי תרומה משמע דאפי' בכה\"ג שלקחו פירותיו שלא ברשות אלו תרמו מהם ובא ב\"ה ואמר כלך אצל יפות הוי תרומה וממילא אזדא ליה סוגיא דאלו מציאות דמוקי בשוייה שליח ואני תמה על פה קדוש יאמר כן דמההיא דמרי ב\"א פשיטא שאין ראיה שהרי לא הוצרכו לאוקמיה בשוייה שליח אלא במקום שצ\"ל דניחא ליה למפרע כמו בתרומה ומזה קשה על אביי ועל כן מוכרח לתרץ דמיירי שעשאו שליח משא\"כ בההיא דמרי בר איסק אין שום צורך לומר שעשאו שליח שהרי עיקר הקושיא על מר זוטרא שם שלא היה רוצה לאכול אחר ששמע ממרי בר איסק שאמר למה לא אייתית מהנך שפירתא וזה דבר ברור ומפ\"ב דקדושין ג\"כ אין ראיה כלל אע\"ג דהתם מיירי ג\"כ למפרע דהיינו אם הקדושין הם קדושין למפרע מ\"מ אין ראיה משם שהרי התם רבא אמר לאותו דין ורבא לטעמיה דאית ליה בפרק אנו מציאות דיאוש שלא מדעת הוי יאוש וא\"צ לאוקמיה כלל ברייתא דתרומה בשוייה שליח וכדאמרי' התם בהדיא תרגמא רבא אליבא דאביי בשוייה שליח משמע לדידיה לא ס\"ל ואע\"ג דאמרינן שם ה\"נ מסתברא מכח קושיא דבעינן לדעתכם ממילא צ\"ל אפי' לרבא דמיירי בשוייה שליח וא\"כ צריכין אנו לומר דסוגיא דקדושין חולקת על ההיא דאלו מציאות כיון דהתם מיירי בלא עשאו שליח אכתי תקשה לך נהי דלפי סברא זו הדר ביה תלמודא מקושיא דבעינן לדעתכם מ\"מ מאן יימר לן דהדר ביה מהקושיא שהקשו שם על אביי מכח יאוש שלא מדעת דהא לא חזינן שום תירוץ על ההיא קושיא רק כמו שתרגם רבא אליבא דאביי דמיירי בעשאו שליח אבל רבא גופיה לא ס\"ל כן וכההיא מימרא דידיה בקדושין זהו ודאי דבר שאין עליו פירכא והיאך מצאנו ידינו ורגלינו בבית המדרש לחלוק על אוקימתא מפורשת בפ' א\"מ אליבא דהלכתא ואין לנו שום סמיכה משום דוכתא והתוס' בקדושין פירשו באמת דגם התם מיירי בשליח אלא דאין קושיא מזה על הרמב\"ם דאיהו מפרש כמשמעותן של דברים בלא שליח והיותר קשה לי הפלא ופלא על דעת הרמב\"ם שכ' אפילו בירד לשדה חבירו שלא ברשות כדי ליקח פירות לעצמו ואח\"כ תרם דהוי תרומה בנמצא שם יפות כיון דאמר בברייתא דכל שהוא חשש גזל אין תרומתו תרומה ובהא ודאי יש גזל אפילו באומר כלך אצל יפות למסקנא דרבא דלא מהני כלך אצל יפות אלא בתרומה דמצוה היא אבל במקום אחר אמרינן דמחמת כיסופא הוא דאמר הכי ומהאי טעמא לא אכל מר זוטרא הפירות והמעיין שם ברש\"י דאלו מציאות יראה שנשמר מקושיא זאת שפי' שם בהך ברייתא שאמרה אם חושש משום גזל פי' במה שיתרום בלא רשות נתחשב כמו גזל רצה בזה דלא תלה מילתא דתרומה במה שיש בו משום גוזל ממון חבירו באמת דא\"כ היה קשה קושיא שזכרתי ע\"כ פי' דתלוי בתורם שלא ברשות דנחשב כגזל אבל להרמב\"ם שכתב בהדיא אפי' בגזל ממש דהיינו שלקט הפירות כדי ליקחם לעצמו בזה אמר כיון שאין בו משום גזל שהרי אמר ב\"ה כלך אצל יפות ע\"כ הוה תרומה בזה ודאי יש תימה רבה הא באמת לענין גזל ממון לא מהני אמירת כלך אצל יפות דדוקא לענין תרומה מהני וזו קושיא עצומה בלי ספק והנלע\"ד ליישב דהרמב\"ם ס\"ל כיון דחזינן דרבא ומר זוטרא אומרים דוקא בתרומה מהני כלך אצל יפות דהוה מצוה וניחא ליה אבל לא בשאר דוכתי וע\"כ צריך אתה לומר כיון דמצוה היא אמרינן כיון דהשתא ניחא ליה ודאי מעיקרא נמי היה דעתו בזה שכל הרוצה לתרום משלו מן היפות יבא ויתרום ואין זה בכלל תורם שלא ברשות דשם לא מהני כיון שאין לנו הוכחה דדעתו של זה היתה בכך וע\"כ צריך אתה לומר כן דאל\"כ קשה הא בעינן לדעתכם אליבא דכ\"ע ואליבא דרבא לא מיירי בעשאו שליח כדמשמע בקדושין אלא ע\"כ דכאן אמרינן דהוה לדעתכם וכאלו אמר בפירוש מתחלה שעשאו שליח לכך ה\"נ נימא לאביי דלא מיירי בעשאו שליח ולא תקשה קושיית הגמ' הא אמרינן יאוש שלא מדעת לא הוי יאוש ואמאי הוה כאן תרומה דגם לזה נימא סברא זאת דהוה כאלו אמר בפירוש מתחלה כיון דמצוה היא והא דתרגם רבא אליבא דאביי דמיירי בעשאו שליח ולא אמר דמצוה שאני דרבא לא הוה בריר ליה אליבא דאביי אי ס\"ל הך חילוקא דמצוה שאני ע\"כ תירץ דמיירי בעשאו שליח אבל איהו בעצמו ס\"ל מצוה שאני וא\"כ אנן אמרינן למסקנא דגם אביי ס\"ל הך חילוקא וא\"צ לאוקמי בשליח וזו היא סברא מוכרחת כיון דמתחלה היו ב' קושיות האחת דוקא לאביי מכח יאוש שלא מדעת והשנית אפי' לרבא מכח לדעתכם ושניהם יש לתרץ דמיירי בעשאו שליח וכיון דחזינן בקדושין דרבא לא מוקי לה בעשאו שליח ע\"כ לומר דמתרץ קושיא השנית מכח מצוה שאני ניחא לן לומר דגם אביי מתרץ קושיא שעליו בדרך זה כנ\"ל ברור ונכון להרמב\"ם דלא איכפת ליה בעשאו שליח כלל ומה שהקשינו לעיל דהא בגזל ממש ס\"ל לרבא דלא מהני כלך אצל יפות ואמאי הוה תרומה כל שלקט כדי ליקחם נראה לתרץ דמיירי שכל מה שלקט לעצמו תרם כולו ולא השאיר לו כלום ועל כן אין כאן גזל מעיקרא דסופו דהוה מצוה מוכיח על תחלתו וכאלו לקט תחלה לשם תרומה והשתא דאתינא להכי להרמב\"ם דמיירי בלא עשאו שליח ניחא גם דעת הטור ודבריו כמשמען בלא עשאו שליח וכן דברי הסמ\"ג עשין סימן קל\"ד מבוארים בלא עשאו שליח:","\u0003ואם לאו כו'. \u0004שאז ודאי דרך רוגז אמר כן למה אתה לוקח ביפות:","\u0003המדבר ואינו שומע כו'. \u0004בכולם הטעם מפני הברכה שצריך לומר ולשמוע ובשכור וסומא הטעם שאינו יכול לכוין ליטול היפות:","\u0003לעונת נדרים. \u0004מבואר בסי' רל\"ג ותרומתו תרומה כיון שנדר והקדש שלו קיים:","\u0003שמא אחר כו'. \u0004ולא אמרינן חזקה שליח עושה שליחותו אלא לחומרא כגון ששלח אחד לקדש לו אשה זהו דעת רמב\"ם ור\"ת וי\"א ס\"ל דחזקה זו אפילו לקולא והיינו אם יודע שכרי שלו נתרם אבל אם ספק לו אם כרי שלו נתרם לא אזלינן לקולא כאלו וכצ\"ל אבל אם אינו יודע אם כרי שלו תרום כו':","\u0003ממחין זה על זה. \u0004פי' שהיו מוחין א' על חבירו שלא נתרצה בתרומתו של חבירו והיינו אחר שתי ההפרשות אמרינן בזה דתרומת הראשון הוה תרומה על כל פנים דהא באותו פעם לא היתה מחאה והוי כשאר שותפין וע\"כ תרומת הראשון תרומה בכל גווני ולא של השני דתרומתו בטעות ואם לאו פי' שאין ידוע אם מוחין זע\"ז אם תרם האחד כשיעור ודאי הוי כמו ברישא אלא דאם אין כשיעור ממילא גם תרומת השני תרומה דאמרינן דסומכין זע\"ז וכל אחד יתרום כנ\"ל לדעת הטור:","\u0003אם שינה השליח. \u0004פי' תרתי בעינן שינה שליח וביטול שליחותו דבביטול לחוד לא סגי דלא אתי דבור ומבטל דבור ובשינה לחוד לא סגי דאין דרך להקפיד על שינוי כל דהו כזה לכך בעינן תרוייהו:","\u0003נכסי יתומים. \u0004בפרק הנזקין אמרינן בזה דוקא להאכילם אבל לא להניח וכן כתוב בסמ\"ג סי' קל\"ד וכ\"כ בכ\"מ שהרמב\"ם לא הוצרך להביאו לפי שסמך על מ\"ש בהל' נחלות:","\u0003הגנב והגזלן. \u0004לפי שקנאו בייאוש בעלים כל שאין מרדפין אחריהם:","\u0003ותרם ואח\"כ כנס. \u0004אין בזה שינוי דגם הבעה\"ב נתכוין לכך שהרי אין דרך להכניס אלא א\"כ תרם תחלה:","\u0003גזרו חכמים כו'. \u0004משום בעלי כיסין שיתלו פירותם בעובד כוכבים שיפטרו מתרומה:","\u0003טעונה גניזה. \u0004דשמא בלבו לשמים:","\u0003אלא מהם. \u0004כיון שכבר קראן כולן מעשר לא יפריש מטבל שיש לו במקום אחר עליהם לפי שנראה כאילו מפריש מטבל על המעשר:","\u0003ממקום אחר. \u0004ולא מיניה וביה שמא יפריש מים ולא יין:\n\u0003ומ\"ש \u0004בלבו על הכל ממילא נפטרו גם השמרים:","\u0003שנכנסה לשביעית. \u0004דלשביעית לא אזלינן בתר חנטה:","\u0003האביונות. \u0004הם דומין קצת לאילן וקצת לירק:","\u0003בד\"א במעשר שני כו'. \u0004בזה מתורץ מ\"ש הטור שמותר להכשירו שיהיה טמא והרמב\"ם שמביא אח\"כ פסק שירקבו אלא דהרמב\"ם מיירי מטהור שלא נכשר עד אחר המירוח והובא לירושלים שאז אסור לטמאותו:","\u0003הרבה דיני צדקה. \u0004נראה דיש לדמות מעשר שמפרישין מן הריוח ממון לדין מעשר עני של תבואה ופירות ומו\"ח ז\"ל כתב שהמעשר של ממון שלנו אין בו חיוב לא מן התורה ולא מדרבנן ותמהתי שהרי ר\"ס רמ\"ט מבואר שחיוב גמור הוא כמ\"ש כל הפוסקים והב\"י בשם ירושלמי וע\"כ נעתיק דברי הטור בקיצור לענין מעשר עני וז\"ל באו איש ואשה לשאול כו' (הוא מוזכר בסי' רנ\"א סעיף ט') וכשהוא מחלקו בשדה אין בו טובת הנאה לבעלים אלא העניים באים ונוטלים אותו בע\"כ ואפי' עני שבישראל מוציאין אותו מידו אבל המתחלק בבית יש בו טובת הנאה לבעלים ונותנו לכל עני שירצה (ובפרק הזרוע (חולין דף קל\"א) אמרינן בברייתא בהדיא מעשר המתחלק בביתו שיש בו טובת הנא' לבעלים ואפי' עני שבישראל מוציאין אותו מידו ויליף לה בגמרא שם בג\"ש מלקט ואע\"פ שהטור לא הביא זה רק על המתחלק בשדה ודאי אין חילוק דהא בג\"ש יליף לה ותרוייהו שייכי בההיא ג\"ש וכן כתב ב\"י ואין להקשות אמ\"ש התוספות שם דבדבר שיש בו טובת הנאה לבעלים אפילו בא עני ולקחו מוציאין אותו מידו והיאך אמרינן שמוציאין מהעני בע\"כ מעשר עני הא ל\"ק דכייפינן ליה שיתן מעשר עני אבל הברירה בידו לתת לאיזה עני שירצה ואילו בא עני ולקח שלא מדעת זה העני בעל השדה יכול להוציא ממנו ולתתו לעני אחר כל זה נראה לי פשוט ותמהתי על מו\"ח ז\"ל שכ' כאן על הב\"י דלא דק מכח דברי התוס' שזכרתי ואגב ריהטיה לא דק בגמ' בזה ומזה נ\"ל סמך למה שנוהגים לכוף החתן בשעת קבלת נידוניא שלו ליתן מעשר כדאשכחן כאן שמוציאין מידו אלא שמחלקין את המעשר לקרובי החתן והכלה דהם קודמין לשאר עניים בזה דגם במעשר עני מצינו כן כמ\"ש ב\"י סי' רנ\"א בשם המרדכי דיש זכות לקרוביו בזה וראיתי קצת אומרים דדוקא מהנדן שהכלה נותנת להחתן מפריש מעשר אבל לא ממה שאבי החתן נותן לבנו מטעם שאביו נתן כבר מעשר ותמהתי מאין הרגלים דאטו יש חיוב על הממון כאן דתוכל לומר שהממון כבר נפטר ממעשר והלא חובת גברא הוא שהוא חייב לתת ממה שנתנו האל ית' ומה לי שנתן לו אביו או חותנו ודאי דעת משובש האומר כן) אב ובנו שני אחים ושותפין שהיה אחד מהן עני נותן לו השני מעשר עני שלו (זה נתבאר גם בצדקה בסימן רנ\"א סעיף י\"ב) אין פורעין בו המלוה ולא משלמין בו את התגמול (פי' ב\"י שחבירו עשה לו טובה של דבר הרשות אסור לשלם גמולו במ\"ע) אבל משלמין ממנו דבר של גמילות חסדים וצריך להודיעו שהוא ממעשר עני (פי' כגון לסעודת הבראה של אבל) ולא פודין בו את השבויים ולא עושין בו שושבינות ואין נותנין ממנו צדקה (כפירש ב\"י צדקה שפסקו עליו בני העיר שכבר נתחייב בה דה\"ל פורע חובו) (נ\"ל דגם ההיא דפדיון שבוים שאין נותן לזה ממעשר עני היינו שיש בלא\"ה לפדות שפסקו עליו כן והוא רוצה לפטור עצמו במ\"ע אבל אם אין חייב לפדותו בלא\"ה ודאי יכול המפריש לתת מ\"ע שלו לזה דאין לך צדקה גדולה מזה דשבי כולהו איתנייהו ביה חרב ורעב כדאיתא פ\"ק דב\"ב כנ\"ל) ונותנין אותו לחבר עיר בטובת הנאה פירות דרך דורון וכבוד כל זה נראה ששייך גם כן במעשר שמפרישין מן ריוח שנתן הש\"י לבני האדם ולעיל סימן רנ\"א כתב ב\"י ג\"כ בשם המרדכי דמעשר עני דומה למפריש צדקה:"]],["לֶקֶט, שִׁכְחָה וּפֵאָה, אִם אֵין עֲנִיֵּי יִשְׂרָאֵל מְצוּיִים שָׁם \u0010y0\u0011 לִטְּלָם, אֵין צָרִיךְ לְהַנִּיחָם. \u0005הַגָּה: וְהָאִדָּנָא אֵין נוֹהֲגִין בָּהֶם, לְפִי שֶׁהָרֹב עוֹבְדֵי כּוֹכָבִים, וְאִם יַנִּיחוּם, \u0010y1\u0011 יָבוֹאוּ עוֹבְדֵי כּוֹכָבִים וְיִטְּלוּם (טוּר)\u0006.",["\u0003א\"צ להניחם. \u0004שאין נוהגים מן התורה אלא בארץ ובח\"ל הם דרבנן:","\u0003יבואו עובדי כוכבים כו'. \u0004כ' ב\"י ועוד אפשר לומר דע\"כ לא אמרו דבח\"ל חייבים אלא בח\"ל הסמוכה לארץ דכשם שחייבת בתרומה ומעשרות חייבת במתנות אבל במקומות הרחוקים כשם שפטורים מתרומות ומעשרות פטורים ממתנות:"],[]],["\u0010y0\u0011 רֵאשִׁית הַגֵּז אֵינוֹ נוֹהֵג אֶלָּא בָּאָרֶץ, בֵּין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת. \u0005וְיֵשׁ אוֹמְרִים דְּבַר תּוֹרָה רֵאשִׁית הַגֵּז נוֹהֵג אֲפִלּוּ בְּחוּץ לָאָרֶץ, אֶלָּא שֶׁלֹּא נָהֲגוּ כֵן (טוּר)\u0006.\nאֵין חַיָּבִים בְּרֵאשִׁית הַגֵּז \u0010y1\u0011 אֶלָּא הַכְּבָשִׁים בִּלְבַד, זְכָרִים וּנְקֵבוֹת. וְאִם הָיָה צִמְרָן קָשֶׁה וְאֵינוֹ רָאוּי לִלְבִישָׁה, פָּטוּר.\nגָּזַז הַצֶּמֶר וְלִבְּנוֹ, \u0010y2\u0011 חַיָּב. אֲבָל אִם צְבָעוֹ, פָּטוּר.\nהַגּוֹזֵז אֶת הַמֵּתָה, פָּטוּר. \u0005הַתּוֹלֵשׁ צֶמֶר רְחֵלִים בְּיָדוֹ, וְלֹא גָּזַז, חַיָּב.\u0006\nהַמַּפְרִישׁ רֵאשִׁית הַגֵּז, וְאָבַד, חַיָּב בְּאַחֲרָיוּתוֹ עַד שֶׁיִּתְּנֶנּוּ לְכֹהֵן.\nהָאוֹמֵר: כָּל גִּזָּתִי רֵאשִׁית, דְּבָרָיו \u0010y3\u0011 קַיָּמִים.\nהַלּוֹקֵחַ גֵּז צֹאנוֹ שֶׁל עוֹבֵד כּוֹכָבִים, אַחַר שֶׁגְּזָזָן הָעוֹבֵד כּוֹכָבִים, פָּטוּר מֵרֵאשִׁית הַגֵּז. וְאִם לָקַח הַצֹּאן לְגִזָּתָן, חַיָּב, אַף עַל פִּי שֶׁגָּדְלָה הַגִּזָּה בִּרְשׁוּת הָעוֹבֵד כּוֹכָבִים, וְאַף עַל פִּי שֶׁחוֹזְרִים הַצֹּאן לָעוֹבֵד כּוֹכָבִים אַחַר גְּזִיזָה, חַיָּב. \u0005וְיֵשׁ חוֹלְקִין וְאוֹמְרִים דְּפָטוּר, אִם לֹא קָנָה הַצֹּאן לְגִזָּתָן (דַּעַת רַשִׁ\"י וְטוּר)\u0006. \u0010y4\u0011\nהַלּוֹקֵחַ גֵּז צֹאנוֹ שֶׁל חֲבֵרוֹ, אִם שִׁיֵּר הַמּוֹכֵר מְעַט מִצֹּאנוֹ לְהִגָּזֵז, חַיָּב לְהַפְרִישׁ מֵהַנִּשְׁאָר עַל הַכֹּל. \u0010y5\u0011 וְאַף עַל פִּי שֶׁלֹּא הִתְחִיל הַמּוֹכֵר לִגְזֹז. וְאִם לֹא שִׁיֵּר כְּלוּם, \u0010y6\u0011 הַלּוֹקֵחַ חַיָּב לְהַפְרִישׁ. וְאִם הָיוּ שְׁנֵי מִינִים, כְּגוֹן גִּזָּה לְבָנָה וְגִזָּה שְׁחוּמָה \u0005(פי' אֲדֻמָּה)\u0006 וּמָכַר מִין זֶה וְהִנִּיחַ הַמִּין הָאַחֵר, זֶה נוֹתֵן לְעַצְמוֹ עַל מַה שֶּׁלָּקַח וְזֶה נוֹתֵן לְעַצְמוֹ עַל מַה שֶׁמָּכַר. \u0005הַגָּה: קָנָה גֵּז צֹאנוֹ שֶׁל חֲבֵרוֹ, אִם שִׁיֵּר הַמּוֹכֵר קְצָת גִּזָּה לְעַצְמוֹ, הוּא חַיָּב. לֹא שִׁיֵּר מֵהֶם כְּלוּם, הַלּוֹקֵחַ \u0010y7\u0011 חַיָּב לִתֵּן. וְאִם פֵּרֵשׁ לוֹ: אֲנִי מוֹכֵר לְךָ הַכֹּל, שְׁנֵיהֶם פְּטוּרִים (טוּר)\u0006.\nכַּמָּה צֹאן יִהְיוּ לוֹ וְיִהְיוּ חַיָּבוֹת בְּרֵאשִׁית הַגֵּז, \u0010y8\u0011 אֵין פָּחוֹת מֵחָמֵשׁ; וְהוּא שֶׁיִּהְיֶה בַּגִּזָּה שֶׁלָּהֶם אֵין פָּחוֹת מִמִּשְׁקַל שִׁשִּׁים סֶלַע; וְתִהְיֶה גִּזַּת כָּל אֶחָד מֵחֲמִשְׁתָּן אֵין פָּחוֹת מִי\"ב סֶלַע; וְאִם הָיְתָה אַחַת מֵהֶן גּוֹזֶזֶת פָּחוֹת מִי\"ב, אַף עַל פִּי שֶׁחֲמִשְׁתָּן גּוֹזְזוֹת שִׁשִּׁים סֶלַע אוֹ יוֹתֵר, פָּטוּר.\nהַשֻּׁתָּפִים, חַיָּבִים. וְהוּא שֶׁיִּהְיֶה בְּחֵלֶק כָּל אֶחָד כַּשִּׁעוּר. אֲבָל חֲמִשָּׁה צֹאן בִּלְבַד שֶׁל שְׁנֵי שֻׁתָּפִין, פְּטוּרִין.\nרֵאשִׁית הַגֵּז, מִצְוָתָהּ בַּתְּחִלָּה. וְאִם הִפְרִישׁ, בֵּין בָּאֶמְצַע בֵּין בַּסוֹף, יָצָא.\nהָיוּ לוֹ ה' צֹאן וְגָזַז אַחַת מֵהֶן בִּלְבַד, וּמָכַר גִּזָּתָהּ, וְאַחַר כָּךְ גָּזַז שְׁנִיָּה וּמָכַר גִּזָּתָהּ, וְאַחַר כָּךְ גָּזַז שְׁלִישִׁית וּמָכַר גִּזָּתָהּ, הַכֹּל מִצְטָרְפוֹת לְרֵאשִׁית הַגֵּז וְחַיָּב לְאַחַר כַּמָּה שָׁנִים. \u0005וְהוּא הַדִּין אִם מָכַר קְצָת הַצֹּאן לְאַחַר שֶׁהִתְחִיל לִגְזֹז.\u0006 וְיֵשׁ לוֹ לְהַפְרִישׁ מִן הֶחָדָשׁ עַל הַיָּשָׁן וּמִזֶּה עַל זֶה. \u0005הָיוּ לוֹ שְׁנֵי מִינִים, רַע וְטוֹב, לֹא יִתֵּן מִן הָרַע עַל הַטּוֹב, אֶלָּא יִתֵּן מִכָּל אֶחָד לְפִי שִׁעוּרוֹ (טוּר)\u0006. אֲבָל אִם הָיְתָה רָחֵל אַחַת וּגְזָזָהּ, וְאַחַר כָּךְ קָנָה שְׁנִיָּה וּגְזָזָהּ וְהִנִּיחַ גִּזָּתָהּ, וְאַחַר כָּךְ קָנָה שְׁלִישִׁית וּגְזָזָהּ וְהִנִּיחַ גִּזָּתָהּ, אֵינָם מִצְטָרְפִין.\nמִי שֶׁהָיוֹ לוֹ גִּזּוֹת רַבּוֹת שֶׁל רֵאשִׁית הַגֵּז, וְרוֹצֶה לְחַלֵּק לַכֹּהֲנִים, לֹא יִתֵּן לְכָל אֶחָד פָּחוֹת מִמִּשְׁקַל חֲמִשָּׁה סְלָעִים מְלֻבָּן, כְּדֵי בֶּגֶד קָטָן. לֹא שֶׁיְּלַבְּנוֹ וְאַחַר כָּךְ יִתֵּן, אֶלָּא יִתֵּן לוֹ מִצֶּמֶר הַגִּזָּה כְּשֶׁהוּא צוֹאִי \u0005(פי' מְטֻנָּף)\u0006 כְּדֵי שֶׁיִּהְיֶה בּוֹ אַחַר הַלִּבּוּן חֲמִשָּׁה סְלָעִים אוֹ יוֹתֵר, שֶׁנֶּאֱמַר: תִּתֶּן לוֹ, \u0005(דְּבָרִים יח, ד)\u0006 שֶׁיִּהְיֶה בּוֹ כְּדֵי מַתָּנָה הַמּוֹעֶלֶת. \u0005אֲבָל אֵינוֹ \u0010y9\u0011 חַיָּב לִתֵּן רַק חֲמִשָּׁה סְלָעִים מֵהַכֹּל (טוּר)\u0006.\nרֵאשִׁית הַגֵּז חֻלִּין לְכָל דָּבָר. לְפִיכָךְ נוֹתְנִין אוֹתוֹ לַכֹּהֶנֶת, אַף עַל פִּי שֶׁהִיא נְשׂוּאָה לְיִשְׂרָאֵל.",["\u0003ראשית הגז כו'. \u0004דכתיב גז צאנך תתן לו שחייב כל אדם מישראל לתת מראשית גז צאנו לכהן:","\u0003אלא הכבשים כו'. \u0004דכיון דתלה רחמנא טעמא דראשית הגז בשירות כהונה דכתיב וראשית גז צאנך תתן לו כי בו בחר וגו' לעמוד לשרת דבר הראוי לשרת דהיינו רחלים שצמרן ראוי לעשות ממנו תכלת לבגדי כהונה:","\u0003חייב. \u0004שלא עשה בגוף הצמר כלום הלכך חייב אף אחר שלבנו אבל כשגזז וצובע קודם שיתן פטור מראשית הגז שקנאו בשינוי והוי כמזיק מתנות כהונה או שאכלן פטור כדלעיל סי' ס\"א סעי' ל\"א:","\u0003הלוקח גז צאנו כו'. \u0004פי' דדעת המחבר דדוקא כשקונה גז צאנו של עובד כוכבים אחר שגזזן העובד כוכבים כיון שהיה של עובד כוכבים אחר גיזה פטור אבל אם לקח הצאן לגיזתן כלומר שלקח הגיזה בעודו במחובר אף על פי שלא לקח גוף הצאן אלא הגיזה בלבד כיון שלקחן במחובר קודם שגזזן העובד כוכבים חייב אע\"פ שגדלה הגיזה ברשות העובד כוכבים ואף על פי שעיקר הצאן של עובד כוכבים הוא והיש חולקים סוברים דאפילו לקחן במחובר קודם גיזה פטור כשהגוף הצאן הוא של עובד כוכבים ואינו חייב אא\"כ קנה אף הצאן לגיזתן כלומר שיהיה שלו בשעת הגיז' ודוק:","\u0003הלוקח גז צאנו של חבירו. \u0004בעודו במחובר:","\u0003ואע\"פ שלא התחיל כו'. \u0004דחזקה אין אדם מוכר מתנות כהונה ומתנה דכהן גבי מוכר היא:","\u0003הלוקח חייב להפריש. \u0004שאומר לו המוכר מתנה דכהן לא מכרתי לך ומה שלקחתי ממך מעות לא לקחתי אלא בעד צמרי חוץ מחלקו של כהן:","\u0003ואם פירש לו אני מוכר לך הכל. \u0004אם אחר גיזה מכרה המוכר חייב דהא משעת גזיזה חל עליו ליתן ולמה מכרה והלוקח פטור דלאו גז צאנך הוא ואם בעודו מחובר מכרה לו ופירש לו הכל אני מוכר לך שניהם פטורים המוכר פטור דבעודו מחובר לא חל עליו ראשית הגז ובשעת גזיזה לאו גז צאנך הוא דגיזה לאו שלו וכן הלוקח פטור דלאו גז צאנך הוא דהא הצאן אינו שלו ומכל מקום לכתחלה אסור לעשות כן למכור הצמר במחובר ולהפקיע ממונו מיד מצוה:","\u0003אין פחות מחמש. \u0004דכתיב חמש צאן עשויות ודרשו בו שמעשות את בעליהן למצוה:","\u0003רק חמשה סלעים מהכל. \u0004ומדרבנן דמן התורה בכל דהו סגי:"],[]],["\u0003הלכות נידוי וחרם\u0004\nהָעוֹבֵר \u0010y0\u0011 עַל דְּבַר \u0010y1\u0011 אִסוּר, מְנַדִּין אוֹתוֹ לְאַלְתַּר. \u0005הַגָּה: אֲבָל מִכֹּחַ מָמוֹן, אֵין מְנַדִּין אוֹתוֹ, עַד שֶׁיַּתְרוּ בּוֹ ג' פְּעָמִים, דְּהַיְנוּ ב' ה' ב' (טוּר)\u0006 מִן הַבֵּית דִּין, כְּמוֹ שֶׁיִּתְבָּאֵר בְּחשֶׁן מִשְׁפָּט סִימָן י\"א. \u0010y2\u0011 וְאֵין נִדּוּי פָּחוֹת מִשְּׁלֹשִׁים יוֹם; וְאִם אֵינוֹ חוֹזֵר בּוֹ, שׁוֹנִים לְנַדּוֹתוֹ לְאַחַר שְׁלֹשִׁים יוֹם. וְאִם אֵינוֹ חוֹזֵר בּוֹ, \u0010y3\u0011 מַמְתִּינִים לוֹ עוֹד שְׁלֹשִׁים וּמַחֲרִימִין אוֹתוֹ. אֲפִלּוּ פָּגַע הָרֶגֶל בְּתוֹךְ שְׁלֹשִׁים יוֹם, אֵינוֹ מְבַטֵּל אוֹתוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים, דְּנִדּוּי שְׁלֹשִׁים יוֹם, \u0010y4\u0011 בְּנִדּוּי דִּידְהוּ, אֲבָל נִדּוּי דִּידָן \u0010y5\u0011 כִּנְזִיפָה דִּידְהוּ, שֶׁהִיא ז' יָמִים; וּנְזִיפָה דִּידָן, חַד יוֹמָא. \u0005הַגָּה: וּמְנַדִּין לְמִי שֶׁהוּא חַיָּב נִדּוּי, \u0010c0\u0011 וַאֲפִלּוּ יֵשׁ לָחוּשׁ שֶׁעַל יְדֵי כֵן יֵצֵא לְתַרְבּוּת רָעָה, אֵין לָחוּשׁ בְּכָךְ (פִּסְקֵי מהרא\"י סִימָן קל\"ח)\u0006. \u0010y6\u0011\nהַמְנֻדֶּה, אֵין יוֹשְׁבִין בְּד' אַמּוֹתָיו, חוּץ מֵאִשְׁתּוֹ וּבָנָיו. \u0005(ר\"ן)\u0006 \u0005וְיֵשׁ אוֹמְרִים אַף בְּנֵי בֵּיתוֹ, שָׁרֵי\u0006 \u0005(טוּר ובת\"ה סִימָן רע\"ו)\u0006 \u0005וְיֵשׁ לְהָקֵל.\u0006 וְאֵין אוֹכְלִין \u0005וְשׁוֹתִין\u0006 עִמּוֹ \u0005(טוּר)\u0006. \u0010y7\u0011 וְאֵין מְזַמְּנִין עָלָיו. וְאֵין כּוֹלְלִין אוֹתוֹ לְכָל דָּבָר שֶׁצָּרִיךְ עֲשָׂרָה. \u0005הַגָּה: \u0010c1\u0011 אֲבָל אִם לֹא \u0010y8\u0011 נִדּוּהוּ בְּפֵרוּשׁ, אַף עַל גַּב שֶׁהוּא עֲבַרְיָן אוֹ שֶׁעָבַר עַל גְּזֵרַת צִבּוּר, מְצָרְפִין אוֹתוֹ לְמִנְיַן י' לְהִתְפַּלֵּל עִמּוֹ (ריב\"ש סִימָן קע\"ב וּמָרְדְּכַי רֵישׁ שְׁבוּעוֹת שְׁתַּיִם וְהַגָּהוֹת אַלְפָסִי פֶּרֶק אֵלּוּ מְגַלְּחִין)\u0006. וַאֲפִלּוּ מְנֻדֶּה מַמָּשׁ שֶׁאֵין מְצָרְפִין אוֹתוֹ לְמִנְיָן, \u0010y9\u0011 מִכָּל מָקוֹם מֻתָּר לְהִתְפַּלֵּל בְּעוֹדוֹ בְּבֵית הַכְּנֶסֶת \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת הָרַשְׁבָּ\"א וריב\"ש סי' קע\"ב)\u0006. וּמָה שֶׁנָּהֲגוּ לְגָרְשׁוֹ \u0010y10\u0011 מִבֵּית הַכְּנֶסֶת, שֶׁלֹּא יִדְחֹק יְחִידִים שֶׁצְּרִיכִים לְהִתְרַחֵק מֵאַרְבַּע אַמּוֹתָיו. \u0005(שָׁם בריב\"ש)\u0006. \u0010y11\u0011 וְאָסוּר \u0010y12\u0011 בְּתִכְבֹּסֶת וּבְתִסְפֹּרֶת וּבִנְעִילַת הַסַנְדָּל, \u0005(ראב\"ד ורא\"ש)\u0006 כְּאָבֵל. וּמֻתָּר בְּדִבְרֵי תּוֹרָה. שׁוֹנֶה, וְשׁוֹנִין לוֹ. נִשְׂכָּר, וְנִשְׂכָּרִין לוֹ. וְהַמֻּחְרָם, לֹא שׁוֹנֶה וְלֹא שׁוֹנִין לוֹ; לֹא נִשְׂכָּר וְלֹא נִשְׂכָּרִין לוֹ; וְכֵן אָסוּר לְהַנּוֹתוֹ יוֹתֵר מִכְּדֵי חַיָּיו \u0005(תְּשׁוּבַת רַשְׁבָּ\"א)\u0006. אֲבָל שׁוֹנֶה הוּא לְעַצְמוֹ, שֶׁלֹּא יִשְׁכַּח תַּלְמוּדוֹ, וְעוֹשֶׂה לוֹ חֲנוּת קְטַנָּה כְּדֵי פַּרְנָסָתוֹ; וּמֻתָּר לְדַבֵּר עִם הַמְּנֻדֶּה וְעִם הַמֻּחְרָם, אֶלָּא אִם כֵּן הֶחְמִירוּ עָלָיו בֵּית דִּין בְּפֵרוּשׁ. \u0005הַגָּה: וּמִכָּל מָקוֹם לֹא יַרְבֶּה עִמּוֹ בִּדְבָרִים, וְלֹא יְדַבֵּר עִמּוֹ אֶלָּא לְצֹרֶךְ, כְּמוֹ שֶׁמְּדַבֵּר עִם הָאָבֵל (הַגָּהוֹת אַלְפָסִי וריב\"ש הַנַּ\"ל)\u0006. בְּמָקוֹם שֶׁאָסוּר לֵישֵׁב בְּד' אַמּוֹתָיו, כָּל שֶׁאָדָם יוֹשֵׁב תְּחִלָּה וְהַמְנֻדֶּה בָּא לְשָׁם, אֵין צָרִיךְ לְהִתְרַחֵק מִשָּׁם \u0005(בֵּית יוֹסֵף בְּשֵׁם \u0010y13\u0011 הַקוּנְטְרֵס)\u0006. וְאָסוּר לִכָּנֵס לְבֵיתוֹ, דְּהָוֵי כְּד' אַמּוֹתָיו, \u0010y14\u0011 וְאֵין חִלּוּק בֵּין עוֹמֵד לְיוֹשֵׁב \u0005(שָׁם)\u0006.\nמְנֻדֶּה שֶׁמֵּת, בֵּית דִּין שׁוֹלְחִין \u0010y15\u0011 וּמַנִּיחִין אֶבֶן עַל אֲרוֹנוֹ, \u0010y16\u0011 וְאֵין קוֹרְעִין עָלָיו, \u0010y17\u0011 וְלֹא חוֹלְצִין, וְלֹא מַסְפִּידִין. וְהָנֵי מִלֵּי לְאַפְקִירוּתָא וְעוֹבֵר עַל דִּבְרֵי חֲכָמִים; אֲבָל לְמָמוֹנָא, כֵּיוָן שֶׁמֵּת, פָּטוּר מִגְּזֵרָתָם וְאֵין סוֹקְלִין אֲרוֹנוֹ, וּמַסְפִּידִין אוֹתוֹ כָּרָאוּי.\nאֲפִלּוּ נִדּוּהוּ מִשּׁוּם עוֹבֵר עַל דִּבְרֵי חֲכָמִים, אִם חָזַר בּוֹ, אַף עַל פִּי שֶׁלֹּא הִתִּירוּ נִדּוּיוֹ, מִתְעַסְקִין עִמּוֹ לְכָל דָּבָר.\nאַף עַל פִּי שֶׁאָסוּר לֶאֱכֹל וְלִשְׁתּוֹת עִם הַמְּנֻדֶּה אוֹ הַמֻּחְרָם, מִכָּל מָקוֹם הָאוֹכֵל וְשׁוֹתֶה עִמּוֹ אֵין לוֹ דִּין מְנֻדֶּה.\nאִם רָצוּ בֵּית דִּין לְמַעֵט הַנִּדּוּי מִל' יוֹם, אוֹ לְהוֹסִיף, הָרְשׁוּת בְּיָדָם. \u0005הַגָּה: \u0010y18\u0011 וְיֵשׁ רְשׁוּת לְבֵית דִּין לְהַחְמִיר עָלָיו \u0010y19\u0011 שֶׁלֹּא יָמוּלוּ בָּנָיו, וְשֶׁלֹּא יִקָּבֵר אִם יָמוּת (בִּנְיָמִין זְאֵב סי' רפ\"ט וְכֵן כָּתַב הַבֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ן סי' רמ\"ד)\u0006, \u0010c2\u0011 וּלְגָרֵשׁ אֶת בָּנָיו מִבֵּית הַסֵּפֶר וְאִשְׁתּוֹ מִבֵּית הַכְּנֶסֶת, עַד שֶׁיְּקַבֵּל עָלָיו הַדִּין \u0005(נ\"י פֶּרֶק הַגּוֹזֵל)\u0006.\nכְּשֶׁיַּגִּיעַ הַזְּמַן, מַתִּירִין לוֹ אִם יִרְצוּ, \u0010c3\u0011 אַף אִם לֹא יַחֲזֹר בּוֹ. וּמִכָּל מָקוֹם טוֹב, הוּא, שֶׁלֹּא יַתִּירוּ לוֹ אִם לֹא יַחֲזֹר בּוֹ, שֶׁלֹּא תִּתְמַעֵט יִרְאָתָם.\nאִם יִרְצוּ בֵּית דִּין \u0010c4\u0011 לְהַחְמִיר עָלָיו עוֹד וּלְהַחֲרִימוֹ, הָרְשׁוּת בְּיָדָם.\nאִם רָאוּ בֵּית דִּין קֹשִׁי הָאִסוּר וְהָעֲבֵרָה, מַחֲרִימִין גַּם הָאוֹכֵל וְשׁוֹתֶה עִמּוֹ וְהַיּוֹשֵׁב בְּד' אַמּוֹתָיו.\nאִם רָאוּ בֵּית דִּין לְנַדּוֹת, \u0010y20\u0011 שֶׁלֹּא יְזַמֵּן בִּשְׁלֹשָׁה, וְלֹא יִתְפַּלֵּל בַּעֲשָׂרָה, וְלֹא יִקְבְּרוּ לוֹ מֵת, וְלֹא יָמוּלוּ לוֹ בֵּן, רַשָּׁאִים הֵם. \u0010y21\u0011\nאִם נִתְנַדָּה עַל עֲבֵרָה, אֵינוֹ מִצְטָרֵף לַעֲשָׂרָה.\nהָא דְּאָמְרִינַן בִּמְנֻדֶּה סְתָם שֶׁהוּא אָסוּר בְּדִינֵי הַמְּנֻדֶּה, דַּוְקָא מְנֻדֶּה לְבֵית דִּין שֶׁהוּא מְנֻדֶּה לְכָל אָדָם, בֵּין דְּלֹא אָתֵי לְבֵית דִּין אוֹ דְּלֹא צָיֵת דִּינָא אוֹ לְאַפְקִירוּתָא אוֹ לִדְבַר עֲבֵרָה, בֵּין נִדּוּהוּ בֵּית דִּין, בֵּין שֶׁנִּדָּהוּ כָּל אָדָם, דִּינוֹ שָׁוֶה; בֵּין לְעִירוֹ, בֵּין לְעִיר אַחֶרֶת. אֲבָל מְנֻדֶּה לַחֲצָאִין, כְּגוֹן תַּלְמִיד שֶׁנִּדָּה לִכְבוֹדוֹ, וְכֵן מְנֻדֶּה לְעִיר אַחֶרֶת שֶׁנִּדּוּהוּ לִכְבוֹדָם, אֵינוֹ אָסוּר בְּכָל דִּין הַמְּנֻדֶּה, אֶלָּא שֶׁבְּנֵי אָדָם מַרְחִיקִין אוֹתוֹ כְּדֵי \u0010y22\u0011 לְבַיְּשׁוֹ, אֲבָל אֲבֵלוּת אֵין עָלָיו. \u0010c5\u0011\nהָא דְּאָמְרִינַן סְתָם נִדּוּי ל', הַיִנוּ לְעִנְיָן כְּשֶׁמְּנַדִּין אוֹתוֹ \u0010y23\u0011 אוֹמְרִים: פְּלוֹנִי יְהֵא בְּנִדּוּי שְׁלֹשִׁים יוֹם; וּמִכָּל מָקוֹם אִם חָזַר בּוֹ, \u0010y24\u0011 אִם הָיָה הַנִּדּוּי בִּשְׁבִיל מָמוֹן אוֹ אַפְקִירוּתָא וּפִיֵּס לְבַעַל דִּינוֹ, מַתִּירִין אוֹתוֹ לְאַלְתַּר. וַאֲפִלּוּ אִם לֹא חָזַר בּוֹ, יֵשׁ מִי שֶׁאוֹמֵר שֶׁמַּתִּירִין לוֹ לְאַחַר שְׁלֹשִׁים יוֹם, וְהוּא שֶׁיָּבֹא לְבֵית דִּין וּמְבַקֵּשׁ שֶׁיַּתִּירוּ לוֹ. אֲבָל אִם מְזַלְזֵל בַּנִּדּוּי וְאֵינוֹ מְבַקֵּשׁ שֶׁיַּתִּירוּ לוֹ, מַנִּיחִין אוֹתוֹ בְּנִדּוּי עַד שֶׁיָּמוּת. \u0010y25\u0011 וְיֵשׁ מִי שֶׁחוֹלֵק בָּזֶה \u0005וְסוֹבֵר דְּאַף לְאַחַר שְׁלֹשִׁים אֵין מַתִּירִין לוֹ עַד שֶׁיַּחֲזֹר (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006 ; וְתוֹךְ שְׁלֹשִׁים אֵין מַתִּירִין לוֹ אֲפִלּוּ חָזַר מִמַּה שֶּׁעָשָׂה \u0005(מַשְׁמָע בְּבֵית יוֹסֵף לְדַעַת הַרַמְבַּ\"ם)\u0006.\nנְזִיפָה הִיא שֶׁאָדָם גָּדוֹל גּוֹעֵר בּוֹ לוֹמַר: כַּמָּה פְּלוֹנִי חָצוּף, וְכַיּוֹצֵא בוֹ. \u0010y26\u0011 וְזֶה מִשְׁפָּטוֹ, שֶׁיְּהֵא מִתְחַבֵּא וְיוֹשֵׁב בְּבֵיתוֹ, וִיהֵא נִכְלָם, וְלֹא יַרְאֶה פָּנִים לְמִי שֶׁהִכְלִימוֹ, וִימַעֵט בִּשְׂחוֹק וּבְדִבּוּר וּבַעֲסָקָיו, וִיצַעֵר עַצְמוֹ לְעֵינֵי כָּל רוֹאָיו. אֲבָל אֵין צָרִיךְ לְהִתְרַחֵק מִבְּנֵי אָדָם, לֹא בַּאֲכִילָה וּשְׁתִיָּה, וְלֹא בִּשְׁאֵלַת שְׁלוֹם, וְאֵין צָרִיךְ לִנְהֹג בְּאַחַת מִכָּל דִּינֵי הָאֵבֶל, וְאֵין צָרִיךְ לְפַיֵּס לְמִי שֶׁהֶחֱצִיף כְּנֶגְדּוֹ, וְאֵין צָרִיךְ שֶׁיַּתִּירוּ לוֹ, אֶלָּא כֵּיוָן שֶׁנָּהַג כְּנָזוּף, \u0010y27\u0011 זְמַן נְזִיפָה, מֻתָּר מִמֵּילָא. \u0005הַגָּה: וַאֲפִלּוּ לֹא אָמַר לוֹ הַגָּדוֹל כְּלוּם, אֶלָּא שֶׁיּוֹדֵעַ בְּעַצְמוֹ שֶׁאָדָם גָּדוֹל נָקַט בְּלִבּוֹ עָלָיו, צָרִיךְ לִנְהֹג נְזִיפָה בְּעַצְמוֹ (תְּשׁוּבַת ר' דָּוִד כֹּהֵן סי' כ\"ב)\u0006.\nמְנֻדֶּה לָרַב, מְנֻדֶּה לַתַּלְמִיד. \u0010y28\u0011 \u0005אֲבָל אֵינוֹ מְנֻדֶּה לִשְׁאָר הַחֲכָמִים (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ם)\u0006. מְנֻדֶּה לַתַּלְמִיד שֶׁנִּדָּה לִכְבוֹדוֹ, אֵינוֹ מְנֻדֶּה לָרַב, \u0010y29\u0011 אֲבָל מְנֻדֶּה הוּא לִשְׁאָר הָעָם \u0005שֶׁאֵינָן חֲכָמִים. אֲבָל לֹא לַחֲכָמִים, אֲפִלּוּ קְטַנִּים מִמֶּנּוּ (בֵּית יוֹסֵף מִמַּשְׁמָעוּת לְשׁוֹן הַרַמְבַּ\"ם)\u0006. וְדַוְקָא בִּמְנֻדֶּה שֶׁלֹּא בִּפְנֵי הָרַב, אֲבָל בִּפְנֵי הָרַב, \u0010y30\u0011 אַפְקִירוּתָא הִיא, וְאִי פָּלִיג לֵיהּ רַבֵּיהּ יְקָרָא, שַׁפִּיר דָּמִי. \u0005רַב שֶׁגָּזַר חֵרֶם וְנִדּוּי בְּאֵיזֶה דָּבָר, \u0010y31\u0011 וְאֵין תַּלְמִידָיו יְכוֹלִין לַעֲמֹד בִּגְזֵרוֹתָיו, אֵין צְרִיכִין לְקַיֵּם (פִּסְקֵי מהרא\"י סי' רכ\"ב)\u0006.\nתַּלְמִיד יָכוֹל לְנַדּוֹת \u0010y32\u0011 לְמִי שֶׁבִּזָּה בְּפָנָיו רַבּוֹ אוֹ אָבִיו, וּמִכָּל מָקוֹם כֵּיוָן שֶׁלֹּא נִדָּהוּ הָרַב, וְגַם לֹא \u0010y33\u0011 נִדּוּהוּ בֵּית דִּין, אֵינוֹ מְנֻדֶּה לָרַב.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בְּמִי שֶׁנִּדּוּהוּ מִפְּנֵי שֶׁבִּזָּה תַּלְמִיד חָכָם. אֲבָל מִי שֶׁנִּדּוּהוּ עַל שְׁאָר דְּבָרִים שֶׁחַיָּב עֲלֵיהֶם נִדּוּי, אֲפִלּוּ נִדָּהוּ קָטָן שֶׁבְּיִשְׂרָאֵל, חַיָּב הַנָּשִׂיא וְכָל יִשְׂרָאֵל לִנְהֹג בּוֹ נִדּוּי, עַד שֶׁיַּחֲזֹר בִּתְשׁוּבָה מִדָּבָר שֶׁנִּדּוּהוּ בִּשְׁבִילוֹ וְיַתִּירוּ לוֹ.\nרַב מִצַּד הַשִּׁלְטוֹן וְאֵינוֹ רַב בַּתּוֹרָה, אֵינוֹ יָכוֹל לְנַדּוֹת לִכְבוֹדוֹ. \u0005הַגָּה: וְכָל שֶׁכֵּן מִי שֶׁנּוֹהֵג שְׂרָרָה אוֹ רַבָּנוּת מִצַּד מָמוֹנוֹ אוֹ יִחוּסוֹ, שֶׁאֵינוֹ יָכוֹל לְנַדּוֹת לִכְבוֹדוֹ (בֵּית יוֹסֵף בְּשֵׁם קֻנְטְרֵסִין)\u0006. וְדַוְקָא מְנַדִּין לִכְבוֹד הָרַב, \u0010y34\u0011 אֲבָל לֹא מַחֲרִימִין \u0005(בֵּית יוֹסֵף וריב\"ש סי' קע\"ג)\u0006, אִם לֹא שֶׁמַּחֲזִיק בְּמַחֲלֹקֶת יוֹתֵר מִדַּאי \u0005(שָׁם בריב\"ש)\u0006. וְהָא דְּאָמְרִינַן הָרַב שֶׁנִּדָּה לִכְבוֹדוֹ הָוֵי מְנֻדֶּה לְתַלְמִידָיו, הַיְנוּ אִם לֹא חָזַר בּוֹ הַמְּנֻדֶּה קֹדֶם שֶׁנִּדָּה אוֹתוֹ, \u0010y35\u0011 \u0010c6\u0011 אֲפִלּוּ אִם הִבְטִיחַ אֶת הָרַב לְפַיְּסוֹ אַחַר כָּךְ, לֹא מְהָנֵי עַד שֶׁיַּעֲשֶׂה. אֲבָל אִם קֹדֶם שֶׁנִּתְנַדָּה אָמַר לְפַיֵּס הָרַב, וְלֹא הִשְׁגִּיחַ עָלָיו, וְנִדָּהוּ, אֵינוֹ מְנֻדֶּה כְּלָל לְתַלְמִידָיו. וּמִיָּד שֶׁאוֹמֵר שֶׁיְּתַקֵּן אֲשֶׁר עִוֵּת כְּפִי מַה שֶּׁיַּגִּידוּ לוֹ חֲכָמִים, אֵין נִדּוּי עָלָיו \u0005(מהרי\"ק שֹׁרֶשׁ קס\"ט)\u0006. קָהָל שֶׁתִּקְּנוּ שֶׁאֵין אָדָם יָכוֹל לְנַדּוֹת לִכְבוֹדוֹ, אֵין בְּתַקָּנָתָם כְּלוּם, וְאִם עָמַד רַב וְנִדָּה לִכְבוֹדוֹ, נִדּוּיוֹ נִדּוּי \u0005(תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן ת\"ס)\u0006. \u0010y36\u0011\nזָקֵן שֶׁנִּדָּה לְצֹרֶךְ עַצְמוֹ, אֲפִלּוּ כַּהֲלָכָה, אֵינוֹ נִדּוּי. \u0005הַגָּה: \u0010y37\u0011 \u0010c7\u0011 פֵּרוּשׁ שֶׁלֹּא נִתְכַּוֵּן לִכְבוֹד תּוֹרָה, רַק לְהַרְוִיחַ מָמוֹן שֶׁיִּתֵּן לוֹ שֶׁיַּתִּיר לוֹ נִדּוּיוֹ (טוּר בְּשֵׁם אֲבִי הָעֶזְרִי)\u0006, אוֹ שֶׁעָשָׂה לוֹ מִשּׁוּם שִׂנְאָה, כְּגוֹן שֶׁאָנוּ רוֹאִים שֶׁנִּדָּה לְאֶחָד, וַאֲחֵרִים שֶׁעָשׂוּ כְּמוֹתוֹ לֹא נִדָּה \u0005(ת\"ה סי' רע\"ד)\u0006 וְכָל כַּיּוֹצֵא בָּזֶה. \u0010y38\u0011\nמְנֻדֶּה לְעִירוֹ, מְנֻדֶּה לְעִיר אַחֶרֶת. \u0005אֲפִלּוּ גְּדוֹלָה מִמֶּנָּהּ (טוּר)\u0006. מְנֻדֶּה לְעִיר אַחֶרֶת, אֵינוֹ מְנֻדֶּה לְעִירוֹ. \u0005הַגָּה: אֲבָל \u0010y39\u0011 מְנֻדֶּה לִשְׁאָר הָעֲיָרוֹת כַּיּוֹצֵא בְּעִיר שֶׁנִּדּוּהוּ (טוּר)\u0006. בְּנֵי הָעִיר שֶׁעָשׂוּ חֵרֶם עַל כָּל מִי שֶׁיָּבֹא לָדוּר בְּעִירָם, אֵינוֹ חָל עַל הַבָּא לָדוּר שָׁם, אֶלָּא אִם כֵּן יֵשׁ לוֹ רַב בָּעִיר דְּאָז צָרִיךְ לְקַיֵּם נִדּוּי רַבּוֹ. אֲבָל הֵם יְכוֹלִין לְתַקֵּן בֵּינֵיהֶם וְלִגְדֹּר עַל עַצְמָן שֶׁלֹּא יִשְׂאוּ וְיִתְּנוּ עִמּוֹ \u0005(מָרְדְּכַי פֶּרֶק לֹא \u0010y40\u0011 יַחְפֹּר)\u0006.\nמְנֻדֶּה לַנָּשִׂיא, מְנֻדֶּה לְכָל יִשְׂרָאֵל. מְנֻדֶּה לְכָל יִשְׂרָאֵל, אֵינוֹ מְנֻדֶּה לַנָּשִׂיא.\nנָהֲגוּ שֶׁלֹּא לִנְהֹג נִדּוּי בְּעוֹבֵר עַל גְּזֵרַת הַקָּהָל בְּחֵרֶם וְנִדּוּי, עַד שֶׁיַּכְרִיזוּ עָלָיו. \u0005הַגָּה: מִי שֶׁעָבַר עַל גְּזֵרַת רַבֵּנוּ גֵרְשׁוֹם מְאוֹר הַגּוֹלָה, אִם עָבַר בְּשׁוֹגֵג, אֵין צָרִיךְ הַתָּרָה. וְאִם הִתְרוּ בּוֹ וְעָבַר בְּמֵזִיד, כָּל בֵּי עֲשָׂרָה שְׁלוּחֵי רַבֵּנוּ גֵרְשׁוֹם הֵם לְהַתִּיר לוֹ כְּשֶׁחוֹזֵר מִדַּעְתּוֹ, דְּאַמְדִּינָן דַּעַת רַבֵּנוּ גֵרְשׁוֹם שֶׁכָּךְ הָיְתָה דַּעְתּוֹ מִתְּחִלָּה לִנְהֹג בּוֹ נְזִיפָה וְנִדּוּי לְפִי דַּעְתָּם (הַגָּהוֹת מָרְדְּכַי דב\"ק בְּשֵׁם תְּשׁוּבַת רַשִׁ\"י)\u0006. אֲבָל בְּדָבָר שֶׁגָּזַר בְּפֵרוּשׁ שֶׁיְּהֵא בְּנִדּוּי לְעוֹלָם, אָז הוּא בְּנִדּוּי לְעוֹלָם אִם עָבַר בְּמֵזִיד \u0005(ג\"ז שָׁם)\u0006.\nכֵּיצַד הַתָּרַת נִדּוּי, אוֹמְרִים לוֹ: \u0010c8\u0011 שָׁרוּי לְךָ, מָחוּל לְךָ, וְאִם הוּא שֶׁלֹּא בְּפָנָיו, אוֹמְרִים: \u0005(פְּלוֹנִי)\u0006 שָׁרוּי לוֹ.\nמַתִּירִין הַנִּדּוּי בִּשְׁלֹשָׁה הֶדְיוֹטוֹת, \u0010y41\u0011 אוֹ בְּיָחִיד מֻמְחֶה. וְתַלְמִיד מַתִּיר הַחֵרֶם וְהַנִּדּוּי, אֲפִלּוּ בִּמְקוֹם הָרַב. \u0005הַגָּה: וְכָל חֵרֶם וְנִדּוּי שֶׁלֹּא הֻתַּר, אֲפִלּוּ הָיָה זְמַן רַב בְּנִדּוּי וְחָזַר בּוֹ, אֲפִלּוּ הָכֵי אֵינוֹ מֻתָּר עַד שֶׁיַּתִּירוּ לוֹ בְּפֵרוּשׁ (בֵּית יוֹסֵף בְּשֵׁם קוּנְטְרֵס שכ\"כ בְּשֵׁם הָרַאֲבַ\"ד)\u0006.\nג' שֶׁנִּדּוּ וְהָלְכוּ לָהֶם, וְחָזַר בּוֹ מֵהַדָּבָר שֶׁנִּדּוּהוּ בִּגְלָלוֹ, מַתִּירִין לוֹ ג' אֲחֵרִים. וְיֵשׁ מִי שֶׁאוֹמֵר \u0010y42\u0011 שֶׁצָּרִיךְ שֶׁיִּהְיוּ גְּדוֹלִים כְּמוֹתָם \u0005בְּחָכְמָה וְיִרְאָה וּגְדֻלָּה וְשָׁנִים (כֵּן מַשְׁמָע מֵהַטּוּר)\u0006.\nנִדּוּהוּ ג', אֵין הַשְּׁנַיִם יְכוֹלִין לְהַתִּירוֹ אֶלָּא אִם כֵּן יִתֵּן לָהֶם הַשְּׁלִישִׁי רְשׁוּת. אֲבָל שְׁלָשְׁתָּן מַתִּירִין לוֹ, וְאֲפִלּוּ זֶה שֶׁלֹּא בִּפְנֵי זֶה, אַף עַל פִּי שֶׁהָיוּ בְּיַחַד בִּשְׁעַת הַנִּדּוּי. וְאִם הָיוּ רַבִּים בִּשְׁעַת שֶׁנִּדּוּהוּ, צָרִיךְ שֶׁיַּתִּירוּ כְּלוּם. וְכָל אוֹתָם שֶׁנִּמְלְכוּ בָּהֶם בִּשְׁעַת הַנִּדּוּי, חֲשׁוּבִים מֵהַמְנַדִּים \u0010y43\u0011 וְצָרִיךְ שֶׁיַּתִּירוּ גַּם הֵם.\nנִדּוּהוּ סְתָם, אַף עַל פִּי שֶׁעָבְרוּ עָלָיו ל' יוֹם, לְעוֹלָם עוֹמֵד בְּנִּדּוּיוֹ עַד שֶׁיַּתִּירוּהוּ. \u0010c9\u0011\nאִם זִלְזֵל בְּנִדּוּיוֹ וּבְחֶרְמוֹ, \u0010y44\u0011 צָרִיךְ לִנְהֹג אִסוּר כַּיָּמִים שֶׁנָּהַג הֶתֵּר קֹדֶם שֶׁיַּתִּירוּהוּ.\nנִדּוּהוּ בְּפָנָיו, אֵין מַתִּירִין לוֹ \u0010c10\u0011 אֶלָּא בְּפָנָיו. \u0005וְאִם הִתִּירוּ לוֹ שֶׁלֹּא בְּפָנָיו, \u0010y45\u0011 יֵשׁ אוֹמְרִים דִּבְדִיעֲבַד הָוֵי הֶתֵּר. (הר\"ן פ\"ק דִּנְדָרִים וְכֵן מַשְׁמָע מִתְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן תש\"ג)\u0006. נִדּוּהוּ שֶׁלֹּא בְּפָנָיו, מַתִּירִין לוֹ אֲפִלּוּ שֶׁלֹּא בְּפָנָיו.\nנִדּוּהוּ עַל תְּנַאי, חָל הַנִּדּוּי, וְצָרִיךְ הַתָּרָה אַף עַל פִּי שֶׁמְּקַיֵּם הַתְּנַאי. וַאֲפִלּוּ אִם נִדָּה אֶת עַצְמוֹ עַל תְּנַאי. וְדַוְקָא שֶׁהַמְנֻדֶּה מְסֻפָּק בִּשְׁעַת הַתְּנַאי אִם יָכוֹל לְקַיְּמוֹ, אֲבָל אִם בָּרוּר לוֹ שֶׁיָּכוֹל לְקַיְּמוֹ, אֵין צָרִיךְ הַתָּרָה. \u0010y46\u0011\nאֲפִלּוּ אִם קָבַע זְמַן, שֶׁאָמַר: יְהֵא בְּנִדּוּי, אִם לֹא יַעֲשֶׂה דָּבָר פְּלוֹנִי לִזְמַן פְּלוֹנִי, יְכוֹלִין לְהַתִּירוֹ מִיָּד \u0010c11\u0011 אַף עַל פִּי שֶׁלֹּא הִגִּיעַ הַזְּמַן.\nהַמְנַדֶּה עַצְמוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, \u0010y47\u0011 יֵשׁ אוֹמְרִים שֶׁאֵין לוֹ הַתָּרָה; לָכֵן שׁוֹמֵר נַפְשׁוֹ יִרְחַק מִמֶּנּוּ \u0005וְעַיֵּן לְעֵיל סִימָן רכ\"ח סָעִיף מ\"ה.\u0006\nתַּלְמִיד חָכָם שֶׁנִּדָּה לְעַצְמוֹ, מַתִּיר לְעַצְמוֹ אֲפִלּוּ נִדָּה עַל דַּעַת פְּלוֹנִי, וַאֲפִלּוּ עַל דָּבָר שֶׁחַיָּב עָלָיו נִדּוּי. וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאִם הָיָה חַיָּב נִדּוּי אֵינוֹ יָכוֹל לְהַתִּיר לְעַצְמוֹ. וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאִם הָיָה \u0010y48\u0011 \u0010c12\u0011 דֶּרֶךְ שְׁבוּעָה, אֵינוֹ יָכוֹל לְהַתִּיר לְעַצְמוֹ.\nמִי שֶׁאֵינוֹ תַּלְמִיד חָכָם, שֶׁנִּדָּה לְעַצְמוֹ, יֵשׁ מִי שֶׁאוֹמֵר \u0010y49\u0011 שֶׁצָּרִיךְ \u0010y50\u0011 עֲשָׂרָה שֶׁיַּתִּירוּ לוֹ.\nנִדּוּהוּ בַּחֲלוֹם, הָוֵי נִדּוּי וְצָרִיךְ הַתָּרָה, \u0010y51\u0011 וְאֲפִלּוּ הִתִּירוּ לוֹ בַּחֲלוֹם אֵינוֹ כְּלוּם. וַאֲפִלּוּ יוֹדֵעַ מִי נִדָּהוּ, אֵינוֹ יָכוֹל לְהַתִּירוֹ \u0010y52\u0011 \u0010c13\u0011 וְצָרִיךְ עֲשָׂרָה בְּנֵי אָדָם שֶׁשּׁוֹנִים הֲלָכוֹת לְהַתִּירוֹ. לֹא מָצָא, טוֹרֵחַ אַחֲרֵיהֶם עַד פַּרְסָה; לֹא מָצָא, מַתִּירִין לוֹ אֲפִלּוּ עֲשָׂרָה שֶׁשּׁוֹנִים מִשְׁנָה; לֹא מָצָא, מַתִּירִין לוֹ אֲפִלּוּ עֲשָׂרָה שֶׁיּוֹדְעִים לִקְרוֹת בַּתּוֹרָה; לֹא מָצָא, מַתִּירִין לוֹ אֲפִלּוּ עֲשָׂרָה שֶׁאֵינָם יוֹדְעִים לִקְרוֹת; \u0010c14\u0011 לֹא מָצָא בִּמְקוֹמוֹ עֲשָׂרָה, מַתִּירִין לוֹ אֲפִלּוּ שְׁלֹשָׁה. \u0010y53\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּאֵין לוֹ הַתָּרָה רַק עַל יְדֵי עֲשָׂרָה שֶׁשָּׁנוּ \u0010c15\u0011 הֲלָכוֹת אוֹ מִשְׁנָיוֹת (תּוֹסָפוֹת)\u0006, וּמִיהוּ סָגֵי אִם יַתִּירוּ לוֹ בָּזֶה אַחַר זֶה \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nיֵשׁ אוֹמְרִים מִי שֶׁנִּדּוּהוּ בַּחֲלוֹם, וְשָׁלַח שָׁלִיחַ לְהַתִּיר לוֹ שֶׁלֹּא בְּפָנָיו, \u0010y54\u0011 אִם מָצָא הַשָּׁלִיחַ הַעֲשָׁרָה מְכֻנָּסִים, מַתִּירִין לוֹ; \u0010y55\u0011 וְאִי לֹא, לֹא.\nהַשּׁוֹמֵעַ הַזְכָּרַת הַשֵּׁם מִפִּי \u0010c16\u0011 חֲבֵרוֹ לַשָּׁוְא, אוֹ שֶׁנִּשְׁבָּע בְּפָנָיו לַשֶּׁקֶר, אוֹ שֶׁבֵּרַךְ בְּרָכָה שֶׁאֵינָהּ צְרִיכָה, חַיָּב לְנַדּוֹתוֹ; וְאִם לֹא נִדָּהוּ, הוּא עַצְמוֹ חַיָּב נִדּוּי, וְצָרִיךְ לְהַתִּיר לוֹ מִיָּד, כְּדֵי \u0010y56\u0011 שֶׁלֹּא יְהֵא מִכְשׁוֹל לַאֲחֵרִים. \u0010c17\u0011\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁהָיָה הַנִּשְׁבָּע הַזֶּה, אוֹ הַמְבָרֵךְ לְבַטָּלָה, מֵזִיד. אֲבָל אִם הָיָה שׁוֹגֵג, וְלֹא יָדַע שֶׁזֶּה אָסוּר, אָסוּר לְנַדּוֹתוֹ.\nהַמְנַדֶּה אֶת חֲבֵרוֹ שֶׁלֹּא כַּדִּין, וְאָמַר לֵיהּ הַלָּה: אַדְּרַבָּה, נִדּוּי שֶׁל שֵׁנִי נִדּוּי. וְהָנֵי מִלֵּי, שֶׁזֶּה הַשֵּׁנִי הוּא גַּבְרָא רַבָּא \u0010y57\u0011 \u0005אַף עַל פִּי שֶׁאֵינוֹ נִסְמָךְ (מהרי\"ק שֹׁרֶשׁ קנ\"ח)\u0006, אוֹ שֶׁאֵינוֹ יָדוּעַ מִי הוּא, דְּחַיְשִׁינָן שֶׁמָּא הוּא יוֹתֵר גָּדוֹל מֵהַמְנַדֶּה. אֲבָל אִם הַמְנַדֶּה שֶׁלֹּא כַּדִּין תַּלְמִיד חָכָם, \u0010y58\u0011 וְהָאַחֵר אֵינוֹ תַּלְמִיד חָכָם, לֹא. \u0005הַגָּה: \u0010y59\u0011 וְהוּא הַדִּין תַּלְמִיד נֶגֶד רַבּוֹ לֹא יוּכַל לוֹמַר: אַדְּרַבָּה, אֶלָּא אִם נָטַל רְשׁוּת מִבֵּית דִּין (מהרי\"ק שֹׁרֶשׁ ק\"ע)\u0006. מִי שֶׁאָמַר לַחֲבֵרוֹ: אַל תַּעֲשֶׂה דָּבָר זֶה בְּנִדּוּי, וְזֶה אוֹמֵר לוֹ: אַדְּרַבָּה, אַף עַל פִּי שֶׁעוֹשֶׂה שֶׁלֹּא כַּדִּין, \u0010y60\u0011 מִכָּל מָקוֹם נִדּוּי הַשֵּׁנִי גַּם כֵּן אֵינוֹ כְּלוּם, הוֹאִיל וְלֹא נִדָּהוּ סְתָם, רַק שֶׁאָמַר לוֹ שֶׁאַל יַעֲשֶׂה הַדָּבָר בְּנִדּוּי \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת ריב\"ש)\u0006. \u0010y61\u0011\nתַּלְמִיד חָכָם, שֶׁבִּזָּהוּ רָשָׁע \u0010y62\u0011 עַד שֶׁנִּדָּהוּ, וְאָמַר לֵיהּ הָרָשָׁע; אַדְּרַבָּה, יַכְרִיזוּ עַל הָרָשָׁע שֶׁהוּא מְנֻדֶּה, וְיַעֲמֹד בְּנִּדּוּיוֹ ל' יוֹם, וְאַחַר כָּךְ יְבַקֵּשׁ מְחִילָה בָּרַבִּים. כָּךְ הוֹרָה הָרֹא\"שׁ. \u0010y63\u0011\nאָח גָּדוֹל בְּשָׁנִים שֶׁבִּזָּה לְאָחִיו הַקָּטָן בַּשָּׁנִים וְהוּא תַּלְמִיד חָכָם, וְנִדָּה הַקָּטָן בְּשָׁנִים לַגָּדוֹל בְּשָׁנִים, נִדּוּיוֹ נִדּוּי.\nחָכָם, זָקֵן בְּחָכְמָה, אוֹ אַב בֵּית דִּין שֶׁסָרַח, אֵין מְנַדִּין אוֹתוֹ בְּפַרְהֶסְיָא \u0010y64\u0011 לְעוֹלָם, אֶלָּא אִם כֵּן עָשָׂה כִּירָבְעָם בֶּן נְבָט וַחֲבֵרָיו. אֲבָל כְּשֶׁחָטָא שְׁאָר חֲטָאוֹת, \u0010y65\u0011 מַלְקִין אוֹתוֹ בְּצִנְעָא. וְכֵן כָּל תַּלְמִיד חָכָם שֶׁנִּתְחַיֵּב נִדּוּי, אָסוּר לְבֵית דִּין לִקְפֹּץ וּלְנַדּוֹתוֹ בִּמְהֵרָה, אֶלָּא בּוֹרְחִים וְנִשְׁמָטִים מִמֶּנּוּ. וַחֲסִידֵי הַחֲכָמִים הָיוּ מִשְׁתַּבְּחִים שֶׁלֹּא נִמְנוּ מֵעוֹלָם לְנַדּוֹת תַּלְמִיד חָכָם, וְאַף עַל פִּי שֶׁנִּמְנִים לְהַלְקוֹתוֹ אִם נִתְחַיֵּב מַלְקוֹת אוֹ מַכַּת מַרְדוּת. וְאִי סָנֵי שׁוּמְעָנֵיהּ, כְּגוֹן שֶׁמִּתְעַסֵק בְּסִפְרֵי אֶפִּיקוֹרוֹסִין וְשׁוֹתֶה בְּמִינֵי זֶמֶר, אוֹ שֶׁחֲבֵרָיו מִתְבַּיְּשִׁין מִמֶּנּוּ, \u0010y66\u0011 וְשֵׁם שָׁמַיִם מִתְחַלֵּל עַל יָדוֹ, מְשַׁמְּתִינָן לֵהּ.\nעַל כ\"ד דְּבָרִים מְנַדִּין אֶת הָאָדָם, וְאֵלּוּ הֵן: \u0005(א)\u0006 \u0010y67\u0011 הַמְבַזֶּה אֶת הֶחָכָם, אֲפִלּוּ לְאַחַר מוֹתוֹ. \u0005(ב)\u0006 \u0010y68\u0011 הַמְבַזֶּה שְׁלִיחַ בֵּית דִּין. \u0005(ג)\u0006 הַקּוֹרֵא לַחֲבֵרוֹ עֶבֶד. \u0005(ד)\u0006 \u0010y69\u0011 הַמְזַלְזֵל בְּדָבָר אֶחָד מִדִּבְרֵי סוֹפְרִים, וְאֵין צָרִיךְ לוֹמַר מִדִּבְרֵי תּוֹרָה. \u0010y70\u0011 \u0005(ה)\u0006 מִי שֶׁשָּׁלְחוּ לוֹ בֵּית דִּין וְקָבְעוּ לוֹ זְמַן, וְלֹא בָּא. \u0010y71\u0011 \u0005(ו)\u0006 מִי שֶׁלֹּא קִבֵּל עָלָיו אֶת הַדִּין, מְנַדִּין אוֹתוֹ עַד שֶׁיִּתֵּן. \u0005(ז)\u0006 מִי שֶׁיֵּשׁ בִּרְשׁוּתוֹ דָּבָר הַמַּזִּיק, מְנַדִּין אוֹתוֹ עַד שֶׁיָּסִיר הַנֵּזֶק. \u0010y72\u0011 \u0005(ח)\u0006 הַמּוֹכֵר קַרְקַע שֶׁלּוֹ לְגוֹי, מְנַדִּין אוֹתוֹ עַד שֶׁיְּקַבֵּל עָלָיו כָּל אֹנֶס שֶׁיָּבֹא מֵהַגּוֹי לְיִשְׂרָאֵל חֲבֵרוֹ בַּעַל הַמֶּצֶר. \u0010y73\u0011 \u0005(ט)\u0006 הַמֵּעִיד עַל יִשְׂרָאֵל בְּעֶרְכָּאוֹת שֶׁל \u0010c18\u0011 גּוֹיִים, וְהוֹצִיא מִמֶּנּוּ מָמוֹן בְּעֵדוּתוֹ, שֶׁלֹּא כַּדִּין, מְנַדִּין אוֹתוֹ עַד שֶׁיְּשַׁלֵּם. \u0010y74\u0011 \u0005(י)\u0006 טַבָּח כֹּהֵן שֶׁאֵינוֹ מַפְרִישׁ הַמַּתָּנוֹת, וְנוֹתְנָם לְכֹהֵן אַחֵר, מְנַדִּין אוֹתוֹ עַד שֶׁיִּתֵּן. \u0010y75\u0011 \u0005(י\"א)\u0006 הַמְחַלֵּל יוֹם טוֹב שֵׁנִי שֶׁל גָּלֻיּוֹת, אַף עַל פִּי שֶׁהוּא מִנְהָג. \u0010y76\u0011 \u0005(י\"ב)\u0006 הָעוֹשֶׂה מְלָאכָה בְּעֶרֶב פֶּסַח אַחַר חֲצוֹת. \u0010y77\u0011 \u0005(י\"ג)\u0006 \u0010c19\u0011 הַמַּזְכִּיר שֵׁם שָׁמַיִם לְבַטָּלָה, אוֹ לִשְׁבוּעָה בְּדִבְרֵי הֲבַאי. \u0005(י\"ד)\u0006 הַמֵּבִיא אֶת הָרַבִּים לִידֵי אֲכִילַת קָדָשִׁים בַּחוּץ. \u0005(ט\"ו)\u0006 הַמֵּבִיא רַבִּים לִידֵי חִלּוּל הַשֵּׁם. \u0010y78\u0011 \u0005(ט\"ז)\u0006 הַמְחַשֵּׁב שָׁנִים וְקוֹבֵעַ חֳדָשִׁים בְּחוּצָה לָאָרֶץ. \u0005(י\"ז)\u0006 הַמַּכְשִׁיל אֶת הָעִוֵּר. \u0005(י\"ח)\u0006 הַמְעַכֵּב אֶת הָרַבִּים מִלַּעֲשׂוֹת מִצְוָה. \u0010y79\u0011 \u0005(י\"ט)\u0006 טַבָּח שֶׁיָּצְתָה טְרֵפָה מִתַּחַת יָדוֹ. \u0010y80\u0011 \u0005(כ)\u0006 טַבָּח שֶׁלֹּא הֶרְאָה בְּדִיקַת סַכִּינוֹ לְחָכָם. \u0010y81\u0011 \u0005(כ\"א)\u0006 הַמַּקְשֶׁה עַצְמוֹ לָדַעַת. \u0010y82\u0011 \u0005(כ\"ב)\u0006 הַמְגָרֵשׁ אֶת אִשְׁתּוֹ, וְעָשׂוּ בֵּינוֹ וּבֵינָהּ שֻׁתָּפוּת אוֹ מַשָּׁא וּמַתָּן הַמְּבִיאָן לְהִזָּקֵק זֶה לָזֶה, כְּשֶׁיָּבוֹאוּ לְבֵית דִּין, מְנַדִּין אוֹתָם. \u0010y83\u0011 \u0005(כ\"ג)\u0006 חָכָם שֶׁשְּׁמוּעָתוֹ רָעָה. \u0010y84\u0011 \u0005(כ\"ד)\u0006 \u0010y85\u0011 \u0010c20\u0011 הַמְנַדֶּה לְמִי שֶׁאֵינוֹ חַיָּב נִדּוּי. \u0005הַגָּה: וְאֵין צְרִיכִין לְעִנְיַן נִדּוּי עֵדוּת וּרְאָיָה בְּרוּרָה, אֶלָּא אֹמֶד הַדַּעַת בַּאֲמִתּוּת הַדְּבָרִים, שֶׁהַתּוֹבֵעַ טוֹעֵן בָּרִי וְאָז אֲפִלּוּ אִשָּׁה אֲפִלּוּ קָטָן נֶאֱמָן, אִם הַדַּעַת נוֹתֵן שֶׁאֱמֶת הַדָּבָר (מהרי\"ק שֹׁרֶשׁ ק\"כ)\u0006. \u0010y86\u0011\nחָכָם שֶׁהוֹרָה לְהַתִּיר בְּמַיִם שֶׁאֵין לָהֶם סוֹף, \u0010y87\u0011 חַיָּב נִדּוּי. וְכֵן מִי שֶׁעוֹבֵר עַל נִדְרוֹ, וְכָל בֵּית דִּין שֶׁנִּזְקָק לוֹ לִשְׁאֵלָה, בַּר שַׁמְתָּא הוּא. וְכֵן הָעוֹשִׂים מְלָאכָה בְּעוֹד שֶׁיֵּשׁ מֵת בָּעִיר, וַעֲדַיִן לֹא נִקְבַּר, חַיָּבִים נִדּוּי, אֶלָּא אִם כֵּן יֵשׁ חֲבוּרוֹת בָּעִיר. וְכֵן מִי שֶׁעוֹשֶׂה קַלִּים וַחֲמוּרִים, אוֹ גְּזֵרָה שָׁוָה לַעֲקֹר דָּבָר מִן הַתּוֹרָה, אוֹ שׁוֹאֵל דָּבָר שֶׁאִי אֶפְשָׁר. וְכֵן מִי שֶׁיֵּשׁ לוֹ עִרְעוּר עַל חֲבֵרוֹ בְּדָבָר אֶחָד, וּמוֹסֵר אוֹתוֹ לְמֶלֶךְ אוֹ לְשׁוֹפֵט גּוֹי, מְשַׁמְּתִין לֵיהּ עַד דְּמַיְתֵי לֵיהּ וְקַיְימֵי בְּבֵית דִּין. וְכֵן תַּלְמִיד חָכָם הַמַּחֲזִיק בְּמַחֲלֹקֶת כְּנֶגֶד הָרַבִּים. וְכֵן הַמּוֹרֶה הוֹרָאָה בִּמְקוֹם רַבּוֹ. \u0010c21\u0011\nצוֹרְבָא מִדְּרַבָּנָן, יָכוֹל לְנַדּוֹת לְמִי שֶׁהִפְקִיר כְּנֶגְדּוֹ. \u0010y88\u0011 וְאִם דִּינוֹ פָּסוּק, כְּגוֹן שֶׁקְּרָאוֹ: עֶבֶד, הוּא \u0010y89\u0011 מְנֻדָּה לְכָל יִשְׂרָאֵל; וְאִם אֵין דִּינוֹ פָּסוּק, אֵינוֹ \u0010y90\u0011 מְנֻדֶּה אֶלָּא לִקְטַנִּים מִמֶּנּוּ. \u0005וַאֲפִלּוּ לֹא בִּזָּהוּ בְּפֵרוּשׁ, רַק שֶׁכִּוֵּן לְבַזּוֹתוֹ לְפִי אֻמְדָּנָא הַמּוּכָח (מהרי\"ק ש\"א)\u0006.\nרְאוּבֵן שֶׁחַיָּב לְשִׁמְעוֹן מָמוֹן, \u0010y91\u0011 וּמְסָרֵב מִלְּפָרְעוֹ, אִם נִדָּה שִׁמְעוֹן לִרְאוּבֵן שֶׁיִּפְרָעֶנּוּ, \u0010y92\u0011 נִדּוּיוֹ נִדּוּי. \u0005הַגָּה: \u0010y93\u0011 וְיֵשׁ אוֹמְרִים דְּלֹא עָבִיד אֱינָשׁ דִּינָא לְנַפְשֵׁיהּ לְנַדּוֹת חֲבֵרוֹ עַל דְּבַר מָמוֹן (שָׁם שֹׁרֶשׁ כ\"ה בְּשֵׁם מהר\"מ וְרַאֲבַ\"ד)\u0006, וְכֵן \u0010y94\u0011 עִקָּר; כָּל שֶׁכֵּן אִם חֲבֵרוֹ אוֹמֵר לִהְיוֹת לוֹ צָיֵת דִּין \u0005(מהרי\"ו סִימָן רכ\"ט)\u0006.\nהַמְבַזֶּה אֶת הֶחָכָם, אֲפִלּוּ בִּדְבָרִים, וַאֲפִלּוּ לְאַחַר מִיתָה, \u0010y95\u0011 אִם יֵשׁ עֵדִים בַּדָּבָר, בֵּית דִּין מְנַדִּין אוֹתוֹ בָּרַבִּים, וְהֵם מַתִּירִין לוֹ כְּשֶׁיַּחֲזֹר בִּתְשׁוּבָה. אֲבָל אִם הֶחָכָם חַי, אֵין מַתִּירִין לוֹ עַד שֶׁיְּרַצֶּה הֶחָכָם שֶׁנִּדּוּהוּ בִּשְׁבִילוֹ. \u0005מִיהוּ אִם עָשָׂה הַמֻּטָּל עָלָיו, וְאֵין הֶחָכָם רוֹצֶה לִמְחֹל, מַתִּירִין לוֹ נִדּוּיוֹ (בֵּית יוֹסֵף)\u0006. וְכֵן הֶחָכָם בְּעַצְמוֹ מְנַדֶּה לִכְבוֹדוֹ לְעַם הָאֶרֶץ שֶׁהִפְקִיר כְּנֶגְדּוֹ, וְאֵין צָרִיךְ לֹא עֵדִים וְלֹא הַתְרָאָה, וְאֵין מַתִּירִין לוֹ עַד שֶׁיְּרַצֶּה הֶחָכָם; וְאִם מֵת הֶחָכָם, בָּאִים שְׁלֹשָׁה וּמַתִּירִין לוֹ. \u0005הַגָּה: וְעַיֵּן לְעֵיל סוֹף סי' רמ\"ג (בהג\"ה)\u0006, אִם דָּנִין בַּזְּמַן הַזֶּה דִּין תַּלְמִיד חָכָם. הַקּוֹרֵא לְחָכָם: מַלְשִׁין, אוֹ מַסוּר, אֵין לְךָ בִּזּוּי גָּדוֹל מִזֶּה, וּמְנַדִּין עַל זֶה \u0005(מהרי\"ק שֹׁרֶשׁ ק\"פ)\u0006.\nאִם נִדּוּ לְאָדָם אֶחָד עַל שֶׁעָבַר עֲבֵרָה, וְגָזַר הַשַּׂר עֹנֶשׁ עַל מִי שֶׁיַּחֲזִיק הַנִּדּוּי, חַיָּבִים לִכָּנֵס בְּסָפֵק עֹנֶשׁ כְּדֵי לְהַחֲזִיק דָּתֵנוּ. אֲבָל אִם נִדּוּהוּ עַל דְּבָרִים שֶׁבֵּינוֹ לַחֲבֵרוֹ, כְּגוֹן שֶׁהוֹלִיכוֹ לְעֶרְכָּאוֹת, אֵין אָנוּ חַיָּבִים לִכָּנֵס בְּסַכָּנַת הָעֹנֶשׁ. \u0005הַגָּה: \u0010y96\u0011 וְעַיֵּן לְעֵיל סי' רכ\"ח סָעִיף מ\"ז וְגַם בְּסִימָן רל\"ב סָעִיף י\"ב. אַף עַל פִּי שֶׁחַיָּב אָדָם לִמְחוֹת בְּעוֹבְרֵי עֲבֵרָה, וְכָל מִי שֶׁאֵינוֹ מוֹחֶה, וּבְיָדוֹ לִמְחוֹת, נִתְפָּס בְּאוֹתוֹ עָוֹן, מִכָּל מָקוֹם אֵין אָדָם חַיָּב לְהוֹצִיא מָמוֹנוֹ עַל זֶה. \u0010c22\u0011 וְלָכֵן נָהֲגוּ לְהָקֵל מִלִּמְחוֹת בְּעוֹבְרֵי עֲבֵרָה, שֶׁיֵּשׁ לָחוּשׁ שֶׁיִּהְיוּ עוֹמְדִין עַל גּוּפֵנוּ וּמְאֹדֵנוּ (מהרי\"ו סִימָן קנ\"ז)\u0006.",["\u0003על דבר איסור כו'. \u0004ע\"ל סעיף מ\"ג אם מנדין באיסור דרבנן:","\u0003מנדין אותו לאלתר. \u0004משמע אפי' בלא התראה מיהו בקונטרסים שהביא ב\"י משמע דאפי' לדבר איסור לא נהגו לנדות אלא לאחר התראה:","\u0003ואין נידוי פחות מל' יום. \u0004כ' ב\"י בשם הקונטרסים דנ\"מ אם חכם נדהו משו' כבודו והלך לו אין מתירין לו עד אחר ל' יום לדידהו ולדידן ז' ימים דכיון דהלך לו מסתמא ניחא ליה שיתירוהו אחר זמן זה וכן נראה דנ\"מ למי שעומד במרדו ואמרינן לנדותו פעם שנית שמנדין לאלתר ושונין לאחר ז' ומחרימין אחר י\"ד דהא בהא תליא כן נ\"ל להלכה אבל לא למעשה מפני שלא ראיתי לא' מן הראשונים שכ' כן עכ\"ל ור\"ל דודאי אין לפרש דאין ביד הב\"ד למעט הנידוי פחות מל' יום דהא ליתא כדלקמן סעיף ו':","\u0003ממתינים לו עוד ל' כו'. \u0004עיין בח\"מ סי' י\"ט:","\u0003בנידוי דידהו. \u0004כלומר של בני א\"י:","\u0003כנזיפה. \u0004ענין נזיפה הוא לקמן סעיף י\"ד:","\u0003אין יושבין בד' אמותיו. \u0004וד' אמות אלו הן ח' אמות דהיינו שהוא באמצען וד\"א לכל צד וד\"א אלו תפסי אפי' בר\"ה או בסמטא או בשדה הפקר אבל לא בבית אחר. מקונטרסים שהביא ב\"י:","\u0003ואין מזמנין עליו כו'. \u0004דוקא נתנדה מחמת עבירה כדלקמן סעיף י\"א אבל לא שנתנדה מחמת ממון כן הוא בתשו' הרשב\"א שהביא בב\"י לקמן:","\u0003אע\"פ שהוא עבריין כו'. \u0004וכך כתב המחבר בא\"ח סי' נ\"ה סי\"א:","\u0003מותר להתפלל בעודו בב\"ה. \u0004אלא א\"כ פירשו עליו להחמיר בכך כ\"כ המחבר שם סעיף י\"ב:","\u0003שלא ידחוק יחידים כו'. \u0004כלומר אותן שבאו לארבע אמותיו אבל אותן שהיו תחלה שם ובא אצלן א\"צ להתרחק כדלקמן בהג\"ה:","\u0003ואסור בתכבוסת כו'. \u0004אבל א\"צ קריעה ועטיפת ראש וכפיית המטה כאבל ומותר ברחיצה וסיכה ותשמיש המטה ובתפילין ושאלת שלום כן הסכמת רוב הפוסקים:","\u0003ובנעילת הסנדל כו'. \u0004וכ\"פ בא\"ח סימן תקנ\"ד סעיף י\"ז ולקמן סימן פ\"ב ס\"ד ותימה דבב\"י פסק כאן דמותר בנעילת הסנדל וכ\"כ הריב\"ש ס\"ס קע\"ג בשם הרשב\"א והכי נהוג:","\u0003ואסור ליכנס לביתו. \u0004בעודו בבית וכתב בד\"מ דלא משמע כן מתשובה שאכתוב למטה (וכתבו הרב לעיל בהג\"ה) ואפשר לחלק בין בית לבית הכנסת עד כאן לשונו ודבר פשוט הוא שהרי בקונטרסים גופיה כתב דטעם דד\"א הוא מפני שהן חצרו:","\u0003ואין חלוק בין עומד כו'. \u0004וצ\"ע אי מהלך תופס ארבע אמות. שם:","\u0003ומניחין אבן על ארונו. \u0004ואין צריך לעשות עליו גל כגלו של עכן:","\u0003ואין קורעין כו'. \u0004ע\"ל סימן שמ\"ה ס\"ד וסי' שע\"ז:","\u0003ולא חולצין כו'. \u0004אבל כבודם של חיים עושים לאבלים עומדים בשורה ומנחמין. רמב\"ן. וגם לענין קבורה ותכריכי המת הוא כשאר בני אדם. תשובת רשב\"א. וכתב עוד דאפילו מוחרם בקברי אבותיו הוא נקבר ומביאו ב\"י ע\"ש:","\u0003ויש רשות לב\"ד כו'. \u0004ואין זה משום נשבע לבטל את המצוה דלמיגדר מילתא ב\"ד מתנין לעקור דבר תורה:","\u0003שלא ימולו. \u0004צ\"ע דהא כבר כתבו המחבר בסעיף י':","\u0003שלא יזמן בשלשה. \u0004צ\"ע דהא בזימון ובתפלה בי' בלא\"ה כל מנודה אסור כדלעיל סעיף ב' והרמב\"ן שכתב כן אפשר דסבירא ליה דמנודה אינו אסור בזימון וצירוף י' אלא שהרשות ביד ב\"ד להחמיר עליו ולפי מ\"ש לעיל דדוקא בנתנדה מחמת עבירה אינו מצטרף לזימון ולעשרה (כדמשני) [כמ\"ש] בסעיף שאחר זה אבל לא בנתנדה מחמת ממון י\"ל דהמחבר אשמועינן דבנתנדה מחמת ממון הרשות ביד ב\"ד לנדות שלא יזמן בג' ולא יתפלל בי':","\u0003אם נתנדה על עבירה כו'. \u0004דמחמת שנעשה עבריין בעבירה חמורה שנתנדה עליה אינו ראוי לחבורה ודוקא נתנדה אבל עבר עבירה לחוד אע\"פ שהוא עבריין מצטרף כדלעיל סעיף ב' בהג\"ה ובממון אפי' נתנדה מצטרף:","\u0003אבל אבילות אין עליו. \u0004שאין אבילות לחצאין הילכך מותר בתכבוסת ותספורת ובנעילת הסנדל ונראה דלצירוף זימון ומנין מ\"מ אסור אם נתנדה מחמת עבירה שהרי אין זה מטעם אבילות דהא אבל מצטרף לזימון ומנין כדלקמן ס\"ס שע\"ט:","\u0003אומרים פלוני יהא בנידוי כו'. \u0004ר\"ל כשמנדים אותו סתם אמרינן שיהא בנידוי ל' יום:","\u0003אם היה הנדוי בשביל ממון כו'. \u0004בטור איתא (בלשון הראב\"ד) או בשביל עבירה כו' ונ\"ל שאינו מדוקדק דא\"כ היאך כתב אח\"כ ואפי' לא חזר בו מתירין אותו לאחר ל' דהיאך יתכן להתיר לו אם לא חזר מהעבירה וכן נתבאר בריש הסימן דאם לא חזר בו ממתינין לו עוד ל' יום כו' ודוחק לומר דהתם איירי שאינו בא לבית דין ומבקש שיתירוהו לו וכן בלשון הראב\"ד גופיה שבאשר\"י לא כתב או לדבר עבירה אלא כתב דבממונא מתירין אותו אחר ל' אפי' לא פייס לבעל דינו וכן הוא ברבי' ירוחם ני\"ד ונ\"ל דהאי ואפי' לא חזר בו [לא] קאי אלדבר עבירה ונראה של זה השמיט המחבר האי או לדבר עבירה:","\u0003ויש מי שחולק בזה. \u0004כב\"י שהוא הרמב\"ם שהעתיק לקמן סעיף מ\"ז דבריו שכתב עד שירצה החכם וצ\"ע קצת למה הביא כאן סברא הראשונה כיון שסתם לקמן כדברי הרמב\"ם ואפשר דס\"ל דחכם שאני:","\u0003וזה משפטו ושיהא מתחבא כו'. \u0004וכתב בקונטרסים משמע לי שאסו' בתספורת אותו היום דאין למתאנח ועצב [ראוי] לספר ולגלח עכ\"ל ב\"י:","\u0003זמן נזיפה. \u0004היינו ז' לבני א\"י ויום א' לבני בבל כדלעיל ריש הסימן:","\u0003אבל אינו מנודה לשאר החכמים. \u0004אפי' הם קטנים ממנו. ב\"י וד\"מ וע' ס\"ק ל' מ\"ש בזה:","\u0003אבל מנודה הוא לשאר העם שאינם חכמים כו'. \u0004הוא ממשמעות ב\"י והוא מדברי הרמב\"ם אבל באמת פשט הש\"ס והפוסקים משמע דדוקא לרב אינו מנודה אבל לשאר כל העולם מנודה אפי' לחכמים כמותו וכ\"כ הרב חסדאי ובעל הקונדריסים והריב\"ש דמנודה אפי' לחכמים כמותו כל שאינן גדולים ממנו ומביאם ב\"י אלא שכתב דמדברי הרמב\"ם שכתב) כל אדם משמע דאינו מנודה אלא לשאר העם ולא לתלמידים אפילו הם קטנים ממנו מאחר שהם ג\"כ תלמידים ולענין מעשה אין בידינו להחמיר יותר ממאי דמשמע מדברי הרמב\"ם עכ\"ל ולפע\"ד אין כדאי בדקדוק זה לפרש כל העם ולא חכמי' כיון שפשט הש\"ס והפוסקים לא משמע כן והנך רבוותא דלעיל כתבו בפירוש דאפי' חכמים כמותו חייבים לנהוג בו נידוי וגם הטור כתב דנדויו נידוי לשאר כל אדם וכן משמע בש\"ס פרק אלו מגלחין ריש (מועד קטן דף י\"ז) מנודה לתלמיד אינו מנודה לרב לרב הוא דאינו מנודה הא לכ\"ע מנודה כו' משמע דלכ\"ע מנודה אפילו לחכמים כמותו לבד מרבו וכ\"כ רש\"י דף ט\"ז סוף ע\"א אינו מנודה לרב אבל לכ\"ע מנודה וכ\"כ ר' ירוחם ני\"ד ח\"א אינו מנודה לרב אבל לכנ העולם מנודה ונראה שגם דעת הרמב\"ם כן ולפ\"ז כ\"ש ברב שנידה שמנודה לשאר החכמים מיהו נראה [דדוקא] שאם התלמיד הוא ת\"ח שראוי לנדות לכבודו וכדלקמן סעיף י\"ח:","\u0003אפקירותא היא. \u0004מן התלמיד והתלמיד עצמו צריך נידוי:","\u0003ואין תלמידיו יכולים לעמוד בגזרותיו כו'. \u0004כ\"כ הרב ג\"כ לעיל ס\"ס רכ\"ח לענין גזירת הקהל:","\u0003למי שביזה בפניו. \u0004אע\"פ שאינו בפני הרב:","\u0003אינו מנודה לרב. \u0004וה\"ה לגדול מן התלמיד בחכמה. ריב\"ש ונראה דאפילו אותו גדול הוא תלמיד של אותו הרב שנידוהו לכבודו מ\"מ כיון דאינו מנודה לרב אינו חייב לנהוג בו נידוי:","\u0003אבל לא מחרימין. \u0004(על) [מלשון] זה משמע דאפי' אחרים אינם יכולים להחרים לכבוד הרב אע\"פ שאין הרב מחרים בעצמו וכדעת ב\"י מיהו היינו דוקא יחיד אבל ב\"ד פשיטא שיכולים להחרים:","\u0003אפילו אם הבטיח הרב לפייסו אח\"כ. \u0004כלומר אפי' אם הבטיח אחר הנידוי לפייס ל\"מ עד שיעשה וע\"ל סי' רמ\"ג ס\"ח אם ת\"ח בזמן הזה יכול לנדות לעצמו:","\u0003זקן שנידה כו'. \u0004כלומר ת\"ח שנידה אע\"פ שנידה כהלכה דהעושה כן חייב נידוי מ\"מ כיון דלא מתכוין לכבוד התורה אינו נידוי וכדמפרש הרב ואזיל:","\u0003פירוש שלא נתכוין כו'. \u0004ובהג\"מ בשם הרמ\"ך פי' דהיינו כשלא ביזהו כלל אלא שאינו מכבדו כמו שחייב לכבדו בקימה והידור אין נידויו נדוי ומהרי\"ק בשם מהר\"מ פירש דאיירי בנידהו לפני רבו (וכמ\"ש הראב\"ד והמחבר לעיל סט\"ו) ועוד תירץ דמיירי שנידה אותו בשביל שמעכב ממונו שלא כדין אף ע\"פ שכהלכה נידהו אין נידויו נידוי וכ\"כ הרא\"ש בתשו' וע\"ל סמ\"ו:","\u0003מנודה לעירו כו'. \u0004פי' הב\"ח דהיינו במנודה מחמת כבוד דאפקיר כנגדם אע\"פ שלא הפקיר בבי דינא אבל במנודה לב\"ד מחמת דלא ציית דינא או באפקרותא דב\"ד [או] לדבר עבירה דינו שוה בין לעירו ובין לעיר אחרת דלכל ישראל הוא מנודה וחייבים לנהוג בו נידוי וכ\"פ העט\"ז:","\u0003לשאר העיירות כיוצא בה. \u0004אבל לא לעדיפי מינה כמ\"ש ב\"י:","\u0003מנודה לנשיא. \u0004שנידוהו לכבודו:","\u0003או ביחיד מומחה. \u0004נראה דהאידנא ליכא יחיד מומחה כמו לענין נדרים לעיל ר\"ס רכ\"ח אבל מדברי הב\"ח שכתב כאן סתמא דנקטי' דמותר ביחיד מומחה אפי' שאינו סמוך לא משמע כן ונראה לחלק דהתם בעינן גמיר וסביר בדיני נדרים משא\"כ הכא:","\u0003שצריך שיהיו גדולים כו'. \u0004כתב הראב\"ד בהשגות פ\"ז דהא דבעינן המתירים כחשבון המנדים וכחשיבותן היינו כשבאין להתיר תוך זמן הנדר אבל כשישלים הזמן כל ג' או יחיד מומחה מתירין לו אי נמי כשנידהו יחיד אפילו אינו מומחה על דבר עבירה כשישלים לו זמן מתירין לו כל ג' או יחיד מומחה אבל נידוהו רבים צריכים רבים כמותן להתירו עכ\"ל ומביאו הב\"ח ועיין מ\"ש לעיל סעיף א' בשם הקונדרסים:","\u0003וצריך שיתירו גם הם. \u0004או בני אדם כנגדם חשובים כמותם [כן] כתב הטור בשם הראב\"ד: נידוהו ואינו יודע מי נידהו אין אחרים יכולים להתירו אלא הנשיא (ש\"ס):","\u0003צריך לנהוג כו'. \u0004ע\"ל סי' ר\"ח ס\"ק י\"ד מ\"ש בזה:","\u0003י\"א דבדיעבד הותר. \u0004דטעמא דמלתא דאין מתירין לו אלא בפניו הוא משום חשדא דפעמים שיתירוהו והמנודה לא ידע וכשלא ינהגו בו נידוי יבא לחשדן ויבאו ג\"כ לזלזל פעם אחרת בנידוי אבל נידהו שלא בפניו ליכא חשדא דאף הוא סובר שמא התירוהו שלא בפניו כשם שנידוהו שלא בפניו ולפ\"ז כל שהודיעוהו דליכא חשדא מתירין לו שלא בפניו (אפי' לכתחלה) וכל שהתירוהו נמי אפילו לא הודיעו מותר (דכולי האי לא גזרו) כ\"כ הר\"ן מיהו הרא\"ש הביא די\"מ דאפי' דיעבד אינו מותר ומשמע מדבריו דאפילו לכתחלה לכ\"ע אין להתיר לו אפילו ע\"י שיודיעוהו:","\u0003אפילו אם קבע כו'. \u0004אע\"פ שלא הגיע הזמן דלא אמרו שאינו יכול להתירו עד שיחול אלא גבי נדר אבל נידוי קל טפי בהתרה שהמנדה מתיר לעצמו (כדלקמן סעיף ל\"ג) כ\"כ הרא\"ש בתשובה והעט\"ז וכב\"י דאפי' נידוהו אחרים דינא הכי כך פסק הב\"ח ותימה דלעיל סימן רכ\"ח סי\"ז פסקו המחבר והעט\"ז והב\"ח דה\"ה דהמנדה עצמו על תנאי שאין מתירין לו עד שיחול כמו נדר והוא דעת הרשב\"א וכן בב\"ח סי' רכ\"ח כתב אדברי הרשב\"א והרא\"ש כ' בתשובה נידוי שנידה ע\"ת יכול להתירו אע\"פ שלא חל ע\"כ וצ\"ע ולענין הלכה אע\"פ שפסקו הב\"י והב\"ח כאן כהרא\"ש ודלא כהמרדכי פרק האומנין הרי נראין הדברים דאישתמיטתהו דברי הרשב\"א ועוד שהרי הם עצמם פסקו בסי' רכ\"ח כהרשב\"א הלכך אין מדבריהם הכרע והדרינן לכללא דיחיד ורבים הלכה כרבים דהרא\"ש ה\"ל יחידאי לגבי הרשב\"א והמרדכי (והוא בריב\"ש ס\"ס רע\"ב) וכ\"נ מדברי הריב\"ש שהביא הב\"י בסי' רכ\"ח ד' רס\"ח ע\"א שכ' על מי שקבל עליו בחרם לעשות דבר פלוני תוך שנה הרי זה כמו שנשבע שמכאן ועד זמן פלוני יעשה דבר פלוני שמעתה חלה עד שיעבור הזמן כו' וכן מוכח להדיא מדבריו בתשובה סי' קפ\"ה וסי' רפ\"ב שכתב מה שנסתפק לכם בהיתר החרם הוא מחמת שלא הגיע הזמן פרעון עדיין בשעת היתר החרם ואין מתירין הנדר עד שיחול וה\"ה לחרם ושבועה אין בזה חשש שלא נאמר זה אלא ביחיד הנודר אבל בחרמי תקנות הקהל לא כו' והרי כאלו התנו כן בפירוש בשעת הנדר והחרם כו' וכ\"נ עיקר:","\u0003שאין לו התרה. \u0004שכיון שנידה עצמו בעה\"ב הכניס עצמו בנידוי שלמעלה ומי יתירנו לו:","\u0003דרך שבועה. \u0004שאמר אני נשבע להיות בנידוי אם אעשה דבר פלוני. ב\"י ופרישה:","\u0003שצריך עשרה כו'. \u0004נראה מדברי הב\"ח דה\"ה לעיל סעיף ל\"ג בת\"ח דאינו יכול להתיר לעצמו צריך י' שיתירו לו וע\"ש:","\u0003עשרה שיתירו לו. \u0004כדלקמן סעיף ל\"ה גבי חלום אבל א\"צ ששונים הלכות דשאני התם דחמיר טפי שנידוהו מהשמים. הרא\"ש וטור:","\u0003ואפילו התירו לו בחלום אינו כלום. \u0004שא\"א לחלום בלא דברים בטלים וחיישינן שמא הנידוי אמת וההתרה אינה כלום וע\"ל סי' ר\"י ס\"ב:","\u0003וצריך עשרה כו'. \u0004משום דיש לחוש שמא בשליחות המקום נתנדה וכל בי עשרה שכינתא שריא:","\u0003וי\"א דאין לו התרה רק ע\"י עשרה ששנו הלכות. \u0004ואם לא מצא יש לו התרה ע\"י י' ששנו משניות ויתירו לו ביחד ואם לא מצא סגי בזה אח\"ז. כ' ב\"י בשם מ\"כ מי שנידוהו בחלום ובאים להתירו לו יאמרו מחמת דאישתמית פלוני בחלמיה מותר יהא ליה לא יסורי' ולא קללה יבואו עליו ויאמרו יחי ראובן ואל ימות וגו' תודיעני אורח חיים וגו' ה' שמעתי שמעך וגו' ויאמרו ג\"פ ויעבור וגו' ע\"כ וכ\"כ העט\"ז כתב הר\"ן צ\"ע במי שנידוהו בחלומו אם צריך לנהוג בכל דיני המנודה ומביאו ב\"י ומסתימת דברי הפוסקים משמע דשוה למנודה בכל דבר:","\u0003אם מצא השליח כו' \u0004דמסתייע מלתא כיון שמצאם מכונסים:","\u0003ואי לא לא. \u0004דהוי כנידהו בפניו שאין מתירים לו אלא בפניו אבל ע\"י מנודה עצמו ודאי מועיל אפי' ע\"י חיזור בני אדם. תוספות:","\u0003שלא יהא מכשול לאחרים. \u0004שאינם יודעים שנידה את זה:","\u0003אע\"פ שאינו נסמך. \u0004ובמהרי\"ק שורש ק\"ע נוטה לומר דאפילו אינו גדול כמותו ע\"ש:","\u0003והאחר אינו תלמיד חכם. \u0004אע\"פ שלא למד מעולם לפני המנודה. מהרי\"ק שם. ולכאורה קשה דהא כ' מהרי\"ק שם דהיינו דוקא למ\"ד שצריך שהמתנדה נידהו אבל להרמב\"ם שסובר שהב\"ד נזקקין לו לנדותו ל\"ש ת\"ח ל\"ש ע\"ה כיון שאין זה חייב נידוי ב\"ד חייבים לנדות המנדה עכ\"ד ומביאו ב\"י וא\"כ הא לקמן בסעיף מ\"ג העתיק המחבר לשון הרמב\"ם ואפשר דהמחבר פליג אמהרי\"ק בהא אלא ס\"ל כדפירש הרמ\"ך דברי הרמב\"ם דלקמן דמיירי בנידה לת\"ח דוקא ומביאו ב\"י א\"נ ס\"ל כהרשב\"ץ דלקמן ס\"ק פ\"ו והכא מיירי באינו רגיל בכך:","\u0003וה\"ה תלמיד כו'. \u0004כתב מהרי\"ק שם דמדברי תשובת מהר\"מ נראה דאם פשע הרב ונידה בענין שה\"ל לחוש שמא אינו חייב נידוי אם אמר התלמיד אדרבה נידויו נידוי ומביאו ב\"י וד\"מ ועיין במהרי\"ק עצמו שהאריך בזה:","\u0003מ\"מ נידוי השני ג\"כ אינו כלום כו'. \u0004ואפי' לדעת הרמב\"ם שב\"ד נזקקין ומנדין אותו הכא אין נזקקין. ריב\"ש שם:","\u0003ת\"ח כו'. \u0004בתשובת הרא\"ש איתא ת\"ח או ש\"ץ כו' ונראה דמיירי בנידהו הש\"ץ בשליחות ב\"ד:","\u0003עד שנידהו. \u0004ומיירי שנידהו כדין וכן בעט\"ז גרס שביזהו רשע עד שנידהו וכן הוא בתשובת הרא\"ש משמע דה\"פ שביזה את החכם עד שבשביל כך נידהו ואחר שנידהו א\"ל הרשע אדרבה וא\"כ ודאי דכדין נידהו דהרי מנדין המבזה את החכם כדלקמן רסמ\"ג:","\u0003אח גדול כו'. \u0004כפול לעיל סי' ר\"מ סעיף כ\"ג ושם מבואר הטעם:","\u0003לעולם. \u0004אפילו חזר וסרח כמה פעמים:","\u0003מלקין אותו בצנעא. \u0004שנאמר וכשל גם נביא עמך לילה אע\"פ שכשל כסהו כלילה ואומרים הכבד ושב בביתך:","\u0003ושם שמים מתחלל על ידו. \u0004עד שאומרים עליו שרא ליה מריה לפלני':","\u0003המבזה את החכם. \u0004והוא שראוי להורות ויגע בתורה. בית יוסף בשם הקונטרסים:","\u0003המבזה שליח ב\"ד. \u0004עי' בח\"מ ס\"ס ח':","\u0003המזלזל בדבר א' מדברי סופרים. \u0004הקשה הר\"ן דבקצת דוכתי אמרינן דמאן דעבר אמידי דרבנן מלקינן ליה אבל לא משמתינן ליה ותירץ דבמילתא דעיקרה מדרבנן דכי עקר לה עקר לכולה מצוה משמתינן ליה אבל בדבר שעיקרו מן התורה והוא עובר על מה שאסרו חכמים מכין אותו מכת מרדות וכתב עליו בכ\"מ וז\"ל וק\"ל דהא נט\"י אין עיקרה מן התורה אם לא על ידי אסמכתא לכך נ\"ל דהמפקפק בדבר מד\"ס חמיר טפי מעובר על דבר מדבריהם ולפיכך אע\"פ שהעובר אינו חייב אלא מכת מרדות המפקפק או המזלזל חייב נידוי עכ\"ל ולא ידענא מאי קשיא דהא אדרבה נט\"י כיון דאין עיקרה מן התורה אלא ע\"ד אסמכתא מנדין אותו דכי עקר לה עקר לכולה מצוה וכ\"כ הר\"ן פרק מקום שנהגו להדיא וז\"ל וי\"ל דבמילתא דעיקרה מדרבנן דכי עקר לה עקר לכולה מצוה משמתינן ליה כי האי וכדאמרינן נמי את מי נדו את ר\"א בן הצר שפקפק בנט\"י כו' ועל תירוצו עדיין קשה קושית הר\"ן דאמאי משמתינן על המחלל י\"ט שני של גליות והעושה מלאכה בע\"פ אחר חצות וכן הרואה את המת ואינו מלוהו לקמן סי' שמ\"ג וא\"כ צ\"ל כהר\"ן:","\u0003ה' מי ששלחו. \u0004עיין בח\"מ סי' י\"ח:","\u0003ו' מי שלא כו'. \u0004עיין בח\"מ סי' ק':","\u0003ח' המוכר כו'. \u0004עיין בח\"מ סי' קע\"ה ס\"ח:","\u0003ט' המעיד כו'. \u0004עיין בח\"מ סי' כ\"ח ס\"ג:","\u0003י' טבח כהן. \u0004ע\"ל סי' ס\"א סעיף כ\"ד:","\u0003י\"א המחלל כו'. \u0004עיין בא\"ח ר\"ס תצ\"ו:","\u0003י\"ב העושה כו'. \u0004עיין בא\"ח ר\"ס תס\"ח:","\u0003י\"ג המזכיר כו'. \u0004ע\"ל סל\"ז:","\u0003ט\"ז המחשב כו'. \u0004נראה דהיינו דוקא כשמחשב וקובע ע\"פ שהיו רגילים לקבוע בא\"י בזמן שהיה בהמ\"ק קיים אבל לחשב בתקופות ומזלות כמו שנהגו האידנא אדרבה מצוה היא כדאמרי' [שבת ע\"ה] כל היודע לחשוב תקופות ומזלות ואינו חושב עליו הכתוב אומר ואת פועל ה' לא יביטו וגו':","\u0003י\"ט טבח כו'. \u0004ע\"ל ס\"ס קי\"ט:","\u0003כ' טבח כו'. \u0004לעיל סי\"ח סט\"ז וכבר נתבאר שם דאין דין זה נוהג עכשיו:","\u0003כ\"א המקשה כו'. \u0004עיין בא\"ע סכ\"ג ס\"ג:","\u0003כ\"ב המגרש כו'. \u0004עיין בא\"ע סי' קי\"ט ס\"ה:","\u0003כ\"ג חכם כו'. \u0004לעיל סמ\"ב:","\u0003כ\"ד המנדה כו'. \u0004לעיל סל\"ט:","\u0003המנדה למי שאינו חייב נידוי. \u0004ובא לב\"ד להתרעם עליו שנידהו שלא כדין ב\"ד מנדין אותו עכ\"ל עט\"ז והוא מב\"י ומשמע דכל שלא בא לב\"ד לקבול עליו אין ב\"ד נזקקין לנדותו וכ\"כ בעל מגדול עוז ספ\"ז מהל' ת\"ת ובכ\"מ כתוב שהרשב\"ץ בתשובה תירץ בשם ר' שם טוב דהכא מיירי במי שרגיל בכך שב\"ד נזקקין לנדותו משמע דברגיל אפי' אינו קובל עליו הב\"ד נזקקין לנדותו:","\u0003חכם שהורה כו'. \u0004עיין בא\"ע סימן י\"ז:","\u0003וכן מי כו'. \u0004ע\"ל סי' ר\"ח כב\"י דכל אלו שנזכרים בסעיף זה הם בכלל דברים שהוזכרו בסעיף הקודם דהוי בכלל המזלזל בדבר אחד מדברי סופרים כו' ע\"ש ואין להקשות א\"כ למה חשב י\"א המחלל י\"ט שני וי\"א העושה מלאכה בערב פסח ויש לומר דקמ\"ל בהנך אע\"ג דליכא אלא מנהג מנדין ליה ומ\"מ למ\"ש בשם הכ\"מ לעיל ס\"ק ע' דמזלזל דוקא היינו דמפקפק קשה דלא הוי הנך בכלל וגם לפי' הר\"ן צ\"ע ויש ליישב בדוחק וצ\"ע:","\u0003ואם דינו דין פסוק. \u0004שחייב נדוי:","\u0003מנודה לכל ישראל. \u0004דהוי כנדוהו ב\"ד:","\u0003אלא לקטנים ממנו. \u0004לכאורה הלכה מגומגם דמשמע דלקטנים ממנו אפי' הם חכמים מנודה וכ\"מ מלשון ב\"י שכתב אבל מנודה הוא לתלמידיו לאותן שאינם גדולים ממנו כו' וזה אינו דדוקא כשאינם חכמים מנודה להם וכמ\"ש לעיל סעיף ט\"ו ס\"ק כ\"ט לדעת המחבר ולפי מה שכתב שם ס\"ק ל' הכא מנודה אפי' לחכמים כמותו כל שאין גדולים ממנו:","\u0003ומסרב לפרוע כו'. \u0004אבל אם דוחהו איזה דחייה כגון אין לי מעות עכשיו וכה\"ג לא הוי נדוי מהרי\"ק וכן כשכופהו לצורך המס ולא נתחייב לגמרי אין נידויו נידוי כדאיתא בהגהת אשיר\"י:","\u0003נידויו נידוי. \u0004אפי' אין שמעון ת\"ח. כן הוא בהגהת אשיר\"י:","\u0003וי\"א כו'. \u0004אפי' ת\"ח אינו יכול לנדות דאין אדם יכול לנדות לעצמו בשביל ממון בשום ענין וע\"ל סי\"ט ס\"ק ל\"ח:","\u0003כל שכן אם חבירו מזומן לו להיות לו ציית דין. \u0004אלא שכופר שאינו חייב לו:","\u0003אם יש עדים כו'. \u0004ולפעמים א\"צ עדים כשרים אלא אפילו אשה או קטן או קרובים נאמנים בדבר של קטטות כ\"כ מהרי\"ק שורש ק\"פ וכן כתב הרב בח\"מ ס\"ס ל\"ז:","\u0003וע\"ל סי' רכ\"ה סמ\"ז:\u0004 וסי' רל\"ב סי\"ב כצ\"ל:"],["\u0003ואפילו יש לחוש שע\"י כן יצא לתרבות רעה. \u0004תמיה לי האי מילתא טובא דהיאך נחוש לאיסור שעושה זה ונביאהו לידי תרבות רעה ח\"ו אשר כל באיה לא ישובון והנה מקור דין זה בפסקי מהרא\"י סי' קל\"ח וז\"ל וראיה ממה שמצאתי בקובץ שהוכיח מהא דאמר באגודה פרק הנושא שאמר רבינו הקדוש בעת פטירתו בדרך נבואה דרב אחא בר יאשיה שמתינהו להנהו דאקפו פירי בכוורא וחללו שבת ואשתמוד משום דשמתינהו וקשה מאי קמ\"ל תלמודא בהאי מילתא ורבינו הקדוש גופיה למאי הלכתא ניבא דבר זה אלא לאשמועינן דאפילו אם נראה לחכמים שמפני שהן מנדין מאן דהו שבשביל כך יצא לתרבות רעה לא יניחו עבור זה מלעשות כהלכה עכ\"ל. ומ\"ש בשם פרק הנושא הוא ט\"ס אלא האי נבואה דרבי היא בפרק עשרה יוחסין (קידושין דף ע\"ב) ולעד\"נ דמהא אין ראיה כלל דהתם משמע שרבינו הקדוש בא להזהיר את השומעים שידעו שיש פסולים בבבל כמו שאמר התם טובא דיש מקום שכולם ממזרים ויש מקום שיש ב' אחים שמחליפים נשותיהם זה לזה וע\"ז אמר ג\"כ שיש מקום בבבל שסרו היום מאחרי המקום ברוך הוא דשמתינהו רב אחא כו' ועל כן יש להתרחק מהם וא\"ל הלא המפורסם א\"צ ראיה ולא דמי לשאר המקומות שהזהיר שיש ממזרים שהם אינם ידועים משא\"כ בזה שהמיר ובודאי בלאו הכי יפרשו מהם לזה אימא לך דמכ\"ש לק\"מ דכוונתו של רבי היתה להוכיח שהנבואה דבר בו בשאר הדברים שאמר אף שלא היו מבוררי' בעיני השומעים ויביאו ראיה מדבר זה שיראו שהוא יודע בא\"י מה שנעשה היום בבבל מהנך דשמתינהו רב אחא וזה א\"א כי אם בדרך נבואה מזה ידעו שגם בשאר הדברים רוח ה' דבר בו כנ\"ל ברור כוונת נבואה זו ויש לי להביא ראיה איפכא מתלמוד ערוך פ\"ק דקדושין (דף כ') שמי שנמכר לעבודת אלילים עצמם דהיינו לחטוב לה עצים ושאר צרכים לא לשם אלהות ואמרה תורה שצריך לגאול אותו דתנא דבי ר' ישמעאל הואיל והלך זה ונעשה כומר לעבודת כוכבים אימא לידחי אבן אחר הנופל כלומר שלא תהא לו גאולה ת\"ל גאולה תהיה לו והנה ק\"ו יש כאן דמה התם שכבר נעשה כומר לעבודת כוכבים ואפ\"ה הזהיר' תורה בקום עשה שחייבין לפדותו ק\"ו בזה שעדיין לא התחיל בעבודת כוכבים כלום פשיטא שצריכים אנו להיות נזהרים להיות לפחות בשב ואל תעשה ולא לעשו' מעשה להביאם לידי עבודת כוכבים ודאי זה דבר שאין שוה על הלב להניחו וראיה עוד ממ\"ש הגאון מוהר\"ר יודא מינץ ז\"ל בתשובה סי' ה' וז\"ל ובראותי שא\"א להציל שתי נפשות מישראל שלא יצאו לתרבות רעה ח\"ו אמרתי להתיר מינקת חבירו כו'. ומביא ראיה מפ' השולח (גיטין ד' ל\"ח) ההיא איתתא דהוה עבדי אינשי בה איסור' אמר אביי אי לא דאמר שמואל כל המשחרר עבדו עובר בעשה כו' ע\"ש וא\"כ ק\"ו בזה שאין לעשות מעשה שיש חשש ממנו כנ\"ל ברור שאין לעשות למעשה כהג\"ה זאת אע\"פ שהיא מהלכה ממקום קדוש בעל אגודה ז\"ל ובאגודה שלנו לא נמצא זה כלל . ועיין מ\"ש בס\"ס זה בשם רש\"ל:","\u0003אבל אם לא נדוהו בפירוש. \u0004פי' שלא פירשו בנידוי שלא יצטרפוהו למנין:","\u0003ולגרש את בניו מבית הספר כו'. \u0004כן כתב הר\"ן בשם רב פלטוי גאון ורש\"ל כתב ע\"ז בפרק הגוזל בתרא סי' י\"ג חלילה במה שהעולם אינו מתקיים אלא בהבל פיהם של תינוקות לבטלם בשלמא מילה שעיקר המצוה תלויה באב והיא כבודו וכן לקבור מתו עליו מוטל שלא להלין והיא כבודו כופין אותו עד שיקבל עליו תשובה ואח\"כ מלין וקוברין אבל בת\"ת של תינוקות שאין לו תשלומין ועליו נאמר אם תעזבני יום יומים אעזבך פשיטא דלית טעמא להא מילתא גם מה שכתב להוציא את אשתו מבהכ\"נ לא נהירא אם הוא חטא היא מה חטאה כו' לא אאמין שיצאו ב' דברים אלו מפי הגאון עכ\"ל ויש לתמוה על תמיהתו לפי דעתו היה לו יותר לתמוה על שלא יקברו לו מתו אם הוא חטא אותו נפש מה חטאה שתהא מוטלת בבזיון וכמ\"ש הטור סי' שמ\"א דבזיוני דכולי חיי הוא ונלע\"ד דהאי גאון לא מיירי אלא מבניו הקטנים שאין בהם זכות מצד עצמן עדיין אלא תלויים ועומדים בזכות של אביהם אותם יש רשות לעכב הקבורה אבל לא גדולים שהם בני קבולי שכר או עונש מצד עצמם ומזה הטעם נתן הגאון רשות גם כן לגרש בניו מבית הספר והיינו הקטנים אבל באשתו ודאי אין שום טעם לבזותה דהיא עולה עמו ואינה יורדת עמו כנלע\"ד:","\u0003אף אם לא יחזור כו'. \u0004האי לא יחזור נראה פירושו שאינו מתחרט על מעשיו ואינו מבקש תשובה על מה שעשה אבל מ\"מ אינו מוסיף לעשות החטא עדיין וכמ\"ש הבית יוסף בשם נימוקי יוסף בסי' זה אבל אם הוא מוסיף ועושה זה החטא פשיטא שאין זה תלוי בזמן אלא לעולם נחשב לו כאילו אותו היום מחדש וזה נ\"ל פשוט:","\u0003להחמיר עליו עוד ולהחרימו כו'. \u0004בב\"י הקשה על הטור שכ\"כ דהרי כבר כתב שלאחר ששונין בו ב\"פ ל' יום בנדוי מחרימין אותו ומהו זה שכתב כאן שאם ירצו ב\"ד יעשו כן וא\"ל דקמ\"ל דיש כח בידם לעשות כן להחרים אע\"פ שלא היה עדיין בנדוי דהא כתב הטור בסמוך שאין מחרימין אלא עד שיתקשה שתי פעמים שבפעם הא' מנדין ושונין עד ל' יום וממתינין עוד כו' ויש מתרצים דכאן מיירי שהוא מבקש שיתירו לו דאם [לא] כן היאך אמר הטור וכשיגיע הזמן מתירים לו מיד הא בעינן שלשים יום אחרים כמ\"ש לעיל אלא ע\"כ דבקש מב\"ד ההתרה וקמ\"ל כיון דלא חזר בו לא מיבעיא שיכולים לנדותו אלא אפי' להחרימו רשאים אע\"פ שהוא מבקש שיתירו לו ואין זה במשמעות הלשון ולעד\"נ דהטור תנא והדר מפרש דהיינו בתחלה כתב שיש בעונש נדוי דבר זה לרחקו עד ס' יום ואח\"כ להחרימו וה\"א דהחיוב הוא כן דכל מי שבא לכלל נדוי חייבים ב\"ד לנהוג כמ\"ש לעיל דהיינו כשיעור הימים ואח\"כ להחרימו וחדא תלוי בחבירו ולא תמצא זה בלא זה ע\"כ אמר שאינו כן אלא כל אלו הפרטיים בנדוי אינם הכרחיים אלא הרשות ביד ב\"ד לנהוג כן בין במנהג הימים שאין צריכין דוקא ל' יום וכן אין צריך להחרימו בהכרח אלא ברצון הב\"ד תלוי הדבר ובזה מתורץ גם מה שקשה על הש\"ע סעיף י' שכתב שלא יזמן בג' כו' שזהו נזכר כבר בדין נדוי אלא דקמ\"ל דברצון הב\"ד תליא מילתא שיש להם רשות לעשות כן אבל אינו מוכרח כנ\"ל ברור:","\u0003הא דאמרינן כו'. \u0004זו דעת הראב\"ד באשר\"י וטור ונבאר דבריו בסייעתא דשמיא ויתבאר שמ\"ש רמ\"א ותוך ל' יום כו' אינו מדוקדק אע\"פ שהוא נמשך מדברי הקונטרסים שהביא ב\"י ת\"ר אין נידוי פחות מל' יום והקשה הראב\"ד מדאיתא בגמרא שאביי ס\"ל דבממון אמרינן טוט אסור וטוט שרי פירוש שיוכל ב\"ד להוציאו מן החרם אפי' לאלתר אם פייס בעל דינו אבל לאפקירותא בעינן ל' יום דוקא ופסק הרי\"ף דלא כאביי אלא אפי' באפקרותא סגי אי פייס לבעל דינו אפי' לאלתר א\"כ במאי מיירי ברייתא דאין נידוי פחות מל' יום אי דפייס לבע\"ד הא לאלתר שרינן ואי לא פייסיה לבתר ל' מי שרינן וי\"ל דמיירי דפייסיה לבע\"ד וה\"ק אין מנדין אותו תחילה לפחות מל' יום ואם חזר בו מתירין לאלתר כו' א\"נ דלא פייסיה ואפ\"ה אחר ל' יום מתירין לו שכבר קיבל דינו והוא שיבוא לב\"ד ויבקש שיתירו לו כו' ופסק הטור והש\"ע כב' התירוצים לקולא דהיינו פייסו מתירין אפי' תוך ל' ואחר ל' אפי' לא פייסו אלא שבקש מב\"ד להתיר והנה על קולא השניה חולק הרמב\"ם וס\"ל דאין מתירין לעולם עד שירצה החכם שביזהו כמ\"ש ב\"י אלא דגם על קולא הראשונה כתב ב\"י בשם קונטרסים דהרא\"ש חולק וס\"ל כאביי דלאפקירותא בעי' דוקא שלשים יום ולא כהרי\"ף ותמה ב\"י מאין לבעל קונטרס לומר כן ואני אומר דודאי אותו בעל קונטרס לא דק בזה דהא בתשובת הרא\"ש כלל כ\"א פסק להדיא כדברי הרי\"ף דל\"ש ממון ול\"ש אפקירותא סגי בפייסו לבע\"ד אפילו לאלתר וגם בפ' אלו מגלחין מביא דברי הראב\"ד ולא חלק עליהם והיאך נאמר שחולק עליהם. ע\"כ ברור דמ\"ש רמ\"א י\"א דהיינו דעת הרא\"ש שתוך ל' לא מהני פיוס וחזרה זה אינו מתוקן דהרי\"ף והרמב\"ם והראב\"ד והרא\"ש כולהו ס\"ל האי מילתא ואין חולק על קולא הראשונה שזכרנו:\n\u0003והב\"י \u0004רצה ליישב דעת הקונטרס מהא דאיתא ריש אלו מגלחין במועד וחשיב שם המנודה שהתירו לו חכמים פי' שלא היה יכול לגלח קודם הרגל דמנודה אסור בתגלחת ופריך בירושל' הביאו הרא\"ש במה אנן קיימין אם התירו לו קודם הרגל יגלח פירוש למה לא גילח קודם הרגל ואם לא התירו לו קודם הרגל אל יגלח פי' אל יגלח ברגל דלאו אנוס היה קודם הרגל דה\"ל לפייס בע\"ד כדי שיתירו לו אלא בהתירו לו קודם הרגל וחל ל' שלו ברגל שאין נדוי פחות מל' יום מזה שמעינן דס\"ל להרא\"ש שהביא זה הירושלמי דאין נדוי פחות מל' יום ולא כמ\"ש הרי\"ף והראב\"ד דלא בעינן ל' והוא דבר שאין הדעת סובלו דהרי גם הטור כתב כאן כהרי\"ף והראב\"ד ואפ\"ה כתב בא\"ח סי' תקל\"א דדוקא אם חל יום ל' שלו ברגל כמ\"ש הירושלמי שאין נדוי פחות מל' וכן הרא\"ש ויהיו דבריו סותרים זא\"ז בחד פירקא בפרק אלו מגלחין שבראש הפ' מביא הירושלמי הזה ובסמוך אח\"כ כתב כדברי הרי\"ף והראב\"ד והב\"י תירץ שם דהרא\"ש מפרש הירושלמי דמה שאמר אביי דלאפקירותא בעינן ל' יום פי' דבתוך ל' יום אין שייך היתר כלל אפילו על אחר ל' יום וע\"ז קאמר הרי\"ף דלית הלכתא כן אלא עכ\"פ מהני ההיתר בתוך שלשים יום על אחר שלשים יום אבל עכ\"פ בעינן ל' יום לכולי עלמא ותמהתי על פה קדוש יאמר כן דהא הרי\"ף והרא\"ש הביאו ראיה דלית הלכתא כאביי מהנהו עובדי דריש לקיש ורב הונא דשמתוה לאיתתא דאפקה הזכרת השם מפומה כו' והתם לא המתינו כלל ל' יום וכמדומה שלא עיין הרב ב\"י בזה כל הצורך. ולמו\"ח ז\"ל ראיתי שכ' בא\"ח לתרץ דבא\"ח מיירי שלא פייס לבע\"ד רק פייס לב\"ד שיוציאוהו מן החרם דמהני אפילו תוך ל' יום לענין שיהא מותר לאחר ל' יום מש\"ה בעינן ל' יום דוקא ואחר ל' יום מגלח אפילו ברגל ודרך זה פלאי ביותר דא\"כ ודאי אסור לגלח ברגל כיון שהיה אפשר לו לפייס בעל דינו ואז היה שרי לגלח לאלתר קודם הרגל וע\"כ אסור לגלח ברגל וכמו שהקשה בירושלמי ולא מצינו שאיכפת לן בבקשה מב\"ד אלא לאחר ל' יום שכבר סבל דינו כמ\"ש הטור כאן בשם הראב\"ד אבל לא תוך ל' יום לענין שיוכל לגלח אחר ל' ברגל זה לא היה ולא נברא:\n\u0003והנלע\"ד \u0004בזה כי יש להקשות על הירושלמי והטור שפסק כוותיה דבעינן שהתירו קודם הרגל מה אכפת לן בזה הא לא שלמו ל' יום עד הרגל ולמה לא יהיה מותר לגלח אפי' לא התירו אלא ברגל ולמה היה לו לבקש היתר קודם הרגל כיון שעדיין נמשך הנדוי עליו והתוס' ר\"פ אלו מגלחין הביאו ג\"כ זה הירושלמי בלשון זה בירושלמי פריך והלא פשע שלא בא לפני המועד לפני חכמים להתיר לו ומשני שכלו לו ל' יום של נידוי במועד דאין נדוי פחות מן ל' יום עכ\"ל הרי שלא הצריכו היתר קודם הרגל באמת וכן מוכח בגמרא שלנו בפרק אלו מגלחין דאמר רבא מי קתני שהתירוהו חכמים שהתירו לו חכמים קתני דאזיל ופייס לבעל דינו פירש\"י ברגל התירו לו חכמים שבאותו דור וא\"כ אמאי פסק הטור שהתירו לו קודם הרגל והלא תלמוד דידן עיקר ותו יש לי לדקדק בלשון הטור א\"ח שכ' וז\"ל וכן המנודה שלא היה יכול לגלח קודם שהרי המנודה אסור בתגלחת וכגון שהתירו לו קודם הרגל וחל יום ל' ברגל שלא היה יכול לגלח קודם שאין נידוי פחות מל' יום אבל אם נשאר בנדוי שלא ביקש שיתירו לו וברגל ביקש שיתירו לו לאו אנוס הוא ואינו יכול לגלח עכ\"ל דקשה דמשמע דגם בסיפא מיירי שא\"א לצאת מהנדוי קודם הרגל כמו ברישא אלא דבסיפא מיירי שלא ביקש קודם ואמאי סיים דלאו אנוס הוא אכתי אנוס הוא מצד שלא כלו הל' יום. ע\"כ נלע\"ד דפשוט דלכולי עלמא מתפרש הברייתא דאין נדוי פחות מל' יום על ב' דרכים דהיינו אם הנדוי תלוי בזמן כגון שא\"א לפייסו שהלך החכם שביזהו או שאר אונסים או שראו חכמים להחמיר עליו להיות בנדוי איזה זמן וכמ\"ש לקמן סעיף מ' בזה אמרי' כפשוטו אין נידוי פחות מל' יום אבל אם תלוי בפיוס החכם אז לא אכפת לן בל' יום אלא דמתחלה בשעת הנדוי אומרים שהנדוי יהיה ל' יום וכשחוזר מתירין לאלתר וזהו בעצמו הויכוח בירושלמי דהמקשן סבר דבפיוס תליא הנדוי וע\"ז פריך למה יגלח ברגל אי התירו לו קודם היה לו אז לגלח ואי לא התירו קודם מצד שלא פייס קשה דפושע הוא במה שלא פייס כיון שבפיוס תליא מילתא ומשני דהך נדוי לא חליא בפיוס אלא בזמן ל' יום וכפי מה שזכרתי וע\"כ אפי' התירו לו קודם הרגל מיקרי אנוס וכל שכן אם לא התירו עד הרגל נמצא דמ\"ש הירושלמי בתירוצא דהתירו קודם הרגל הוא לרבותא כמ\"ש וזהו ממש דברי הטור והכי קאמר וכן המנודה שלא היה יכול לגלח כו' פירוש מצד שהוא צריך דוקא שלשים יום ולא מהני פיוס מגלח ברגל כיון שחל ל' שלו ברגל ומ\"ש וכגון שהתירו לו ברגל וחל ל' כו' הך תיבה וכגון לא קאי על מ\"ש שהתירו לו קודם הרגל אלא אדבתריה דחל ל' שלו ברגל שזהו דוקא אבל מ\"ש שהתירו לו קודם הרגל לאו דוקא אלא לרבותא נקטיה כמו שכתבתי בפי' הירושלמי וכן בכל מקום שתמצא בזה שהתירו קודם הרגל הוא לרבותא וע\"כ שפיר מסיים הטור אבל אם נשאר בנדוי ולא ביקש פי' אבל אם אין הנידוי תלוי אלא בפיוס והוא נשאר בנידוי ולא ביקש לפייס קודם הרגל אז ודאי לאו אנוס הוא ונמצא כל אפייא שוין דבמקום שתלוי בפיוס סגי בפיוס אפי' לאלתר וכל העם על מקומו יבא בשלום ודברי רמ\"א כאן שתוך ל' יום לא מועיל חזרה הוא דלא כמאן ולית מאן דחש לה כנלע\"ד:","\u0003אפילו אם הבטיח הרב לפייסו אח\"כ. \u0004פי' שכבר נידהו הרב ובא זה המנודה ומבטיחו לפייסו לא מהני עד שיעשה הפיוס מה שאין כן במבטיחו קודם הנידוי לא ינדה אותו אע\"פ שעדיין לא עשה הפיוס ובלבוש פירש בלשון זה ואפי' הבטיח המנודה שירצה לפייס הרב אחר שיתירו לו נידויו לא מהני ואין מתירין לו עד שיעשה כו' עכ\"ל הוא סבר דמ\"ש רמ\"א לפייסו אח\"כ פירושו שאומר בפירוש שיפייסנו אחר ההיתר וממילא אם מבטיח סתם לפייסו מתירין לו ולעד\"נ דאינו כן אלא אח\"כ דקאמר רמ\"א פירושו אחר הנידוי שנידה אותו ולא מהני אפי' אומר סתם לפייסו עד שיעשה:","\u0003פירוש שלא נתכוין כו'. \u0004ובהגה' מיי' פ\"ו דת\"ת פי' דמיירי שנדהו לפי שלא היה מכבדו כראוי בקימה והידור ולפיכך אין נידויו נידוי דהא דמנדין לכבוד הרב ה\"מ שביזהו וגינהו במידי שהוא גנאי לתלמיד חכם אבל לא להגדיל כבודו:","\u0003שרוי לך כו'. \u0004תמהתי שאין נזהרים בזה עכשיו שאינו מותר עד שיתירו לו בפירוש כתוב בדרישה יש רוצים ללמוד מכאן דכל מי שהוא בחרם ומתירין לו שהשמש יכריז שאינו בחרם עוד ואין ראיה מכאן להכרזת השמש דדילמא א\"צ אלא להתיר החרם בינם לבין עצמם ויודיעוהו ולא להכריז עכ\"ל אבל נ\"ל דצריך להכריז השמש שאינו בחרם מטעם שאכתוב בסמוך בנידוהו בפניו כו':","\u0003אם זלזל כו'. \u0004בסימן ר\"ח סעיף ג' פסק להיפך עיין מ\"ש שם:","\u0003אלא בפניו. \u0004כתב הר\"ן הטעם משום חשדא דפעמים שיתירוהו ומנודה לא ידע וכשלא ינהגו בו נדוי יבואו לומר שמזלזלי' בנידוי ולא יחוש לנידוי חכמי' אח\"כ אבל כשנידוהו שלא בפניו [יאמר כשם שנידוהו שלא בפניו] כך התירו שלא בפניו ע\"כ ומזה נלמד שיכריז השמש שפלוני נקי מהחרם ג\"כ משום חשדא שמא לא ישמע אחד הפטור מהחרם כנ\"ל:","\u0003אע\"פ שלא הגיע הזמן כו'. \u0004אע\"ג דלענין נדר אינו יכול להתירו עד שיחול נידוי קיל מיניה שהרי יכול להתיר לעצמו וא\"צ אחר להתירו כ\"כ הרא\"ש ובשם המרדכי כ' בית יוסף דנדוי כנדר וכ' שהעיקר כהרא\"ש וכ\"פ בש\"ע ותימה על הש\"ע שבסי' רכ\"ח סעיף י\"ז פסק כהמרדכי ומדברי ריב\"ש שמביא ב\"י בסי' רכ\"ח על מי שקיבל עליו בחרם לעשות דבר פלוני תוך שנה הרי הוא כנשבע שמכאן ועד זמן פלוני יעשה דבר פלוני ומעתה חלה השבועה כו' משמע דס\"ל כהמרדכי דנדוי כשבוע' ואם כן מן הראוי הוא לקבוע הלכה כן:","\u0003דרך שבועה. \u0004כגון שאומר אני נשבע להיות בנדוי אם אעשה דבר פלוני. כ\"כ ב\"י:\n\u0003ומ\"ש \u0004וצריך התרה כתב ב\"י מ\"כ בשעת ההתרה יאמרו מחמת דאשתמית פלוני בחלמיה מותר יהא ליה לא יסורין ולא קללה יבואו עליו ויאמרו יחי ראובן ואל ימות וגו' תודיעני אורח חיים וגו' ה' שמעתי שמעך וגו' ואומר ג' פעמים ויעבור וגו' עכ\"ל:","\u0003וצריך עשרה כו'. \u0004הטעם דיש לחוש שמא מן השמי' נידוהו ועל כל בי עשרה שכינתא שריא והותר לו באותו ב\"ד שנתנדה. אשיר\"י:","\u0003לא מצא במקומו י'. \u0004בזה לא הצריך לטרוח עד פרסה שאין להם מעלה גדולה כ\"כ יתר על ג' כנ\"ל:","\u0003הלכות או משניות. \u0004בגמרא אמר איפכא דמתני או תני אלא דכאן קאי אדיעבד ור\"ל לכל הפחות בעינן שוני הלכות או אפילו שוני משניות:","\u0003לשוא. \u0004פי' לבטלה כמ\"ש בסעיף שאח\"ז:","\u0003בד\"א כו'. \u0004בטור כתוב וכתב הרמב\"ם כו' וקשה מאי פליג על הסמ\"ג ונ\"ל דהסמ\"ג נקט דוקא שוגג שאינו יודע האיסור משמע שאם יודע אלא שבשוגג נשמט מפיו יש לנדותו ומדברי הרמב\"ם משמע כל שוגג שהרי כתב לא ענש הכתוב שוגג כו' גם לשון מזהירו משמע דמיירי בשאר שוגג ג\"כ דאל\"כ הל\"ל אלא מודיעו:","\u0003והוציא ממנו ממון בעדותו כו' מנדין אותו עד שישלם. \u0004עיין מ\"ש ע\"ז בח\"מ סימן כ\"ח סעיף ג':","\u0003המזכיר ש\"ש לבטלה. \u0004יש מקשין למה לא חשיב מי שלא נידה את זה המזכיר ונראה דאין חיוב לנדותו שמא סבור זה השומע שאותו המזכיר הוא אינו יודע שיש איסור בדבר ולא אמרו דהשומע צריך לנדותו אלא אם הוא יודע בעצמו בבירור שהמזכיר הוא יודע שיש איסור בדבר:","\u0003המנדה למי שאינו חייב נידוי. \u0004כתו' בהגהת מיימוני דוקא שיודע שאינו חייב נידוי כי הא דר\"ל במועד קטן אבל מורה שנידה שסבור שזה חייב נידוי וטעה אין לנדות המורה וכתב רש\"ל י\"א דוקא אם אותו שנידה שלא כדין הוא ת\"ח אבל לא בעם הארץ והמנדה ת\"ח ומההיא דר\"ל אין ראיה דשמא אותו שנידה ר\"ל היה גדול ממנו:","\u0003צורבא מרבנן. \u0004עביד דינא ניפשיה. כתוב בדרישה בשם הג\"ה על זה לא כל הרוצה לעשות עצמו צורבא מרבנן עושה ע\"ש:","\u0003ולכן נהגו להקל. \u0004גדולה מזאת כתוב בדרישה בשם מהרמ\"ץ דמהר\"מ כתב דבזמן הזה שהנדויין מקולקלין אין מנדין כל מי שראוי לנדות אף בעבירות גדולות דאפילו בשורת הדין לא החמירו חכמים פן ימנענו מלעשות תשובה כל שכן שבדורינו שנבלים מביישים את האדם על ככה ולפעמים אין האדם מושל ברוחו ויבא לידי שפיכות דמים כו' ע\"כ לשונו:"]],["\u0003הלכות ביקור חולים ורפואה ונוטה למות וגוסס\u0004\nמִצְוָה לְבַקֵּר חוֹלִים. \u0010c0\u0011 הַקְּרוֹבִים וְהַחֲבֵרִים נִכְנָסִים מִיָּד; וְהָרְחוֹקִים, אַחַר ג' יָמִים. וְאִם קָפַץ עָלָיו הַחֹלִי, אֵלּוּ וָאֵלּוּ נִכְנָסִים מִיָּד. \u0005(טוּר בְּקִצוּר מס' ת\"ה לְהָרַמְבַּ\"ן)\u0006.\nאֲפִלּוּ הַגָּדוֹל יֵלֵךְ לְבַקֵּר הַקָּטָן, וַאֲפִלּוּ כַּמָּה פְּעָמִים בַּיּוֹם, \u0010y0\u0011 \u0010c1\u0011 וַאֲפִלּוּ בֶּן גִּילוֹ. וְכָל הַמּוֹסִיף הֲרֵי זֶה מְשֻׁבָּח, וּבִלְבַד שֶׁלֹּא יַטְרִיחַ לוֹ. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּשׂוֹנֵא יָכוֹל לֵילֵךְ לְבַקֵּר חוֹלֶה (מהרי\"ל קצ\"ז)\u0006, וְלֹא נִרְאֶה לִי, \u0010y1\u0011 אֶלָּא לֹא יְבַקֵּר חוֹלֶה, וְלֹא יְנַחֵם הָאָבֵל שֶׁהוּא שׂוֹנְאוֹ, שֶׁלֹּא יַחֲשֹׁב שֶׁשָּׂמֵחַ לְאֵידוֹ, וְאֵינוֹ לוֹ אֶלָּא צַעַר, כֵּן נִרְאֶה לִי \u0005(ש\"ס פ' כ\"ג)\u0006.\nהַמְבַקֵּר אֶת הַחוֹלֶה, לֹא יֵשֵׁב עַל גַּבֵּי מִטָּה, וְלֹא עַל גַּבֵּי כִּסֵא, וְלֹא עַל גַּבֵּי סַפְסָל, אֶלָּא מִתְעַטֵּף וְיוֹשֵׁב לְפָנָיו, שֶׁהַשְּׁכִינָה לְמַעְלָה מֵרַאֲשׁוֹתָיו. \u0005הַגָּה: וְדַוְקָא כְּשֶׁהַחוֹלֶה שׁוֹכֵב עַל הָאָרֶץ, דְּהַיּוֹשֵׁב גָּבוֹהַּ מִמֶּנּוּ, אֲבָל כְּשֶׁשּׁוֹכֵב עַל הַמִּטָּה מֻתָּר לֵישֵׁב עַל כִּסֵּא וְסַפְסָל (בֵּית יוֹסֵף בְּשֵׁם הר\"ן, וְכֵן נוֹהֲגִין)\u0006.\nאֵין מְבַקְּרִין הַחוֹלֶה בְּג' שָׁעוֹת רִאשׁוֹנוֹת שֶׁל יוֹם, מִפְּנֵי שֶׁכָּל חוֹלֶה, מֵקֵל עָלָיו חָלְיוֹ בַּבֹּקֶר, וְלֹא יָחוּשׁ לְבַקֵּשׁ עָלָיו רַחֲמִים. וְלֹא בְּג' שָׁעוֹת אַחֲרוֹנוֹת שֶׁל יוֹם, שֶׁאָז מַכְבִּיד עָלָיו חָלְיוֹ, וְיִתְיָאֵשׁ מִלְּבַקֵּשׁ עָלָיו רַחֲמִים. \u0005וְכָל שֶׁבִּקֵּר וְלֹא בִּקֵּשׁ עָלָיו רַחֲמִים, לֹא קִיֵּם הַמִּצְוָה (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ן)\u0006.\nכְּשֶׁמְּבַקֵּשׁ עָלָיו רַחֲמִים, \u0010y2\u0011 אִם מְבַקֵּשׁ לְפָנָיו, יָכוֹל לְבַקֵּשׁ \u0010c2\u0011 בְּכָל לָשׁוֹן שֶׁיִּרְצֶה. וְאִם מְבַקֵּשׁ שֶׁלֹּא בְּפָנָיו, לֹא יְבַקֵּשׁ \u0010c3\u0011 אֶלָּא בִּלְשׁוֹן הַקֹּדֶשׁ.\nיִכְלֹל אוֹתוֹ \u0010y3\u0011 בְּתוֹךְ חוֹלֵי יִשְׂרָאֵל, שֶׁיֹּאמַר: הַמָּקוֹם יְרַחֵם עָלֶיךָ בְּתוֹךְ חוֹלֵי יִשְׂרָאֵל. וּבְשַׁבָּת אוֹמֵר: שַׁבָּת הִיא \u0010y4\u0011 מִלִּזְעֹק, וּרְפוּאָה קְרוֹבָה לָבוֹא.\nאוֹמְרִים לוֹ שֶׁיִּתֵּן דַּעְתּוֹ עַל עִנְיָנָיו, אִם הִלְוָה אוֹ הִפְקִיד אֵצֶל אֲחֵרִים, אוֹ אֲחֵרִים הִלְווּ אוֹ הִפְקִידוּ אֶצְלוֹ, וְאַל יִפְחַד מִפְּנֵי זֶה מֵהַמָּוֶת.\nאֵין מְבַקְּרִין \u0010y5\u0011 לֹא לְחֹלִי מֵעַיִם וְלֹא לְחֹלִי הָעַיִן \u0010y6\u0011 וְלֹא לְחֹלִי הָרֹאשׁ. וְכֵן כָּל חֹלִי דְּתָקִיף לֵיהּ עָלְמָא וְקָשֶׁה לֵיהּ דִּבּוּרָא אֵין מְבַקְּרִין אוֹתוֹ בְּפָנָיו, אֶלָּא נִכְנָסִין בַּבַּיִת הַחִיצוֹן וְשׁוֹאֲלִין וְדוֹרְשִׁין בּוֹ אִם צְרִיכִין לְכַבֵּד וְלִרְבֹּץ לְפָנָיו, וְכַיּוֹצֵא בוֹ, וְשׁוֹמְעִין צַעֲרוֹ וּמְבַקְּשִׁים עָלָיו רַחֲמִים. \u0010y7\u0011\nמְבַקְּרִין חוֹלֵי עוֹבְדֵי כּוֹכָבִים, מִפְּנֵי דַּרְכֵי שָׁלוֹם. \u0010y8\u0011 \u0010c4\u0011\nבְּחוֹלֵי מֵעַיִם אֵין הָאִישׁ מְשַׁמֵּשׁ אֶת הָאִשָּׁה, אֲבָל הָאִשָּׁה מְשַׁמֶּשֶׁת אֶת הָאִישׁ. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁמִּי שֶׁיֵּשׁ לוֹ חוֹלֶה בְּבֵיתוֹ, יֵלֵךְ אֵצֶל חָכָם שֶׁבָּעִיר שֶׁיְּבַקֵּשׁ עָלָיו רַחֲמִים (נ\"י פֶּרֶק י\"נ)\u0006, \u0010y9\u0011 וְכֶן נָהֲגוּ לְבָרֵךְ חוֹלִים בְּבֵית הַכְּנֶסֶת, לִקְרֹא לָהֶם שֵׁם חָדָשׁ, כִּי שִׁנּוּי הַשֵּׁם קוֹרֵעַ גְּזַר דִּינוֹ. \u0010y10\u0011 נִחוּם אֲבֵלִים, קוֹדֵם לְבִקּוּר חוֹלִים \u0005(כָּל בּוֹ)\u0006.",["\u0003ואפי' בן גילו. \u0004שנוטל א' מס' בחליו:","\u0003אלא לא יבקר כו'. \u0004וכתב הב\"ח דללוות את השונא ליכא למיחש לשמח לאידו באשר הוא סוף כל האדם אבל לנחם אבל או לבקר חולה שהוא שונאו יש לחוש לכך ומיהו הכל לפי מה שהוא השנאה ולפי מה שהם השונאים:","\u0003אם מבקש לפניו. \u0004הרי מבקש כביכול בפני השכינה עצמה שהרי היא מראשותיו של חולה אבל אם מבקש שלא בפניו אין המלאכי השרת מכירין בכל לשון ועיין בא\"ח ס\"ס ק\"א:","\u0003בתוך חולי ישראל. \u0004שמתוך שכוללו עם אחרים תפלתו נשמעת יותר:","\u0003ורפואה קרובה לבא. \u0004ובא\"ח סי' רפ\"ז מסיים המחבר ורחמיו מרובים ושבתו בשלום וכ\"פ הב\"ח ע\"ש:","\u0003לא לחולי מעיים. \u0004משום כיסופא:","\u0003ולא כו'. \u0004שהדבור קשה להם:","\u0003מבקרין חולי עובדי כוכבים כו'. \u0004משמע אפי' חולי עובדי כוכבים לחוד וע\"ל סי' קנ\"א:","\u0003בחולי מעים כו'. \u0004דחיישינן כיון שהיא חולה והוא בריא שמא יבא עליה בע\"כ אבל האשה משמשת האיש דכיון שהאיש חולה ליכא למיחש שיבא על אשה בריאה בע\"כ דכיון שהיא בריאה והוא חולה יכולה היא שתנצל מידו עכ\"ל עט\"ז והוא מדברי ב\"י אבל הד\"מ והב\"ח והדרישה השיגו על הב\"י בזה ופירשו דמדאיתמר דין זה גבי חולי מעים ש\"מ דלא שייך אלא גבי חולי מעים דכשנפנית איכא גילוי מלפניה ומאחריה ואיכא חששא דיצרו תקפה עליו כו' ע\"ש וע\"ל סי' קצ\"ה ס\"ק י\"ט ולקמן סי' שנ\"ב ס\"ג:","\u0003וכן נהגו לברך החולים כו'. \u0004עיין בא\"ח סי' נ\"ד ס\"ב כתב הרב דיש נוהגין לברך החולה בין ישתבח ליוצר וכתוב בדינים והלכות של מהרי\"ו סי' ח' שאין לברך החולים בשבת ויו\"ט וכ\"כ בתשובה סי' קט\"ו. ובא\"ח ס\"ס רפ\"ח כ' הרב דמותר לברך בשבת חולה המסוכן בו ביום:","\u0003ניחום אבלים קודם כו'. \u0004שניחום אבלים הוא גמילות חסד שעם החיים ועם המתים וכתב הב\"ח כשא\"א לקיים שניהם מניח את החולה ועוסק בנחמות אבלים אבל כשאפשר לקיים שניהם ביקור חולים קודם כדי לבקש רחמים עליו שיחיה או לרבץ ולכבד לפניו דחשיב כאלו מחייהו וע\"ל סי' ר\"מ סי\"ב (דין מי שאסר הנאתו על חבירו אם יכול לבקרו נתבאר בסי' רכ\"א סעיף ד'):"],["\u0003הקרובים והחברים נכנסים מיד. \u0004פירש מו\"ח ז\"ל הטעם כי היכי דלא ליתרע מזליה להטיל עליו שם חולה כדאמרינן בנדרים (דף מ') רבא יומא קמא דחליש אמר לא תגלו לאינשי דלא ליתרע מזליה כו' אבל קרובים וחברים שנכנסים תמיד בביתו ליכא הרגשה כ\"כ ומ\"ה כשקפץ עליו החולי נכנסים גם הרחוקים מיד:","\u0003בן גילו. \u0004פי' שנולד בשעתו ונוטל א' מס' מחליו וכן השני ממה ששייר הראשון נוטל חלק ס':","\u0003בכל לשון שירצה. \u0004ולא שייך כאן אין מלאכי השרת נזקקין ללשון ארמי דשכינה עם החולה שנאמר ה' סעדנו על ערש דוי וע\"כ א\"צ אז למלאכים:","\u0003אלא בלשון הקודש. \u0004משמע דבכל שאר לשונות אין מלאכים נזקקין חוץ מלשון הקודש דוקא והוא דעת הרי\"ף הביאו בא\"ח סי' ק\"א אלא דכ' שם בשם הרא\"ש דדוקא ללשון ארמי אין נזקקין אבל שאר לשונות הוי כמו לשון קודש וא\"כ קשה על הטור למה סתם כאן נגד אביו ומצריך דוקא לשון הקודש ונראה דמשום דחולה בעי רחמי טובא על כן כ' כאן שיעשה אליבא דכ\"ע:","\u0003בחולי מעים כו'. \u0004בד\"מ נתן טעם דפריצות כשאיש משמש לנקיבה בקינוח ודברים כאלו יותר מאשה לאיש כי יצרו של איש גדול משל אשה ולי נראה הטעם דבחולי מעיים צריך החולה הרבה פעמים להיות לו לסיוע לקום לעשות צרכיו ונמצא שיבא האיש המשמש לאשה חולנית כזאת לידי קושי כיון דמתעסק בגופה תמיד משא\"כ בשאר חולי שא\"צ להקימה ולסעדה כ\"כ אבל אשה לאיש בכל גווני מותר כי אין כח באיש להתקשות בעת ההיא:"]],["\u0010y0\u0011 \u0010c0\u0011 נָתְנָה הַתּוֹרָה רְשׁוּת לָרוֹפֵא לְרַפְּאוֹת. וּמִצְוָה הִיא. וּבִכְלַל פִּקּוּחַ נֶפֶשׁ הוּא. וְאִם מוֹנֵעַ עַצְמוֹ, הֲרֵי זֶה שׁוֹפֵךְ דָּמִים, וַאֲפִלּוּ יֵשׁ לוֹ מִי שֶׁיְּרַפְּאֶנּוּ, שֶׁלֹּא מִן הַכֹּל אָדָם זוֹכֶה לִהִתְרַפְּאוֹת. וּמִיהוּ לֹא יִתְעַסֵק בִּרְפוּאָה אֶלָּא אִם כֵּן הוּא בָּקִי, וְלֹא יְהֵא שָׁם גָּדוֹל מִמֶּנּוּ, שֶׁאִם לֹא כֵן, הֲרֵי זֶה שׁוֹפֵךְ דָּמִים. \u0010y1\u0011 וְאִם רִפֵּא שֶׁלֹּא בִּרְשׁוּת בֵּית דִּין, חַיָּב בְּתַשְׁלוּמִין, אֲפִלּוּ אִם הוּא בָּקִי. וְאִם רִפֵּא בִּרְשׁוּת בֵּית דִּין, וְטָעָה וְהִזִּיק, פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם. \u0010y2\u0011 וְאִם הֵמִית, וְנוֹדַע לוֹ שֶׁשָּׁגַג, גּוֹלֶה עַל יָדוֹ.\nהָרוֹפֵא, \u0010y3\u0011 \u0010c1\u0011 אָסוּר לִטֹּל שְׂכַר הַחָכְמָה \u0010y4\u0011 וְלִמּוּד, אֲבָל שְׂכַר הַטֹּרַח וְהַבַּטָּלָה, מֻתָּר.\nמִי שֶׁיֵּשׁ לוֹ סַמָּנִים, וַחֲבֵרוֹ חוֹלֶה וְצָרִיךְ לָהֶם, אָסוּר לוֹ לְהַעֲלוֹת בִּדְמֵיהֶם יוֹתֵר מִן הָרָאוּי. וְלֹא עוֹד, אֶלָּא אֲפִלּוּ פָּסְקוּ לוֹ בִּדְמֵיהֶם הַרְבֵּה, מִפְּנֵי צֹרֶךְ הַשָּׁעָה שֶׁלֹּא מָצְאוּ סַמָּנִין אֶלָּא בְּיָדוֹ, אֵין לוֹ אֶלָּא דְּמֵיהֶן. אֲבָל אִם הִתְנָה בִּשְׂכַר הָרוֹפֵא הַרְבֵּה, חַיָּב לִתֵּן לוֹ, שֶׁחָכְמָתוֹ מָכַר לוֹ וְאֵין לוֹ דָּמִים. \u0005הַגָּה: וְאַף עַל פִּי שֶׁיֵּשׁ מִצְוָה עָלָיו לְרַפְּאוֹתוֹ; \u0010y5\u0011 שֶׁכָּל מִצְוֹת עֲשֵׂה דְּרַמְיָא אַכֻּלֵּי עָלְמָא, אִם נִזְדַּמְּנָה לְאֶחָד וְלֹא רָצָה לְקַיְּמָהּ אֶלָּא בְּמָמוֹן, אֵין מוֹצִיאִין הַמָּמוֹן מִיָּדוֹ, \u0010y6\u0011 \u0010c2\u0011 וְלֹא מַפְקִיעִין מִיָּדוֹ חִיּוּב שֶׁלָּהֶן (טוּר)\u0006.",["\u0003נתנה התורה כו'. \u0004שלא יאמר מה לי לצער הזה שמא אטעה ונמצאתי הורג בשוגג:","\u0003ואם ריפא שלא ברשות ב\"ד וטעה והזיק חייב בתשלומין. \u0004אבל אם הזיק במזיד אפי' ריפא ברשות ב\"ד חייב בדיני אדם וכ\"מ בפרישה ס\"ו:","\u0003ואם המית כו'. \u0004ומ\"מ א\"צ למנוע בשביל חשש טעות ומצוה היא כמו שנתבאר:","\u0003אסור כו'. \u0004דאבידת גופו היא ורחמנא אמרה והשבותו לו לרבות אבידת גופו:","\u0003והלימוד. \u0004כלומר שלומד הרופא לחולה או להמתעסק עמו שיעשה לרפואתו כך וכך:","\u0003שכל מצות עשה דרמיא אכולי עלמא אם נזדמנה לא' כו'. \u0004כצ\"ל:","\u0003ולא מפקיעין מידו חיוב שלהן. \u0004והב\"ח כתב דצ\"ל חיוב שלו וה\"פ ל\"מ שאם כבר קבל הרופא שכר שקצבו והרי הוא בידו שאין מוציאין מידו אלא אפי' לא קבל כלום אלא שקצבו לו ונתחייבו לו בכך וכך צריכין לשלם לו מה שנתחייבו לו ע\"ש:"],["\u0003נתנה תורה רשות כו' ומצוה היא כו'. \u0004קשה כיון דבאמת מצוה היא למה קרי לה תחלה רשות ונראה דהכי הוא כוונת הענין זה דרפואה האמיתית היא ע\"פ בקשת רחמים דמשמיא יש לו רפואה כמ\"ש מחצתי ואני ארפא אלא שאין האדם זוכה לכך אלא צריך לעשות רפואה על פי טבע העולם והוא יתברך הסכים על זה ונתן הרפואה ע\"י טבע הרפואות וזהו נתינת רשות של הקדוש ב\"ה וכיון שכבר בא האדם לידי כך יש חיוב על הרופא לעשות רפואתו וזה מבואר בגמרא פרק הרואה (ברכות דף ס\"ב) דאמר רב אחא הנכנס להקיז דם אומר יהי רצון מלפניך שיהא עסק זה לי לרפואה ותרפאני כי אל רופא נאמן אתה ורפואתך אמת לפי שאין דרכן של בני אדם לרפאות פירש\"י כלומר לא היה להם לעסוק ברפואות אלא לבקש רחמים אמר אביי לא לימא אינש הכי דתנא דבי רבי ישמעאל ורפא ירפא מכאן שניתנה רשות לרופא לרפא נראה פי' הגמרא בדרך הזה דרב אחא הצריך לומר האי לישנא שכן אין דרכן של בני אדם בנוסח התפלה שאומר המקיז דם דהיינו שהוא מתנצל למה מבקש רפואה על ידי ההקזה שהוא לפי הטבע אף שאינו מן הראוי לעשות כן אלא לבקש רחמים להנצל ע\"י רחמים של מעלה מ\"מ מאחר שכבר נהגו לעשות רפואה ע\"י הטבע גם אני עושה כן ועל כל פנים אני מודה שהכל בא על ידך כי אל רופא נאמן אתה ועל זה חולק אביי דלא לימא שכן נהגו דגם התורה הסכימה על זה שיהא רפואה ע\"פ הטבע כי ירדה תורה לסוף דעת האדם שלא יהיה זכאי כל כך שתבא רפואתו ע\"י נס מן השמים וע\"כ אין שייך לומר דהאי קרא דרפא ירפא קמ\"ל מצוה דאלו האדם זכאי אינו צריך לכך ואדרבה היה צריך דוקא רפואה ע\"י שמים אלא דלפי דרכו של אדם רשות הוא לו וע\"כ הוה האידנא חיוב בדבר ומצוה היא כיון דלפי מעשה האדם חיותו תלוי בכך כן נ\"ל נכון ועיין ברמב\"ן פ' בחקותי האריך בענין זה של רפואות ומדבריו משמע בפירוש ורפא ירפא כמ\"ש: אך יש לי מקום עיון במה שכתב שם שאין מעשה רפואות בבית הצדיקים וכן אמרו כל כ\"ב שנה דמלך רבה אפילו אומנא לביתיה לא קרא עכ\"ל משמע דמפרש שלא הוצרך לרפואה ובגמרא משמע דהוא הלך לבית האומן רק שלא נהג כבוד בעצמו לקרוא אותו לביתו. שוב ראיתי בסוף הוריות מביא גם כן אגדה זאת ומביא בעל עין יעקב שם פירוש גאון דהכי קאמר הזכות של ענוה של רב יוסף גרמה שלא הוצרך כלל לאומן ולזה כוון גם הרמב\"ן:","\u0003אסור ליטול שכר החכמה והלימוד. \u0004פי' שלומד אותו לעשות רפואה לפי שאבידת גופו היא ורחמנא אמר והשבותו לו לרבות אבידת גופו ואמרינן בענין עשיית המצוה מה אני בחנם אף אתם בחנם:","\u0003ולא מפקיעין מידו חיוב שלו. \u0004כן הוא הנוסחא בהעתק הבית יוסף דברי הרמב\"ן וכן עיקר ורצונו לומר דאע\"פ שיש איסור בנטילת שכר על הלימוד והחכמה כמ\"ש בסעיף ב' מ\"מ כיון שכבר התנה עמו והתחייב נגדו חייב לשלם כיון דלאו עליה דידיה לחודיה רמיא מצוה זאת דהא כל אדם יוכל להתחכם ללמוד רפואות ואע\"ג דבבורח מבית האסורים והיתה מעברות לפניו ואמר לו העבירני ואתן לך דינר אין נותן לו אלא שכרו כמו שכתוב בחושן משפט סימן רס\"ד שאני התם דקצבה יש לאותה פעולה משא\"כ בחכמת הרפואות שאין לה שיעור ומתחלה לא היה חיוב עליו ללמוד זה על כן מהני התנאי דוקא בזה כן נראה לי ביאור הדברים:"]],["חוֹלֶה שֶׁמֵּת לוֹ מֵת, אֵין מוֹדִיעִין אוֹתוֹ, שֶׁמָּא תִּטָּרֵף דַּעְתּוֹ עָלָיו. \u0010y0\u0011 וְאֵין קוֹרְעִין חֲלוּקוֹ, \u0010y1\u0011 וְאֵין בּוֹכִין, וְאֵין מַסְפִּידִין בְּפָנָיו, שֶׁלֹּא יִשָּׁבֵר לִבּוֹ; וּמַשְׁתִּיקִין אֶת הַמְנַחֲמִין מִפָּנָיו.",["\u0003ואין קורעין כו'. \u0004פי' ל\"מ שאין מודיעין אותו שמא תטרף דעתו אלא אפי' נודע לו איך מצוים לו לקרוע שמא תגדל דאגתו וכ\"כ הב\"ח בשם הר\"ן:","\u0003ואין בוכין כו'. \u0004כתב הב\"ח נראה דה\"פ ולא עוד אלא שאין בוכין ואין מספידין בפניו אף על מת שאינו קרובו של חולה שלא ישבר את לבו פי' דכיון שרואה החולה הזה שזה הפלוני מת ובוכין ומספידין עליו בפניו נשבר לבו מפחדו שמא ימות גם הוא ומטעם זה משתיקין המנחמים בפניו שע\"י המנחמים נזכר למיתת אותו פלוני ומתפחד שמא ימות גם הוא גם קרוב לפרש שאין בוכין ומספידין נמי מיירי שמת לו מת ונודע לו שמת קאמר וכן משתיקין המנחמים על מת שלו:"],[]],["נָטָה לָמוּת, \u0010y0\u0011 אוֹמְרִים לוֹ: הִתְוַדֶּה, וְאוֹמְרִים לוֹ: הַרְבֵּה הִתְוַדּוּ וְלֹא מֵתוּ, וְהַרְבֵּה שֶׁלֹּא הִתְוַדּוּ, מֵתוּ, וּבְשָׂכָר שֶׁאַתָּה מִתְוַדֶּה אַתָּה חַי, וְכָל הַמִּתְוַדֶּה יֵשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא. וְאִם אֵינוֹ יָכוֹל לְהִתְוַדּוֹת בְּפִיו, יִתְוַדֶּה בְּלִבּוֹ. \u0005וְאִם אֵינוֹ יוֹדֵעַ לְהִתְוַדּוֹת, אוֹמְרִים לוֹ: אֱמֹר: מִיתָתִי תְּהֵא כַּפָּרָה עַל כָּל עֲוֹנוֹתַי (טוּר)\u0006. וְכָל אֵלּוּ הַדְּבָרִים אֵין אוֹמְרִין לוֹ בִּפְנֵי עַמֵּי הָאָרֶץ, וְלֹא בִּפְנֵי נָשִׁים, וְלֹא בִּפְנֵי קְטַנִּים, שֶׁמָּא יִבְכּוּ וְיִשְׁבְּרוּ לִבּוֹ.\nסֵדֶר וִדּוּי שְׁכִיב מֵרַע: מוֹדֶה אֲנִי לְפָנֶיךָ ה' אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי שֶׁרְפוּאָתִי וּמִיתָתִי בְּיָדְךָ, יְהִי רָצוֹן מִלְּפָנֶיךָ שֶׁתְּרַפְּאֵנִי רְפוּאָה שְׁלֵמָה, וְאִם אָמוּת, תְּהֵא מִיתָתִי כַּפָּרָה עַל כָּל חֲטָאִים וַעֲוֹנוֹת וּפְשָׁעִים, שֶׁחָטָאתִי וְשֶׁעָוִיתִי וְשֶׁפָּשַׁעְתִּי לְפָנֶיךָ, וְתֵן חֶלְקִי בְּגַן עֵדֶן, וְזַכֵּנִי לָעוֹלָם הַבָּא הַצָּפוֹן לַצַּדִּיקִים. \u0005וְאִם רוֹצֶה לְהַאֲרִיךְ כְּוִדּוּי יוֹם כִּפּוּר, הָרְשׁות בְּיָדוֹ (כָּל בּוֹ)\u0006.",["\u0003אומרים לו התודה שכן דרך כל המומתין מתודין.\u0004 טור וש\"ס שבת דף ל\"ב ע\"א כתב הב\"ח ומשמע דוקא בנטה למות אבל בלא נטה למות אין אומרים לו התודה כדי שלא יהא נשבר לבו ואע\"פ שא\"ל הרבה הולכים בשוק ומתודים מ\"מ כשאומרים לו לאדם התודה שכן דרך כל המומתים מתודים ידע הוא שמסוכן הוא מאד דאל\"כ לא היו מזכירין מיתתו בפניו ויהיה נשבר לבו לפיכך אין אומרים לו כך אלא בנטה למות כו' נראה מדבריו דאומרים לו התודה שכן דרך כל המומתין מתודין ולכך אין אומרים לו כך אלא בנטה למות אבל הפרישה כתב דהאי שכן דרך כל המומתין מתודין לשון הטור הוא ולא שיאמרו לו כך וא\"כ אפי' בנטה למות אין אומרים לו כך ואע\"ג שהב\"ח הביא אח\"כ לשון רש\"י שכתב אומרים העומדים שם שכן דרך כל המומתין מתודין כדתנן בסנהדרין כו' אין דעת רש\"י לומר שהעומדים שם אומרים כל המומתים מתודין דא\"כ היאך כתב כדתנן בסנהדרין כו' אלא האי שכן דרך כל המומתים כו' דבור אחר הוא ומתחלה פי' אאומרים מאן נינהו האומרים ומפרש העומדים שם ואח\"כ מפרש שכן דרך כל המומתים כו' מל' שכן דרך כל המומתים כדתנן בסנהדרין כו' ומ\"מ נראה דדוקא בנטה למות אומרים לו התודה דאל\"כ חושב שמסוכן הוא וישבר לבו אי נמי בלא נטה למות אין אומרים לו כך שהרי עדיין יש לו שהות שיוכל להתודות אבל בנטה למות יש לחוש שימות פתאום בלא וידוי:"],[]],["הַגּוֹסֵס, \u0010y0\u0011 הֲרֵי הוּא כְּחַי לְכָל דְּבָרָיו. \u0010y1\u0011 \u0010c0\u0011 אֵין קוֹשְׁרִין לְחָיָיו, \u0010y2\u0011 וְאֵין סָכִין אוֹתוֹ, וְאֵין מְדִיחִין אוֹתוֹ, וְאֵין פּוֹקְקִין אֶת נְקָבָיו, \u0010y3\u0011 וְאֵין שׁוֹמְטִין הַכַּר מִתַּחְתָּיו, וְאֵין נוֹתְנִין אוֹתוֹ עַל גַּבֵּי חוֹל, וְלֹא עַל גַּבֵּי חַרְסִית וְלֹא עַל גַּבֵּי אֲדָמָה, וְאֵין נוֹתְנִין עַל כְּרֵסוֹ, לֹא קְעָרָה, וְלֹא מַגְרֵפָה, וְלֹא צְלוֹחִית שֶׁל מַיִם, וְלֹא גַּרְגִּיר שֶׁל מֶלַח, וְאֵין מַשְׁמִיעִין עָלָיו עֲיָרוֹת, וְאֵין שׂוֹכְרִין חֲלִילִין וּמְקוֹנְנוֹת, וְאֵין מְעַמְּצִין עֵינָיו עַד שֶׁתֵּצֵא נַפְשׁוֹ. \u0010y4\u0011 וְכָל הַמְּעַמֵּץ עִם יְצִיאַת הַנֶּפֶשׁ, הֲרֵי זֶה שׁוֹפֵךְ דָּמִים. וְאֵין קוֹרְעִין, וְלֹא חוֹלְצִין, וְלֹא מַסְפִּידִין עָלָיו, וְלֹא מַכְנִיסִין עִמּוֹ אָרוֹן לַבַּיִת, עַד שֶׁיָּמוּת. וְאֵין פּוֹתְחִין עָלָיו בְּצִדּוּק הדִּין, עַד שֶׁתֵּצֵא נַפְשׁוֹ. \u0005הַגָּה: \u0010y5\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין חוֹצְבִין לוֹ קֶבֶר אַף עַל פִּי שֶׁאֵינוֹ עִמּוֹ בַּבַּיִת, עַד אַחַר שֶׁיָּמוּת (ריב\"ש סִימָן קי\"ד)\u0006. אָסוּר לַחֲצֹב שׁוּם קֶבֶר לִהְיוֹת פָּתוּחַ עַד לְמָחָר שֶׁלֹּא יִקְבְּרוּ בּוֹ הַמֵּת בְּאוֹתוֹ הַיּוֹם, וְיֵשׁ סַכָּנָה בַּדָּבָר \u0005(רַבֵּנוּ יְרוּחָם בְּשֵׁם הר\"י הֶחָסִיד זַ\"ל)\u0006. וְכֵן אָסוּר לִגְרֹם לַמֵּת שֶׁיָּמוּת מְהֵרָה, כְּגוֹן מִי שֶׁהוּא גּוֹסֵס זְמַן אָרֹךְ וְלֹא יוּכַל לְהִפָּרֵד, \u0010y6\u0011 אָסוּר לְהִשָּׁמֵט הַכַּר וְהַכֶּסֶת מִתַּחְתָּיו, \u0010c1\u0011 מִכֹּחַ שֶׁאוֹמְרִין שֶׁיֵּשׁ נוֹצוֹת מִקְצָת עוֹפוֹת שֶׁגּוֹרְמִים זֶה וְכֵן לֹא יְזִיזֶנּוּ מִמְּקוֹמוֹ. וְכֵן אָסוּר לָשׂוּם מַפְתְּחוֹת ב\"ה תַּחַת רֹאשׁוֹ, כְּדֵי שֶׁיִּפָּרֵד. אֲבָל אִם יֵשׁ שָׁם דָּבָר שֶׁגּוֹרֵם עִכּוּב יְצִיאַת הַנֶּפֶשׁ, כְּגוֹן שֶׁיֵּשׁ סָמוּךְ לְאוֹתוֹ בַּיִת קוֹל דּוֹפֵק, כְּגוֹן חוֹטֵב עֵצִים, אוֹ שֶׁיֵּשׁ מֶלַח עַל לְשׁוֹנוֹ וְאֵלּוּ מְעַכְּבִים יְצִיאַת הַנֶּפֶשׁ, מֻתָּר לַהֲסִירוֹ מִשָּׁם, דְּאֵין בָּזֶה מַעֲשֶׂה כְּלָל, אֶלָּא שֶׁמֵּסִיר הַמּוֹנֵעַ \u0005(הַכֹּל בְּהַגָּהַת אַלְפָסִי פֶּרֶק אֵלּוּ מְגַלְּחִין)\u0006.\nמִי שֶׁאָמְרוּ לוֹ: רָאִינוּ קְרוֹבְךָ גּוֹסֵס הַיּוֹם שְׁלֹשָׁה יָמִים, צָרִיךְ לְהִתְאַבֵּל עָלָיו. \u0010y7\u0011 \u0005דְּוַדַּאי כְּבָר מֵת.\u0006\nאוֹמְרִים צִדּוּק הַדִּין עִם יְצִיאַת נְשָׁמָה, וּכְשֶׁמַּגִּיעַ לְדַיַּן אֱמֶת, קוֹרֵעַ הָאָבֵל.\nכֵּיוָן שֶׁנָּטָה אָדָם לָמוּת, אֵין רַשָּׁאִין לִפָּרֵד מִמֶּנּוּ, כְּדֵי שֶׁלֹּא תֵּצֵא נַפְשׁוֹ \u0010c2\u0011 וְהוּא יְחִידִי. \u0005וּמִצְוָה לַעֲמֹד עַל הָאָדָם יְצִיאַת נְשָׁמָה, שֶׁנֶּאֱמַר: וִיחִי עוֹד לָנֶצַח לֹא יִרְאֶה הַשָּׁחַת, כִּי יִרְאֶה חֲכָמִים יָמוּתוּ וְגו' (תְּהִלִּים מ\"ט, יא)\u0006 \u0005(הַגָּהוֹת אַלְפָסִי שָׁם)\u0006. \u0010y8\u0011\nמִנְהָג לִשְׁפֹּךְ כָּל הַמַּיִם שְׁאוּבִים \u0010c3\u0011 שֶׁבִּשְׁכוּנַת הַמֵּת.",["\u0003הרי הוא כחי לכל דבר. \u0004ואסור לעשות דבר המקרב מיתתו וכתב הר\"ן הרי הוא כחי פי' ליתן גט ולמתנה וכהן רשאי ליכנס לבית שהוא עומד בו ואע\"פ שרוב גוססים למיתה ע\"כ ומביאו הב\"ח בסתם ולקמן סי' ש\"ע נתבאר דאסור ליכנס לבית שיש בו גוסס ע\"ש:","\u0003אין קושרים. \u0004כדי שלא יפתח פיו:","\u0003ואין סכין. \u0004ואין מדיחין מנהג הוא שעושים לכל מת להדיח זוהמא שעל בשרו:","\u0003ואין שומטין הכר מתחתיו. \u0004אע\"פ שאין משכיבים את המת על שום דבר חם כמו כר וכסת אלא מיד מורידין אותו ומניחין אותו לארץ כי דברים חמין מסריחין ומתפיחין אותו וקאמר דאין עושין לו כן כל זמן שהוא גוסס וז\"ש אח\"כ ואין נותנין אותו על גבי החול והטעם מפני שמזיזו ממקומו כ\"כ בפרישה:","\u0003וכל המעמץ עם יציאת הנפש ה\"ז שופך דמים. \u0004אלא ישהה מעט שמא נתעלף עכ\"ל הרמב\"ם. ובמס' שמחות מסיים וכל הנוגע בו ה\"ז שופך דמים למה הדבר דומה לנר המטפטף שכיון שנוגע בו האדם מיד נכבה וכ\"כ הרי\"ף והרמב\"ם:","\u0003וי\"א דאין כו'. \u0004והב\"ח כתב דמותר מדינא כל שאין החולה מרגיש בדבר מיהו צריך ליזהר בע\"ש סמוך לשבת שמא לא יספיקו לקברו אם לא בחלול שבת ואם לא יקברוהו א\"כ יצטרכו להניחו פתוח הלכך לא שרינן להו אא\"כ משערינן שאם ימות סמוך לשבת ממש ולא יהא אפשר לקברו שעכ\"פ יספיק לחזור ולמלאות החפירה בריוח קודם שיכנס שבת ע\"כ. ועיין בא\"ח סי' תקמ\"ז סעיף י\"א:","\u0003אסור להשמט הכר והכסת כו'. \u0004כתב העט\"ז ותמהני מ\"ש מהסרת קול דופק ומלח דה\"נ לא עביד מידי אלא שמסיר המונע וצ\"ע עכ\"ל ולק\"מ דהכא אין האיסור משום הנוצות אלא האיסור הוא מפני שמתנועע הגוסס וכ\"כ הדרישה והב\"ח ע\"ש:","\u0003דודאי כבר מת. \u0004דדוקא בעודו לפנינו חשוב גוסס כחי לכל דבר אבל לא כשאינו לפנינו:","\u0003מנהג כו'. \u0004והטעם שידעו הכל שיש בו מקרה מות ולא יצטרך להודיע בפה ויהא מוציא דבה ועוד שמלאך המות מפיל במים טפת דם המות. שם. ובתשב\"ץ כתוב ראה באחד ששתה מהמים ומת כו' ע\"ש ובא\"ח סימן תנ\"ה כתב הרב שאין לשפוך מים שלנו מפני מת כו' ע\"ש:"],["\u0003אין קושרין לחייו. \u0004כל מה דחשב כאן הטעם דאין מקרבין מיתתו כי כל אלו הם קירוב מיתה והשמטת הכר הוא ג\"כ סימן מיתה כי אין רוצה להניח על דבר חם:","\u0003מכח שאומרים שיש נוצות כו'. \u0004פי' דאף ע\"ג דמטעם זה יש היתר לעשות כן דהא אין עושה קירוב מיתה אלא מסיר מונע יציאת נפש כדכתב אחר כך מכל מקום כאן אסור כיון שע\"י זה מזיז גופו והוה קירוב מיתה בידים אלא דקשה לי למה התיר הסרת מלח מעל לשונו והלא גם שם מזיז פיו על ידו והוה כמעמץ עיניו ועל כן נראה לע\"ד שאין לנהוג היתר בהסרת מלח:","\u0003והוא יחידי. \u0004מפני שהנפש משתוממת בשעה שיוצאה מן הגוף:","\u0003שבשכונת המת. \u0004הטעם לפי שהמלאך המות מפיל במים טפת דם המות והך שכונה לא נתבאר כאן שיעור' אלא דבכתובו' (דף כ\"ח) כתבו התוס' דשכונה היינו שלשה בתים כדאמרינן סוף פרק קמא דעבודת כוכבים. בראקנ\"ט פרשת ויחי כ' דבשעת מיתה יזהר שלא יצא שום אבר ממנו חוץ למטה והפליג על שאינו נזהר בזה:"]],["\u0003הלכות קריעה\u0004\nמִי שֶׁמֵּת לוֹ מֵת, וְהוּא מֵהַמֵּתִים \u0010y0\u0011 שֶׁרָאוּי לְהִתְאַבֵּל עֲלֵיהֶם, \u0010y1\u0011 חַיָּב לִקְרֹעַ עָלָיו. וְצָרִיךְ שֶׁיִּקְרַע מְעֻמָּד; וְאִם קָרַע מְיֻשָּׁב, לֹא יָצָא, \u0005וְצָרִיךְ לַחֲזֹר וְלִקְרֹעַ (טוּר בְּשֵׁם רי\"ץ גֵּאוּת וְהָרֹא\"שׁ וְהַגָּהוֹת מַיְמוֹנִי וּבֵית יוֹסֵף לְדַעַת ראב\"ד ורי\"ף וְרַמְבַּ\"ן וּמָרְדְּכַי פא\"מ)\u0006. וּלְכַתְּחִלָּה צָרִיךְ \u0010y2\u0011 לִקְרֹעַ קֹדֶם שֶׁיִּסְתֹּם פְּנֵי הַמֵּת. \u0005(בֵּית יוֹסֵף בְּשֵׁם סמ\"ק)\u0006.\nמְקוֹם הַקְּרִיעָה, בְּכָל מָקוֹם בְּבֵית הַצַּוָּאר לְפָנָיו; אֲבָל אִם קָרַע לְאַחֲרָיו, \u0005אוֹ בְּשׁוּלֵי הַבֶּגֶד (טוּר)\u0006 אוֹ מִן הַצְּדָדִין, לֹא יָצָא. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים שֶׁיּוֹצֵא אִם קוֹרֵעַ בְּשׁוּלֵי הַבֶּגֶד, וְכֵן נָהֲגוּ לְהָקֵל לִקְרֹעַ בְּשׁוּלֵי הַבֶּגֶד, (אֵלּוּ מִנְהָגִים תִּמְצָא בִּסְמַ\"ק ובמהרי\"ו וּבְחִדּוּשֵׁי אֲגֻדָּה וּבְכָל בּוֹ)\u0006, \u0010y3\u0011 כְּשֶׁקּוֹרְעִין עַל שְׁאָר מֵתִים שֶׁאֵינָן מִתְאַבְּלִין עֲלֵיהֶם; אֲבָל עַל הַמֵּתִים שֶׁהֵם קְרוֹבָיו, וּמִתְאַבְּלִים עֲלֵיהֶם, אֵינוֹ יוֹצֵא בִּקְרִיעָה זוֹ וְצָרִיךְ לִקְרֹעַ בְּבֵית הַצַּוָּאר, וְכֵן נָהֲגוּ.\nשִׁעוּר קְרִיעָה, טֶפַח. וְאִם קָרַע עַל מֵת, וּבָא לְהוֹסִיף בְּאוֹתָהּ קְרִיעָה עַל מֵת אַחֵר, \u0010y4\u0011 אִם אַחַר ז', סָגֵי בְּכָל שֶׁהוּא. וְאִם הוּא בְּתוֹךְ ז', צָרִיךְ טֶפַח. וְעַל אָבִיו וְאִמּוֹ, אֲפִלּוּ אַחַר ז', קוֹרֵעַ עַד שֶׁיְּגַלֶּה אֶת לִבּוֹ.\nכְּשֵׁם שֶׁקּוֹרֵעַ עַל קְרוֹבוֹ שֶׁמִּתְאַבֵּל עָלָיו, כָּךְ קוֹרֵעַ בִּפְנֵי קְרוֹבוֹ עַל מֵת שֶׁמֵּת לִקְרוֹבוֹ, כֵּיצַד, הֲרֵי שֶׁמֵּת בֶּן בְּנוֹ אוֹ אֲחִי בְּנוֹ \u0010c0\u0011 אוֹ אֵם בְּנוֹ, חַיָּב לִקְרֹעַ בִּפְנֵי בְּנוֹ. וְכֵן קוֹרֵעַ \u0010y5\u0011 עַל חָמִיו וַחֲמוֹתוֹ. וְהָאִשָּׁה קוֹרַעַת עַל חָמִיהָ וַחֲמוֹתָהּ. \u0005וְאֵין נוֹהֲגִין עַכְשָׁו כֵּן, וּכְמוֹ שֶׁיִּתְבָּאֵר לְקַמָּן סי' שע\"ד לְעִנְיַן אֲבֵלוּת.\u0006\nהָעוֹמֵד בִּשְׁעַת יְצִיאַת נְשָׁמָה \u0010c1\u0011 שֶׁל אִישׁ, \u0010y6\u0011 אוֹ אִשָּׁה מִיִּשְׂרָאֵל, חַיָּב לִקְרֹעַ \u0005(טוּר בְּשֵׁם רַמְבַּ\"ן וּבֵית יוֹסֵף אַף לְדַעַת רַשִׁ\"י)\u0006. וַאֲפִלּוּ אִם לִפְעָמִים עָשָׂה עֲבֵרָה לְתֵאָבוֹן, אוֹ שֶׁמַּנִּיחַ לַעֲשׂוֹת מִצְוָה בִּשְׁבִיל טֹרַח. \u0005הַגָּה: \u0010y7\u0011 אֲבָל רָגִיל לַעֲשׂוֹת עֲבֵרָה, אֵין מִתְאַבְּלִין עָלָיו (מָרְדְּכַי סוֹף מ\"ק)\u0006. וְכָל שֶׁכֵּן עַל מוּמָר \u0005(לַעֲבוֹדַת כּוֹכָבִים)\u0006 \u0005(שָׁם וּפוֹסְקִים וְכֵן מוּכָח מִשַּׁ\"ס פי' נִגְמַר הַדִּין וְכַמָּה דּוּכְתֵי)\u0006. \u0010y8\u0011 וְיֵשׁ אוֹמְרִים שֶׁמּוּמָר \u0010c2\u0011 שֶׁנֶּהֱרַג בִּידֵי עוֹבֵד כּוֹכָבִים, \u0010y9\u0011 מִתְאַבְּלִין עָלָיו \u0005(הַגָּהַת אֲשֵׁרִ\"י פֶּרֶק א\"מ ואוֹר זָרוּעַ)\u0006. וְכֵן מוּמָר קָטָן שֶׁהֵמִיר עִם אָבִיו אוֹ אִמּוֹ, דְּהָוֵי כְּאָנוּס \u0005(מָרְדְּכַי ה\"א בְּשֵׁם ר\"י וּמְבִיאוֹ בֵּית יוֹסֵף סִימָן שמ\"ה)\u0006 וְיֵשׁ אוֹמְרִים דְּאֵין מִתְאַבְּלִין, וְכֵן עִקָּר \u0005(שָׁם בְּשֵׁם ר\"ח)\u0006. הַפּוֹרְשִׁים מִדַּרְכֵי צִבּוּר, אַף עַל פִּי שֶׁאֵין מִתְאַבְּלִין עֲלֵיהֶם, מִתְאַבְּלִין עַל בְּנֵיהֶם \u0005(אוֹר זָרוּעַ)\u0006. וְע\"ל סִימָן שמ\"ה. \u0010y10\u0011\nעַל אָדָם כָּשֵׁר, שֶׁאֵינוֹ חָשׁוּד עַל שׁוּם עֲבֵרָה וְלֹא עַל שׁוּם בִּטּוּל מִצְוָה, וְלֹא סַנֵי שׁוּמְעָנֵיהּ, אַף עַל פִּי שֶׁאֵינוֹ גָּדוֹל בַּתּוֹרָה, וְאַף עַל פִּי שֶׁלֹּא עָמַד בִּשְׁעַת יְצִיאַת נְשָׁמָה, חַיָּב לִקְרֹעַ עָלָיו; \u0010y11\u0011 וְהוּא שֶׁעוֹמֵד שָׁם בֵּין מִיתָה לִקְבוּרָה; \u0010y12\u0011 וְתַלְמִידֵי חֲכָמִים פְּטוּרִים מִקְּרִיעָה זוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאֵין חַיָּב לִקְרֹעַ עַל אָדָם כָּשֵׁר, אֶלָּא אִם כֵּן עוֹמֵד עָלָיו בִּשְׁעַת יְצִיאַת נְשָׁמָה; אֲבָל חַיָּב לִבְכּוֹת וּלְהִתְאַבֵּל עָלָיו (ר\"ן פ' הָאוֹרֵג וְהַגָּהוֹת מַיְמוֹנִי פֶּרֶק י\"א בְּשֵׁם רַאַבִיָ\"ה)\u0006, וְכֵן נָהֲגוּ לְהָקֵל.\nעַל חָכָם וְעַל תַּלְמִיד חָכָם שֶׁשּׁוֹאֲלִין אוֹתוֹ דְּבַר הֲלָכָה בְּכָל מָקוֹם וְאוֹמְרָהּ, קוֹרְעִין עָלָיו אֲפִלּוּ לְאַחַר קְבוּרָה, בְּיוֹם שְׁמוּעָה, \u0010y13\u0011 אִם הוּא תּוֹךְ ל' יוֹם. וְקוֹרֵעַ עָלָיו בִּשְׁעַת הֶסְפְּדוֹ. \u0005לֹא קָרַע בְּיוֹם שְׁמוּעָה, וּכְבָר עָבַר זְמַן הֶסְפְּדוֹ, וְלֹא קָרַע, שׁוּב אֵינוֹ קוֹרֵעַ (כָּךְ מַשְׁמָע בַּטּוּר וּבְבֵית יוֹסֵף)\u0006. וְקוֹרְעִין עָלָיו \u0010y14\u0011 עַד שֶׁמְּגַלִּין אֶת לִבָּם. וּכְבָר נָהֲגוּ תַּלְמִידֵי חֲכָמִים בְּכָל מָקוֹם לִקְרֹעַ זֶה עַל זֶה טֶפַח, אַף עַל פִּי שֶׁהֵם שָׁוִים, וְאֵין אֶחָד מֵהֶם מְלַמֵּד אֶת חֲבֵרוֹ. \u0005הַגָּה: \u0010y15\u0011 יֵשׁ אוֹמְרִים שֶׁאֵין קוֹרְעִין עַל חָכָם, אֶלָּא אִם כֵּן הוּא רַבּוֹ אוֹ שֶׁיּוֹדְעִין מִשְּׁמוּעוֹתָיו שֶׁחִדֵּשׁ, דְּהַיְנוּ רַבּוֹ, (הָרֹא\"שׁ והגמי\"י בְּשֵׁם הר\"מ)\u0006, \u0010y16\u0011 וְכֵן נָהֲגוּ לְהָקֵל בִּמְדִינוֹת אֵלּוּ. \u0010y17\u0011 \u0010c3\u0011\nעַל רַבּוֹ שֶׁרֹב חָכְמָתוֹ מִמֶּנּוּ; אִם מִקְרָא, מִקְרָא; וְאִם מִשְׁנָה, מִשְׁנָה; אִם גְּמָרָא, גְּמָרָא; קוֹרֵעַ כָּל בְּגָדָיו עַד שֶׁמְּגַלֶּה לִבּוֹ. וְיֵשׁ אוֹמְרִים שֶׁאֵינוֹ קוֹרֵעַ אֶלָּא טֶפַח, וְאֵינוֹ מְאַחֶה לְעוֹלָם. וַאֲפִלּוּ מִשְּׁמוּעָה רְחוֹקָה, קוֹרֵעַ עָלָיו לְעוֹלָם. וְאִם לֹא לָמַד רֹב חָכְמָתוֹ מִמֶּנּוּ, אֵינוֹ קוֹרֵעַ עָלָיו, אֶלָּא כְּדִין שְׁאָר מֵתִים שֶׁהוּא מִתְאַבֵּל עֲלֵיהֶם. וַאֲפִלּוּ לֹא לָמַד מִמֶּנּוּ אֶלָּא דָּבָר אֶחָד, בֵּין קָטָן בֵּין גָּדוֹל, קוֹרֵעַ עָלָיו. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּקֶרַע שֶׁעַל רַבּוֹ שֶׁאֵינוֹ מֻבְהָק, נָמֵי אֵינוֹ מִתְאַחֶה (טוּר בְּשֵׁם הָרֹא\"שׁ וּבֵית יוֹסֵף בְּשֵׁם רַשִׁ\"י וְתוֹסָפוֹת והר\"ן)\u0006. תַּלְמִידֵי חֲכָמִים שֶׁיּוֹשְׁבִים בְּיַחַד וּמַקְשִׁים וּמְפָרְקִין זֶה לָזֶה וְלוֹמְדִים בְּיַחַד, יֵשׁ אוֹמְרִים שֶׁדִּינָן כְּרַב שֶׁאֵינוֹ מֻבְהָק, וְיֵשׁ אוֹמְרִים שֶׁדִּינָן כְּרַב מֻבְהָק \u0005(אֵלּוּ שֵׁנִי הַסְבָרוֹת בַּטּוּר)\u0006. וְיֵשׁ אוֹמְרִים דְּאֵין צְרִיכִין לִקְרֹעַ אֶלָּא עַל רַבּוֹ שֶׁלִּמְּדוֹ רֹב חָכְמָתוֹ, אֲבָל חֲבֵרִים הַלּוֹמְדִים זֶה עִם זֶה, אוֹ שֶׁהֵאִיר עֵינָיו בְּדָבָר אֶחָד, אֵינוֹ אֶלָּא חֻמְרָא בְּעָלְמָא, וְהֵיכָא דְּנָהוּג נָהוּג, וְהֵיכָא דְּלֹא נָהוּג לֹא נָהוּג, וְאֵין מוֹרִין כֵּן. \u0005(מָרְדְּכַי ה\"א בְּשֵׁם הַשְּׁאִלְתּוֹת והגמ\"יי בְּשֵׁם הר\"מ)\u0006, וְלָכֵן נָהֲגוּ לְהָקֵל בִּמְדִינוֹת אֵלּוּ. \u0010y18\u0011\nעַל כָּל הַמֵּתִים, קוֹרֵעַ עָלָיו טֶפַח בַּבֶּגֶד הָעֶלְיוֹן, וְדַיּוֹ. וְעַל אָבִיו וְאִמּוֹ, קוֹרֵעַ כָּל בְּגָדָיו, אֲפִלּוּ הוּא לָבוּשׁ י', עַד שֶׁמְּגַלֶּה לִבּוֹ. וְאִם לֹא קָרַע כָּל בְּגָדָיו, לֹא יָצָא, וְגוֹעֲרִים בּוֹ, וְכָל זְמַן שֶׁאוֹתוֹ הַבֶּגֶד עָלָיו, אוֹמְרִים לוֹ: קְרַע, אֲפִלּוּ לְאַחַר שְׁלֹשִׁים.\nאֲפַרְקְסוּתוֹ, אֵינוֹ צָרִיךְ לִקְרֹעַ, יֵשׁ מְפָרְשִׁין שֶׁהוּא בֶּגֶד הַזֵּעָה הַדָּבוּק לִבְשָׂרוֹ, וְיֵשׁ מְפָרְשִׁים \u0010c4\u0011 דְּהַיְנוּ בֶּגֶד הָעֶלְיוֹן שֶׁקּוֹרִין קאפ\"ה; וּפָשַׁט הַמִּנְהָג שֶׁלֹּא לִקְרֹעַ הקאפ\"ה עַל שׁוּם מֵת, אֲפִלּוּ עַל אָבִיו וְאִמּוֹ, וְלִקְרֹעַ עַל אָבִיו וְאִמּוֹ גַּם הֶחָלוּק שֶׁקּוֹרִין קאמיז\"ה \u0005(כָּל בּוֹ בְּשֵׁם רַבּוֹתָיו הַפּוֹסְקִים וסמ\"ק לְפי' הֶעָרוּךְ)\u0006. \u0005הַגָּה: וּבִמְדִינוֹת אֵלּוּ אֵין נוֹהֲגִין כֵּן, אֶלָּא אֵין קוֹרְעִין הֶחָלוּק שֶׁל פִּשְׁתָּן שֶׁהוּא בֶּגֶד \u0010y19\u0011 הַזֵּעָה, וְלֹא הַסַּרְבָּל הָעֶלְיוֹן; \u0010y20\u0011 אֲבָל שְׁאָר בְּגָדָיו, קוֹרֵעַ בְּאָבִיו וְאִמּוֹ; וּבִשְׁאָר מֵתִים, הַמַּלְבּוּשׁ הָעֶלְיוֹן תַּחַת הַסַּרְבָּל\u0006 \u0005(סמ\"ג בְּשֵׁם רַבּוֹתֵינוּ הַצָרְפָתִים)\u0006.\nאֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה שָׁוִים לְעִנְיַן קְרִיעָה, \u0010y21\u0011 אֶלָּא שֶׁהָאִשָּׁה קוֹרַעַת הַתַּחְתּוֹן וּמַחֲזִירָתוֹ לְאַחֲרֶיהָ, וְחוֹזֶרֶת וְקוֹרַעַת הָעֶלְיוֹן.\nעַל כָּל הַמֵּתִים, אִם רָצָה מַנִּיחַ שְׂפַת הַבֶּגֶד שְׁלֵמָה, וְקוֹרֵעַ מֵהַשָּׂפָה וּלְמַטָּה. \u0010c5\u0011 וְעַל אָבִיו וְאִמּוֹ, צָרִיךְ לִקְרֹעַ כָּל הַשָּׂפָה. \u0005(וְיֵשׁ אוֹמְרִים אַף עַל שְׁאָר מֵתִים צָרִיךְ לִקְרֹעַ הַשָּׂפָה (מָרְדְּכַי)\u0006, וְכֵן נוֹהֲגִין \u0005(מהרי\"ו סִימָן ו')\u0006.\nעַל כָּל הַמֵּתִים יֵשׁ לוֹ לִקְרֹעַ בִּפְנִים, שֶׁלֹּא בִּפְנֵי אָדָם, לְפִיכָךְ יֵשׁ לוֹ לְהַכְנִיס יָדוֹ בִּפְנִים, וְקוֹרֵעַ בְּצִנְעָא. אֲבָל עַל אָבִיו \u0005(וְאִמּוֹ)\u0006, אֵינוֹ קוֹרֵעַ אֶלָּא מִבַּחוּץ, בִּפְנֵי כָּל אָדָם.\nעַל כָּל הַמֵּתִים, רָצָה קוֹרֵעַ בַּיָּד, רָצָה קוֹרֵעַ בִּכְלִי. עַל אָבִיו וְאִמּוֹ, בַּיָּד. עַל כָּל הַמֵּתִים, \u0010c6\u0011 אִם בָּא לְהַחֲלִיף תּוֹךְ ז' יָמִים, מַחֲלִיף וְאֵינוֹ קוֹרֵעַ. \u0010y22\u0011 עַל אָבִיו וְאִמּוֹ, אִם מַחֲלִיף תּוֹךְ ז', קוֹרֵעַ כָּל הַבְּגָדִים שֶׁהוּא מַחֲלִיף, וְאֵינוֹ מְאַחֶה לְעוֹלָם, כְּמוֹ בַּפַּעַם הָרִאשׁוֹן. \u0005עַל כָּל הַמֵּתִים יָכוֹל לְהַחֲזִיר קִרְעוֹ לְאַחֲרָיו תּוֹךְ שִׁבְעָה, אֲבָל לֹא בְּאָבִיו וְאִמּוֹ (רַבֵּנוּ יְרוּחָם בְּשֵׁם הָרַאֲבַ\"ד)\u0006.\nעַל כָּל הַמֵתִים, \u0010c7\u0011 שׁוֹלֵל \u0005(פי' תּוֹפֵר תְּפִירָה בִּלְתִּי שָׁוָה)\u0006 לְאַחַר ז', וּמְאַחֶה \u0010y23\u0011 לְאַחַר שְׁלֹשִׁים יוֹם. \u0010y24\u0011 \u0005וְאֵין חִלּוּק אִם פָּגַע בָּהֶם הָרֶגֶל אוֹ לֹא (הגמ\"יי בְּשֵׁם רַאַבִיָ\"ה)\u0006. עַל אָבִיו וְאִמּוֹ, שׁוֹלֵל לְאַחַר ל' יוֹם, וְאֵינוֹ מְאַחֶה לְעוֹלָם. וְהָאִשָּׁה שׁוֹלֶלֶת לְאַלְתַּר, מִפְּנֵי כְּבוֹדָהּ. \u0005הַגָּה: וְכָל זְמַן שֶׁאָסוּר לִשְׁלֹל, אֲפִלּוּ לְחַבֵּר רֹאשׁ הַקְּרִיעָה עַל יְדֵי מַחַט, אָסוּר. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לְהַחְמִיר אֲפִלּוּ עַל שְׁאָר מֵתִים, שֶׁלֹּא לִשְׁלֹל תּוֹךְ ל', וְאָז אֲפִלּוּ רֹאשׁ הַקְּרִיעָה אָסוּר לְחַבֵּר עַל יְדֵי מַחַט (מהרי\"ו סִימָן ו')\u0006.\nעַל כָּל הַמֵּתִים, אִם רָצָה חוֹלֵץ כָּתֵף. עַל אָבִיו וְאִמּוֹ, \u0010c8\u0011 חַיָּב לַחֲלֹץ כָּתֵף וְהוֹלֵךְ כָּךְ לִפְנֵי הַמִּטָּה, עַד שֶׁיִּקָּבֵר. וְאִם הַבֵּן אָדָם גָּדוֹל, וְאֵין כְּבוֹדוֹ שֶׁיֵּלֵךְ חֲלוּץ כָּתֵף, אֵין צָרִיךְ לַחֲלֹץ.\nנָשִׂיא דּוֹמֶה לְאָב, לַחֲלִיצַת כָּתֵף, וְלִקְרֹעַ מִבַּחוּץ, וּלְאִחוּי. כָּל הַקּוֹרְעִים עַל חָכָם שֶׁמֵּת, כֵּיוָן שֶׁהֶחֱזִירוּ פְּנֵיהֶם מֵאֲחוֹרֵי הַמִּטָּה, שׁוֹלְלִין וּמְאַחִין לְמָחָר. וְחָכָם שֶׁבָּאָה שְׁמוּעָתוֹ, שׁוֹלֵל בּוֹ בַּיּוֹם, וּמְאַחֶה לְמָחָר. וְעַל נָשִׂיא וְעַל רַבּוֹ מֻבְהָק, שׁוֹלֵל לְמָחָר וְאֵינוֹ מְאַחֶה לְעוֹלָם. עַל חָכָם, חוֹלֵץ מִיָּמִין. וְעַל אַב בֵּית דִּין, מִשְּׂמֹאל. וְעַל נָשִׂיא, מִכָּאן וּמִכָּאן. וְעַל אָבִיו וְאִמּוֹ וְעַל רַבּוֹ מֻבְהָק, רָצָה מִכָּאן רָצָה מִכָּאן, וְאִם רָצָה, חוֹלֵץ שְׁתֵּיהֶן. \u0005וְיֵשׁ אוֹמְרִים דְּעַכְשָׁיו בַּזְּמַן הַזֶּה לֹא נָהֲגוּ לַחֲלֹץ כָּתֵף כְּלָל (כָּל בּוֹ בְּשֵׁם ר\"י)\u0006, וְכֵן נוֹהֲגִין הָאִדָּנָא.\nעַל כָּל הַמֵּתִים, אִם לֹא שָׁמַע אֶלָּא לְאַחַר ל' יוֹם, אֵינוֹ קוֹרֵעַ. \u0010y25\u0011 וּמִי שֶׁאֵין לוֹ חָלוּק וְנִזְדַּמֵּן לוֹ תּוֹךְ שִׁבְעָה, קוֹרֵעַ; אַחַר ז' אֵינוֹ קוֹרֵעַ. עַל אָבִיו וְעַל אִמּוֹ, קוֹרֵעַ וְהוֹלֵךְ לְעוֹלָם \u0010y26\u0011 \u0005כָּל בְּגָדָיו (מהרי\"ו סִימָן יג)\u0006.\nכְּשֵׁם שֶׁאָסוּר לְאַחוֹת קֶרַע שֶׁאֵינוֹ מִתְאַחֶה, \u0010c9\u0011 כָּךְ אָסוּר לַהֲפֹךְ צַד עֶלְיוֹן שֶׁל בֶּגֶד לְמַטָּה, וּלְאַחוֹתוֹ; וַאֲפִלּוּ הַלּוֹקֵחַ אוֹתוֹ, אָסוּר לְאַחוֹתוֹ. לְפִיכָךְ אִם בָּא לְמָכְרוֹ, \u0010y27\u0011 צָרִיךְ לְהוֹדִיעוֹ. וְאִם מְכָרוֹ לוֹ סְתָם, וְלֹא הוֹדִיעוֹ, אָסוּר לְאַחוֹתוֹ עַד שֶׁיֵּדַע שֶׁאֵינוֹ מֵהַקְּרָעִים שֶׁאֵינָם מִתְאַחִים. וְאָסוּר לְמָכְרוֹ לְעוֹבֵד כּוֹכָבִים.\nהַקּוֹרֵעַ \u0010c10\u0011 מִתּוֹךְ \u0010y28\u0011 הַמְּלָל, וּמִתּוֹךְ הַשְּׁלָל, וּמִתּוֹךְ הַלִּקּוּט, וּמִתּוֹךְ הַסֻלָּמוֹת, לֹא יָצָא. אֲבָל מִתּוֹךְ אִחוּי אֲלֶכְּסַנְדְּרִי, \u0010y29\u0011 דְּהַיְנוּ תְּפִירָה שֶׁהִיא שָׁוָה לְמַעְלָה וּבוֹלֶטֶת מִלְּמַטָּה, יָצָא.\nקָרַע עַל הַמֵּת, וּמֵת לוֹ מֵת אַחֵר תּוֹךְ ז', קוֹרֵעַ \u0010y30\u0011 \u0010c11\u0011 קֶרַע אַחֵר; לְאַחַר ז', מוֹסִיף עַל קֶרַע הָרִאשׁוֹן כָּל שֶׁהוּא. מֵת לוֹ מֵת שְׁלִישִׁי \u0010y31\u0011 אַחַר ז' שֶׁל שֵׁנִי, מוֹסִיף עָלָיו כָּל שֶׁהוּא. וְכֵן מוֹסִיף וְהוֹלֵךְ עַד טַבּוּרוֹ. הִגִּיעַ לַטַּבּוּר, מַרְחִיק ג' אֶצְבָּעוֹת, וְקוֹרֵעַ. נִתְמַלֵּא לְפָנָיו, \u0010y32\u0011 מַחֲזִירוֹ לַאֲחוֹרָיו. נִתְמַלֵּא מִלְּמַעְלָה, \u0010y33\u0011 הוֹפְכוֹ לְמַטָּה. נִתְמַלֵּא מִכָּאן וּמִכָּאן, נַעֲשָׂה כְּמִי שֶׁאֵין לוֹ חָלוּק, שֶׁאֵינוֹ קוֹרֵעַ.\nאָמְרוּ לוֹ: מֵת אָבִיו וְקָרַע, וְאַחַר שִׁבְעָה מֵת בְּנוֹ, וְהוֹסִיף. מִתְאַחֶה הַתַּחְתּוֹן וְלֹא הָעֶלְיוֹן. אָמְרוּ לוֹ: מֵת בְּנוֹ, וְקָרַע, וְאַחַר ז' מֵת אָבִיו, אֵינוֹ מוֹסִיף, אֶלָּא \u0010y34\u0011 קוֹרֵעַ קְרִיעָה אַחֶרֶת, שֶׁאֵין אָבִיו וְאִמּוֹ בְּתוֹסֶפֶת.\nמִי שֶׁמֵּתוּ לוֹ שְׁנֵי מֵתִים כְּאֶחָד, אוֹ שֶׁבָּאָה לוֹ שְׁמוּעָה מִשְּׁנַיִם כְּאֶחָד, קוֹרֵעַ קְרִיעָה אַחַת עַל שְׁנֵיהֶם. קָרַע, וְאַחַר כָּךְ מֵת לוֹ מֵת אַחֵר \u0005תּוֹךְ שִׁבְעָה (טוּר)\u0006, קוֹרֵעַ קֶרַע בִּפְנֵי עַצְמוֹ, בֵּין בְּאוֹתוֹ קֶרַע עַצְמוֹ שֶׁמּוֹסִיף בּוֹ וְקוֹרֵעַ עוֹד טֶפַח, אוֹ מַרְחִיק ג' אֶצְבָּעוֹת וְקוֹרֵעַ טֶפַח. לְאַחַר ז', מוֹסִיף עַל קֶרַע רִאשׁוֹן כָּל שֶׁהוּא. מֵת אָבִיו אוֹ אִמּוֹ וְאֶחָד מִשְּׁאָר קְרוֹבָיו, קוֹרֵעַ תְּחִלָּה עַל אָבִיו אוֹ עַל אִמּוֹ עַד לִבּוֹ, וּמַרְחִיק שָׁלֹשׁ אֶצְבָּעוֹת, וְקוֹרֵעַ טֶפַח עַל הַמֵּת הָאַחֵר. מֵת אָבִיו, וְקָרַע, וְאַחַר ז' מֵת אֶחָד מֵהַקְּרוֹבִים, מוֹסִיף עַל קֶרַע הָרִאשׁוֹן, וְתַחְתּוֹן מִתְאַחֶה וְעֶלְיוֹן אֵינוֹ מִתְאַחֶה. מֵת אֶחָד מֵהַקְּרוֹבִים, וְקָרַע, וְאַחַר כָּךְ מֵת אָבִיו אוֹ אִמּוֹ, בֵּין בְּתוֹךְ ז' בֵּין לְאַחַר ז', מַרְחִיק ג' אֶצְבָּעוֹת וְקוֹרֵעַ מִן הַצַּד בִּשְׂפַת הַבֶּגֶד, \u0010y35\u0011 שֶׁהֲרֵי צָרִיךְ לְהַבְדִּיל קָמֵי שָׂפָה, וְקוֹרֵעַ עַד שֶׁמַּגִּיעַ לְלִבּוֹ. מֵתוּ אָבִיו וְאִמּוֹ כְּאֶחָד, קוֹרֵעַ קֶרַע אֶחָד עַל שְׁנֵיהֶם.\nאָמְרוּ לוֹ: מֵת אָבִיו, וְקָרַע, וְאַחַר כָּךְ נִמְצָא שֶׁהוּא בְּנוֹ, יָצָא יְדֵי קְרִיעָה. \u0010c12\u0011 וְהוּא שֶׁנּוֹדַע לוֹ תּוֹךְ כְּדֵי דִּבּוּר. וְאִם לֹא נוֹדַע לוֹ עַד אַחַר כְּדֵי דִּבּוּר, לֹא יָצָא. \u0010y36\u0011 אֲבָל אִם אָמְרוּ לוֹ: מֵת לְךָ מֵת, וּכְסָבוּר אָבִיו הוּא, וְקָרַע, וְאַחַר כָּךְ נִמְצָא שֶׁהוּא בְּנוֹ, \u0010y37\u0011 יָצָא, אֲפִלּוּ לֹא נוֹדַע לוֹ עַד אַחַר כְּדֵי דִּבּוּר.\nהָיָה לוֹ חוֹלֶה, וְנִתְעַלֵּף, וְקָרַע עָלָיו, וְאַחַר כָּךְ מֵת; אִם מֵת תּוֹךְ כְּדֵי דִּבּוּר שֶׁל קְרִיעָה, אֵין צָרִיךְ קְרִיעָה אַחֶרֶת. וְאִם לָאו, צָרִיךְ קְרִיעָה אַחֶרֶת.\nאָמְרוּ לוֹ: מֵת אָבִיו, וְקָרַע וְנָהַג קְצָת יְמֵי אֲבֵלוּת, וְאַחַר כָּךְ אָמְרוּ לוֹ: לֹא מֵת, וְהִפְסִיק, וְחָזְרוּ וְאָמְרוּ לוֹ: \u0010c13\u0011 בַּפַּעַם הָרִאשׁוֹן מֵת, כְּמוֹ שֶׁאָמְרוּ הָרִאשׁוֹנִים, \u0010y38\u0011 יָצָא \u0010y39\u0011 יְדֵי קְרִיעָה.\nקָטָן שֶׁמֵּת לוֹ מֵת, \u0010y40\u0011 \u0010c14\u0011 מְקָרְעִין לוֹ.\nהַקּוֹרֵעַ בְּשַׁבָּת עַל מֵתוֹ, אַף עַל פִּי שֶׁחִלֵּל שַׁבָּת, יָצָא יְדֵי קְרִיעָה.\nהַקּוֹרֵעַ \u0010c15\u0011 בְּחָלוּק גָּזוּל, \u0010y41\u0011 לֹא יָצָא יְדֵי קְרִיעָה.\nקָטָן \u0010y42\u0011 דְּלֹא קִים לָן בֵּהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו, שֶׁמֵּת בְּתוֹךְ ל' אוֹ אֲפִלּוּ בְּיוֹם שְׁלֹשִׁים, \u0010c16\u0011 אֵין קוֹרְעִין עָלָיו.\nאֵין קוֹרְעִין בְּיוֹם טוֹב, אֲפִלּוּ בְּיוֹם טוֹב שֵׁנִי שֶׁל גָּלֻיּוֹת, אֲפִלּוּ קְרוֹבִים שֶׁל מֵת. אֲבָל בְּחֹל הַמּוֹעֵד, קוֹרְעִין עַל כָּל אֶחָד כְּפִי מַה שֶּׁהוּא, אִם עוֹמֵד בִּשְׁעַת יְצִיאַת נְשָׁמָה, אוֹ אִם הוּא אָדָם כָּשֵׁר אוֹ חָכָם עַל כָּל אֶחָד, כְּדִינוֹ שֶׁנִּתְבָּאֵר. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּנוֹהֲגִין שֶׁאֵין לִקְרֹעַ בְּחֹל הַמּוֹעֵד, \u0010y43\u0011 \u0010c17\u0011 רַק עַל אָבִיו וְאִמּוֹ; \u0010y44\u0011 וְעַל שְׁאָר מֵתִים קוֹרְעִין לְאַחַר הַמּוֹעֵד (ת\"ה סִימָן רפ\"ח)\u0006, \u0010y45\u0011 וּבְמָקוֹם שֶׁאֵין מִנְהָג, יֵשׁ לִקְרֹעַ עַל כֻּלָּם.\nשָׁמַע בָּרֶגֶל שְׁמוּעָה קְרוֹבָה, קוֹרֵעַ, וַאֲפִלּוּ אִם אַחַר הָרֶגֶל \u0010y46\u0011 \u0010c18\u0011 תִּהְיֶה רְחוֹקָה.\nהַהוֹלֵךְ בְּבֶגֶד קָרוּעַ לִפְנֵי הַמֵּת, שֶׁמַּרְאֶה עַצְמוֹ שֶׁקָּרַע, וְלֹא קָרַע, הֲרֵי זֶה גּוֹזֵל אֶת הַחַיִּים וְאֶת הַמֵּתִים.\nהָאוֹמֵר לַחֲבֵרוֹ: הַשְׁאִילֵנִי חֲלוּקְךָ שֶׁאֲבַקֵּר אֶת אַבָּא שֶׁהוּא חוֹלֶה, וְהָלַךְ וּמְצָאוֹ שֶׁמֵּת, \u0010y47\u0011 \u0010c19\u0011 קוֹרְעוֹ, וּמְאַחֶהוּ וּמַחֲזִיר לוֹ חֲלוּקוֹ, וּמְשַׁלֵּם לוֹ דְּמֵי קִרְעוֹ. \u0010y48\u0011 וְאִם לֹא הוֹדִיעוֹ, \u0010y49\u0011 הֲרֵי זֶה לֹא יִגַּע בּוֹ.\nהַמַּשְׁאִיל לַחֲבֵרוֹ חָלוּק לֵילֵךְ בּוֹ לְבֵית הָאָבֵל, אֵינוֹ רַשַּׁאי לִטֹּל מִמֶּנּוּ עַד שֶׁיַּעַבְרוּ יְמֵי הָאֵבֶל. \u0010y50\u0011 \u0005וּבְחֹשֶׁן הַמִּשְׁפָּט סִימָן שמ\"א סָעִיף ב' לֹא פָּסַק כֵּן.\u0006 \u0010y51\u0011\nקוֹרְעִין עַל שְׁמוּעוֹת רָעוֹת, כְּגוֹן שֶׁנִּקְבְּצוּ רֹב הַצִּבּוּר לַמִּלְחָמָה וְשָׁמְעוּ שֶׁנִּגְּפוּ לִפְנֵי אוֹיְבֵיהֶם, אֲפִלּוּ לֹא נֶהֶרְגוּ אֶלָּא הַמִּעוּט מֵהֶם. \u0005וְהוּא הַדִּין אִם הָלְכוּ בַּשֶּׁבִי (נ\"י פא\"מ)\u0006.\nהַשּׁוֹמֵעַ \u0010c20\u0011 בִּרְכַּת הַשֵּׁם, וַאֲפִלּוּ בִּרְכַּת הַכִּנּוּי \u0005(רַמְבַּ\"ם פ\"ב מֵהִלְכוֹת עֲבוֹדַת כּוֹכָבִים ד\"י)\u0006 \u0005אֲפִלּוּ אָמְרוּ בִּלְשׁוֹן לַעַז הָוֵי כְּכִנּוּי\u0006 \u0005(נ\"י פֶּרֶק אַרְבַּע מִיתוֹת)\u0006, \u0010y52\u0011 \u0010c21\u0011 חַיָּב לִקְרֹעַ, וְהוּא שֶׁיִּשְׁמָעֶנָּה מִיִּשְׂרָאֵל. \u0010y53\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּבַזְּמַן הַזֶּה מוּמָר דִּינוֹ כְּעוֹבֵד כּוֹכָבִים (ג\"ז שָׁם)\u0006. \u0010y54\u0011 וַאֲפִלּוּ הַשּׁוֹמֵעַ מֵהָעֵדִים הֵיאָךְ בֵּרַךְ פְּלוֹנִי, חַיָּב לִקְרֹעַ. וְהָעֵדִים אֵינָם צְרִיכִים לִקְרֹעַ פַּעַם אַחֶרֶת. הָרוֹאָה \u0010y55\u0011 סֵפֶר תּוֹרָה שֶׁנִּשְׂרַף, אוֹ תְּפִלִּין, אוֹ אֲפִלּוּ מְגִלָּה אַחַת מֵהַנְּבִיאִים אוֹ מֵהַכְּתוּבִים, \u0010y56\u0011 \u0010c22\u0011 קוֹרֵעַ שְׁתֵּי קְרִיעוֹת. \u0010c23\u0011 וְדַוְקָא שֶׁשּׂוֹרְפִין אוֹתָהּ בִּזְרוֹעַ, \u0010y57\u0011 וּכְמַעֲשֶׂה שֶׁהָיָה.\nהָרוֹאֶה עָרֵי יְהוּדָה בְּחֻרְבָּנָן, אוֹ יְרוּשָׁלַיִם אוֹ בֵּית הַמִּקְדָּשׁ, חַיָּב לִקְרֹעַ. \u0005וְעַיֵּן בא\"ח סי' תקס\"א.\u0006\nכָּל אֵלּוּ הַקְּרָעִים רַשַּׁאי \u0010y58\u0011 \u0010y59\u0011 \u0010c24\u0011 לְמָלְלָן, לְשָׁלְלָן, \u0010y60\u0011 לְלַקְּטָן, לַעֲשׂוֹתָן \u0010y61\u0011 כְּמִין סֻלָּמוֹת, לְמָחֳרָתוֹ; אֲבָל אֵין מִתְאַחִין לְעוֹלָם.",["\u0003שראוי להתאבל. \u0004כאשר יתבאר לקמן סי' שע\"ד:","\u0003חייב לקרוע. \u0004מדרבנן ואסמכוה אקרא:","\u0003קודם שיסתום פני המת בקבר. \u0004ולעיל סימן של\"ט סעיף ג' נתבאר דכשמגיע לדיין האמת קורע האבל:","\u0003כשקורעין על שאר מתים. \u0004כשעומדים שם בשעת יציאת נשמה כדלקמן סעי' ה' כן הוא בסמ\"ק ופוסקים שם:","\u0003אם אחר שבעה כו'. \u0004כלומר אם מת לו מת אחר ז' סגי כדלקמן סעיף כ\"א:","\u0003על חמיו כו'. \u0004משמע אבל לא על שאר קרובי אשתו. בית יוסף וכן הוא בטור לקמן סי' זה:","\u0003או אשה. \u0004וכן תינוק קטן מיהו לא נהגו לקרוע על הקטן וכ\"כ מהרש\"ל מיהו בקטן שלומד מקרא צריך לקרוע לכל הפירושים כ\"כ הב\"ח:","\u0003אבל רגיל לעשות עבירה. \u0004אף לתיאבון אין קורעין ואין מתאבלין עליו:","\u0003וי\"א שמומר כו' עד וכן עיקר. \u0004משמע דאף במומר שנהרג בידי עובד כוכבי' עיקר דאין להתאבל עליו וכ\"כ בעט\"ז וי\"א דאין מתאבלים עליהם וכן עיקר עכ\"ל וצ\"ע שבד\"מ לא הביא אלא הגהת אשר\"י והא\"ז שכתבו דמתאבלי' עליו ולא הביא שום חולק ולפעד\"נ שא\"א לחלוק על זה והוא שנ\"ל שיצאה להם כן מש\"ס פרק נגמר הדין [סנהדרין דף מ\"ז ע\"א וב'] דמומר שנהרג בידי עובד כוכבים כיון דלא מיקטל כדין הוי ליה מיתתו כפרה ומתאבלים עליו עיין שם וכ\"מ מדברי הר\"מ שהביא הרא\"ש בפרק אלו מגלחין ע\"ש:","\u0003מתאבלים עליו. \u0004דחזקה שהרהר בתשובה עכ\"ל עט\"ז ולא דק דא\"כ כ\"ש נהרג ע\"פ ב\"ד והטעם הוא בהגהת אשר\"י וא\"ז שם דכיון שנהרג ה\"ל כפרה והיינו כדאי' בש\"ס דכיון דשלא כדין מיקטל ה\"ל כפרה ועיין עוד לקמן סי' שד\"מ מדינים אלו:","\u0003על אדם כשר שאינו חשוד כו'. \u0004והב\"ח כתב דלהר\"ר יונה אדם כזה לא נקרא אדם כשר ואינו נקרא אדם כשר לקרוע עליו אף שלא בשעת יציאת נשמה אלא כשנוהג מנהג כשרים לחזור אחר מצות ג\"ח וכ\"נ דעת הרמב\"ן והכי נקטינן ע\"כ:","\u0003והוא שעומד שם כו'. \u0004מל' זה משמע קצת שאינו חייב לקרוע אלא בפניו ול\"נ כהרא\"ש והטור דאפילו עומד בביתו חייב לקרוע אפי' אינו עומד עליו כשידע בין מיתה לקבורה כ\"כ הב\"ח ועיין שם שהאריך ול\"נ גם דעת המחבר כן שהרי כתב בא\"ח סי' תקמ\"ז סעיף ו' ועל אדם כשר אינו קורע אא\"כ ידע בין מיתה לקבורה ע\"ש מיהו האידנא נהגו להקל בכל ענין:","\u0003ותלמידי חכמים פטורים כו'. \u0004ודעת הראב\"ד והרא\"ש גבי כי נח נפשיה דרב ספרא דסבור רבנן דלא למיקרע עליה כו' נראה להדיא דתלמידי חכמים חייבים ע\"ש:","\u0003אם הוא תוך ל' יום. \u0004ואם לא קרע בשעת שמועה יקרע עליו בשעת הספדו ע\"ש כנ\"ל וכ' הב\"ח מיהו דוקא כשהספדו תוך ל' אבל לאחר ל' אין קורעין אפי' בשעת הספד וכ\"כ הרא\"ש בשם הראב\"ד:","\u0003עד שמגלין את לבם. \u0004ולהי\"א שבסעיף ח' כ\"ש הכא שאינו קורע אלא טפח ובסי' רמ\"ב יישב הב\"י ממ\"ש הרמב\"ם דברבו קורע עד שמגלה לבו ומ\"ש כן בת\"ח הניח בצ\"ע ע\"ש:","\u0003וי\"א. \u0004בש\"ע נרשם כך משמע בטור וליתא אלא אדרבה בטור משמע איפכא אלא הוא דעת הר\"מ שהביא הרא\"ש והגמי\"י בשם י\"א שהביא ראיה מדאמרינן בש\"ס כי נח נפשי' דרב ספרא לא קרעוה רבנן עליה אמרי לא גמרינן מיניה אמר ליה אביי מי תניא הרב שמת חכם שמת תניא ועוד כל יומא שמעתתי' בפומן בבי מדרשא והרא\"ש כתב ול\"נ הפך דבריו וה\"פ ועוד אפי' אי תנן הרב שמת כל יומא שמעתתיה בפומן והרי הוא רב שלנו עכ\"ל וכב\"י ונ\"ל שדברי הרא\"ש מבוארין בטעמן ומינה לא תזוז ולי נראה דברי הר\"מ ברורין בטעמן דלפירוש הרא\"ש קשיא אטו לא ידעי רבנן דכל יומא שמעתתיה בפומן אלא דהוה ס\"ל דזהו לא מיקרי רב וקאמר אביי דהוי רב ועיקר חסר מן הספר והכי הל\"ל ועוד דכיון דשמעתתיה בפומן הוי רב שלנו ותו מנ\"ל לאביי הכי דלמא רבנן ס\"ל דשמעתתיה בפומן לא הוי רב ותו ל\"ל האי ועוד דהא רב ספרא עכ\"פ חכם הוי אלא ה\"פ מי קתני הרב שמת חכם שמת תניא דהיינו שידעינן משמועותיו שחדש ועוד כל יומא שמעתתיה בפומן כלומר עוד כל היום שמועותיו בפינו וא\"כ אנו יודעין משמעתתיה שחדש וזה ברור:","\u0003וכן נהגו להקל. \u0004כתב הב\"ח משמע דס\"ל שאפילו שאר חכם אינו שוה לחכם שמת אלא קטן ממנו נמי אינו קורע ולפע\"ד ליכא למ\"ד הכי שהרי בברייתא מפורש חכם שמת הכל כקרוביו הכל קורעין עליו וכדקאמר אביי בש\"ס מי קתני רב שמת חכם שמת תניא אפילו אינו רבו וכמו שדקדק הרא\"ש מהך דאביי ומפורש בב\"י עכ\"ל ולא עמדתי על סוף דעתו דהרי הר\"מ קאמר הכי ומפרש דהך דחכם שמת היינו שיודעין משמועותיו שחדש ועפ\"ז הם דברי הרב וכבר כתבתי בסמוך שדברי הר\"מ ברורין ומ\"ה אני תמה שלא נהגו לקרוע אפי' על חכם שיודעין משמועותיו שחדש ואפי' על גדול ממנו ואין להם על מה שיסמכו ואולי ס\"ל דלא נקרא ת\"ח אלא כשיודע דבר הלכה בכל מקום ואפי' במסכת כלה כדאיתא בש\"ס וכבר כתב האגודה פ\"ק דחולין דעתה בעונינו אין ת\"ח דהא אין יודע אפי' במסכת כלה עכ\"ל והביאו מהרי\"ל ומהרי\"ו בתשובותיהם כמש\"ל סי' י\"ח ס\"ק כ\"ט וצ\"ע:","\u0003על רבו כו'. \u0004ע\"ל סי' רמ\"ב סעיף כ\"ה:","\u0003על כל המתים כו'. \u0004כתב מהרש\"ל דנהיגין דעל אב ואם מקרעין מצד שמאל ועל כל שאר קרובים כגון בניו ואחיו מצד ימין וכן מצאתי עכ\"ל וכתב הב\"ח סעיף י\"ב דכן נוהגין בקהלות ומ\"מ היינו מצד המנהג אבל מדינא משמע דמצד שקורעין על אביו ואמו קורעין גם על שאר קרובים כדמשמע בש\"ס ופוסקים וט\"ו לקמן סעיף כ\"ב או אפשר שכיון שכבר קרע מצד א' לא נהגו להחמיר בכך ולקרוע בצד השני אלא סגי בהוספה:","\u0003ולא הסרבל העליון. \u0004כתב בתשו' משאת בנימין סי' פ' דהיינו מה שקורין מאנטי\"ל אבל הרא\"ק חייבים לקרוע בין על אביו ועל אמו בין על שאר מתים:","\u0003אבל שאר בגדיו כו'. \u0004כלומר עד שמגלה לבו וכדלעיל סעיף ט':","\u0003אלא שהאשה כו'. \u0004כלומר בקריעת אב ואם שצריך לקרוע כל הבגדים האשה קורעת התחתון תחלה ומחזירה לאחוריה וחוזרת וקורעת העליון כדי שלא תגלה את לבה ויבואו האנשים העומדים שם לבוא לידי הרהור ואע\"ג דכתב הרב בסמוך דאין נוהגין לקרוע החלוק מ\"מ כשמגלה החלוק נמי איכא פריצות כמו מגלה לבה כ\"כ הב\"ח בסעיף י':","\u0003על אביו ואמו אם מחליף כו'. \u0004היינו בחול אבל בשבת אף על אביו ואמו מחליף ואינו קורע ואם אין לו להחליף מחזיר הקרע לאחוריו כדאיתא בש\"ס דף כ\"ד ע\"א וכ\"כ הרמב\"ם בפ\"י וכן משמע לקמן סי' ת' וע\"ש מיהו היינו דוקא כשמחליף בבגדים של חול אבל בבגדי שבת נוהגין איסור כדלקמן סי' שפ\"ט סעיף ג':","\u0003לאחר שלשים. \u0004מותר ג\"כ לשלול בערב הרגל ודוקא סמוך לערב לאחר שהתפללו מנחה. מהרי\"ו סי' ז':","\u0003ואין חילוק כו'. \u0004כלומר אע\"ג דרגל מבטל גזרת ז' ול' כדלקמן סי' שצ\"ט היינו דוקא לענין אבילות אבל לענין קריעה וכל מילי דקריע' בעינן ז' ול' ממש כ\"כ ב\"י בשם הגמי\"י בשם ראבי\"ה והוא בתשובת מיימוני מיהו האידנא נהגו לאחות הקרע כל שפסק האבלות ונראה דמשום דטעמא דראבי\"ה דאמרינן בש\"ס דאבלות לחוד וקריעה לחוד ואנן קיי\"ל כהרמב\"ן (לקמן סעיף ל') דכשם שאין מתאבלין על הקטן כך אין קורעין דהא דאמרינן בש\"ס אבלות לחוד וקריעה לחוד היינו לומר דלית ביה האי כללא דהלכה כדברי המיקל באבל אבל לענין כל שאר מילי אין חילוק וכמ\"ש הרמב\"ן שם ומביאו בית יוסף וכתב דהכי נקטינן וכן לקמן סי' שצ\"ט שכתבו הפוסקים סתמא שהרגל מבטל גזרת ז' ול' משמע דכל הגזרה ששייך בז' ולמ\"ד מבטל מכל דבר כנ\"ל:","\u0003ומי שאין לו חלוק לקרוע. \u0004כגון שהוא פוחח (פי' בגדיו קרועים) או שהיה לבוש בגדים שאולים. רמב\"ן. או שאין לו רק החלוק התחתון של פשתן שאותו אין קורעין כדלעיל סעיף י' בהג\"ה. ב\"ח:","\u0003כל בגדיו. \u0004היינו אותן שעליו בשעת שמועה אבל לא אותן שמחליף כדלעיל סעיף (ז') [י\"ד]:","\u0003צריך להודיעו. \u0004משום מקח טעות אבל משום איסורא א\"צ להודיעו דהא אפילו בסתם אסור ללוקח לאחותו כדלעיל סימן ט\"ז באותו ואת בנו. רמב\"ן. והב\"ח כ' דל\"ד דהתם דין או\"ב הכל יודעין מה שאין כן דין קריעה דלאו כ\"ע דינא דקריעה גמירי:","\u0003המלל כו'. \u0004עיין ס\"ס זה פירושו:","\u0003דהיינו תפירה כו'. \u0004והוא שקורין בל\"א איב\"ר נא\"ט כמו שעושין בתפירת הכתונת וי\"מ אותו כמו התפירה שעושין החייטין בבתי שוקיים שחוזרין וכופפין הבגד היוצא מהתפירה לשני צדדי התפירה ותופרין אותו בשני צדדיו ומותחין אותו עד שאין ניכר התפירה פרישה ועב\"ח:","\u0003קרע אחר. \u0004היינו שבאותו קרע מוסיף וקורע עוד טפח או מרחיק שלש אצבעות וקורע עוד טפח כדלקמן סעיף כ\"ג:","\u0003אחר ז' של שני. \u0004כ' הב\"ח () משמע אם מת לו מת תוך שבעה לשני אע\"פ שקרע על שני קרע אחר מ\"מ אין להוסיף כל שהוא על הקרע ראשון כו' ולי נראה איפכא שבתוך שבעה של שני צריך טפח ואפשר הכי נמי קאמר אין להוסיף עליו כל שהוא אלא צריך טפח ודוחק:","\u0003מחזירו לאחוריו. \u0004וקורע מלפניו:","\u0003הופכו למטה. \u0004וישים לו בית צואר מאחריו ויקרענו:","\u0003קורע קריעה אחרת כו'. \u0004והב\"ח כתב דאם בקריעה הראשונה שקרע על בנו הבדיל קמי שפה א\"צ קריעה אחרת וסגי במה שמוסיף על הקרע הראשון ואין זה נראה לענין דינא דאף לפי פירושו מוכח מהרמב\"ן דלהרמב\"ם אפילו הבדיל קמי שפה צריך קריעה אחרת וכן משמע פשט דבריו וכתב עליו הרמב\"ן שיפה כוון וכ\"פ רבינו ירוחם וכ\"כ נ\"י בשם הראב\"ד וכן נראה דעת הרב שאע\"פ שכתב לעיל סעיף י\"ג שנוהגין להבדיל קמי שפה על כל המתים סתם כאן ובסעיף כ\"ג כדברי המחבר וכן העט\"ז:'","\u0003שהרי צריך כו'. \u0004משמע אע\"פ שהבדיל קמי שפה גם בקריעה ראשונה מ\"מ כיון שצריך גם עתה להבדיל א\"כ כל שמוסיף אינו מבדיל לכך צריך קריעה חדשה:","\u0003אבל אמרו לו כו'. \u0004והב\"ח פסק דבכה\"ג לא יצא ידי קריעה ולא מיקרי סתם אלא הקורע על מתו לשם מי שהוא א\"צ לחזור ולקרוע אפי' לא נודע לו מי הוא עד אחר (כ\"ד חודש) [כדי דבור] ע\"ש וע\"ל סי' רל\"ד סעיף ל\"ג:","\u0003יצא. \u0004וכתב ד\"מ בשם נ\"י פרק א\"מ דאם א\"ל מת לו מת סתם ואינו יודע איזהו וקרע סתם ואח\"כ נודע לו מי הוא יצא ידי קריעה דיש ברירה ע\"כ:","\u0003יצא ידי קריעה כו'. \u0004אבל אמרו לו מת וקרע ולא מת ואח\"כ מת לא יצא ידי קריעה. רמב\"ן בסת\"ה ומביאו הטור:","\u0003ידי קריעה. \u0004ולענין ז' ימי אבילות קרוב היה לומר כיון שחלה עליו אבלות ונהגו אע\"פ שבטל מקצת הימים בשוגג עולין לו ואין תשלומין לאבלות ודבר זה צריך תלמוד רמב\"ן שם ומביאו הטור וע\"ל סימן שצ\"ו:","\u0003מקרעין לו. \u0004מפני עגמת נפש. ועיין בטור מ\"ש בשם הרי\"ץ גאות וע\"ל סימן שצ\"ו:","\u0003לא יצא כו'. \u0004דל\"ד לקרע בשבת שגוף החלוק אינה עבירה אע\"פ שהמעשה שעשה הוא עבירה אבל הכא גוף החלוק הוא עבירה:","\u0003דלא קים לן כו'. \u0004אבל קים לן דכלו חדשיו כגון שבעל ופירש אפילו מת בתוך ל' קורע ומתאבל עליו:","\u0003רק על אביו כו'. \u0004ואין חילוק בין יום קבורה ליום שמועה רק בין אביו ואמו ושאר קרובים. ב\"ח:","\u0003אבל על שאר מתים כו'. \u0004כלומר קרוביו אבל על שאר אדם כשר נהגו להקל שלא לקרוע כלל כדלעיל סעיף ו' בהג\"ה:","\u0003ובמקום שאין מנהג כו'. \u0004כתוב בתשובת משאת בנימין סימן ע\"ב דהיינו בכל מלכות פולי\"ן דאילו באשכנז נהגו שלא לקרוע כי אם על אב ועל אם וכמ\"ש הרב בא\"ח סימן תקמ\"ד סעיף ו' אבל במלכות פולין יש לקרוע על כולם:","\u0003תהיה רחוקה כו'. \u0004ואפי' לפי מנהגינו לעיל סעיף ל\"א דאין קורעין על שאר קרובים בחש\"מ לא נהגו כך אלא היכא דיכול לקרוע אחר הרגל אבל היכא דנעשית רחוקה לאחר הרגל דאין יכול לקרוע אחר הרגל בהא ליכא מנהג ויש לתפוס כהלכה וכרוב הגאונים נ\"ל וכ' מהרש\"ל היכא דשמע שמועה רחוקה אינו קורע ברגל אפילו על אביו ואמו ע\"כ עכ\"ל ב\"ח:","\u0003קורעו ומאחהו. \u0004אע\"ג דעל האב אין מאחין לעולם כדלעיל סעיף ט\"ו שאני הכא שאם נתן לו רשות לקרוע שלא יתבייש שם לא הקנהו הלכך מאחהו:","\u0003ואם לא הודיעו. \u0004שהולך לבקר בו החולה:","\u0003לא יגע בו. \u0004ונ\"ל) דאף אם קרע לא יצא דהוי שואל שלא מדעת וגזלן הוי ובחלוק הגזול לא יצא כדלעיל סכ\"ט:","\u0003ובח\"מ כו'. \u0004ולענ\"ד נראה דנ\"ק דשם כ' שאל חלוק מחבירו לילך בו לבית האבל כדי שילך ויחזור עכ\"ל ר\"ל דהשואל בקש מהמשאיל אם כן לא נתכוין אלא לטובת השואל למלא בקשתו ויכול לומר לו לא השאלתי לך אלא שתלך ותחזור אבל הכא כתב המשאיל לחברו כו' ר\"ל שהמשאיל בא מעצמו לזכות להשואל במצוה שיקיים מצות ניחום אבלים א\"כ כל יומא ויומא רמיא מצוה עליה כנ\"ל ובב\"ח ובסמ\"ע כתבו יישובים אחרים דחוקים גם לא נתישב לפי דבריהם לאיזה צורך כתבו הט\"ו דין זה כאן שאין לו שייכות אלא בח\"מ גם למה הביא בב\"י דברי הרמב\"ם שבח\"מ כאן אבל לדידי א\"ש דבח\"מ מיירי לענין ממונא וכאן לענין איסור ודו\"ק:","\u0003קורעין כו'. \u0004דכתיב ויחזק דוד בבגדיו ויקרעם על שאול ועל עם ה' כי נפלו בחרב וכב\"י בשם רבינו ירוחם דלפי הפסוק נראה שחייב להתאבל כל היום ולפיכך אינו שולל עד למחר ע\"כ ומביאו ד\"מ ונראה דה\"ה דמאחין למחר):","\u0003והוא שישמע מישראל. \u0004לדעת הרמב\"ן והטור דבשם המיוחד חייב לקרוע אפי' בעובד כוכבים ופי' שם המיוחד בין בכתיבתו בין בקריאתו ועב\"ח:","\u0003וי\"א כו'. \u0004והב\"ח חלק על זה לפי מה שפירש הוא דברי הרמב\"ם והסמ\"ג דאפי' בישראל מומר חייב לקרוע ואין דבריו מוכרחים ע\"ש.","\u0003ואפילו השומע מהעדים כו'. \u0004כלומר כגון ששמע מהעדים שפלוני בירך השם אע\"פ שאין העד מוציא הגדוף מפיו ממש חייב השומע מפי העד לקרוע וא\"צ לשמוע משני העדים אלא חפי' מאחד מן העדים וה\"ה כשאינו עד כשהעיד בב\"ד אלא ששמע הגדוף ממש כל השומע מפי אותו ששמע הגדוף ממש אע\"פ שזה לא הוציא מפיו הגדוף ממש אלא שאמר פלוני גידף השם חייב השומע לקרוע אבל השומע מפי אחד פלוני גידף השם והוא עצמו לא שמע הגידוף ממש אלא שמעו מפי אחד מהעדים אין זה האחרון חייב לקרוע. כל זה כתוב בספר ת\"ה דאיתא בירושלמי עכ\"ל ב\"ח:","\u0003שנשרף. \u0004וה\"ה נקרע ונחתך ונמחק בזרוע בין מישראל בין מעובדי כוכבים דהכל תלוי כשרואה החלול השם בזרוע. ב\"ח:","\u0003קורע ב' כו'.\u0004 אחת על הכתב וא' על הגויל:","\u0003וכמעשה שהיה. \u0004ששרף יהויקים את המגלה:","\u0003למוללן. \u0004שאוחז ב' ראשי הקרע בין האצבעות וכורכן יחד ותוחב שתים או שלש תפירות:","\u0003לשללן. \u0004תפירה רחבה שתפר הרבה במשיחה אחת:","\u0003ללקטן. \u0004שאורג כל הקרע ראשו על סופו ותוחב במחט ב' או ג' פעמים:","\u0003כמין סולמות. \u0004פירוש כמעלות הסולם שתופר ב' תפירות וחוזר ותופר למטה והניח בין תפירה לתפירה הפסק. כל זה מדברי רבינו ירוחם שהביא ב\"י:"],["\u0003או אם בנו. \u0004פירוש אם גירשה:","\u0003של איש או אשה. \u0004בטור בשם הרמב\"ן הכריע כן דלא כפירש\"י הטעם דדומה לס\"ת שנשרף היינו שעדיין היה יכול ללמוד וא\"כ לא היה צריך לקרוע על אשה דקשה על זה היאך יקרע על העתיד אלא הטעם דדמיון בעלמא הוא לס\"ת שנשרף שהוא הפסד גדול וחרדה רבה ועל כן קורעין גם על אשה וכתב רש\"ל שלפי פרש\"י משמע דקורעין על קטן אבל בפרק האורג פירש\"י ומהרא\"ם והרא\"ש שאין לך ריק בישראל שאין בו תורה ומצות ואם כן מ\"ה קורעין נמי על אשה ולא על קטן וכנ\"ל עכ\"ל וכתב מו\"ח ז\"ל מיהו בקטן שלומד מקרא צריך לקרוע לכ\"ע עכ\"ל:","\u0003שנהרג בידי עובד כוכבים כו'. \u0004דעל ידי כן הוה ליה כפרה. רבינו גרשון ישב על בנו שהמיר ומת י\"ד יום דק\"ו לשכינה י\"ד יום כ\"כ בהגהות אשר\"י סוף פ' אלו מגלחין:","\u0003על רבו כו'. \u0004כתב ברוקח על רבו שלמדו חכמה יושב עליו יום אחד או שעה אחת אבילות):","\u0003דהיינו בגד העליון שקורין קאפ\"ה כו'. \u0004הטעם בזה בב\"י בשם סמ\"ג שאינו אלא לצניעות וכן פסק בסמ\"ק שאין קורעין הגלימא העליונה שקורין גרינ\"ק וזהו הטעם שכתב רמ\"א שאין נוהגין לקרוע הסרבל העליון ורצונו לומר מה שקורין בל\"א רא\"ק ובספר משאת בנימין כתוב שהרא\"ק צריך קריעה מן הדין שהוא מלבוש גמור ולא בא רמ\"א כאן לפטור אלא המלבוש שקורין שו\"ל מנטי\"ל שהוא בגד שראשו מקיף האדם סביב צוארו ומשתלשל למטה שהולכין בו קצת זקנים בקראקא לצניעות בבית הכנסת ולא הביא שום ראיה לדבריו והם תמוהים מאד בעיני דבשו\"ל מאנטי\"ל אין הולכין לבית הקברות ואיך ירמוז עליו רמ\"א במה שאינו בנמצא כי אותו מנטי\"ל הוא לכבוד והידור ואין האבל הולך בבגד כזה בעת צרתו ובאגודה פרק אלו מגלחין כתב בהדיא וז\"ל י\"מ כמו קאפ\"ה בצרפת או סרבל הואיל ולצניעות נעשית ובשבתו בביתו אינו לובשו עכ\"ל והרי גם הרא\"ק אין אדם לובשו בביתו ובספר הנ\"ל מביא דברי אגודה אלו לראייה לו ואמר שהאגודה לא נתכוין לזה כי אין אותו הרא\"ק בנמצא אלא במדינה זאת ואתפלא מאד על זה דמה בכך דודאי דין אחד להם דכך לנו מלבוש הרא\"ק כמו הקאפ\"ה במדינות אחרות דאידי ואידי מלבוש עליון קרי להו דהא אין האדם הולך בו בביתו ואם לפעמים לובשו בביתו דעתו בטילה נגד הרוב בני אדם. ועוד אני אומר דאין ראוי אפי' להחמיר ולקרוע הרא\"ק דהוי חומרא דאתא לידי קולא דהיינו בשאר מתים שדין הוא לקרוע הבגד העליון לחוד וזה ודאי אינו נכון שלא לקרוע רק הרא\"ק ולצאת בו ידי קריעה בבגד שהוא חייב ודאי קריעה וכמו שכתב בית יוסף בשם הגה' מיימוני שתמה על הר\"מ בקריעת המקטורי\"ן בדרך זה והיינו ממש ברא\"ק שבמדינה זו על כן נראה לע\"ד ברור דדברי רמ\"א בסרבל העליון דהיינו רא\"ק שלנו דאין צריכין קריעה דאף שהוא מלבוש חשוב מכל מקום לאו בחשיבות תליא מילתא אלא במה שהוא לובש תמיד כן נ\"ל:","\u0003ועל אביו ואמו כו'. \u0004כתב רש\"ל דנוהגין דעל אביו ואמו מקרעין מצד שמאל ועל שאר קרובים כגון בניו ואחיו מצד ימין וכן מצאתי עכ\"ל אבל במהרי\"ל כתוב דקרע לבנו על אמו בצד ימין. ומו\"ח ז\"ל כתב מיהו מסתברא כיון דעל אביו ואמו צריך לקרוע עד שיגלה לבו והלב משמאלו על כן צריך לקרוע משמאל לגלות לבו וכן נוהגין בקהילות ע\"פ רש\"ל:","\u0003אם בא להחליף כו'. \u0004כתב מו\"ח ז\"ל בשם מהר\"ר מנחם מ\"ץ בגדים ישנים שהיו יודעי' שלבש אותם קודם מיתת אביו יכול ללובשן [אחר בלא קריעה עכ\"ל:","\u0003שולל. \u0004פי' תפירה בלתי שוה מאחה היינו תפירה שוה:","\u0003לחלוץ כתף. \u0004בסוף פ\"ק דבבא קמא פירש\"י על חלוצי כתף שקרעו בגדיהם עד שנראה כתפיהם ובפרישה פירש מ\"ש הטור פי' חולץ זרוע ומוציא כתפו חוץ לקרע היינו במקום שהוא פתוח כבר ולא שיעשה אז קריעה ולא עיין בגמרא שזכרתי:","\u0003כך אסור להפוך כו'. \u0004נראה דאם בא לחתוך סביבות הקריעה ולהשליכו ולהושיב שם חתיכת בגד אחר שרי לאחר י\"ב חודש לאביו ואמו דאין זה בכלל איחוי הקריעה כלל וכן הסכים מו\"ח ז\"ל בזה:","\u0003מתוך המלל. \u0004כתב ב\"י בסוף סי' זה וכפירש\"י דאלפסי וז\"ל מולל שני ראשי הקרע בין אצבעותיו וכורכן יחד כעין כריכות ספרים ותוחב שם שנים וג' תפירות. שולל תפירה רחבה. לוקט אוגד בידו כל הקרע ראשו עם סופו ותוחב במחט שתים ושלש פעמים. סולמות כמעלות הסולם שתופר שתי תפירות ומפסיק וחוזר ותופר למטה שמניח בין תפירה לתפירה הפסק מעט ע\"כ לשונו. ועל כן הקורע מתוך אלו לא יצא כיון שבלאו הכי היה כמין קריעה:","\u0003קרע אחר. \u0004או מוסיף על הקרע זה טפח כמ\"ש למטה:","\u0003והוא שנודע לו תוך כדי דיבור. \u0004עיין מה שכתבתי מזה בסי' רל\"ד סעיף ל\"ג:","\u0003בפעם הראשון כו'. \u0004אבל אם היה חי בפעם הראשון לא יצא ידי קריעה דהא אחר כדי דיבור הוא:","\u0003מקרעין לו \u0004בטור כתוב מפני עגמת נפש פירוש כדי להרבות בהספד. כתב הרי\"ץ גיאות וקטן שהגיע לחינוך קורעין לו כדרך שמחנכין אותו בשאר מצות. ופירש ב\"י דהיינו אפילו היכא שמת לו מת דלית ביה משום עגמת נפש. וכתוב בדרישה מכאן ראיה קצת שקטן שהגיע לחינוך צריך לנהוג כל דיני אבילות) ע\"כ. ונראה לי דאף ביום שמועה קרובה דהוה כמו יום הקבורה כמו שכתוב לקמן סימן ת\"ב הוה דינא הכי דגם שם איכא עגמת נפש וכבוד למת לעיני הרואים קריעה של קטן ויש מי שחולק על זה ואין בדבריו ממש:","\u0003בחלוק גזול. \u0004לפי שהגוף של חלוק בעבירה מה שאין כן בקורע בשבת אין עבירה בגוף החלוק:","\u0003אין קורעין עליו. \u0004לפי שהקריעה היא דרבנן וספיקא לקולא:","\u0003רק על אביו כו'. \u0004לפי שבמרדכי מביא דעות שאין לקרוע כלל בח\"ה על כן מכריעין לחלק בין אב לשאר קרובים אבל במקום שאין מנהג יש לקרוע על כולם בח\"ה דהעיקר כההיא דעה שקורעין בח\"ה דמשמעות המשנה כך היא. וכתב מו\"ח ז\"ל אע\"פ דנהיגין שלא לקרוע על שאר מתים בח\"ה היינו אם אפשר לקרוע אחר המועד אבל היכא דשמע שמועה קרובה ברגל ולאחר הרגל נעשית רחוקה דאינו יכול לקרוע אחר הרגל בזה ליכא מנהג ויש לתפוס כהלכה דקורעין בח\"ה עכ\"ל. וכתב עוד בשם רש\"ל ונראה בעיני היכא ששמע שמועה רחוקה אין קורעין במועד אפילו על אב ואם אלא קורע אחר הרגל דמאחר שנפסק ממנו אבילות לא חמיר הקריעה לדחות הרגל עכ\"ל:","\u0003תהיה רחוקה. \u0004פי' דאמרינן בגמ' אין קריעה בלא שבעה והוה אמינא דבכאן אינו קורע כיון שלא ינהוג שבעה אחר המועד דהא יהיה רחוקה קמ\"ל דלא כן הוא דלא אמרו אין קרועה בלא שבעה אלא אם שמע בי\"ט עצמו דאינו יכול לקרוע ולאחר הרגל יהיה רחוקה ולא ינהוג אז אבילות אלא יום א' בזה לא יקרע אפילו אחר הרגל אבל בשמע שמועה קרובה בחול המועד דיכול לקרוע קורע בח\"ה אע\"פ שאחר הרגל יהיה רחוקה ולא ינהוג אלא יום אחד מ\"מ עכשיו זמן קריעה היא לו דאין הרגל מפסיק אלא האבילות ולא קריעה:","\u0003קורעו ומאחהו. \u0004אע\"פ ששאר קרעים של אב אינם מתאחים הכא שאני שלא נתן המשאיל רשות רק לקרוע שלא יתבייש שם אבל לא הקנהו לו וזהו דלא כדעת הטור:","\u0003ברכת השם. \u0004שאמר יכה יוסי את יוסי:","\u0003והוא שישמענה מישראל. \u0004דאם היינו קורעים על עובדי כוכבים יתמלאו כל הבגדים קרעים:","\u0003קורע שתי קריעות. \u0004אחת על הגוילין ואחת על הכתב:","\u0003ודוקא ששורפין אותו בזרוע. \u0004משמע דוקא בשריפה אבל בשאר כליון לא וכ\"פ ב\"י דהכי משמע בירושלמי ולא משמע הכי בגמרא שלנו שהרי אמרי' דבת נעמית' הוי בעית למיבלע תפילין של רבי אבהו אמר חייבינא שתי קריעות אמרו ליה הכי אמר שמואל לא אמרו אלא בזרוע וכמעשה שהיה ביהויקים ולא אמרו שלא אמרו אלא בשריפה דוקא ובירושלמי אמרו בלשון זה לא אמרו אלא על ס\"ת ששרפו מלך ישראל בזרוע והנה ע\"כ מלך ישראל לאו דוקא כמו שכתב ב\"י גופיה והוא משמעות כל הפוסקים ממילא נמי מה שזכר שריפה הוא נמי לאו דוקא כיון דבגמרא שלנו ליתיה ע\"כ ודאי שריפה לאו דוקא וכ\"פ מו\"ח ז\"ל:","\u0003לשללן כו'. \u0004נתבאר בסעיף כ':"]],["\u0003הלכות אנינות\u0004\n\u0010y0\u0011 מִי שֶׁמֵּת לוֹ מֵת שֶׁהוּא חַיָּב לְהִתְאַבֵּל עָלָיו, \u0010y1\u0011 קֹדֶם קְבוּרָה \u0010y2\u0011 \u0010c0\u0011 אוֹכֵל בְּבַיִת אַחֵר. אֵין לוֹ בַּיִת אַחֵר, אוֹכֵל בְּבֵית \u0010y3\u0011 חֲבֵרוֹ. אֵין בַּיִת לַחֲבֵרוֹ, עוֹשֶׂה לוֹ מְחִצָּה וְאוֹכֵל; וַאֲפִלּוּ מְחִצָּה שֶׁל סָדִין סָגֵי, אִם תָּקַע שׁוּלֵי הַסָדִין בְּעִנְיָן שֶׁאֵינוֹ נִטָּל בָּרוּחַ. וְאִם אֵין לוֹ דָּבָר לַעֲשׂוֹת מְחִצָּה, מַחֲזִיר פָּנָיו וְאוֹכֵל. וּבֵין כָּךְ וּבֵין כָּךְ, \u0010y4\u0011 וַאֲפִלּוּ הוּא בְּעִיר אַחֶרֶת, \u0010y5\u0011 \u0010c1\u0011 אֵינוֹ מֵסֵב וְאוֹכֵל, וְאֵינוֹ אוֹכֵל בָּשָׂר וְאֵינוֹ שׁוֹתֶה יַיִן, וְאֵינוֹ מְבָרֵךְ בִּרְכַּת הַמּוֹצִיא וְלֹא בִּרְכַּת הַמָּזוֹן, וְאֵין מְבָרְכִים עָלָיו וְלֹא מְזַמְּנִין עָלָיו, אֲפִלּוּ אִם אוֹכֵל עִם אֲחֵרִים שֶׁמְּבָרְכִים, לֹא יַעֲנֶה אַחֲרֵיהֶם אָמֵן. וּפָטוּר מִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה, וַאֲפִלּוּ אִם אֵינוֹ צָרִיךְ לַעֲסֹק בְּצָרְכֵי הַמֵּת, כְּגוֹן שֶׁיֵּשׁ לוֹ אֲחֵרִים שֶׁעוֹסְקִים בִּשְׁבִילוֹ. וְיֵשׁ אוֹמְרִים שֶׁאֲפִלּוּ אִם יִרְצֶה לְהַחְמִיר עַל עַצְמוֹ לְבָרֵךְ אוֹ לַעֲנוֹת אָמֵן אַחַר הַמְּבָרְכִין, אֵינוֹ רַשַּׁאי \u0005וְעַיֵּן בא\"ח סי' ע\"א.\u0006 וּבְשַׁבָּת וְיוֹם טוֹב, אוֹכֵל בָּשָׂר וְשׁוֹתֶה יַיִן, \u0010y6\u0011 \u0005אִם יִרְצֶה (רַבֵּנוּ יוֹנָה פ' מִי שֶׁמֵּתוֹ)\u0006. וּמְבָרֵךְ, וְחַיָּב בְּכָל הַמִּצְוֹת, חוּץ מִתַּשְׁמִישׁ הַמִּטָּה שֶׁאָסוּר בּוֹ. \u0005וּמֻתָּר לֵילֵךְ לְבֵית הַכְּנֶסֶת בְּשַׁבָּת, וְאַף בְּחֹל אֵין בּוֹ אִסּוּר, רַק מֵאַחַר שֶׁאָסוּר לְהִתְפַּלֵּל, מַה יַּעֲשֶׂה שָׁם (כָּל בּוֹ)\u0006 \u0010y7\u0011 וְאִם צָרִיךְ לְהַחְשִׁיךְ עַל הַתְּחוּם כְּדֵי לַעֲסֹק בְּצָרְכֵי הַמֵּת, חָל עָלָיו אֲנִינוּת לֵיאָסֵר בְּכֻלָּן מִשָּׁעָה שֶׁמַּתְחִיל לָלֶכֶת כְּדֵי לְהַחְשִׁיךְ עַל הַתְּחוּם. וְאִם רוֹצֶה לְקָבְרוֹ בְּיוֹם טוֹב רִאשׁוֹן עַל יְדֵי עֲמָמִין, אָסוּר \u0010y8\u0011 \u0010c2\u0011 בְּכֻלָּן. וְכָל שֶׁכֵּן בְּיוֹם טוֹב שֵׁנִי, שֶׁהוּא בְּעַצְמוֹ יָכוֹל לְקָבְרוֹ, שֶׁחָלוּ עָלָיו כָּל דִּינֵי אֲנִינוּת. \u0010y9\u0011 \u0010c3\u0011 \u0005יֵשׁ אוֹמְרִים דְּתַלְמִיד עַל רַבּוֹ מֻבְהָק אָסוּר לֶאֱכֹל בָּשָׂר וְיַיִן כָּל זְמַן שֶׁמֻּטָּל לִפְנֵיהֶם (הַגָּהוֹת אֲשֵׁרִי פ' א\"מ)\u0006.\nמִי שֶׁמֵּת לוֹ מֵת, יֹאכַל בְּמוֹצָאֵי שַׁבָּת בְּלֹא הַבְדָּלָה, וְלֹא יִתְפַּלֵּל, וְלֹא בַּבֹּקֶר קֹדֶם קְבוּרָה, וּלְאַחַר קְבוּרָה יִתְפַּלֵּל תְּפִלַּת שַׁחֲרִית, אִם לֹא עָבַר זְמַנָּהּ. אֲבָל תְּפִלַּת הָעֶרֶב לֹא יִתְפַּלֵּל, שֶׁכְּבָר עָבַר זְמַנָּהּ. וְלֹא דָּמִי לְשָׁכַח וְלֹא הִתְפַּלֵּל עַרְבִית \u0010y10\u0011 שֶׁמִּתְפַּלֵּל שַׁחֲרִית שְׁתַּיִם, \u0010c4\u0011 כֵּיוָן שֶׁבַּלַּיְלָה לֹא הָיָה חַיָּב לְהִתְפַּלֵּל. וּלְעִנְיַן הַהַבְדָּלָה, \u0010y11\u0011 \u0010c5\u0011 יַבְדִּיל אַחַר שֶׁיִּקָּבֵר הַמֵּת \u0005(מהר\"מ וּמָרְדְּכַי והג\"מ)\u0006.\nמָקוֹם שֶׁנּוֹהֲגִים שֶׁכַּתָּפִים מְיֻחָדִים לְהוֹצִיא הַמֵּת, וּלְאַחַר שֶׁנִּתְעַסְקוּ הַקְּרוֹבִים בְּצָרְכֵי הַקְּבוּרָה יִמְסְרוּהוּ לָהֶם וְהֵם יִקְבְּרוּהוּ, מִשֶּׁמְּסָרוּהוּ לָהֶם, מֻתָּרִים הַקְּרוֹבִים בְּבָשָׂר וְיַיִן, \u0010y12\u0011 אֲפִלּוּ קֹדֶם שֶׁהוֹצִיאוּהוּ מֵהַבַּיִת, שֶׁשּׁוּב אֵינוֹ מֻטָּל עֲלֵיהֶם. \u0005הַגָּה: מָקוֹם שֶׁנּוֹשְׂאִין הַמֵּת מֵעִיר לְעִיר, אִם מָקוֹם קָרוֹב הוּא הָוֵי כְּאִלּוּ מֻטָּל לְפָנָיו. אֲבָל אִם הוּא מָקוֹם רָחוֹק, כְּגוֹן מַהֲלַךְ שֵׁנִי יָמִים, מֻתָּר עַד שֶׁיָּבוֹאוּ לְעִיר קְבוּרָתוֹ (רַבֵּנוּ יוֹנָה פ' מִי שֶׁמֵּתוֹ)\u0006.\nמִי שֶׁמֵּת בִּתְפִיסָה, וְלֹא נִתַּן לִקְבוּרָה, \u0010y13\u0011 לֹא חָל עַל הַקְּרוֹבִים אֲנִינוּת, וְגַם אֲבֵלוּת לֹא חָל עֲלֵיהֶם, \u0010y14\u0011 כֵּיוָן שֶׁלֹּא נִתְיָאֲשׁוּ מִלְּקָבְרוֹ. וְכֵן אִם קְרוֹבֵי הַמֵּת בִּתְפִיסָה, אֵין אֲנִינוּת חָל עֲלֵיהֶם. וְכֵן מִי שֶׁנֶּהֱרַג בַּדֶּרֶךְ אוֹ גְּרָרַתּוּ חַיָּה אוֹ שְׁטָפוֹ נָהָר, וְלֹא נִתְיָאֲשׁוּ מִלְּקָבְרוֹ, אֵין עַל הַקְּרוֹבִים לֹא דִּין אֲנִינוּת וְלֹא דִּין אֲבֵלוּת, וּמוֹנִים לוֹ שִׁבְעָה וּשְׁלֹשִׁים מִיּוֹם שֶׁנִּתְיָאֲשׁוּ מִלְּקָבְרוֹ.\nכָּל זְמַן שֶׁלֹּא נִקְבַּר הַמֵּת, אֵינוֹ חוֹלֵץ מִנְעָל וְסַנְדָּל, וְאֵינוֹ חַיָּב בַּעֲטִיפַת הָרֹאשׁ וּכְפִיַּת הַמִּטָּה, אֲבָל אָסוּר לֵישֵׁב אוֹ לִישַׁן עַל גַּבֵּי מִטָּה, אֲפִלּוּ כְּפוּיָה. \u0005הַגָּה: \u0010y15\u0011 וְכָל שֶׁכֵּן שֶׁאָסוּר בְּתַשְׁמִישׁ הַמִּטָּה (טוּר בְּשֵׁם הָרַמְבַּ\"ן וּבְשֵׁם הַתּוֹסָפוֹת וּבְמָרְדְּכַי פ\"ק דִּכְתֻבּוֹת בְּשֵׁם י\"א)\u0006. וְיֵשׁ אוֹמְרִים דְּאָסוּר בִּרְחִיצָה וְסִיכָה וְשִׂמְחָה וּשְׁאֵלַת שָׁלוֹם \u0010y16\u0011 וְתִסְפֹּרֶת וּבִמְלָאכָה \u0005(טוּר)\u0006, אֲבָל מֻתָּר לָצֵאת מִפֶּתַח בֵּיתוֹ. \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ד בְּשֵׁם סמ\"ק)\u0006.\nהַמְשַׁמֵּר אֶת הַמֵּת, אֲפִלּוּ שֶׁאֵינוֹ מֵתוֹ, \u0010y17\u0011 פָּטוּר מִקְּרִיאַת שְׁמַע, וּמִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה. הָיוּ שְׁנַיִם, זֶה מְשַׁמֵּר וְזֶה קוֹרֵא.",["\u0003מי שמת לו מת. \u0004אפילו אינו מוטל לפניו אלא מוטל עליו לקברו כל דין אונן עליו וכמו שיתבאר:","\u0003קודם קבורה. \u0004הוא אונן ואסור בכל הדברים שהאונן אסור בהן אבל לאחר קבורה אפי' באותו יום שמת אין דין אונן עליו כ\"ה בסמ\"ג ושאר פוסקים וכ\"פ הב\"ח:","\u0003אוכל בבית אחר. \u0004ואם אינו לפניו מותר לאכול בבית שהוא שם. פרישה וכ\"כ הב\"ח אוכל בבית אחר מיירי במוטל לפניו ואיכא משום לועג לרש אם אוכל בפניו וזה ודאי אסור אפי' בשבת ע\"כ:","\u0003אין בית לחבירו.\u0004 כגון שהוא שרוי בין העובדי כוכבים. מרדכי וב\"ח:","\u0003ואפילו הוא בעיר אחרת. \u0004משמע אפי' יש לו מי שיתעסקו עמו בעירו שמת דין אונן עליו והיינו כדעת הרא\"ש שחולק אר\"ת ומביאו הטור אבל הב\"ח פסק כר\"ת דקרובים שבעיר אחרת אין דין אונן עליהם אא\"כ אין למת קרובים המתאבלים עליו בעירו שמוטל עליהם לקברו אבל אם יש לו קרובים המוטל עליהם לטפל בעירו אין דין אונן על אותן הקרובים שבעיר אחרת ע\"ש:","\u0003אינו מיסב ואוכל. \u0004פירוש על השלחן או על המטה:","\u0003אם ירצה. \u0004דכיון שהוא מתכוין למצוה אם ירצה יאכל ואם ירצה לא יאכל שאינה חובה על האדם שיאכל בשר וישתה יין בשבת שהרי אמרו עשה שבתך חול ואל תצטרך לבריות הלכך בכל דבר שהוא מצוה חייבים לעשותו בשבת אבל זה רשות הוא אם ירצה יאכל בשר וישתה יין ואם לא ירצה יניח עכ\"ל תר\"י ומשמע דברכות ותפלה חייב בשבת ובי\"ט וכ\"נ ממה שסדר הרב האי אם ירצה קודם ומברך:","\u0003ואם צריך להחשיך כו'. \u0004עיין בא\"ח סימן ע\"א ותקמ\"ח סעיף ד':","\u0003וכ\"ש ביו\"ט שני של גליות שהוא בעצמו יכול לקברו. \u0004כמו שנתבאר באו\"ח סימן תצ\"ו ס\"ב ובמהרי\"ל כתב בשם מהר\"ש על מת שמת בשמיני עצרת לעת ערב שמותר להאבל לקדש בליל שמחת תורה שאחריו משום דאין אנינות ביו\"ט ע\"כ ועיין בדרישה שביאר טעמו דכיון דביו\"ט שני נוהגין איסור לתפור התכריכים ולחפור הקבר ושאר מלאכות וכמ\"ש באו\"ח סימן תקכ\"ו א\"כ אינו מוטל עליהם הרבה ולכן אין דין אנינות נוהג בלילה כי אם ביום ולפ\"ז ה\"ה בכל ליל יו\"ט שני שאינו נוהג בו דין אנינות אבל דוחק לחלק כן אלא נ\"ל דמהר\"ש לא ס\"ל כרא\"ש אלא ס\"ל כסמ\"ג דף רמ\"ח סוף ע\"א וכיש פוסקים דש\"ס דידן וחולק אירושל' ובכל ענין אין אבלות נוהג ביו\"ט שני אפי' ביום והכי משמע לישנא דמהר\"ש משום דאין אבילות ביו\"ט ולפ\"ז לדידן דקי\"ל כהרא\"ש א\"כ ה\"ה בלילה אסור לקדש):","\u0003י\"א כו'.\u0004 וכן כתב המחבר לעיל סימן רמ\"ב סעיף כ\"ז ולקמן סימן שע\"ד ס\"י בסתם:","\u0003שמתפלל שחרית שתים. \u0004וכמ\"ש בא\"ח סימן ק\"ח ס\"ב:","\u0003יבדיל אחר שיקבר המת. \u0004עד סוף יום שלישי בשבת כמ\"ש בא\"ח סימן רצ\"ט סעיף ו':","\u0003אפילו קודם כו'. \u0004אע\"פ שלא חל עדיין האבלות:","\u0003לא חל כו'. \u0004דלא קרינן מוטל לפניו כיון דלא ניתן לקבורה:","\u0003כיון שלא נתייאשו מלקברו. \u0004ואפי' המושל רוצה ממון הרבה מ\"מ כיון דבממון תלוי הדבר שאחר כך יתפייס בדמים מועטים מפני כך לא חלה האבילות עדיין אבל אם היתה הגזירה שלא ליתנו לקבורה מחמת שנאה ולא מחמת ממון אינה עשוי' ליבטל וחלה האבילות מיד כן מתבאר מדברי הרמב\"ן ושאר פוסקים:","\u0003וכל שכן שאסור בתה\"מ. \u0004דאפי' בשבת אסור כמ\"ש לעיל סעיף א':","\u0003ובמלאכה. \u0004ע\"ל סי' שמ\"ג וסי' שס\"א סעיף י\"א:","\u0003פטור מק\"ש כו'. \u0004דעוסק במצוה הוא ופטור משאר המצות:"],["\u0003אוכל בבית אחר. \u0004דהוה כלועג לרש כן פירש\"י בפרק מי שמתו והא דלא אסרו גם באחר מטעם זה לפי שדוקא בחייב קבורתו יש חשש במה שאינו עוסק בקבורתו ויושב לאכול בפני המת:","\u0003אינו מיסב ואוכל. \u0004פי' על השלחן או על המטה:","\u0003וכל שכן ביום טוב שני. \u0004נראה דהיינו ביום שהוא זמן קבורה אבל בלילה שלפניו דהיינו מוצאי יום טוב הראשון מותר כמו ביום ראשון וכן פסק במהרי\"ל הלכות יום טוב שהורה מהר\"ש על מת שמת בשמיני עצרת שמותר להאבל לעשות קידוש בערב ליל שמחת תורה משום דאין אנינות ביו\"ט ונראה שמזה הטעם פסק שאין דרך לקבור בלילה:","\u0003י\"א דתלמיד כו'. \u0004זה קאי על ימות החול:","\u0003כיון שבלילה לא היה חייב להתפלל. \u0004כתוב בדרישה מכאן היה נראה דה\"ה למתעסק בצרכי צבור וכיוצא בו בזמן התפלה שפטור מלהתפלל כמ\"ש הטור סימן צ\"ג ומתוך העסק עבר זמן אותה תפלה שגם כן א\"צ להשלימה בזמן תפלה שאחריה להתפלל שתים אחד לתשלומין כיון שג\"כ בזמן העסק היה פטור מתפלה כמו באבילות דהכא דמה לי אונס דאבילות או עסק מצוה. ולדעתי כ\"ש הוא דהא כשנתעסק בצרכי ציבור גם כן עבד עבודת הש\"י עכ\"ל. ותמה אני אם יצאו דברים אלו מפיו דהא כל שהוא אונס מקרי פטור מתפלה ובהדיא אמרו באונס דמתפלל אח\"כ שתים כמו שכתוב בא\"ח סימן ק\"ח. ותו דכתב בת\"ה סימן ה' במי שהיה טרוד אצל הפקיד מחמת חוב ולא היה יכול להיפטר אא\"כ בהפסד ממון ובתוך כך עבר זמן התפלה דמיקרי אונס אע\"ג דמחמת ממון הוא ומתפלל אח\"כ שתים הרי לך בהדיא אע\"ג דהיה פטור באותה שעה מתפלה מחמת טירדא דמיקרי אונס וה\"ה נמי פטור מחמת טירדא דמצוה וא\"כ נסתרה דעת בעל הדרישה בזה בפירושו והא דלמד דין זה מן אבילות דהכא אין הנדון דומה לראיה דדוקא אם הפטור בא מחמת דבר אחר דהיינו שהוא עצמו יכול להתפלל בלי שום מניעה אלא שהאבילות פוטרתו בזה אין תשלומין אח\"כ משא\"כ אם הפטור מחמת טירדא אין זה קרוי פטור מצד עצמו אלא אונס דהא באמת א\"א לו להתפלל) דזה נקרא פטור ולא אונס שאין לו פנאי והוה כמו חולה שאין יכול להתפלל ועל זה תקנו תשלומין דמיקרי פטור מחמת אונס כיון שא\"א לו כן נ\"ל ברור:","\u0003יבדיל אחר שיקבר. \u0004דזמן הבדלה עד סוף יום שלישי ובטור כתוב כל השבת כולה היינו מה ששייך לאותו שבת ועיין מ\"ש בסימן שצ\"ו דפסקי הש\"ע סותרים זה את זה. ובישוב הדברים כתב רש\"ל בתשובה סי' ע' דאם יש לאונן בן לימול ועדיין לא נקבר המת דמ\"מ ימול הבן בבית הכנסת קודם עלינו כמו בשאר פעמים. אח\"כ מצאתי בשם רמ\"א בכתב ידו שיש לקבור קודם דאל\"כ הוי אונן וא\"א לו לברך להכניסו בברית דאונן פטור מכל המצות ונראה שיש לחוש לזה אם אפשר לקברו קודם שיוצאין מבית הכנסת בשחרית דאין דוחין זריזות המצוה אבל אם א\"א יברך הסנדק וימול אותו בשחרית דהא איתא בסימן ש\"ס מת ומילה מילה קודמת:"]],["\u0003הלכות אבילות\u0004\nמִי שֶׁהֵכִין כָּל צָרְכֵי \u0010y0\u0011 חֻפָּתוֹ, שֶׁאָפָה פִּתּוֹ וְטָבַח טִבְחוֹ וּמָזַג יֵינוֹ, וּמֵת אָבִיו שֶׁל חָתָן, וְהוּא בְּמָקוֹם שֶׁאֵינוֹ מָצוּי לִמְכֹּר, וְאִם תִּדָּחֶה הַחֻפָּה יַפְסִיד מַה שֶּׁהֵכִין; אוֹ שֶׁמֵּתָה אִמָּהּ שֶׁל כַּלָּה, וְאִכָּא תַּמְרוּקֵי נָשִׁים וְקִשּׁוּטִין שֶׁאֵינָם מִתְקַיְּמִים, \u0005מֵאַחַר שֶׁאֵין לָהֶם מִי שֶׁיִּטְרַח בַּעֲבוּרָם בְּפַעַם אַחֶרֶת (כָּךְ מַשְׁמָע \u0010y1\u0011 \u0010c0\u0011 מִגְּמָרָא)\u0006, מַכְנִיסִין \u0010c1\u0011 אֶת הַמֵּת לְחֶדֶר, וְאֶת הֶחָתָן וְאֶת הַכַּלָּה \u0010c2\u0011 לַחֻפָּה, וּבוֹעֵל בְּעִילַת מִצְוָה \u0010y2\u0011 וּפוֹרֵשׁ, וְכֵיוָן שֶׁחָלָה עָלָיו הַחֻפָּה הַוְיָא לְדִידֵיהּ כְּרֶגֶל, \u0010y3\u0011 וְנוֹהֵג שִׁבְעַת יְמֵי הַמִּשְׁתֶּה וְאַחַר כָּךְ נוֹהֵג שִׁבְעַת יְמֵי אֲבֵלוּת. וְכָל שִׁבְעַת יְמֵי הַמִּשְׁתֶּה נוֹהֵג בָּהֶם דְּבָרִים \u0010y4\u0011 שֶׁבְּצִנְעָא, וְאָסוּר בְּתַשְׁמִישׁ הַמִּטָּה, הִלְכָּךְ כָּל ז' יְמֵי הַמִּשְׁתֶּה וְז' יְמֵי הָאֵבֶל \u0010y5\u0011 הוּא \u0010y6\u0011 יָשֵׁן בֵּין הָאֲנָשִׁים, וְהִיא יְשֵׁנָה בֵּין הַנָּשִׁים. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁאֲסוּרָה לְיַחֵד עִמּוֹ \u0010c3\u0011 בַּיּוֹם כְּמוֹ בַּלַּיְלָה, וְאֵין צָרִיךְ לִהְיוֹת לָהֶם שְׁתֵּי שְׁמִירוֹת רַק הוּא בֵּין הָאֲנָשִׁים אוֹ הִיא בֵּין הַנָּשִׁים (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. וְאִם אֵינָם יְשֵׁנִים בְּחֶדֶר אֶחָד, אֵין צְרִיכִין שִׁמּוּר כְּלָל \u0005(כ\"כ הָרַשְׁבָּ\"א בְּכַלָּה שֶׁפֵּרְסָה וְכו')\u0006. וְיֵשׁ אוֹמְרִים דְּבַלַּיְלָה צָרִיךְ שְׁתֵּי שְׁמִירוֹת, וּבַיּוֹם מֻתָּר לְהִתְיַחֵד עִמָּהּ \u0005(טוּר בְּשֵׁם הָרַאֲבַ\"ד)\u0006. \u0010y7\u0011 וְהַמִּנְהָג \u0010y8\u0011 לִקַּח קָטָן אֵצֶל הֶחָתָן וּקְטַנָּה אֵצֶל הַכַּלָּה, וְאֵין מִתְיַחֲדִין בַּיּוֹם בְּלֹא קָטָן אוֹ קְטַנָּה. וּלְעִנְיַן שְׁלֹשִׁים, \u0010y9\u0011 אֵינוֹ מוֹנֶה אֶלָּא מִז' יְמֵי אֲבֵלוּת וָאֵילָךְ, \u0010y10\u0011 \u0010c4\u0011 וְכָל שִׁבְעַת יְמֵי הַחֻפָּה מֻתָּר בְּגִהוּץ וְתִסְפֹּרֶת. וְאִם אֵין לוֹ פְּסֵידָא, כְּגוֹן בְּמָקוֹם שֶׁמָּצוּי לִמְכֹּר מַה שֶּׁהֵכִין, אוֹ אֲפִלּוּ אִית לֵיהּ פְּסֵידָא, וּמֵתָה אִמּוֹ שֶׁל חָתָן אוֹ אָבִיהָ שֶׁל כַּלָּה אוֹ אֶחָד מִשְּׁאָר קְרוֹבֵיהֶם, שֶׁנִּשְׁאַר מִי שֶׁיָּכִין לָהֶם לְפַעַם אַחֶרֶת, לֹא הִתִּירוּ לִדְחוֹת הָאֲבֵלוּת אֶלָּא קוֹבֵר אוֹתוֹ מִיָּד, וְנוֹהֵג שִׁבְעַת יְמֵי אֲבֵלוּת, וְאַחַר כָּךְ מַכְנִיסִין אֶת הֶחָתָן וְאֶת הַכַּלָּה לַחֻפָּה מִיָּד, וְנוֹהֵג שִׁבְעַת יְמֵי הַמִּשְׁתֶּה.",["\u0003שאפה פתו וטבח כו'. \u0004כתב הב\"ח דוקא שהכין כל צרכי חופתו אבל אם לא הכין הכל כגון שאפה פתו וטבח טבחו ולא מזג יינו או איפכא דהשתא בע\"כ צריך להשתדל להכין לו יין ידחה החופה וישתדל להכין פעם אחרת גם הפת והבשר עכ\"ל ואין דבריו מוכרחין דהא עכ\"פ אם לא יעשה החופה מיד יפסיד מה שהכין כבר ושוב אין מכין להם מה שכבר נפסד דנהי דצריך להשתדל להכין יין היאך ישתדל להכין פת ובשר וראיה לדבר שברמזים פ\"ק דכתובות לא כתב אלא מי שהיה טבחו טבוח ויינו מזוג ומת אביו של חתן כו' ולא כתב פתו אפויה וכן מ\"ש הב\"ח וכצ\"ל דהכינו כל התכשיטין כו' אינו מוכרח מטעמא דאמרן כיון דבתכשיטים נמי איכא הפסד כמ\"ש הר\"ן והמחבר כגון דאיכא תמרוקי הנשים שיתקלקלו:","\u0003מכניסין את המת לחדר כו'. \u0004דאם יקברוהו יחול עליו אבילות בסתימת הגולל ושוב לא יוכל לכנוס לחופה עד שיעבור האבילות ואע\"ג דאונן נמי אסור בתשמיש המטה וכדלעיל סי' שמ\"א מ\"מ הכא הקילו והתירו תשמיש לאונן ולא לאבל ומשום קילותא דקמי' סתימת הגולל לא אתי לזלזולי באבילו' דעיקר ז' דלעולם ימי אבילות מסתימת הגולל ואילך חמורים הם ממי שמתו מוטל לפניו ומקילתא לחמירתא לא גמירי אינשי כ\"כ הרמב\"ן בסת\"ה ריש דף כ\"ד:","\u0003ופורש. \u0004ואסור לבעול שנית אפילו קודם שנקבר המת משום דאונן אסור בתשמיש. רמב\"ן שם:","\u0003ונוהג ז' ימי המשתה כו'.\u0004 אפי' למ\"ד אבילות יום ראשון דאורייתא טעמא דנוהג ימי המשתה ברישא משום דב\"ד יכולים לעקור דבר מן התורה בשב ואל תעשה ולפ\"ז אינו ראוי להתעסק בדברים של שמחה כל אותו היום אלא שאינו חייב לעשות מעשה דאבילות והיינו שב ואל תעשה ביום הראשון עכ\"ל העט\"ז והוא מדברי הר\"ן שהביא הב\"י ונראה דלדידן דקי\"ל לקמן סימן שצ\"ט ס\"ס י\"ג יום ראשון אינו אלא דרבנן מותר להתעסק בדברי' של שמחה ומטעם זה השמיטו המחבר והרב דברי הר\"ן אלו וגם העט\"ז נראה שלא כתבו אלא למ\"ד יום ראשון דאוריי' תדע דהא קי\"ל דאפי' גיהוץ ותספורת מותר כל ז' כמ\"ש גם העט\"ז גופי' ומשמע אפי' ביום הא' והרי אין לך מעשה גדול מזה אלא ודאי כדפי':","\u0003ואסור בתשמיש המטה. \u0004וכתב הטור בשם הראב\"ד דדוקא בתשמיש וביחוד אסור אבל במיני פרישות כמזיגת הכוס והצעת המטה והרחצת פניו ידיו ורגליו מות' ולא עוד אלא אפי' בחיבוק ונישוק יש להתיר וכ\"נ מדברי הרא\"ש שבפרק אלו מגלחין שהביא הטור דמודה בזה להראב\"ד וכ\"נ דעת המחבר שלא כתב לאסור אלא תשמיש המטה מיהו תימא דבריש כתובות כתב הרא\"ש וכן ברמזים שם דכיון דהאי אבילות קילא ליה מנדה אינה מוזגת לו הכוס ואינה מצעת לו המטה ואינה מרחצת לו פניו ידיו ורגליו (ודוחק לומר דבפרק אלו מגלחין מיירי דוקא ביום ועוד דמל' הרמזים פרק ואלו מגלחין סי' פ\"ג אבל שאר פרישות כגון הצעת המטה וכיוצא בה שרי כו' משמע דלעולם שרי) ולענין דינא גם דעת ר' ירוחם נתיב כ\"ב ח\"ב דאסור וכתב וזה לשונו וכתב הראב\"ד אע\"ג דהוא ישן בין האנשים והיא בין הנשים מותרת במזיגת הכוס ובהצעת המטה ותמהו עליו וכ' מורי הר\"ר אברהם בן אסמעאל נר\"ו כי מאחר שאסור לישן עמה ביחוד כ\"ש שאסור לה למזוג כוס ולהציע לו המטה ולרחוץ פניו ידיו ורגליו עכ\"ל וכן מוכח בש\"ס ריש כתובות דף ד' דהא בנדה יחוד שרי כשבעל ואפ\"ה מזיגת הכוס אסור מכ\"ש אבילות דהכא דיחוד אסור דמזיגה יהא אסור וליכא למימר דלענין נדה יותר מסתבר לאסור מזיגת הכוס כו' ולענין אבילות יותר מסתבר לאסור יחוד דא\"כ מאי פריך ש\"ס למימרא דאבילות קילא ליה מנדה האמר ר\"י ב\"ח כל מלאכות שהאשה עושה לבעלה כו' וגבי אבילות תניא כו' ואפשר דעת הראב\"ד כדקמסיק אבילות דהכא כיון דאקילו ביה רבנן אתי לזלזולי ביה ומן הדין היה מותר אבילות דהכא אף ביחוד רק דחכמים אסרו ליה יחוד כי היכי דלא לזלזל ביה א\"כ די כשעשו לו היכר בין אבילות דהכא ואסרו לו יחוד כי היכי דלא לזלזל ומה לנו לגזור עוד ולאסור גם מיני פרישות (שוב מצאתי במהרש\"א ריש כתובות שהניח דברי הראב\"ד בצ\"ע):","\u0003והוא ישן בין האנשים כו'. \u0004כ' העט\"ז אע\"ג דשאר אבל מותר להתיחד שאני הכא שאשה חדשה היא לו כו' ולא דק דלפי זה אפילו אירע בו אבילות שבעה תוך ז' ימי המשתה אסור להתיחד והא ליתא כמבואר לקמן סי' שפ\"ג והאמת שלא עיין בש\"ס ריש פ\"ק דכתובות (דף ד' ע\"ב) מוכח התם מכל הסוגיא דאין לחלק בין אשתו ישנה לחדשה (ועיין בתו' ד\"ה ומי שאני ודוק) אלא הכא היינו טעמא כדאמר רב אשי התם וכדאיתא בפוסקים דהא אבילות דהכא קילא ליה שהרי מת לו מת קודם שחלו ז' ימי המשתה והתירו לו חכמים להכניס את המת לחדר ואת החתן וכלה לחופה כדי לדחות האבילות מעליו ואיכא למיחש דלמא אתי לזלזולי ביה:","\u0003ישן בין האנשים כו'. \u0004כתב הב\"ח דמיירי בבעולה אבל בבתולה מותר לייחד דנהי דאבילות קילא מ\"מ כיון שבעל אסורה לו משום דם נדות שחמיר וכן נתבאר לעיל סי' קצ\"ב ס\"ק י\"ג:","\u0003והמנהג ליקח כו'. \u0004ואע\"פ שאבילות בחתן שהכין צרכי חופתו דבר שאינו מצוי הוא ובדבר שאינו מצוי לא שייך בו מנהג וכדלעיל סי' ק\"כ ס\"ק ג' מ\"מ כיון דכן המנהג בפירסה כלתו נדה וכדלעיל סי' קצ\"ב ס\"ד ה\"ה הכא דחד דינא אית ליה בזה:","\u0003קטן כו'. \u0004כתב הב\"ח מיהו צריך שיהו יודעים טעם ביאה ושאינה מוסרת עצמה לביאה כמו שמבואר באבן העזר סי' כ\"ב:","\u0003אינו מונה אלא מז' ימי האבילות כו'. \u0004ואע\"ג דברגל קי\"ל לקמן סי' שצ\"ט דעולה לו למנין שאני סתם דנהג בו מצות ל' משא\"כ הכא דמותר אפי' בגיהוץ ותספורת. רמב\"ן ושאר פוסקים. ודין חתן שאירעו אבל ברגל אי ז' ימי משתה עולים לו כתבתי לקמן סי שצ\"ט ע\"ש:","\u0003וכל שבעת ימי המשתה מותר בגיהוץ כו'. \u0004והב\"ח כ' דנראה לאסור בגיהוץ ותספורת דאינו מפורסם דמשום אבל הוא שעושה כן דשמא לפי שאין לו בגדים מגוהצים ואין הספר מזומן לספר אותו והוי דברים שבצנעה כו' ותימה היאך הפריז מדותיו לחלוק על הרמב\"ן וטור בסברא בעלמא וכ\"ד הרא\"ש ורבינו ירוחם נתיב נ\"ב ח\"ב וגם דעת המחבר וכ\"כ בתשו' משאת בנימין סי\"ט אלא ה\"ט דחתן כיון דדמי למלך ביפיו תחזינה עיניך א\"כ כל כמה דלא מספר ומגהץ מפורסם הוא דמשום אבל הוא עושה כן דהו\"ל להשתדל בגדים מגוהצין וספר לספר דעליה רמיא למיגהץ ולספר:"],["\u0003מכניסין את המת. \u0004מעשה אירע בבתולה שניסת בליל שבת ועדיין לא נבעלה וביום השבת מתה אמה של הכלה ונשאלתי כדת מה לעשות באבילות דידה כי קצת לומדים רצו לדמות דין זה לכאן ואני אמרתי שטעו דע\"כ לא התירו כאן לבעול בעילת מצוה אלא משום פסידא דסעודה שהכינו כבר ויצטרכו להוצאה חדשה אם ידחו עשיית החופה עד אחר האבילות וכמו שכ' הרא\"ש פ\"ק דכתובות דלא התירו חופה וביאה לאונן אלא משום פסידא ע\"כ אמר מכניסין כו' כדי שלא יחול האבילות עליו עד שיסתום הגולל אבל כאן שכבר נעשית החופה רק שלא נבעלה עדיין בודאי אם ידחו הבעילה אין כאן פסידא דסעודה דמאי דהוה הוה שהרי לא יעשו סעודה שנית ע\"כ אסור לבעול דהא תשמיש המטה אסו' גם קודם הקבור' כמו שכתב הטור ושלחן ערוך בסי' שקודם לזה וראיה עוד מדברי הטור וש\"ע סוף סימן שפ\"ג שכתב אם מת לחתן מת אחר החופה שאסור אפי' ביחוד אם לא בעל. אך נ\"ל לענין אבילות דכלה זאת שתתחיל מיד ביום א' ותמנה יום ז' ואח\"כ תיבעל דאין לומר) כיון שחלה עליה החופה ה\"ל כרגל וממילא לא תתחיל באבילות עד שיכלו ז' ימי החופה כמו מת לו מת ברגל זה אינו דז' ימי המשתה תקינו רבנן לשמח חתן וכלה והם לא ניחא להו בהאי תקנתא דאם תנהוג תחלה ז' ימי המשתה והיא אסורה לבעלה תצטרך להמתין ז' ימי אבילות ותיאסר י\"ד יום ואפי' בממון מצינו בכמה דוכתי שיוכל אינש לומר לא ניחא לי בהאי תקנתא כדאיתא ריש ב\"ק ובפרק הכותב לענין איני ניזונית ואיני עושה כ\"ש כה\"ג במידי דקיום מצוה שיש להקדים כל מה שאפשר ועוד ראיה מפרק שלוח הקן (דף קמ\"א) דבעינן תשלח יתירה לרבות ציפורי מצורע דלא תימא דאתי עשה דטהרת מצורע ודחי עשה דשלח משום דעשה דטהרת מצורע אתי להתיר תשמיש המטה קמ\"ל תשלח יתירה דלא ידחה ש\"מ דמשום היתר תשמיש הייתי אומר דדחי את עשה שכנגדו אי לאו קרא יתירה ק\"ו בבעילת מצוה דיש לדחות מפניה מידי דמדרבנן דהיינו ז' ימי משתה. על כן פסקתי שתתחיל למנות תכף אחר השבת ז' ימי אבלות ואחר תיבעל בעילת מצוה כנלע\"ד נכון וברור:\n\u0003אחר \u0004הדברים דלעיל ראיתי בספר הדרישה בזה הסי' במה שכתב הטור וכיון שחלה עליו החופה ה\"ל לדידיה כרגל כתב וז\"ל לפי מה שכתבתי לקמן בסימן שס\"א והבאתי ראיה מגמרא ופוסקים דמה שמכסין ראש הכלה בשחרית מיקרי חופה) נ\"ל ג\"כ לסמוך על זה דאם חלילה אירע אבילות לחתן או לכלה אחר שכיסו ראש הכלה דאין צריכין לפסוק שבעת ימי המשתה אלא קוברין המת מיד ונדחו שבעת ימי אבילות עד אחר שבעת ימי המשתה כדין אי מת אביו של חתן כאן ואפשר לחלק דדוקא בימיהם דהיו מקדשין מתחלה בשעת שידוכין מ\"ה מתחלת החופה בשחרית דשייך ייחוד אחר שנתארסה כבר משא\"כ בזמנינו מיהו נראה דגם בימי המרדכי לא היו מקדשין רק כמו בזמנינו ואפי' הכי קרי חופה משעת כיסוי הכלה עכ\"ל תמוהין לי דברי הרב טובא חדא במאי שחושב כיסוי ההינומא לחופה דהא כתב רמ\"א באבן עזר סי' נ\"ד דהמנהג בינינו לקרות החופה דוקא היריעות על כלונסות כו' דזה החופה הנוהגת עכשיו כו' והרבה פעמים אנו רואים שמסלקין נדוניית החתן אחר כיסוי ההינומא ואם אין מסלקין אותו כראוי החתן פונה לדרכו ואין שם עדיין שום חיוב עליו לישאנה מחמת כיסוי ההינומא והיאך נאמר להקל שכבר חל עליו רגל משעת הכיסוי במקום דליכא פסידא דהיינו שהוא אבל שלא על אביו דאלו על אביו לא היה לו לבעל הדרישה לבקש היתר מחמת שכבר חל עליו חופה דבזה אפי' קודם החופה התירו לעשות החופה ואפי' לבעול בעילת מצוה כל זמן שלא נקבר המת. ובר מן דין קשה טובא ממה שכתב הרא\"ש פרק קמא דכתובות שתחילה העתיק דברי הרי\"ף שכתב ושמע מיניה היכא דליכא פסידא דאינו נוהג שבעת ימי המשתה ברישא וכ' הרא\"ש שמלשון זה משמע דאפי' בדליכא פסידא מכניסין המת לחדר ואת החתן ואת הכלה לחופה ובועל בעילת מצוה ופורש וקובר את מתו ונוהג שבעת ימי אבילות ואח\"כ שבעת ימי משתה דאין חילוק בין איכא פסידא או ליכא פסידא אלא לענין הנהגת שבעת ימי אבילות ברישא אבל בשניהם בועל בעילת מצוה תחילה ולא מסתבר כלל דמה תועלת יש במהירות החופה ויבזו המת ויפסיקו אבילות בין החופה ובין שבעת ימי המשתה ולא התירו חופה וביאה לאונן אלא באביו של חתן או אמה של כלה וגם איכא פסידא אז התירו חופה לאונן ולהקדים ימי המשתה לאבילות אבל כשמקדים האבילות למשתה גם אחר החופה כו' עכ\"ל הרי מבואר דלהרי\"ף שבהיתר מכניס לחופה גמורה ובועל בעילה גמורה ואפ\"ה אין חל עליו הרגל שלו לעשות ימי המשתה אלא צריך להמתין ולהתחיל באבילות תחלה ואפי' הרא\"ש שחולק עליו הוא מטעם שלא יפסיק באבילות בין חופה לימי המשתה אבל לא עלה על דעתו שיעשה גם ז' ימי המשתה תיכף כיון שחל עליו רגל שלו בהכנסת חופה והיינו מטעם המפורש בגמרא דלא התירו לעשות ימי המשתה אלא כשיש פסידא דהיינו שמת אביו של חתן או אמה של כלה אבל בלא פסידא אסור לעשות ימי המשתה כלל ועיקר והוא דבר פשוט דלא התירו כאן לעשות ימי המשתה אלא במקום פסידא דהיינו במת אביו של חתן אזי התירו שני דברים דהיינו בעילת מצוה כל זמן שהוא אונן ודחיית אבילות אחר הקבורה עד אחר ימי המשתה אבל לא באבילות אחר ויותר מזה קשה ממה שכ' הר\"ן פ\"ק דכתובות דאע\"פ שחל עליו החופה והוה כרגל מ\"מ לא הקילו אלא בשב ואל תעשה אבילות אבל אסור לו להתעסק בדברים של שמחה כל אותו יום של מיתה וקבורה למאן דאמר יום ראשון דאורייתא וא\"כ היכי יעשה החופה ביום שנעשה אבל מטעם שכיסו הכלה ביום שנעשה אבל והרי אין לך מעשה שמחה גדולה מזה ואין לומר שיש לסמוך על מאן דאמר אין שום אבילות דאורייתא כדאיתא סימן שצ\"ח דהא לא הכריע ואין שייך כאן לומר הלכה כדברי המיקל באבל דהא בב\"י סי' שצ\"ט פסק כמאן דאמר דאוריי' ותו דכבר כ' הר\"ן בתשו' הביאו ב\"י סי' רכ\"ח דף רס\"ח דבכל מילי דמספקא לן אי הוה מן התורה או מדרבנן מקרי ספק דאוריי' ולחומרא ותו דהא אונן ביום ראשון דאורייתא אפי' להרא\"ש כמ\"ש הטור סי' שצ\"א ובפרק טבול יום (זבחים דף ק') אמרינן אפי' נקבר הוה אונן ביום המיתה עד הערב לאכילת קדשים ומשום הכי כתב הרא\"ש בפרק אלו מגלחין דרבן גמליאל לא רצה לרחוץ ביום המיתה אע\"ג דהוה איסטניס כיון דיום המיתה דאורייתא ועל כן נראה לע\"ד דבכל אבילות שהוא שלא על אביו של חתן או אמה של כלה יש לדחות עשיית החופה עד אחר שבעת ימי אבילות ואע\"פ שכבר כיסוי הכלה בהינומא וירויחו בזה הקדמת בעילת מצוה שבעת ימים וכפי שכתבתי למעלה כן נראה לע\"ד נכון:","\u0003את המת לחדר. \u0004דכל זמן שלא נקבר הוה אונן והתירו איסור תשמיש לאונן בזה מחמת פסידא דאית ליה ואין לו אב להכין אחר אבל אחר שנקבר המת מתחיל האבילות ולא התירו לו כאן איסור אבילות אלא דחו את אבילות עד אחר ימי המשתה והכל מחמת פסידא:","\u0003ובועל בעילת מצוה ופורש. \u0004אע\"ג דבכל בעילת מצוה פורש בזמן הזה מכל מקום כאן מיירי בזמן התלמוד שלא היו פורשין אחר בעילת מצוה מ\"מ כאן באבילות צריך לפרוש גם מה שכתב הטור לדעת הראב\"ד שמותר בחיבוק ונישוק מיירי ג\"כ מזמן התלמוד ובזה ניחא נמי מה שיש להקשות על מ\"ש שצריך החתן שמירה אחר שבעל בעילת מצוה והלא אמרו בגמרא דדוקא באיסור שהוא אבילות החמירו עליו כאן שצריך שמירה אע\"פ שבעל דלא יטעה להקל עוד כיון שהקילו בו רבנן לענין היתר תשמיש באונן אבל ביש איסור נדה עליו אין צריך שמירה אם בעל כבר שבודאי לא נחשד על הנדה וא\"כ לדידן שפורשין אחר בעילות של מצוה כמו בשאר נשים למה הצריך שמירה בזמנינו די\"ל דכיון דבזמן התלמוד היה חיוב בשמירה אין לנו להקל בזה דאין בנו כח אלא להחמיר ולא להקל כן נ\"ל:","\u0003ביום כמו בלילה. \u0004בטור כתוב בשם הרא\"ש דלמראית עין היצר מתגבר. רבים מקשים מהא דאמרינן גבי ליל יוה\"כ דיש נוהגין להדליק נר כדי שלא ישמש מטתו ושבוש הוא דהתם לא חיישינן אלא שמא ישכח וישמש ע\"כ הוה היכר ע\"י נר מה שאין כן כאן דחיישינן שמא יעבור במזיד ומראית עינו יגרום לו זה:","\u0003וכל שבעת ימי החופה מותר בגיהוץ כו'. \u0004זהו טעם על מה שאמר תחלה שאין מונה שלשים אלא מן אחר הרגל דהיינו שבשאר רגל מונים שלשים מימי הרגל כיון שאסור גם ברגל בגיהוץ ותספורת מחמת אבילות וכאן מותר בגיהוץ ותספורת דכתיב מלך ביפיו תחזינה עיניך:"]],["מֵת בָּעִיר, כָּל בְּנֵי הָעִיר אֲסוּרִין בִּמְלָאכָה, \u0010y0\u0011 שֶׁכָּל הָרוֹאֶה מֵת וְאֵינוֹ מְלַוֵּהוּ עַד שֶׁיְּהֵא לוֹ כָּל צָרְכּוֹ, בַּר נִדּוּי הוּא. וְאִם יֵשׁ חֲבוּרוֹת בָּעִיר, שֶׁכָּל אַחַת מִתְעַסֶקֶת בְּמֵתִים בְּיוֹמָהּ, מֻתָּר בְּיוֹם שֶׁאֵינָהּ יוֹמָהּ. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁלֹּא בִּשְׁעַת הוֹצָאָתוֹ, אֲבָל בִּשְׁעַת הוֹצָאָתוֹ הַכֹּל בְּטֵלִים, \u0010y1\u0011 כְּדִלְקַמָּן.\nבִּכְפָר קָטָן, אֵין שׁוֹאֲלִים שָׁלוֹם זֶה לָזֶה כְּשֶׁהַמֵּת בָּעִיר. \u0005הַגָּה: \u0010y2\u0011 וְכָל שֶׁכֵּן שֶׁאֵין שׁוֹאֲלִים בְּשָׁלוֹם כְּשֶׁיֵּשׁ מֵת עַל בֵּית הַקְּבָרוֹת. (כִּתְבֵי מהר\"ר אִסֶרְלָן סִימָן כ\"ה בְּשֵׁם סֵפֶר חֲסִידִים)\u0006, אֲבָל כְּשֶׁאֵין מֵת שָׁם, שׁוֹאֲלִין. בְּרִחוּק אַרְבַּע אַמּוֹת מִן הַקֶּבֶר \u0005(בתוס' דְּאִלְפָס פֶּרֶק ג' דמ\"ק וְהַכֹּל בּוֹ בְּשֵׁם הר\"מ)\u0006.",["\u0003שכל הרואה המת כו'. \u0004נ\"ל טעות וצ\"ל וכל הרואה כו' ועיין בטור:","\u0003כדלקמן. \u0004סי' שס\"ה ס\"ב:","\u0003וכ\"ש שאין שואלין בשלום בבית הקברות כשיש מת שם. \u0004אפי' בעיר גדולה:"],[]],["מִצְוָה גְּדוֹלָה לְהַסְפִּיד עַל הַמֵּת כָּרָאוּי. וּמִצְוָתוֹ שֶׁיָּרִים קוֹלוֹ לוֹמַר עָלָיו דְּבָרִים הַמְּשַׁבְּרִים אֶת הַלֵּב, \u0010y0\u0011 כְּדֵי לְהַרְבּוֹת בְּכִיָּה וּלְהַזְכִּיר שִׁבְחוֹ. וְאָסוּר לְהַפְלִיג בְּשִׁבְחוֹ יוֹתֵר מִדַּאי, אֶלָּא מַזְכִּירִין מִדּוֹת טוֹבוֹת שֶׁבּוֹ, \u0010c0\u0011 וּמוֹסִיפִין בָּהֶם קְצָת, רַק שֶׁלֹּא יַפְלִיג. וְאִם לֹא הָיוּ בּוֹ מִדּוֹת טוֹבוֹת כְּלָל, לֹא יַזְכִּיר עָלָיו. וְחָכָם וְחָסִיד, מַזְכִּירִים לָהֶם חָכְמָתָם וַחֲסִידוּתָם. וְכָל הַמַּזְכִּיר עַל מִי שֶׁלֹּא הָיָה בּוֹ כְּלָל, אוֹ שֶׁמּוֹסִיף לְהַפְלִיג יוֹתֵר מִדַּאי עַל מַה שֶּׁהָיָה בּוֹ, גּוֹרֵם רָעָה לְעַצְמוֹ וְלַמֵּת.\nכְּשֵׁם שֶׁמַּסְפִּידִין עַל הָאֲנָשִׁים כָּךְ מַסְפִּידִין עַל הַנָּשִׁים כָּרָאוּי לָהֶן, \u0005וְנִסְפָּדוֹת בֵּין הָאֲנָשִׁים וַחֲכָמִים (טוּר)\u0006.\nבְּמָקוֹם שֶׁרְגִילִין לְהַשְׂכִּיר מְקוֹנְנוֹת לְהַסְפִּיד, חַיָּב לְהַשְׂכִּיר מְקוֹנְנוֹת לְהַסְפִּיד עַל אִשְׁתּוֹ. וְאִם לֹא רָצָה, בָּא אָבִיהָ וּמַשְׂכִּיר, וּמוֹצִיא מִמֶּנּוּ בְּעַל כָּרְחוֹ.\nקָטָן, בֶּן כַּמָּה שָׁנִים יִהְיֶה כְּשֶׁמַּסְפִּידִין עָלָיו, \u0010y1\u0011 \u0010c1\u0011 עֲנִיִּים בְּנֵי חֲמִשָּׁה, עֲשִׁירִים בְּנֵי שִׁשָּׁה; בְּנֵי זְקֵנִים כִּבְנֵי עֲנִיִּים. אֲבָל צִדּוּק הַדִּין וְקַדִּישׁ, אוֹמְרִים עַל תִּינוֹק מִשֶּׁעָבְרוּ עָלָיו שְׁלֹשִׁים יוֹם. \u0005הַגָּה: \u0010y2\u0011 וְאֵין נוֹהֲגִים כֵּן, אֶלָּא עַד שֶׁיִּהְיֶה בֶּן י\"ב חֹדֶשׁ שֶׁיּוֹצֵא בְּמִטָּה, כְּדִלְקַמָּן סִימָן שנ\"ג סָעִיף ה'.\u0006\nבְּנֵי עֲשִׁירִים וּבְנֵי חֲכָמִים, \u0010y3\u0011 מוֹסִיפִין קְצָת עַל שֶׁבַח מַעֲשֵׂיהֶם.\nתִּינוֹק שֶׁיּוֹדֵעַ לִשָּׂא וְלִתֵּן, מַסְפִּידִין אוֹתוֹ בְּמַעֲשֵׂה עַצְמוֹ; וְאִם אֵין לוֹ מַעֲשִׂים, מַסְפִּידִין אוֹתוֹ בְּמַעֲשֵׂה אֲבוֹתָיו; וְאִם אֵין לָהֶם מַעֲשִׂים, מַסְפִּידִין לָהֶם בְּמַעֲשֵׂה קְרוֹבָיו.\nהַכַּלָּה, מַסְפִּידִין אוֹתָהּ בֵּין בְּמַעֲשֵׂה אָבִיהָ \u0010y4\u0011 בֵּין בְּמַעֲשֵׂה בַּעֲלָהּ. \u0010c2\u0011\nהַמְּחֻתָּךְ וְהַמְסֹרָס וְהַנְּפָלִים, וּבֶן ח', וְכֵן בֶּן ט' מֵת, וְהָעוֹבֵד כּוֹכָבִים וְהָעֲבָדִים, \u0010y5\u0011 אֵין מִתְעַסְקִין לְהֶסְפֵּד וּלְלַוּוֹת. \u0010y6\u0011\nיוֹרְשִׁים שֶׁאֵינָם רוֹצִים לִפְרֹעַ שְׂכַר הַסַפְדָן, \u0010y7\u0011 \u0010c3\u0011 מוֹצִיאִים מֵהֶם בְּעַל כֹּרְחָם.\nמִי שֶׁצִּוָּה שֶׁלּא יִסְפְּדוּהוּ, שׁוֹמְעִין לוֹ. \u0005אֲבָל אִם צִוָּה שֶׁלּא לִנְהֹג עָלָיו ז' וּגְזֵרַת שְׁלֹשִׁים, \u0010y8\u0011 אֵין שׁוֹמְעִין לוֹ (מהרי\"ו סִימָן ד')\u0006.\nאִסוּר תְּלִישַׁת שֵׂעָר, וְכֵן שְׂרִיטָה עַל מֵת, בְּסִימָן ק\"פ.\nהָעָם הָעוֹסְקִים בַּהֶסְפֵּד, כָּל זְמַן שֶׁהַמֵּת מֻטָּל לִפְנֵיהֶם, נִשְׁמָטִים אֶחָד אֶחָד וְקוֹרִין אֶת שְׁמַע וּמִתְפַּלְּלִין. אֵין הַמֵּת מֻטָּל לִפְנֵיהֶם, הֵם יוֹשְׁבִים וְקוֹרִים, וְהָאוֹנֵן יוֹשֵׁב וְדוֹמֵם; הֵם עוֹמְדִים וּמִתְפַּלְּלִים, וְהוּא מַצְדִּיק עָלָיו אֶת הַדִּין וְאוֹמֵר: יְהִי רָצוֹן מִלְּפָנֶיךָ ה' אֱלֹהַי שֶׁתִּגְדֹּר פִּרְצוֹתֵינוּ וּפִרְצוֹת עַמְּךָ בֵּית יִשְׂרָאֵל. \u0005[בְּרַחֲמִים]\u0006\nלְאַחַר קְבוּרָה מַפְסִיקִין הַהֶסְפֵּד, בֵּין בִּקְרִיאַת שְׁמַע בֵּין בִּתְפִלָּה. \u0005וְעַיֵּן בְּאֹרַח חַיִּים סִימָן ע\"ב.\u0006 \u0010y9\u0011\nאֵין עוֹשִׂין שְׁנֵי הֶסְפֵּדִים בְּעִיר אַחַת, אֶלָּא אִם כֵּן יֵשׁ שָׁם רֹב עַם לְחַלֵּק לִשְׁנַיִם וְיִהְיֶה בְּכָל הֶסְפֵּד עַם כְּדֵי צָרְכּוֹ.\nאֵין עוֹשִׂים שְׁנֵי הֶסְפֵּדִים בְּעִיר אַחַת, אֶלָּא אִם כֵּן יֵשׁ כְּדֵי לְסַפֵּר שְׁבָחָיו שֶׁל זֶה וּשְׁבָחָיו שֶׁל זֶה. \u0010y10\u0011\nאֵין אוֹמְרִים בִּפְנֵי הַמֵּת אֶלָּא דְּבָרִים שֶׁל מֵת, כְּגוֹן צָרְכֵי קְבוּרָתוֹ וְהֶסְפֵּד; אֲבָל שְׁאָר כָּל דָּבָר, \u0010y11\u0011 אָסוּר. וְהָנֵי מִלֵּי בְּדִבְרֵי תּוֹרָה, אֲבָל בְּמִלֵּי דְּעַלְמָא לֵית לָן בָּהּ.\nמֻתָּר לוֹמַר פְּסוּקִים וּדְרָשָׁה \u0010c4\u0011 לִכְבוֹד הַמֵּת, בְּתוֹךְ אַרְבַּע אַמּוֹתָיו אוֹ בְּבֵית הַקְּבָרוֹת \u0005(מהרא\"י בְּבֵאוּר מא\"ח לְדַעַת רמ\"ה)\u0006.\nחָכָם שֶׁמֵּת, בֵּית מִדְרָשׁוֹ בָּטֵל, שֶׁסוֹפְדִין אוֹתוֹ כָּל שִׁבְעָה. אֲבָל שְׁאָר מִדְרָשׁוֹת, עוֹסְקִין בַּתּוֹרָה אֲפִלּוּ בִּשְׁעַת הֶסְפֵּד; וְאַחַר הַהֶסְפֵּד אֵין תַּלְמִידָיו מִתְקַבְּצִים בְּבֵית מִדְרָשׁוֹ, אֶלָּא מִתְחַבְּרִים שְׁנַיִם שְׁנַיִם וְלוֹמְדִים בְּבָתֵּיהֶם. אַב בֵּית דִּין שֶׁמֵּת, כָּל מִדְּרָשׁוֹת שֶׁבָּעִיר בְּטֵלִין, וְהָרְגִילִין לְהִתְפַּלֵּל בב\"ה מְשַׁנִּים מְקוֹמָם. נָשִׂיא שֶׁמֵּת, כָּל בָּתֵּי מִדְרָשׁוֹת שֶׁבְּכָל מָקוֹם שֶׁמַּסְפִּידִין אוֹתוֹ בְּטֵלִים, וְאַחַר הַהֶסְפֵּד אֵין נִכְנָסִים לְבֵית הַמִּדְרָשׁ, אֶלָּא מִתְחַבְּרִים שְׁנַיִם שְׁנַיִם וְלוֹמְדִין בְּבָתֵּיהֶם. וְכָל בְּנֵי הָעִיר מִתְפַּלְּלִים בְּבֵית הָאָבֵל, בֵּין בְּחֹל בֵּין בְּשַׁבָּת, חוּץ מִקְּרִיאַת הַתּוֹרָה בְּשַׁבָּת וְשֵׁנִי וַחֲמִישִׁי, שֶׁקּוֹרִין בב\"ה. וְלֹא יְטַיְּלוּ בַּשּׁוּק, אֶלָּא יוֹשְׁבִים מִשְׁפָּחוֹת מִשְׁפָּחוֹת וְדָוִים כָּל הַיּוֹם.\nמַסְפִּידִין תַּלְמִידֵי חֲכָמִים וּנְשׁוֹתֵיהֶם בב\"ה וּבְבֵית הַמִּדְרָשׁ, אֲבָל לֹא שְׁאָר הָעָם.\nחָכָם וְאַלּוּף וְגָאוֹן, מַכְנִיסִין אוֹתוֹ לְבֵית הַמִּדְרָשׁ, וּמַנִּיחִין הַמִּטָּה בַּמָּקוֹם שֶׁהָיָה דּוֹרֵשׁ, וְסוֹפְדִין אוֹתוֹ שָׁם; וּכְשֶׁמּוֹצִיאִים הַמִּטָּה, סוֹפְדִים אוֹתוֹ עַד בֵּית הַקְּבָרוֹת, וּבַיּוֹם הַז' עוֹלִים לְבֵית הַקְּבָרוֹת וּמְבַקְּרִין אוֹתוֹ, וְכֵן בְּיוֹם שְׁלֹשִׁים וְתַכְלִית י\"ב חֹדֶשׁ, מְבַקְּרִין וּמַשְׁכִּיבִין אוֹתוֹ.",["\u0003כדי להרבות בכייה. \u0004וכל המוריד דמעות על אדם כשר הקב\"ה סופרן ומניחם בבית גנזיו וכל המתעצל בהספדו של אדם כשר אינו מאריך ימים וראוי לקברו בחייו. ש\"ס:","\u0003עניים בני חמשה. \u0004שהעני מצטער על בניו יותר מהעשיר לפי שאין לו שמתה אחרת:","\u0003ואין נוהגין כו'. \u0004ובכאן ק\"ק לובלין נוהגין שעל בן ל' אומרים צדוק הדין וקדיש וכמדומה לי שגם בשאר קהלות נוהגין כן וכן ראוי לנהוג:","\u0003מוסיפין כו'. \u0004משום כבוד אבותם:","\u0003בין במעשה בעלה. \u0004שעולה עמו ואינה יורדת עמו:","\u0003אין מתעסקין להספד וללוות. \u0004אבל צרכי מטה וקבורה מתעסקין עמהם. טור:","\u0003יורשים כו'. \u0004דוקא שירשו ממון המת דאל\"כ אפילו בניו אין מוציאין מהם בעל כרחו כדלקמן סי' שמ\"ח סעיף ב':","\u0003מוציאין מהם. \u0004דהספד יקרא דשכבא הוא ומטעם זה שומעין לו כשאומר אל תספדוהו ועי' בח\"מ סי' רנ\"ג סעיף ל\"ח:","\u0003אין שומעין לו. \u0004אבל צום האב ואם שלא לנהוג בהם י\"ב חדש כיון דאינו שייך בשאר מתים אלא בכבוד אב ואם מצוה לקיים דבריהם. מהרי\"ו שם:","\u0003אין עושים כו'. \u0004ע\"ל ס\"ס שנ\"ד:","\u0003אין אומרים כו'. \u0004משמע דעת המחבר דד\"ת אפילו חוץ לד' אמות אסור ומילי דעלמא אפי' תוך ד' אמות שרי והב\"ח פסק דד\"ת אסור אפי' חוץ לד' אמות ומילי דעלמא אינו אסור אלא תוך ד\"א ודבריו של מת מותר אפי' בד\"ת אפי' תוך ד\"א וכן נהגו לדרוש באגדות ופסוקים אפי' תוך ד\"א בפני המת ויוצאין מענין לענין עד שמגיעין לספר שבחיו של מת מעסק תורתו וחסידותו ויותר מדות טובות שהיו בו ע\"כ. וכתב המרדכי דכל אותו חדר שהמת מוכח בו חשוב כד' אמות וכן פסק הב\"ח וע\"ל סי' שס\"ו:","\u0003אסור. \u0004משום לועג לרש חרף עושהו:"],["\u0003ומוסיפין בהם קצת. \u0004קשה מה לי שקר מעט מה לי שקר הרבה ונראה לתת טעם לזה דדבר מסתבר הוא שכל מי שעושה איזה מצוה כגון צדקה וכיוצא בה באיזה שיעור בודאי אם היה בא לידו דבר הצורך קצת יותר ודאי לא היה מניח מלעשות גם אותו השיעור כי לא היה משחית בעבור דבר מעוט יותר וע\"כ נחשב לו כאלו עשאו ואין כאן עדות שקר עליו:\n\u0003יש \u0004בירושלמי המת יודע ושומע קילוסו כמתוך החלום וכל שאומרים בפניו יודע עד שיסתום הגולל):","\u0003עניים בני חמשה. \u0004דעניים מצטערים יותר מעשירים דעשירים יש להם שמחה בממון שלהם:","\u0003המחותך. \u0004פי' שהוציאוהו חתוך מן הבטן. מסורס שיצא הפוך. כן כ' נימוקי יוסף:","\u0003מוציאין מהם בעל כרחם. \u0004דהספדא יקרא דשיכבא הוא:","\u0003לכבוד המת. \u0004דכל שאין לכבוד המת ודאי אסור ולא כיש שמכוונים להראות מעלתם בדרוש שעל המת מה שאינו לכבודו ולאו שפיר קעבדי ושמעתי הרבה גדולים היו מקפידין על דבר זה. וכתב הטור בשם רב האי גאון דאפילו חוץ לארבע אמות אסור בד\"ת:\n\u0003בספר \u0004תורת האדם כתוב דאין מנהג ולא דרך ארץ להזכיר המת אחר שנים עשר חודש וכל שאין מגעת שמועה אלא לאחר שנים עשר חודש פטורים מהספד ואין חודש העיבור בכלל כי לא הוזכר שנה רק י\"ב חדש:"]],["הַמְאַבֵּד עַצְמוֹ לָדַעַת, \u0010y0\u0011 אֵין מִתְעַסְקִים עִמּוֹ לְכָל דָּבָר, וְאֵין מִתְאַבְּלִין עָלָיו, וְאֵין מַסְפִּידִין אוֹתוֹ, \u0010y1\u0011 וְלֹא קוֹרְעִין וְלֹא חוֹלְצִין, אֲבָל עוֹמְדִין עָלָיו בְּשׁוּרָה וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְכָל דָּבָר שֶׁהוּא כָּבוֹד לַחַיִּים.\nאֵיזֶהוּ מְאַבֵּד עַצְמוֹ לָדַעַת, \u0010y2\u0011 כְּגוֹן שֶׁאָמַר: הֲרֵי הוּא עוֹלֶה לְרֹאשׁ הַגַּג, וְרָאוּהוּ שֶׁעָלָה מִיָּד דֶּרֶךְ כַּעַס, אוֹ שֶׁהָיָה מֵצֵר, וְנָפַל וָמֵת, הֲרֵי זֶה בְּחֶזְקַת שֶׁאִבֵּד עַצְמוֹ לָדַעַת. אֲבָל אִם רָאוּהוּ חָנוּק וְתָלוּי בָּאִילָן, \u0010y3\u0011 אוֹ הָרוּג וּמֻשְׁלָךְ עַל גַּבֵּי סֵיפוֹ, הֲרֵי הוּא בְּחֶזְקַת כָּל הַמֵּתִים, וּמִתְעַסְקִים עִמּוֹ וְאֵין מוֹנְעִין מִמֶּנּוּ דָּבָר. \u0005הַגָּה: \u0010y4\u0011 מִי שֶׁגָּנַב וְגָזַל וְעַל יְדֵי זֶה נֶהֱרַג בְּדִין מַלְכוּת, מִתְאַבְּלִים עָלָיו, אִם אֵין בּוֹ סַכָּנָה מִפְּנֵי אֵימַת הַמַּלְכוּת, וְלֹא מִקְרֵי מְאַבֵּד לָדַעַת (מהרי\"ו סִימָן קי\"ד)\u0006.\nקָטָן הַמְאַבֵּד עַצְמוֹ לָדַעַת, חָשׁוּב כְּשֶׁלֹּא לָדַעַת. וְכֵן גָּדוֹל הַמְאַבֵּד עַצְמוֹ לָדַעַת, וְהוּא אָנוּס \u0010y5\u0011 כְּשָׁאוּל הַמֶּלֶךְ, אֵין מוֹנְעִין מִמֶּנּוּ כָּל דָּבָר. \u0010y6\u0011\nמְנֻדֶּה שֶׁמֵּת, דִּינוֹ כִּמְאַבֵּד עַצְמוֹ לָדַעַת; אֵין קוֹרְעִין וְלֹא חוֹלְצִין וְלֹא מַסְפִּידִין עָלָיו, וּמַנִּיחִין אֶבֶן עַל אֲרוֹנוֹ. וְהָנֵי מִלֵּי בְּאַפְקִירוּתָא, כְּשֶׁעוֹבֵר עַל דִּבְרֵי תּוֹרָה; אֲבָל בְּמָמוֹנָא, כֵּיוָן שֶׁמֵּת, פָּטוּר מִגְּזֵרָתָם, וְאֵין מַנִּיחִים אֶבֶן עַל אֲרוֹנוֹ, ומַסְפִּידִין אוֹתוֹ כָּרָאוּי.\nכָּל הַפּוֹרְשִׁים מִדַּרְכֵי צִבּוּר, וְהֵם הָאֲנָשִׁים שֶׁפָּרְקוּ עֹל הַמִּצְוֹת מֵעַל צַוָּארָם, וְאֵין נִּכְלָלִים בִּכְלַל יִשְׂרָאֵל בַּעֲשִׂיָּתָם, וּבִכְבוֹד הַמּוֹעֲדוֹת וִישִׁיבַת בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת, אֶלָּא הֲרֵי הֵם כִּבְנֵי חֹרִין לְעַצְמָן כִּשְׁאָר הָאֻמּוֹת, וְכֵן הַמּוּמָרִים וְהַמּוֹסְרִים, כָּל אֵלּוּ אֵין אוֹנְנִים וּמִתְאַבְּלִים עֲלֵיהֶם, אֶלָּא אֲחֵיהֶם וּשְׁאָר קְרוֹבֵיהֶם \u0010y7\u0011 לוֹבְשִׁים לְבָנִים וּמִתְעַטְּפִים לְבָנִים וְאוֹכְלִים וְשׁוֹתִים \u0010y8\u0011 וּשְׂמֵחִים. \u0005הַגָּה: הַפּוֹרֵשׁ מִן הַצִּבּוּר וְלֹא רָצָה לָשֵׂאת עִמָּהֶם בְּמִסִּים וְאַרְנוֹנִיּוֹת, מִתְאַבְּלִים עָלָיו (תשו' רַשְׁבָּ\"א סי' תשס\"ג)\u0006 אֲבָל אֵין שְׁאָר בְּנֵי הָעִיר צְרִיכִים לְבַטֵּל מִמְּלָאכְתָן בִּשְׁבִילוֹ לַעֲסֹק עִמּוֹ \u0005(כֵּן מַשְׁמָע בנ\"י סוֹף מ\"ק)\u0006.\nקָטָן בֶּן שָׁנָה אוֹ שְׁנָתַיִם שֶׁהֵמִיר \u0010y9\u0011 עִם אִמּוֹ, וָמֵת, אֵין מִתְאַבְּלִין עָלָיו \u0005וְעַיֵּן לְעֵיל סִימָן ש\"מ (סָעִיף ה')\u0006.\nמִי שֶׁנָּפַל בַּיָּם, אוֹ טָבַע בַּנָּהָר, אוֹ אֲכָלַתּוּ חַיָּה, אֵין מוֹנְעִין מִמֶּנּוּ דָּבָר.\nאָרוֹן הָעוֹבֵר מִמָּקוֹם לְמָקוֹם, אִם שִׁלְדּוֹ \u0005(פֵּרוּשׁ הַשִּׁדְרָה וְצַלְעוֹתֶיהָ)\u0006 קַיֶּמֶת, עוֹמְדִין עָלָיו בְּשׁוּרָה וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים, אִם יֵשׁ אֲבֵלִים שֶׁמִּתְאַבְּלִין עָלָיו; וְאִם אֵין שִׁלְדּוֹ קַיֶּמֶת, אֵין עוֹמְדִין עָלָיו בְּשׁוּרָה וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְלֹא תַּנְחוּמֵי אֲבֵלִים.",["\u0003אין מתעסקין כו'. \u0004דכתיב ואת דמכם לנפשותיכם אדרוש וגו' דעון גדול הוא המאבד עצמו לדעת וכתב בתשו' הרשב\"א סי' תשס\"ג דאף שאמרו בכל מקום אין מתעסקין עמהם לכל דבר לא לענין קבורה ותכריכים אמרו אלא שאין קורעין ולא חולצין כו' ומביאו ד\"מ:","\u0003ולא קורעין כו'. \u0004משמע שאין קורעין עליו כלל אפי' האבלים אבל דעת הרמב\"ן והטור שהאבלי' קורעין עליו והאי אין קורעין פי' לרחוקים:","\u0003כגון שאמר הרי הוא עולה כו'. \u0004וכ' הרמב\"ן אע\"פ שלא ראוהו מפיל עצמו כיון שאמר הריני עולה לראש הגג ואפיל עצמי ואמות חזקה לדעת עשה וכ' הב\"ח בשם מהרש\"ל דאפי' אמר ראו שאני עולה כו' ולא ראוהו עולה אדבוריה לחוד לא סמכינן ואינו בחזקת מאבד עצמו לדעת וכתב שדבריו נכונים:","\u0003או הרוג כו'. \u0004ע\"ל סי' שס\"ד סעיף ד' דין הרוגים:","\u0003מי שגנב כו'. \u0004משמע דר\"ל דל\"ת דכיון שגנב וגזל והתיר עצמו למיתה בדיניהם לא יתאבל עליו דה\"ל מאבד עצמו לדעת קמ\"ל דלא לפי שהיה סבור שיוכל לברוח אבל משום עבירה דגנב וגזל מתאבלי' עליו דלא חשוב כפורש מדרכי הציבור דלקמן סעיף ה' כך משמע מדברי הרב וכן כתב הרשב\"א בתשובה ס\"ס תשס\"ג דאחד מבעלי עבירה כגזלנים וכה\"ג אינן בכלל הפורשים מדרכי הצבור ולפ\"ז בגנב וגזלן שמתו על מטתן מתאבלין עליהן וכתב הב\"ח שכן נוהגין ואע\"פ שבתשו' מהרי\"ו סי' קי\"ד כתב אמעשה דגנב שנהרג בדיניהם וז\"ל ומ\"ש בספרים שקבל הגונב כו' לא ידענא פירושו ובודאי שיש לו כפרה וחלק לעוה\"ב דאפי' הרוגי ב\"ד יש להם חלק לעוה\"ב אפילו עובדי כוכבים כדאיתא בפרק נגמר הדין אומרי' לו התודה שכל המתודה יש לו חל\"ה וה\"נ מסתמא התודה כמ\"ש כו' אין ר\"ל דדוקא מיתתו שנהרג הוי כפרה וכמו שהבין הב\"ח מדבריו אלא ה\"ה מת על מטתו הוי כפרה כשמתודה אלא דעובדא דהתם הוי בנהרג מיהו לעיל סי' ש\"מ סעיף ה' כתב הרב דברגיל לעשות עבירה אין מתאבלין עליו ונראה דהיינו כשלא התודה קודם מיתתו:","\u0003כשאול המלך. \u0004שהרג את עצמו לפי שראה שהפלשתים יעשו בו כרצונם ויהרגוהו:","\u0003מנודה כו'. \u0004כפול לעיל סי' של\"ד ס\"ג:","\u0003לובשים לבנים כו'. \u0004וכתב הטור בשם הרי\"ץ גיאות מכאן שהאבלים וקרובי המת לובשים שחורים וכל מקום ומקום יש לעשות כפי מנהגו:","\u0003ושמחים. \u0004על שאבדו שונאיו של מקום דכתיב באבוד רשעי' רנה:","\u0003עם אמו. \u0004או עם אביו כדלעיל סי' ש\"מ ס\"ה בהג\"ה:"],[]],["מִי שֶׁהָיָה בַּעֲלָהּ עִמָּהּ צָלוּב בָּעִיר, אוֹ שֶׁאִשְׁתּוֹ עִמּוֹ צְלוּבָה בָּעִיר, אוֹ אָבִיו וְאִמּוֹ, וַעֲדַיִן לֹא כָּלָה הַבָּשָׂר \u0010y0\u0011 כֻּלּוֹ, לֹא יִשְׁהֶה בְּתוֹכָהּ אֶלָּא אִם כֵּן הָיְתָה גְּדוֹלָה כְּאַנְטוֹכְיָא, שֶׁאֵין אֵלּוּ מַכִּירִין אֶת אֵלּוּ, וְלֹא יִשְׁהֶה בְּצַד זֶה אֶלָּא בְּצַד זֶה.",["\u0003לא ישהה בתוכה. \u0004שהוא גורם לבזות המת שאומרים אותו פלוני הצלוב הוא אחיו של פלוני זה וכתב הפרישה דאם נקבר מותר וכתב הב\"ח דדוקא צלוב בעיר אבל במלכותינו שצולבין חוץ לעיר על פני השדה מותר לשהות בכל העיירות וע\"כ אין דין זה נוהג כלל עכשיו:"],[]],["\u0010y0\u0011 מִי שֶׁמֵּת לוֹ מֵת לִפִנֵי שְׁלֹשִׁים יוֹם הַסְמוּכִים לָרֶגֶל, לֹא יִסְפְּדֶנּוּ מִשֶּׁיִּכָּנְסוּ שְׁלֹשִׁים יוֹם הַסְמוּכִים לָרֶגֶל, וַאֲפִלּוּ יֵשׁ לוֹ הֶסְפֵּד בְּלֹא זֶה, כְּגוֹן שֶׁמֵּת לוֹ מֵת בְּתוֹךְ שְׁלֹשִׁים שֶׁמֻּתָּר לְסָפְדוֹ, וַאֲפִלּוּ מֵת עֶרֶב הָרֶגֶל, אָסוּר לְהַסְפִּיד עִמּוֹ עַל הַמֵּת שֶׁמֵּת לוֹ לִפְנֵי שְׁלֹשִׁים יוֹם קֹדֶם הַמּוֹעֵד.\nמִי שֶׁבָּאָה לוֹ שְׁמוּעָה בְּתוֹךְ שְׁלֹשִׁים יוֹם קֹדֶם הָרֶגֶל, \u0010y1\u0011 נִרְאֶה לִי שֶׁמֻּתָּר לְסָפְדוֹ, אַף עַל פִּי שֶׁהִיא רְחוֹקָה.\nמַה שֶּׁאָנוּ נוֹהֲגִין בְּתַשְׁלוּם הַשָּׁנָה לְקוֹנֵן וּלְהַזְכִּיר נְשָׁמוֹת, נִרְאֶה לִי אֵינוֹ בִּכְלַל זֶה וּמֻתָּר לַעֲשׂוֹתוֹ סָמוּךְ לָרֶגֶל.",["\u0003מי שמת כו'. \u0004עיין מזה בא\"ח סי' תקמ\"ז סעיף ג' ודין מחשיכין על התחום בשבת להביא צרכי המת כתוב בא\"ח סי' ש\"ו ס\"ג ודין עובד כוכבים שעשה קבר והביא חלילין בשבת נתבאר שס סי' שכ\"ה סעיף י\"ד ט\"ו ע\"ש:","\u0003נ\"ל כו'. \u0004וכ' העט\"ז ואנו נוהגין להזכיר אפילו פעם הראשון אפילו בתוך הרגל:"],[]],["\u0010y0\u0011 שׂוֹרְפִין עַל הַמְּלָכִים \u0005אוֹ עַל הַנְּשִׂיאִים (טוּר בְּשֵׁם תּוֹסֶפְתָּא)\u0006, מִטָּתָן וּכְלֵי תַּשְׁמִישָׁן, אֲבָל עַל הַהֶדְיוֹטוֹת \u0010y1\u0011 אָסוּר.\nהָאוֹמֵר: אַל תִּקְבְּרוּהוּ מִנְּכָסָיו, \u0010y2\u0011 אֵין שׁוֹמְעִין לוֹ, \u0010y3\u0011 אֶלָּא מוֹצִיאִין מִיּוֹרְשָׁיו כָּל צָרְכֵי קְבוּרָתוֹ בְּעַל כָּרְחוֹ, וְכֵן כָּל מַה שֶּׁרְגִילִין לַעֲשׂוֹת לִבְנֵי מִשְׁפַּחְתּוֹ, וַאֲפִלּוּ הָאֶבֶן שֶׁנּוֹתְנִין עַל הַקֶּבֶר; \u0010y4\u0011 וְהוּא שֶׁיָּרְשׁוּ מָמוֹן מֵאֲבִיהֶם.\nאֲפִלּוּ מִי שֶׁאֵין לוֹ מָמוֹן שֶׁצִּוָּה וְאָמַר: אַל תִּקְבְּרוּהוּ, \u0010y5\u0011 אֵין שׁוֹמְעִין לוֹ.",["\u0003שורפין כו'. \u0004ואין בו משום דרכי האמורי ולא משום בל תשחית שזהו כבודם שלא ישתמשו אחרים בכלי תשמישן ומש\"ה שורפים מטתן וכלי תשמישן דוקא ולא דברים אחרים:","\u0003אסור. \u0004דאיכא יוהרא והשחתה:","\u0003אין שומעין לו. \u0004דלאו כל כמיניה להעשיר בניו ולהטיל עצמו על הצבור:","\u0003אלא מוציאין מיורשיו. \u0004אפי' נתן ממון הרבה לאחרים אין מוציאין מהמקבלין מתנות רק מהיורשים כמ\"ש בח\"מ סי' רנ\"ג סל\"א:","\u0003והוא שירשו ממון מאביהם. \u0004דאל\"כ אין כופין הקרובים אלא על הכל מוטל לקברו:","\u0003אין שומעין לו. \u0004משום דאיכא בזיונא דחיי:"],[]],["מֵת, בֵּין עוֹבֵד כּוֹכָבִים בֵּין יִשְׂרָאֵל, תַּכְרִיכָיו \u0010y0\u0011 אֲסוּרִים בַּהֲנָאָה. וְדַוְקָא שֶׁהִזְמִינָם לְצָרְכּוֹ וּנְתָנָם עָלָיו, אֲבָל בְּהַזְמָנָה לְבַד, אֲפִלּוּ עֲשָׂאָם לְצָרְכּוֹ לְאַחַר שֶׁמֵּת, לֹא נֶאֶסְרוּ, \u0010y1\u0011 דְּהַזְמָנָה לָאו מִלְּתָא. וְכֵן אִם נְתָנָם עָלָיו וְלֹא הִזְמִינָם לְכָךְ בִּתְחִלָּה, עֲדַיִן לֹא נֶאֶסְרוּ.\nנוֹיֵי הַמֵּת הַמְחֻבָּרִים בְּגוּפוֹ, כְּגוֹן פֵּאָה נָכְרִית וְכַיּוֹצֵא בָהּ, אֲסוּרִים כְּמוֹ הַמֵּת עַצְמוֹ. \u0010y2\u0011 \u0005וְדַוְקָא כְּשֶׁהֵם קְשׁוּרִים בְּשַׂעֲרוֹת גּוּפָן, אֲבָל אֵינָן קְשׁוּרִים, מֻתָּר (כָּךְ מַשְׁמָע מִפֵּרוּשׁ רַשִׁ\"י פ\"ק דַּעֲרָכִין)\u0006 ; וְלָכֵן מֻתָּר לִטֹּל טַבָּעוֹת שֶׁבְּיָדָם שֶׁל מֵתִים, וְכַיּוֹצֵא בָּזֶה. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּסְתָם, אֲבָל אִם צִוָּה שֶׁיִּתְּנוּ נוֹי גּוּפוֹ הַמְחֻבָּרִים בּוֹ לִבְנוֹ אוֹ לְבִתּוֹ אוֹ לְצֹרֶךְ דָּבָר אַחֵר, מֻתָּרִים. אֲבָל שְׂעָרוֹ מַמָּשׁ, אֲפִלּוּ אִם צִוָּה עָלָיו, אָסוּר בַּהֲנָאָה. \u0005הַגָּה: אִשָּׁה שֶׁיּוֹצֵאת לֵהָרֵג, נֶהֱנִין בִּשְׂעָרָהּ, אַף עַל פִּי שֶׁנִּגְמַר דִּינָה, אֵין שַׂעֲרוֹתֶיהָ נֶאֱסָרִים עַד שֶׁתִּקָּטֵל (טוּר)\u0006.\nאִם הָיוּ אָבִיו וְאִמּוֹ מְזָרְקִים עָלָיו כֵּלִים, \u0010y3\u0011 מִצְוָה לַאֲחֵרִים לְהַצִּילָן, אִם לֹא נָגְעוּ \u0010y4\u0011 בַּמִּטָּה הַנִּקְבֶּרֶת עִמּוֹ. \u0005הַגָּה: וְאִם הִצִּילָן, חַיָּב בִּשְׁמִירָתָן; וְאִם הֶחֱזִירָן לְאָבִיו וּלְאִמּוֹ, וְחָזְרוּ וּזְרָקוּם, וְנֶאֶסְרוּ, חַיָּב הַמַּחֲזִיר לְשַׁלֵּם, דְּהָוֵי כִּזְרָקָן לִמְקוֹם גְּדוּדֵי חַיּוֹת וְלִסְטִים (בְּמָרְדְּכַי פֶּרֶק הַמּוֹכֵר אֶת הַסְפִינָה תְּשׁוּבַת מהר\"מ)\u0006. אֲבָל אִם נָגְעוּ בָּהּ, \u0010y5\u0011 אֲסוּרִים, \u0010y6\u0011 אִם הֵם שֶׁל אוֹתוֹ שֶׁזְּרָקָן עָלָיו, \u0010y7\u0011 וְהוּא שֶׁיִּזְרְקֵם עַל דַּעַת שֶׁיִּקְבְּרֵם עִמּוֹ \u0005(טוּר בְּשֵׁם רֹא\"שׁ וְהוּא סוֹף מ\"ק)\u0006. \u0005הַגָּה: הַדַּף שֶׁטִּהֲרוּ עָלָיו, וְכָל הַכֵּלִים שֶׁמּוֹלִיכִין הַמֵּת עֲלֵיהֶם לִקְבוּרָה, לֹא נֶאֶסְרוּ, דַּהֲרֵי לֹא נְתָנָם שָׁם עַל מְנָת לִקְבֹּר עִמּוֹ.\u0006 \u0005(תְּשׁוּבַת מהרי\"ל סִימָן נ\"ה, וְכָךְ מַשְׁמָע מִדִּבְרֵי הָרֹא\"שׁ שֶׁהֵבִיא הַטּוּר)\u0006.\nכָּל הַמַּרְבֶּה כֵּלִים עַל הַמֵּת, הֲרֵי זֶה עוֹבֵר מִשּׁוּם בַּל תַּשְׁחִית. \u0005(וַיִּקְרָא כ, יט)\u0006.",["\u0003אסורים בהנאה. \u0004דכתיב ותקבר שם מרים וילפינן שם שם מעגלה ערופה מה עגלה ערופה אסורה בהנאה אף מת וכל תכריכיו אסורים בהנאה:","\u0003דהזמנה לאו מלתא היא כו'. \u0004עיין בא\"ח ס\"ס מ\"ב:","\u0003ודוקא כשהם קשורים כו'. \u0004והב\"ח פסק דאפי' קלועים בתוכם ואינם קשורים אסורים אלא כשאינן קשורין בה כלל דהיינו דתלי בסיכתא מותרים ע\"ש:","\u0003מצוה לאחרים כו'. \u0004שיש בו משום השבת אבדה דודאי יתחרטו אח\"כ:","\u0003במטה הנקברת עמו. \u0004כלומר שנושאין אותו בה לקבורה:","\u0003אסורים. \u0004מדרבנן שגזרו בהן משום דמיחלפי בתכריכי המת:","\u0003אם הם של אותו כו'. \u0004לאפוקי של אחרים דלא דאין אדם אוסר דבר שאינו שלו:","\u0003והוא שיזרקם ע\"ד שיקברם עמו. \u0004כגון שיזרקם מתוך מרירות הלב ע\"מ לקברן עמו ונגעו במטה הנקברת לאפוקי המצע שמניחים על המת או הכר וכסת שנותנים תחת מראשותיו או סדין או טלית שפירסו על הארון או על המטה שמוליכין בה המת לקברו אינו נאסר:"],[]],["אִם רָצוּ, מַתִּירִין שְׂעָרוֹת לְכַלּוֹת, וּמְגַלִּים פְּנֵי חֲתָנִים, וְנוֹתְנִין דְּיוֹ וְקֻלְמוֹס בְּצִדּוֹ, \u0010y0\u0011 וְתוֹלִין מַפְתְּחוֹ שֶׁל מֵת וּפִנְקָסוֹ בָּאֲרוֹנוֹ, מִשּׁוּם עָגְמַת נֶפֶשׁ. וְעוֹשִׂים חֻפּוֹת לַחֲתָנִים וְכַלּוֹת, וְתוֹלִין בָּהֶם דְּבָרִים שֶׁלֹּא הֵבִיאוּ אֹכֶל נֶפֶשׁ; אֲבָל דְּבָרִים שֶׁהֵבִיאוּ אוֹכֵל נֶפֶשׁ, אָסוּר, \u0010y1\u0011 מִפְּנֵי שֶׁהֵם נֶאֱסָרִים בַּהֲנָאָה.",["\u0003ותולין כו'. \u0004כתב הב\"ח ומיהו עכשיו לא נהגו לעשות כן ומעכבין על מי שבא לשנות המנהג:","\u0003מפני שהם נאסרים בהנאה. \u0004והוה בהו משום בל תשחית לאסור אוכל נפש שלא לצורך:"],[]],["תַּכְרִיכֵי הַמֵּת, מֻתָּר לַעֲשׂוֹתָן \u0010y0\u0011 מִכִּלְאַיִם.\nאֵין קוֹבְרִין אֶת הַמֵּת אֶלָּא בְּטַלִּית שֶׁיֵּשׁ בּוֹ צִיצִית. \u0005הַגָּה: \u0010c0\u0011 וְיֵשׁ אוֹמְרִים דְּאֵין צָרִיךְ צִיצִית (טוּר בְּשֵׁם י\"א)\u0006. וְנָהֲגוּ לְקָבְרוֹ בְּצִיצִית, \u0010y1\u0011 אַךְ שֶׁפּוֹסְלִין תְּחִלָּה הַצִּיצִית, אוֹ כּוֹרְכִין אֶחָד מִן הַכַּנְפוֹת.",["\u0003מכלאים. \u0004כדלעיל סי' ש\"א סעיף ז':","\u0003אך שפוסלין כו'. \u0004והב\"ח כתב דאין לפסלן אלא יש לקשרן זה עם זה או לכסותם תוך הכנפות ע\"ש:"],["\u0003וי\"א שא\"צ ציצית. \u0004כשנפטר רבינו גרשון אמר ציצית חוץ ונחלקו בפירוש דבריו יש אומרים דרצונו לומר יסירו הציצית מהטלית ויש אומרים דהכי קאמר שישימו אותן חוץ לארון:"]],["\u0010y0\u0011 אֵין קוֹבְרִין הַמֵּת בְּתַכְרִיכִים יְקָרִים, אֲפִלּוּ לְנָשִׂיא שֶׁבְּיִשְׂרָאֵל.\nנָהֲגוּ לִקְבֹּר בִּבְגָדִים לְבָנִים. \u0010y1\u0011\nהָאִישׁ אֵינוֹ כּוֹרֵךְ וּמְקַשֵּׁר הָאִשָּׁה, אֲבָל הָאִשָּׁה כּוֹרֶכֶת וּמְקַשֶּׁרֶת הָאִישׁ.\nמַעֲצִימִין עֵינָיו שֶׁל מֵת; וְאִם נִפְתַּח פִּיו, קוֹשְׁרִין לְחַיָּיו. וּפוֹקְקִין נְקָבָיו אַחַר שֶׁמְּדִיחִין אוֹתוֹ בְּמִינֵי בְּשָׂמִים. וְגוֹזְזִין שְׂעָרוֹ. \u0005הַגָּה: וְצִפָּרְנָיו. וּמְדִיחִים אוֹתוֹ הֵיטֵב בְּכָל מָקוֹם, שֶׁיְּהֵא נָקִי מִכָּל טֻמְאָה (בִּנְיָמִין זְאֵב)\u0006, וְטָחִין רֹאשׁוֹ בְּבֵיצִים טְרוּפִים בִּקְלִפָּתָן, שֶׁגַּלְגַּל הוּא שֶׁחוֹזֵר בָּעוֹלָם \u0005(כָּל בּוֹ)\u0006.",["\u0003אין קוברין כו'. \u0004משום תיקון העולם שהעניים אינם יכולים לעשות כן וגם משום גסות הרוח והשחתה וכתוב בד\"מ והגהת דרישה בשם נ\"י פרק אלו מגלחין כל העושה תכריכין נאים למת מכירין בו שהוא מודה בתחיית המתים ותע\"ב עכ\"ל. ומיירי שהבגד פשתן יהא נאה וע\"כ נהגו קצת לחזור אחר היפה אבל בחשובים יותר מדאי ודאי אסור:","\u0003האיש אינו כורך. \u0004משום הרהור אבל באשה ליכא הרהור כל כך:"],[]],["בָּרִאשׁוֹנָה הָיוּ מְגַלִּים פְּנֵי עֲשִׁירִים וּמְכַסִים פְּנֵי עֲנִיִּים, מִפְּנֵי שֶׁמַּשְׁחִירִים בִּשְׁנַת בַּצֹּרֶת, וְהָיוּ עֲנִיִּים חַיִּים מִתְבַּיְּשִׁים. הִתְקִינוּ שֶׁיִּהְיוּ מְכַסִים פְּנֵי הַכֹּל. \u0010y0\u0011 \u0010c0\u0011\nאֵין מַנִּיחִין סֵפֶר תּוֹרָה עַל מִטָּתוֹ שֶׁל חָכָם.\nכְּבוֹדוֹ שֶׁל חָכָם לְהוֹצִיאוֹ דֶּרֶךְ הַפֶּתַח, וְלֹא לְשַׁלְשְׁלוֹ דֶּרֶךְ גַּגּוֹת; וּבְמִטָּה רִאשׁוֹנָה, וְלֹא לְשַׁנּוֹתוֹ מִמִּטָּה לְמִטָּה.\nתִּינוֹק בֶּן ל' יוֹם, מוֹצִיאִים אוֹתוֹ \u0010y1\u0011 בְּחֵיק לְבֵית הַקְּבָרוֹת, וְלֹא בְּאָרוֹן, וְנִקְבָּר בְּאִשָּׁה אַחַת וּשְׁנֵי אֲנָשִׁים; \u0010y2\u0011 אֲבָל לֹא בְּאִישׁ אֶחָד וּשְׁתֵּי נָשִׁים, מִשּׁוּם יִחוּד. \u0010y3\u0011 וְאֵין עוֹמְדִים עָלָיו \u0010y4\u0011 בְּשׁוּרָה, וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים, וַאֲפִלּוּ אִם קִים לָן שֶׁכָּלוּ לוֹ חֳדָשָׁיו.\nבֶּן ל' יוֹם גְּמוּרוֹת, יוֹצֵא \u0010y5\u0011 בִּגְלוּסְקָמָא \u0005(פי' אָרוֹן וַיִּישֶׂם בָּאָרוֹן (בְּרֵאשִׁית נ, כו)\u0006, ת\"י וְשַׁוּוּן יָתֵהּ בִּגְלוּסְקָמָא נ\"י) \u0010c1\u0011 הַנִּטֶּלֶת בַּאֲגַפַּיִם \u0005(פי' נֶסֶר רָחָב, וּפי' אֲגַפַּיִם, זְרוֹעוֹת)\u0006, וְעוֹמְדִין עָלָיו בְּשׁוּרָה, וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים. בֶּן י\"ב חֹדֶשׁ, יוֹצֵא בְּמִטָּה. וְכָל הַיּוֹצֵא בְּמַטָּה, רַבִּים מַצְהִיבִים עָלָיו; וְשֶׁאֵינוֹ יוֹצֵא בְּמִטָּה, אֵין רַבִּים מַצְהִיבִים עָלָיו. וְכָל הַנִּכָּר לָרַבִּים, רַבִּים מִתְעַסְקִין בּוֹ; וְכָל שֶׁאֵינוֹ נִכָּר לָרַבִּים, אֵין רַבִּים חַיָּבִים לְהִתְעַסֵק בּוֹ.\nתִּינוֹק שֶׁמֵּת \u0010y6\u0011 קֹדֶם שֶׁנִּמּוֹל, מוֹהֲלִין אוֹתוֹ עַל קִבְרוֹ, בְּלֹא בְּרָכָה, וְקוֹרִין לוֹ שֵׁם.\nאֵין מוֹצִיאִין מֵת בְּמִטָּה, אֶלָּא אִם כֵּן הָיָה רֹאשׁוֹ וְרֻבּוֹ קַיָּם.",["\u0003אין מניחין וכו'. \u0004דוקא על מטתו אבל לפניו על גבי קרקע או ספסל משמע בטור לעיל סי' שד\"מ מתשו' רב האי שמותר וכ\"כ בפרישה:","\u0003בחיק כו'. \u0004וכתוב בא\"ז דהיינו דא\"צ להוציא ואלא בחיק אבל אם רוצים להוציאו במטה הרשות בידם ומביאו הב\"ח:","\u0003אבל לא באיש א' ושתי נשים. \u0004משום יחוד:","\u0003ואין עומדין כו'. \u0004פי' אין צריך לעמוד. רש\"י וכ\"כ העט\"ז:","\u0003בשורה. \u0004ר\"ל שהיה כל אחד אומר לו תתנחם:","\u0003בגלוסקמא. \u0004פי' בנסר רחב שאינו ניטל אלא על הכתפים ואין צריך מטה גדול:","\u0003מוהלין כו'. \u0004נתבאר לעיל ס\"ס רס\"ג:"],["\u0003אין מניחין ס\"ת על מטתו. \u0004בסימן שד\"מ העתיק ב\"י בשם ת\"ה וז\"ל ואם נפטר אדם גדול וחסיד ויחיד במקומו אל יהיה ס\"ת בדבר זה מוטל אלא עומד בתיבה וכדומה לה עכ\"ל:","\u0003הניטלת באגפיים. \u0004פירוש בשני בני אדם דרך כבוד:"]],["עִיר שֶׁיֵּשׁ בָּהּ שְׁנֵי מֵתִים, מוֹצִיאִין \u0010y0\u0011 אֶת הָרִאשׁוֹן וְאַחַר כָּךְ מוֹצִיאִין הַשֵּׁנִי. \u0010y1\u0011 \u0010c0\u0011 וְאִם הָיוּ מְלִינִים הָרִאשׁוֹן, מוֹצִיאִין הַשֵּׁנִי. חָכָם וְתַלְמִיד חָכָם, מוֹצִיאִין הֶחָכָם. תַּלְמִיד חָכָם וְעַם הָאָרֶץ, מוֹצִיאִין תַּלְמִיד חָכָם. אִישׁ וְאִשָּׁה, מוֹצִיאִין הָאִשָּׁה, מִפְּנֵי שֶׁקְּרוֹבָה לְבֵית הַנִּוּוּל. הוֹצִיאוּ הָרִאשׁוֹן וּקְבָרוּהוּ, \u0010y2\u0011 אֵין עוֹמְדִין עָלָיו בְּשׁוּרָה, וְאֵין אוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְלֹא תַּנְחוּמֵי אֲבֵלִים, עַד שֶׁיּוֹצִיאוּ הַשֵּׁנִי. \u0010y3\u0011 הוֹצִיאוּ הַשֵּׁנִי וּקְבָרוּהוּ, בָּאִים וְעוֹמְדִים בְּשׁוּרָה, מְנַחֲמִים וּפוֹטְרִים אֶת הָרַבִּים; \u0010y4\u0011 וְאֵין מְנַחֲמִים שְׁנֵי אֲבֵלִים כְּאֶחָד, אֶלָּא אִם כֵּן הָיָה כְּבוֹדָם שָׁוֶה וְקִלּוּסָן שָׁוֶה.",["\u0003את הראשון. \u0004היינו אותו שמת ראשון:","\u0003ואם היו מלינין כו'. \u0004כלומר אם רוצים להלין הראשון לכבודו כדלקמן סי' שנ\"ז מוציאין את השני דהא בלא\"ה לא יוציאו עכשיו הראשון:","\u0003אין עומדין עליו כו'. \u0004כדי שלא לעכב קבורת השני:","\u0003הוציאו השני וקברוהו. \u0004(דאין עומדין) [באין ועומדין] בשורה על הא' והשני כאחד:","\u0003ואין מנחמין שני אבלים. \u0004אלא מנחמין אותן בזה אחר זה או נחלקים לשתי כתות:"],["\u0003ואם היו מלינים הראשון. \u0004פירוש שרוצים להלין הראשון להמתין על קרוביו או שאר צרכיו אין להלין גם השני בשבילו."]],["\u0010y0\u0011 אֵין מַנִּיחִין מִטָּה שֶׁל אִשָּׁה בָּרְחוֹב, מִפְּנֵי הַכָּבוֹד. \u0010y1\u0011 \u0010c0\u0011 \u0005וְאֵין עוֹלִין בְּחֶבֶר עִיר עַל הָאִשָּׁה (טוּר)\u0006.",["\u0003אין מניחין כו'. \u0004מפני שקרובה לינוול:","\u0003ואין עולין כו'. \u0004שאין כבוד לחכם שמנהיג העיר שכל העיר נוהגין ע\"פ צוויו שיהא עולה באשה כשנושאין אותה לקבורה:"],["\u0003ואין עולין בחבר עיר. \u0004בסימן רנ\"ו כתב הטור יש בעיר חבר עיר פירוש אדם גדול ובברכות אמרינן ר' יהודה אומר אין מתפללין מוספין אלא בחבר עיר והיינו צבור ואיך שיהיה פירושו כאן מ\"מ לא בא למעט באשה אלא שאין עומדין בחבורה ברחובה של עיר לענין הנזכר בטור בסימן שע\"ז אבל לענין ללוותה פשיטא שאין חלוק בין אשה לאיש וכמ\"ש סי' שד\"מ סעיף ב' כנ\"ל פשוט וכן משמע בפרישה:"]],["מֵת שֶׁלֹּא הָיָה לוֹ צָרְכֵי קְבוּרָה, וְגָבוּ לוֹ וְהוֹתִירוּ, אִם כְּשֶׁגָּבוּ \u0010y0\u0011 יַחְדָּו לְצָרְכֵי זֶה הַמֵּת, \u0010c0\u0011 יִנָּתְנוּ לְיוֹרְשָׁיו; וְאִם לָאו, יַעֲשׂוּ מֵהֶם צָרְכֵי מֵתִים אֲחֵרִים.",["\u0003יחדו לצרכי זה המת.\u0004 ל\"ש מעות או שאר דברים ינתנו ליורשיו לא משום דקני ליה זה המת בגביי' בעלמא דהא קי\"ל הזמנה לאו מלתא היא אלא משום דזילותא ה\"ל למת זה בגבייה ואחיל לי' זילותא ליורשיו וע\"ל סי' רנ\"ג ס\"ו:"],["\u0003ינתנו ליורשיו. \u0004אע\"פ דהזמנה לאו מילתא היא מ\"מ כיון דהוה ליה זילותא לגביה אחולי אחליה לגבי יורשיו כן איתא פרק נגמר הדין:"]],["אָסוּר לְהָלִין הַמֵּת, אֶלָּא אִם כֵּן הֵלִינוּ לִכְבוֹדוֹ, \u0010c0\u0011 לְהָבִיא לוֹ אָרוֹן וְתַכְרִיכִין אוֹ מְקוֹנְנוֹת, אוֹ כְּדֵי שֶׁיָּבֹאוּ קְרוֹבִים אוֹ לְהַשְׁמִיעַ עֲיָרוֹת.\nכָּל הַמֵּתִים, הַמְמַהֵר לְהוֹצִיא מִטָּתוֹ \u0010y0\u0011 הֲרֵי זֶה מְשֻׁבָּח. אֲבָל עַל אָבִיו וְעַל אִמּוֹ, הֲרֵי זֶה מְגֻנֶּה, אֶלָּא אִם כֵּן הָיָה עֶרֶב שַׁבָּת אוֹ עֶרֶב יוֹם טוֹב, אוֹ שֶׁהָיוּ גְּשָׁמִים מְזַלְּפִים עַל מִטָּתוֹ.",["\u0003ה\"ז משובח. \u0004לפי שאין דרך להספיד ולהתאבל עליהם הרבה הלכך יותר כבוד להם כשנקברים במהרה משיעמדו הרבה ולא יספידו' אבל על אביו ואמו שחייב להספידם ולקונן עליהם הרבה הממהר להוציא הרי זה מגונה:"],["\u0003להביא לו ארון ותכריכין. \u0004וה\"ה להמתין על קרוביו. כן כתב רש\"ל:"]],["נוֹשְׂאֵי הַמִּטָּה, וְחִלּוּפֵיהֶן, וְחִלּוּפֵי חִלּוּפֵיהֶן, בֵּין אוֹתָם שֶׁהֵם לִפְנֵי הַמִּטָּה בֵּין אוֹתָם שֶׁל אַחֲרֶיהָ, מֵאַחַר שֶׁלַּמִּטָּה צֹרֶךְ בָּהֶם, \u0010y0\u0011 פְּטוּרִים \u0005מִקְּרִיאַת שָׁמַע;\u0006 וּשְׁאָר הַמְּלַוִּין אֶת הַמֵּת, שֶׁאֵין לַמִּטָּה צֹרֶךְ בָּהֶם, חַיָּבִים. \u0005וְעַיֵּן בא\"ח סִימָן ע\"ב.\u0006 \u0010y1\u0011\nאֵין מוֹצִיאִין אֶת הַמֵּת סָמוּךְ לִקְרִיאַת שְׁמַע, כָּל שֶׁאֵין שְׁהוּת לְהוֹצִיאוֹ לְקִבְרוֹ קֹדֶם שֶׁיַּגִּיעַ זְמַן קְרִיאַת שְׁמַע; וְאִם הִתְחִילוּ לְהוֹצִיאוֹ, אֵין מַפְסִיקִין כְּדֵי לִקְרוֹת. \u0005הַגָּה: וְיֵשׁ לְהַמְתִּין מִלְּקָבְרוֹ עַד שֶׁיּוּכְלוּ לְשַׁעֵר שֶׁכְּבָר הִתְפַּלְּלוּ רֹב הַקָּהָל; וְאֵין חִלּוּק בָּזֶה בֵּין קְרִיאַת שְׁמַע שֶׁל שַׁחֲרִית לִקְרִיאַת שְׁמַע שֶׁל עַרְבִית. וְיֵשׁ מְקִלִּין בְּשֶׁל עַרְבִית, הוֹאִיל וּזְמַנָּהּ כָּל הַלַּיְלָה (מְבֹאָר בא\"ח סִימָן ע\"ב)\u0006. \u0010y2\u0011 \u0010c0\u0011\nבְּמָקוֹם שֶׁיֵּשׁ כַּתָּפִים מְיֻחָדִים לָשֵׂאת אֶת הַמִּטָּה, אֲסוּרִים בִּנְעִילַת הַסַנְדָּל, שֶׁמָּא יַפְסִיק סַנְדָּלוֹ שֶׁל אֶחָד מֵהֶם, וְנִמְצָא מִתְעַכֵּב מֵהַמִּצְוָה. \u0005הַגָּה: יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁהָאֲבֵלִים יוֹצְאִים רִאשׁוֹן מִן הַבַּיִת, וְהַקְּרוֹבִים וְהַמִּטָּה אַחֲרֵיהֶם, וְהָרְחוֹקִים נוֹתְנִין הַמֵּת עַל הַמִּטָּה, וְלוֹקְחִים הָאֲבֵלִים וְהַקְּרוֹבִים הַמִּטָּה עַל כִּתְפֵיהֶם, וְאַחַר כָּךְ שְׁאָר הָעָם (כָּל בּוֹ)\u0006. יֵשׁ אוֹמְרִים כְּשֶׁמַּגִּיעִים עִם הַמֵּת לַקְּבָרוֹת, \u0010y3\u0011 מַעֲמִידִים אוֹתוֹ כָּל ד' אַמּוֹת קֹדֶם שֶׁנִּקְבַּר \u0005(שָׁם וּב\"ז)\u0006 ; וְכֵן נָהֲגוּ הָאִדָּנָא לְהַעֲמִידוֹ ב' ג' פְּעָמִים קֹדֶם שֶׁאוֹמְרִים עָלָיו צִדּוּק הַדִּין, וּבְיָמִים שֶׁאֵין אוֹמְרִים צִדּוּק הַדִּין אֵין צָרִיךְ לְהַעֲמִיד אוֹתוֹ \u0005(מ\"כ בְּשֵׁם מהרי\"ל)\u0006.",["\u0003פטורים מק\"ש. \u0004שעוסק במצוה פטור מהמצוה:","\u0003אין מוציאין כו'. \u0004שלא להפקיע חובת קריאת שמע:","\u0003במקום שיש כו'. \u0004לאפוקי האידנא שאין לנו כתפים מיוחדי' אלא הכל מסייעים לישא לית לן בה:","\u0003מעמידים אותו כו'. \u0004כתב העט\"ז וטעם ההעמדה שמעתי כדי להבריח רוחות הטומאה הרוצים להחזיק בו שלא להכניס עמו לקבורה כי כשמעמידים אותו הולכים להם ובימים שא\"א בהם צדוק הדין א\"צ להעמיד אותו כי ביום זה אין כל כך רוחות טמאות מצויות:"],["\u0003במקום שיש כתפים כו'. \u0004נ\"ל שלא יפה עושים באיזה קהילות שעושין להם חבורה של נושאי המטה ואין מניחין אחרים לשאת דא\"כ היו צריכים לילך יחף והם אין עושין כן:"]],["\u0010y0\u0011 מָקוֹם שֶׁנָּהֲגוּ לָצֵאת נָשִׁים לִפְנֵי הַמִּטָּה, יוֹצְאוֹת. מָקוֹם שֶׁנָּהֲגוּ לָצֵאת לְאַחַר הַמִּטָּה, יוֹצְאוֹת. וְעַכְשָׁו נָהֲגוּ שֶׁאֵין יוֹצְאוֹת אֶלָּא לְאַחַר הַמִּטָּה, וְאֵין לְשַׁנּוֹת. \u0010y1\u0011\nיֵשׁ לִמְנֹעַ מִלָּצֵאת נָשִׁים לְבֵית הַקְּבָרוֹת אַחַר הַמִּטָּה.",["\u0003מקום שנהגו כו'. \u0004כתב הרמב\"ן והטור מתוספתא מקומות שנהגו להיות אבלים הולכים לפני המטה הולכים וכתב הב\"ח האידנא ליכא מנהג בהליכת אבלים אלא הולכים בין שאר העם:","\u0003יש למנוע כו'. \u0004כלומר שיצאו אחר המטה וכדלעיל סעיף א' אבל יש למנוע שלא יצאו לבית הקברות אחר המטה שאם עושים כן גורמים רעה לעולם ח\"ו:"],[]],["אִם פָּגְעוּ מֵת וְכַלָּה זֶה בָּזֶה, \u0010y0\u0011 מַעֲבִירִין הַמֵּת מִלִּפְנֵי הַכַּלָּה; וְכֵן אִם אֵין בָּעִיר כְּדֵי לָזֶה וְלָזֶה, מַקְדִּימִין וּמַכְנִיסִין הַכַּלָּה לַחֻפָּה, וְאַחַר כָּךְ קוֹבְרִים הַמֵּת. אֲבָל אַחַר שֶׁנִּכְנְסָה לַחֻפָּה, וְיֵשׁ לְפָנָיו לְנַחֵם אָבֵל וּלְשַׂמֵּחַ חָתָן, תַּנְחוּמֵי הָאֵבֶל קוֹדֵם. \u0010y1\u0011 וְכֵן הַבְרָאַת הָאָבֵל קוֹדֵם לְמִשְׁתֶּה שֶׁל חָתָן. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁיֵּשׁ בְּיָדוֹ סִפּוּק כְּדֵי שְׁנֵיהֶם, אֲבָל אִם אֵין בְּיָדוֹ כְּדֵי שְׁנֵיהֶם, מִשְׁתֵּה הֶחָתָן קוֹדֵם. \u0005חָתָן וְאָבֵל בב\"ה, יוֹצֵא הֶחָתָן עִם שׁוֹשְׁבִינָיו תְּחִלָּה, וְאַחַר כָּךְ הָאָבֵל, וְהַמְנַחֲמִים וְכֵן הַקְּרוּאִים שֶׁלָּהֶם אוֹכְלִים עִם הֶחָתָן כְּשֶׁיִּרְצוּ, וְלֹא עִם הָאָבֵל (בֵּית יוֹסֵף בְּשֵׁם הַגָּהוֹת מַיְמוֹנִי פ\"ד)\u0006. הַמֵּת וְהַמִּילָה, מִילָה קוֹדֶמֶת; וְאִם הוּא מֵת מִצְוָה, \u0010y2\u0011 \u0010c0\u0011 מֵת מִצְוָה קוֹדֵם.",["\u0003מעבירין את המת מלפני הכלה. \u0004להכניסה לחופה דלעולם מצות החיים קודמת למצות המתים ועיקר מצות הכלה להכניסה לחופה משום לא תוהו בראה וגו':","\u0003וכן הבראת האבל קודם כו'. \u0004מפני שהחתן אוכל משלו ומאכיל אחרים והאבל אינו אוכל עד שיאכילוהו אחרים:","\u0003מת מצוה קודם כו'. \u0004אכל הסימן קאי שמת מצוה קודם לכל דבר שבתורה כדלקמן ר\"ס שע\"ד ועיין באו\"ח ס\"ס תרפ\"ז:"],["\u0003מת מצוה קודם. \u0004בטור סיים שהרי הוא דוחה תלמוד תורה ומקרא מגילה כו' והוא בגמ' הביאו הרא\"ש פ\"ב דכתובות וכ' שם אע\"ג דגם מת שאינו מצוה נמי דוחה ת\"ת כמ\"ש סי' שס\"א מ\"מ נקט מת מצוה משום שאר דברים שאמר שם בגמרא והטור נגרר אחר לשון הגמרא. ומת מצוה אמרינן בפ' האשה רבה דהיינו כל שקורא ואין אחרים עונין ופירשו התוספות בנזיר דף מ\"ג כלומר שאם המת יכול לקרות יש לו עונין קרובים אין זה מת מצוה ועיין לקמן סימן שע\"ד סעיף ג' שכתוב בענין אחר:"]],["\u0010y0\u0011 מְבַטְּלִים תַּלְמוּד תּוֹרָה לְהוֹצָאַת הַמֵּת. לְמָאן דְּמַתְנֵי לַאֲחֵרִים, אֵין לוֹ שִׁעוּר, אֲפִלּוּ יֵשׁ עִמּוֹ כַּמָּה אֲלָפִים מִתְבַּטֵּל בִּשְׁבִילוֹ. לְמָאן דְּקָרֵי וְתָנֵי, \u0010y1\u0011 דְּהַיְנוּ שֶׁקָּרָא וְשָׁנָה וַעֲדַיִן לֹא שָׁנָה לַתַּלְמִידִים, \u0010y2\u0011 אִם יֵשׁ ס' רִבּוֹא אֵין צָרִיךְ לְהִתְבַּטֵּל בִּשְׁבִילוֹ. לְמָאן דְּלֹא קָרֵי וְתָנֵי, כֵּיוָן שֶׁיֵּשׁ לוֹ מִי שֶׁיִּתְעַסֵק עִמּוֹ אֵין צָרִיךְ לְהִתְבַּטֵּל בִּשְׁבִילוֹ, \u0010y3\u0011 וְהוּא שֶׁיֵּשׁ שָׁם עֲשָׂרָה. \u0005וְיֵשׁ אוֹמְרִים דְּעַכְשָׁיו מִן הַסְּתָם מְבַטְּלִין, שֶׁאֵין לְךָ אֶחָד מִיִּשְׂרָאֵל בַּזְּמַן הַזֶּה שֶׁאֵינוֹ בַּמִּקְרָא אוֹ בַּמִּשְׁנָה. (בֵּית יוֹסֵף בְּשֵׁם הריטב\"א פ\"ב דִּכְתֻבּוֹת שכ\"כ בְּשֵׁם סמ\"ג)\u0006 וְאִשָּׁה, יֵשׁ אוֹמְרִים שֶׁדִּינָה כְּמָאן דְּקָרֵי וְתָנֵי; וְיֵשׁ אוֹמְרִים שֶׁדִּינָה כְּמָאן דְּלֹא קָרֵי וְתָנֵי, וְכֵן נָהֲגוּ בְּאִשָּׁה וְתִינוֹק \u0010y4\u0011 לְקֻלָּא. וְאֵין מְבַטְּלִין תַּלְמוּד תּוֹרָה לְמֵת, כְּשֶׁיֵּשׁ מִי שֶׁיִּתְעַסֵק עִמּוֹ כָּל צָרְכּוֹ, אֶלָּא עוֹסֵק בַּתּוֹרָה. \u0010c0\u0011 וְאֵינוֹ צָרִיךְ לָצֵאת וְלִרְאוֹת אִם יֵשׁ עִמּוֹ כָּל צָרְכּוֹ אִם לָאו, אֶלָּא כֵּיוָן שֶׁיֵּשׁ שָׁם מִי שֶׁיַּעֲשֶׂה מַעֲשֶׂה, תַּלְמוּד תּוֹרָה שֶׁלּוֹ קוֹדֵם. \u0010y5\u0011 וְתִינוֹקוֹת שֶׁל בֵּית רַבָּן אֵין מִתְבַּטְּלִין כְּלָל.\nבַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁמְּבַטְּלִין תַּלְמוּד תּוֹרָה, לְלַוּוֹתוֹ בִּשְׁעַת הוֹצָאָתוֹ; אֲבָל כָּל זְמַן שֶׁמֻּטָּל לְקָבְרוֹ, אֵין מְבַטְּלִין בִּשְׁבִילוֹ תַּלְמוּד תּוֹרָה, אֶלָּא אִם יֵשׁ חֲבוּרוֹת בָּעִיר שֶׁכָּל אַחַת מִתְעַסֶקֶת יוֹמָהּ, אוֹתָהּ שֶׁאֵינָהּ יוֹמָהּ מֻתֶּרֶת בֵּין בְּלִמּוּד בֵּין בִּשְׁאָר מְלָאכוֹת. וּבִשְׁעַת הוֹצָאָה, מְבַטְּלִין מִכָּל שְׁאָר מְלָאכוֹת וּבָאִים לְלַוּוֹתוֹ, אֲפִלּוּ אִי לֹא קָרֵי וְתָנֵי, דְּלֹא מְפַלְּגִינָן בֵּין לֹא קָרֵי וְתָנֵי אֶלָּא בְּבִטּוּל תַּלְמוּד תּוֹרָה, אֲבָל בִּשְׁאָר מְלָאכוֹת, אֲפִלּוּ אִי לֹא קָרֵי וְתָנֵי הַכֹּל בְּטֵלִים וּבָאִים לְלַוּוֹתוֹ. וְאִם אֵין חֲבוּרוֹת בָּעִיר, כָּל בַּעֲלֵי מְלָאכוֹת צְרִיכִים לְהִתְבַּטֵּל וּלְהִתְעַסֵק בּוֹ עַד שֶׁיִּקָּבֵר; אֲבָל מִתַּלְמוּד תּוֹרָה אֵין צְרִיכִים לְהִתְבַּטֵּל אֶלָּא בִּשְׁעַת הוֹצָאָתוֹ, כִּדְאַמְרָן.\nהָרוֹאֶה אֶת הַמֵּת וְאֵינוֹ מְלַוֵּהוּ, עוֹבֵר מִשּׁוּם לוֹעֵג לָרָשׁ \u0005(מִשְׁלֵי יז, ה)\u0006 וּבַר נִדּוּי הוּא, וּלְפָחוֹת יְלַוֶּנּוּ ד' אַמּוֹת.\nאֲפִלּוּ בְּמָקוֹם שֶׁאֵינוֹ צָרִיךְ לְלַוּוֹת אֶת הַמֵּת, \u0010c1\u0011 צָרִיךְ לַעֲמֹד מִפָּנָיו.\nאָרוֹן הָעוֹבֵר מִמָּקוֹם לְמָקוֹם, אִם שִׁלְדּוֹ קַיֶּמֶת, צְרִיכִין לְלַוּוֹתוֹ כְּמוֹ בִּשְׁעַת הוֹצָאַת הַמֵּת.",["\u0003מבטלין ת\"ת כו'. \u0004פירוש חובה לבטל כן הסכימו הפוסקים:","\u0003שקרא ושנה כו'. \u0004משמע תרווייהו בעינן אבל מלשון הריטב\"א שהביא ב\"י שאין לך אדם מישראל שאינו או במקרא או במשנה כו' משמע דקרא או שנה קאמרינן:","\u0003אם יש ס' רבוא כו'. \u0004דנטילתה כנתינתה מסיני מה נתינת התורה בסיני בס' רבוא אף נטילתה בס' רבוא:","\u0003והוא שיש עמו עשרה. \u0004כדי שיוכלו לומר קדיש וברכת אבלים:","\u0003ואין מבטלים ת\"ת למת כשיש כו'. \u0004הל' מגומגם אבל בטור ניחא דקאי אמאן דלא קרי ותני דסגי כשיש לו מי שיתעסקו עמו וקאמר דאם יש אנשים בעיר שיוכלו להתעסק עמו א\"צ לראות אם מתעסקים עמו דמסתמא מתעסקים עמו ות\"ת קודם אבל מאן דמתני דאין לו שיעור ודאי דלעולם צריך ללוותו וכן למאן דקרי ותני דצריך ששים רבוא ודאי מסתמא ליכא ששים רבוא וע\"כ גם דברי המחבר צריך לפרש כן ודו\"ק. כתב האגודה מה שרגילין לבטל תלמוד תורה כל זמן שיש מת בעיר הטעם פן יהיה צרכי המת נדחה כי כולם ילכו ללמוד ונ\"ל בקהלות שעשו כתות ויש אנשים מיוחדים המתעסקים בו אדם הלומד לש\"ש ואינו רגיל לטפל בהם יכול ללמוד ע\"כ ומביאו מהרש\"ל והדרישה והב\"ח כתב עליו ונראה דאפילו למאן דקרי ותני קאמר דיוכל ללמוד אבל למאן דמתני לאחרים דאין לו שיעור צריך לבטל אפי' עשו כתות דהא דתניא מבטלין ת\"ת להוצאת המת אין פירושו מותר לבטל אלא חובה קתני עכ\"ל ולא הבנתי דבריו דהא האגודה מיירי שלא בשעת הוצאתו דיוכל ללמוד אפילו למאן דמתני דדוקא בשעת הוצאתו צריך לבטל וכדלקמן סעיף ב':","\u0003ותינוקות של בית רבן אינן מתבטלין כלל. \u0004פי' אפי' להוצאת המת וטעמא כדכ' הטור שהרי אין מבטלין אותן אפי' לבנין בית הכנסת דלא כעט\"ז שכתב הטעם שהרי אינם מתעסקים עמו דהא אין מבטלין אותו אפילו להוצאת המת:"],["\u0003וא\"צ לצאת ולראות כו'. \u0004זה קאי אמאן דלא קרי ותני שא\"צ לראות אם יש שם מתעסקים כל צרכו כמ\"ש לפני זה ונראה דהדעה הזאת חולקת על מה שכתב רמ\"א דהאידנא מן הסתם מבטלין ואם כן לפי דברי רמ\"א יש לבטל גם בזה מ\"מ רב הלומד עם תלמידיו לא יבטל בשביל זה מן הסתם. נראה לי:","\u0003צריך לעמוד מפניו. \u0004פי' מפני העוסקים עמו שהם גומלי חסדים כן הוא בטור בשם ירושלמי דקאמר אלין דקיימי מקמי מיתא לא קיימי מקמי מיתא אלא מקמי אלין דגמלין לו חסד וקשה לי ממ\"ש בפרק אלו מגלחין דכשנשא רבי חגי ארונו של רב הונא למערתא דר' חייא ובניו א\"ל יהודא לחזקיה קום מדוכתיך דלאו אורח ארעא דקאים רב הונא בהדי דקאים כו' ש\"מ דקם מקמי מיתא וצריך לומר דהכא אמר מסתם אדם שאין ת\"ח ומ\"מ נ\"ל ללמוד דבכל דבר מצוה שאדם הולך ומתעסק בה יש לעמוד לפניו וכן משמע בפ\"ק דקידושין (דף ל\"ג) א\"ר יוסי בר אבין בוא וראה כמה חביבה מצוה בשעתה שהרי מפניהם עומדים בעלי אומניות ומפני תלמיד חכם אין עומדים משמע כל מצוה:"]],["הַנּוֹתֵן מֵתוֹ בְּאָרוֹן וְלֹא קְבָרוֹ בַּקַּרְקַע, עוֹבֵר מִשּׁוּם מֵלִין אֶת הַמֵּת. וְאִם נְתָנוֹ בְּאָרוֹן וּקְבָרוֹ בַּקַּרְקַע, אֵינוֹ עוֹבֵר עָלָיו, \u0010y0\u0011 וּמִכָּל מָקוֹם יָפֶה לְקָבְרוֹ בַּקַּרְקַע מַמָּשׁ, אֲפִלּוּ בְּחוּץ לָאָרֶץ.\nנוֹתְנִין הַמֵּת \u0010y1\u0011 עַל גַּבָּיו, וּפָנָיו לְמַעְלָה, כְּאָדָם שֶׁהוּא יָשֵׁן.\nאֵין קוֹבְרִים ב' מֵתִים זֶה בְּצַד זֶה, אֶלָּא אִם כֵּן הָיָה דֹּפֶן הַקֶּבֶר מַפְסִיק בֵּינֵיהֶם; וְלֹא הַמֵּת בְּצַד עֲצָמוֹת; וְלֹא עֲצָמוֹת בְּצַד הַמֵּת. אֲבָל נִקְבָּר הָאִישׁ עִם בִּתּוֹ קְטַנָּה, וְהָאִשָּׁה עִם בְּנָהּ קָטָן וְעִם בֶּן בְּנָהּ קָטָן. \u0010y2\u0011 זֶה הַכְּלָל כָּל שֶׁיָּשֵׁן עִמּוֹ בְּחַיָּיו, נִקְבָּר עִמּוֹ בְּמוֹתוֹ. \u0010y3\u0011\nאֵין נוֹתְנִין ב' אֲרוֹנוֹת זֶה עַל זֶה; וְאִם נָתַן, כּוֹפִין הָעֶלְיוֹן שֶׁיְּפַנֶּה. וְאִם יֵשׁ בֵּינֵיהֶם עָפָר שִׁשָּׁה טְפָחִים, מֻתָּר.\nאֵין קוֹבְרִין רָשָׁע אֵצֶל צַדִּיק, אֲפִלּוּ רָשָׁע חָמוּר אֵצֶל רָשָׁע קַל. \u0010y4\u0011 וְכֵן \u0010c0\u0011 אֵין קוֹבְרִין צַדִּיק וְכָשֵׁר וּבֵינוֹנִי, אֵצֶל חָסִיד \u0010y5\u0011 מֻפְלָג. \u0005אֲבָל קוֹבְרִים בַּעַל תְּשׁוּבָה אֵצֶל צַדִּיק גָּמוּר (בֵּית יוֹסֵף)\u0006.\nשְׁנַיִם שֶׁהָיוּ שׂוֹנְאִים זֶה לָזֶה, אֵין לְקָבְרָם יַחַד.",["\u0003ומ\"מ יפה לקברו בקרקע קשה ממש. \u0004כלומר אע\"פ שהארון קבור בקרקע מ\"מ לא יהא הארון סתום מכל צד אלא יקבר המת בקרקע ממש ובעט\"ז ובפרישה תמהו על מה שנוהגין עכשיו לעשות לכהנים ארונות שלמים (דהיינו שעושים מלמטה דף ושוכב על הדף ואומרים טעם משום חשיבות כהנים הוא) דהרי אדרבה טוב הוא לשכב על העפר ולפמ\"ש בדרישה דבזמנינו שנותנים חרסית על פיו ועיניו הוי במקום עפר דבזמנם ניחא עי\"ל דאי אפשר לארונות שעושין עכשיו שלא יהיו נקובים בצדדים ובנקב סגי כדאיתא בטור ופוסקים:","\u0003על גבי וכו'. \u0004דכל היכא דישכיבו אותו באופן אחר או מעומד או יושב ה\"ל דרך גנאי וכתב העט\"ז ונוהגין לכסות הארון בדף ושלא להטיל שום עפר על גופו מפני שבזיון הוא לו:","\u0003זה הכלל כו'. \u0004נראה דדוקא אקטן הנ\"ל קאי אבל בן גדול אף שמותר עם אביו וכן בת גדולה עם אמה אסור לקברה עמהם ומ\"ש עם בן בנה הקטן ה\"ה דהוא מותר עם בת בנו או בתה אלא במאי דסיים פתח וחד מנייהו נקט. פרישה:","\u0003אין נותנין כו'. \u0004כתב הב\"ח דאפילו אי אפשר לקבור במקום אחר ולכן צריך למחות בקהלות שהקוברים עושים כן שלא ישימו זה על זה אלא בדאיכא בבירור הפסקת ו' טפחים מיהו אם אי אפשר לקברו בענין אחר ודאי שרי וכן משמע מתשובת רב האי גאון שהביא הטור בסי' שאח\"ז ופשוט הוא:","\u0003וכן אין קוברין צדיק וכ\"ש בינוני כו'. \u0004כצ\"ל:","\u0003אבל קוברים בעל תשובה כו'. \u0004וכתב הב\"ח אבל אין קוברין בעל תשובה אצל חסיד:"],["\u0003אין קוברין צדיק וכ\"ש בינוני. \u0004כן צריך להיות כאן ובטור וכן הוא בספר ת\"ה:"]],["\u0010y0\u0011 \u0010c0\u0011 אֵין מְפַנִּין הַמֵּת וְהָעֲצָמוֹת, לֹא מִקֶּבֶר מְכֻבָּד לְקֶבֶר מְכֻבָּד, וְלֹא מִקֶּבֶר בָּזוּי לְקֶבֶר בָּזוּי, וְלֹא מִבָּזוּי לִמְכֻבָּד, וְאֵין צָרִיךְ לוֹמַר מִמְּכֻבָּד לְבָזוּי. \u0010y1\u0011 \u0010c1\u0011 וּבְתוֹךְ שֶׁלּוֹ, אֲפִלּוּ מִמְּכֻבָּד לְבָזוּי, מֻתָּר, שֶׁעָרֵב לְאָדָם שֶׁיְּהֵא נָח אֵצֶל אֲבוֹתָיו. וְכֵן כְּדֵי לְקָבְרוֹ \u0010y2\u0011 בְּאֶרֶץ יִשְׂרָאֵל, מֻתָּר. וְאִם נְתָנוּהוּ שָׁם עַל מְנַת לְפַנּוֹתוֹ, מֻתָּר בְּכָל עִנְיָן. וְאִם אֵינוֹ מִשְׁתַּמֵּר בְּזֶה הַקֶּבֶר, שֶׁיֵּשׁ לָחוּשׁ שֶׁמָּא יוֹצִיאוּהוּ עוֹבְדֵי כּוֹכָבִים, אוֹ שֶׁיִּכָּנְסוּ בּוֹ מַיִם, אוֹ שֶׁהוּא קֶבֶר הַנִּמְצָא, מִצְוָה לְפַנּוֹתוֹ. \u0005יֵשׁ נוֹהֲגִין לָתֵת מֵעֲפַר אֶרֶץ יִשְׂרָאֵל בַּקֶּבֶר (אוֹר זָרוּעַ)\u0006, וְיֵשׁ לְמִנְהָג זֶה עַל מַה שֶּׁיִּסְמֹכוּ \u0005(מִדְרָשׁ תַּנְחוּמָא פ' וַיְחִי)\u0006. \u0010y3\u0011\nאֵין מוֹלִיכִים מֵת מֵעִיר שֶׁיֵּשׁ בָּהּ קְבָרוֹת לְעִיר \u0005(אַחֶרֶת)\u0006, אֶלָּא אִם כֵּן מֵחוּצָה לָאָרֶץ, לָאָרֶץ. \u0005הַגָּה: אוֹ שֶׁמּוֹלִיכִין אוֹתוֹ לִמְקוֹם קִבְרוֹת אֲבוֹתָיו (כֵּן מַשְׁמָע בְּאוֹר זָרוּעַ)\u0006. וְאִם צִוָּה לְהוֹלִיכוֹ מִמָּקוֹם לְמָקוֹם, אוֹ שֶׁצִּוָּה לְקָבְרוֹ בְּבֵיתוֹ וְלֹא בְּבֵית הַקְּבָרוֹת, שׁוֹמְעִין לוֹ \u0005(ג\"ז שָׁם)\u0006. וּמֻתָּר לִתֵּן סִיד עָלָיו, \u0010c2\u0011 כְּדֵי לְעַכֵּל הַבָּשָׂר מַהֵר, וּלְהוֹלִיכוֹ לַמָּקוֹם אֲשֶׁר צִוָּה \u0005(רַשְׁבָּ\"א סִימָן שס\"ט)\u0006.\nאֵין מְלַקְּטִין עֲצָמוֹת, לֹא מִתּוֹךְ הָאָרוֹן וְלֹא מִתּוֹךְ הַקֶּבֶר, לְצַד זֶה, לִקְבֹּר שָׁם מֵת אַחֵר, אוֹ לְצֹרֶךְ הַמָּקוֹם.\nמָקוֹם שֶׁנּוֹהֲגִין \u0010c3\u0011 לִקְבֹּר בְּמַהֲמוֹרוֹת \u0005(פי' בְּשׁוּחוֹת עֲמֻקוֹת מִן בְּמַהֲמֹרוֹת בַּל יָקוּמוּ (תְּהִלִּים קמ, יא)\u0006 ) בְּלא אָרוֹן, עַד שֶׁיִּתְעַכֵּל הַבָּשָׂר, וְאַחַר כָּךְ מְלַקְּטִין הָעֲצָמוֹת וְקוֹבְרִין אוֹתָן בְּאָרוֹן, \u0010y4\u0011 מֻתָּר.\nאָרוֹן שֶׁפִּנּוּהוּ, אָסוּר בַּהֲנָאָה. אִם הוּא שֶׁל אֶבֶן וְשֶׁל חֶרֶס, יִשָּׁבֵר; וְשֶׁל עֵץ, יִשָּׂרֵף.\nהַמּוֹצֵא נְסָרִים בְּבֵית הַקְּבָרוֹת, \u0010y5\u0011 \u0010c4\u0011 לֹא יְזִיזֵם מִמְּקוֹמָם.\nאָסוּר לִפְתֹּחַ הַקֶּבֶר אַחַר שֶׁנִּסְתַּם הַגּוֹלֵל, אֲפִלּוּ אִם עוֹרְרִים הַיּוֹרְשִׁים לְפָתְחוֹ כְּדֵי \u0010c5\u0011 לִבְדֹּק אִם הֵבִיא שְׁתֵּי שְׂעָרוֹת.",["\u0003אין מפנין כו'. \u0004הטעם שהבלבול קשה למתים מפני שמתייראין מיום הדין וזכר לדבר ישנתי אז ינוח לי ובשמואל הוא אומר למה הרגזתני להעלות וגו':","\u0003ובתוך שלו כו'. \u0004כלומר לפנותו לקברו אצל אבותיו מפני שזהו כבודו וכתב הבית יוסף וד\"מ משום האי כבוד מפנין ולא משום כבוד אחר:","\u0003בארץ ישראל מותר.\u0004 שהוא כפרתו שעפר א\"י מכפרת דכתיב וכפר אדמתו עמו:","\u0003אין מוליכין כו'. \u0004משום כבוד המתים הקבורים באותה העיר שמבזה אותם שלא לנוח אצלם את זה:","\u0003ארון שפינוהו אסור בהנאה. \u0004שכל מה שנקבר עם המת אסור בהנאה כדלעיל ר\"ס שמ\"ט:","\u0003לא יזיזם ממקומם. \u0004דחיישינן שמא מארון שפינוהו הם:"],["\u0003אין מפנין כו'. \u0004הטעם דבלבול קשה להם שמתייראין מיום הדין וזכר לדבר ישנתי אז ינוח לי:","\u0003ובתוך שלו. \u0004פי' למקום שהוא שלו ששם שוכבים בני משפחתו:","\u0003כדי לעכל הבשר. \u0004שנאמר בשרו עליו יכאב כל זמן שבשרו עליו יכאב אינו נוח מן הדין:","\u0003במהמורות. \u0004פי' גומא מלשון במהמורות בל יקומו:","\u0003לא יזיזם ממקומם. \u0004דשמא מן ארון הם וכתוב בפרישה ה\"ה חרסים:","\u0003אם הביא שתי שערות. \u0004פי' אם היה גדול ונפקא מינה לענין מכירתו שמכר אם הוא מכר:"]],["\u0010y0\u0011 קֶבֶר שֶׁל בִּנְיָן, אָסוּר בַּהֲנָאָה; אֲבָל קַרְקַע עוֹלָם שֶׁל קֶבֶר, אֵינוֹ נֶאֱסָר. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּהַקַּרְקַע שֶׁלָּקְחוּ מִן הַקֶּבֶר וְחָזְרוּ וְנָתְנוּ עָלָיו, \u0010y1\u0011 דְּהָוֵי תָּלוּשׁ וּלְבַסּוֹף חִבְּרוֹ, אָסוּר בַּהֲנָאָה (טוּר בְּשֵׁם הר\"ר יְשַׁעְיָה)\u0006. \u0010y2\u0011 וְיֵשׁ אוֹסְרִין עוֹד לֵישֵׁב עַל הָאֶבֶן שֶׁנּוֹתְנִין עַל הַקֶּבֶר לְמַצֵּבָה \u0005(גַּם זוֹ בִּשְׁמוֹ וכ\"כ הַגָּהוֹת אֲשֵׁרִ\"י בְּשֵׁם אוֹר זָרוּעַ פֶּרֶק אֵלּוּ מְגַלְּחִין)\u0006. \u0010c0\u0011 וְיֵשׁ חוֹלְקִים וּמַתִּירִים \u0005(טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006. הַכֵּלִים שֶׁחוֹפְרִים וְקוֹבְרִים בָּהֶם, מֻתָּרִים בַּהֲנָאָה, וְאֵין לְהִשְׁתַּמֵּשׁ בָּהֶן אֶלָּא מִדַּעַת הַגַּבַּאי, כְּמוֹ בִּשְׁאָר צְדָקָה \u0005(תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן צ\"ז)\u0006. וְהָא דְּקֶבֶר שֶׁל בִּנְיָן אָסוּר לְעוֹלָם, דַּוְקָא שֶׁבְּנָאוֹ לְשֵׁם מֵת, וּנְתָנוֹ בּוֹ אֲפִלּוּ עַל דַּעַת לְפַנּוֹתוֹ, וַאֲפִלּוּ לֹא נָתַן בּוֹ אֶלָּא נֵפֶל. אֲבָל אִם בְּנָאוֹ לִשְׁמוֹ, וְלֹא נְתָנוֹ בּוֹ, מֻתָּר. וְכֵן אִם נְתָנוֹ בּוֹ אַדַּעְתָּא לְפַנּוֹתוֹ, וְלֹא הִזְמִינוֹ מִתְּחִלָּה, מֻתָּר לְאַחַר שֶׁפִּנָּהוּ. אֲבָל אִם נְתָנוֹ בּוֹ עַל דַּעַת לִהְיוֹת בּוֹ עוֹלָמִית, אָסוּר אֲפִלּוּ לְאַחַר שֶׁפִּנָּהוּ, אֲפִלּוּ לֹא בְּנָאוֹ לִשְׁמוֹ. וְאִם לֹא בְּנָאוֹ לִשְׁמוֹ, וּנְתָנוּהוּ בְּתוֹכוֹ וְהוֹסִיף בּוֹ דִּימוֹס \u0005(פֵּרוּשׁ נִדְבָּךְ, וְהוּא שׁוּרַת בִּנְיַן הַחוֹמָה)\u0006 לִשְׁמוֹ, כֻּלּוֹ אָסוּר, אֲפִלּוּ לְאַחַר שֶׁפִּנָּהוּ וַאֲפִלּוּ שֶׁקְּבָרוֹ שָׁם עַל דַּעַת לְפַנּוֹתוֹ. וְאִם מַכִּיר הַדִּימוֹס שֶׁהוֹסִיף לִשְׁמוֹ, מְסִירוֹ, וְהוּא לְבַדּוֹ אָסוּר, וּשְׁאָר הַקֶּבֶר מֻתָּר.\nקֶבֶר הַנִּמְצָא, \u0010y3\u0011 מֻתָּר לְפַנּוֹתוֹ. פִּנָּהוּ, מְקוֹמוֹ טָהוֹר \u0010y4\u0011 וּמֻתָּר בַּהֲנָאָה. \u0010y5\u0011 קֶבֶר הַיָּדוּעַ, אָסוּר לְפַנּוֹתוֹ; \u0010y6\u0011 פִּנָּהוּ, מְקוֹמוֹ טָמֵא וְאָסוּר בַּהֲנָאָה. \u0010y7\u0011 וְהָרַמְבַּ\"ם גּוֹרֵס קֶבֶר הַנִּמְצָא, מֻתָּר לְפַנּוֹתוֹ; \u0010y8\u0011 פִּנָּהוּ, מְקוֹמוֹ טָמֵא וְאָסוּר בַּהֲנָאָה; קֶבֶר הַיָּדוּעַ, אָסוּר לְפַנּוֹתוֹ; פִּנָּהוּ, מְקוֹמוֹ טָהוֹר וּמֻתָּר בַּהֲנָאָה.\nמֵת מִצְוָה, שֶׁמְּצָאוֹ אָדָם בַּשָּׂדֶה וּקְבָרוֹ שָׁם, אֲפִלּוּ שֶׁלֹּא מִדַּעַת בַּעַל הַשָּׂדֶה, אָסוּר לְפַנּוֹתוֹ, שֶׁמֵּת מִצְוָה קוֹנֶה מְקוֹמוֹ. \u0010y9\u0011 וְכָל הַמּוֹצְאוֹ צָרִיךְ לְקָבְרוֹ בַּמָּקוֹם שֶׁמְּצָאוֹ. וְאִם מְצָאוֹ עַל הַמֶּצֶר, שֶׁצָּרִיךְ לְפַנּוֹתוֹ מִשָּׁם מִפְּנֵי הָרַבִּים שֶׁלֹּא יַאֲהִילוּ עָלָיו, אִם מְצָאוֹ בֵּין שְׂדֵה בּוּר \u0005(פיר' שֶׁאֵינָהּ חֲרוּשָׁה וּזְרוּעָה)\u0006 לִשְׂדֵה נִיר \u0005(פֵּרוּשׁ נִיר נֶחֱרַשׁ וְלֹא נִזְרַע)\u0006, מְפַנֶּהוּ לִשְׂדֵה בּוּר. בֵּין שְׂדֵה נִיר לִשְׂדֵה זֶרַע, מְפַנֶּהוּ לִשְׂדֵה נִיר. בֵּין שְׂדֵה זֶרַע לִשְׂדֵה אִילָן, מְפַנֶּהוּ לִשְׂדֵה זֶרַע. בֵּין שְׂדֵה אִילָן לִשְׂדֵה כֶּרֶם, מְפַנֶּהוּ לִשְׂדֵה אִילָן. וְאִם שְׁתֵּיהֶם שָׁווֹת, מְפַנֶּהוּ לַקָּרוֹב שֶׁבָּהֶם. וְאִם שְׁתֵּיהֶן שָׁווֹת בְּקֵרוּב, מְפַנֶּהוּ לְאֵיזֶהוּ מֵהֶם שֶׁיִּרְצֶה. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּמְצָאוֹ חוּץ לַתְּחוּם. אֲבָל אִם מְצָאוֹ בְּתוֹךְ הַתְּחוּם, מְבִיאוֹ לְבֵית הַקְּבָרוֹת. וְאֵינוֹ נִקְרָא מֵת מִצְוָה, \u0010c1\u0011 אֶלָּא אִם כֵּן מָצָא רֹאשׁוֹ וְרֻבּוֹ.\nאִם מָצְאוּ יִשְׂרָאֵל הָרוּג, יִקְבְּרוּהוּ כְּמוֹ שֶׁמְּצָאוּהוּ, בְּלֹא תַּכְרִיכִין, וְלֹא יַחְלְצוּ בּוֹ אֲפִלּוּ מִנְעָלָיו. \u0005הַגָּה: \u0010c2\u0011 וְכֵן עוֹשִׂין לְיוֹלֶדֶת שֶׁמֵּתָה, \u0010y10\u0011 אוֹ לְמִי שֶׁנָּפַל וָמֵת (מהרי\"ל סִימָן ס\"ה)\u0006. וְיֵשׁ אוֹמְרִים שֶׁמַּלְבִּישִׁין אוֹתָם לְמַעְלָה מִבִּגְדֵיהֶם, תַּכְרִיכִין \u0005(הגהמי\"י בְּשֵׁם ר\"י מִדּוּרָא)\u0006. וְנָהֲגוּ שֶׁאֵין עוֹשִׂין לָהֶם תַּכְרִיכִין כִּשְׁאָר מֵתִים, רַק קוֹבְרִין אוֹתָן בְּבִגְדֵיהֶם, וּלְמַעְלָה מֵהֶם סָדִין, כִּשְׁאָר מֵתִים.\nקֶבֶר הַמַּזִּיק אֶת הָרַבִּים, כְּגוֹן שֶׁהוּא סָמוּךְ לַדֶּרֶךְ, אֲפִלּוּ נִקְבַּר שָׁם מִדַּעַת בַּעַל הַשָּׂדֶה, מֻתָּר לְפַנּוֹתוֹ, \u0010c3\u0011 וּמְקוֹמוֹ טָהוֹר, \u0010y11\u0011 וְאָסוּר בַּהֲנָאָה אִם קָדַם הַקֶּבֶר; אֲבָל אִם קָדַם הַדֶּרֶךְ, מְקוֹמוֹ \u0010y12\u0011 מֻתָּר בַּהֲנָאָה.\nקֶבֶר שֶׁפִּנָּהוּ, הֵיכָא דְּמֻתָּר בַּהֲנָאָה, \u0010y13\u0011 לֹא יַעֲשֶׂנּוּ בֵּית הַתֶּבֶן וְלֹא בֵּית הָעֵצִים וְלֹא בֵּית הָאוֹצָרוֹת.\nהַחוֹצֵב קֶבֶר לְאָבִיו וּקְבָרוֹ בְּמָקוֹם אַחֵר, \u0010y14\u0011 לֹא יִקָּבֵר בּוֹ הוּא עוֹלָמִית, מִשּׁוּם כְּבוֹד אָבִיו; אֲבָל אַחֵר, מֻתָּר לִקָּבֵר בּוֹ.",["\u0003קבר של בנין כו'. \u0004דילפינן מדכתיב וישלך את עפרה אל קבר בני העם מקיש קבר לעבודת כוכבי' מה עבודת כוכבי' אינו נאסר במחובר כדלעיל סי' קמ\"ה אף קבר אין נאסר במחובר אבל קבר של בנין הוי תלוש ולבסוף חברו דאסור כמו שבנאו לעבודת כוכבים כדלעיל סימן קמ\"ה סעיף ג':","\u0003דהוי תלוש ולבסוף חברו אסור בהנאה. \u0004ואיזה הוא קרקע עולם כגון החופר כוך בסלע שהוא קרקע עולם שלא נתלש. טור וכ\"ש צדדי הקבר ותחתיתו שאין נאסר אלא דאשמועינן בכוך דאפי' העפר שעל גביו אינו נאסר משום דקרקע עולם הוא וכ\"כ בפרישה:","\u0003ויש אוסרים עוד כו'. \u0004וכתב בהגהת אשר\"י דאסור למכור מצבה שנשברה ואסור להשען על המצבה ואסור לדרוך ע\"ג הקברים דאסור בהנאה וכתב הב\"ח שכן נוהגין איסור:","\u0003מותר לפנותו. \u0004ולא חיישי' שמא מת מצוה הוא דמת מצוה קלא אית ליה:","\u0003ומותר בהנאה. \u0004שאין אדם אוסר דבר שאינו שלו ומיירי בקבר של בנין דאלו במחובר בלאו הכי אין מחובר נאסר וכ\"כ נ\"י:","\u0003קבר הידוע. \u0004שנקבר שם מדעת בעל השדה:","\u0003מקומו טמא ואסור בהנאה. \u0004גזירה דרבנן היא שגזרו טומאה עולמית כדי שלא יפנוהו:","\u0003והרמב\"ם גורס קבר כו'. \u0004וה\"פ קבר הנמצא דהיינו שלא היינו יודעים שהיה שם קבר מותר לפנותו דכיון שלא היה ידוע מסתמא נקבר שם שלא ברשות בעל השדה:","\u0003פינהו מקומו טמא. \u0004כלומר השדה שסביבותיו היכא דאיכא למיחש לקברים. קבר הידוע שאין שם אלא הוא לבדו (ועבר) [ונקבר] שם שלא מדעת בעל השדה מותר לפנותו ומקומו טהור ומותר בהנאה כיון שידוע שאין שם קברים אחרים. ב\"י:","\u0003וכל המוצאו צריך לקברו במקום שמצאו. \u0004וא\"צ להוליכו לקברות וכתב מהרש\"ל ומה שהאידנא אין נזהרים בזה הוא לפי שאין הארץ שלנו ואין לנו רשות לקבור בכל מקום ואף אם נקבר אותו לשם יש לחוש שהעובדי כוכבים יחזרו ויוציאו אותו כדי לפשוט בגדיו מעליו [או] משום זלזול ע\"כ מוליכין אותו לבה\"ק מיוחד עד כאן והביאוהו האחרונים:","\u0003או למי שנפל ומת. \u0004במהרי\"ל כתוב דאם דם יצא ממנו אז אין לטהר אותו כי הדם יסתלק ממנו אך יקברוהו במלבושיו וכ' הב\"ח ונראה דהיינו דוקא כשמת במלבושיו אבל בנפל ולא מת מיד אלא לאחר כמה ימים שכבר פשט מלבושיו וגם אין דם יוצא ממנו שכבר פסק ומת על מטתו מכח אותו נפילה אז ודאי מטהרין אותו ועושין לו תכריכין כשאר בני אדם שמתין על מטתן ובדבר הזה יש חילוק בין נפל מן הגג להרוג דאלו בהרוג בידי עובד כוכבים אע\"פ שבשעה שמלאוהו כבר פסק הדם קוברים אותו כאשר הוא נמצא כדי להעלות חימה ולנקום נקם וזה אין שייך בנפל מן הגג וכן ביולדת שמתה ודם יוצא ממנה אין לטהרה אלא קוברים אותה בלבושיה אבל אם לא מתה אלא לאחר כמה ימים ושבועות וכבר פסק הדם נוהגין עמה כמו בשאר מתים לטהרה ולעשות לה תכריכין שוב מצאתי כתוב שמעתי הטעם גבי הרוג דהרי כבר יצאו כל הדמים ממנו והם מובלעים בבגדיו וחיישינן שמא נבלע בתוכן הרביעית דם שהנפש יוצאת בו ע\"כ יקברוהו כמו שמצאוהו ולא יחלצו אפילו מנעליו דשמא הדמים שיצאו עם יציאת הנפש הם בתוך המנעלים וע\"כ נוהגין בהרוג לחפור ולחתור במרא וחצינא בקרקע במקום שנמצא שם ההרוג וכן כל דמו שיצא ממנו במקום קרוב לו וקוברין אותו עפר שנבלע בו דמו עם ההרוג דשמא באותו הדם יצא דם הנפש ומזה הטעם ג\"כ במי שנפל מן הגג ומת או נפל עליו הבית ומת ונעשה בגופו פצעים וחבורות ומוציא מהם דם וזה גם כן טעם היולדת דרובם אינם מתי' אלא מחמת שנעשה באיברים הפנימים שלה פצעים כשכורעת לילד וע\"י כן יצא ממנה דם הרבה נבלעו בכתונת שעל גופה ובשאר בגדים שעליה והדמים שיצאו עם יציאת הנפש נבלעו בתוכם משא\"כ כשאין שם פצעים ולא יצא מהם דם כלל דאז אין קוברין אותה בבגדיה אלא בתכריכינן כשאר מתים ומטהרין אותם ולפ\"ז מי שמת בדרך בקור גדול ושלג נראה דפושטין מלבושיו ומטהרין ומלבישין אותו בתכריכין כיון שאין בו פצעים ולא יצא ממנו דם וכן מי שנטבע במים בבגדיו דפושטין בגדיו ומטהרין אותו ומלבישין אותו תכריכין וכמ\"ש בסוף ספר מהרי\"ל ע\"כ ואני ראיתי בהרבה קהלות נוהגין לטהר כל יולדת ולהלבישה תכריכים ולהלבישה בגדיה למעלה מהתכריכין ולמעלה מהם הסדין:","\u0003ואסור בהנאה. \u0004אם הוא קבר של בנין לאפוקי קרקע עולם אינה נאסרת כדלעיל ריש הסימן:","\u0003מותר בהנאה. \u0004שהרי אין אדם אוסר דבר שאינו שלו ולאו כל כמיניה לאסור של רבים:","\u0003לא יעשנו כו'. \u0004דגנאי הוא למת לעשות כן:","\u0003לא יקבר כו'. \u0004עיין בטור דמסיק בשם הרמב\"ן דכיון דטעמא הוא משום כבוד אביו אפי' קרקע עולם נמי אסור:"],["\u0003ויש חולקין ומתירין. \u0004דס\"ל דלא אסרו בגמרא אלא קבר של בנין לחוד וכ' רש\"ל שהעולם נהגו איסור לישב על הקבר עד כאן. וכתב בהגהת אשר\"י דכל מה שנעשה לצורך המת ולכבוד המת אסור בהנאה ומתוך כך אסור למכור מצבה שנשברה ולפי דבריו אסור להשען על המצבה וא\"כ אסור לדרוך על גבי הקברים משום דאסור בהנאה עכ\"ל. ובפרק (הספינה) [המוכר פירות] (דף ק\"א) פי' רשב\"ם דנושאי המטה שדורסין ע\"ג המערות המוקפות מכל צד כשמביאין את המטה לחצר דבשביל הילוך לפי שעה לא קפיד ר\"ש עכ\"ל משמע דאין איסור כשדורסין ע\"ג הקברים לפי (דהכי) [שעה] בהילוך למקום שרוצים לילך שם:","\u0003אא\"כ מצא ראשו ורובו. \u0004פי' וכ\"ש אם נמצא כולו שלם. וכ' רש\"ל הא דאין נוהגין האידנא בדיני מת מצוה האלו לפי שאין הארץ שלנו ואין לנו רשות בכל מקום ואף אם נקבר אותו לשם יש לחוש שהעובדי כוכבים יחזרו ויוציאו אותו כדי לפשוט בגדיו מעליו או משום זלזול ע\"כ מוליכים אותו לבה\"ק מיוחד נ\"ל עכ\"ל:","\u0003וכן עושין ליולדת כו'. \u0004בתשו' מהרי\"ל סימן ס\"ה כתוב וז\"ל על אשה שנפלה מהגג ומתה הורה מהר\"ש אם דם יוצא ממנה אין לטהרה כי הדם יסתלק ממנה ומנהג פשוט לקבור בבגדים כל הרוגים בידי עובדי כוכבי' הנמצאי' לעלות חימה ולנקום נקם אבל יולדת שמתה נסתפקו אם מיתה בידי שמים היא כמו שאר חלאים כו' עכ\"ל. משמע ה\"ה ביולדת אם יוצא ממנה דם דאין לטהרה שלא יסתלק הדם דמ\"ש מנפלה. וכ' מו\"ח ז\"ל בזה יש חילוק בין נפלה מגג להרוג דבהרוג אף אם כבר פסק הדם בשעה שמצאוהו מ\"מ קוברין אותו בבגדיו להעלות חימה משא\"כ בנפלה ולא מתה אלא לאחר כמה ימים על מטתה וכן ביולדת שמתה לאחר ימים יש לטהרה כשאר מתים. וכתב עוד דמי שמת מחמת קור ושלג או נטבע במים בבגדיו דפושטין בגדיו ומטהרין אותו ומלבישין אותו בתכריכין ע\"כ. והמנהג לקבור בבגדים הנמצאים נטבעים וכן יולדת שמתה בר מינן בבגדיה והיותר תמוה שמלבישין בגדים ומנעלים ליולדת שמתה אפי' כמה ימים אחר לידתה והוא שלא כדין לפי ע\"ד:","\u0003ומקומו טהור. \u0004דלא גזרו עליו מפני הנזח ומיהו אסור בהנאה דאיסור דאורייתא הוא ולא פקע רש\"י. והא דאסור בהנאה היינו בקבר בנין כמ\"ש בריש סימן זה:"]],["הַחוֹפֵר כּוּךְ לַמֵּת, \u0010y0\u0011 פָּטוּר מִקְּרִיאַת שְׁמַע וּמִן הַתְּפִלָּה וּמִן הַתְּפִלִּין וּמִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה. וְאִם הֵם שְׁנַיִם, וְהִגִּיעַ זְמַן קְרִיאַת שְׁמַע, אֶחָד עוֹלֶה וְקוֹרֵא קְרִיאַת שְׁמַע וּמִתְפַּלֵּל, וְחוֹזֵר זֶה וְחוֹפֵר, וְעוֹלֶה חֲבֵרוֹ וְקוֹרֵא קְרִיאַת שְׁמַע וּמִתְפַּלֵּל. וְדַוְקָא כּוּךְ, דְּלֹא חָפִיר לֵיהּ אֶלָּא חַד, אֲבָל אִם הָיָה מָקוֹם שֶׁשְּׁנַיִם יְכוֹלִים לְהִתְעַסֵק בּוֹ כְּאֶחָד, פְּטוּרִים. \u0010y1\u0011\nמַרְחִיקִין הַקְּבָרוֹת מֵהָעִיר חֲמִשִּׁים אַמָּה.",["\u0003פטור כו'. \u0004דעוסק במצוה הוא ופטור משאר מצות:","\u0003מרחיקין כו'. \u0004כתב העט\"ז הטעם שלא יפגעו בו תמיד ויתעצבו ולא דק דהטעם הוא מפני שריחה רע וכדמשמע בלא יחפור ריש דף כ\"ה דקתני מרחיקין את הנבלות ואת הקברות ואת הבורסקי כו' וכן פירש\"י ושאר מפרשים שם וכ\"כ הרמב\"ם והמחבר בח\"מ סי' קנ\"ה סכ\"ג:"],[]],["\u0010y0\u0011 הַמּוֹכֵר קִבְרוֹ וְדֶרֶךְ קִבְרוֹ, מְקוֹם מַעֲמָדוֹ וּמְקוֹם הֶסְפֵּדוֹ, \u0010y1\u0011 בָּאִים בְּנֵי הַמִּשְׁפָּחָה וְקוֹבְרִין אוֹתוֹ בְּעַל כָּרְחוֹ שֶׁל לוֹקֵחַ, וּמַחֲזִירִין אֶת דָּמָיו.\nאִשָּׁה שֶׁיָּרְשָׁה קֶבֶר מִמִּשְׁפַּחְתָּהּ, נִקְבֶּרֶת בְּתוֹכוֹ הִיא, \u0010y2\u0011 אֲבָל לֹא יוֹצְאֵי יְרֵכָה; אֶלָּא אִם כֵּן רָאֲתָה אוֹתָם בְּחַיֶיהָ.\nאָבִיהָ אוֹמֵר: תִּקָּבֵר אֶצְלִי, וּבַעֲלָהּ אוֹמֵר: תִּקָּבֵר אֶצְלִי, תִּקָּבֵר אֵצֶל בַּעֲלָהּ. וְיֵשׁ גּוֹרְסִין תִּקָּבֵר אֵצֶל אָבִיהָ. וְאִם יֵשׁ לָהּ בָּנִים, וְאוֹמֶרֶת: אֵצֶל בָּנַי, קוֹבְרִין אוֹתָהּ אֵצֶל בָּנֶיהָ.\nאָבִיהָ אוֹמֵר: לֹא תִּקָּבֵר אֶצְלִי, וּבַעֲלָהּ אוֹמֵר: לֹא תִּקָּבֵר אֶצְלִי, \u0010y3\u0011 קוֹבְרִים אוֹתָהּ אֵצֶל בַּעֲלָהּ.",["\u0003המוכר קברו כו'. \u0004עי' בח\"מ ס\"ס רי\"ז:","\u0003באים בני המשפחה כו'. \u0004שגנאי להם שבני המשפחה לא יהיו קבורים במקום אחד כמנהגם ואע\"ג דמי שצוה שאל יספידוהו שומעין לו כדלעיל סי' שד\"מ סעיף י' שאני התם דאמר כן בשעת מיתה אבל הכא זוזי אנסוהו א\"נ התם לדידיה לחוד אבל הכא מקום הספדו יורשיו ובני משפחתו נספדים שם ואיכא פגם שלהן:","\u0003אבל לא יוצאי ירכה. \u0004מפני שבניה מתייחסים על שם משפחות אביהם וגנאי לבני משפחתם ליקבר אצלם. טור:","\u0003קוברים אותה אצל בעלה. \u0004מפני שחייב בקבורתה כמו שנתבאר בא\"ע סימן פ\"ט:"],[]],["קוֹבְרִים מֵתֵי \u0010y0\u0011 עוֹבְדֵי כּוֹכָבִים וּמְנַחֲמִים אֲבֵלֵיהֶם, מִפְּנֵי דַּרְכֵי שָׁלוֹם.\nלֹא יְהַלֵּךְ בְּבֵית הַקְּבָרוֹת אוֹ בְּתוֹךְ ד' אַמּוֹת שֶׁל מֵת וּתְפִלִּין בְּרֹאשׁוֹ, מִשּׁוּם לֹעֵג לָרָשׁ \u0005(מִשְׁלֵי יז, ה)\u0006, וְאִם הֵם \u0010y1\u0011 מְכֻסִים, מֻתָּר.\nלֹא יְהַלֵּךְ בְּבֵית הַקְּבָרוֹת אוֹ בְּתוֹךְ ד' אַמּוֹת שֶׁל מֵת, אוֹ שֶׁל קֶבֶר, וְסֵפֶר תּוֹרָה בִּזְרוֹעוֹ, וְיִקְרָא בּוֹ \u0010y2\u0011 אוֹ יִתְפַּלֵּל, וְהוּא הַדִּין עַל פֶּה אָסוּר לִקְרוֹת, אֶלָּא אִם כֵּן לִכְבוֹד הַמֵּת, כְּמוֹ שֶׁנִּתְבָּאֵר. \u0005וְעַיֵּן לְעֵיל סִימָן שד\"מ סָעִיף י\"ז.\u0006\nמֻתָּר לִכָּנֵס לְבֵית הַקְּבָרוֹת אוֹ לְתוֹךְ ד' אַמּוֹת שֶׁל מֵת אוֹ שֶׁל קֶבֶר, וְהוּא לָבוּשׁ צִיצִית, וְהוּא שֶׁלֹּא יְהֵא נִגְרָר עַל הַקֶּבֶר. אֲבָל אִם נִגְרָר, אָסוּר מִשּׁוּם: לֹעֵג לָרָשׁ \u0005(מִשְׁלֵי יז, ה)\u0006 בַּמֶּה דְּבָרִים אֲמוּרִים, בִּימֵיהֶם שֶׁהָיוּ מַטִּילִים צִיצִית בַּמַּלְבּוּשׁ שֶׁלּוֹבְשִׁים לְצֹרֶךְ עַצְמָן, \u0010y3\u0011 אֲבָל הָאִדָּנָא שֶׁאֵין אָנוּ לוֹבְשִׁין אוֹתוֹ \u0010c0\u0011 אֶלָּא לְשֵׁם מִצְוָה, אָסוּר, אֲפִלּוּ אֵינָם נִגְרָרִים. וְהָנֵי מִלֵּי כְּשֶׁהַצִּיצִיּוֹת מְגֻלִּים, אֲבָל אִם הֵם מְכֻסִים, מֻתָּר.\nיֵשׁ נוֹהֲגִין לִקְשֹׁר שְׁנֵי צִיצִיּוֹת שֶׁבִּשְׁנֵי כְּנָפַיִם זֶה עִם זֶה כְּשֶׁנִּכְנָסִים לְבֵית הַקְּבָרוֹת, וְלֹא הוֹעִילוּ כְּלוּם בְּתַקָּנָתָם \u0005וְעַיֵּן בא\"ח סִימָן כ\"ג.\u0006\nכֵּיוָן שֶׁהִרְחִיק ד' אַמּוֹת, קוֹרֵא וּמִתְפַּלֵּל, וַאֲפִלּוּ רוֹאֶה הַקֶּבֶר אוֹ בֵּית הַקְּבָרוֹת. וְאִם יֵשׁ שָׁם מְחִצָּה, מֻתָּר אַחַר הַמְּחִצָּה, סָמוּךְ אֲפִלּוּ תּוֹךְ ד' אַמּוֹת לַקֶּבֶר.",["\u0003קוברים כו'. \u0004היינו שמשתדלין בקבורת מתים עובדי כוכבים ועי' טור וב\"י:","\u0003לא יהלך כו'. \u0004עי' בא\"ח סי' מ\"ה ולעיל סי' רפ\"ב ס\"ד:","\u0003או יתפלל כו'. \u0004כתב מהרש\"ל דה\"ה קדיש צריך להרחיק ד' אמות ומביאו הדרישה וכ\"כ הב\"ח:","\u0003אבל האידנא כו'. \u0004כתב מהרש\"ל והעולם נוהגין היתר בטלית קטן וכ\"כ הב\"ח וסיים הטעם כיון שהציציות מכוסים:"],["\u0003אלא לשם מצוה אסור. \u0004כתב רש\"ל והעולם נהגו היתר בטלית קטן עיין בא\"ח סימן כ\"ג עכ\"ל:"]],["בֵּית הַקְּבָרוֹת, \u0010y0\u0011 אֵין נוֹהֲגִין בָּהֶן קַלּוּת רֹאשׁ; \u0005כְּגוֹן לִפָּנוֹת שָׁם (כָּל בּוֹ)\u0006 אוֹ לֶאֱכֹל וְלִשְׁתּוֹת שָׁם, וְאֵין קוֹרִין וְאֵין שׁוֹנִין שָׁם \u0005(סמ\"ג)\u0006, \u0010y1\u0011 וְאֵין מְחַשְּׁבִין שָׁם חֶשְׁבּוֹנוֹת. \u0005(בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006 ; וְאֵין מַרְעִין בָּהֶם בְּהֵמוֹת; וְאֵין מוֹלִיכִין בָּהֶם אַמַּת הַמַּיִם; וְלֹא יְטַיֵּל בָּהֶם לְקַפַּנְדְרִיָא \u0005(פי' לְמַעֲבָר מִצַד זֶה לְצַד זֶה)\u0006 ; וְלֹא יְלַקֵּט מֵהֶם עֲשָׂבִים; וְאִם לִקֵּט, שֶׁצָּרִיךְ לְלָקְטָן לְצֹרֶךְ בֵּית הַקְּבָרוֹת, \u0010y2\u0011 שׂוֹרְפָן בִּמְקוֹמָן. \u0005הַגָּה: וְכֵן אֵין לִקַּח מִקַּרְקַע עוֹלָם שֶׁל קֶבֶר, אַף עַל גַּב דְּמֻתָּר בַּהֲנָאָה (כֵּן מַשְׁמָע מֵהָרֹא\"שׁ וְהַמָּרְדְּכַי)\u0006. וְכָל זֶה אֵינוֹ אֶלָּא מִשּׁוּם כְּבוֹד הַמֵּתִים, וְלָכֵן אִם צָרִיךְ אוֹתוֹ לִרְפוּאָה, שָׁרֵי \u0005(ג\"ז בְּמָרְדְּכַי)\u0006. וְכֵן מֻתָּר לֵהָנוֹת מֵהָעֲשָׂבִים שֶׁעַל הַקְּבָרוֹת אוֹ פֵּרוֹת אִילָנוֹת שֶׁעֲלֵיהֶם לְצֹרֶךְ הַקְּבָרוֹת, כְּגוֹן שֶׁהַמּוֹשֵׁל עוֹבֵד כּוֹכָבִים מַרְעֶה בְּהֵמוֹת עַל הַקְּבָרִים וְאִי אֶפְשָׁר לִמְחוֹת בְּיָדוֹ כִּי אִם בְּהוֹצָאָה מְרֻבָּה, וְאֵין יַד הַקָּהָל מַשֶּׂגֶת, מוֹכְרִים דְּבָרִים אֵלּוּ כְּדֵי לְהַצִּיל הַקְּבָרוֹת מִיַּד עוֹבְדֵי כּוֹכָבִים, שֶׁזֶּהוּ כְּבוֹד הַמֵּתִים \u0005(ת\"ה סִימָן רפ\"ד ומהרי\"ו סִימָן נ')\u0006. וְאִם אֵין דְּבָרִים עַל הַקְּבָרוֹת לִמְכֹּר לְצֹרֶךְ הַהוֹצָאָה, אִם יַד הַקָּהָל מַשֶּׂגֶת וְשֶׁבְּיָדָם לִמְחוֹת בְּהוֹצָאָה מוּעֶטֶת, צְרִיכִין לִמְחוֹת, אִם אֵין חֲשָׁשׁ בַּדָּבָר שֶׁהַמּוֹשֵׁל יִתְגָּרֶה בָּהֶם עַל יְדֵי זֶה; אֲבָל בְּלָאו הָכֵי אֵין צְרִיכִין לִמְחוֹת \u0005(ג\"ז שָׁם)\u0006.\nאִילָנוֹת שֶׁנּוֹטְעִין בְּבֵית הַקְּבָרוֹת, \u0010y3\u0011 מֻתָּר לְלַקֵּט פֵּרוֹתֵיהֶם, מֵאַחַר שֶׁאֵינָם עַל הַקְּבָרוֹת עַצְמָם.\nקֶבֶר חָדָשׁ, נִמְדָּד וְנִמְכָּר וְנֶחְלָק; וְהַיָּשָׁן, אֵינוֹ נִמְדָּד וְלֹא נִמְכָּר וְלֹא נֶחְלָק.",["\u0003אין נוהגין כו'. \u0004מפני כבודן של מתים:","\u0003ואין מחשבין שם חשבונות. \u0004אפילו של רבים. שם:","\u0003שורפן במקומן. \u0004אין זה כבוד של מתים אלא קנסא או משום שלא יחשדוהו שמוליכם לבהמתו:","\u0003מותר ללקט כו'. \u0004כתב הב\"ח מה שנוהגין הגבאים ללקוט הפירות למכרם והדמים לצדקה ומקצתם נותנים אותם לעובד כוכבים שומר בה\"ק והעובד כוכבים יעשה לו ג\"כ גן בבה\"ק צריך ליזהר שלא יהא אילן נטוע ולא הגן זרוע אלא במקום שאין בו ספק קבר:"],[]],["הַכֹּהֵן \u0010c0\u0011 מֻזְהָר שֶׁלֹּא לִטָּמֵא בְּמֵת, וְלֹא לְכָל טֻמְאוֹת הַפּוֹרְשׁוֹת מִמֶּנּוּ, וְלֹא \u0010c1\u0011 לְגוֹלָל, וְלֹא לְדוֹפֵק, וְלֹא לְאֵבֶר מִן הַחַי שֶׁאֵין בּוֹ כְּדֵי לְהַעֲלוֹת אֲרוּכָה אִם הָיָה \u0010y0\u0011 מְחֻבָּר, וְלֹא לְאִילָן הַמֵּסֵךְ עַל הָאָרֶץ וַעֲנָפָיו מֻבְדָּלִים זֶה מִזֶּה וְטֻמְאָה תַּחַת אֶחָד \u0010c2\u0011 מֵהֶן וְאֵין יָדוּעַ תַּחַת אֵיזֶה, אוֹ אֲבָנִים הַיּוֹצְאִים מֵהַגָּדֵר וְטֻמְאָה תַּחַת אֶחָד מֵהֶם וְאֵין יָדוּעַ תַּחַת אֵיזֶה, וְכֵן שָׂדֶה שֶׁנֶּחֱרַשׁ בּוֹ קֶבֶר וְאֵין יָדוּעַ מְקוֹמוֹ \u0010y1\u0011 \u0010c3\u0011 וְכָל אֶרֶץ הָעַמִּים, אָסוּר לְכֹהֵן לִטָּמֵא בָּהֶן. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּכֹהֲנִים אֲסוּרִים \u0010y2\u0011 לִטָּמֵא לְחֶרֶב שֶׁנִּטְמָא בְּמֵת (כָּל בּוֹ בְּשֵׁם סֵפֶר יְרֵאִים ותשו' רַשְׁבָּ\"א בְּשֵׁם רַבּוֹתֵינוּ הַצָרְפָתִים)\u0006, וְיֵשׁ מְקִלִּין \u0005(תְּשׁוּבַת רַשְׁבָּ\"א שָׁם בְּשֵׁם הָרַאֲבַ\"ד וְעַיֵּן בתוס' דְּנָזִיר בַּאֲרִיכוּת)\u0006, וְכֵן נָהֲגוּ לְהָקֵל וְאֵין נִזְהָרִין מִזֶּה.",["\u0003ולא לאילן כו'. \u0004אע\"פ שאין כאן אלא ספק טומאה הכהן מוזהר עליו ומוכח מכאן דאילן המיסך על המת דיכול לעמוד תחת ענפיו שאינם מאהילין על המת דהרי כאן לא אסר לעמוד תחת האילן אלא מטעם דאינו ידוע תחת איזו. פרישה:","\u0003וכל ארץ העמים כו'. \u0004פירוש בזמן שהיה א\"י בטהרה אסור לכהן לילך מארץ ישראל לארץ העמים שהוא חוצה לארץ שהיו העובדי כוכבים קוברים מתיהם בכל מקום:","\u0003ליטמא לחרב. \u0004דחרב הרי הוא כחלל וה\"ה לכל מיני מתכות:"],["\u0003הכהן מוזהר שלא ליטמא למת. \u0004) אפי' נפל כדאיתא פרק בתרא דאהלות שמא קברו בו נפלים:","\u0003לגולל. \u0004הוא אבן שנותנין על הקבר לציון ודופק היינו לפעמים סומכין אבן באבנים קטנים. טור:","\u0003ואין ידוע תחת איזה כו'. \u0004משמע דאם ידוע תחת איזה מהם מותר לכהן לעמוד תחת אחרים שאינם מאהילים:","\u0003וכל ארץ העמים כו'. \u0004זה קאי בזמן שהיה טהרות בא\"י:"]],["מִי שֶׁנִּשְׁבְּרָה מַפְרַקְתּוֹ \u0010y0\u0011 וְרֹב בָּשָׂר עִמָּהּ, וְכֵן מִי שֶׁנִּקְרַע \u0010y1\u0011 מִגַּבּוֹ כְּדָג, אֲפִלּוּ עֲדַיִן הוּא חַי, חָשִׁיב כְּמֵת, וּמְטַמֵּא. אֲבָל גּוֹסֵס, וּמִי שֶׁנִּשְׁחֲטוּ בּוֹ ב' סִימָנִים אוֹ פָּצוּעַ פְּצָעִים הַרְבֵּה, אֵינָם מְטַמְּאִין, עַד שֶׁתֵּצֵא נַפְשָׁם; \u0010y2\u0011 וּמִכָּל מָקוֹם אָסוּר לִכָּנֵס לְבַיִת שֶׁיֵּשׁ בּוֹ גּוֹסֵס. \u0005וְיֵשׁ מַתִּירִין, (ר\"ן סוֹף מַ\"ק וּמָרְדְּכַי פֶּרֶק אֵלּוּ מְגַלְּחִין בְּשֵׁם בה\"ג)\u0006, \u0010y3\u0011 וְטוֹב לְהַחְמִיר.",["\u0003ורוב בשר עמה כו'. \u0004ומשמע בש\"ס דחולין (דף כ\"א) דבזקן אפילו בלא רוב בשר מטמא באהל וכ\"כ מהרש\"ל פ\"ק דחולין סימן מ\"ד ומשמעותו התם דאם נעשה גיסטרא שנחתך לרחבו בצואר כולה או בשדרה עד חללה או שנחלק לשנים מטמא באוהל וכ\"כ מהרש\"ל שם:","\u0003מגבו כו'. \u0004אבל מלפניו לא:","\u0003ומ\"מ אסור ליכנס כו'. \u0004פי' אע\"פ שטומאה אין כאן חילול יש כאן:","\u0003וטוב להחמיר. \u0004והב\"ח כתב דמדינא צריך ליזהר ואין כאן מקום לפסוק לקולא ע\"ש מיהו נראה דא\"צ להקיצו ולהגיד לו כשיש גוסס כמו שצריכין להקיצו כשיש מת כדלקמן סי' שע\"ב וכן אם הגידו לו והוא ערום מותר להמתין עד שילבש עצמו ואח\"כ יצא וקרוב הדבר לומר שא\"צ לצאת כלל מבית שיש בו גוסס דהכי משמע לישנא דאסור ליכנס לבית כו' משמע דוקא ליכנס אסור אלא שנכון להחמיר ולצאת כי מדברי המרדכי ושאר פוסקים משמע דאין חילוק:"],[]],["\u0010y0\u0011 אָסוּר לְכֹהֵן לִכָּנֵס תַּחַת אֹהֶל שֶׁהַמֵּת תַּחְתָּיו, אֲפִלּוּ הוּא גָּדוֹל הַרְבֵּה, וַאֲפִלּוּ לְבַיִת אַחֵר אוֹ לַעֲלִיָּה אַחֶרֶת, הַפְּתוּחִים לְאוֹתוֹ בַּיִת \u0010c0\u0011 בְּנֶקֶב שֶׁיֵּשׁ בּוֹ טֶפַח עַל טֶפַח, וּבַיִת לְאוֹתוֹ בַּיִת, עַד עוֹלָם; וְאִם סָתַם הַנֶּקֶב, מֻתָּר לוֹ לִכָּנֵס לַבַּיִת \u0010y1\u0011 הָאַחֵר, שֶׁהַסְתִימָה חוֹצֶצֶת, אֲפִלּוּ לֹא בִּטְּלוּ לִהְיוֹת שָׁם עוֹלָמִית. וְהָנֵי מִלֵּי, שֶׁסָתַם כָּל הַנֶּקֶב; אֲבָל אִם לֹא סָתַם כָּל הַנֶּקֶב, אֶלָּא מִעֲטוֹ מִטֶּפַח, אִם נְתָנוֹ לִהְיוֹת שָׁם עוֹלָמִית, מְמַעֵט וְחוֹצֵץ בִּפְנֵי הַטֻּמְאָה שֶׁלֹּא תַּעֲבֹר; וְאִם לָאו, אֵינוֹ מְמַעֵט. \u0005הַגָּה: \u0010y2\u0011 \u0010c1\u0011 וְכָל דָּבָר הַמְקַבֵּל טֻמְאָה אֵינוֹ חוֹצֵץ בִּפְנֵי הַטֻּמְאָה (הַגָּהַת אַלְפָסִי פֶּרֶק בְּנֵי הָעִיר ובהל' טֻמְאָה לְהָרִי\"ף וְרַמְבַּ\"ן וְרֹא\"שׁ וּמָרְדְּכַי רֵישׁ פֶּרֶק לֹא יַחְפֹּר)\u0006. וְלֹא מִקְרֵי סְתִימָה בְּחַלּוֹן, \u0010c2\u0011 אֶלָּא אִם כֵּן יָכוֹל לַעֲמֹד בְּלֹא סְמִיכָה \u0005(ג\"ז שָׁם)\u0006.\nאֲרֻבָּה שֶׁבֵּין בַּיִת לַעֲלִיָּה וְאֵין בָּהּ פּוֹתֵחַ טֶפַח, וְכַזַּיִת מֵהַמֵּת לְמַטָּה בַּבַּיִת כְּנֶגֶד \u0010y3\u0011 \u0010c3\u0011 הָאֲרֻבָּה, הַבַּיִת טָהוֹר וְהָעֲלִיָּה טְמֵאָה. \u0010y4\u0011\nשְׁנֵי חֲדָרִים פְּתוּחִים לְבַיִת, וּבְכָל אַחַת חֲצִי זַיִת מֵהַמֵּת, וְדַלְתוֹתֵיהֶם נְעוּלִים, \u0010y5\u0011 \u0010c4\u0011 הַבַּיִת טָמֵא וְהֵם טְהוֹרִים; וְאִם נִפְתְחוּ, גַּם הֵם טְמֵאִים. \u0010y6\u0011\nחָצֵר הַמֻּקֶּפֶת זִיזִין וְאַכְסַדְרָאוֹת, וְטֻמְאָה בְּאֶחָד מֵהַבָּתִּים, \u0010y7\u0011 \u0010c5\u0011 אִם כָּל פִּתְחֵי הַבָּתִּים וְהַחַלּוֹנוֹת נְעוּלִים, טֻמְאָה יוֹצֵאת לְתַחַת הַזִּיזִין וְהָאַכְסַדְרָאוֹת; \u0005וְהַטַּעַם, מִשּׁוּם דְּהוֹאִיל וְסוֹף הַטֻּמְאָה לָצֵאת דֶּרֶךְ שָׁם, רוֹאִין כְּאִלּוּ יָצְאָה; \u0010y8\u0011 וְלָכֵן יֵשׁ מַחְמִירִין לְכֹהֲנִים לֵילֵךְ דֶּרֶךְ שַׁעַר הָעִיר שֶׁסּוֹף הַמֵּת לָצֵאת מִשָּׁם (פִּסְקֵי מהרא\"י סִימָן כ\"ה וְכָל בּוֹ)\u0006, \u0010c6\u0011 וְיֵשׁ מַתִּירִין \u0005(שָׁם הֵבִיא בְּשֵׁם י\"א)\u0006, וְהַמֵּקֵל לֹא הִפְסִיד בְּמָקוֹם שֶׁלֹּא נָהֲגוּ לְהַחְמִיר; \u0010y9\u0011 וְאִם נִפְתַּח \u0010y10\u0011 חַלּוֹן אוֹ פֶּתַח מִצַּד הָאַחֵר, וְאוֹתָם שֶׁל צַד הֶחָצֵר כֻּלָּם נְעוּלִים, אֵין הַטֻּמְאָה יוֹצֵאת לְתַחַת הַזִּיזִין. \u0010c7\u0011 וְאִם נִפְתַּח גַּם כֵּן אֶחָד מֵהֶן לְצַד הַזִּיזִין, הַטֻּמְאָה יוֹצֵאת מֵהַבַּיִת לְתַחַת הַזִּיזִין. \u0010y11\u0011 וְכֵן אִם טֻמְאָה תַּחַת הַזִּיזִין, \u0010c8\u0011 נִכְנֶסֶת מִתַּחְתֵּיהֶן לַבַּיִת; \u0010y12\u0011 לָכֵן \u0010y13\u0011 גַּגִּים הַבּוֹלְטִים לְמַעְלָה לְחוּץ עַל פִּתְחֵי הַבָּתִּים, וְטֻמְאָה בְּאֶחָד מֵהַבָּתִּים, \u0010c9\u0011 כָּל הַבָּתִּים \u0010y14\u0011 שֶׁפִּתְחֵיהֶם פְּתוּחִים, טְמֵאִים. \u0005הַגָּה: ב' גַּגִּין שֶׁאֵין נוֹגְעִין זֶה בָּזֶה, אַף עַל פִּי שֶׁאֵין בֵּינֵיהֶם רַק פָּחוֹת מִג', לֹא הָוֵי חִבּוּר לַטֻּמְאָה, דְּלֹא אַמְרִינָן לָבוּד לְהַחְמִיר (מהרי\"ו בִּפְסָקָיו)\u0006. \u0010y15\u0011 וְאִם הָיוּ זֶה לְמַעְלָה מִזֶּה, אַף עַל פִּי שֶׁאֵינָן נוֹגְעִים, אַמְרִינָן: חָבוּט רָמֵי, וּכְאִלּוּ נוֹגְעִים \u0005(נ\"י בְּהִלְכוֹת \u0010y16\u0011 טֻמְאָה רי\"ף)\u0006. הַכֹּהֲנִים \u0010c10\u0011 אֵינָן יְכוֹלִין לָכֹף לִקְרוֹבֵי הַמֵּת שֶׁיּוֹצִיאוּ הַמֵּת מִמְּקוֹמוֹ, כְּדֵי שֶׁהֵם יִהְיוּ רַשָּׁאִים לִכָּנֵס לְבֵיתָם, אִם לֹא בְּמָקוֹם שֶׁדֶּרֶךְ לְהוֹצִיא כָּל הַמֵּתִים \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ס\"ה)\u0006. \u0010y17\u0011\nאָסוּר לִקְרַב בְּתוֹךְ אַרְבַּע אַמּוֹת שֶׁל מֵת אוֹ שֶׁל קֶבֶר. בַּמֶּה דְּבָרִים אֲמוּרִים, שֶׁאֵין הַקֶּבֶר מְסֻיָּם בִּמְחִצּוֹת גְּבוֹהוֹת י' טְפָחִים, אֲבָל אִם הוּא מְסֻיָּם בִּמְחִצּוֹת גְּבוֹהוֹת עֲשָׂרָה טְפָחִים, אוֹ בְּחָרִיץ עָמֹק י' טְפָחִים, אֵין צָרִיךְ לְהַרְחִיק מִמֶּנּוּ אֶלָּא ד' טְפָחִים. \u0010y18\u0011 \u0005וּמֻתָּר לְכֹהֵן לַעֲמֹד אֵצֶל בַּיִת שֶׁיֵּשׁ בּוֹ מֵת, וּמֻתָּר לִגֹּעַ בִּכְתָלָיו, וּבִלְבַד שֶׁלֹּא יְהֵא שׁוּם דָּבָר מַאֲהִיל עָלָיו (תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן קל\"ו)\u0006.\nמֵת הַמּוּנָח בִּסְפִינָה, \u0010y19\u0011 אִם הִיא קְטַנָּה שֶׁמִּתְנַדְנֶדֶת כְּשֶׁדּוֹרְכִין בָּהּ, \u0010c11\u0011 אָסוּר לְכֹהֵן לִכָּנֵס בָּהּ.",["\u0003אסור לכהן ליכנס כו'. \u0004כתב הרוקח סימן שס\"ו אשת כהן שמעוברת מותרת ליכנס באהל המת דס\"ס הוא שמא נפל הוא או שמא נקבה הוא:","\u0003שהסתימה חוצצת כו'. \u0004ובמשנה פ\"ח דאהלו' אית' דסריגות שבחלונות חוצצין פירוש שאם היה חלון בין ב' בתים והטומאה בבית א' והיו עצים דקים או טסי ברזל בחלונות בסירוג בקלוע אע\"פ שיש ביניהם אויר כיון שאין שם פותח טפח אף באחד מהנקבים הרי זה חוצץ ולא יצטרפו נקבי הסריגות לפותח טפח וכ\"פ הרמב\"ם סוף פרק י\"ג מהל' טומאת המת וכ\"כ הסמ\"ג סוף עשין רל\"א וכן כתב הב\"ח:","\u0003וכל דבר המקבל טומאה כו'. \u0004עי' ברמב\"ם בהלכות כלים מהו הן הדברים המקבלים טומאה או לאו:","\u0003הבית טהור כו'. \u0004דטומאה בוקעת ועולה כיון שהיא מונחת תחת הארובה ואע\"פ שאין בארובה פותח טפח ואין הטומאה מתפשטת לצדדי הבית הואיל שיש מקום לטומאה לעלות לארובה שכנגדה ואינה חוזרת ויורדת לבית כיון שאין בארובה טפח שאם היה בארובה טפח הוה חשבינן בית ועליה כמו חדר א':","\u0003שני חדרים פתוחים לבית. \u0004היינו כששני החדרים כל א' מהם פתחו פתוח לבית בפני עצמו ושניהם הם לפנים מן הבית:","\u0003הבית טמא כו'. \u0004דסוף הטומאה לצאת ורואה אני כאלו שני החצאי זיתים מונחים בבית ואין הטומאה נכנסת בחדרים כיון שדלתותיהם נעולות אבל כשנפתחו חזרה הטומאה מן הבית לחדרים:","\u0003חצר המוקפת כו'. \u0004כלומר בתי החצר המה סביב לצד החצר ולא לצד הב' דהיינו אחורי החצר לכל בית יש ב' פתחי' וכן חלונות א' פתוח לצד השני לאחורי החצר אשר אין שם זיזין:","\u0003אם כל פתחי הבתים והחלונות נעולים כו'. \u0004כצ\"ל ור\"ל כשכל דלתות הבית שהטומאה בתוכו נעולות מכל צד בין אותו צד הפתוח לחצר בין אותו צד שאחורי החצר אז טומאה יוצאת לתחת הזיזין ואכסדראות וכל מה שתחתיהן טמא דכיון דאין מקום לטומאה לצאת אלא דרך שם חזינן לטומאה כאלו כבר הוא שם דגזרו חכמים על כל המקומות שסוף הטומאה לצאת כאחד ואין ידוע דרך איזה יצא אבל לא נ\"מ מידי במה ששאר פתחי הבית פתוחים או נעולים דמ\"מ הטומאה יוצאת לתחת הזיזין והאכסדראות אי נמי אשמועינן דאם היו שאר פתחי הבית פתוחים אז היו ג\"כ הבתים הפתוחים טמאים וכל מה שבתוכה היה טמא כי הטומאה יוצאת לתחת הזיזין כיון שסוף הטומאה לצאת ואח\"כ יוצאת מתחת הזיזין ונכנסת לבתי' הפתוחי':","\u0003ולכן יש מחמירין כו'. \u0004אמנם אין להחמיר בבית של צדוק הדין דאדרבה אותו הפתח בא לטמא את האהל פסקי מהרא\"י שם וכתב בספר מע\"מ ד' קי\"ח סוף ע\"א שטעם זה יספיק בבית צדוק הדין שאין בו אלא פתח אחד שבו מכניסין ומוציאין את המת אבל אם יש בו ב' פתחים שבפתח האחד מכניסין ובפתח אחד מוציאין כמו שיש בבית צדוק הדין שבק\"ק פראג יש להחמיר שאין לכהני' ליכנס באותו הפתח שמוציאין ממנו המת:","\u0003ואם נפתח חלון או פתח מצד האחר. \u0004שאחורי החצר שבאותו הפתח יצא שהרי לצד החצר הוא נעול:","\u0003חלון או פתח. \u0004שיש בו ד' על ד' כן הוא בעט\"ז והוא מדברי הרא\"ש:","\u0003וכן אם טומאה תחת הזיזין נכנסת מתחתיהן לבית. \u0004היינו כשהבית פתוח:","\u0003וכן גגין הבולטין כצ\"ל. \u0004כתב מהרש\"ל והאחרונים בשם תשובת מהר\"ח א\"ז במקום שיש עירוב ועשו קורות שיש בהקיפן טפח ממבוי למבוי וראשי הקורות נכנסין תחת הגגין שמכאן ומכאן והטומאה נכנסת תחתיה והקורה מביאה הטומאה מגג לגג ומתפשטת בכל הבתים מכאן ומכאן א\"כ כשיש מת ב\"מ באחד מן הבתים נמצא שהמבוי מחובר ע\"י קורות העירוב ע\"כ וכ' הב\"ח שהקור' צריך שתהי' עגולה ג\"ט כדי שתהיה רחבה טפח דכל שיש בהקיפו ג\"ט רחבו טפח:","\u0003גגין הבולטין כו'. \u0004כתב דרישה הכל תלוי בגג שע\"ג הפתח הבית שהמת בתוכו ומשם באה מהגג שלפני הפתח להגג של הבית ואף שאין הבתים סמוכים זה אצל זה אלא שיש מחיצה ביניהם מן הצד אף שאין עליה גג קטן אם הקורה מונח עליה רחב טפח דהא כשהטומאה באה מהפתח לגג והגג מקיף את כל הבית הרי טומאה מתחת הגג שהוא מן תחת אותה מחיצה ואותה מחיצה מביא הטומאה תחת גג הבית הסמוך לה ונכנסה תוכו דרך (בתים) [פתחים] או חורין אבל כשאין גג ע\"ג פתח הבית שהמת בתוכו אף שיש לו גג מן הצד והוא מאהיל על הבתים שסמוכים לה מכל צד אין הטומא' באה שם ומה שרגילין לומר אם הוא מוקף חומה גבוהה אותה חומה אין בה נ\"מ כ\"א לענין צד שלפני הפתח או אם אין חומה גבוהה לפני פתח הבית שהמת בתוכו ויש חומה בבית הסמוך לו בצד שלפני הפתח באופן שלא יביא הטומאה מגג של מת לתחת הגג שלפני פתח הבית הסמוך אף שמן הצד ליכא חומה מפסקת והגגות מאהילין זה על זה לית לן בה עכ\"ל. ול\"נ שצריך שיהא גג אהל טפח מתחלה עד סוף אבל כל שיש ביניהם הפסק בחומה גבוהה אף שהיא עבה כמה טפחים כיון שאין אהל טפח שוב אין לטומאה מקום לילך וכן הסכימו רבים וגדולים) וכן המנהג פשוט:","\u0003שפתחיהן פתוחים טמאים. \u0004אבל אם הן סתומים טהורים ולפ\"ז אף כשהטומאה באה באיזה בית אם דעת הכהנים לסגור פתח בתיהן וחלונותיהן ולא לצאת מהן עד אחר הוצאת המת אין צריכין לצאת מבתיהן וכ\"כ בדרישה ולפ\"ז כהן שהוא בבית או בחדר שהטומא' נוגעת אליו והוא נעול בדלת וחלונות ונודע לו שהגיע הטומא' אליו אסור לצאת מן החדר עד אחר הוצאת המת שהרי כל זמן שלא נפתח החדר לא נכנסת הטומאה לתוכו וכשיפתח תכנס הטומאה לתוכו:","\u0003ואם היו זה למעלה מזה כו'. \u0004כתב הב\"ח דאפילו היה הגג העליון הרבה למעלה משלשה טפחים כיון שיש בגגו טפח אמרי' חביט רמי כו' ע\"ש:","\u0003הכהנים אינם יכולים כו'. \u0004כתב הב\"ח נ\"ל דאם הוא נפל דליכא משום כבוד כופין אותו להוציאו ממקומו כדי שיכנסו לביתם:","\u0003אסור לקרב תוך ארבע אמות כו'. \u0004כ' הדרישה מכאן מוכח דאפילו תוך ד' אמות של מת המונח לפנינו אסור לקרב כהן משום דתופס ד\"א או משום גזרה שמא יגע במת עצמו אף שהוא מונח לפנינו והכל יודעים שאסור ליגע במת מ\"מ לא מחשב כמו מחיצה גבוהה י' טפחים וכן המרדכי והג\"מ כתבו דאסור וב\"י הביאם ע\"ש ולא כמו ששמעתי מקילין לכהן הדורש לעמוד עליו אפי' תוך ארבע אמות של מת כיון שהמת מונח לפנינו וניכר עכ\"ל. ולי נראה שטעם אותן המקילין דדוקא במת שמונח בבית בהך גוונא דמיירי הטור וכן בהך דמרדכי וה\"מ במת המונח בספינה דהוי כמונח בבית שהוא מקום קביעתו תופס ארבע אמות אבל לא המונח על המטה וכן מחלק הרוקח סימן שט\"ו וז\"ל מת בביתו סתום אסור לכהן ליקרב בתוך ארבע אמות דמת תופס ד' אמות לטומאה כשהוא בקבר אבל כשהוא במטה שמוציאין אותו ובעת צדוק הדין מעמידין אותו אינו תופס דאין שם קביעותו עכ\"ל. ומ\"ש מעמידין אותו נראה דכ\"ש כשנושאין אותו על המטה דאין תופס:","\u0003ומותר לכהן לעמוד כו'. \u0004ואין חילוק בין בית פתוח או סתום לענין זה והב\"ח כתב דיש להחמיר דאף בבית סתום אם פרץ פצימתו ומת בתוכו תופס ד' אמות סביביו וצריך להרחיק ארבע אמות מהבית ע\"כ וכ\"כ הרוקח סימן שט\"ו מת בבית סתום אסור לכהן ליקרב בתוך ד' אמות:","\u0003אם היא קטנה שמתנדנדת כשדורכים בה אסור ליכנס בה. \u0004אפי' חוץ לד\"א של מת כיון שא\"א שלא יסיט הטומאה אבל אם היא גדולה שאינה מתנדנדת כשדורכים בה מותר חוץ לארבע אמות של מת:"],["\u0003בנקב שיש בו טפח. \u0004פירוש במקום אחד אבל אם אינו במקום אחד אלא ע\"י צירוף יש טפח כגון מה שקורין גיגאטי\"ר שעשוי ע\"י סירוג ויש שם נקבים קטנים הרבה אין זה מביא הטומאה והוא משנה פרק י\"ג דאהלות הסירוגות מצטרפות למלא מקדח דברי בית שמאי וב\"ה אומרים עד שיהא כמלא מקדח במקום אחד ומבואר שם בין להביא הטומאה ובין להוציא ופשוט הוא דדין שיעור מקדח בחלון שעשוי לאורה שוה לשיעור טפח בחלון העשוי לתשמיש כמבואר בפ' הנ\"ל וכ\"פ רמב\"ם להדיא פרק י\"ד דטומאת מת דדוקא בעינן טפח במקום א' ואם לאו הרי היא כסתומה. וכ\"כ הרמב\"ם בפירוש המשנה בפרק ח' דאהלות גבי סריגת החלון ועיין מה שכתבתי מזה לקמן סעיף ד' על דברי הדרישה:","\u0003וכל דבר המקבל טומאה. \u0004זה קאי גם ארישא דסותם כל הנקב דמועיל אפילו אין מבטלו שם מ\"מ בעינן שלא יהא דבר המקבל טומאה אלא צריך לסתמו בעץ או באבן דבר שאינו כלי כמ\"ש בית יוסף בשם לשון הרי\"ף:","\u0003אא\"כ יכול לעמוד בלא סמיכה. \u0004בפרק לא יחפור סוף (בבא בתרא דף י\"ט) כתבו התוס' טעם לזה דכל שצריך סמיכה מקרי סתימת עראי ועוד טעם אחר שהסמיכה לא תהיה על ידי דבר שהוא מקבל טומאה אע\"פ שהדבר עצמו שסותם הוא אינו מקבל טומאה מכל מקום כיון שהדבר שסומכו מקבל טומאה הוה כאלו הוא עצמו מקבל טומאה וכ\"פ הר\"ש והרמב\"ם בפ\"ו דאהלות במשנה דקוברי המת שהיו עוברין כו' ופשוט הוא לדברי הכל כל שמושיב באותו חלון עצים ואבנים כל כך הרבה עד שכותלי החלון מחזיקים אותם זה ודאי מהני וחוצץ דאין זה בכלל סמיכה כלל כנ\"ל פשוט:) \u0003ומעשה \u0004שהי' בטומאה שהיתה בבית סמוך לבית הכנסת באופן שהיתה נכנסת דרך חלון ביהכ\"נ של נשים וצוה מורה אחד לסתום החלון באותו פרוכת קטן שתלוי שם בקרסי הברזל תמיד שהוא לצניעות שתולין אותו שם הנשים בשעה שאינן צריכין לראות ביהכ\"נ של אנשים ואמרתי שטעה המורה דבהדיא אמרינן במתניתין דפ' ח' דאהלות דסדין ומחצלת העשוין כאהלים שחוצץ בפני הטומאה אבל אם אין עשוים כאהלים אין חוצץ וכתב שם הר\"ש כל שהוא עשוי כאהל חוצץ אע\"ג דמקבל טומאה ואם אין עשוי כאהל אינו חוצץ וביאר ברמב\"ם פרק י\"ג דטומאת מת שאין עשוי כאהל אלא מתוח בלבד ואין להם שיפוע אהלים ואין שם כתלים עכ\"ל וה\"ה כאן שאין כאן אלא סתימה על החלון ולא כותל ולא אהל ותו דאותו הפרוכת תלוי בטבעות של ברזל נמצא דהברזל עושה הקיום ובהדיא כ' רמב\"ם פרק י\"ח דטומאת מת אם הגיף א' את הדלת וסמכו במפתח כדי שלא יטמא את הבית וכן אם היה אדם מבפנים או בחוץ סומך את הדלת אם יכול הדלת לעמוד בפני עצמו הבית טהור ואם לאו הבית טמא לפי שהאדם והכלים הוא שחוצץ בפני הטומאה והאדם והכלים מביאין את הטומאה ואינם חוצצין עכ\"ל וכן כתבו התוס' בפרק לא יחפור (בבא בתרא דף י\"ט) בד\"ה רואין כו' לענין אם סגר הדלת במפתח דבעינן דבר החוצץ עומד על ידי דבר שאינו מקבל טומאה ולשונם אזכיר בסמוך ה\"ה נמי כאן שהטבעות של ברזל מעמידין את הפרוכת והם כלים וא\"ל ממ\"ש במשנה דכלים דף כ\"א דטבעות כלים טהורות דהא איתא בפרק במה בהמה (שבת דף נ\"ב) ברש\"י וז\"ל ומיהו עם הרצועה מקבלת טומאה אלא שאין מקבלת טומאה לעצמה עכ\"ל ממילא כאן שהטבעות עם אותו פרוכת הוה ודאי שם כלי עליהם והוה כמפתח ותו נראה דאפי' אם אינו מקבל טומאה מ\"מ אינו חוצץ וזה מוכח ממה דקשה תרי משניות אהדדי לכאורה דבפי\"א דכלים שנינו כל כלי מתכות שיש לו שם בפני עצמו טמא חוץ מן הדלת ומן הנגר ומן המנעול והפותה שתחת הציר (והציר) [והצינור] שנעשו לקרקע פי' הרמב\"ם שתשמישן עם הקרקע משמע מזה דכלים אלו ובתוכן מנעול שנועל בו בית לא מקבל טומאה ובפרק ו' דאהלות שנינו קוברי המת שהיו עוברים באכסדרה והגיף אחד מהם את הדלת וסמכו במפתח פירש הרמב\"ם שהיה שער הבית קצת פתוח והחזיק אחד מהנושאים לנעול שער הבית במפתח אשר בו עכ\"ל אם יכול הדלת לעמוד בפני עצמו טהור פירש ר\"ש דאם יכולה לעמוד בלא סמיכת המפתח ה\"ל מפתח כמאן דליתיה ואם לאו טמא דכל דבר הנסמך באדם וכלים אין חוצץ בפני הטומאה משמע מזה דמפתח שהדלת נעול בו מקבל טומאה וע\"כ אינו חוצץ ובתוס' פרק לא יחפור (בבא בתרא דף י\"ט) כתוב טעם למה אמרינן דאם ינטלו אינם יכולים לעמוד דאינו חוצץ וז\"ל והיינו טעמא דסתימת עראי היא כיון שאינו יכול לעמוד בפני עצמו אי נמי משום דבעינן דבר החוצץ עומד על ידי דבר שאינו מקבל טומאה ומיהו בפי' משניות מצא ר\"י דמפרש דאפי' במפתח שאינו מקבל טומאה איירי ומטעמא דלא חשיב אהל לחוץ בפני הטומאה כיון שעומד ע\"י כלי אע\"ג דאינו מקבל טומאה עכ\"ל נ\"ל דהתו' באו לפרש המשנה דאהלות שזכרנו ולתרץ קושיא שזכרנו דתחלה תירצו דמפתח לאו דוקא אלא כל דבר שבעולם אם בא לסמוך בו דבר החוצץ אינו חוצץ ולא תליא מילתא במקבל טומאה אלא סתימה מעלייתא בלא שום סמיכה בעינן ואח\"כ כתבו דדוקא מפתח נקט שהוא מקבל טומאה ולא מיירי בההוא גוונא דמיירי בכלים שזכרנו דהתם המנעול אין מקבל טומאה דנעשה תחלה לצורך תשמיש קרקע אבל באהלות מיירי ממפתח דעלמא שלא נעשה לקרקע והוא מקבל טומאה ואח\"כ כתבו שבפי' המשניות ס\"ל דודאי מפתח דוקא נקט דאינו חוצץ כיון שהוא על כל פנים כלי מה שאין כן במידי דאינו כלי לגמרי ולא תליא מילתא בטומאה ומתני' דאהלות מיירי אפי' במפתח שנעשה לקרקע דאין מקבל טומאה הנה לפנינו דמפתח שנועלין בו הדלת פשיטא דאינו חוצץ ואפי' אינו מקבל טומאה אלא אפי' שאר דבר שאינו כלי לגמרי אין יכול לסמוך בו הדלת לתירוצא קמא ובמרדכי פרק לא יחפור כתב כתירוצא קמא דצריך שיהיה עומד שם בחלון בלא סמיכת דבר אחר וכ\"כ רמ\"א בסי' זה בסמוך. ואע\"ג דבמרדכי הביא שם עוד מתני' דהגפת מפתח לא מהני אע\"פ שאינו מקבל טומאה לא נתכוין שיהיה עכ\"פ כלי דהא פסק כתירוצא קמא כמו שזכרתי אלא בא לתקן בזה שלא נימא דבטומאה תליא מילתא תדע דהא לא זכר שיהיה דוקא כלי. ממילא נשמע מזה דלא מועיל חציצת דלת או חלון כל שאינה יכולה לעמוד בלא צירים של ברזל או שאר דבר של ברזל אע\"פ שהם לצורך קרקע וזה מועיל שלא יקבלו טומאה מ\"מ אינם חוצצים כמו שזכרנו ולפ\"ז הא דאמרי' בסעיף ד' דמהני נעילת מפתחים לחצון היינו אם הם בענין שיכולים לעמוד בלא שום סמיכה ולא ביש לה צירים של ברזל דאל\"כ אינם חוצצין דהוה כמפתח של משנה דאהלות ועיין מה שאכתוב לקמן שלא לסמוך להקל כדברי הדרישה לנעול הבית כדי לחוץ. ועל כן בודאי אינו חוצץ ומטעם זה יראה דאם יש סתימה בחלון של ברזל שהוא עשוי כמו סבכה שקורין בלשון אשכנז גיגאטי\"ר והוא של ברזל אינו מועיל כיון שהוא מקבל טומאה) ואינו עשוי כעין אהל ועיין מה שכתבתי מזה בסעיף ד' שעל פי זה אין להתיר לכהן להיות בבית ולסתום הפתח והחלון:","\u0003הבית טהור והעליה טמאה. \u0004לפי שהטומאה עולה כנגדה מאחר שהיא מונחת תחת הארובה והוה כאלו אין שם אהל עליה ואין לה כח לירד ולהחזיר הטומאה לבית מאחר שאין בה פותח טפח כ\"פ הרא\"ש בהלכות קטנות ואין להקשות יהיה פתח הבית ההוא טמא משום שסוף הטומאה לצאת דרך אותה פתח כמו דאמרינן אחר כך בסי' זה דכאן שאין שם רק כזית מן המת ועליו אין אהל הוה כמונח ברשות הרבים ואינו מטמא כלל בבית כנ\"ל פשוט ובחנם האריך על זה בדרישה.) ומזה למדנו שאם יש מת בבית בחדר שאין עליו אהל אין לכהן להיות בכל הבית הן מטעם שהטומאה חוזרת ויורדת הן מטעם שסוף הטומאה לצאת דרך הפתח דלא הקיל הרא\"ש כאן אלא אם אין פתח רק פחות מטפח:","\u0003הבית טמא והם טהורים. \u0004הואיל ואין בכל אחד אלא חצי זית שהוא חצי שיעור והבית טמא דסוף הטומאה לצאת דרך שם ורואין כאלו שני חצאי זיתים מונחים בבית ואין הטומאה נכנסת בחדרים כיון שדלתותיהם נעולים: \u0003דלא אמרינן לבוד להחמיר. \u0004לכאורה משמע אבל להקל אמרינן לבוד והוא תמוה דא\"כ לא תמצא טומאה יוצאת או נכנסת דרך נקב דנימא כלבוד דמי והוה סתום ועיינתי במקור דכתב מהרי\"ו וז\"ל הר\"ר יעקב שאלני אם אמרינן לבוד גבי אהל המת כגון ב' בתים הסמוכים זה לזה בבנין פחות מג' טפחים ומת באחד מהם והשבתי לו דלא אמרי' לבוד וראיה מפ\"ק דעירובין גבי עור העסלא ובסוכה פרק הישן גבי קורות הבית שאינם מכוונות עי\"ש בגמרא ורש\"י עכ\"ל ועיינתי בפ\"ק דעירובין כתבו שם התוספות דבטומאה לא אמרינן לבוד ולא זכרו מחומרא כלל ובפרק הישן (סוכה דף כ\"ב) אמרינן אבל אין ביניהם פותח טפח ביניהן ועל גביהן טהור פרש\"י וה\"ה באין מכוונות שע\"ג טהור ותחתיה טמא דכיון שיש בה טפח מביאה טומאה לכל אורך שתחתיה עכ\"ל משמע דהטומאה יורדת למטה ומטמא מה שבתחתונה דאין שם חציצה ואי ס\"ד דאמרינן לבוד לקולא אמאי יטמא מה שבתחתונה אע\"פ שלא אמרינן חבוט רמי מ\"מ להוי כסתום ויהיה חציצה לטהר מה שלמטה אלא ודאי לטומאה לא אמרינן כלל לבוד וא\"כ צריכין לומר מ\"ש רמ\"א כאן דלא אמרינן לבוד פי' אפי' להחמיר:","\u0003אם כל פתחי הבתים נעולים כו'. \u0004כן הוא גם בטור אבל הוא לאו דוקא דהעיקר תלוי בפתח הבית שהמת בתוכו דסוף הטומאה לצאת דרך שם ע\"כ מטמא אע\"פ שהוא נעול אבל בבתים אחרים מאי מעלה יש בנעילתם וכן מה שכ' אח\"כ דאותם של צד החצר כולם נעולים הלא אפי' אם הם פתוחים רק שאותו פתח של בית שהטומאה בתוכו הוא נעול אין הטומאה יוצאת תחת הזיזין כיון שיש פתח לצד אחר להבית שהמת בתוכו ורבים אומרי' שיש ט\"ס בדברי הטור וצ\"ל אם כל פתחי הבית כו' וכן אח\"כ צ\"ל ואותו של צד החצר נעול וכן הוא ברא\"ש דלא זכר רק אותו פתח שהמת בתוכו שיש לו שני פתחים אחד לצד הזיזין ואחד לצד המבוי ותליא מילתא איזה מהם פתוח דאמרינן שם תצא הטומאה:","\u0003ויש מתירין. \u0004טעם לזה דלא אמרינן סוף הטומאה לצאת טמא אלא באותו פתח שמוציאין תחילה מתוך האהל ולא מתוך האויר הואיל ובאותה יציאה נטהר האוהל ע\"כ אותו פתח יטמא ולא מכאן ואילך:","\u0003ואם נפתח ג\"כ אחד מהם. \u0004פי' אותו שהמת בתוכו נפתח ג\"כ לצד הזיזין דהיינו שנפתח אותו הבית משני צדדיו על כן גם תחת הזיזין טמא אף על פי ששאר בתים שתחתיה נעולים וכמו שזכרנו בסמוך:","\u0003נכנסת מתחתיהן לבית. \u0004פי' כל בית שפתחו פתוח לצד הזיזין:\n\u0003רש\"ל \u0004הביא הג\"ה אחת וז\"ל אני אומר במקום שיש עירוב ועשו קורות שיש בהם היקף טפח ממבוי למבוי וראשי הקורות נכנסין תחת הגגין שמכאן ומכאן והטומא' נכנסת תחתיה הקורה מביאה את הטומאה מגג לגג ומתפשטת בכל הבתים מכאן ומכאן אם כן כשיש מת ב\"מ באחד מן הבתים אין כהן רשאי להיות בשום בית מן הבתים שבמבואות המחוברות ע\"י קורה של העירוב וזוכרני כשהיינו לומדים בבית מורי ר\"מ ז\"ל והיה פתח פתוח מחצר הרב לחצר בית הכנסת ומשקוף הפתח היה מגיע מצד א' תחת תקרת הבית שהיה בו מת ואסר מורי לכהנים לצאת ולבוא דרך אותו הפתח כל זמן שהמת בבית ע\"כ לשון תשובת מהר\"ר חיים. וכתוב בדרישה ונראה לע\"ד וגם שמעתי דהיינו דוקא במחיצה שיש עליה גג קטן או מחיצה שמשקוף עליה רוחב טפח ויש בו פתח פתוח לצאת ולבוא דרך תוכה דנמצא שם משקוף עליה כיון שנכנסין ויוצאים דרך תוכה אבל מחיצה מושכת מבית לבית ואין גג עליו וגם אין פתח פתוח בתוך המחיצה אפי' אם הקורה המונח עליו בעובי טפח וגם גגות הבתים משני צדדי המחיצה בקצה שלהם מאהילים עליהם מכל מקום אינו מביא הטומאה כיון דבאמצעית המחיצה אין עליה גג ולא שם תקרה כיון שאין שם פתח נקרא כסתום באמצע ואין בו כח להוליך הטומאה עכ\"ל משמע מדבריו באם יש מחיצה פנויה בלא גג עליה ויש פתח באמצעיתה מביאה את הטומאה מבית לבית כיון שמראש המחיצה יש שם אוהל מן הגג של בית הטמא אע\"פ שאין הפתח מגיע עד אותו החלק שהוא תחת הגג והיינו כיון שיש שם משקוף עליו מאחר שנכנסין ויוצאין שם ותמיהני מאד על דבר זה כיון שיש הפסק בחלק המחיצה שהוא סותם קודם התחלת הפתח בין החלק שמגיע תחת הגג ובין פתח מי יכניס הטומאה מן תחת הגג להפתח שבאמצע והלא אפילו ביש הפסק בפחות משלשה לא אמרינן לבוד להחמיר וע\"כ לא אסרו שם בתשובה שהבאתי בשם רש\"ל אלא שהתקרה היתה מונחת בלא מחיצה תחתיה מן תחת הגג של בית הטמא לתחת הגג של בית אחר נמצא שהיה חלל תחת התקרה מן בית הטמא לבית האחר בלי הפסק מחיצה סתומה מה שאין כן בהך מילתא שיש הפסק מחמת המחיצה הבנויה על הארץ ואין בה בליטה טפח סמוך לחלק שתחת הגג השני ודאי אין כאן הבאת טומאה כלל מידי דהוה אשני בתים סמוכים ואין גג בולט למעלה מהם דאין נכנסת הטומאה מבית לבית אע\"פ ששניהם פתוחים דהא גגים בולטים בעינן כמ\"ש בשולחן ערוך כאן ונראה דאין לחוש לטומאה כשיש מחיצה בנויה אע\"פ שיש פתח באמצעה לא בתוך המחיצה כולה אלא אם כן יש עליה גם כן גג קטן או בליטה טפח מן אותו צד שנכנס תחת בית הטמא לחלק המגיע תחת הגג השני:","\u0003כל הבתים שפתחיהם פתוחים כו'. \u0004הטעם שכיון שיש גגין על הפתח של הבתים כולם ובאחד מהן יש שם מת הטומאה הולכת דרך פתח ביתו תחת הגגין ונכנסת לבתים אחרים שהם פתוחים תחת הגג שלהם אבל אם אין גג על הפתחים וכותלי הבתים שאצל הבית הטמא הם סתומים עד הגג שלהם מן החצר אין טומאה לאותן הבתים אע\"פ שהם פתוחים לצד הרחוב אע\"פ שגג אחד יש מבית הטמא מן הצד לבית שאצלו מ\"מ אין מקום לטומאה להכניס לבית האחר כיון שבצד ששם הפתח אין שם גג. וכתוב בדרישה אף אם הטומאה באה מפתח בית הטמא לתחת גגו ומשם מגג לגג של בית אחר מ\"מ אם דעת הכהנים לסגור פתח בתיהן וחלונותיהן ולא לצאת משם עד אחר הוצאת המת אין צריכין לצאת מבתיהן וגדולה מזאת עשיתי במת עמי ביום השבת וצויתי להוציאו ולהניחו במרתף שתחת הבית ופתח המרתף לצד חוץ ולא היה גג על גבי [פתח] המרתף והכהנים נשארו בבית אלא שיש להקשות אהנחת מת במרתף ודלת המרתף סגורה בפתח המרתף הא בעינן שיהיה ביציאת הקבר פותח טפח וכמ\"ש בסימן שע\"ב דהאידנא דכולו סתום אפילו יש בו אויר טפח כל שכנגדו טמא) וה\"נ אף שבמרתף הוא חלל גדול סביב המת מכל מקום ליכא ביציאת הפתח דהמרתף פותח טפח כל זמן שהוא סגור והכהנים בבית ע\"ג המרתף מיהו אם בהדלת הפתח שבמרתף עשוים חורין חורין כמו שקורין בל\"א גיגאטי\"ר אף שאין בחור א' טפח מ\"מ כיון שיש בהצטרפות החורין יחד פתוח כמה טפחים יש צד להקל שהוא בכלל יציאתה פותח טפח עכ\"ל ותמהני על פה קדוש יאמר כן נגד המשניות ערוכות הבאתים בתחלת סימן זה שאין נקבי הגיגאטי\"ר מצטרפות לטפח. ובפירוש אמרו במשנה פרק י\"ב דאהלות שאין הטומאה יוצאת מהבית כשאין שם נקב [טפח] במקום א' וא\"כ נשארה הטומא' בבית והוה כקבר סתום ומטמא עד לרקיע והיאך כ' לקולא מחמת הצטרפות הנקבים להוציא הטומאה כיון שהמרתף סגור מכל צד אע\"ג דאין הדלת מקרי חציצה כמו שאכתוב בסמוך מ\"מ המרתף סתום ע\"כ אין לסמוך על היתר זה דהצטרפות הנקבים כלל. גם מה שכתב להתיר לכהנים לסגור פתחיהם וחלון זהו דבר הנמנע דהא סגירת הפתח ע\"י מפתח הוא ואינו חוצץ כדאיתא לעיל ר\"ס זה סעיף א' הבאתיו בשם רמב\"ם) ותו דהא הדלת תלויה ע\"י צירים של ברזל ודבר כזה אינו חוצץ כמו שכתבתי לעיל בראיה ברורה ומעולם לא שמענו לנהוג בהיתר זה לכהנים וכמה הקילו רבותינו להיות חס על הכהן שלא להגיד לו עד שילביש עצמו ולא נהגו בהיתר זה אלא ודאי דליתיה. כן נלע\"ד ברור:","\u0003אינם יכולים לכוף כו'. \u0004הטעם בתשובת מהרי\"ל וז\"ל אבל אי רגילין להשהותם משום כבודם להשמיע עליו רבים שיתעסקו עמו א\"נ לטהרו בביתו א\"כ היאך מצינו לכופן לזלזל נגד המנהג ולא שייך הכא על המזיק להרחיק עצמו כיון דאנוס הוא דהואיל ונהוג נהוג עכ\"ל. ומו\"ח ז\"ל כתב דאם הוא נפל דלא איכא משום כבוד כופין אותו להוציאו מביתו בשביל הכהנים דעל המזיק להרחיק עצמו ע\"כ. ואני תמהתי על דברי התשובה הנ\"ל דהא אין שייך כלל כאן לכוף אותו להוציאו מטעם על המזיק להרחיק עצמו כדאיתא בח\"מ סימן קנ\"ה בש\"ע סעיף ל\"ב בהיה לו אילן סמוך לבור חבירו אין בעל הבור יכול לומר הרי שרשי האילן מפסידים לבורי שזה נזק הבא מאליו לאחר זמן ובשעה שנטעו אינו מזיקו כו' ק\"ו כאן שאין עושה לעולם שום מעשה להזיקו אלא מן השמים הוא היאך יכוף אותו ונראה דעל זה נמי נתכוון בתשובה במה שכתב דאונס הוא כלומר דנעשה ממילא ומה שסיים אחר זה דהואיל ונהוג נהוג ובלאו הכי ראוי להגיה כן דהיאך שייך לומר אונס כיון שהוא מנהג ולפי זה גם בנפל אין שייך לכופו להוציאו כיון שאין שם מזיק עליו אלא שאם הכהן רוצה לשלוח שם להוציא הנפל אל מקום אחר אין אבי הנפל יכול לעכב כיון שהוא ניזוק וזה לא חסר כלל כן נראה לע\"ד:","\u0003אסור לכהן כו'. \u0004דא\"א לו שלא יסיט הטומאה. רש\"ל הביא בשם הגהת מיי' וא\"ז שפסקו כרבינו משולם להתיר אפי' בספינה קטנה רק שלא יהא תוך ד' אמותיו ויש להחמיר כיון שגם ב\"י הביא זה להחמיר:"]],["אַף עַל פִּי שֶׁהַכֹּהֵן אָסוּר \u0010y0\u0011 לִכָּנֵס לְבֵית הַפְּרָס, \u0005(פֵּרוּשׁ שָׂדֶה שֶׁנֶּאֱבַד בָּהּ קֶבֶר, וְשֶׁנֶּחֱרַשׁ בָּהּ קֶבֶר, וְשִׁעוּרָהּ מֵאָה אַמָּה)\u0006 אוֹ לְאֶרֶץ הָעַמִּים, אִם הָיָה צָרִיךְ לֵילֵךְ שָׁם לִשָּׂא אִשָּׁה אוֹ לִלְמֹד תּוֹרָה, וְאֵין לוֹ דֶּרֶךְ אַחֶרֶת, \u0010c0\u0011 יָכוֹל לַעֲבֹר דֶּרֶךְ שָׁם, אֲפִלּוּ אִם מוֹצֵא לִלְמֹד בְּמָקוֹם אַחֵר. וְכֵן אָבֵל הָעוֹבֵר דֶּרֶךְ שָׁם, יָכוֹל לֵילֵךְ אַחֲרָיו לְנַחֲמוֹ. וְכֵן מִטַּמֵּא בְּטֻּמְאָה שֶׁל דִּבְרֵיהֶם, לָדִין עִם עוֹבְדֵי כּוֹכָבִים וּלְעַרְעֵר עִמָּהֶם, מִפְּנֵי שֶׁהוּא כְּמַצִּיל מִיָּדָם, וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. \u0005הַגָּה: כֹּהֵן שֶׁשּׁוֹכֵב \u0010y1\u0011 עָרֹם, וְהוּא בְּאֹהֶל עִם הַמֵּת וְלֹא יָדַע, אֵין לְהַגִּיד לוֹ, אֶלָּא יִקְרְאוּ לוֹ סְתָם, שֶׁיֵּצֵא כְּדֵי שֶׁיַּלְבִּישׁ עַצְמוֹ תְּחִלָּה. אֲבָל אִם כְּבַר הִגִּידוּ לוֹ, אָסוּר לְהַמְתִּין עַד שֶׁיִּלְבַּשׁ עַצְמוֹ. וְדַוְקָא אִם הוּא בְּאֹהֶל הַמֵּת, שֶׁהוּא טֻמְאָה דְּאוֹרַיְתָא, אֲבָל אִם הוּא בְּבֵית הַפְּרָס אוֹ אֶרֶץ הָעַמִּים, שֶׁהוּא טֻמְאָה דְּרַבָּנָן, יַלְבִּישׁ עַצְמוֹ תְּחִלָּה, דְּגָדוֹל כְּבוֹד הַבְּרִיּוֹת (ת\"ה סִימָן רפ\"ה)\u0006, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן ש\"ג לְעִנְיַן כִּלְאַיִם. כֹּהֵן שֶׁהוּא יָשֵׁן, וּמֵת עִמּוֹ בָּאֹהֶל, \u0010y2\u0011 צְרִיכִין לַהֲקִיצוֹ וּלְהַגִּיד לוֹ כְּדֵי שֶׁיֵּצֵא \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ס\"ט)\u0006.\nקִבְרֵי עוֹבְדֵי כּוֹכָבִים, נָכוֹן לִזָּהֵר הַכֹּהֵן מִלֵּילֵךְ עֲלֵיהֶם; \u0005(מהר\"מ וְתוס' פ' הַמְקַבֵּל)\u0006 \u0010y3\u0011 \u0005אַף עַל פִּי שֶׁיֵּשׁ מְקִלִּין\u0006 \u0005(רַמְבַּ\"ם והגמי\"י בְּשֵׁם ס' יְרֵאִים)\u0006. \u0005וְנָכוֹן לְהַחְמִיר. אֲבָל קֶבֶר שֶׁל מוּמָר\u0006 \u0005(לַעֲבוֹדַת כּוֹכָבִים)\u0006, \u0005מְטָּמֵא כְּשֶׁל יִשְׂרָאֵל\u0006 \u0005(רַשְׁבָּ\"א סי' קצ\"ד ורמ\"ב)\u0006.",["\u0003לבית הפרס. \u0004הוא שדה שנחרש בו קבר:","\u0003והוא באוהל כו'. \u0004ודוקא) אם הוא באוהל המת כו' נראה דוקא נקט באוהל המת אבל אם בבתים הסמוכים לבית שהמת בתוכו אע\"פ שהן ג\"כ טמאים כדלעיל סימן שע\"א ס\"ד מ\"מ י\"ל דאינו אלא טומאה דרבנן כדאיתא בטור סי' זה ופוסקים עב\"י דדבר תורה אוהל שיש בו חלל פותח טפח טהור ע\"ש ודוק וכשהבית שהמת בתוכו סתום מכל צד נמי ליכא בבתים הסמוכים טומאה אלא מדרבנן משום דסוף הטומאה לצאת ואם כן בבתים הסמוכים בכל ענין ילביש עצמו תחלה:","\u0003צריכין להקיצו ולהגיד לו. \u0004דאפילו בלא שהייה קעבר הכהן ואע\"ג דלא ידע מ\"מ איסורא עביד בשוגג ואף על גב דאינו עושה מעשה איסורא איכא ולאחריני דידעי מצוה להפרישו עכ\"ל תשובת מהרי\"ל סי' ס\"ט ס\"ל אע\"ג דאינו מעשה ולאו שאין בו מעשה אין לוקין עליו איסור דאוריי' מיהא איכא ולפי זה משמע דבאיסורא דרבנן א\"צ להקיצו וא\"כ למ\"ש בסמוך דהיכא דאינו באוהל עצמו אם המת רק בבית הסמוך לה ליכא אלא איסורא [דרבנן] אין צריך להקיצו ואפשר לזה דקדק הרב ומת עמו באוהל צריכים להקיצו וע\"ל סי' שע\"ג ס\"ק א':","\u0003אף על פי שיש מקילין. \u0004מטעם דכתיב אדם כי ימות באוהל וגו' ואתם קרוים אדם ואין העובדי כוכבים קרוים אדם אבל במגע ומשא י\"א דאפילו המקילים אוסרים וכן נראה דעת ב\"י ע\"ש:"],["\u0003יכול לעבור דרך שם. \u0004אבל לא על הקברות אפילו לדבר מצוה משום דהאידנא כולם סתומים ויש בהקברים חלל הרבה על כן טומאה בוקעת ועולה עד לרקיע ואפילו נגד צד הריקן שבו מה שאין כן אי הוה סתום ואין בתוכו חלל טפח אינו מטמא אלא כנגד הטומאה ממש לא נגד צד הריקן שבו:"]],["כְּשֵׁם שֶׁהַכֹּהֵן מֻזְהָר שֶׁלֹּא לִטָּמְאוֹת, כָּךְ \u0010c0\u0011 מֻזְהָרִים הַגְּדוֹלִים עַל הַקְּטַנִּים. \u0005וְדַוְקָא לְטַמְּאוֹתָן בְּיָדַיִם, אֲבָל אִם הַקְּטַנִּים מִטָּמְאִין מֵעַצְמָן, \u0010y0\u0011 עַיֵּן בְּא\"ח סִימָן שמ\"ג אִי צָרִיךְ לְהַפְרִישָׁן (הָרַשְׁבָּ\"א סִימָן קכ\"ח ומהרי\"ו, וְטוּר בְּשֵׁם הָרַמְבַּ\"ם כָּתַב כָּאן דְּאֵין צָרִיךְ)\u0006.\nאֲפִלּוּ בַּעַל מוּם, \u0010y1\u0011 מֻזְהָר מִלִּטַּמֵּא, אֲבָל חָלָל וְכֹהֶנֶת, מֻתָּרִים לִטָּמֵא.\nכָּל הַמֵּתִים הָאֲמוּרִים בַּפָּרָשָׁה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, מִצְוָה שֶׁיִּטָּמֵא לָהֶם; וְאִם לֹא רָצָה, מְטַמְאִים אוֹתוֹ עַל כָּרְחוֹ, אֶחָד הָאִישׁ \u0010y2\u0011 וְאֶחָד הָאִשָּׁה.\nאֵלּוּ הֵם הַקְּרוֹבִים שֶׁמִּטָּמֵא לָהֶם: אִשְׁתּוֹ נְשׂוּאָה שֶׁהִיא כְּשֵׁרָה; \u0010y3\u0011 אֲבָל פְּסוּלָה, אוֹ גְּרוּשָׁה, אוֹ אֲרוּסָה, לֹא אוֹנֵן וְלֹא מִטָּמֵא לָהּ; וְכֵן הִיא, לֹא אוֹנֶנֶת \u0010y4\u0011 וְלֹא מִטָּמְאָה לוֹ. וּמִטָּמֵא לְאִמּוֹ, \u0010y5\u0011 אֲפִלּוּ נִתְחַלְּלָה; וְלִבְנוֹ וּלְבִתּוֹ דְּקִים לֵיהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו, \u0010y6\u0011 אוֹ שֶׁהֵם מִשְּׁלֹשִׁים יוֹם וָאֵילָךְ, אֲפִלּוּ הֵם פְּסוּלִים; חוּץ מִבְּנוֹ וּבִתּוֹ מִשִּׁפְחָה אוֹ כּוּתִית; וּלְאָחִיו וְלַאֲחוֹתוֹ מֵאָבִיו, אֲפִלּוּ הֵם פְּסוּלִים, אֶלָּא אִם כֵּן הֵם בְּנֵי שִׁפְחָה אוֹ כּוּתִית; אֲבָל לְאָחִיו וְלַאֲחוֹתוֹ מֵאִמּוֹ, אֵינוֹ מִטָּמֵא. \u0005וְכֵן אֵינוֹ מִטָּמֵא\u0006 לַאֲחוֹתוֹ אֲרוּסָה, אֲפִלּוּ הִיא אֲרוּסָה לְכֹהֵן; וְלֹא לַאֲנוּסָה \u0010y7\u0011 וּמְפֻתָּה; אֲבָל מִטָּמֵא לַאֲחוֹתוֹ אֲרוּסָה שֶׁנִּתְגָּרְשָׁה, וּבוֹגֶרֶת, וּמֻכַּת עֵץ; וּמִטָּמֵא לְשׁוֹמֶרֶת יָבָם, אֲפִלּוּ אִם כָּתַב בִּכְתֻבָּתָהּ: אִי מִיתַת בְּלֹא בָּנִים תֶּהְדַּר כְּתֻבָּתֵךְ לְבֵי נָשָׁא \u0005(פֵּרוּשׁ לְבֵית אָבִיהָ)\u0006.\nכָּל אֵלּוּ שֶׁמִּטָּמֵא לָהֶם, \u0010y8\u0011 אֲפִלּוּ שֶׁלֹּא \u0010y9\u0011 לְצֹרֶךְ. וְיֵשׁ אוֹמְרִים דְּדַוְקָא לְצֹרֶךְ. \u0005הַגָּה: וְלַסְּבָרָא הָרִאשׁוֹנָה, אֲפִלּוּ מֵת לוֹ מֵת בְּשַׁבָּת, שֶׁאִי אֶפְשָׁר לְקָבְרוֹ בּוֹ בַּיּוֹם, שָׁרֵי לִטָּמְאוֹת לוֹ וּלְשָׁמְרוֹ, כְּדֵי שֶׁלֹּא יְהֵא מֻטָּל בְּבִזָּיוֹן (ת\"ה סי' רפ\"ג)\u0006 ; וְנָכוֹן לְהַחְמִיר כַּסְּבָרָא הָאַחֲרוֹנָה, שֶׁלֹּא לִטָּמְאוֹת רַק לְצֹרֶךְ קְבוּרָה וּלְהָבִיא לוֹ אָרוֹן וְתַכְרִיכִין. \u0005(שָׁם בְּשֵׁם תּוֹסָפוֹת שנ\"ץ)\u0006.\nאֵינוֹ מִטָּמֵא לָהֶם, אֶלָּא \u0010y10\u0011 עַד שֶׁיִּסְתֹּם הַגּוֹלֵל. \u0005וְאִם דַּעְתּוֹ לְפַנּוֹתוֹ, מֻתָּר לִטָּמֵא לוֹ לְצֹרֶךְ, עַד שֶׁיִּסְתֹּם גּוֹלֵל שֵׁנִי (תְּשׁוּבַת הָרַשְׁבָּ\"א סִימָן רצ\"ב)\u0006.\nאָסוּר לְכֹהֵן לְהִתְטַמֵּא לְמֵת, אֲפִלּוּ בְּעֵת שֶׁמִּטָּמֵא לִקְרוֹבָיו. לְפִיכָךְ כֹּהֵן שֶׁמֵּת לוֹ מֵת, צָרִיךְ לִזָּהֵר וּלְקָבְרוֹ בְּסוֹף בֵּית הַקְּבָרוֹת, כְּדֵי שֶׁלֹּא לִכָּנֵס לְבֵית הַקְּבָרוֹת וְלֹא יִתְטַמֵּא בְּקִבְרוֹת אֲחֵרִים כְּשֶׁיִּקְבֹּר מֵתוֹ. \u0005הַגָּה: \u0010y11\u0011 וְדַוְקָא לְאַחַר שֶׁפָּרַשׁ מִמֵּתוֹ, אֲבָל בְּעוֹד שֶׁהוּא עוֹסֵק בְּמֵתוֹ, מֻתָּר לִטָּמְאוֹת אַף לַאֲחֵרִים (טוּר)\u0006.\nכֹּהֵן שֶׁפָּרְשׁוּ אֲבוֹתָיו מִדַּרְכֵי צִבּוּר, כְּגוֹן הַמַּסוּרוֹת, אֵינוֹ מִטָּמֵא לָהֶם; וְלֹא לַהֲרוּגֵי בֵּית דִּין; וְלֹא לְמִי שֶׁמְּאַבֵּד עַצְמוֹ לָדַעַת, וְלֹא לְסָפֵק, כְּגוֹן שֶׁנִּתְעָרֵב וְלָדָהּ בִּוְלַד חֲבֶרְתָּהּ אוֹ סָפֵק בֶּן ט' לָרִאשׁוֹן אוֹ בֶּן ז' לָאַחֲרוֹן.\nאֵין הַכֹּהֵן מִטָּמֵא לְאֵבֶר מִן הַחַי מֵאָבִיו, וְלֹא לְעֶצֶם מֵעַצְמוֹת אָבִיו. וְכֵן הַמְלַקֵּט עֲצָמוֹת, אֵינוֹ מִטָּמֵא לָהֶם, אַף עַל פִּי שֶׁהַשִּׁדְרָה \u0010y12\u0011 קַיֶּמֶת. חָסֵר מִמֶּנּוּ כָּל שֶׁהוּא, אֲפִלּוּ הוּא מֻנָּח אֶצְלוֹ, אֵינוֹ מִטָּמֵא לוֹ, שֶׁאֵינוֹ מִטָּמֵא אֶלָּא לְשָׁלֵם. וְיֵשׁ מִי שֶׁאוֹמֵר דְּהָנֵי \u0010y13\u0011 מִלֵּי כְּשֶׁחָסֵר לְאַחַר מִיתָה, אֲבָל אִם חָסַר מִמֶּנּוּ אֵבֶר בְּחַיָּיו, וּמֵת, מִטָּמֵא לוֹ, אַף עַל פִּי שֶׁאֵינוֹ שָׁלֵם. \u0005וְיֵשׁ אוֹמְרִים שֶׁאֵינוֹ מִטָּמֵא לְהָרוּג, דְּמִקְרֵי חָסֵר (כָּל בּוֹ בְּשֵׁם ר\"ש מאוירא)\u0006 וְנָכוֹן לְהַחְמִיר.",["\u0003עיין באו\"ח סימן שמ\"ג כו'. \u0004משמע כמו דאמרינן התם דא\"צ להפרישן הוא הדין הכא מיהו הביא הרב שם די\"א דהיינו דוקא שלא הגיע לחינוך ע\"ש ובאגודה פרק חרש כתב נ\"ל על תינוקות הישנים באוהל המת אין מחייבים להקיצם ולהוציאם אך מפני חינוך טוב הוא עכ\"ל והביאוהו האחרונים:","\u0003אבל חלל כו'. \u0004כתב הב\"ח דוקא חלל דאורייתא אבל של דבריהם כגון שנולד מחלוצה אסור לטמא ואם הוא נולד מספק חלוצה הוי כהן גמור לכל דבר ויתבאר בא\"ע סימן ז' ע\"ש:","\u0003ואחד האשה. \u0004שהיתה כהנת מצוה לה לטמאות:","\u0003אבל פסולה או גרושה. \u0004פי' אפי' יש לו בנים ממנה. מרדכי וכ\"כ האחרונים:","\u0003ולא מיטמאה לו. \u0004כלומר אינה מחוייבת לטמא לו אבל הרשות בידה לטמא:","\u0003אפי' נתחללה. \u0004כגון אחר שנולד כהן זה ממנה נשאת לכהן כשהיא גרושה:","\u0003או שהם מל' יום ואילך. \u0004לאפוקי ספק נפל דאין מטמאין לו וה\"ה לאחיו ולאחותו הקטנים שהן ספק נפלים אין מטמא להם:","\u0003אבל מטמא לאחותו הארוסה אחר שנתגרשה. \u0004מן האירוסין:","\u0003אפילו שלא לצורך. \u0004מיטמא ומצוה ליטמא:","\u0003וי\"א דוקא לצורך. \u0004קבורה או להביא לו ארון ותכריכים ואז מצוה ליטמא אבל שלא לצורך אסור לטמאות:","\u0003עד שיסתום הגולל בו'. \u0004ע\"ל ריש סי' שע\"ה בטור מהו גולל שרש\"י פי' גולל היינו כיסוי הארון ור\"ת פי' גולל הוא אבן שנותנים על הקבר כו' ע\"ש ובב\"ח שם כתב דנקטינן כרש\"י וכתב הרמב\"ן בת\"ה ומביאו הטור שם דלפירש\"י כשנותנים אותו בבית בארון וסותמין הכסוי במסמרים ע\"ד ליתן הארון בכוך או בקבר הוי סתימה כו' והוא תמה עליו בת\"ה דהיאך אפשר לומר שאם סתמו ארונו בבית שלא יטמא בנו עליו כו' ומביאו ב\"י שם ולפעד\"נ דמה שפירש\"י בכל מקום גולל היינו כסוי הארון אין ר\"ל אפילו סתמו בבית אלא ר\"ל משיסתם כסוי הארון בקבר תדע דבפרק שואל (שבת ד' קנ\"ב ע\"ב) אמרינן כל שאומרי' בפני המת יודע עד שיסתום הגולל (ופירש\"י גם כן התם גולל הוא כסוי שנותנים על ארונו) דכתיב וישוב העפר אל הארץ כשהיה פירש\"י גופו קרוי עפר ומששב אל הארץ כשהי' מיד והרוח תשוב שאין בו עוד רוח ע\"כ ולפי זה אם נסתם הארון בבית במסמרים גם לפירש\"י בנו מיטמא עליו עד שיסתם בקבר:","\u0003ודוקא לאחר שפירש ממתו כו'. \u0004כלומר אין כאן איסור בהליכה מפני שאז עוסק במתו ומות' לטמאות אז אף לאחרים אלא האיסור הוא מפני שבחזרה יצטרך לילך על הקברי' וכבר פירש ממתו והב\"ח פסק דאף בהליכה אסור להוסיף טומאה כיון שאפשר לו לקברו בסוף בית הקברות וכן נראה דעת המחבר וכ\"כ העטרת זהב דנכון להחמיר כסברא זו והמ\"מ דף קי\"ז מיקל בדבר:","\u0003חסר ממנו כל שהוא. \u0004מן המת:","\u0003כשחסר לאחר מיתה. \u0004או כשחסר בשעת מיתה כגון שחתכו ראשו שאינו עכשיו כמו שהיה בחיים ולא קרינן ביה לאביו:"],["\u0003הגדולים על הקטנים. \u0004פי' הכהנים הגדולים ובטור כתוב אם מטמאין מעצמן אין ב\"ד מצווין להפרישו כו' ש\"מ שעל ב\"ד יש גם כן אזהרה שלא לטמאות בידים. וכ' באגודה דתינוק הישן באוהל המת אין צריכין להקיצו ולהוציאו אך מפני החינוך טוב הוא עכ\"ל:"]],["מִצְוָה לְהִטָּמְאוֹת לְמֵת מִצְוָה, אֲפִלּוּ הוּא כֹּהֵן גָּדוֹל וְנָזִיר וְהוֹלֵךְ לִשְׁחֹט אֶת פִּסְחוֹ, וְלָמוּל אֶת בְּנוֹ, וּמָצָא מֵת מִצְוָה, הֲרֵי זֶה מִטָּמֵא לוֹ.\nאֵינוֹ נִקְרָא מֵת מִצְוָה לְעִנְיָן זֶה, אֶלָּא אִם כֵּן מָצָא רֹאשׁוֹ וְרֻבּוֹ. וְאִם מָצָא רֹאשׁוֹ וְרֻבּוֹ חוּץ מֵאֵבֶר אֶחָד, \u0010y0\u0011 חוֹזֵר לִטָּמֵא בִּשְׁבִיל אוֹתוֹ אֵבֶר.\nאֵיזֶהוּ מֵת מִצְוָה, שֶׁמְּצָאוֹ בַּדֶּרֶךְ אוֹ בְּעִיר שֶׁל עוֹבְדֵי כּוֹכָבִים, וְאֵין לוֹ קוֹבְרִים, וּמִמָּקוֹם שֶׁמְּצָאוֹ \u0010c0\u0011 אֵינוֹ יָכוֹל לִקְרוֹת יִשְׂרָאֵל שֶׁיַּעֲנֵהוּ וְיָבֹא לְטַפֵּל בּוֹ וּלְקָבְרוֹ, אָסוּר לוֹ לָזוּז מִשָּׁם וּלְהַנִּיחַ אֶת הַמֵּת, אֲפִלּוּ לֵילֵךְ לָעִיר לְהָבִיא קוֹבְרִים, אֶלָּא יְטַמֵּא עַצְמוֹ וְיִקְבְּרֶנּוּ. אֲבָל אִם הָיוּ יִשְׂרָאֵל קְרוֹבִים לִמְקוֹם הַמֵּת, שֶׁהַמּוֹצֵא אֶת הַמֵּת קוֹרֵא אוֹתָם וְהֵם עוֹנִים לוֹ וּבָאִים לְקָבְרוֹ, אֵין זֶה מֵת מִצְוָה שֶׁיִּטָּמֵא עָלָיו הַכֹּהֵן, אֶלָּא קוֹרֵא אוֹתָם וְהֵם קוֹבְרִים. בָּאוּ בְּנֵי הָעִיר, אִם יֵשׁ לוֹ כָּל צָרְכּוֹ, מוֹשֵׁךְ אֶת יָדָיו. \u0005(לְשׁוֹן רַמְבַּ\"ן בתה\"א ורא\"ש בְּהִלְכוֹת טֻמְאָה)\u0006 \u0005הַגָּה: יֵשׁ אוֹמְרִים אִם אֵינוֹ מוֹצֵא שֶׁיִּקְבְּרוּהוּ, רַק בְּשָׂכָר, אֵינוֹ חַיָּב לִשְׂכֹּר מִשֶּׁלּוֹ, אֶלָּא מִטָּמֵא, אִם יִרְצֶה\u0006 \u0005(נ\"י פֶּרֶק הָאִשָּׁה רַבָּה בְּשֵׁם ריטב\"א)\u0006. \u0005מֵת הַנִּמְצָא, וְלֹא יַדְעִינָן אִם עוֹבֵד כּוֹכָבִים אִם יִשְׂרָאֵל הוּא, \u0010y1\u0011 אַזְלִינָן בָּתַר רֻבָּא הַנִּמְצָאִים שָׁם, אִם יֵשׁ, \u0010y2\u0011 שֶׁלֹּא נוּכַל לוֹמַר כָּל קָבוּעַ כְּמֶחֱצָה עַל מֶחֱצָה\u0006 \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת הָרַשְׁבָּ\"א)\u0006.\nכָּל הַקְּרוֹבִים שֶׁהַכֹּהֵן מִטָּמֵא לָהֶם, שֶׁהֵם: אָבִיו, וְאִמּוֹ, וּבְנוֹ, וּבִתּוֹ, וְאָחִיו, וַאֲחוֹתוֹ מֵאָבִיו הַבְּתוּלָה, וְאִשְׁתּוֹ, מִתְאַבְּלִים עֲלֵיהֶם. וְעוֹד הוֹסִיפוּ עֲלֵיהֶם: אָחִיו מֵאִמּוֹ, וַאֲחוֹתוֹ מֵאִמּוֹ, בֵּין בְּתוּלָה בֵּין נְשׂוּאָה, וַאֲחוֹתוֹ נְשׂוּאָה מֵאָבִיו, שֶׁמִּתְאַבְּלִים עֲלֵיהֶם אַף עַל פִּי שֶׁאֵין כֹּהֵן מִטָּמֵא לָהֶם. וּכְשֵׁם שֶׁהוּא מִתְאַבֵּל עַל אִשְׁתּוֹ, כָּךְ הִיא מִתְאַבֶּלֶת עָלָיו. וְדַוְקָא אִשְׁתּוֹ כְּשֵׁרָה וּנְשׂוּאָה, אֲבָל פְּסוּלָה אוֹ אֲרוּסָה, לֹא. אֲבָל בְּנוֹ, וּבִתּוֹ, וְאָחִיו, וַאֲחוֹתוֹ, אֲפִלּוּ הֵם פְּסוּלִים, מִתְאַבֵּל עֲלֵיהֶם, חוּץ מִבְּנוֹ, וּבִתּוֹ וְאָחִיו וַאֲחוֹתוֹ מִשִּׁפְחָה וְכוּתִית, שֶׁאֵינוֹ מִתְאַבֵּל עֲלֵיהֶם.\nהַגֵּר שֶׁנִּתְגַּיֵּר הוּא וּבָנָיו, אוֹ עֶבֶד שֶׁנִּשְׁתַּחְרֵר הוּא וְאִמּוֹ, אֵין מִתְאַבְּלִין זֶה עַל זֶה. \u0010y3\u0011 \u0005וְהוּא הַדִּין גֵּר שֶׁנִּתְגַּיֵּר עִם אִמּוֹ, אֵין מִתְאַבֵּל עֲלֵיהֶם (סְבָרַת הָרַב מֵהַמָּרְדְּכַי הל' שְׂמָחוֹת מִמַּעֲשֶׂה שֶׁבָּא לִפְנֵי ר\"י לְמַאי דקי\"ל אֲבֵלוּת יוֹם רִאשׁוֹן דְּרַבָּנָן)\u0006.\nכָּל מִי שֶׁמִּתְאַבֵּל עָלָיו, מִתְאַבֵּל עִמּוֹ אִם מֵת לוֹ מֵת. וְדַוְקָא בְּעוֹדוֹ בְּפָנָיו, אֲבָל שֶׁלֹּא בְּפָנָיו אֵין צָרִיךְ לִנְהֹג אֲבֵלוּת; חוּץ מֵאִשְׁתּוֹ, שֶׁאַף עַל פִּי שֶׁמִּתְאַבֵּל עָלֶיהָ אֵינוֹ מִתְאַבֵּל עִמָּהּ אֶלָּא עַל אָבִיהָ אוֹ עַל אִמָּהּ מִשּׁוּם כְּבוֹד חָמִיו וַחֲמוֹתוֹ, אֲבָל עַל אָחִיהָ וַאֲחוֹתָהּ אוֹ בְּנָהּ וּבִתָּהּ מֵאִישׁ אַחֵר, אֵינוֹ מִתְאַבֵּל עִמָּהּ. וּמִכָּל מָקוֹם אֵינוֹ יָכוֹל לְכֹפָהּ לְהִתְקַשֵּׁט, אֲבָל יְכוֹלָה לִמְזֹג לוֹ הַכּוֹס וּלְהַצִּיעַ לוֹ הַמִּטָּה וְלִרְחֹץ פָּנָיו יָדָיו וְרַגְלָיו. וְכֵן הִיא אֵינָהּ מִתְאַבֶּלֶת עִמּוֹ, אֶלָּא כְּשֶׁמֵּתוּ חָמִיהָ אוֹ חֲמוֹתָהּ, אֲבָל שְׁאָר קְרוֹבָיו שֶׁמֵּתוּ, אֵינָהּ מִתְאַבֶּלֶת עִמּוֹ. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּהָאִידָּנָא נוֹהֲגִין לְהָקֵל בַּאֲבֵלוּת זֶה שֶׁל הַמִתְאַבְּלִים עִמּוֹ, דְּאֵין זֶה אֶלָּא מִשּׁוּם כְּבוֹד הַמִתְאַבְּלִים, וְעַכְשָׁו נָהֲגוּ כֻּלָּם לִמְחֹל. וְכֵן נוֹהֲגִין הָאִדָּנָא שֶׁלֹּא לְהִתְאַבֵּל כְּלָל עִם הַמִתְאַבְּלִים (טוּר בְּשֵׁם הָרֹא\"שׁ וְהוּא בְּפ' א\"מ וְרַמְבַּ\"ן בת\"ה והגמי\"י פֶּרֶק א)\u0006, וְכָל הַמַּחְמִיר בָּזֶה \u0010y4\u0011 אֵינוֹ אֶלָּא מִן הַמַּתְמִיהִים \u0005(הַגָּהוֹת מַיְמוֹנִי פ\"ב)\u0006. וּמִכָּל מָקוֹם נָהֲגוּ שֶׁכָּל קְרוֹבֵי הַמֵּת, \u0010y5\u0011 הַפְּסוּלִין לוֹ לְעֵדוּת, מַרְאִין קְצָת אֲבֵלוּת בְּעַצְמָן כָּל שָׁבוּעַ הָרִאשׁוֹנָה, \u0010y6\u0011 \u0010c1\u0011 דְּהַיְנוּ עַד אַחַר שַׁבָּת הָרִאשׁוֹן, שֶׁאֵינָן רוֹחֲצִים וְאֵין מְשַׁנִּים קְצָת בִּגְדֵיהֶם כְּמוֹ בִּשְׁאָר שַׁבָּת \u0005(גְּדוֹלֵי אוסטריי\u0006 ךָ \u0005נָהֲגוּ כֵּן)\u0006. וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ עוֹד לְהַחְמִיר בְּעִנְיָנִים אֲחֵרִים, וְהָעִקָּר כְּמוֹ שֶׁכָּתַבְתִּי. וְכָל זֶה בִּשְׁמוּעָה קְרוֹבָה, אוֹ שֶׁהָיָה אֵצֶל הַמִּיתָה; אֲבָל בִּשְׁמוּעָה רְחוֹקָה, אֵין לַאֲבֵלוּת זֶה מָקוֹם כְּלָל \u0005(תִּמְצָא הַכֹּל מְבֹאָר בת\"ה סִימָן רנ\"א)\u0006. מִי שֶׁרוֹצֶה לְהַחְמִיר עַל עַצְמוֹ לְהִתְאַבֵּל עַל מִי שֶׁאֵינוֹ צָרִיךְ, אוֹ לִלְבֹּשׁ שְׁחֹרִים עַל קְרוֹבוֹ, אֵין מוֹחִין בְּיָדוֹ \u0005(הָרֹא\"שׁ כְּלָל כ\"ז דִּין ט')\u0006.\nאֵין מִתְאַבְּלִים עִם הַקְּרוֹבִים שֶׁמִּתְאַבְּלִים עֲלֵיהֶם, אֶלָּא כְּשֶׁמִּתְאַבְּלִים עַל הַקֻּרְבָה דִּשְׁאֵר, כְּגוֹן בְּנוֹ וְאָחִיו שֶׁמִּתְאַבֵּל עַל בֵּן וּבַת שֶׁלָּהֶם; אֲבָל עַל קֻרְבָה דְּקִדּוּשִׁין שֶׁלָּהֶם, כְּגוֹן שֶׁמֵּתָה אֵשֶׁת בְּנוֹ אוֹ אֵשֶׁת אָחִיו אוֹ בַּעַל בִּתּוֹ אוֹ בַּעַל אֲחוֹתוֹ, אֵינוֹ מִתְאַבֵּל עֲלֵיהֶם.\nתִּינוֹק, כָּל שְׁלֹשִׁים יוֹם וְיוֹם שְׁלֹשִׁים בַּכְּלָל, \u0010y7\u0011 אֵין מִתְאַבְּלִים עָלָיו, אֲפִלּוּ גָּמְרוּ שְׂעָרוֹ וְצִפָּרְנָיו; וּמִשָּׁם וָאֵילָךְ מִתְאַבֵּל עָלָיו, אֶלָּא אִם כֵּן נוֹדַע שֶׁהוּא בֶּן ח'. וְאִי קִים לֵיהּ בֵּיהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו, כְּגוֹן שֶׁבָּעַל וּפֵרֵשׁ וְנוֹלַד חַי לִט' חֳדָשִׁים גְּמוּרִים, אֲפִלּוּ מֵת בַּיּוֹם שֶׁנּוֹלַד, מִתְאַבְּלִים עָלָיו. \u0005סָפֵק בֶּן ט' לָרִאשׁוֹן (אוֹ)\u0006 בֶּן ז' לָאַחֲרוֹן, \u0010c2\u0011 שְׁנֵיהֶם מִתְאַבְּלִים עָלָיו \u0005(מָרְדְּכַי הִלְכוֹת אֲבֵלוּת וְהַגָּהוֹת מַיְמוֹנִי פֶּרֶק א' וּבֵית יוֹסֵף בְּשֵׁם הַתּוֹסָפוֹת)\u0006.\nיֵשׁ מִי שֶׁאוֹמֵר דִּתְאוֹמִים שֶׁמֵּת א' מֵהֶם תּוֹךְ שְׁלֹשִׁים יוֹם, \u0010y8\u0011 וְהַשֵּׁנִי חַי \u0010c3\u0011 וּמֵת אַחַר ל' יוֹם, אֵין מִתְאַבְּלִין עָלָיו. \u0010y9\u0011\nעַל רַבּוֹ שֶׁלִּמְּדוֹ חָכְמָה נוֹהֵג דִּינֵי אֲנִינוּת, אֶלָּא שֶׁמְּבָרֵךְ וּמְזַמֵּן וּמִתְאַבֵּל עָלָיו בַּחֲלִיצַת סַנְדָּל \u0010c4\u0011 וְכָל דִּינֵי אֲבֵלוּת, יוֹם אֶחָד. \u0005(וְכָתַב הַבֵּית יוֹסֵף בְּשֵׁם רַבִּי שִׂמְחָה שֶׁצָרִיךְ לְשַׁנּוֹת מְקוֹמוֹ בב\"ה, מִיהוּ בְּמִקְצָת הַיּוֹם סָגֵי)\u0006.\nנָשִׂיא, אַף עַל פִּי שֶׁהַכֹּל מִטָּמְאִין לוֹ, אֵין מִתְאַבְּלִים עָלָיו. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּאֵין מִתְאַבְּלִין עַל בֵּן הָרִאשׁוֹן אוֹ בֵּן הַבְּכוֹר שֶׁמֵּת לְאָדָם (כָּל בּוֹ וריב\"ש וּבֵית יוֹסֵף הֵבִיאוּ מִי שֶׁנָּהֲגוּ כֵּן, וְהֵם כָּתְבוּ שֶׁהוּא טָעוּת)\u0006 ; וְהַמִּנְהָג הוּא מִנְהַג טָעוּת, אֶלָּא חַיָּבִים לְהִתְאַבֵּל עֲלֵיהֶם. וּמִכָּל מָקוֹם נִשְׁתַּרְבֵּב הַמִּנְהָג בְּעִירֵנוּ \u0010y10\u0011 שֶׁאֵין אָב וָאֵם הוֹלְכִים אַחַר בְּנֵיהֶם הָרִאשׁוֹן לְבֵית הַקְּבָרוֹת. יֵשׁ אוֹמְרִים בִּשְׁעַת הַדֶּבֶר אֵין מִתְאַבְּלִים, מִשּׁוּם בִּיעֲתוּתָא \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ג')\u0006, וְשָׁמַעְתִּי קְצָת נָהֲגוּ כֵּן.",["\u0003חוזר ליטמא כו'.\u0004 כלומר דאע\"ג דאינו מטמא עליו אלא כשמצא ראשו ורובו היינו לטמאות לכתחלה אבל אם כבר קברו חוץ מאבר א' חוזר לטמאות על אותו אבר ובזה חמור מהקרובים שאינו מטמא להם אלא א\"כ הם שלמים כדלעיל ס\"ס הקודם:","\u0003אזלינן בתר רוב הנמצאים שם אם לא שנוכל לומר כל קבוע כמחצה כו'. \u0004כצ\"ל ור\"ל דאזלינן בתר רוב העוברים ושבים המצויים שם או בתר רוב עיירות אם רובו עובדי כוכבים א\"צ לקברו ואם רובו ישראל הוי מת מצוה ולא אזלינן בתר העיר הקרובה אפי' בקורבה דמוכח אלא בתר רובו אזלינן דכל דפריש מרובא פריש כן הוא בתשו' הרשב\"א סי' פ\"ג ס\"ק ח':","\u0003שנוכל לומר כל קבוע כו'. \u0004כגון שידוע שהיו כאן ט' עובדי כוכבים וחד ישראל ונהרג אחד מהן במקומו דה\"ל קבוע לא אזלינן בתר רוב עובדי כוכבים אלא הוי כמחצה על מחצה וכ' העט\"ז ולחומרא ואין הכהן מטמא עכ\"ל ר\"ל דכיון דהוי כמחצה על מחצה אם כן הוי ספיקא ואזלינן לחומרא וצריך לקברו ומ\"מ אין הכהן מיטמא מספק כדלעיל סי' שע\"ג ס\"ח:","\u0003וה\"ה גר כו'. \u0004ואע\"פ דבמרדכי כ' דגר מתאבל על אמו היינו למ\"ד אבילות יום ראשון דאורי' ולא לדידן דקי\"ל לקמן ס\"ס שצ\"ט דהוא מדרבנן וכן כ' בד\"מ:","\u0003אינו אלא מן המתמיהים. \u0004ואינו כמכבד האבלים אלא כלועג להם. שם בהגמ\"ר ואע\"ג דמי שרוצה להחמיר ולהתאבל על מי שאינו צריך הרשות בידו וכמ\"ש הרב בסוף ההג\"ה היינו דוקא כשמתאבל לגמרי כדין אבילות אבל כשאינו מתאבל אלא לפניו הוי כלועג לאבל. נ\"ל:","\u0003הפסולים לו לעדות כו'. \u0004עיין בח\"מ סי' ל\"ג איזהו פסולין לעדות ומ\"מ נראה דדוקא פסולי עדות מחמת קורבה דשאר ולא פסולי עדות מחמת קורבה דקידושין כדלקמן בסעיף שאח\"ז והכי נהוג שאינם רוחצים כי אם בפושרים גמורים. ת\"ה שם:","\u0003דהיינו עד אחר שבת הראשון. \u0004הן סמוך הן מופלג וכ' הב\"ח דכ\"ש דאסור לילך לסעודת מצוה כגון ברית מילה עד מוצאי שבת ע\"ש ובתשו' משאת בנימין סי' פ\"ג כ' וז\"ל קרובי המת שאינן חייבים להתאבל ומ\"מ מראין קצת סימני אבילות ראיתי מקומות חלוקים בזה יש מקומות שנוהגין רק פסולי עדות למת מראין אבילות אבל הכשרים לעדות אין מראין אבילות כלל ויש מקומות שאפי' שלישי ברביעי מראין אבילות והיכא דנהוג נהוג והיכא דלא נהוג נראה דאין להראות אבילות רק הפסולים לעדות וכדעת תרומת הדשן סימן רצ\"ח מ\"מ נראה דאין כל הקרובים שוים לזה אלא קרוב קרוב קודם ואותם קרובים שמן הדין היו חייבים להתאבל ממש כדאמרינן כל שאתה מתאבל עליו אתה מתאבל עמו אף ע\"ג דהאידנא לא נהיגין הכי מ\"מ באבילות ממש צריכין להראות אבילות ביום המית' או ביום השמוע' אם הוא תוך ל' עד מוצאי שבת הא' ואין להחליף מבגדי חול לבגדי שבת וגם אין לרחוץ בחמין גם לא לחוף הראש רק בצונן או במים פושרין גם אין לאכול חוץ לביתו לא בסעודת מצוה ולא בסעודת מריעות אבל כתונת לבן אין למנוע לכבוד שבת גם אין לשנות את מקומם בב\"ה אבל במו\"ש מותר בכל דבר בין אם הוא מופלג או סמוך ואותן הקרובים שמן הדין אין מתאבלין אין להחמיר עליהן ברחיצת חמין וחפיפת הראש ולא בחילוף בגדי שבת כל כך ודי להם בבגד העליון של חול ושלא לאכול חוץ לבית וכ\"ש אותן מקומות שנהגו דאפילו הכשרים לעדות מראי' קצת אבילות שאין להחמיר כל כך עכ\"ל ומ\"ש להתיר ברחיצת חמין וחפיפת הראש באותן קרובים שאין מתאבלים עם מי שמתאבל עמהן אין נראה כן מדברי ת\"ה והרב דהא אוסרי' ברחיצ' על קרובי המת הפסולים לעדות דהיינו שני בשני אע\"ג שאין מתאבלין גם מ\"ש להחמיר שאין להחליף כלל מבגדי חול לשבת כאותן שמתאבלין אין נראה כן מדבריהם אלא משנים רק קצת מבגדיהן ומ\"מ נראה דהולכים בדברים אלו אחר המנהג:","\u0003אין מתאבלין עליו כו'. \u0004משמע דמיירי דלא קים לן שכלו חדשיו והיינו שהשיג הב\"י על הגהת אשר\"י וז\"ל ואיני יודע למה התנה שלא גמרו שערו וצפרניו כו' דלא כהב\"ח שכ' על הב\"י ומ\"ש הגהת אשר\"י ולא גמרו שערו וצפרניו כו' היינו משום דאי גמרו שערו וצפרניו ודאי מתאבלין כיון דספק הוא אם כלו חדשיו תלינן דכלו לו חדשיו כיון דלא מת עד לאחר שלשים וגם גמרו שערו וצפרניו והב\"י כתב על הגהת אשר\"י זו ואיני יודע כו' ושגגה יצאה מתחת קולמסו דהדבר פשוט כדפרישית עכ\"ל ולא עמדתי על סוף דעתו דהא הב\"י מיירי השתא במת תוך ל' וכן מיירי בהגהת אשר\"י וז\"ל בסוף מ\"ק והיכא דלא קים לן אי כלו לו חדשיו או לאו ולא גמרו שערו וצפרניו ומת ביום ל' אין מתאבלין עליו עכ\"ל ודוחק לומר דמת ביום ל' דינו כלאחר ל' דהא קי\"ל בענין אבילות דיום ל' כתוך ל' וכדמסיק רב אשי בפרק יש בכור ריש (בכורות ד' מ\"ט) וכן דעת הרמב\"ן והטור להדיא דאם מת ביום שלשים אפי' גמרו שערו וצפרניו אין מתאבלין עליו היכא דלא קים ליה ביה שכלו חדשיו וכן דעת המחבר:","\u0003והשני חי אחר שלשים יום כו' כצ\"ל. \u0004ור\"ל אין מתאבלין ע\"ז שמת תוך ל' ולא אמרינן מדזה הוא חי והוא בן קיימא אפילו גם זה שמת מסתמא בן קיימא הוי דלא כהעט\"ז שכתב שאין מתאבלין על זה השני שמת אחר שלשים דמסתמא נמי נפל היה דהא ודאי ליתא וכבר השיג עליו הב\"ח בזה וכן משמע להדיא בא\"ז גופיה שממנו מקור דין זה ומביאו בד\"מ וז\"ל תשובה על תאומים שמת אחד מהן תוך ל' והשני חי לא אמרינן מדהשני חי הראשון נמי בן קיימא הוי ואין מתאבלין עליו עכ\"ל תשובת הרשב\"א וכן פירש בהגה' דרישה ועיקר:","\u0003על רבו כו'. \u0004ע\"ל סימן רמ\"ב סעיף כ\"ו:","\u0003שאין אב ואם הולכים כו'. \u0004אבל על בניהם השני הולכים אע\"פ שהראשון היה נפל וכן נוהגין:"],["\u0003אינו יכול לקרות ישראל. \u0004כתב רש\"ל לעולם הוא מ\"מ עד שיהיו שם נושאי המטה וקובריה. רוקח עכ\"ל:","\u0003עד אחר שבת הראשון. \u0004כתב מו\"ח ז\"ל כ\"ש שאין נכנסין לסעודה אפילו לסעודת מצוה עד מוצ\"ש ובספר משאת בנימין כ' שיש להחמיר עוד שלא לחוף הראש בחמין אותו ערב שבת:","\u0003שניהם מתאבלין עליו. \u0004אע\"ג דאבילות דרבנן החמירו כאן בספק דגנאי היה לו אם לא היו מתאבלין עליו כלל. כ\"כ במרדכי:","\u0003ומת אחר ל' יום אין מתאבלין עליו. \u0004לפי זה משמע דעל השני אין מתאבלין והטעם דאנו רואין שגם השני אינו בן קיימא כיון שהוא מטיפה אחת עם הראשון וכ\"פ בלבוש ואמר דהיינו דוקא כשהי' השני ג\"כ חולה בשעת מיתת הראשון והאריך בזה לחזק דבריו ובאמת דעתו מתמיה מאד לפטור מאבילות מכח סברא חלושה כזאת ובדרכי משה ראיתי שהעתיק בלשון זה כתב אור זרוע תשובה על תאומים שמת אחד מהן תוך שלשים והשני חי לא אמרינן מדהשני חי הראשון נמי הוה בן קיימא ואין מתאבלין עליו עכ\"ל רשב\"א עכ\"ל. ונמצא דעל הראשון קאמר דאין מתאבלין אבל על השני דמת אחר שלשים יום ודאי מתאבלין עליו וכאן הוא ט\"ס וצריך להיות והשני חי עדיין אחר שלשים יום אין מתאבלים עליו וקאי על הראשון וכן משמע בסימני הטור שחיבר בעל השו\"ע שז\"ל תאומים שמת אחד מהם תוך שלשים יום והשני חי עדיין אין מתאבלין עליו אפילו מת בסוף שלשים עכ\"ל הרי כ' אין מתאבלין עליו קודם שזכר אפי' מת בסוף ל' ואם איתא דעל השני כ' אין מתאבלין היה לו לכתוב תחילה מיתתו של שני ואדרבה כתבו אחר שכ' שהשני חי עדיין אלא פשוט שעל הראשון קאי ועליה מסיים אפי' מת בסוף ל' כלומר ביום הל' עצמו אפ\"ה אין מתאבלין עליו אע\"פ שיש שתי סברות להתאבל על הראשון. האחת כיון שחי עד יום ל' ובו מת ועוד שהשני חי עדיין והם מטפה אחת הוה אמינא כמו שהשני בן קיימא ה\"נ הראשון קמ\"ל דלא ומימים רבים הודעתי דברים אלו למו\"ח ז\"ל והשיב לי שמזמן קודם הרבה התעורר אותו הרב הגאון מוהר\"ר משה חריף ז\"ל בזה וכן עלה המוסכם בין שניהם וכן קבע בחבורו דאראשון דוקא קאי וכן כתב בפרישה. אח\"כ מצאתי בתשובת מהר\"ם מינץ בסי' נ\"ה שהביא בהדיא המקור מהלכות שמחות שדין זה קאי שהשני חי עדיין ואז נאמר שהראשון גם כן לא היה נפל ולקמן סימן שצ\"ז אעתיק דבריו ודברי הלבוש אינם נכונים בזה דעל השני אם מת פשיטא שחייב להתאבל עליו. שוב ראיתי שגם מהר\"ר מאיר ז\"ל מלובלין פסק בתשובות סימן ס\"ז דאין להתאבל על השני מכח הג\"ה זאת והוא מחסרון ידיעה שהיה לו להרב בזה ועלה לו כמו לבעל הלבוש:","\u0003וכל דיני אבילות יום אחד. \u0004בסימן רמ\"ב מבואר דסגי במקצת יום ראשון וכתב רש\"ל ונכון להם שלא לשתות ולא לאכול בשר כל היום עד לאחר קבורה מא\"ז עכ\"ל:"]],["מֵאֵימָתַי חָל הָאֲבֵלוּת, מִשֶּׁנִּקְבַּר וְנִגְמַר \u0010c0\u0011 סְתִימַת הַקֶּבֶר בְּעָפָר, מִיָּד מַתְחִיל הָאֲבֵלוּת וּמְעַטֵּף רֹאשׁוֹ, אֲבָל אֵינוֹ חוֹלֵץ מִנְעָלָיו עַד שֶׁיַּגִּיעַ לְבֵיתוֹ \u0005(רַמְבַּ\"ן)\u0006. וְעַכְשָׁו נוֹהֲגִים לַחֲלֹץ מִנְעָל אַחַר סְתִימַת הַגּוֹלָל מִיָּד, כִּדְאִיתָא בְּסִימָן שע\"ו. \u0005הַגָּה: וְע\"ל סִימָן שפ\"ב. הָיָה סָבוּר שֶׁנִּסְתַּם הַקֶּבֶר וְהִתְחִיל לְהִתְאַבֵּל, וְאַחַר כָּךְ נוֹדַע לוֹ שֶׁטָּעָה, חוֹזֵר וּמַתְחִיל הָאֲבֵלוּת מֵחָדָשׁ (תְּשׁוּבַת הָרֹא\"שׁ כְּלָל כ\"ז)\u0006.\nמִי שֶׁדַּרְכָּם לִשְׁלֹחַ הַמֵּת \u0010y0\u0011 לִמְדִינָה אַחֶרֶת לְקָבְרוֹ, וְאֵינָם יוֹדְעִים מָתַי יִקָּבֵר, מֵעֵת שֶׁיַּחַזְרוּ פְּנֵיהֶם מִלְלַוּוֹת מַתְחִילִין לִמְנוֹת שִׁבְעָה וּשְׁלֹשִׁים וּמַתְחִילִין לְהִתְאַבֵּל \u0005(ל' רַמְבַּ\"ם פֶּרֶק א' מה\"א ד\"ו)\u0006 ; וְהַהוֹלְכִים עִמּוֹ, מוֹנִים מִשֶּׁיִּקָבֵר. \u0010y1\u0011 וְאִם גָדוֹל הַמִּשְׁפָּחָה הוֹלֵךְ עִמּוֹ, \u0010y2\u0011 אַף אֵלוּ שֶׁבְּכָאן אֵינָם מוֹנִים אֶלָא מִשֶּׁיִּקָבֵר; וּגְדוֹל \u0010y3\u0011 מִשְׁפָּחָה הַיְנוּ דְּבֵיתָא סָמוּךְ עֲלֵהּ וּגְרִירֵי כֻּלְהוּ בַּתְרֵיהּ, לֹא שְׁנָא אָח לֹא שְׁנָא בֵּן קָטָן; וְיֵשׁ מִי שֶׁאוֹמֵר וְהוּא שֶׁיְּהֵא בֶּן י\"ג.\nאִם מְפַנִּין אֶת הַמֵּת מִקֶבֶר לְקֶבֶר, אִם קְבָרוּהוּ בְּקֶבֶר רִאשׁוֹן עַל דַּעַת לִהְיוֹת קָבוּר שָׁם עוֹלָמִית, אֶלָא שֶׁאַחַר כָּךְ נִמְלְכוּ לְפַנּוֹתוֹ מִשָּׁם, אֵין מוֹנִין לוֹ אֶלָא מִשֶּׁיִּקָבֵר בְּקֶבֶר רִאשׁוֹן, אֲפִלוּ פִּנּוּהוּ תּוֹךְ ז'. אֲבָל אִם בִּתְחִלָה קְבָרוּהוּ עַל דַּעַת לְפַנּוֹתוֹ כְּשֶׁיִּזְדַּמֵּן לָהֶם, מַתְחִילִין אֲבֵלוּת מִיָּד; וְאִם פִּנּוּהוּ תּוֹךְ שִׁבְעָה, חוֹזְרִין וּמוֹנִין מִשֶּׁיִּקָבֵר שֵׁנִית; וְאִם לֹא פִּנּוּהוּ עַד לְאַחַר שִׁבְעָה, כְּבַר עָבַר אֲבֵלוּתָם וְאֵין מִתְאַבְּלִין עָלָיו פַּעַם אַחֶרֶת; וְאִם מִתְּחִלָה הָיָה דַּעְתָּם לְפַנּוֹתוֹ מִשָּׁם תּוֹךְ שִׁבְעָה, אֵין מַתְחִילִין לִמְנוֹת עַד שֶׁיִּקָבֵר בַּקֶבֶר הַשֵּׁנִי.\nאִם נָתְנוּ הַמֵּת בְּאָרוֹן, וּנְתָנוּהוּ בְּבַיִת אַחֵר לְפִי שֶׁהָיְתָה הָעִיר בְּמָצוֹר, מוֹנִים לוֹ מִיָּד שִׁבְעָה וּשְׁלֹשִׁים, אַף עַל פִּי שֶׁדַּעְתָּם לְקָבְרוֹ בְּבֵית הַקְבָרוֹת אַחַר הַמָּצוֹר, \u0010y4\u0011 וּסְתִימַת אָרוֹן הָוֵי כִּקְבוּרָה וְחָל עֲלֵיהֶם אֲבֵלוּת מִיָּד.\nהֲרוּגֵי מַלְכוּת שֶׁאֵין מַנִּיחִים אוֹתָם לִקָבֵר, מֵאֵימָתַי מַתְחִילִין לְהִתְאַבֵּל עֲלֵיהֶם וְלִמְנוֹת ז' וּשְׁלֹשִׁים, \u0010y5\u0011 מִשֶּׁנִּתְיָאֲשׁוּ לִשְׁאֹל לַמֶּלֶךְ לְקָבְרָן, אַף עַל פִּי שֶׁלֹּא נִתְיָאֲשׁוּ מִלִגְנֹב אוֹתָם.\nמִי שֶׁהוֹדִיעוּהוּ שֶׁצָּלְבוּ עוֹבְדֵי כּוֹכָבִים קְרוֹבוֹ בְּעִיר אַחֶרֶת וְנָהַג אֲבֵלוּת מִיָּד, וְאַחַר כָּךְ נוֹדַע לוֹ שֶׁעֲדַיִן עוֹמֵד בַּצְּלִיבָה, אוֹתוֹ אֲבֵלוּת לֹא עָלָה לוֹ וְחוֹזֵר וּמוֹנֶה מִשֶּׁיִּקָבֵר \u0010c1\u0011 אוֹ מִשֶּׁנִּתְיָאֲשׁוּ מִלְקָבְרוֹ \u0005(דַּעַת ר\"י וְרַמְבַּ\"ן)\u0006. \u0010y6\u0011\nמִי שֶׁטָּבַע \u0010c2\u0011 בְּמַיִם שֶׁיֵּשׁ לָהֶם סוֹף, אוֹ שֶׁיָּצָא קוֹל שֶׁהֲרָגוּהוּ לִסְטִים אוֹ שֶׁגְרַרְתּוֹ חַיָּה, מֵאֵימָתַי מוֹנִים, מִשֶּׁנִּתְיָאֲשׁוּ לְבַקֵשׁ. מְצָאוּהוּ אֵבָרִים אֵבָרִים וּמַכִּירִין אוֹתוֹ בְּסִימָנֵי גוּפוֹ, אֵין מוֹנִין לוֹ עַד שֶׁיִּמָּצֵא רֹאשׁוֹ וְרֻבּוֹ אוֹ יִתְיָאֲשׁוּ מִלְבַקֵשׁ \u0005(בָּרַיְתָא מְבִיאָהּ רַמְבַּ\"ן)\u0006 ; וְאִם נִמְצָא אַחַר שֶׁנִּתְיָאֲשׁוּ מִמֶּנּוּ, \u0010y7\u0011 אֵין הַקְרוֹבִין צְרִיכִים לַחֲזֹר וּלְהִתְאַבֵּל, אֶלָא הַבָּנִים, \u0010y8\u0011 אִם הֵם שָׁם בְּשָׁעָה שֶׁנִּמְצָא מִתְאַבְּלִים אוֹתוֹ הַיּוֹם דְּלֹא גָרַע מִלִקוּט עַצְמוֹת אָבִיו; אֲבָל אִם אֵינָם שָׁם, וְשָׁמְעוּ אַחַר שֶׁעָבַר הַיּוֹם, אֵין צְרִיכִין לְהִתְאַבֵּל. \u0005הַגָּה: אִם שָׁלְחוּ מֵתֵיהֶם לְעִיר אַחֶרֶת, \u0010y9\u0011 שֶׁדִּינָם לְהַתְחִיל הָאֲבֵלוּת מִשֶּׁיַּחֲזִירוּ פְּנֵיהֶם, וְהִתְחִילוּ לִמְנוֹת הָאֲבֵלוּת, וְאַחַר כָּךְ נִתְפַּס הַמֵּת וְלֹא נִתַּן לִקְבוּרָה זְמַן אָרֹךְ, אֵין צְרִיכִין לְהַפְסִיק אֲבֵלוּתָן, וְאֵין צְרִיכִין לַחֲזֹר וּלְהִתְאַבֵּל אַחַר כָּךְ, דְּמֵאַחַר שֶׁדִּינָם לְהַתְחִיל מִיָּד, אֵין צְרִיכִין לְהַפְסִיק (מָרְדְּכַי סוֹף מ\"ק)\u0006.\nמִי שֶׁמֵּת לוֹ קָרוֹב, וְלֹא יָדַע עַד שֶׁבָּא \u0010y10\u0011 לַמָּקוֹם שֶׁמֵּת שָׁם הַמֵּת, אוֹ לִמְקוֹם קְבוּרָה, אִם הָיָה בְּמָקוֹם קָרוֹב שֶׁהוּא מַהֲלַךְ י' פַּרְסָאוֹת שֶׁאֶפְשָׁר שֶׁיָּבֹא בְּיוֹם אֶחָד, אֲפִלוּ בָּא בַּיּוֹם הַז', אִם מָצָא מְנַחֲמִים אֵצֶל גְדוֹל הַבַּיִת, אֲפִלוּ שֶׁנִּנְעֲרוּ לַעֲמֹד, הוֹאִיל וּמָצָא מְנַחֲמִים \u0005דְּהַיְנוּ שֶׁנּוֹהֲגִים עֲדַיִן קְצָת אֲבֵלוּת (טוּר וְרַשְׁבָּ\"א בִּתְשׁוּבָה)\u0006, עוֹלֶה וּמוֹנֶה לוֹ עִמָּהֶם תַּשְׁלוּם שְׁלֹשִׁים יוֹם; וְאִם לֹא מָצָא מְנַחֲמִים, מוֹנֶה לְעַצְמוֹ. וְכֵן אִם הָיָה בְּמָקוֹם רָחוֹק, אֲפִלוּ בָּא בְּיוֹם שֵׁנִי, מוֹנֶה לְעַצְמוֹ שִׁבְעָה וּשְׁלֹשִׁים מִיּוֹם שֶׁבָּא. \u0005הַגָּה: \u0010y11\u0011 וְיֵשׁ אוֹמְרִים דַּאֲפִילוּ אִם בָּא אֶחָד, וְאֵין הַגָּדוֹל בַּבַּיִת רַק שֶׁהָלַךְ לְצֹרֶךְ הַמֵּת, אִם חָזַר תּוֹךְ ג' יָמִים הָוֵי כְּאִלּוּ הוּא בַּבַּיִת \u0010y12\u0011 וְהַבָּא תּוֹךְ ג' מוֹנֶה עִמָּהֶם (וְכֵן הוּא בַּטּוּר)\u0006 ; וְיֵשׁ לְהָקֵל כִּסְבָרָא זוֹ. וְכָל שֶׁדִּינוֹ לִמְנוֹת עִמָּהֶם, אֲפִלּוּ אִם חָזַר אַחַר כָּךְ לְבֵיתוֹ, מוֹנֶה עִמָּהֶם \u0005(הָרַשְׁבָּ\"א סִימָן תע\"ז)\u0006.\nבַּמֶּה דְּבָרִים אֲמוּרִים, כְּשֶׁלֹּא שָׁמַע שֶׁמֵּת, עַד שֶׁבָּא. אֲבָל אִם נוֹדַע לוֹ בַּיּוֹם הַשֵּׁנִי וְהִתְחִיל לְהִתְאַבֵּל, לֹא יְקַצֵּר אֲבֵלוּתוֹ בִּשְׁבִיל שֶׁבָּא אֶצְלָם.\nמִי שֶׁהוּא אָבֵל, וּבְתוֹךְ ז' מֵת לוֹ מֵת אַחֵר, מוֹנֶה ז' לְמֵת אַחֲרוֹן וְעוֹלִים לוֹ לְתַשְׁלוּם שִׁבְעָה יְמֵי אֲבֵלוּת הָרִאשׁוֹן. \u0010y13\u0011\nמִי שֶׁהִתְפַּלֵל עַרְבִית, וַעֲדַיִן הוּא יוֹם, וְשָׁמַע שֶׁמֵּת לוֹ מֵת, יֵשׁ מִי שֶׁאוֹמֵר שֶׁמּוֹנֶה מִיּוֹם הַמָּחֳרָת, \u0010y14\u0011 \u0010y15\u0011 וְאוֹתוֹ יוֹם \u0010c3\u0011 אֵינוֹ עוֹלֶה.",["\u0003למדינה אחרת כו'. \u0004משמע דוקא) כששולחים אותו לעיר אחרת אבל הקוברים בבית הקברות סמוך לעיר החוזרים משערי העיר אינן מתאבלין עד שאמרו להם שנקבר וכמ\"ש הרמב\"ן וכן כתב בית יוסף ונ\"מ ע\"כ לענין קובר מתו בערב הרגל וכדאיתא בפוסקים בשם בעל הלכות:","\u0003ואם גדול המשפחה כו'. \u0004משמע דוקא לחומרא אזלינן בתר גדול המשפחה דאין מונין אלא משיקבר אבל אי גדול המשפחה הוא אצל אלו שנשארו כאן אין מעלה ומוריד אלא אף על פי כן ההולכים עם המת אין מונין אלא משיקבר וכדעת התוספות שמביא בית יוסף וכן כתבו התוספות פרק אלו מגלחין (מועד קטן דף כ\"ב) סוף ע\"א ריש ד\"ה מהדריתו אפייכו כו' דההולכים עם המת מונין משיסתם הגולל בין גדול הבית בבית בין הולך לבית הקברות וכן המנהג עכ\"ל. אבל הטור כ' דהכל הולך אחר גדול הבית דאם נשאר כאן אלו ואלו מונין משיצא המת וכן נראה דעת הרמב\"ן בת\"ה דף מ\"ז ע\"ג והרא\"ש פרק אלו מגלחין במה שהביאו שם הירושלמי ע\"ש ולא עמדתי על סוף דעת בית יוסף שכ' וגירסת הרמב\"ן בירושלמי מגומגמת כו' שהרי גירסתו אות באות כגירסת הרא\"ש מיהו לפי מה שהביא הבית יוסף נוסח הירושלמי מוכח לענין דינא כדעת התוספות הנ\"ל ונ\"ל שגירסא זו עיקר דהא בירושלמי פריך אית תנוי תני אלו שבכאן מונין משיצא המת ואלו ששם מונין משיסתם הגולל ואית תנוי תני אלו וחלו משיסתם הגולל ומשני רבי סימון דהכל הולך אחר גדול המשפחה ואם איתא מאי פסקא הל\"ל נמי אלו ואלו מונין משיצא המת והיינו כשיש גדול הבית בבית אלא ודאי לא אזלינן אחר גדול הבית אלא להחמיר ונ\"ל שכן דעת ראבי\"ה שהביא מרדכי פ' א\"מ שכתב ואותם שהלכו עם המת לקברו משמע מתוך דברי ראבי\"ה שמונה משיסתם הגולל ולדברי רבי אברהם מונה משיצא מפתח ביתו עם גדול הבית ואח\"כ כתב ואם היה גדול הבית בבה\"ק בהא פליגי רבוותא ראבי\"ה פירש דכולן מונין עמו משיסתם הגולל כו' ע\"ש:","\u0003אף אלו שבכאן כו'. \u0004ומדברי ראב\"ן דף ל\"ח ע\"ג מבואר דדוקא אם יכול לבא אל הקבר תוך שלשה ימים אבל אם אינו יכול לבוא תוך שלשה ימים אלו שבבית מונין מיד וגדול הבית שבב\"ה משיסתם הגולל ואין נגררים עמו ומפרש שם כך בש\"ס הא דאתא גו תלתא כו' ואפשר גם המחבר וסייעתו מודים לזה דלא מסתבר כלל אם יקבר המת במקום רחוק שאלו שבכאן ישבו ימים רבים ולא יתחילו אבלות עד שיקבר אף שפי' ראב\"ן בש\"ס דחוק מ\"מ הסברא נכונה:","\u0003דהיינו דביתא סמוך עליה כו'. \u0004לקמן כתבתי בשם הרשב\"א דמי שמתה אשתו הבעל נקרא גדול הבית עיין שם:","\u0003וסתימת הארון הוי כקבורה. \u0004כלומר אע\"ג דקי\"ל לעיל סעיף א' דאין אבילות חל אלא משיסתם הגולל דהיינו משנקבר ונגמר סתימת הקבר בעפר היינו בעלמא אבל במצור מיד שנתנוהו בבית אחר וסתמו הארון הוי כקבורה דהוי כנתיאשו מלקברו דאע\"ג דרוצים לקברו אח\"כ בבה\"ק מ\"מ השתא במצור ה\"ל קבורה מעליותא לדידהו שהרי אם תלכד העיר לא יקברוהו בענין אחר וכן נראה בב\"י ובב\"ח טרח ליישב דברי המחבר בע\"א ע\"ש:","\u0003משנתיאשו כו'. \u0004ואין חילוק בין נתיאשו תוך ל' או אחר ל'. כן הסכמת הפוסקים:","\u0003מי שטבע במים שיש להם סוף כו'. \u0004נראה להכי נקט מים שיש להם סוף לאפוקי שאין להם סוף דאין מתאבלין עליו כלל וכמ\"ש הב\"י בשם העיטור בשם תשובת הרי\"ף מי שטבע במים שאין להם סוף דאין היתר לאשתו לא ינהוג אבילות והא דתניא באבל רבתי טבע בנהר איכא למימר שנפל ומת או שנפל למים שיש להם סוף עכ\"ל ולפ\"ז מ\"ש או שיצא קול כו' או שגררתו חיה כו' היינו נמי בענין שמותרת אשתו להנשא ואע\"ג דמדברי רב האי ורב שרירא שהביא הטור משמע דאפילו לא נתברר שמת אלא קול יוצא בכך מתאבלין עליו נראה כיון דנדחו דבריהם בפוסקים כדאיתא בטור וב\"י נדחו ג\"כ בזה וכן כתב הרב בא\"ע סימן י\"ז ס\"ה דאשתו אסורה להספיד או ללבוש שחורים כל זמן שאין כאן עדות שהוא ראוי להשיאה על ידו עיין שם:","\u0003אין הקרובים צריכים להתאבל. \u0004כ\"כ טור ותמיה לי דהא כיון דלא גרע מליקוט עצמות אם כן גם הקרובים צריכין להתאבל כדלקמן סימן ת\"ג סעיף א' וסעיף ה' ונראה דמשמע ליה הכי מדכתב הרא\"ש בשם מהר\"ם דאם קברוהו במקום בנו וידע בנו את קבורתו לא גרע מיום ליקוט עצמות כו' משמע ליה מהאי לישנא דוקא בנו אבל הדבר ברור משום דמהר\"ם שם קאי אעובדא דר' אליקום שנהרג אחד בדרך וחפשו בנו ואח\"כ נמצא ולא הוזכר שם רק בנו עלה קאי אבל אה\"נ דה\"ה שאר קרובים דהא מייתי ראיה מהא דתניא באבל רבתי כל שקורעים במיתתו קורעים עליו בשעת ליקוט עצמות עיין שם וגם דברי רבינו ירוחם נתיב כ\"ח ח\"א מגומגמים שכתב ואם אחר כך נמצא ההרוג וקברוהו הורה רבי אליקום דאין מתאבלין עליו אפילו בניו. אבל רבי מאיר כתב דבניו מתאבלין כל אותו היום כדין ליקוט עצמות כו' ויש לישב דבריו דנקט בניו והוא הדין שאר קרובים א\"נ אתא לאפוקי שאותן המתאבלין עם מי שמתאבלין כדלעיל סימן שע\"ד סעיף ו' א\"צ להתאבל כאן אבל דברי הט\"ו אי אפשר ליישב כן וצ\"ע:","\u0003אם הם שם כו'. \u0004אורחא דמילתא נקט דמסתמא כל שאינן שם לא שמעו באותו היום אבל ודאי אע\"פ שאינן שם ושמעו באותו היום צריכין להתאבל כל אותו היום כדלקמן סימן ת\"ג סעיף ה' ולפי מ\"ש בסמוך גם בקרובים הדין כן:","\u0003שדינם להתחיל האבילות משיחזרו פניהם. \u0004היינו היכא שלא הלך גדול הבית עמהם לעיר אחרת כדלעיל סעיף ב' וכ\"כ ב\"י ומביאו בד\"מ ולהכי כתב הרב אם שלחו מתיהם לעיר אחרת כו' דאילו בבה\"ק שבאותה העיר אף החוזרים אינם מתאבלים עד שנאמר להם שנקבר וכמ\"ש לעיל ס\"ק א':","\u0003למקום שמת. \u0004דוקא שבא אצלם למקום שמת או למקום קבורה אבל אם לא היה לא מקום מיתה ולא מקום קבורה כל אחד מונה לעצמו כ\"כ הגהת אשר\"י מא\"ז ומביאו ב\"י וד\"מ:","\u0003וי\"א כו'. \u0004באמת הרב נמשך אחר מ\"ש הב\"י שדעת הרמב\"ם (שהעתיק המחבר דבריו כאן) כדעת הרי\"ף שהשמיט מלכתוב דין דהלך גדול לבה\"ק כו' וגדול הבית שהלך לבה\"ק אינו מונה אלא משיסתם הגולל ואפילו חזר אצל בני הבית ביום ג' והם מונים משיחזרו פניהם והבא ממקום קרוב מונה עם גדול הבית דאחריו הוא נגרר ולא אחר בני הבית עכ\"ל ומביאו ד\"מ וכתב עליו ואני אומר דסברת הרא\"ש הוא סברת רבותינו הצרפתים ור\"ח כמבואר מדברי הרמב\"ן שהביא ב\"י בארוכה ולכן נראה דכוותייהו נקטינן דהלכה כדברי המיקל באבל. ותו דבעלי התוספות ור\"ח והרא\"ש רבים נינהו גם הרא\"ש בתרא הוא והסכים לסברתן וכן הלכה עכ\"ל וע\"פ זה כתב הרב כאן וי\"א כו' ויש להקל כסברא זו כו' אבל באמת אין דברי הב\"י נראים עיקר כמ\"ש בספרי אלא נראה עיקר כמ\"ש הרמב\"ן לדעת הרי\"ף ומביאו ב\"י דס\"ל דאפי' בא הגדול אצל בני הבית תוך ז' מונה עמהם ולא מסתימת הגולל בין שבא ממקום קרוב או רחוק וכן אפי' קטן שהלך לבה\"ק וחזר תוך ז' מונה עמהן וכן הבא ממקום אחר לשם ומצא שהלך גדול הבית לבה\"ק כיון שחזר גדול הבית אפי' ביום ז' מונה עמהן אף זה נגרר עמו ונמצאו כולם מונין מנין א' והוא שבא זה ממקום קרוב וא\"כ גם דעת הרמב\"ם כן שהוא הלך ממש בדרך הרי\"ף רבו ע\"ש והסמ\"ג דף רמ\"ו ע\"ג כ' כל' הרמב\"ם ומדברי רבינו ירוחם נתיב כ\"ח ח\"א נראה שפוסק כהרמב\"ן ע\"ש ודעת הרא\"ש נ\"ל דמפרש הא דאתא בגו תלתא על האחר הבא ולא הוזכר לדבריו בש\"ס אם חזר הגדול לביתו או לא אלא לעולם היכא דהלך הגדול לבית הקברות ובא אחר תוך שלשה מונה עמהן לאחר שלשה מונה לעצמו ואם לא הלך לבית הקברות אז אפי' בא ביום הז' מונה עמהן כרבי שמעון והיינו דכ' הרא\"ש הלך גדול הבית לבה\"ק כו' ובא אחד מן האחין תוך ג' מהו כו' אבל הטור ס\"ל דהרא\"ש מפרש הא דאתא בגו תלתא על הגדול לדבריו שצ\"ל הא דכתב הרא\"ש ובא א' מן האחין תוך שלשה היינו משום דאי בא אחר ג' בעוד שהגדול בבית אז פשיטא ול\"מ לן דהא' מונה עמהן כשחזר הגדול תוך ג' ודוחק וגם לדבריו צ\"ל הא דכ' הרא\"ש והא דמפליג רבי יוחנן הכא בין תוך ג' ובין לאחר ג' היינו היכא דהלך גדול הבית לבה\"ק עכ\"ל היינו דבגדול הבית מפליג בין חזר תוך ג' או לא ולישנא לא משמע הכי ועוד דהעיקר חסר מן הספר וה\"ל לפרש דבגדול הבית הוא דמפליג בין חזר תוך ג' או לא ודוק ודעת ר\"ח ורי\"ץ גיאות ורבותינו הצרפתים שהביא הרמב\"ן ופירש דעתם הכל תלוי במה שהגדול מונה עמהם או לא דאם הגדול מונה עמהם אז גם הבא ממקום קרוב מונה עמהם ואם גדול מונה לעצמו אז גם הבא מונה לעצמו וע\"כ הוכרח לפרש דבריהם שהגדול הלך לבה\"ק קודם סתימת הגולל דאם לא כן לא משכחת לה שהגדול מונה לעצמו והלכך לסברתם שחילקו בין תוך ג' לאחר ג' דינא הכי אם חזר הגדול תוך ג' שאז מונה עמה' ולא מסתימת הגולל גם הבא מונה עמהם ואם חזר אחר ג' שאז מונה לעצמו לסברתם אז גם הבא מונה לעצמו ואינו מונה עמהם ולא עם הגדול רק לעצמו אבל כשחזר הגדול ג\"כ מן המת קודם סתימת הגולל שמתחיל מיד למנות עם שאר בני הבית אף שהולך אח\"כ לבה\"ק וחזר אחר שלשה ימים מ\"מ הרי הוא מונה עמהם וכיון שמונה עמהם א\"כ גם הבא מונה עמהן בכל ענין רק שבא ממקום קרוב אבל להרא\"ש אינו תלוי במה שהגדול מונה עמהן או לא אלא הכל תלוי בין אם בא תוך שלשה או לא ואף שאבלות הגדול התחיל בשוה עם שאר בני הבית יש חילוק בין תוך שלשה או לא וע\"כ כתב הרא\"ש שהלך הגדול לבה\"ק להתעסק בצרכי המת לעשות לו מצבה או צורך בנין בתוך הקבר כלומר שמתחילתן התחיל אבילותם בשוה רק שהלך לבה\"ק אחר הקבורה לצורך מצבה וכה\"ג אז יש חילוק בין תוך ג' לאחר ג' וע\"כ כתב הטור וא\"א הרא\"ש ז\"ל כתב כסברא ראשונה שאינו נגרר אחריהם אלא אם כן חזר הגדול תוך שלשה ימים ולא כתב בקיצור וא\"א ז\"ל כתב כסברא הראשונה שאינו נגרר אחריהם אלא כשבא תוך שלשה אבל לא הוזכר בדבריו לחלק בין סתימת הגולל או לא וכן לענין התחלת אבלות נראה שחולק הרא\"ש שהרי אחר שכתב פירוש דבריו על סוגיא דש\"ס דידן הביא הירושלמי דאית תנוי תני אלו שבכאן מונין משיצא המת ואלו ששם מונין משיסתם הגולל ואית תנוי תני אלו ואלו מונין משיסתם הגולל ר' סימון בשם ריב\"ל אומר הכל הולך אחר גדול שאם היה הגדול כאן אלו ואלו מונין משיצא המת ואם היה הגדול שם אלו ואלו מונין משיסתם הגולל אין שם גדול אלו שכאן מונין משיצא המת ואלו ששם מונין משיסתם הגולל ע\"כ וכ' עלה הך הירושלמי לאו מענין סוגיא דשמעתין אלא איירי בענין התחלת אבלות כדאמרינן בשמעתין אמר ליה רבא לבני מחוזאי אתון דלא אזליתו בתר ערסא מכי אהדריתו אפייכו מבבא דאבולא אתחילו מנו והירושלמי השמיענו שיש חילוק כשיש שם גדול עכ\"ל ר\"ל דש\"ס דידן מיירי כשהתחילו האבילות בשוה כגון שכולם הלכו לקברות בשעת קבורה או שגם הגדול נשאר בבית בענין שהתחילו כולם למנות משיסתם הגולל לאו משיצא המת אלא דאם אח\"כ יצא הגדול לבה\"ק לצורך מצבה וכה\"ג יש חילוק בין תוך ג' לאחר שלשה (אבל לר\"ת וסייעתו וכן להרי\"ף לדעת הרמב\"ן צריך לומר שהירושלמי חולק על ש\"ס דידן וכן הוא בת\"ה בהדיא ע\"ש בדף צ\"ב ע\"ג) ולפי זה היכא שהיה הגדול בשעת קבורה דהיינו בסתימת הגולל והאחרים נשארו בבית לעולם מונין אלו ואלו משיסתם הגולל ולא הוזכר חילוק דתוך ג' או לאחר ג' בכאן ובין חזר הגדול לבית או לא לעולם מתחילין הכל משיסתם הגולל וע\"כ דקדק הטור וכ' וא\"א הרא\"ש ז\"ל כ' כסברא הראשונה שאינו נגרר אחריהם אא\"כ חזר הגדול תוך שלשה רצה לומר בזה דוקא הסכים לסברא הראשונה דלא כהפרישה סעיף כ\"ז שערבב דברי הרמב\"ן עם דעת הרא\"ש וטור ולכן הוקשה לו מ\"ש הטור לעיל (דהיינו שפסק כהירושלמי דלעיל) דהכל הולך אחר הגדול לענין התחלת אבילות ולפמ\"ש לק\"מ דהתם מיירי לענין התחלת אבילות וכאן מיירי שהתחילו שניהם בשוה וזה ברור ומ\"מ בלא\"ה יש לתרץ דהא דכ' לעיל דאלו ואלו מונין משיסתם הגולל היינו היכא דגדול הבית דר שם במקום שיקבר המת וכן מחלק במרדכי וז\"ל ור' אברהם פירש דכולהו מונין משיצא מפתח ביתו לפי שהוא טפל להם וכן מצאתי כתוב בשם ר\"י ופירש דירושלמי פליג אש\"ס דידן וכש\"ס דידן עבדינן דמונה עמהם והוא דאתא בגו תלתא יומי אבל אתא בתר תלתא יומי מונה לעצמו משיסתם הגולל לפי דבריו כשהוא דר כאן והלך לבה\"ק כן הוא הדין אבל אם גדול הבית דר שם במקום שיקבר המת אז אלו ואלו מונין משיסתם הגולל כדברי הירושלמי ולא יחלוק על ש\"ס שלנו לפ\"ז עכ\"ל ובע\"כ לדברי המחבר צריך לתרץ כן שהרי העתיק דברי הרמב\"ם דמשמע מיניה מיהא בין לפי מה שפי' הוא דבריו בין לפי מה שפירשתי דבריו דאלו שנשארו כאן מיהא מונין משיצא המת ולא משיסתם הגולל אע\"ג דהגדול היה בשעת סתימת הגולל בבה\"ק ולעיל סעיף ב' כתב ואם גדול המשפחה הולך עמו אף אלו שבכאן אינן מונין אלא משיקבר א\"ו התם מיירי דגדול הבית דר במקום שיקבר והאי דר שם נראה לי היינו דכיון דדר שם ונשאר שם הולכים אחריו אבל אם לא נשאר שם כי דר שם מאי הוי ס\"ס השתא הוא אצלם ונראה דאף הרמב\"ן שכ' דהירושלמי מיירי בכל גווני אפילו היכא דהגדול חזר אצלם ולכך הוצרך לומר דפליג אש\"ס דידן תדע דע\"כ במרדכי גופיה צ\"ל כן שמתחילה כתב ופירוש ירושלמי פליג אש\"ס דידן כו' ואח\"כ כתב ולא יחלוק על ש\"ס שלנו לפ\"ז א\"ו מ\"ש מתחילה דפליג היינו בחזר הגדול לביתו משום דבירושלמי אינו מחלק בכך ומשמע דבכל ענין הולכים אחר הגדול ומ\"ש אח\"כ ולא יחלוק כו' היינו דנשאר שם במקום שדר שם ולענין דינא נראה עיקר כסברת הרי\"ף והרמב\"ם והרמב\"ן והסמ\"ג ורבינו ירוחם דלעיל דרבים וגדולים נינהו ומקילין באבל וגם רבינו ירוחם בתרא הוא וכ' מהרש\"ל דאף הרמב\"ן מודה היכא שלא נשארו מקצתן בבית דמונה לעצמו והביאוהו האחרונים ומשמע מדבריו שם דמודה להרא\"ש וא\"כ אם בא תוך ג' מיהת מונה עמהן אף שלא נשארו מקצתן בבית ודוק. אלא מיהו היכא דהתחיל הגדול למנות עמהן בשוה ואח\"כ הלך לבה\"ק לצורך מצבה וכה\"ג נהי דלהרמב\"ן בכל ענין מונה עמהן היינו היכא דחזר הגדול אצלן תוך ז' אבל היכא דלא חזר כלל מזה לא הוזכר בדבריו ונראה דקי\"ל כהרא\"ש בהא דאם בא אחד ממקום קרוב תוך ג' מונה עמהן דהוי כמי שישנו בבית ואם בא אחר ג' מונה לעצמו כיון דאין הגדול שם ודוקא כשהלך להתעסק בצרכי המת אבל אם הלך בעסק אחר בכל ענין מונה לעצמו כיון שלא חזר הגדול תוך ז' וכל גדול שבענין זה היינו כמו גדול דלעיל סעיף ב'. וכן משמע מדברי הפוסקים בהדיא מיהו היכא דאשתו מתה ובאו אחים ושאר קרובים הבעל נקרא גדול הבית מפני שהוא חייב בקבורתה ולטפל יותר מן האח או האב ואין הולכים אחר המצטער יותר שאין כל הדעות שוות. כ\"כ הרשב\"א בתשוב' סי' תע\"ח:","\u0003והבא תוך ג' מונה עמהן. \u0004לא ידענא למה הצריך שיבא תוך ג' דהא לסברא זו דהטור א\"צ רק שהגדול יחזור תוך ג' ואפי' בא הקרוב ביום ז' מונה עמהן ואפשר דנקט תוך ג' לרבותא דאע\"פ שבא בעוד שלא היה גדול הבית בבית ואצ\"ל אם בא אחר ג' בעוד שחזר הגדול תוך ג' וכעין מה שפירשתי לעיל לישנא דהרא\"ש ובא אחד מן האחים בתוך ג' כו' לדעת הטור ואפשר דאפי' לסברא הראשונה אם בא אחר שלשה בעוד שחזר הגדול לבית מונה עמהם כיון דבא אצלם וגדול הבית שם להכי נקט תוך שלשה דלסברא הראשונה מונה לעצמו א\"א משום דהרב נטה לסברת הרא\"ש דבתראי הוא וכמ\"ש בד\"מ הבאתיו לעיל וספוקי מספקא ליה בדעת הרא\"ש הא דמחלק בין תוך שלשה אי קאי אגדול וכדעת הטור או אקרוב הבא וכדפרש\"י הלכך אזיל הכא והכא לחומרא ודו\"ק:","מזה מי שמת לו קרוב ונודע לו במקומו מונה לעצמו משנודע לו ואפי' בא אח\"כ למקום המת אצל שאר הקרובים שהתחילו כבר להתאבל לא יקצר אבילותו בשביל זה וכן אם בא אצל הקרובים ואינם במקום שמת המת ולא במקום קבורה כל אחד מונה לעצמו משעה שנודע לו אבל אם לא ידע שמת לו מת עד שבא אל הקרובי' שבמקום המת או מקום קבורה אם היה במקום קרוב שהוא מהלך עשר פרסאות אפי' בא ביום הז' אם מצא מנחמין אצל גדול הבית אפילו שננערו לעמוד הואיל ומצא מנחמין דהיינו שנוהגין עדיין קצת אבילות מונה עמהן דכיון שהגדול מונה עמהן גם הוא מונה עמהן אבל אם לא מצא אצלן גדול הבית מונה לעצמו וכן גדול הבית שבא ממקום קרוב מונה לעצמו ואם בשעת קבורה הלכו מקצת הקרובי' לבית הקברות מונין עם אלו שבבית בין גדולים בין קטנים בין שבה\"ק קרוב או רחוק בין באו תוך ג' בין ביום ז' והוא שבאו ומצאו מנחמין אבל אם לא מצאו מנחמין ביום ז' אותן שהלכו לבה\"ק מונין לעצמן משיסתם הגולל וכן הבא ממקום אחר לשם ומצא שהלך הגדול לבה\"ק כיון שחזר הגדול אצלם אפי' ביום ז' ומונה עמהם אף זה נגרר עמהם ונמצא כולם מונין מנין א' והוא שבא זה ממקום קרוב ודוקא שנשארו מקצתן בבית אבל אם לא נשארו מקצתן בבית מונה לעצמו אם לא שבא תוך ג' ואם לא חזר הגדול תוך ז' שאז הגדול מונה לעצמו משיסתם הגולל אז גם הבא ממקום קרוב אינו מונה עם אותן שבבית משיצא המת אלא מונה לעצמו משעה שנודע לו וכל זה שהלך הגדול לבה\"ק במקום שאינו דר שם אבל הלך למקום שדר שם ונשאר שם אפי' אותן שנשארו כאן שהחזירו פניהם מהמת הולכים אחריו ומונים משיסתם הגולל ודוקא שיכול לבא שם תוך ג' אבל אם אינו יכול לבא שם תוך ג' אלו שכאן מונין מיד וגדול שבבה\"ק מונה משיסתם הגולל ואם התחילו אותן שבבית והגדול למנות אבלותן בשוה כולם משיצא המת או כולם משיסתם הגולל אז הבא ממקום קרוב מונה עמהן בכל ענין אפי' בא ביום הז' בעוד שנוהגין קצת אבילות כיון שחזר הגדול קודם שעמדו המנחמין ומונה עמהן אבל אם התחילו אבילות בשוה והלך הגדול אח\"כ לבה\"ק להתעסק בצרכי המת לעשות מצבה או בנין לקבר ולא חזר כלל אחר שבא הקרוב או שחזר אחר שעמדו המנחמין דינא הכי אם בא הקרוב תוך ג' מונה עמהם ואם בא לאחר ג' מונה לעצמו ואם הלך הגדול לעסק אחר שלא בצרכי המת אפילו בא הקרוב תוך ג' מונה לעצמו כיון שלא חזר הגדול לביתו ואם בא הקרוב ממקום רחוק בכל ענין מונה לעצמו וכל שדינו למנות עמהם אפילו חזר אח\"כ לביתו מונה עמהן:","\u0003מי שהתפללו ערבית. \u0004וגם הוא התפלל וכן במרדכי ובתשו' מהרי\"ל סימן פ\"א ובב\"ח העתיק מי שהתפלל ערבית כו' וכן בת\"ה סימן רמ\"א אבל אם הוא עדיין לא התפלל ערבית כתבו מהרש\"ל והב\"ח שם שאותו יום עולה לו אף ע\"פ שהקהל התפללו ערבית אפילו למ\"ד לעיל ס\"ס קצ\"ו לענין נדה דבתר צבורא גרירא שאני אשה שרובן אינן מתפללים ונגררות אחר הקהל לכן אף אם היא רגילה להתפלל לא חילקו בדבר משא\"כ הכא כן כתב מהרש\"ל שם וכן כתב הגאון אמ\"ו זצ\"ל בתשובה דאם לא התפלל הוא אף על פי שהצבור התפללו אותו היום עולה לו דהא בכה\"ג לא עביד תרי קולי דסתרי אהדדי ואפי' למאן דמחמיר לעיל סימן קצ\"ו שאני אבילות דרבנן דקי\"ל הלכה כדברי המיקל באבל א\"נ יש לחלק דלעיל איירי שהקהל התפללו ערבית והיא רצתה להקל על עצמה ולעשות יום וללבוש לבנים לאו כל כמינה לאפוקי נפשה מצבורא אבל כאן מן השמים שלחו לו אבלות בעודו יום ולא התפלל יכול לומר לדידי יום הוא ומהרש\"ל בתשובה חילק בע\"א ולדעתי הוא חילוק קלוש ויותר נ\"ל כמ\"ש עכ\"ל ודבריו נכונים. ולפ\"ז אם אירע אבילות זו לאשה שלא התפללה אותו יום עולה לה) דלא כמהרש\"ל וכן עיקר:","\u0003ואותו יום אינו עולה. \u0004כתב העט\"ז ולפי מ\"ש לעיל ר\"ס קצ\"ו גבי לובשת לבנים דהמיקל לא הפסיד נ\"ל דכ\"ש באבל דהמיקל למנות יום ששמע ליום א' אע\"פ שהתפללו הקהל ערבית לא הפסיד נ\"ל עכ\"ל ואין נ\"ל דהא דין דהכא לקוח ממרדכי בשם מהר\"ם ומביאו בת\"ה סי' רמ\"א ויליף מינה לענין נדה וכ' שם שאחד מן הגדולים כתב לו בתשובה שאין לדמות נדה לאבלות משום דאותה שעה דמתפלל ערבית אינו אלא סניף ותוספת ליום שלאחריו ואינו עיצומו של יום ולכך לענין אבלות לא חשיב כיום דהא סניף הוא ותוספות ליום שלאחריו אבל לענין ספירה לא קפדינן אלא אעיצומו של ז' ימים ולא על התוספת עכ\"ד וא\"כ אנן קי\"ל כגדול זה וכן משמע מדברי הב\"ח ושאר אחרונים דמקילין גבי נדה ולא הכא ואפשר גם העט\"ז לא קאמר אלא כשהתפללו הקהל ערבית ולא הוא דאז אותו יום עולה לו וכמ\"ש בסמוך:"],["\u0003סתימת הקבר בעפר. \u0004דמ\"ש בגמרא עד שיסתום הגולל פרש\"י כסוי הארון ופירש הרמב\"ן דהיינו כשנותנין אותו בארון וסותמין הכיסוי בנסרים לדעת ליתן אותו ארון בכוך או קבר אח\"כ אז מונה משעת סתימת הארון אבל אם מוציאין במטה או בארון פתוח לבה\"ק מונים משיסתום הקבר לגמרי ור\"ת פי' גולל הוא האבן שנותנין על הקבר למעלה לסתמו ולא לעשות סימן לקבר וכל זמן שהארון מגולה דהיינו שלא ניתן עליו עפר עדיין אע\"פ שנשתקע במסמרים אין אבילות עדיין:","\u0003או משנתיאשו לקברו. \u0004מעשה ביהודי אחד שהרגוהו והשליכוהו בנהר רינו\"ס ובעשרה בטבת היה המעשה ולפני אדר נתיאש בנו מלבקשו עוד והורה ר' יעקב למנות מעתה שבעה ושלשים ולאחר שעברו ימי האבילות נמצא אביו בתוך הנהר והובא לבה\"ק והורה לו הזקן רק לקרוע והסכים עמו הרמב\"ן:","\u0003במים שיש להם סוף. \u0004דאלו במים שאין להם סוף אין היתר לאשתו דבחזקת חי קיים ע\"כ לא ינהג אבילות כ\"כ בית יוסף בשם בעל העיטור:","\u0003אינו עולה. \u0004דהוו תרי קולי דסתרי אהדדי ועיין מה שכתבתי בזה סי' ת\"ב סעיף י\"א:"]],["אֵין הַמְנַחֲמִים רַשָּׁאִים לִפְתֹּחַ, עַד שֶׁיִּפְתַּח הָאָבֵל תְּחִלָה. וְהָאָבֵל מֵסֵב בָּרֹאשׁ, וְכֵיוָן שֶׁנִּעְנַע הָאָבֵל בְּרֹאשׁוֹ, בְּעִנְיָן שֶׁנִּרְאֶה שֶׁפּוֹטֵר אֶת הַמְנַחֲמִים, אֵינָם רַשָּׁאִים לֵישֵׁב אֶצְלוֹ. \u0005אֵין אָבֵל אוֹ חוֹלֶה חַיָּבִים לַעֲמֹד, אֲפִלּוּ מִפְּנֵי נָשִׂיא (פ' א\"מ)\u0006.\nהַבָּא לְכַבֵּד אֶת חֲבֵרוֹ וְלָקוּם מִפָּנָיו, אוֹמֵר לוֹ: שֵׁב, אֶלָא אִם כֵּן הוּא אָבֵל אוֹ חוֹלֶה, דְּמַשְׁמָע: שֵׁב בָּאֲבֵלוּת שֶׁלְךָ, שֵׁב בַּחֹלִי שֶׁלְךָ. \u0005הַגָּה: לֹא יֹאמַר אָדָם: לֹא נִפְרַעְתִּי כְּפִי מַעֲשַׂי, אוֹ כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ, שֶׁאַל יִפְתַּח פִּיו לַשָּׂטָן (כֵּן מַשְׁמָע בְּפֶרֶק מִי שֶׁמֵּתוֹ וּבְהַגָּהוֹת אַלְפָסִי שָׁם)\u0006. וְאַל יֹאמַר אָדָם לְאָבֵל: מַה לְּךְ לַעֲשׂוֹת כִּי אִי אֶפְשָׁר לְשַׁנּוֹת, שֶׁזֶּהוּ \u0010c0\u0011 כְּגִדּוּף, דְּמַשְׁמָע הָא אִם אֶפְשָׁר לְשַׁנּוֹת הָיָה עוֹשֶׂה, אֶלָּא יְקַבֵּל עָלָיו גְּזֵרַת הַשֵּׁם יִתְבָּרַךְ מֵאַהֲבָה \u0005(נ\"י פ' שׁוֹר שֶׁנָּגַח דְּמַשְׁמָע כֵּן בַּגְּמָרָא)\u0006.\nמֵת שֶׁאֵין לוֹ אֲבֵלִים לְהִתְנַחֵם, בָּאִים עֲשָׂרָה בְּנֵי אָדָם כְּשֵׁרִים וְיוֹשְׁבִים בִּמְקוֹמוֹ כָּל ז' יְמֵי הָאֲבֵלוּת, וּשְׁאָר הָעָם מִתְקַבְּצִים עֲלֵיהֶם; וְאִם לֹא הָיוּ שָׁם עֲשָׂרָה קְבוּעִים, בְּכָל יוֹם וְיוֹם מִתְקַבְּצִים עֲשָׂרָה מִשְּׁאָר הָעָם וְיוֹשְׁבִים בִּמְקוֹמוֹ. \u0005הַגָּה: וְלֹא רָאִיתִי נוֹהֲגִין כֵּן. וְכָתוּב במהרי\"ל: \u0010c1\u0011 נוֹהֲגִים לְהִתְפַּלֵּל בַּעֲשָׂרָה כָּל ז' בַּמָּקוֹם שֶׁנִּפְטַר שָׁם הָאָדָם, \u0010y0\u0011 וְהַיְנוּ עַל אָדָם שֶׁלֹּא הִנִּיחַ קְרוֹבִים יְדוּעִים לְהִתְאַבֵּל עָלָיו, אֲבָל יֵשׁ לוֹ בְּשׁוּם מָקוֹם שֶׁמִּתְאַבְּלִים עָלָיו, אֵין צָרִיךְ וְכָזֶה רָאוּי לִנְהֹג.\u0006\nעַכְשָׁו נוֹהֲגִים שֶׁאַחַר שֶׁנִּגְמַר סְתִימַת הַקֶבֶר מֵעָפָר \u0005אוֹ לְאַחַר שֶׁהָפַךְ הָאָבֵל פָּנָיו מִן הַמֵּת,\u0006 \u0010y1\u0011 חוֹלְצִין מִנְעָל וְסַנְדָּל \u0010y2\u0011 וּמַרְחִיקִין מְעַט מִבֵּית הַקְבָרוֹת, וְאוֹמְרִים קַדִּישׁ דְּהוּא עָתִיד לְחַדְּתָא עָלְמָא, \u0010y3\u0011 וְאַחַר כָּךְ \u0010y4\u0011 תּוֹלְשִׁין עָפָר וְתוֹלְשִׁין עֲשָׂבִים, וּמַשְׁלִיכִים אַחַר גֵוָם וְרוֹחֲצִין יְדֵיהֶם בְּמַיִם. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁיּוֹשְׁבִים ז\"פ, מִפְּנֵי שֶׁהָרוּחוֹת מְלַוּוֹת אוֹתוֹ, וְכָל זְמַן שֶׁיּוֹשְׁבִין, בּוֹרְחִין מִמֶּנּוּ (מהרי\"ל בִּתְשׁוּבָה כ\"ג בְּשֵׁם י\"א)\u0006. וּבִמְדִינוֹת אֵלּוּ לֹא נָהֲגוּ לֵישֵׁב \u0010y5\u0011 \u0010c2\u0011 רַק ג\"פ, אַחַר שֶׁרָחֲצוּ הַיָּדַיִם, וְאוֹמְרִים כָּל פַּעַם: וִיהִי נֹעַם וְגו' \u0005(תְּהִלִּים צ, יז)\u0006, יוֹשֵׁב בְּסֵתֶר \u0005(תְּהִלִּים צא, א)\u0006 וְגו' וּכְשֶׁנִּקְבָּר הַמֵּת בְּיוֹם טוֹב, יְכוֹלִין לֵישֵׁב כָּךְ ג\"פ כְּמוֹ בַּחֹל \u0005(מ\"כ בְּהַגָּהוֹת מִנְהָגִים)\u0006. וְהוּא הַדִּין אִם נִקְבַּר סָמוּךְ לְשַׁבָּת, עוֹשִׂין כֵּן בְּשַׁבָּת. וְנָהֲגוּ לְהַקְפִּיד אִם יִכָּנֵס אָדָם לְבַיִת אַחֵר קֹדֶם שֶׁיִּרְחַץ וְיֵשֵׁב ג\"פ, וּמִנְהַג אֲבוֹתֵינוּ תּוֹרָה \u0005(שָׁם במהרי\"ל)\u0006. וְנִמְצָא בְּמִדְרָשׁוֹת לוֹמַר קַדִּישׁ עַל אָב \u0005(כָּל בּוֹ וריב\"ש בְּשֵׁם תַּנְחוּמָא וְסִפְרִי, וּבְחַיֵּי בְּשֵׁם מַסֶכֶת כַּלָּה, וּבֵית יוֹסֵף בְּשֵׁם הַזֹּהַר, וּבְאוֹר זָרוּעַ בְּשֵׁם תַּנָּא דְּבֵי אֵלִיָּהוּ רַבָּא)\u0006 ; עַל כֵּן נָהֲגוּ לוֹמַר עַל אָב וָאֵם קַדִּישׁ בַּתְרָא י\"ב חֹדֶשׁ, וְכֵן נָהֲגוּ לְהַפְטִיר בַּנָּבִיא, וּלְהִתְפַּלֵּל עַרְבִית בְּמוֹצָאֵי שַׁבָּתוֹת שֶׁהוּא הַזְּמַן שֶׁחוֹזְרִין הַנְּשָׁמוֹת לְגֵיהִנֹּם, וּכְשֶׁהַבֵּן מִתְפַּלֵּל וּמְקַדֵּשׁ בָּרַבִּים, פּוֹדֶה אָבִיו וְאִמּוֹ מִן הַגֵּיהִנֹּם \u0005(כָּל בּוֹ בְּשֵׁם הַגָּהוֹת)\u0006. וְנָהֲגוּ לוֹמַר קַדִּישׁ עַל הָאֵם אַף עַל פִּי שֶׁהָאָב חַי עֲדַיִן, אֵינוֹ בְּיָדוֹ לִמְחוֹת לִבְנוֹ שֶׁלֹּא יֹאמַר קַדִּישׁ עַל אִמּוֹ \u0005(סְבָרַת הַבֵּית יוֹסֵף עַל פִּי הַמִּנְהָג)\u0006. מִצְוָה לְהִתְעַנּוֹת בְּיוֹם שֶׁמֵּת אָב אוֹ אֵם \u0005(ריב\"ש וְכָל בּוֹ)\u0006. \u0010y6\u0011 שְׁלֹשָׁה אַחִין וְאִישׁ נָכְרִי, הַשְּׁלֹשָׁה אַחִין נוֹטְלִין הַשְּׁלֹשָׁה קַדִּישִׁין וְהָאוֹמֵר נוֹטֵל קַדִּישׁ אֶחָד. וְנָהֲגוּ שֶׁאִם מַגִּיעַ לְאָדָם יוֹם שֶׁמֵּת בּוֹ אָבִיו וְאִמּוֹ, שֶׁאוֹמְרִים עֲלֵיהֶם קַדִּישׁ יָתוֹם לְעוֹלָם, וּמִי שֶׁיּוֹדֵעַ לְהִתְפַּלֵּל כָּל הַתְּפִלָּה, מִתְפַּלֵּל; וְאִם יֵשׁ אֲבֵלִים אֲחֵרִים, נָהֲגוּ \u0010y7\u0011 \u0010c3\u0011 שֶׁתּוֹךְ שִׁבְעָה לְאֶבְלָם \u0010y8\u0011 הֵם קוֹדְמִים, וְאֵין לוֹ קַדִּישׁ כְּלָל; \u0010y9\u0011 תּוֹךְ שְׁלֹשִׁים, יֵשׁ לוֹ קַדִּישׁ אֶחָד; לְאַחַר ל', כָּל הַקַּדִּישִׁים שֶׁל אוֹתוֹ הַיּוֹם הֵם שֶׁלּוֹ. וּמוֹנִין שִׁבְעָה וְל' מִיּוֹם הַקְּבוּרָה, אַף עַל פִּי שֶׁלֹּא שָׁמַע הָאָבֵל מִיָּד \u0005(במהרי\"ל)\u0006. \u0010y10\u0011 וְאִם \u0010y11\u0011 נָכְרִי הוּא כְּאֶחָד מִבְּנֵי הָעִיר לְעִנְיַן קַדִּישׁ זוֹ, \u0010y12\u0011 הוֹלְכִים אַחַר הַמִּנְהָג \u0005(אָגוּר)\u0006. וְאֵין מָקוֹם לְקַדִּישׁ זוֹ אֶלָּא עַל אָב וָאֵם בִּלְבַד, אֲבָל לֹא בִּשְׁאָר קְרוֹבִים \u0005(בְּאוֹר זָרוּעַ)\u0006. וְאִם אֵין בב\"ה אָבֵל עַל אָבִיו וְאִמּוֹ, אוֹמֵר אוֹתוֹ קַדִּישׁ מִי שֶׁאֵין לוֹ אָב וָאֵם, בְּעַד כָּל מֵתֵי יִשְׂרָאֵל. \u0005(שָׁם)\u0006 וְיֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ שֶׁשְּׁאָר קְרוֹבִים אוֹמְרִים קַדִּישׁ עַל קְרוֹבֵיהֶם כְּשֶׁאֵין אֲבֵלִים עַל אֲבִיהֶם וְאִמָּם, וְיֵשׁ מְקוֹמוֹת שֶׁאֲפִלּוּ יֵשׁ אֲבֵלִים עַל אֲבִיהֶם וְאִמָּם, אוֹמְרִים שְׁאָר קְרוֹבִים, אֶלָּא שֶׁעוֹשִׂים פְּשָׁרָה בֵּינֵיהֶם שֶׁאֵין אוֹמְרִים כָּל כָּךְ קַדִּישִׁים כְּמוֹ הָאֲבֵלִים עַל אָב וָאֵם \u0005(מהרי\"ק שֹׁרֶשׁ מ\"ד)\u0006 ; וְהוֹלְכִין בְּכָל זֶה אַחַר הַמִּנְהָג, וּבִלְבַד שֶׁיְּהֵא מִנְהָג קָבוּעַ בָּעִיר. וְהָאֲבֵלִים אוֹמְרִים קַדִּישׁ אֲפִלּוּ בְּשַׁבָּת וְיוֹם טוֹב \u0005(בְּאוֹר זָרוּעַ בְּשֵׁם ר\"י \u0010y13\u0011 מקורבי\"ל)\u0006, אֲבָל לֹא נָהֲגוּ לְהִתְפַּלֵּל בְּשַׁבָּת וְיוֹם טוֹב \u0005(כֵּן הוּא בִּתְשׁוּבַת מהרי\"ל)\u0006, אַף עַל פִּי שֶׁאֵין אִסּוּר בַּדָּבָר, אֲבָל בִּימוֹת הַחֹל, מִי שֶׁיּוֹדֵעַ לְהִתְפַּלֵּל, יִתְפַּלֵּל וְיוֹתֵר מוֹעִיל מִקַּדִּישׁ יָתוֹם שֶׁלֹּא נִתְקַן אֶלָּא לִקְטַנִּים; וּמִי שֶׁאֵינוֹ יוֹדֵעַ לְהִתְפַּלֵּל כָּל הַתְּפִלָּה, יִתְפַּלֵּל לַמְנַצֵּחַ וּבָא לְצִיּוֹן וְכו' \u0005(בְּאוֹר זָרוּעַ)\u0006. וְנָהֲגוּ שֶׁאֵין אוֹמְרִים קַדִּישׁ וּתְפִלָּה \u0010c4\u0011 רַק י\"א חֳדָשִׁים, כְּדֵי שֶׁלֹּא יַעֲשׂוּ אֲבִיהֶם וְאִמָּם רְשָׁעִים, כִּי מִשְׁפַּט רָשָׁע י\"ב חֹדֶשׁ. וְאִם הָיוּ אֲבֵלִים כָּאן וּבָאוּ אַחַר כָּךְ אֲבֵלִים אֲחֵרִים, הַשְּׁנִיִּים יֵשׁ לָהֶם הַקַּדִּישִׁים וְהַתְּפִלּוֹת כָּל ל' יוֹם מִיּוֹם הַקְּבוּרָה, אַף עַל פִּי שֶׁלֹּא שָׁמְעוּ. \u0010y14\u0011 יֵשׁ אוֹמְרִים דְּמוּמָר \u0010c5\u0011 שֶׁנֶּהֱרַג בְּיַד עוֹבְדֵי כּוֹכָבִים, בָּנָיו אוֹמְרִים עָלָיו קַדִּישׁ \u0005(הרד\"כ בַּיִת י\"א ובב\"ז)\u0006 וְעַיֵּן לְעֵיל סִימָן ש\"מ.",["\u0003והיינו על אדם כו'. \u0004ע\"ל סימן שפ\"ד סעיף ג' בהג\"ה:","\u0003חולצים מנעל כו'. \u0004וע\"ל ס\"ס שפ\"ב:","\u0003ומרחיקין מעט מבה\"ק. \u0004כדי לומר קדיש לפחות ד\"א שהמת תופס ד\"א עכ\"ל עט\"ז וכ\"כ לעיל ס\"ס שס\"ז בשם האחרונים דאף לקדיש צריך להרחיק ד\"א. כתוב בב\"ה בשם א\"ח דאם נקבר בלילה א\"א לא צדוק הדין ולא קדיש בבה\"ק וכ\"כ בב\"י בשם הכל בו ():","\u0003ואחר כך תולשים עפר כו'. \u0004ואומרים זכור כי עפר אנחנו וגם הוא רמז לתחיית המתים שיחיו מעפרם ע\"ד ויציצו (ויפרחו) מעיר כעשב הארץ:","\u0003תולשים עפר כו'. \u0004לומר דטומאה זו אינה נטהרת אלא בכעין ג' דברים הללו מים ואפר פרה ואזוב. רמב\"ן. והכל בו כתב תולשים עשבים בצרור עפרם וזורקם על ראשו דרך צער ע\"ד ויזרקו עפר על ראשיהם השמימה:","\u0003רק שלש פעמים כו'. \u0004ועי' בעט\"ז שכ' דיש לישב ז\"פ בפסוק דכי מלאכיו יצוה לך וגו' ויאמר אתה גבור כו' שיש בזה סוד הקבל' להבריח כחות הטומאה ע\"כ וכ\"כ בפרישה בשם מהרש\"ל שקבל כך מאמ\"ז לומר ז' פעמים בפסוק כי מלאכיו גו' ע\"ש:","\u0003ג' אחין ואיש נכרי כו'.\u0004 כלומר נכרי שאינו אח שלהן אפי' הוא תושב:","\u0003שתוך ז' לאבלם כו'. \u0004כתוב במנהגים דהיינו דוקא בשבת שבתוך ז' אבל בחול אינו הולך לב\"ה אך אם הבן ז' הוא קטן שאינו בר מצוה והולך לב\"ה כל ז' לומר קדיש או מי שאירע לו מיתת אב ואם תוך אותן ז' יאמר קדיש יתום פעם א' עכ\"ל ונרא' דמי שבטלה אבלותו ברגל כגון שעה א' לפני הרגל בטלה ממנו גזירת ז' או ל' מ\"מ דין ז' ול' יש לו אפילו בחול כמו בשבת דהרי בדין הולך לב\"ה. כ' בתשו' מ\"ב סי' ע\"ג שדברי המנהגי' סותרי' זא\"ז דמתחלה כ' יום שמת אב ואם לתושב דוחה את בן ל' מכ\"ש בן י\"ב חדש לתושב כל אותו יום התענית דהיינו תפלת ערבית ושחרית ומנחה וכן הקדישי' של אותו יום שאומרים לפני העמוד אלמא דסבירא ליה דיא\"צ עדיף ושוב כ' דבן י\"ב חדש ויארצייט אורח יש לאורח קדיש א' אבל בן ל' אורח מחלק עמו כל הקדישים והתפלות אלמא דבן ל' עדיף ותירץ דברישא מיירי שיש הרבה יארצייט דאם לא יאמרו כלל עבר זמנו בטל קרבנו ולפי זה מ\"ש במנהגים אם הבן ז' קטן או מי שאירע יארצייט תוך אותן ז' יאמר קדיש יתום פעם א' זהו דוקא ביארצייט מטעם דעבר זמנו בטל קרבנו אבל לבן ל' א\"צ ליתן אפילו קדיש א' עכ\"ל ולא משמע הכי ברישא דיש הרבה יארצייט ועוד מדכתב דוחה את בן ל' מכ\"ש בן י\"ב חודש כו' אלמא דבגוני דאיירי בי\"ב חדש מיירי בל' ובי\"ב חדש ודאי מיירי אפילו ביארצייט א' ועוד דא\"כ מאי כ\"ש הוא דילמא היכא דליכא אלא יארצייט א' אינו דוחה אפילו י\"ב חדש והא דדוחה בן ל' היינו משום דיש הרבה יא\"צ אלא נראה דהדברים כפשטן דמיירי שיש רק יא\"צ א' ואפ\"ה דוחה את הבן ל' דס\"ל למנהגים דיא\"צ עדיפא מבן שלשים. וכן משמע מהעט\"ז שהבאתי לקמן דדעת המנהגים כן ול\"ק מ\"ש בסוף דאורח יא\"צ יש לו רק קדיש א' והבן ל' חולק עם תושב בן י\"ב די\"ל דודאי לענין אורח נגד תושב בן ל' עדיף משום דמצי התושב לומר מן הדין אין ליתן לך כלל דהרי היכא דשניהם בן ל' או יארצייט או בני י\"ב חדש אין לאורח כלום אלא כיון דאתה ל' ואני י\"ב חדש אתה חולק עמי אבל ביארצייט שזמנו קבוע וגם ידוע לו קודם לכן שנה תמימה ואתה באת בגבולי די לך בקדיש אחד אבל בבן ל' ליכא למימר הכי ולפי זה לדידן דקים לן דבן ל' עדיף א\"כ אירע בן ל' תושב תוך ז' לקטן יש לו ג\"כ קדיש אחד והכי נהוג:","\u0003הם קודמים כו'.\u0004 כתוב במנהגים דאפילו הבן ז' הוא נכרי דוחה את התושב אפילו בן ל' או יארצייט:","\u0003תוך שלשים יש לו קדיש אחד. \u0004ליארצייט אבל לבן י\"ב חדש אין לו כלום שהתושב בן שלשים דוחה את התושב בן י\"ב בתפלה ובקדיש לפני העמוד אך בקדיש ובפריסת שמע שעל פתח ב\"ה שניהם שוין בו ויחלקו בגורל כ\"כ במנהגים ויש מנהגים אחרים בקדיש ופריסת שמע שעל הפתח ונהרא נהרא ופשטיה ועיין עוד במנהגים מדינים אלו. ומ\"ש תוך שלשים יש לו קדיש אחד משמע דאם יש שלשה קדישים כגון בשבת אומר הבן שלשים שני קדישים והיארצייט קדיש אחד וכן משמע במהרי\"ל סוף הל' תפלה ובמנהגים כתוב ויום שמת בו אב ואם לתושב דוחה את בן שלשים מכ\"ש בן י\"ב חודש לתושב כל אותו יום התענית דהיינו תפלת ערבית שחרית ומנחה וכן הקדישים של אותו יום שאומרים לפני העמוד ע\"כ. מיהו הלבוש בא\"ח סימן קל\"ג השיג על זה וז\"ל ול\"נ שאין היארצייט דוחה את הבן שלשים מכל וכל אלא די לו בקדיש אחד עכ\"ל וזהו כדעת מהרי\"ל והרב וכ\"פ בתשובת מ\"ב סימן ע\"ג וכן עיקר וכתב עוד שם דהיינו דוקא דליכא אלא יארצייט אחד ובן שלשים אחד אבל היכא דבן שלשים ויארצייט הם רבים ואי אפשר ליתן קדיש לכל אחד ואחד ובע\"כ נידחין קצתן בכה\"ג היארצייט עדיף ונדחה הבן שלשים מפני היארצייט שאם לא יאמר היארצייט קדיש היום למחר עבר זמנו ובטל קרבנו מה שאין כן בבן שלשים ע\"כ ואע\"פ שהוציא כן מתוך מה שתירץ ליישב דברי מנהגים אהדדי ואין דבריו מוכרחים בתירוץ זה וכמ\"ש לעיל מ\"מ הסברא נכונה וכן נהגו:","\u0003ואם נכרי הוא באחד מבני העיר לענין קדיש זו הולכין אחר המנהג. \u0004יש קהילות דנהיגי דתושב דוחה את האורח ויש מקומות דנהיגי דשוין הן ומקומות דנהיגי דתושב דוחה את הנכרי מ\"מ פעם ראשונה יש רשות לנכרי להתפלל ולומר קדיש יתום פעם אחת. כ\"כ במנהגים. ונראה לי דהא דיש לו לאורח קדיש אחד היינו דהוי כמו תושב בן י\"ב חדש ולפי זה היכא דהתושב אין לו קדיש אחד כגון שיש כאן בן שלשים וכה\"ג גם לאורח אין לו כלום:","\u0003נכרי כו'. \u0004כתוב במנהגים אם אותו שמת יש לו בנים בעיר אחרת ובאו לשם אינם נקראים תושבים בשביל אביהם שנקבר שם רק אותן הדרים תוך הקהלה וכל דרי הקהלה נקראים תושבים הן אותן שנותנים מס או משרתי הקהלה ואפי' עניי העיר שיש להם שם דירת קבע כולם חשבינן כתושבים ואם אדם קובע דירתו תוך הקהלה אז משעה שהוא חייב לישא בעול עם דרי הקהלה חשוב תושב אבל לא משעה שגמר פיסוק המס עם ההגמון אע\"ג שצריך ליתן המס להגמון וכן איפכא מי שעקר דירה מן הקהלה אז משעה שאינו חייב לישא בעול עם דרי הקהלה חשוב כאורח אע\"פ שחייב עדיין ליתן המס להגמון ואם יש לבעל הבית מלמד או שמש המושכר לזמן והוא פנוי שאין לו אשה ובנים אז גם הוא נקרא תושב אבל אם יש לו אשה ובנים במקום אחר אז דינו כנכרי ואם בעל הבית מגדל בביתו יתום אפילו בשכר ואין לו אב או אם במקום אחר אז נקרא תושב אבל אם יש לו אב או אם אינו נקרא תושב אפילו אם מגדלו בתורת צדקה מכ\"ש אם הוא אצלו בשכר עכ\"ל ונראה דנערים ובחורים הלומדים בישיבה אפילו יש להם אב או אם במקום אחר יש להם דין תושב ואפי' בעה\"ב שלומד בישיבה אע\"פ שיש לו אשה ובנים במקום אחר ונותן מס במקום שאשתו ובניו שם מ\"מ דין תושב יש לו במקום שהוא לומד והכי נהוג:","\u0003הולכים אחר המנהג. \u0004וכתוב במנהגים דהיכא ששניהם בני שלשים או שניהם יא\"צ או שניהם שנים עשר חודש דוחה את האורח לגמרי מלהתפלל ולומר קדיש על העמוד אך בפריסת שמע וקדיש על הפתח שניהן שוין ויחלקו בגורל ואם תושב ואורח שניהם בני שבעה יחלקו בגורל כי לענין שבעה אין שום עילוי לתושב על האורח ע\"כ. וכתוב בתשובת מ\"ב שם דאפילו בן שבעה אחד גדול ותושב ובן שבעה אחד קטן ואורח אפ\"ה חולקים בשוה:","\u0003אבל לא נהגו להתפלל בשבתות ויו\"ט. \u0004וכן בימים נוראים אסור וכ\"פ מהרי\"ל מיהו היכא דליכא דעדיף מיניה מותר כ\"כ מהרי\"ו בדינים והלכות סימן מ\"ז:","\u0003דמומר שנהרג. \u0004דוקא נהרג אבל מת על מטתו לא וכן כתבתי לעיל סימן ש\"מ דכשנהרג יש לו כפרה עד כאן לשון ד\"מ."],["\u0003דמשמע הא אם אפשר לשנות כו'. \u0004בפרק שור שנגח ארבעה וחמשה איתא כן שלא רצה עולא לילך לנחם את רבי שמואל בר יהודה שאמר מה לי בתנחומין של בני בבל שאומרים מה אית לך למיעבד דמשמע הא אפשר למיעבד עבדי וזו היא גידוף. ורש\"ל דחה זה מהלכה שאמר הלא גם דוד המע\"ה אמר כן האוכל להשיבו עוד דמשמע אם היה אפשר להשיבו היה עושה. ותמהני על פה קדוש יאמר כן דשאני גבי דוד שאמר למה זה אני צם האוכל להשיבו עוד דודאי כל טצדקי תפלות וצומות יש לו לאדם לעשות כדי לבקש שלא ימות לו מת ועל זה אמר דוד כיון שכבר מת לא יועילו הצומות ועל זה סיים ואמר אני הולך אליו והוא לא ישוב אלי דלכאורה הוא דבר שאינו מענין תשובה לעבדיו שם אלא דהכי קאמר שמא תאמרו דיועילו הצומות שאזכה לראותו בעודו בחיים כשיקום זה הילד בתחיית המתים לזה אמר יודע אני שלא תהיה תחיית המתים בימי ועל זה אמר אני הולך אליו וגו' אבל אותן המנחמים שאומרים אל תצער עצמך כי מה לך לעשות אין אומרי' על התפלה כן אלא על הצער שלא יצער עצמו כיון שא\"א בענין אחר דמשמע הא אפשר בענין אחר היה עושה שפי' היה מצער עצמו על שלא יהיה כרצון האדם וזהו גידוף שמן הראוי להיות כרצון האל יתברך לא כרצון האדם וזה ברור לע\"ד:","\u0003נוהגים להתפלל בעשרה כל שבעה. \u0004באורח חיים סימן קל\"א כ' דאין אומרים תחנון בבית האבל והיינו כל ז' הימים וכ' הרוקח שאחר גמר התפלה אומרים תחנון ואין קורין שם בבית האבל הלל בר\"ח לפי שיש שם אנינות לכך אין אומרים לא המתים יהללו יה משום לועג לרש עכ\"ל. וכתב מו\"ח ז\"ל דבימים נוראים אם האבל הגון ולא נמצא כמוהו הוא קודם להתפלל אפי' תוך ל' על אביו ואמו וכן נמצא בהג\"ה ולא כיש מקפידים:","\u0003רק ג\"פ. \u0004כתב רש\"ל שקיבל מאביו זקינו שיש לומר ז' פעמים דהיינו בפעם א' עד מלת כי ומלת כי בכלל. ובפעם הב' עד כי מלאכיו. ובג' עד כי מלאכיו יצוה. ובד' עד יצוה לך. ובה' עד לך לשמרך. ובו' עד לשמרך בכל. ובז' עד בכל דרכיך ויש בו סוד וכתוב בלבוש שגם הוא נהג כן:","\u0003שתוך ז' לאבלם. \u0004במנהגים כתוב שבן ל' נדחה מבן יארציי\"ט לגמרי אם הוא תושב כל אותו יום ורמ\"א כ' כאן שאין ליא\"צ אלא קדיש א' תוך ל' ובספר משאת בנימין הקשה דברי המנהגים אהדדי דמתחלה כתבו בן ל' ויא\"צ דוחה היא\"צ לבן ל' כמו לי\"ב חודש אלמא דיא\"צ עדיף מבן ל' ושוב כ' דבן י\"ב תושב ויארציי\"ט אורח או בן שלשים אורח מסלק היב\"ח תושב להיארציי\"ט אורח בקדיש אחד ותפלה אחת ולבן שלשים אורח מחלק עמו כל הקדישי' כו' ש\"מ דבן שלשים עדיף מיארציי\"ט וחילק שם דהיכא דאיכא רווחא כגון בשבת דאיכא שלשה קדישים ואחד בן שלשים ואחד יארציי\"ט אז בן שלשים עדיף דהוא אומר שני קדישים והיארציי\"ט קדיש אחד אבל היכא דאיכא דוחק בקדישים ואינו מגיע לכל אחד קדיש אחד אז נדחה הבן שלשים מפני היארציי\"ט והטעם שאם לא יאמר היארציי\"ט אותו יום קדיש לא יוכל לומר למחר כי עבר היום בטל הקרבן מה שאין כן בבן שלשים שיוכל לומר למחר וחילוק נכון הוא דכל שאפשר לתת קדיש לשניהם אז יש מעלה לבן שלשים על היארצייט משא\"כ אם יהיה היארציי\"ט נדחה לגמרי זהו אינו מסתבר וכתב עוד דלענין שבעה אין חילוק בין גדול לקטן תושב לאורח נראה לי דמי שמת בשבת או בי\"ט וא\"א לקברו בו ביום דעל כל פנים יאמר קדיש תיכף אחר המיתה דאין אמירת קדיש תלוי באבילות כלל אבל בחול אין לעשות כן דהא כשהוא אונן פטור מן התפלה כן נ\"ל:","\u0003רק י\"א חודש. \u0004עיין מה שכתבתי בסימן ר\"מ סעיף ט' מזה דבר הגון:","\u0003שנהרג בידי עובדי כוכבים. \u0004פי' דאז יש לו כפרה ע\"י ההריגה אבל מת על מטתו לא וכן מבואר בסימן ש\"מ סעיף ה' לענין אבילות עליו וחילוק זה של מת או נהרג הוא תלמוד ערוך בפרק נגמר הדין (סנהדרין דף מ\"ז:)"]],["הָעֲבָדִים וְהַשְּׁפָחוֹת, אֵין עוֹמְדִין עֲלֵיהֶם בְּשׁוּרָה, וְאֵין אוֹמְרִים עֲלֵיהֶם תַּנְחוּמֵי אֲבֵלִים, אֶלָא אוֹמְרִים לוֹ: הַמָּקוֹם יְמַלֵא חֶסְרוֹנְךָ, כְּשֵׁם שֶׁאוֹמְרִים לְאָדָם עַל שׁוֹרוֹ וַחֲמוֹרוֹ.\nאָבֵל מְנֻדֶּה, אֵין מַבְרִין אוֹתוֹ \u0010y0\u0011 וְאֵין אוֹמְרִים לוֹ תַּנְחוּמֵי אֲבֵלִים. \u0010y1\u0011\nמְנֻדֶּה שֶׁמֵּת, מְנַחֲמִים אֲבֵלָיו.",["\u0003ואין אומרים כו'. \u0004דכל דבר שהוא משום כבוד לחיים אין עושין לאבל שהוא מנודה:","\u0003מנודה כו'. \u0004עיין לעיל סימן שמ\"ה ס\"ד:"],[]],["אָבֵל \u0010c0\u0011 אָסוּר לֶאֱכֹל מִשֶּׁלוֹ בִּסְעֻדָּה רִאשׁוֹנָה, אֲבָל בַּשְּׁנִיָּה מֻתָּר, אֲפִלוּ בְּיוֹם רִאשׁוֹן. וּמִצְוָה עַל שְׁכֵנָיו \u0010y0\u0011 שֶׁיַּאֲכִילוּהוּ מִשֶׁלָהֶם, כְּדֵי שֶׁלֹּא יֹאכַל מִשֶּׁלוֹ. וְיָכוֹל אֶחָד לְהַאֲכִיל אֶת חֲבֵרוֹ בִּימֵי אֶבְלוֹ, וְהוּא יַחֲזֹר גַם כֵּן וְיַאֲכִילֶנּוּ \u0010y1\u0011 בִּימֵי אֶבְלוֹ, וּבִלְבַד שֶׁלֹּא יַתְנוּ בִּתְחִלָה.\nאִשָּׁה שֶׁאֵרְעָהּ אֵבֶל, אֵין לַאֲנָשִׁים לְהַבְרוֹתָהּ; אֲבָל נָשִׁים מַבְרִין \u0010y2\u0011 אוֹתָהּ. וְאִשָּׁה נְשׂוּאָה שֶׁאֵרְעָהּ אֵבֶל, אֵינָהּ יְכוֹלָה לֶאֱכֹל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעֲלָהּ. וְכֵן מִי שֶׁיֵּשׁ לוֹ סוֹפֵר אוֹ שָׂכִיר, אִם אוֹכֵל בִּשְׂכָרוֹ וְאֵרְעוֹ אֵבֶל, לֹא יֹאכַל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעַל הַבַּיִת. אֲבָל מִי שֶׁזָּן עָנִי אוֹ יָתוֹם אוֹ לִבְנוֹ וּבִתּוֹ, בְּלֹא תְּנַאי, וְאֶרְעָם אֵבֶל, יְכוֹלִים לֶאֱכֹל סְעֻדָּה רִאשׁוֹנָה מִשֶּׁל בַּעַל הַבַּיִת. \u0010y3\u0011\nאִם רָצָה הָאָבֵל שֶׁלֹּא לֶאֱכֹל בַּיּוֹם הָרִאשׁוֹן, \u0010y4\u0011 מֻתָּר לֶאֱכֹל מִשֶּׁלוֹ אֲפִלוּ סְעֻדָּה רִאשׁוֹנָה. \u0005הַגָּה: וְכֵן אִם לֹא הִבְרוּהוּ בְּיוֹם רִאשׁוֹן שֶׁנִּמְשַׁךְ עַד הַלַּיְלָה, מֻתָּר לֶאֱכֹל בַּלַּיְלָה מִשֶּׁלּוֹ, וְאֵין צָרִיךְ הַבְרָאָה (טוּר בְּשֵׁם רֹב הַפּוֹסְקִים)\u0006.\nהָיוּ נוֹהֲגִים לְהִתְעַנּוֹת בְּיוֹם מִיתַת הַחֲכָמִים.\nמִי שֶׁנִּקְבַּר בְּעֶרֶב שַׁבָּת סָמוּךְ לַחֲשֵׁכָה \u0010y5\u0011 קֹדֶם בֵּין הַשְּׁמָשׁוֹת, יֵשׁ מִי שֶׁאוֹמֵר שֶׁמַּבְרִין אוֹתוֹ אָז; וְלִי נִרְאֶה דְּכֵיוָן שֶׁאֵינוֹ חוֹבָה טוֹב שֶׁלֹּא לְהַבְרוֹתוֹ אָז, מִפְּנֵי כְּבוֹד הַשַּׁבָּת, וְכֵן נוֹהֲגִין.\nאֵין מַבְרִין עַל הַקָטָן אֶלָא אִם כֵּן הוּא בֶּן שְׁלשִׁים יוֹם שְׁלֵמִים, אוֹ קִים לֵהּ בֵּהּ שֶׁכָּלוּ לוֹ חֳדָשָׁיו.\nמַרְבִּיצִין וּמְכַבְּדִין בְּבֵית הָאָבֵל, וּמְדִיחִין קְעָרוֹת, כּוֹסוֹת וּצְלוֹחִיּוֹת וְקִיתוֹנוֹת, וְאֵין מְבִיאִין שָׁם לֹא בְּשָׂמִים וְלֹא מֻגְמָר, אֲבָל מְבִיאִים אוֹתָם \u0010c1\u0011 בַּבַּיִת שֶׁהַמֵּת שָׁם וְאֵין מְבָרְכִים עֲלֵיהֶם; וְאֵין אוֹמְרִים שְׁמוּעָה וְאַגָדָה בְּבֵית הָאָבֵל, אֶלָא יוֹשְׁבִין וְדוֹמְמִים. \u0010y6\u0011\nכֵּיוָן שֶׁנִּקְבַּר הַמֵּת, מֻתָּר לֶאֱכֹל בָּשָׂר וְלִשְׁתּוֹת יַיִן מְעַט בְּתוֹךְ הַסְעֻדָּה, כְּדֵי לִשְׁרוֹת אֲכִילָה שֶׁבְּמֵעָיו אֲבָל לֹא לִרְווֹת.\nמָקוֹם שֶׁנָּהֲגוּ לְהַבְרוֹת בְּבָשָׂר וְיַיִן וּמִינֵי מַטְעַמִּים עוֹשִׂים; וּמַבְרִין \u0010y7\u0011 תְּחִלָה בְּבֵיצִים אוֹ בְּתַבְשִׁיל שֶׁל עֲדָשִׁים, זֵכֶר לַאֲבֵלוּת, וְאַחַר כָּךְ אוֹכְלִים כָּל צָרְכָּם. \u0010y8\u0011\nאֵין לֶאֱכֹל עִם הָאָבֵל כָּל כָּךְ בְּנֵי אָדָם שֶׁיִּתְחַלְקוּ לִשְׁנֵי מְקוֹמוֹת. \u0010y9\u0011\nהֵיכָא שֶׁצָּרִיךְ לִמְנוֹת שִׁבְעָה אַחַר הָרֶגֶל, וְכֵן \u0010y10\u0011 אִם שָׁמַע שְׁמוּעָה בְּשַׁבָּת, צָרִיךְ לְהַבְרוֹתוֹ הַבְרָאָה רִאשׁוֹנָה שֶׁבִּימֵי אֲבֵלוּת. \u0005וְיֵשׁ אוֹמְרִים שֶׁכֵּיוָן שֶׁנִּדְחָה יוֹם רִאשׁוֹן אֵין מַבְרִין אוֹתוֹ, וְכֵן נוֹהֲגִים (בְּמָרְדְּכַי במ\"ק בְּשֵׁם י\"א ונ\"י)\u0006, וַאֲפִלּוּ הֵיכָא דְּעוֹלֶה לוֹ לְמִנְיַן ז' כְּגוֹן בִּמְקוֹמוֹת שֶׁעוֹשִׂין שְׁנֵי יָמִים, שֶׁשֵּׁנִי עוֹלֶה.\nאֵין מַבְרִין עַל שְׁמוּעָה רְחוֹקָה.\nפָּרֵיס \u0005(פֵּרוּשׁ בּוֹצֵעַ לֶחֶם לְבָרֵךְ הַמּוֹצִיא)\u0006 מְנַחֵם גָדוֹל דִּבְּהוֹן, וּבְשַׁבָּת פָּרֵיס כְּאוֹרְחֵיהּ.",["\u0003שיאכילוהו משלהם. \u0004כלומר הסעודה ראשונה מצוה שיאכילוהו משלהם אבל בסעודה שניה אין כאן מצוה שהרי יכול לאכול משלו:","\u0003בימי אבלו. \u0004פירוש אע\"פ ששניהם אבלים:","\u0003ואשה נשואה כו'. \u0004דכיון שחייב במזונותיה כמשלה דמי:","\u0003אם רצה כו'. \u0004ומשמע דאם רצה האבל להתענות באותו היום מותר וכ\"פ הב\"ח:","\u0003מותר לאכול. \u0004ביום שני או בלילה שאחר יום ראשון משלו אפילו סעודה ראשונה:","\u0003יש מי שאומר כו'. \u0004הוא המרדכי (ואגודה) שהביא בב\"י והיינו מ\"ש בפרישה וב\"י לא כ' כן ואוסר אף בע\"ש והיינו דעתו כאן בש\"ע ודלא כהגהת דרישה שכ' ולא ידעתי למה כתב א\"א ז\"ל וב\"י לא כ\"כ ע\"ש:","\u0003כיון שנקבר כו'. \u0004אבל קודם קבורה אסור בבשר ויין דהוי אונן וכדלעיל סימן שמ\"א:","\u0003בביצים כו'. \u0004שאין להם פה כמו אבל שאין לו פה:","\u0003אין לאכול כו'. \u0004דהוי כסעודת מריעות שיש בה שמחה:","\u0003היכא כו'. \u0004כלומר ואפי' במקום שעושים ב' י\"ט שהשני עולה למנין ז' וכמו שנתבאר באו\"ח סי' תקמ\"ח ס\"ב ולקמן סי' שנ\"ט (סד\"א) [סי\"ג] דיש להברותו אח\"כ דהא לא נדחה דה\"ל להברות ביום ז' שהרי שייך ביה אבילותה כיון דעולה למנין ז' קמ\"ל דאמרי' בזה ג\"כ כיון דנדחה נדחה ואין צריך הבראה:","\u0003אם שמע שמועה בשבת. \u0004צריך עיון דבד\"מ ס\"ס זה פסק כב\"י שכ' בסי' שצ\"ג דמברין בשבת וכתב שכן פשט המנהג בכל העולם להברות בשבת ולא נשמע בעולם שום פוצה פה ומצפצף:"],["\u0003אסור לאכול משלו. \u0004נראה דאם לא שלחו לו או שהוא יחידי בעיר אין חייב לצער עצמו שלא לאכול כלל דמשום הכי כתב כאן הטור ושלחן ערוך דמצוה על שכיניו שיאכילוהו שלא יאכל משלו שזהו מיותר לכאורה אלא הכוונה דעיקר מצוה על השכנים שלא יגרמו שיצטרך לאכול משלו דאם לא ישלחו לו יהיה לו היתר לאכול משלו ע\"י ההכרח:","\u0003בבית שהמת שם. \u0004להעביר הסרחון:"]],["כְּשֶׁמְּבָרְכִין בִּרְכַּת הַמָּזוֹן בְּבֵית הָאָבֵל, אוֹמֵר בְּרָכָה רְבִיעִית כְּנֻסַח זוֹ: בא\"י אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הָאֵל אָבִינוּ מַלְכֵּנוּ בּוֹרְאֵנוּ גוֹאֲלֵנוּ \u0010y0\u0011 קְדוֹשֵׁנוּ קְדוֹשׁ יַעֲקֹב הַמֶּלֶךְ הַחַי הַטּוֹב וְהַמֵּטִיב אֵל אֱמֶת דַּיַּן אֱמֶת שׁוֹפֵט בְּצֶדֶק וְכו'. \u0005הַגָּה: לוֹקֵחַ נְפָשׁוֹת בְּמִשְׁפָּט שַׁלִּיט בְּעוֹלָמוֹ לַעֲשׂוֹת בּוֹ כִּרְצוֹנוֹ כִּי כָּל דְּרָכָיו בְּמִשְׁפָּט וַאֲנַחְנוּ עַמּוֹ וַעֲבָדָיו וּבַכֹּל אֲנַחְנוּ חַיָּבִים לְהוֹדוֹת לוֹ וּלְבָרְכוֹ גּוֹדֵר פִּרְצוֹת יִשְׂרָאֵל הוּא יִגְדֹּר הַפִּרְצָה הַזֹּאת מֵעָלֵינוּ \u0010y1\u0011 וּמֵעַל אָבֵל זֶה לְחַיִּים וּלְשָׁלוֹם (טוּר)\u0006.\nיֵשׁ מוֹסִיפִים בִּבְרָכָה שְׁלִישִׁית: נַחֵם ה' אֱלֹהֵינוּ אֶת אֲבֵלֵי יְרוּשָׁלַיִם וְאֶת הָאֲבֵלִים הַמִתְאַבְּלִים בָּאֵבֶל הַזֶּה, נַחֲמֵם מֵאֶבְלָם וְשַׂמְּחֵם מִיגוֹנָם, כָּאָמוּר: \u0010y2\u0011 כְּאִישׁ אֲשֶׁר אִמּוֹ תְּנַחֲמֶנּוּ \u0005(יְשַׁעְיָה סו, יג)\u0006 וְכו' בא\"י \u0010y3\u0011 מְנַחֵם צִיּוֹן בְּבִנְיַן יְרוּשָׁלַיִם.\nיֵשׁ אוֹמְרִים בְּבִרְכַּת זִמּוּן: נְבָרֵךְ מְנַחֵם אֲבֵלִים שֶׁאָכַלְנוּ מִשֶּׁלוֹ.\nבְּשַׁבָּת, אִם בֵּרַךְ בְּיָחִיד, אוֹ בְּג' אֲבֵלִים, מְבָרֵךְ כְּדֶרֶךְ שֶׁמְּבָרֵךְ בְּחוֹל, דְּצִנְעָא הוּא. וְאִם אָכְלוּ אֲחֵרִים עִמּוֹ וּבֵרְכוּ, אֵין מַזְכִּירִין מֵעֵין הַמְּאֹרָע, דְּכֵיוָן דְּאִכָּא אֲחֵרִים \u0010y4\u0011 לָאו צִנְעָה הוּא. \u0010y5\u0011\nאָבֵל מִצְטָרֵף לִתְפִלָה וּלְזִמּוּן, בֵּין לְג' בֵּין לַעֲשָׂרָה.",["\u0003קדושנו קדוש יעקב. \u0004רוענו רועה ישראל המלך הטוב והמטיב לכל אל שבכל יום ויום הוא הטיב הוא מטיב הוא ייטיב לנו המלך החי הטוב והמטיב אל אמת דיין אמת כו'. דודאי צריך לומר הברכה מתחלה כתיקון חכמים:","\u0003ומעל אבל זה לחיים ולשלום. \u0004הוא גמלנו וכו' וכל טוב וכו' אל יחסרנו הרחמן הוא כו':","\u0003כאיש אשר אמו תנחמנו. \u0004כן אנכי אנחמכם ובירושלים תנוחמו בא\"י כו':","\u0003מנחם ציון בבנין ירושלים. \u0004אבל אין לומר מנחם אבלים ובונה ירושלים דאין חותמים בשתים. ומשמע לכאורה דה\"ה דאין לומר מנחם ציון ובונה ירושלים דה\"ל חותמים בשתים והכי אמרי' בש\"ס פרק שלשה שאכלו (ברכות דף מ\"ט ע\"א) דמושיע ישראל ובונה ירושלים הוה ליה חתימה בשתים דאסור אבל בנחם שאומרים בתשעה באב איתא בכל הסידורים בא\"י מנחם ציון ובונה ירושלים וצ\"ל דמנחם ציון ובונה ירושלים כולו חדא מילתא היא:","\u0003לאו צינעא הוא. \u0004ואין אבילות דבפרהסיא נוהג בשבת כדלקמן סי' ת':","\u0003אבל מצטרף כו'. \u0004ומדברי המרדכי נראה דסעודה ראשונה שמברין את האבל שאסור לאכלה משלו) אין האבל מצטרף בברכת המזון וכן כתב הרוקח סי' שי\"ג דכשמברכין ברכת המזון בשעת הבראתו אין האבלים מן המנין כדאמרינן בפ\"א דכתובות ור\"ל דאמרינן התם (דף ח' ע\"ב) דבברכת רחבה אין אבלים מן המנין ופי' רש\"י שם דהיינו כשמברין את האבל סעודה ראשונה משל אחרים כדאמרינן במ\"ק היו מברין אותו ברחבה כו' משמע להו דהוא הדין האידנא דליכא רחבה מ\"מ בסעודת הבראה תליא מילתא ואע\"פ שהתוס' כתבו במגילה (דף כ\"ג ע\"ב) דבברכת המזון האבל מצטרף אפשר דמודה בסעודה ראשונה דהבראה ולא מיירי אלא בשאר אבילות:"],[]],["אֵלוּ דְּבָרִים שֶׁהָאָבֵל אָסוּר בָּהֶם: בִּמְלָאכָה, בִּרְחִיצָה וְסִיכָה וּנְעִילַת הַסַנְדָּל וְתַשְׁמִישׁ הַמִּטָּה, וְאָסוּר לִקְרוֹת בַּתּוֹרָה, וְאָסוּר בִּשְׁאֵלַת שָׁלוֹם וּבִכְבִיסָה, וְחַיָּב בַּעֲטִיפַת הָרֹאשׁ וּבִכְפִיַּת הַמִּטָּה, כָּל שִׁבְעָה, וְאָסוּר לְהַנִּיחַ תְּפִלִין בַּיּוֹם הָרִאשׁוֹן, וְאָסוּר בְּגִהוּץ וּבְתִסְפֹּרֶת וְשִׂמְחָה וְאִחוּי קֶרַע כָּל ל' יוֹם \u0005וְכָל דִּבְרֵי אֲבֵלוּת נוֹהֲגִין בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה (בִּתְשׁוּבַת הָרַשְׁבָּ\"א סִימָן תמ\"ו)\u0006.\nמְלָאכָה כֵּיצַד, כָּל ג' יָמִים הָרִאשׁוֹנִים אָסוּר בִּמְלָאכָה, אֲפִלוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה; מִכָּאן וָאֵילָךְ, אִם הוּא עָנִי וְאֵין לוֹ מַה יֹאכַל, עוֹשֶׂה בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ, \u0010y0\u0011 וְאִשָּׁה טוֹוָה בַּפֶּלֶךְ בְּתוֹךְ בֵּיתָהּ, אֲבָל אָמְרוּ חֲכָמִים: תָּבֹא מְאֵרָה לִשְׁכֵנָיו שֶׁהִצְרִיכוּהוּ לְכָךְ. \u0010y1\u0011 \u0005כְּדֶרֶךְ שֶׁמֻּתָּר לִכְתֹּב בְּחֹל הַמּוֹעֵד, כָּךְ מֻתָּר לִכְתֹּב בִּימֵי אֶבְלוֹ; אֲבָל לֹא בְּעִנְיָן אַחֵר (כָּל בּוֹ בְּשֵׁם הר\"מ וב\"י סוֹף סִימָן זֶה)\u0006.\nג כְּשֵׁם שֶׁהוּא אָסוּר בַּעֲשִׂיַּת מְלָאכָה, כָּךְ הוּא אָסוּר לִשָּׂא וְלִתֵּן בִּסְחוֹרָה, וְלֵילֵךְ מִמְּדִינָה לִמְדִינָה בִּסְחוֹרָה.\nאֲפִלוּ דָּבָר הָאָבֵד אָסוּר הָאָבֵל לַעֲשׂוֹת בֵּין עֲבָדָיו וְשִׁפְחוֹתָיו \u0010y2\u0011 וּבָנָיו וּבְנוֹתָיו שֶׁמַּעֲשֵׂה יְדֵיהֶם שֶׁלוֹ.\nאָסוּר לַעֲשׂוֹת מְלַאכְתּוֹ עַל יְדֵי אֲחֵרִים \u0005אֲפִלּוּ עוֹבֵד כּוֹכָבִים (מָרְדְּכַי רֵישׁ פֶּרֶק מִי שֶׁהָפַךְ)\u0006, אֶלָא אִם כֵּן הוּא דָּבָר הָאָבֵד, שֶׁדָּבָר הָאָבֵד מֻתָּר לְאָבֵל לַעֲשׂוֹת עַל יְדֵי אֲחֵרִים; \u0010y3\u0011 אֲפִלוּ דָּבָר הָאָסוּר בַּמּוֹעֵד מִשּׁוּם טִרְחָא, מֻתָּר, וַאֲפִלוּ הוּא מַעֲשֵׂה אֻמָּן. \u0005הַגָּה: וְיֵשׁ אוֹמְרִים דְּאִם לֹא יוּכַל לַעֲשׂוֹת עַל יְדֵי אֲחֵרִים, וְהוּא דָּבָר הָאָבֵד, \u0010y4\u0011 \u0010y5\u0011 מֻתָּר לַעֲשׂוֹת הָאָבֵל בְּעַצְמוֹ (טוּר בְּשֵׁם הָרַמְבַּ\"ן וְהָרֹא\"שׁ וְכֵן כָּתַב רַבֵּנוּ יְרוּחָם)\u0006 ; וּלְאַחַר שְׁלֹשָׁה יָמִים הָרִאשׁוֹנִים יֵשׁ לְהָקֵל, וַאֲפִלּוּ תּוֹךְ ג' וְהוּא הֶפְסֵד מְרֻבֶּה.\nפְּרַקְמַטְיָא שֶׁלוֹ, בְּדָבָר הָאָבֵד, שֶׁאִם לֹא יִמְכֹּר יַפְסִיד מֵהַקֶרֶן, נִמְכֶּרֶת עַל יְדֵי אֲחֵרִים; אֲבָל אִם לֹא יַפְסִיד מֵהַקֶרֶן, אֶלָא שֶׁאִם יִמְכְּרֶנָּה עַתָּה יַרְוִיחַ בָּהּ יוֹתֵר מִשֶּׁאִם יִמְכְּרֶנָּה אַחַר כָּךְ, אָסוּר. \u0010y6\u0011 וּמִכָּל מָקוֹם אִם שַׁיָּרוֹת אוֹ סְפִינוֹת בָּאוּ, אוֹ שֶׁהֵם מְבַקְשִׁים לָצֵאת, וּמוֹכְרִים בְּזוֹל אוֹ לוֹקְחִים בְּיֹקֶר, מֻתָּר לִמְכֹּר וְלִקְנוֹת עַל יְדֵי אֲחֵרִים, אֲפִלוּ שֶׁלֹּא לְצֹרֶךְ תַּשְׁמִישׁוֹ, אֶלָא לַעֲשׂוֹת סְחוֹרָה לְהִשְׂתַּכֵּר.\nלְהַלְווֹת לְעוֹבְדֵי כּוֹכָבִים בְּרִבִּית, לְאוֹתָם שֶׁרְגִילִים לִלְווֹת מִמֶּנּוּ, מֻתָּר לְהַלְווֹת לָהֶם עַל יְדֵי אֲחֵרִים, \u0010y7\u0011 מִשּׁוּם דְּהָוֵי דָּבָר הָאָבֵד.\nאִי מַסִיק זוּזֵי בְּאִינְשֵׁי, וְהָאִדָּנָא מַשְׁכַּח לְהוּ, וּבָתַר הָכִי לָא מַשְׁכַּח לְהוּ, שָׁרֵי \u0010y8\u0011 לְשַׁדּוֹרֵי עֲלַיְהוּ.\nאִם יֵשׁ לוֹ דִּין עַל אָדָם, אֵינוֹ תּוֹבֵעַ כָּל ז'. וְאִם הוּא דָּבָר הָאָבֵד, כְּגוֹן שֶׁבִּקֵשׁ לֵילֵךְ לִמְדִינַת הַיָּם, אוֹ \u0010y9\u0011 שֶׁעֵדָיו חוֹלִים, עוֹשֶׂה מֻרְשֶׁה וְדָן עִמּוֹ. \u0010y10\u0011\nכָּל הַדְּבָרִים שֶׁהִתִּירוּ בַּמּוֹעֵד מִשּׁוּם צֹרֶךְ הַמּוֹעֵד, כֻּלָם אֲסוּרִים בְּאָבֵל, אֲפִלוּ עַל יְדֵי אֲחֵרִים.\nאָבֵל שֶׁשָּׂדֵהוּ בְּיַד אֲחֵרִים \u0010y11\u0011 בַּאֲרִיסוּת אוֹ בַּחֲכִירוּת אוֹ בְּקַבְּלָנוּת, הֲרֵי אֵלוּ עוֹבְדִין כְּדַרְכָּן בִּימֵי הָאֵבֶל שֶׁל בַּעַל הַשָּׂדֶה, וַאֲפִלוּ נִשְׁלַם זְמַן חֲכִירוּתָם קֹדֶם וְנִשְׁאֲרוּ בַּשָּׂדֶה כְּמוֹ שֶׁהָיוּ.\nאִם הָאָבֵל הוּא אָרִיס בְּשָׂדֶה שֶׁל אֲחֵרִים, לֹא יַעֲבֹד הוּא בְּעַצְמוֹ, \u0010y12\u0011 אֲבָל עַל יְדֵי אֲחֵרִים מֻתָּר.\nאִם יֵשׁ שְׂכִיר יוֹם שֶׁעוֹבֵד שְׂדֵה הָאָבֵל, אֲפִלוּ בְּעִיר אַחֶרֶת, \u0010y13\u0011 לֹא יַעֲשֶׂה.\nאִם יֵשׁ לָאָבֵל חֲמוֹר אוֹ סְפִינָה \u0010y14\u0011 מֻחְכָּר אוֹ מֻשְׂכָּר בְּיַד אַחֵר, הֲרֵי זֶה לֹא יַעֲשֶׂה בִּימֵי אֶבְלוֹ שֶׁל בַּעַל הַחֲמוֹר וְהַסְפִינָה, אִם לֹא שֶׁשְּׂכָרוֹ קֹדֶם שֶׁהִתְחִיל הָאֲבֵלוּת וַעֲדַיִן לֹא כָּלָה הַזְּמַן; אֲבָל אִם כָּלָה הַזְּמַן, אָסוּר.\nאִם הָיָה הַחֲמוֹר וְהַסְפִינָה בְּיַד אֲחֵרִים, לְמֶחֱצָה, לִשְׁלִישׁ וְלִרְבִיעַ, יֵשׁ מַתִּירִים \u0010y15\u0011 וְיֵשׁ אוֹסְרִים.\nאִם הָאָבֵל מֻשְׂכָּר לְאַחֵר, לֹא יַעֲשֶׂה מְלָאכָה בִּימֵי אֶבְלוֹ. \u0010y16\u0011 \u0005אֲבָל עַל יְדֵי אֲחֵרִים, שָׁרֵי (זֶהוּ מֵהָרֹא\"שׁ)\u0006.\nהָיְתָה מְלֶאכֶת אֲחֵרִים בְּיָדוֹ, \u0010y17\u0011 אֲפִלוּ בְּדָבָר תָּלוּשׁ, כְּגוֹן לֶאֱרֹג, בֵּין בְּקַבְּלָנוּת בֵּין שֶׁלֹּא בְּקַבְּלָנוּת, לֹא יַעֲשֶׂה. \u0005הַגָּה: \u0010y18\u0011 וְאִם הוּא דָּבָר הָאָבֵד, יַעֲשֶׂה עַל יְדֵי אֲחֵרִים (ד\"ע)\u0006. מֻתָּר לְקַבֵּל מְלָאכָה בִּימֵי אֶבְלוֹ לַעֲשׂוֹת אַחַר כָּךְ, וּבִלְבַד שֶׁלֹּא יִשְׁקֹל וְלֹא יִמְדֹּד כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בִּשְׁאָר פְּעָמִים \u0005(מָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006. \u0010y19\u0011\nהָיְתָה מְלַאכְתּוֹ בְּיַד אֲחֵרִים, בְּקַבְּלָנוּת בְּדָבָר תָּלוּשׁ, בְּבֵיתוֹ, לֹא יַעֲשׂוּ; בְּבֵית אֲחֵרִים, יַעֲשׂוּ. \u0005וּבִלְבַד שֶׁקִּבְּלוּ הַמְּלָאכָה קֹדֶם שֶׁנַּעֲשָׂה אָבֵל (מָרְדְּכַי סוֹף מ\"ק וְר\"י)\u0006.\nהָיָה לוֹ בִּנְיָן בְּיַד אֲחֵרִים, בְּקַבְּלָנוּת, בְּחֹל אוֹ בְּחֹל הַמּוֹעֵד \u0010y20\u0011 לֹא יַעֲשׂוּ, אֲפִלוּ הוּא חוּץ לִתְחוּם הָעִיר; וְאִם אֵלוּ הַקַבְּלָנִים עוֹבְדֵי כּוֹכָבִים, \u0010y21\u0011 מֻתָּרִים לִבְנוֹתוֹ בְּשַׁבָּת וְיוֹם טוֹב שֶׁחָלוּ בִּימֵי הָאֵבֶל, אִם הוּא חוּץ לִתְחוּם הָעִיר וְאֵין עִיר אַחֶרֶת שֶׁבָּהּ יִשְׂרָאֵל בְּתוֹךְ תְּחוּם שֶׁל אוֹתוֹ בַּיִת.\nאִם קִבְּלוּ אֲחֵרִים לַחֲרֹשׁ וְלִזְרֹעַ שָׂדֵהוּ, יֵשׁ אוֹמְרִים שֶׁמֻּתָּרִין לַחֲרֹשׁ וְלִזְרֹעַ בִּימֵי אֶבְלוֹ שֶׁל בַּעַל הַשָּׂדֶה, וְיֵשׁ מִי שֶׁאוֹסֵר.\nשְׁנֵי שֻׁתָּפִים חֶנְוָנִים שֶׁאֵרַע אֵבֶל לְאֶחָד מֵהֶם, נוֹעֲלִים חֲנוּתָם, שֶׁלֹּא יַעֲשֶׂה \u0010y22\u0011 הַשֻּׁתָּף בְּפַרְהֶסְיָא, אֲבָל יָכוֹל לַעֲשׂוֹת בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ, אֲפִלוּ בְּעֵסֶק הַשֻּׁתָּפוּת. וְאִם הָאָבֵל אָדָם חָשׁוּב, וְהַשֻּׁתָּפוּת נִקְרָא עַל שְׁמוֹ, שֶׁאֲפִלוּ אִם יַעֲשֵׂהוּ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ יָדוּעַ שֶּׁיֵּשׁ לָאָבֵל חֵלֶק בּוֹ, אָסוּר לַשֵּׁנִי לַעֲשׂוֹת אֲפִלוּ בְּתוֹךְ בֵּיתוֹ.\nכְּבוֹד הַבַּיִת, הֲדָחַת כּוֹסוֹת וְהַצָּעַת הַמִּטּוֹת, אֵין בָּהֶם מִשּׁוּם מְלָאכָה לְאָבֵל; וְכֵן מֻתָּר לְאִשָּׁה לֶאֱפוֹת וּלְבַשֵּׁל בִּימֵי אֶבְלָהּ \u0005כָּל הַצָּרִיךְ לָהּ, אֲבָל מַה שֶּׁאֵינוֹ צָרִיךְ לָהּ אָסוּר;\u0006 \u0010c0\u0011 וְכֵן אִשָּׁה הַמְשָׁרֶתֶת בְּבֵית בַּעַל הַבַּיִת אֶחָד, וְאֵרְעָהּ אֵבֶל, מֻתֶּרֶת לֶאֱפוֹת וּלְבַשֵּׁל וְלַעֲשׂוֹת שְׁאָר צָרְכֵי הַבַּיִת, בֵּין שֶׁהִיא מְשָׁרֶתֶת בְּחִנָּם בֵּין בְּשָׂכָר.\nהַהוֹלֵךְ מִמָּקוֹם לְמָקוֹם לִסְחוֹרָה, וְשָׁמַע שְׁמוּעָה קְרוֹבָה, אִם יָכוֹל לְמַעֵט שֶׁלֹּא לַעֲשׂוֹת שׁוּם עֵסֶק בְּאוֹתָהּ הָעִיר, מוּטָב; וְאִם לָאו, שֶׁאִם לֹא יִקְנֶה בְּאוֹתָהּ הָעִיר לֹא יִמָּצֵא, יִקְנֶה לְצֹרֶךְ הַדֶּרֶךְ דְּבָרִים שֶׁיֵּשׁ בָּהֶם חַיֵּי נֶפֶשׁ.\nעַל כָּל הַמֵּתִים, רָצָה לְמַעֵט בְּעֵסֶק סְחוֹרָה הַמֻּתֶּרֶת לוֹ, כְּגוֹן דָּבָר הָאָבֵד, יְמַעֵט; רָצָה, אֵינוֹ מְמַעֵט. עַל אָבִיו וְאִמּוֹ, יְמַעֵט.\nעַל כָּל הַמֵּתִים אָסוּר עַד ל' יוֹם לֵילֵךְ בִּסְחוֹרָה לְמֵרָחוֹק, דְּאִכָּא פִּרְסוּם גָדוֹל וְדוֹמֶה לְשִׂמְחָה שֶׁהוֹלֵךְ בְּשַׁיָּרָא גְדוֹלָה וּשְׂמֵחִים הַרְבֵּה בַּדֶּרֶךְ; בְּאָבִיו וְאִמּוֹ, עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו וְיֹאמְרוּ: לֵךְ עִמָּנוּ.",["\u0003ואשה טווה בפלך בתוך ביתה. \u0004פירוש אין מתירין לה אלא מלאכה של צינעה ושל עראי כגון להיות טווה בפלך בתוך ביתה ואם אינה מספקת בזה עושה אומנות שלה בצינעה תוך ביתה. עכ\"ל טור:","\u0003כדרך שמותר לכתוב בחוה\"מ כו'. \u0004כמו שנתבאר בא\"ח סי' תקמ\"ה ע\"ש:","\u0003ובניו ובנותיו כו'. \u0004פירוש אפי' הם גדולים אם סמוכים על שלחנו עכ\"ל טור ועט\"ז ור\"ל כל שכן קטנים כשסמוכים על שלחנו אבל אם אינם סמוכים על שלחנו אפי' קטנים מעשה ידיהן לעצמן כמו שנתבאר בח\"מ סימן ע\"ד ס\"ב.","\u0003אפי' כו' ואפי' כו'. \u0004דדוקא במועד אסרו דברים של טורח מפני כבוד המועד אבל באבל שעושה ע\"י אחרים מאי איכפת לן בטורח דאחרים. טור.","\u0003מותר לעשות האבל בעצמו. \u0004אפילו הוא דבר שיש בו טירחא ומעשה אומן כן משמע בש\"ס:","\u0003לעשות כו'. \u0004מיהו יעשה בצינעה כן משמע בש\"ס:","\u0003ומ\"מ אם שיירות או ספינות כו'. \u0004הטעם כיון שהוא דבר שאינו מצוי וכ\"מ בט\"ו בא\"ח סי' תקל\"ט ס\"ה דלא כנראה מהעט\"ז כאן הטעם דהוי הפסד מרובה ע\"ש:","\u0003משום דהוי דבר האבד. \u0004שאם לא ילוה להם ילכו לאחרים וילוו להם וירגילום לבא אצלם ואיכא פסידא. טור:","\u0003לשדורי עלייהו. \u0004כלומר לשלוח אחרים שיתבעו המעות מהם דה\"ל דבר האבד:","\u0003שעדיו חולים. \u0004וירא שמא ימותו:","\u0003כל הדברים כו'. \u0004כלומר כל הדברים שלא התירו במועד משום דבר האבד וכה\"ג אלא משום צורך המועד כולם אסורים באבל כו':","\u0003באריסות כו'. \u0004אריסות היינו לשליש ולרביע חכירות שנותן לו סכום מפירות השדה בין עושה מעט או הרבה וקבלנות שנותן לו מעות סכום ידוע:","\u0003אבל על ידי אחרים מותר. \u0004שאין זה נקרא מלאכת האבל אלא מלאכת בעל השדה:","\u0003לא יעשה. \u0004כיון שאינו אצלו באריסות או בחכירות ובקבלנות:","\u0003מוחכר או מושכר כצ\"ל. \u0004ומוחכר שייך בפירות ושכירות במעות:","\u0003ויש אוסרים. \u0004דדוקא בקרקע שרי דלאריסות קיימא משא\"כ הכא:","\u0003אבל על ידי אחרים שרי. \u0004משמע אפילו אינו דבר האבד וכן משמע להדיא בעט\"ז וכ' דאע\"פ דלעיל סעיף ב' וה' אסור אפי' ע\"י אחרים מ\"מ הכא מותר על ידי אחרים והוא יקח השכר מן הבעלים שהרי אין עיקר המלאכה שלו עכ\"ל. ודין זה הוציא הרב מהרא\"ש שכתב על פירש\"י מה שפי' שאם היה אבל מוחכר או מושכר אצל אחר שיעשה הוא עצמו מלאכה נ\"ל קולא גדולה דהא אפילו עני המתפרנס מן הצדקה לא יעשה בצינעה בתוך ביתו שלשה ימים הראשונים ומשום הפסד ממונו מעט שרית ליה לעשות מלאכה בפרהסיא עכ\"ל ומשמע ליה להרב מדכ' מאי שפירש כו' שיעשה הוא עצמו מלאכה נ\"ל קולא גדולה כו' משמע הא על ידי אחרים שרי ולפע\"ד נראה מדמדמי ליה לעני המתפרנס מן הצדקה משמע דאפי' ע\"י אחרים אסו' ומ\"ש שיעשה הוא עצמו מלאכה נ\"ל קולא גדולה כו' כ' כן כלפי מה שפירש\"י שם על ואם היו מוחכרים או מושכרים וז\"ל ואם היו מוחכרים או מושכרים הם או בהמתם אצל אחרים למהלך חדש או חדשים הרי אלו יעשו הם לעצמם ולא יפסידו שכרם עכ\"ל עלה קאי ואמר מה שפי' שיעשה הוא עצמו מלאכה קולא גדולה אלא קאי אבהמתן לחוד וכפי' הראב\"ד ולא כשהיה עצמו מושכר אבל לא נחית הרא\"ש לחלק כשהוא עצמו מושכר בין ע\"י עצמו לע\"י אחרי' וזה נרא' דעת הט\"ו שלא חילקו בכך:","\u0003אפילו בדבר תלוש. \u0004שיכול לעשותו בצינעה וכל שכן דבר מחובר שאינו יכול לעשותו אלא בפרהסיא:","\u0003ואם הוא דבר האבד כו'. \u0004והעט\"ז כתב וזה לשונו ונ\"ל אפילו אינו דבר האבד מותר לעשות ע\"י אחרים כיון שעיקר המלאכה אינו שלו וכמ\"ש בסעיף י\"ז גבי הוא עצמו מושכר עכ\"ל ודעת הרב נראה דדוקא התם שהוא מושכר לחדש או לחדשים שרי משא\"כ הכא ולפי מ\"ש בס\"ק י\"ז דבהוא עצמו מושכר אסור ע\"י אחרים אם לא בדבר האבד א\"כ כל שכן הכא:","\u0003היתה מלאכתו כו'. \u0004וכ' רבינו ירוחם בשם המפרשים שמכאן יש ללמוד שאם היה לאבל מלמד או סופר או פועל שלא יעשה בביתו ומביאו ב\"י:","\u0003לא יעשו אפי' הוא חוץ לתחום העיר. \u0004ואפי' מסרה להם קודם האבל או קודם ח\"ה אסור מפני מראית העין שכיון שיוכלו בני אדם ללכת שם ויראו המלאכה יאמרו ראה זה שמסר מלאכתו לאחרים בימי האבל או בחול המועד ולא ידעי דקבולת הוא גבייהו קודם לכן:","\u0003מותרים לבנותו כו' אם הוא חוץ לתחום כו'. \u0004דליכא למיגזר משום חשדא שאין בני העיר מצוים שם שיבינו שמלאכת אבל או של ישראל היא:","\u0003בפרהסיא כו'. \u0004זה סותר למ\"ש בב\"י ולענין הלכה כיון שהרי\"ף והרמב\"ם מסכימים לדעת א' הכי נקטינן וראיתי בב\"ה שתיקן דבריו שבב\"י שצ\"ל הכי נקטינן וכתירוצו של הראב\"ד וכך הם דברי רבינו עכ\"ל אבל צ\"ע דכיון דכתב הכי נקטינן על דברי הרי\"ף והרמב\"ם היאך כ' וכתירוצו של הראב\"ד הא ודאי הרי\"ף והרמב\"ם אין מחלקים בין צינעה לפרהסיא כהראב\"ד וכדמשמע בהרא\"ש ורמב\"ן ובב\"י ע\"ש וע' בתשו' מהרש\"ל סימן ס\"ז:"],["\u0003וכן אשה המשרתת כו'. \u0004ואין להקשות הא כתב בסעיף ט\"ז אם האבל מושכר לאחרים לא יעשה מלאכה בימי אבלו דהתם מיירי במלאכה גמורה שאסור לאבל בכל גווני משא\"כ במלאכת צרכי הבית דמותר לאשה עצמה כמ\"ש בסעיף שקודם לזה על כן מותר אפי' למשרתת אבל על כל פנים לא תעשה המשרתת מלאכה שאינו לצורך הבית אלא להרויח וכ\"ש שלא תצא מן הבית כדין אבל וראיתי מי שהורה לשמש שאירע לו אבל שיעשה עבודתו וילך לבית הכנסת ולשמש בצרכי הקהל ולא יפה הורה דטעה בטעם הדין הזה דהיתר משרתת. כ' רש\"ל בשם אגודה דאבל מותר להקיז דם וכתב הכל בו דאבל שעושה מלאכה מנדין אותו:"]],["רְחִיצָה כֵּיצַד, אָסוּר לִרְחֹץ כָּל גוּפוֹ, אֲפִלוּ בְּצוֹנֵן; אֲבָל פָּנָיו יָדָיו וְרַגְלָיו, בְּחַמִּין, אָסוּר; בְּצוֹנֵן, מֻתָּר. וְאִם הָיָה מְלֻכְלָךְ בְּטִּיט וְצוֹאָה, רוֹחֵץ כְּדַרְכּוֹ וְאֵינוֹ חוֹשֵׁשׁ. \u0005הַגָּה: וְכָל זֶה מִדִּינָא אֵינוֹ אָסוּר רַק שִׁבְעָה, אֲבָל אַחַר כָּךְ מֻתָּר בִּרְחִיצָה, \u0010y0\u0011 \u0010c0\u0011 אֶלָּא שֶׁנָּהֲגוּ הָאִדָּנָא לֶאֱסֹר כָּל רְחִיצָה כָּל ל' יוֹם (מהר\"מ הִלְכוֹת שְׂמָחוֹת ובהגמי\"י פ\"ז מהל' י\"ט ופ\"י דהל' אֵבֶל)\u0006 ; וַאֲפִלּוּ לָחֹף הָרֹאשׁ אָסוּר \u0005(לְקַמָּן סי' ש\"צ ובא\"ז)\u0006 ; וְאֵין לְשַׁנּוֹת הַמִּנְהָג, כִּי מִנְהָג קָדוּם הוּא וְנִתְיַסֵּד עַל פִּי וָתִיקִין \u0005(א\"ז בְּשֵׁם רַשְׁבָּ\"א)\u0006.\nסִיכָה כֵּיצַד, אָסוּר לָסוּךְ אֲפִלוּ כָּל שֶׁהוּא, אִם מְכַוֵּן לְתַעֲנוּג, אֲבָל אִם הוּא לְהַעֲבִיר הַזֻּהֲמָא מֻתָּר; וְאֵין צָרִיךְ לוֹמַר מִשּׁוּם רְפוּאָה, כְּגוֹן שֶׁיֵּשׁ לוֹ חֲטָטִין בְּרֹאשׁוֹ.\nיוֹלֶדֶת אֲבֵלָה \u0010y1\u0011 שֶׁצְּרִיכָה לִרְחֹץ, מֻתָּר. וְכֵן מָאן דְּאִית לֵיהּ עִרְבּוּבְיָא בְּרֵישֵׁיהּ, מֻתָּר לָחֹף רֹאשׁוֹ בְּחַמִּין, דְּלֹא גָרַע מֵאִסְטְנִיס \u0005(פי' קַר הַגּוּף וּמְצֻנָּן)\u0006, שֶׁמֻּתָּר לִרְחֹץ כָּל גוּפוֹ. וְלֹא כָּל מִי שֶׁאָמַר: אִסְטְנִיס אֲנִי, מַתִּירִין לוֹ, אֶלָא דַּוְקָא שֶׁהוּא יָדוּעַ שֶׁהוּא אִסְטְנִיס וּמִתְנַהֵג בִּנְקִיּוּת, וְאִם לֹא יִרְחַץ יִצְטַעֵר הַרְבֵּה וְיָבֹא לִידֵי מֵחוּשׁ.\nמִי שֶׁתְּכָפוּהוּ אֲבֵלָיו, שֶׁאֵרְעוּ שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, מֻתָּר לִרְחֹץ כָּל גוּפוֹ בְּצוֹנֵן.\nנִדָּה שֶׁנִּזְדַּמְּנָה זְמַן טְבִילָתָהּ בִּימֵי אֶבְלָהּ, אֵינָהּ טוֹבֶלֶת \u0005(טוּר בְּשֵׁם ר\"ת וְע\"פ ומהרי\"ק שֹׁרֶשׁ ל\"ה)\u0006. \u0005הַגָּה: \u0010y2\u0011 \u0010c1\u0011 וְכָל שֶׁכֵּן שֶׁאֵינָהּ רוֹחֶצֶת לִלְבֹּשׁ לְבָנִים. אֲבָל מִיָּד אַחַר ז', אַף עַל פִּי שֶׁנָּהֲגוּ אִסּוּר בִּרְחִיצָה כָּל ל', מִכָּל מָקוֹם הִיא מֻתֶּרֶת רַק שֶׁתְּשַׁנֶּה הַרְחִיצָה קְצָת\u0006 \u0005(א\"ז בְּסוֹף הִלְכוֹת אֵבֶל)\u0006, \u0005וְחָלוּק לָבָן תִּלְבֹּש וְסָדִין לָבָן תַּצִּיעַ, שֶׁלֹּא תָּבֹא לִידֵי סָפֵק\u0006 \u0005(תְּשׁוּבַת מהרי\"ל סִימָן ט\"ו)\u0006.\nאִשָּׁה לֹא תִּכְחֹל וְלֹא תְּפַרְקֵס בִּימֵי אֶבְלָהּ, \u0010y3\u0011 שֶׁכָּל אֵלוּ אֲסוּרִים בִּרְחִיצָה. וְאֵשֶׁת אִישׁ אֵינָהּ אֲסוּרָה אֶלָא תּוֹךְ שִׁבְעָה, אֲבָל אַחַר ז' מֻתֶּרֶת בַּכֹּל, כְּדֵי שֶׁלֹּא תִּתְגַנֶּה עַל בַּעֲלָהּ. כַּלָה שֶׁאֵרְעָהּ אֵבֶל תּוֹךְ שְׁלֹשִׁים יוֹם לְחֻפָּתָהּ, מֻתֶּרֶת לְהִתְקַשֵּׁט אֲפִלוּ תּוֹךְ ז'. בּוֹגֶרֶת שֶׁאֵרְעָהּ אֵבֶל, כֵּיוָן שֶׁעוֹמֶדֶת לִנָּשֵׂא, מֻתֶּרֶת בְּכִחוּל וּפִרְקוּס אֲבָל אֲסוּרָה בִּרְחִיצַת חַמִּין כָּל גוּפָהּ; נַעֲרָה אֲבֵלָה, אֲסוּרָה אֲפִלוּ בְּכִחוּל וּפִרְקוּס.",["\u0003אלא שנהגו האידנא לאסור רחיצה כל ל' כו'. \u0004כצ\"ל וכן הוא בעט\"ז ולא כמו שנדפס בספרים כל רחיצה כל ל') דודאי רחיצה בצונן ליכא איסורא כלל:","\u0003שצריכה לרחוץ מותר. \u0004אפילו ביום ראשון מיהו אם אין לה צורך כל כך יש להחמיר ביום ראשון כן כתבו האחרונים:","\u0003וכ\"ש שאינה רוחצת כו'. \u0004כלומר כיון דטבילה דאיכא למ\"ד טבילה בזמנה מצוה אסורה כ\"ש רחיצה ללבוש לבנים ובתשו' משאת בנימין סימן ה' חלק על הרב דדוקא טבילה קי\"ל דאסור כיון שאינו לצורך אבל רחיצה ללבון איכא צורך מצוה הלכך בין בתשע' באב בין בז' ימי אבלה תלביש ותציע כדרכה כשאר ימות השנים והרחיצה צריכה לשנות קצת וכמ\"ש הא\"ז והיינו שלא תרחוץ רק באותו מקום ובין ירכותיה בין בחמין בין בצונן ע\"כ דבריו:","\u0003שכל אלו אסורים כרחיצה. \u0004בכ\"ף כצ\"ל מיהו לענין זה חמור מרחיצה שאסור אחר ז' אם לא באשת איש ורחיצה שרי מדינא לאחר ז' כדלעיל סעיף א':"],["\u0003אלא שנהגו האידנא לאסור רחיצה כל שלשים יום. \u0004באור זרוע נתן טעם למנהג דחיישינן דילמא אתא למסרק רישיה דאסור כל שלשים וא\"כ לדידן דשרי לסרוק ראשו כדאיתא סימן ש\"ץ היה מותר לרחוץ ורש\"ל נתן טעם דאסרו משום תספורת כי כן דרך הנכנס במרחץ לגלח שערות ראשו ע\"כ ואין להקשות א\"כ בחול המועד דאסור תספורת ליהוי נמי רחיצה אסורה מטעם זה נראה ליישב דבח\"ה יש איסור על כל העולם ורבים לא יהיו נכשלים אבל באבילות דאיסור על היחיד הוא יש לחוש שמא ישכח באבילות ויגלח שערו כשאר בני אדם וסברא זו מצינו בפרק חבית (שבת דף קמ\"ו) במשנה אבל עשרה בני אדם ופירש\"י הואיל ומרובים הם מדכרי אהדדי:","\u0003וכ\"ש שאינה רוחצת ללבוש לבנים כו'. \u0004בתשובת מהרי\"ל סימן ט\"ז כתב וז\"ל ואסור בתשמיש המטה ואסור לטבול טבילת מצוה ביוה\"כ ותשעה באב דכדאי הוא בית אלהינו כו' וכן בז' ימי אבילות אבל תוך ל' שרי לטבול ולשמש ואפי' לרחוץ כדי ללבן כ' באור זרוע דשרי רק שתשנה הרחיצה קצת אבל חלוק לבן ודאי תלביש וסדין לבן ודאי תציע שלא תבוא לידי ספק עכ\"ל. כ' אחי הגאון מוהר\"ר יצחק הלוי ז\"ל דהאי אבל חלוק לבן כו' קאי נמי אתוך ז' וכן מבואר בבית יוסף שכתב שתוך ז' שרי לרחוץ רק שתשנה הרחיצ' קצת כו' ורמ\"א כאן הבין שמהרי\"ל כ' אבל חלוק לבן כו' קאי אתוך ל' דוקא משמע דתוך ז' אסור לרחוץ ללבישת ליבון והוא תימה דהא לאו רחיצה של תענוג היא ואמאי אסורה והא דאסו' רחיצה של טבילה היינו שהיא ללא צורך כיון שאסורה בתשמיש אבל רחיצה של ליבון אמאי אסורה ועל כל פנים נ\"ל דגם רמ\"א לא נתכוין כאן לדחות לבישת הליבון לגמרי עד אחר ז' דזה פשיטא שאינו שהרי אפשר לה ללבוש ליבון בלא רחיצה לגמרי כמ\"ש ביורה דעה סי' קצ\"ו סעיף ג' בהג\"ה דאפילו לא רחצה רק פניה של מטה סגי ובשעת הדחק סגי אפילו בלא רחיצה כלל רק שהחלוק נקי כו' ולמה נדחה כאן בחנם לבישת הליבון אלא ודאי שלא נתכוין רמ\"א לדחות לבישת הליבון כלל אלא הרחיצה לחוד הוא דאסור:\n\u0003ושוב \u0004ראיתי בתשו' משאת בנימין סימן ה' דמתיר אפי' לרחוץ בתוך שבעה ללבוש לבנים וחולק על רמ\"א בכאן ודבריו נכונים אלא דמ\"מ למעשה נראה לי דאין לה לרחוץ ללבישת ליבון אלא שתרחץ פניה של מטה ותלבוש חלוק נקי לא לבן ממש ותספור שבעה נקיים כנ\"ל ברור ונכון והמחמיר בזה לדחות לבישת הליבון לגמרי הוא מן המתמיהים:\n\u0003כתב \u0004רש\"ל מהר\"ם היה בעל ברית תוך ל' יום של אביו ורחץ בלילה שלפני המילה ונתן טעם לדבריו דהוה כרגל לגביה דידיה וחומרא בעלמא נהגו אבותינו ברחיצה עכ\"ל:"]],["\u0005(אָבֵל)\u0006 אָסוּר בִּנְעִילַת הַסַנְדָּל, דַּוְקָא שֶׁל עוֹר; אֲבָל בְּאַנְפִּלְיָא שֶׁל בֶּגֶד אוֹ שֶׁל גֻמִּי אוֹ שֶׁל שֵׂעָר אוֹ שֶׁל עֵץ, מֻתָּר, שֶׁאֵין מִנְעָל אֶלָא שֶׁל עוֹר. וְאִם הוּא שֶׁל עֵץ וּמְחֻפֶּה עוֹר, אָסוּר. \u0010y0\u0011\nחַיָּה מֻתֶּרֶת לִנְעֹל כָּל ל' יוֹם, מִפְּנֵי שֶׁהַצִּנָּה קָשָׁה לָהּ. \u0010c0\u0011\nכָּל אָדָם מֻתָּר לִנְעֹל בְּמָקוֹם שֶׁיֵּשׁ סַכָּנַת עַקְרָב.\nאָבֵל וּמְנֻדֶּה שֶׁהָיוּ מְהַלְכִים בַּדֶּרֶךְ, מֻתָּרִים בִּנְעִילַת הַסַנְדָּל, וּכְשֶׁיַּגִיעוּ לָעִיר, חוֹלְצִין. \u0010y1\u0011 וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁאִם הִיא עִיר שֶׁרֻבָּהּ עוֹבְדֵי כּוֹכָבִים, אֵין חוֹלְצִין עַד שֶׁיִּכָּנְסוּ לִרְחוֹב הַיְּהוּדִים.\nאִם צָרִיךְ לַחֲלֹץ מִנְעָל בְּבֵית הַקְבָרוֹת אַחַר שֶׁנִּקְבַּר הַמֵּת, נִתְבָּאֵר בְּסִימָן שע\"ה. \u0005הַגָּה: יֵשׁ אוֹמְרִים שֶׁצָּרִיךְ לֵילֵךְ יָחֵף מִבֵּית הַקְּבָרוֹת לְבֵיתוֹ אִם מֵת אָבִיו אוֹ אִמּוֹ (כָּל בּוֹ בְּשֵׁם ר\"י)\u0006, \u0010y2\u0011 וְלֹא רָאִיתִי נוֹהֲגִין כֵּן.",["\u0003חיה כו'. \u0004וה\"ה חולה ומי שיש לו מכה ברגלו כדאיתא בא\"ח סימן תרי\"ד ס\"ג:","\u0003ויש מי שאומר כו'. \u0004וכתב הרב בא\"ח סימן תקנ\"ד סעיף י\"ז שכן נהגו:","\u0003ולא ראיתי נוהגים כן. \u0004היינו משום רשעת העובדי כוכבים כדאיתא בכל בו בעל דין זה ובזה נסתלקה תמיהת הב\"ח על הרב ע\"ש מיהו היכא דליכא חשש דרשעת העובדי כוכבים יש לחלוץ מיד בבית הקברות כדלעיל ר\"ס שע\"ה וסימן שע\"ו ס\"ד:"],["\u0003כל אדם מותר לנעול במקום שיש סכנת עקרב. \u0004לפי מה שכתב המרדכי סוף מועד קטן דאם הולך לפני השר ויש הקפדה עליו אם ילך בלא מנעלים יתן עפר במנעליו וילך עכ\"ל. הוא הדין במקום סכנה ובכל מקום שצריך לילך במנעלים יעשה כן:"]],["אָבֵל אָסוּר בְּתַשְׁמִישׁ הַמִּטָּה, אֲבָל בִּשְׁאָר דְּבַר קֻרְבָה מֻתָּר, אֲפִלוּ בִּמְזִיגַת הַכּוֹס וְהַצָּעַת הַמִּטָּה וְהַרְחָצַת פָּנָיו יָדָיו וְרַגְלָיו, \u0010y0\u0011 בֵּין בַּאֲבֵלוּת דִּידֵהּ בֵּין בַּאֲבֵלוּת דִּידָהּ. \u0005אֲבָל חִבּוּק וְנִשּׁוּק יֵשׁ לְהַחְמִיר (רַבֵּנוּ יְרוּחָם)\u0006. וּמֻתֶּרֶת לֶאֱכֹל עִמּוֹ בִּקְעָרָה. וּמֻתֶּרֶת לִישַׁן עִמּוֹ \u0010y1\u0011 הוּא בְּבִגְדּוֹ וְהִיא בְּבִגְדָּהּ; וּמִיהוּ מִשּׁוּם לֵךְ לֵךְ אַמְרִינָן נְזִירָא יֵשׁ לְהַחְמִיר שֶׁלֹּא יִישַׁן \u0005(עִמָּהּ)\u0006 בְּמִטָּה כְּלָל.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר אֲבֵלוּת; \u0010y2\u0011 אֲבָל אִם מֵת אָבִיו שֶׁל חָתָן אוֹ אִמָּהּ שֶׁל כַּלָה, שֶׁמַּכְנִיסִין אֶת הַמֵּת לַחֶדֶר וְאֶת הֶחָתָן וְאֶת הַכַּלָה לַחֻפָּה, וּבוֹעֵל בְּעִילַת מִצְוָה וּפוֹרֵשׁ וְנוֹהֲגִים ז' יְמֵי הַמִּשְׁתֶּה, וְאַחַר כָּךְ שִׁבְעַת יְמֵי אֲבֵלוּת, אָסוּר לְהִתְיַחֵד עִמָּהּ כָּל י\"ד יוֹם, אֶלָא הוּא יָשֵׁן בֵּין הָאֲנָשִׁים וְהִיא יְשֵׁנָה בֵּין הַנָּשִׁים, כִּדְאִיתָא בְּסִימָן שמ\"ב. אֲבָל אִם כָּנַס לַחֻפָּה וְהִתְחִילוּ יְמֵי הַמִּשְׁתֶּה שֶׁלוֹ, וְאַחַר כָּךְ מֵת לוֹ מֵת, מֻתָּר לְהִתְיַחֵד עִמָּהּ כְּמוֹ בִּשְׁאָר אֲבֵלוּת, וְהוּא שֶׁבָּעַל; אֲבָל אִם לֹא בָּעַל, אָסוּר לְהִתְיַחֵד עִמָּהּ כָּל יְמֵי הָאֵבֶל, בֵּין בְּחֹל בֵּין בְּשַׁבָּת.",["\u0003בין באבילות דידיה כו'.\u0004 כ' הפרישה פירוש אפילו באבילות דידה דאיכא למיחש יותר הואיל והוא אינו אבל דהכל ממנו ולא ממנה עכ\"ל ולא דק דאדרבה באבילות דידיה איכא למיחש יותר דאם יצרו מתגבר עליו נשמעת לו דכיון דאינה אבלה כדאיתא בפ\"ק דכתובות דף ד' ע\"ש):","\u0003הוא בבגדו כו'. \u0004אבל בלא בגדים אסור אפי' סינר מפסיק אפילו בשבת ורגל. טור ורמב\"ן:","\u0003אבל אם מת כו'. \u0004דכיון שהקילו לו רבנן והתירו לו לנהוג ז' ימי המשתה תחלה חיישינן דאתי לזלזולי ביה אבל אם כנס כבר לחופה כו' ליכא למיחש דאתי לזלזולי שהרי לא הקילו לו כלום שקדמו להן ימי החופה. וכן מי שאירעו אבל ברגל מותר לו להתייחד כמ\"ש הרב לקמן סימן שצ\"ט ס\"ב שהרי לא הקילו לו שום דבר אלא הרגל מעצמו הוא שנקבע וגם לית ביה אפושי שמחה כל כך כמו חתן כ\"כ הפוסקים:"],[]],["אָבֵל, כָּל שִׁבְעָה יָמִים \u0010y0\u0011 אָסוּר לִקְרוֹת בְּתוֹרָה, נְבִיאִים וּכְתוּבִים, מִשְׁנָה, גְמָרָא, הֲלָכוֹת וְאַגָדוֹת. \u0010y1\u0011 \u0010c0\u0011 וְאִם רַבִּים צְרִיכִים לוֹ לְהִתְלַמֵּד, מֻתָּר, וּבִלְבַד שֶׁלֹּא יַעֲמִיד תֻּרְגְמָן אֶלָא יֹאמַר לְאַחֵר, וְהָאַחֵר לַתֻּרְגְמָן, וְתֻרְגְמָן יַשְׁמִיעַ לָרַבִּים. \u0005הַגָּה: אוֹ יִדְרֹשׁ בְּעַצְמוֹ (מָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006. וְיָכוֹל לִפְסֹק אִסּוּר וְהֶתֵּר לְיָחִיד הַשּׁוֹאֵל אוֹתוֹ, אִם אֵין אַחֵר אֶלָּא הוּא, וּצְרִיכִין לוֹ \u0005(בא\"ז וְר' יְרוּחָם)\u0006. אָבֵל אָסוּר לוֹמַר הֲלָכָה לְתַלְמִידָיו, וְכֵן נוֹהֲגִין, אַף עַל פִּי שֶׁיֵּשׁ מְקִלִּין \u0005(תא\"ו בְּשֵׁם י\"א)\u0006.\nאִם הָאָבֵל כֹּהֵן, וְאֵין בב\"ה כֹּהֵן אַחֵר, \u0010y2\u0011 אָסוּר לוֹ לַעֲלוֹת לִקְרוֹת בַּתּוֹרָה.\nאִם אֵין שָׁם מִי שֶׁיִּתְפַּלֵל לְהוֹצִיא אֶת הָרַבִּים יְדֵי חוֹבָתָן, יָכוֹל הָאָבֵל לְהִתְפַּלֵל לְהוֹצִיאָן. \u0005הַגָּה: \u0010y3\u0011 וּמִצְוָה לְהִתְפַּלֵּל שַׁחֲרִית וְעַרְבִית בַּמָּקוֹם שֶׁמֵּת שָׁם, אֲפִלּוּ אֵין אָבֵל, כִּי יֵשׁ בָּזֶה נַחַת רוּחַ לַנְּשָׁמָה (א\"ז)\u0006, וְהָאָבֵל מִצְטָרֵף לְמִנְיָן \u0005(שָׁם)\u0006.\nאָבֵל מֻתָּר לִקְרוֹת בְּאִיּוֹב וּבְקִינוֹת וּבִדְבָרִים הָרָעִים שֶׁבְּיִרְמִיָּה וּבְהִלְכוֹת אֲבֵלוּת \u0005וְעַיֵּן בא\"ח סִימָן תקנ\"ד סָעִיף ב'.\u0006 וְהָנֵי מִלֵי בֵּינוֹ לְבֵין עַצְמוֹ, אֲבָל אֵינוֹ לוֹמֵד עִם אֲחֵרִים, אֶלָא הֵם יוֹשְׁבִים וְנוֹשְׂאִים וְנוֹתְנִין בְּהִלְכוֹת אֲבֵלוּת, וְאִם טָעוּ מְשִׁיבָן בְּשָׂפָה רָפָה, וְהוּא אֵינוֹ שׁוֹאֵל. וְהָנֵי מִלֵי כְּשֶׁאֵין רַבִּים צְרִיכִים לוֹ, אֲבָל אִם רַבִּים צְרִיכִים לוֹ, אֲפִלוּ בַּהֲלָכוֹת אֲחֵרוֹת מֻתָּר, כִּדְאָמְרִינַן.\nאָבֵל שֶׁיֵּשׁ לוֹ בָּנִים קְטַנִּים, \u0010y4\u0011 אֵין לוֹ לְבַטְּלָם מִלִמּוּדָם.",["\u0003אסור לקרות בתורה. \u0004דכתיב פקודי ה' ישרים משמחי לב:","\u0003ואם רבים צריכים כו'. \u0004כתוב בבדק הבית בשם א\"ח מלמדי תינוקות י\"ל שדינן כרבים צריכים לו ועוד דמלאכת האבד הוא כשהתינוקות בטלים ע\"כ וכן כתב מהרש\"ל בתשובה סימן ס\"ו ע\"ש:","\u0003אסור לו כו'. \u0004כתב הב\"ח ותימה דבסימן ת' בדין שבת כ' הרב דבאין שם כהן אחר אלא הוא מותר לקרותו וכאן לא כ' כלום עכ\"ל ולק\"מ דהכא טעמא דאיסורא דאבל אסור בדברי תורה אתא לאשמועינן ומדין אבילות בשבת לא מיירי אבל התם דמיירי בכל הסימן מדין איסור אבילות בשבת קאמר דמותר לעלות משום דאל\"כ ה\"ל אבילות דפרהסי' ואין אבילות דפרהסי' נוהג בשבת והכי משמע התם להדיא ע\"ש:","\u0003ומצוה להתפלל כו'. \u0004ע\"ל סי' שע\"ו ס\"ג:","\u0003אין לו לבטלם. \u0004דאין אבילות לקטן כדלקמן ס\"ס שצ\"ו:"],["\u0003ואם רבים צריכים לו להתלמד. \u0004בתא\"ו נתיב כ\"ח כתב וראיתי לרבותי שהיו מגידים ההלכה אחר ג' ימים מזה נ\"ל במלמד שיכול ג\"כ ללמוד ההלכה. עם תלמידיו אחר ג' ימים דזה הוה בכלל רבים צריכים לו דתינוקות של בית רבן הבל פיהם חביב מלימוד הגדולים כדאמרינן במסכת שבת אינו דומה הבל שיש בו חטא לאין בו חטא. ונראה פשוט שאבל מותר להשתמש בתשמישי התורה כשקורין כגון גלילה וכיוצא בה דקריאה לחוד אסור לו משום דכתיב משמחי לב וכן ראיתי בהג\"ה שזה לשונו הרב ר\"ח היה אבל בזמן שני וחמישי והתפללו סליחות אצלו וקראו בתורה והוא היה גולל ס\"ת כו' ומביאה בדרישה:"]],["אָבֵל אָסוּר בִּשְׁאֵלַת שָׁלוֹם. כֵּיצַד, שְׁלֹשָׁה יָמִים הָרִאשׁוֹנִים אֵינוֹ שׁוֹאֵל בִּשְׁלוֹם כָּל אָדָם, וְאִם אֲחֵרִים לֹא יָדְעוּ שֶׁהוּא אָבֵל וְשָׁאֲלוּ בִּשְׁלוֹמוֹ, לֹא יָשִׁיב לָהֶם שָׁלוֹם אֶלָא יוֹדִיעֵם שֶׁהוּא אָבֵל. מִג' עַד שִׁבְעָה, אֵינוֹ שׁוֹאֵל, וְאִם אֲחֵרִים לֹא יָדְעוּ שֶׁהוּא אָבֵל וְשָׁאֲלוּ בִּשְׁלוֹמוֹ, מֵשִׁיב לָהֶם. מִשִּׁבְעָה עַד ל', שׁוֹאֵל בִּשְׁלוֹם אֲחֵרִים שֶׁהֵם שְׁרוּיִים בְּשָׁלוֹם, וְאֵין אֲחֵרִים שׁוֹאֲלִים בִּשְׁלוֹמוֹ, וְכָל שֶׁכֵּן שֶׁמֵּשִׁיב לְמִי שֶׁשּׁוֹאֵל בִּשְׁלוֹמוֹ. לְאַחַר ל' יוֹם, הֲרֵי הוּא כִּשְׁאָר כָּל אָדָם. בַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר קְרוֹבִים, אֲבָל עַל אָבִיו וְאִמּוֹ שׁוֹאֵל בִּשְׁלוֹם אֲחֵרִים אַחַר שִׁבְעָה, וְאֵין אֲחֵרִים שׁוֹאֲלִים בִּשְׁלוֹמוֹ עַד אַחַר י\"ב חֹדֶשׁ. \u0005הַגָּה: וּמֵאַחַר שֶׁאָסוּר בִּשְׁאֵלַת שָׁלוֹם, כָּל שֶׁכֵּן שֶׁאָסוּר לְהַרְבּוֹת בִּדְבָרִים (רַמְבַּ\"ם פ\"ה וְכָל בּוֹ)\u0006. וְאִם עוֹשֶׂה לִכְבוֹד רַבִּים, כְּגוֹן שֶׁרַבִּים בָּאִים לְנַחֲמוֹ, מֻתָּר לוֹמַר לָהֶם: לְכוּ לְבָתֵּיכֶם לְשָׁלוֹם, דְּלִכְבוֹד רַבִּים שָׁרֵי \u0005(נ\"י פֶּרֶק אֵין מְגַלְּחִין וּבְהַגָּהוֹת מיי' וּבְמָרְדְּכַי הִלְכוֹת אֵבֶל)\u0006. \u0010y0\u0011 וְיֵשׁ מְקִלִּין הָאִדָּנָא בִּשְׁאֵלַת שְׁלוֹם הָאָבֵל לְאַחַר ל', וְאֵין טַעַם לָהֶם, \u0010y1\u0011 אִם לֹא שֶׁיַּחְלְקוּ לוֹמַר שֶׁזֶּה מַה שֶּׁאָנוּ נוֹהֲגִים לֹא מִקְרֵי שְׁאֵלַת שָׁלוֹם שֶׁבִּימֵיהֶם \u0005(סְבָרַת הָרַב)\u0006. וְעַיֵּן בא\"ח סִימָן פ\"ט.\nהַמּוֹצֵא אֶת חֲבֵרוֹ אָבֵל בְּתוֹךְ ל' יוֹם, מְדַבֵּר עִמּוֹ תַּנְחוּמִין וְאֵינוֹ שׁוֹאֵל בִּשְׁלוֹמוֹ. לְאַחַר ל' יוֹם, שׁוֹאֵל בִּשְׁלוֹמוֹ וְאֵינוֹ מְדַבֵּר עִמּוֹ תַּנְחוּמִים כְּדַרְכּוֹ, אֶלָא מִן הַצַּד, שֶׁאֵינוֹ מַזְכִּיר לוֹ שֵׁם הַמֵּת, אֶלָא אוֹמֵר לוֹ: תִּתְנַחֵם. מֵתָה אִשְׁתּוֹ וְנָשָׂא אַחֶרֶת, אֵינוֹ נִכְנָס לְבֵיתוֹ לְדַבֵּר עִמּוֹ תַּנְחוּמִין. מְצָאוֹ בַּשּׁוּק, אוֹמֵר לוֹ: תִּתְנַחֵם, בְּשָׂפָה רָפָה וּבְכֹבֶד רֹאשׁ. אֲבָל אִם לֹא נָשָׂא אַחֶרֶת, מְדַבֵּר עִמּוֹ תַּנְחוּמִין \u0010y2\u0011 עַד שֶׁיַּעַבְרוּ ג' רְגָלִים. וְעַל אָבִיו וְעַל אִמּוֹ מְדַבֵּר עִמּוֹ תַּנְחוּמִין כָּל י\"ב חֹדֶשׁ; לְאַחַר י\"ב חֹדֶשׁ מְדַבֵּר עִמּוֹ מִן הַצַּד. \u0010y3\u0011\nמָקוֹם שֶׁנָּהֲגוּ לִהְיוֹת שׁוֹאֲלִים בִּשְׁלוֹם אֲבֵלִים בְּשַׁבָּת, שׁוֹאֲלִים. וְכָתַב הַרַמְבַּ\"ם שֶׁהָאָבֵל נוֹתֵן שָׁלוֹם לְכָל אָדָם בְּשַׁבָּת, שֶׁהוּא מִכְּלַל דְּבָרִים שֶׁבְּפַרְהֶסְיָא. \u0005הַגָּה: \u0010c0\u0011 וְאָסוּר לִשְׁלֹחַ מָנוֹת לְאָבֵל עַל אָבִיו וְאִמּוֹ כָּל י\"ב חֹדֶשׁ, וַאֲפִלּוּ בְּשַׁבָּת, בְּמָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לִשְׁאֹל בִּשְׁלוֹמוֹ בְּשַׁבָּת (תְּשׁוּבַת מהרי\"ל סי' ל\"א)\u0006 ; אֲבָל בְּמָקוֹם שֶׁנָּהֲגוּ לִשְׁאֹל בִּשְׁלוֹמוֹ בְּשַׁבָּת, גַּם זֶה שָׁרֵי.",["\u0003ויש מקילין האידנא בשאילת שלום האבל. \u0004על אביו ואמו אחר ל':","\u0003אם לא שיחלקו כו'. \u0004ובאמת אין זה טעם נכון דא\"כ תוך ל' נמי ולא מצינו לשום פוסק שחילק בכך:","\u0003עד שיעברו ג' רגלים. \u0004כדלקמן סימן שצ\"ב ס\"ב:","\u0003מקום כו'. \u0004ואיתא בירושלמי הובא בפוסקים ר' אושעיא רבא אזל לחד אתר וחמא תמן אבלים בשבתא ושאל בהון ואמר להון איני יודע מנהג מקומכם אבל שלום עליכם כמנהג מקומי ועיין בא\"ח סימן רפ\"ז:"],["\u0003ואסור לשלוח מנות. \u0004כתב מו\"ח ז\"ל בשם הג\"ה בשם רבינו יהודה אבל תוך ל' אינו יכול להזמין לאחרים או להזמן עם אחרים ע\"כ ונראה דה\"ה כל י\"ב חדש על אביו ואמו:"]],["אָבֵל חַיָּב בַּעֲטִיפַת הָרֹאשׁ, דְּהַיְנוּ שֶׁיְּכַסֶה רֹאשׁוֹ בְּטַלִית אוֹ בְּסוּדָר וְיַחֲזִיר קְצָתוֹ עַל פִּיו וְעַל רֹאשׁ הַחֹטֶם; וְהָנֵי מִלֵי שֶׁצָּרִיךְ עֲטִיפָה, בְּכָל הַיּוֹם. אֲבָל כְּשֶׁבָּאִין מְנַחֲמִים אֶצְלוֹ, מְגַלֶה רֹאשׁוֹ לִכְבוֹדָם. \u0005הַגָּה: \u0010y0\u0011 \u0010c0\u0011 וְיֵשׁ אוֹמְרִים שֶׁאֵין נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ בַּעֲטִיפָה (הַגָּהוֹת מַיְמוֹנִי פ\"ה)\u0006 ; וְכֵן הַמִּנְהָג פָּשׁוּט, וְאֵין לְהַחְמִיר לְשַׁנּוֹת בַּמֶּה שֶׁלֹּא נָהֲגוּ אֲבוֹתֵינוּ.",["\u0003וי\"א שאין נוהגין כו'. \u0004מפני שמביא לידי שחוק גדול מן העובדי כוכבים ועבדים ושפחות שבינינו מיהו יש לנהוג בעטיפה קצת דהיינו למשוך הכובע למטה לפני העינים וכן משמע בבית חדש ועיין לקמן סימן ת':"],["\u0003וי\"א שאין נוהגין במדינות אלו כו'. \u0004כתב הרוקח אבל חייב בעטיפה כמו עתה שמושכין הכובע לפני העינים כל ז' ימים ובשבת בצינעא ולא בפרהסיא עכ\"ל. וכתב מו\"ח ז\"ל לפי זה מיד כשמתחיל השליח צבור ברכו אז יגביה האבל את הכובע דלא להוי מילתא דבפרהסיא עכ\"ל:"]],["אָבֵל חַיָּב בִּכְפִיַּת הַמִּטָּה. \u0010c0\u0011 וּבִשְׁעַת שֵׁנָה וַאֲכִילָה, יוֹשֵׁב עַל מִטָּה כְּפוּיָה, אֲבָל כָּל הַיּוֹם אֵינוֹ יוֹשֵׁב, אֲפִלוּ עַל מִטָּה כְּפוּיָה, אֶלָא עַל גַבֵּי קַרְקַע. וְכֵן הַמְנַחֲמִים אֵינָם רַשָּׁאִים לֵישֵׁב אֶלָא עַל גַבֵּי קַרְקַע. \u0010y0\u0011\nעַכְשָׁו לֹא נָהֲגוּ בִּכְפִיַּת הַמִּטָּה, מִפְּנֵי שֶׁיֹאמְרוּ הָעוֹבְדֵי כּוֹכָבִים שֶׁהוּא מְכַשְּׁפוּת, וְעוֹד שֶׁאֵין הַמִּטּוֹת שֶׁלָנוּ עֲשׂוּיוֹת כַּמִּטּוֹת שֶׁלָהֶן כְּדֵי שֶׁיְּהֵא נִכָּר בָּהֶם כְּפִיָּה.",["\u0003עכשיו לא נהגו כו'. \u0004מ\"מ אסור לו לישב על גבי ספסל או כרים וכסתות כי אם על גבי קרקע אם לא חולה וזקן שיש להם צער בישיבה על גבי קרקע מותרים להשים כר קטן מתחתיו. מיהו יכול לילך ולעמוד וא\"צ לישב כלל רק כשהמנחמים אצלו צריך לישב ע\"ג קרקע וה\"ה דכשרוצה לישן דצריך לישן על גבי קרקע מיהו המנחמים יושבים ע\"ג ספסל דמסתמא מחיל להו. כל זה מבואר בדרישה:"],["\u0003ובשעת שינה כו'. \u0004כתב רש\"ל אבל אין לו לישן כל ז' אלא ע\"ג הקרקע כ\"כ הר\"מ והאבל א\"צ לישב ע\"ג קרקע אלא כשהמנחמים אצלו ואז גם המנחמים צריכין לישב ע\"ג קרקע אא\"כ אמר להו האבל שבו ע\"ג ספסלים דמצי מחיל ליקריה (ואפשר משום הכי אין המנחמי' יושבין בזמן הזה ע\"ג קרקע דמחיל האבל מסתמא) ולישב האבל ע\"ג כרים וכסתות בעוד שהמנחמים אצלו לא יתכן אמנם חולה וזקן שיש להם צער בישיבת קרקע מותר להשים כר קטן תחתיו עכ\"ל. מה שכ' שאין צריך האבל לישב ע\"ג קרקע אלא כשהמנחמים אצלו פירוש אבל בלאו הכי יכול לעמוד או לילך בחדרו אבל על כל פנים אסור לישב ע\"ג ספסל:"]],["אָבֵל \u0010c0\u0011 אָסוּר לְהַנִּיחַ תְּפִלִין בְּיוֹם רִאשׁוֹן; \u0010y0\u0011 וְאַחַר שֶׁהֵנֵץ הַחַמָּה בְּיוֹם שֵׁנִי, מֻתָּר לַהֲנִיחָם.\nמִבָּעֵי לֵהּ לְאָבֵל לְיַתּוֹבֵי דַּעְתֵּהּ לְכַוּוֹנֵי לִבֵּהּ לַתְּפִלִין שֶׁלֹּא יַסִיחַ דַּעְתּוֹ מֵהֶם, אֲבָל בִּשְׁעַת הֶסְפֵּד וּבְכִי לֹא מַנַּח לְהוּ.",["\u0003ואחר שהנץ כו'. \u0004ויש פוסקים דאינו אסור אלא ביום ראשון וביום ב' מותר מיד אפי' קודם הנץ החמה וכ\"פ הב\"ח. ואם שמע שמועה קרובה דינה כיום קבורה דאסור להניח תפילין. כן משמע מדברי הרמב\"ן והמחבר לקמן סי' ת\"ב ס\"ב וכ\"פ בתשו' משאת בנימין סימן פ\"ב ופשוט הוא:"],["\u0003אסור להניח תפילין. \u0004גם ביום שמועה קרובה אסור להניח תפילין כ\"כ הרמב\"ן וב\"י מביאו לקמן סימן ת\"ב:"]],["אָבֵל אָסוּר לְכַבֵּס כְּסוּתוֹ כָּל שִׁבְעָה יָמִים, אֲפִלוּ בְּמַיִם לְבַד; וּלְאַחַר שִׁבְעָה, מֻתָּר. וּכְשֵׁם שֶׁאָסוּר לְכַבֵּס, כָּךְ אָסוּר לִלְבֹּשׁ הַמְכֻבָּסִים קֹדֶם לָכֵן. \u0010y0\u0011 \u0005וְאַחַר ז' שָׁרֵי, \u0010y1\u0011 וְהָעוֹלָם נָהֲגוּ בּוֹ אִסּוּר (כְּדַעַת ריב\"א וְסִיעָתוֹ)\u0006. וְנוֹהֲגִין שֶׁאָדָם אַחֵר \u0010y2\u0011 לוֹבְשָׁם תְּחִלָּה, וְאַחַר כָּךְ לוֹבְשָׁם הָאָבֵל, וְהַמִּנְהָג עִקָּר \u0005(טוּר בְּשֵׁם סמ\"ק וכ\"כ הַמָּרְדְּכַי ה\"א וְכָל בּוֹ)\u0006. וְכֵן נוֹהֲגִין בִּמְדִינוֹת אֵלּוּ לְאַחַר שִׁבְעָה; וְאִם לְבָשׁוֹ אָדָם אַחֵר \u0010y3\u0011 רַק שָׁעָה אַחַת דַּי בְּכָךְ \u0005(כָּל בּוֹ וסמ\"ק)\u0006. וְאֵין צָרִיךְ לוֹמַר שֶׁאָסוּר לִלְבֹּשׁ חֲדָשִׁים. וְגַם הַסְדִינִים וְהַמַּצָּעוֹת שֶׁל מִטָּה אָסוּר לְכַבְּסָן וּלְהַצִּיעַ \u0010c0\u0011 הַמְכֻבָּסִין. וְכֵן מִטְפְּחוֹת הַיָּדַיִם, אַף עַל פִּי שֶׁמֻּתָּר לְכַבְּסָן בַּמּוֹעֵד; וְכֵן כָּל אוֹתָן שֶׁשָּׁנִינוּ שֶׁמֻּתָּר לְכַבְּסָן בַּמּוֹעֵד, כְּגוֹן הַיּוֹצֵא מִבֵּית הַשִּׁבְיָה וּמִבֵּית הָאֲסוּרִים, וְהַמְּנֻדֶּה שֶׁהִתִּירוּ לוֹ חֲכָמִים, וְהַנִּשְׁאָל לְחָכָם וְהֻתַּר, וְהַבָּא מִמְּדִינַת הַיָּם \u0010y4\u0011 שֶׁהָלַךְ לְהַרְוִיחַ \u0010y5\u0011 וְלֹא הָיָה לוֹ פְּנַאי לְגַלֵחַ, אֲסוּרִים בִּימֵי אֶבְלוֹ, שֶׁאִם אֵרְעוֹ אֶחָד מֵהֶם, קֹדֶם הָאֲבֵלוּת וְנִכְנַס מִיָּד לְתוֹךְ הָאֲבֵלוּת, אָסוּר לְכַבֵּס אֶלָא אִם כֵּן אֵרְעוֹ אֶחָד מֵהֶם וּתְכָפוּהוּ מִיָּד שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, אָז מֻתָּר לְכַבֵּס אַף בְּנֶתֶר וְחוֹל וַאֲפִלוּ תּוֹךְ שִׁבְעָה, וּבִלְבַד שֶׁיַּעֲשֶׂנּוּ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ. וְאַחַר שֶׁתְּכָפוּהוּ אֲבֵלָיו זֶה אַחַר זֶה, מְכַבֵּס בְּמַיִם אֲבָל לֹא בְּנֶתֶר וְאָהָל.\nמֻתָּר לְכַבֵּס בִּגְדֵי קְטַנִּים שֶׁמֵּת אֲבִיהֶם.\nאָסוּר לִלְבֹּשׁ תּוֹךְ שִׁבְעָה כֵּלִים חֲדָשִׁים צְבוּעִים וִישָׁנִים יוֹצְאִים מִתַּחַת הַמַּכְבֵּשׁ. \u0005(פי' כְּלִי לַעֲצֹר בּוֹ הַבְּגָדִים)\u0006. \u0005הַגָּה: יֵשׁ אוֹמְרִים דְּאָסוּר לִלְבֹּשׁ בִּגְדֵי שַׁבָּת תּוֹךְ ד' שָׁבוּעוֹת הָרִאשׁוֹנִים, אֲבָל אַחַר כָּךְ מֻתָּר אֲפִלּוּ עַל אָבִיו וְאִמּוֹ, וְכֵן לַעֲשׂוֹת בְּגָדִים חֲדָשִׁים\u0006 \u0005(כָּל בּוֹ בְּשֵׁם מוֹהֲרַ\"ם)\u0006, \u0005אָבֵל נָהֲגוּ אִסּוּר כָּל י\"ב \u0010y6\u0011 חֹדֶשׁ.\u0006\nאָסוּר תּוֹךְ שִׁבְעָה לְכַבֵּס וּלְהַנִּיחַ, בֵּין עַל יְדֵי עַצְמוֹ בֵּין עַל יְדֵי אֲחֵרִים. וְאִם הָיְתָה כְּסוּתוֹ \u0010y7\u0011 בְּקִבֹּלֶת בְּיַד אֲחֵרִים, מְכַבֵּס אוֹתוֹ כִּדַרְכּוֹ כְּמוֹ שְׁאָר מְלַאכְתּוֹ בְּתָלוּשׁ שֶׁבְּיַד אֲחֵרִים, בְּקִבֹּלֶת.\nכָּל שְׁלֹשִׁים יוֹם אָסוּר לִלְבֹּשׁ \u0005אוֹ לְהַצִּיעַ תַּחְתָּיו (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006 בֶּגֶד מְגֹהָץ, וְהוּא שֶׁיְּהֵא לָבָן וְחָדָשׁ, וַאֲפִלוּ הוּא שֶׁל פִּשְׁתָּן. וְעַל אָבִיו וְעַל אִמּוֹ, אָסוּר עַד שֶׁיַּגִיעַ הָרֶגֶל אַחַר שְׁלֹשִׁים וְיִגְעֲרוּ בּוֹ חֲבֵרָיו.\nגִהוּץ יֵשׁ אוֹמְרִים צק\"ל בִּלְשׁוֹן עֲרָב, וְיֵשׁ אוֹמְרִים דְּהַיְנוּ כִּבּוּס בְּמַיִם וְאֵפֶר אוֹ בְּנֶתֶר וּבֹרִית.\nאַחַר שִׁבְעָה מֻתָּר לְגַהֵץ, בֵּין לְעַצְמוֹ בֵּין לַאֲחֵרִים; וְלֹא אָמְרוּ שְׁלֹשִׁים יוֹם לְגִהוּץ, אֶלָא \u0010y8\u0011 לִלְבֹּשׁ.\nיֵשׁ מִי שֶׁאוֹמֵר דְּהָאִידָּנָא לֵיכָּא אִסוּר גִהוּץ, שֶׁהֲרֵי אָמְרוּ גִהוּץ שֶׁלָנוּ כְּכִבּוּס שֶׁלָהֶם.",["\u0003ואחר ז' שרי. \u0004היינו כשאין מגוהץ או לדידן דגיהוץ שלנו ככיבוס שלהם כדלקמן בסוף הסימן:","\u0003והעולם נהגו בו אסור. \u0004היינו שחוששים לסברת ריב\"א וסייעתו דאסרו כיבוס כל ל' ומשמע בתוספות דמ\"ק דף כ\"ג ע\"א דאינו אוסר אלא במכובס בנתר וחול אבל לא במים לבד וכתב הב\"ח ולפ\"ז במכובס במים לבד אין צריך להלבישו אחר תחלה ופשיטא דשרי לאחר ז' מיד:","\u0003לובשם תחלה. \u0004ואפילו במגוהצין ג\"כ באבן חלקה מותר בכה\"ג וכ\"כ הב\"ח:","\u0003רק שעה אחת. \u0004כלומר זמן מה וא\"צ שעה זמניות וכן משמע בפוסקים וכן נוהגין ולא כמ\"ש בעט\"ז שעה או שתים ואולי גם הוא ל\"ד קאמר:","\u0003שהלך להרויח. \u0004לאפוקי לטיול ועיין כא\"ח סימן תקל\"א:","\u0003ולא היה לו פנאי לגלח. \u0004והוא הדין כאן לכבס:","\u0003אסור כו'. \u0004הטעם משום דאסור בעשיית מלאכה:","\u0003ביד אחרים. \u0004ובבית אחרים. וכדלעיל סימן ש\"פ סעיף י\"ח ע\"ש:","\u0003יש מי כו'. \u0004עיין בא\"ח סימן תקנ\"א סעיף ג':"],["\u0003וכן מטפחות הידים והשלחן כו'. \u0004כתב רש\"ל עיין בא\"ח סימן תקנ\"א שהיתר פשוט לכבוד שבת לפרוס המטפחת המכובסת ע\"כ:"]],["אָבֵל אָסוּר לְגַלֵחַ שְׂעָרוֹ, אֶחָד שְׂעַר רֹאשׁוֹ וְאֶחָד שְׂעַר זְקָנוֹ וְאֶחָד כָּל שֵׂעָר שֶׁבּוֹ, וַאֲפִלוּ שֶׁל בֵּית הַסְתָרִים, כָּל ל' יוֹם. וּשְׂעַר שֶׁל הַשָּׂפָה וּמֵהַצְּדָדִים, \u0010y0\u0011 כָּל שֶׁמְּעַכֵּב אֶת הָאֲכִילָה, תּוֹךְ ז' אָסוּר; אַחַר שִׁבְעָה, מֻתָּר.\nיָשַׁב לְגַלֵחַ, וְאָמְרוּ לוֹ: מֵת אָבִיו, הֲרֵי זֶה מַשְׁלִים רֹאשׁוֹ, \u0010c0\u0011 אֶחָד הַמְגַלֵחַ וְאֶחָד הַמִּתְגַלֵחַ; וּמַה שֶּׁהַסַפָּר גוֹמֵר, הַיְנוּ בִּדְלֵיכָּא סַפָּר אַחֵר בְּמָתָא.\nכָּל אוֹתָם שֶׁאָמְרוּ מֻתָּר לְגַלֵחַ בְּחֹל הַמּוֹעֵד, אִם אֵרְעוֹ אֶחָד מֵאֵלוּ קֹדֶם הָאֲבֵלוּת, וְנִכְנַס מִיָּד תּוֹךְ הָאֵבֶל, אָסוּר לְגַלֵחַ. אֲבָל אִם אֵרְעוֹ אֶחָד מֵאֵלוּ, וּתְכָפוּהוּ מִיָּד שְׁנֵי אֲבֵלוּת זֶה אַחַר זֶה, מְגַלֵחַ כְּדַרְכּוֹ, בֵּין בְּתַעַר בֵּין בְּמִסְפָּרַיִם, וַאֲפִלוּ תּוֹךְ שִׁבְעָה. וְאָדָם אֶחָד שֶׁתְּכָפוּהוּ אֲבֵלָיו זֶה אַחַר זֶה, מֵקֵל שְׂעָרוֹ בְּתַעַר אֲבָל לֹא בְּמִסְפָּרַיִם. \u0005וּבִלְבַד שֶׁיַּעֲשֶׂנּוּ בְּצִנְעָא (בֵּית יוֹסֵף בְּשֵׁם הָרַמְבַּ\"ן)\u0006.\nעַל כָּל הַמֵּתִים מְגַלֵחַ לְאַחַר שְׁלֹשִׁים; עַל אָבִיו וְעַל אִמּוֹ, עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו. \u0005הַגָּה: וְאֵין הָרֶגֶל מְהָנֵי אִם פָּגַע קֹדֶם שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו (טוּר)\u0006. וְעַיֵּן בא\"ח סִימָן תקמ\"ח. וְשִׁעוּר גְּעָרָה יֵשׁ בּוֹ פְּלֻגְתָּא, וְנוֹהֲגִים בְּג' חֳדָשִׁים \u0005(כְּדַעַת מהרא\"י בִּפְסָקָיו וַאֲגֻדָּה ומהרי\"ל והר\"ן)\u0006. וּבִמְקוֹמוֹת אֵלּוּ נוֹהֲגִין שֶׁאֵין מִסְתַּפְּרִין עַל אָב וָאֵם כָּל י\"ב חֹדֶשׁ \u0005(מהרי\"ל מִנְהַג קְצָת מְקוֹמוֹת)\u0006, אִם לֹא לְצֹרֶךְ, כְּגוֹן שֶׁהִכְבִּיד עָלָיו שְׂעָרוֹ, אוֹ שֶׁהוֹלֵךְ בֵּין הָעוֹבְדֵי כּוֹכָבִים וּמִתְנַוֵּל בֵּינֵיהֶם בְּשַׂעֲרוֹתָיו, דְּמֻתָּר לְסַפֵּר \u0005(כֵּן הֵשִׁיב הָאוֹר זָרוּעַ)\u0006.\nאִשָּׁה מֻתֶּרֶת בִּנְטִילַת שֵׂעָר אַחַר ז'. \u0005הַגָּה: וְיֵשׁ אוֹסְרִים אַף לְאִשָּׁה, וְכֵן \u0010y1\u0011 \u0010y2\u0011 \u0010c1\u0011 עִקָּר.\u0006\nלִסְרֹק רֹאשׁוֹ בְּמַסְרֵק, מֻתָּר, אֲפִלוּ תּוֹךְ שִׁבְעָה.\nכְּשֵׁם שֶׁאָסוּר לְגַלֵחַ כָּל שְׁלֹשִׁים יוֹם, כָּךְ אָסוּר לִטֹּל צִפֹּרְנַיִם בִּכְלִי; אֲבָל בְּיָדָיו אוֹ בְּשִׁנָּיו, מֻתָּר, אֲפִלוּ תּוֹךְ שִׁבְעָה. וְאִשָּׁה שֶׁאֵרַע טְבִילָתָהּ אַחַר שִׁבְעָה, תּוֹךְ שְׁלֹשִׁים, אִם תִּטֹּל צִפָּרְנֶיהָ בְּיָדֶיהָ אוֹ בְּשִׁנֶּיהָ אֵינָהּ נוֹטֶלֶת יָפֶה, אֶלָא תֹּאמַר לְעוֹבֶדֶת כּוֹכָבִים לִטְּלָם בְּתַעַר אוֹ בְּמִסְפָּרַיִם. \u0005הַגָּה: \u0010y3\u0011 \u0010c2\u0011 וְלָאו דַּוְקָא עוֹבֶדֶת כּוֹכָבִים, אֶלָּא הוּא הַדִּין יִשְׂרְאֵלִית, וְסִרְכָא דְּלִשְׁנָא דְּחֹל הַמּוֹעֵד נָקַט (דַּעַת עַצְמוֹ)\u0006.",["\u0003כל שמעכב כו'. \u0004תימה דכאן פסק כדעת הרי\"ץ גיאות שבטור ובב\"י כתב דנקטינן כהראב\"ד ורמב\"ם דאסור כלל ואין חילוק בין שערות המעכבים האכילה או לא ע\"ש:","\u0003לסרוק כו'. \u0004כאן חסר סעיף א' שהרי נרשם סעיף ד' סעיף ו' ולא נרשם סעיף ה' ולא כעט\"ז שחלק סעיף ה' לב' סעיפים ע\"ש אלא צ\"ל סעיף חדש כמו שהוא במקצת ספרי הש\"ע וכך צ\"ל אשה מותרת בנטילת שער אחר ז'. הג\"ה ויש אוסרים אף לאשה וכן עיקר ע\"כ. וכן הוא בהקדמת סמ\"ק ע\"ש ועיין בב\"י ב' הדעות והב\"ח פסק דבמקום שדרכה של אשה לגלח שערות אלו כגון רבוי שערות דצידעא ובת צידעא מותרת ליטלם אחר ז' ע\"ש:","\u0003האשה כו'. \u0004ובב\"י משמע דאפי' לאיש מותר שאין כאן לא תענוג ולא שמחה ונ\"ל דל\"ד נקט אשה ובב\"ח כתב שמצא שט\"ס הוא וצריך להגיה לסרוק ראשו כו' וכן הוא בעט\"ז אך בהגה' סמ\"ק בשם א\"ז מתיר דוקא לאשה ולא לאיש ומביאו הב\"ח:","\u0003ולאו דוקא עובדת כוכבים כו'. \u0004ולפעד\"נ דדוקא נקט עובדת כוכבים דאלת\"ה א\"כ אפילו לאיש לשתרי לגלח או ליטול צפרניו על ידי ישראל אחר אלא ודאי כיון דשלוחו הוא אסור וא\"כ אמאי שרי באשה טפי בשלוחה מבהיא עצמה וגם דוחק לומר דסרכא דלישנא דח\"ה נקט דהא המחבר ס\"ל בא\"ח סי' תקל\"ב דמותר ליטול צפרניו בח\"ה אלא דהגמי\"י ס\"ל דאסור ליטול צפרניו בח\"ה וקאמר דעל ידי עובד כוכבים מותר דאמירה לעובד כוכבי' שבות ובמקום מצוה לא גזור ואם כן ה\"ה באבל דהא קי\"ל אמירה לעובדי כוכבים שבות אפילו בדבר שאינו של שבת וכדלעיל הלכות כלאי בהמה סי' רצ\"ז ס\"ד וא\"כ הכא דוקא לעובד כוכבים שרי דאמירה לעובד כוכבים לא אסור אלא משום שבות ובמקום מצוה לא גזרו אבל לישראל אסור ודו\"ק:"],["\u0003אחד המגלח. \u0004פי' שבשעת הגילוח נאמר למגלח שמת לו מת יכול לגמור מלאכתו משום כבוד הבריות:\n\u0003בסימן \u0004זה נחסר סעיף אחד והיינו סעיף ה' וכצ\"ל אשה מותרת בנטילת שער אחר שבעה ימים. הג\"ה ויש אוסרין אף לאשה וכן עיקר. קבלתי שנמצא כן בש\"ע של רמ\"א כתיבת ידו ז\"ל:","\u0003לסרוק ראשו במסרק כו'. \u0004כצ\"ל:","\u0003ולאו דוקא כו'. \u0004תמוה לי דאם יש איסור ליטול בעצמה ודאי גם ע\"י ישראלית אסור דיש משום לפני עור וגו') אבל נראה לי שהוצרכו ליטול ע\"י ישראלית כדי שיהיה ע\"י שינוי כמ\"ש בסמוך דאילו בידיה או בשיניה אי אפשר לה להסירם היטב כפי הצורך לטבילה אבל תימה לי על בעל הש\"ע שהרי פסק בסעיף ה' אשה מותרת בנטילת שער אחר ז' והיינו כרי\"ף ורמב\"ם וכמו שכ' ב\"י ולמה לא תהיה מותרת כאן ליטול צפרניה ע\"י עצמה בלא שינוי והלא צפרנים אינם חמורים משער. ועוד קשיא אפי' לדעת רמ\"א והלא בסי' שצ\"ג סעיף ג' התירו ליטול צפרנים בשביל למול ולמה לא נתיר בשביל טבילת מצוה לכולי עלמא ולא ראינו נשים נוהגות כן ליטול צפרנים על ידי אחר תוך שלשים:"]],["אָבֵל אָסוּר בְּשִׂמְחָה; לְפִיכָךְ לֹא יִקַח תִּינוֹק בְּחֵיקוֹ כָּל שִׁבְעָה, שֶׁמָּא יָבֹא לִידֵי שְׂחוֹק.\nעַל כָּל מֵתִים נִכְנָס לְבֵית הַמִּשְׁתֶּה לְאַחַר שְׁלֹשִׁים יוֹם; עַל אָבִיו וְעַל אִמּוֹ, \u0010c0\u0011 לְאַחַר י\"ב חֹדֶשׁ. וְאַף אִם הַשָּׁנָה מְעֻבֶּרֶת, מֻתָּר לְאַחַר י\"ב חֹדֶשׁ. וּמִיהוּ \u0010y0\u0011 שִׂמְחַת מְרֵעוּת שֶׁהָיָה חַיָּב לִפְרֹעַ אוֹתָהּ מִיָּד, מֻתָּר לַעֲשׂוֹתָהּ מִיָּד אַחַר שִׁבְעָה. אֲבָל אִם אֵינוֹ חַיָּב לְפָרְעָהּ, אָסוּר לִכָּנֵס לָהּ עַד ל'. וְעַל אָבִיו וְעַל אִמּוֹ, אַף עַל פִּי שֶׁחַיָּב לְפָרְעָהּ, אָסוּר \u0005עַד\u0006 לְאַחַר \u0010y1\u0011 י\"ב חֹדֶשׁ. \u0005הַגָּה: וּבַחֲבוּרַת מִצְוָה, כְּגוֹן שֶׁמַּשִּׂיא יָתוֹם וִיתוֹמָה לְשֵׁם שָׁמַיִם, וְאִם לֹא יֹאכַל שָׁם יִתְבַּטֵּל הַמַּעֲשֶׂה, מֻתָּר לְאַחַר ל', \u0010y2\u0011 אֲבָל תּוֹךְ ל' אָסוּר לְכָל סְעֻדַּת מִצְוָה שֶׁבָּעוֹלָם (טוּר בְּשֵׁם הָרַאֲבַ\"ד)\u0006. אֲבָל סְעֻדַּת מִצְוָה דְּלֵית בֵּיהּ שִׂמְחָה, מֻתָּר לִכָּנֵס בָּהּ, כְּגוֹן פִּדְיוֹן הַבֵּן אוֹ סְעֻדַּת בְּרִית מִילָה, מֻתָּר לֶאֱכֹל שָׁם אֲפִלּוּ תּוֹךְ שִׁבְעָה, וּבִלְבַד שֶׁלֹּא יֵצֵא מִפֶּתַח בֵּיתוֹ \u0005(ת\"ה סִי' רנ\"א)\u0006. וְיֵשׁ אוֹסְרִין בִּסְעֻדַּת בְּרִית מִילָה \u0005(מָרְדְּכַי)\u0006. וְהַמִּנְהָג שֶׁלֹּא \u0010c1\u0011 לֶאֱכֹל בְּשׁוּם סְעֻדָּה בָּעוֹלָם כָּל י\"ב חֹדֶשׁ, אִם הוּא חוּץ לְבֵיתוֹ, וּבְתוֹךְ הַבַּיִת מְקִלִּין שֶׁאוֹכֵל בְּבֵיתוֹ בִּסְעֻדַּת בְּרִית מִילָה, וְכָל שֶׁכֵּן בִּשְׁאָר סְעֻדּוֹת שֶׁאֵין בָּהֶם שִׂמְחָה. אֲבָל בִּסְעֻדַּת נִשּׂוּאִין יֵשׁ לְהַחְמִיר, כֵּן נִרְאֶה לִי. אָבֵל שֶׁהוּא בַּעַל בְּרִית אוֹ מוֹהֵל, יִלְבַּשׁ בִּגְדֵי שַׁבָּת עַד לְאַחַר הַמִּילָה. \u0010c2\u0011 וּמֻתָּר לִכָּנֵס לַמִּילָה לֶאֱכֹל שָׁם, אִם הוּא לְאַחַר ל', אַף עַל פִּי שֶׁאֵין הַמִּילָה בְּבֵיתוֹ \u0005(בֵּית יוֹסֵף בְּשֵׁם תְּשׁוּבַת מהרי\"ל)\u0006.\nלִכָּנֵס לַחֻפָּה שֶׁלֹּא בִּשְׁעַת אֲכִילָה, לִשְׁמֹעַ הַבְּרָכוֹת, יֵשׁ מַתִּירִין וְיֵשׁ אוֹסְרִין; אֶלָא עוֹמֵד חוּץ לַבַּיִת לִשְׁמֹעַ הַבְּרָכוֹת. \u0005הַגָּה: אָבֵל לֹא יִכָּנֵס לַבַּיִת כְּלָל בְּשָׁעָה שֶׁעוֹמְדִים שָׁם בְּמַזְמוּטֵי חָתָן וְכַלָּה, וְכֵן נוֹהֲגִים בְּאַשְׁכְּנַז (טוּר)\u0006 וּבִמְדִינוֹת אֵלּוּ. וְכָל זֶה בְּבַיִת שֶׁעוֹשִׂין הַחֲתֻנָּה וְאוֹכְלִין וְשׁוֹתִין וּשְׂמֵחִין שָׁם, אֲבָל בְּחֻפָּה שֶׁעוֹשִׂין בְּבֵית הַכְּנֶסֶת, שֶׁמְּבָרְכִין שָׁם בִּרְכַּת אֵרוּסִין וְנִשּׂוּאִין וְאֵין שִׂמְחָה כְּלָל, מֻתָּר מִיָּד אַחַר שִׁבְעָה \u0005(הַגָּהוֹת מַיְמוֹנִי)\u0006. וְיֵשׁ אוֹסְרִין עַד שְׁלֹשִׁים \u0005(שָׁם בְּשֵׁם ראבי\"ה)\u0006, וְכֵן נִרְאֶה לִי. וְיֵשׁ מְקוֹמוֹת שֶׁמַּחְמִירִין לִהְיוֹת הָאָבֵל עוֹמֵד כָּל י\"ב חֹדֶשׁ חוּץ לְבֵית הַכְּנֶסֶת לִשְׁמֹעַ הַבְּרָכוֹת \u0005(הַגָּהוֹת במהרי\"ל)\u0006. וּמִכָּל מָקוֹם נִרְאֶה דְּאָבֵל יָכוֹל לְבָרֵךְ בִּרְכַּת אֵרוּסִין וְנִשּׂוּאִין תַּחַת הַחֻפָּה שֶׁבְּבֵית הַכְּנֶסֶת. \u0010c3\u0011 וְכֵן יוּכַל לְהַכְנִיס חָתָן כְּדֶרֶךְ אַרְצֵנוּ שֶׁשְּׁנֵי אֲנָשִׁים מַכְנִיסִין הֶחָתָן תַּחַת \u0010y3\u0011 הַחֻפָּה. וְיוּכַל לִלְבֹּשׁ קְצָת בִּגְדֵי שַׁבָּת בְּשָׁעָה שֶׁמַּכְנִיסִין, \u0010y4\u0011 וּבִלְבַד שֶׁיְּהֵא אַחַר ל' \u0005(ד\"ע)\u0006, וְכֵן נוֹהֲגִין. יֵשׁ מַתִּירִין לְאָבֵל לֶאֱכֹל בִּסְעֻדַּת נִשּׂוּאִין אוֹ בְּרִית מִילָה עִם הַמְּשַׁמְּשִׁין, \u0010y5\u0011 וּבִלְבַד שֶׁלֹּא יְהֵא בִּמְקוֹם שִׂמְחָה כְּגוֹן בְּבַיִת אַחֵר \u0005(כָּל בּוֹ וּבֵית יוֹסֵף בְּשֵׁם סמ\"ק)\u0006, וְיֵשׁ אוֹסְרִין \u0005(הַגָּהוֹת אֲשֵׁרִי)\u0006, וְכֵן נוֹהֲגִין, רַק שֶׁהָאָבֵל מְשַׁמֵּשׁ שָׁם, אִם יִרְצֶה, וְאוֹכֵל בְּבֵיתוֹ מִמַּה שֶּׁשּׁוֹלְחִין לוֹ מִן הַסְּעֻדָּה. יֵשׁ מַתִּירִין לְאָבֵל \u0010y6\u0011 \u0010c4\u0011 לֶאֱכֹל בְּאוֹתָהּ סְעֻדָּה שֶׁל דָּגִים שֶׁעוֹשִׂים לְאַחַר הַנִּשּׂוּאִין, כִּי מֵאַחַר שֶׁכְּבָר פָּסְקוּ לוֹמַר שֶׁהַשִּׂמְחָה בִּמְעוֹנוֹ אִית לֵיהּ הֶכֵּר שֶׁאֵין שִׂמְחָה בְּאוֹתָהּ סְעֻדָּה, וְשָׁרֵי \u0005(בֵּית יוֹסֵף בְּשֵׁם רוֹקֵחַ)\u0006. \u0010y7\u0011 יֵשׁ אוֹמְרִים דְּאָסוּר לֶאֱכֹל בִּסְעֻדָּה בַּלַּיְלָה שֶׁבְּיוֹם הַמָּחֳרָת מֵת אָבִיו אוֹ אִמּוֹ \u0005(בְּהַגָּהוֹת מִנְהָגִים בְּשֵׁם מהרי\"ו)\u0006.",["\u0003שמחת מריעות כו'. \u0004שעושים ריעים זה עם זה שאוכלים ושותים זה עם זה היום וחוזרים ואוכלים עם זה למחר:","\u0003י\"ב חודש. \u0004ואף אם השנה מעוברת סגי בי\"ב חדש. כן כתבו הפוסקים:","\u0003אבל תוך שלשים אסור.) \u0004משמע אפי' בשאר קרובים וכן משמע בעט\"ז וכן הוא להדיא בהראב\"ד שהביא בספר תורת האדם שממנו מקור דין זה ע\"ש וכן בל' הראב\"ד שברא\"ש וכן לענין שאלת שלום לעיל סימן שפ\"ה ולענין נשואין לקמן סימן שנ\"ב אין חילוק בשלשים בין אביו ואמו לשאר קרובים והב\"ח לא פירש כן ולפעד\"נ כמ\"ש:","\u0003ויכול ללבוש קצת בגדי שבת כו'. \u0004בעט\"ז השמיט תיבת קצת ואולי גם הרב ל\"ד נקט דה\"ה דיכול ללבוש כל בגדי שבת וכן נוהגין:","\u0003ובלבד שיהא אחר ל' כו'. \u0004גם כאן פירש הב\"ח דיש להתיר לאבל על שאר קרוביו תוך ל' כמו בכניסת יתום ויתומה דלעיל ולשון הרב לא משמע כן אלא נראה כמ\"ש בס\"ק ג':","\u0003ובלבד שלא יהא במקום שמחה. \u0004כגון בבית אחר כצ\"ל וכן הוא בעט\"ז:","\u0003לאכול באותה סעודה של דגים כו'. \u0004כתב הב\"ח מיהו בליל ב' אע\"פ דנוהגים בק\"ק קראקא שלא לברך שהשמחה במעונו אין לאבל לאכול באותה סעודה דל\"ד ליום ב' שכבר בעל בעילת מצוה בליל ב' כפי מנהגם ולכך עושים סעודה של דגים ביום ב' משום ברכת דגים כדאיתא פ\"ק דכתובות הלכך אינה נקראת סעודת שמחה ואין אומרים לא אשר ברא ולא שהשמחה במעונו אבל בליל ב' מקמי בעילת מצוה דמברכים אשר ברא לא נגמרו הנשואים ומה שלא נהגו לומר שהשמח' במעונו הוא מפני דמתאספי' שם אנשים ונשים כו' עיין שם:","\u0003יש אומרים דאסור לאכול כו'. \u0004וכ' העטרת זהב ולא ראיתי נוהגים כן ואני אומר דבר שאינו מצוי לא שייך בו מנהג כמו שכתב לעיל ר\"ס ק\"צ ולא ראינו אינו ראיה ואני ראיתי נוהגים לאיסור גם לקמן ס\"ס ת\"ב כתב הרב בסתם לאיסור:"],["\u0003לאחר י\"ב חדש. \u0004כתוב בטור ואף אם השנה מעוברת משמע דאחר י\"ב חדש הפסיק לגמרי האבילות מדשרי לילך לבית המשתה ותמהתי על שיש אנשים נוהגים קצת אבילות גם בחודש הי\"ג מאין להם דבר זה והוא באמת דבר בטל וכ\"כ מו\"ח ז\"ל:","\u0003בשום סעודה בעולם תוך י\"ב חדש. \u0004וה\"ה תוך ל' על שאר קרובים:","\u0003למילה לאכול שם אם הוא לאחר ל'. \u0004תמוה לי שהרי בתשובת מהרי\"ל סי' קט\"ז משמע דאחר ז' מותר וב\"י מביאו:\n\u0003שוב \u0004ראיתי בדרכי משה שהכריע כן מסברא דנפשיה לאסור עד לאחר ל' והנה דבר פשוט שעל אביו ואמו קאי זה דאלו בשאר קרובים פשיטא שמותר לאחר שלשים דאין לומר דקמ\"ל איסורא תוך ל' דא\"כ היה לו לומר ואסור כל ל' אלא דעל אביו ואמו קאי ובשאר קרובים אפי' תוך ל' שרי אחר ז' ימים והוא תמוה דבהדיא כתב הרא\"ש פרק אלו מגלחין דתוך ל' שוה בשאר קרובים לאביו ואמו ומ\"מ אין להקל בתוך ל' של אביו ואמו נגד הכרעת רמ\"א:","\u0003וכן יוכל להכניס חתן כו'. \u0004כתב מו\"ח ז\"ל ונראה דכ\"ש שיש להתיר לאבל על שאר קרוביו תוך ל' להכניס החתן דטפי יש להתיר תוך ל' על שאר קרוביו מתוך י\"ב חדש על אביו ואמו ונ\"ל דלא התירו אלא להכניס החתן תחת החופה אבל לא ליכנס לאכול על סעודת החתונה דהא אפילו במשיא יתום ויתומה לא התירו לאכול בסעודה אם לא בדרך שאם לא יהיה שם יתבטל המעשה והא ודאי דמשיא יתומה הוה כמו אביה וטפי הוה מסתבר להתיר מאותו שמכניס החתן תחת החופה כנ\"ל שלא כקצת שנוהגים להקל בזה:","\u0003באותה סעודה של דגים כו'. \u0004לפי המנהג שכתב רמ\"א שלא לאכול בשום סעודה כו' גם זה אסור:"]],["אָסוּר לִשָּׂא אִשָּׁה כָּל ל' יוֹם, אֲפִלוּ בְּלֹא סְעֻדָּה; וּלְאַחַר שְׁלֹשִׁים, מֻתָּר, אֲפִלוּ עַל אָבִיו וְאִמּוֹ, וַאֲפִלוּ לַעֲשׂוֹת \u0010c0\u0011 סְעֻדָּה. וּמֻתָּר לְקַדֵּשׁ אִשָּׁה אֲפִלוּ בְּיוֹם הַמִּיתָה, וְהוּא שֶׁלֹּא יַעֲשֶׂה סְעֻדָּה, אֶלָא אִם כֵּן עָבְרוּ שְׁלֹשִׁים יוֹם. \u0010y0\u0011 \u0005וְיֵשׁ אוֹמְרִים דְּגַם לְאָרֵס אָסוּר כָּל ל' יוֹם (טוּר וְהָרֹא\"שׁ וְהָרַמְבַּ\"ן)\u0006 וְכֵן \u0010y1\u0011 עִקָּר.\nמֵתָה אִשְׁתּוֹ, אָסוּר לִשָּׂא אַחֶרֶת עַד שֶׁיַּעַבְרוּ עָלֶיהָ \u0010c1\u0011 שָׁלֹשׁ רְגָלִים, \u0005אֲבָל לִכָּנֵס לְבֵית הַמִּשְׁתֶּה, \u0010y2\u0011 דִּינוֹ כְּמוֹ בִּשְׁאָר קְרוֹבִים, (טוּר)\u0006 \u0010c2\u0011 וְרֹאשׁ הַשָּׁנָה וְיוֹם כִּפּוּרִים אֵינָם חֲשׁוּבִים כִּרְגָלִים לְעִנְיָן זֶה. וְאִם לֹא \u0010y3\u0011 קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה, אוֹ שֶׁיֵּשׁ לוֹ בָּנִים קְטַנִּים, אוֹ שֶׁאֵין לוֹ מִי שֶׁיְּשַׁמְּשֶׁנּוּ, \u0010y4\u0011 \u0010c3\u0011 מֻתָּר לְקַדֵּשׁ מִיָּד וְלִכְנֹס אַחַר שִׁבְעָה; וְלֹא יָבֹא עָלֶיהָ עַד לְאַחַר שְׁלֹשִׁים יוֹם, אֶלָא אִם כֵּן לֹא קִיֵּם מִצְוֹת פְּרִיָּה וּרְבִיָּה, שֶׁאָז מֻתָּר לָבוֹא עָלֶיהָ אַחַר שִׁבְעָה. \u0005הַגָּה: וְהוּא הַדִּין בִּשְׁאָר אֲבֵלוּת, אֲפִלּוּ בַּאֲבֵלוּת דְּאָבִיו וְאִמּוֹ, מֻתָּר לִשָּׂא וְלָבוֹא עָלֶיהָ אַחַר שִׁבְעָה, אִם לֹא קִיֵּם פִּרְיָה וּרְבִיָּה. יֵשׁ אוֹמְרִים דְּאַף מִי שֶׁהוּא עָשִׁיר וִיכֹלֶת בְּיָדוֹ לִשְׂכֹּר לוֹ מְשָׁרְתִים וּמְשָׁרְתוֹת, מִכָּל מָקוֹם אִם אֵין בִּתּוֹ אוֹ כַּלָּתוֹ אֶצְלוֹ בְּבֵיתוֹ שֶׁתּוּכַל לְשַׁמְּשׁוֹ בַּחֲפִיפַת הָרֹאשׁ אוֹ שְׁאָר דְּבָרִים שֶׁמִּתְבַּיֵּשׁ מֵאֲחֵרִים, מִקְרֵי אֵין לוֹ מִי שֶׁיְּשַׁמְּשֶׁנּוּ, וְכָל כַּיּוֹצֵא בָּזֶה (פִּסְקֵי מהרא\"י סי\"ג)\u0006 ; וְלָכֵן נִשְׁתַּרְבֵּב הַמִּנְהָג שֶׁרַבִּים מְקִלִּין בָּעִנְיָן וְנוֹשְׂאִין נָשִׁים תּוֹךְ שָׁלֹשׁ רְגָלִים, וּבַעַל נֶפֶשׁ יָחוּשׁ לְעַצְמוֹ. מִי שֶׁתְּפָשׂוֹ הַשַּׂר וְאֵינוֹ רוֹצֶה לְהַנִּיחוֹ מִתְּפִיסָתוֹ, עַד שֶׁיִּשָּׂא אִשָּׁה תּוֹךְ שָׁלֹשׁ רְגָלִים אַחַר מִיתַת אִשְׁתּוֹ, יֵשׁ מַתִּירִין מִשּׁוּם צַעַר דִּידֵיהּ \u0005(בֵּית יוֹסֵף)\u0006, וְכֵן נִרְאֶה לִי \u0010c4\u0011 עִקָּר.\nמִי שֶׁלֹּא קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה, וְשִׁדֵּךְ אִשָּׁה וְאַחַר שֶׁהֵכִין צָרְכֵי חֻפָּה, מֵת אֲחִי \u0010y5\u0011 \u0010c5\u0011 הַמְשֻׁדֶּכֶת, מֻתָּר לְכָּנְּסָהּ וְלָבוֹא עָלֶיהָ אַחַר שִׁבְעָה. \u0005הַגָּה: וְכֵן אִם יֵשׁ לוֹ בָּנִים קְטַנִּים וְנִתְרַצָּה לְאָחוֹת אִשְׁתּוֹ, \u0010y6\u0011 מֻתָּר לְכַנְּסָהּ, \u0010y7\u0011 כִּי הִיא מְרַחֶמֶת עַל בְּנֵי אֲחוֹתָהּ יוֹתֵר מֵאַחֶרֶת (כ\"כ בְּפי' הָרֹא\"שׁ וְהַגָּהוֹת מַיְמוֹנִי וּמָרְדְּכַי)\u0006.",["\u0003וי\"א כו'. \u0004מיהו לקשר עצמו בשידוכין בלא אירוסין ודאי שרי אפי' ביום המיתה. ב\"ח:","\u0003מתה אשתו כו'. \u0004והיא שמת בעלה אינה מתאבלת אלא ל' יום אלא שאסורה ליארס ולינשא עד ג' חדשי' משום הבחנה כדאיתא ביבמות (ונתבאר בא\"ע סימן י\"ג) עכ\"ל טור וכ\"כ הפוסקים וכתב המרדכי הטעם שאין האשה צריכה להמתין ג' רגלים משום דאשה בכל דהו ניחא לה ושוכחת אהבת הראשון לאחר ל' יום. ואם אירע שנשא' תוך ל' יום לאבילותן של שאר קרובים לא תבעל כן דעת הרמב\"ם לפי מה שפירש הב\"ח דבריו ע\"ש:","\u0003דינו כמו בשאר קרובים. \u0004לעיל סי' שצ\"א וכן כל שאר אבילות אינו נוהג רק ל' יום כמו בשאר קרובים:","\u0003מצות פריה ורביה. \u0004באופן שנתבאר בא\"ע סי' א':","\u0003מותר לקדש מיד. \u0004כתב הב\"ח דהיינו לדעת המחבר דמתיר בסעיף א' לקדש ביום המיתה ולא קיימא לן הכי אלא רשאי לקדשה ולכנסה מיד אחר ז':","\u0003מותר לכנסה כו'. \u0004כיון דאיכא הפסד בדבר אם לא יכנוס וגם לא קיים פריה ורביה וע\"ל סי' שמ\"ב:","\u0003מותר לכנסה. \u0004מיד ויבא עליה אחר שבעה כן כ' העט\"ז והב\"ח כתב דלא יבא עליה עד אחר שלשים ונראה דלא פליגי דהעט\"ז מיירי בשלא קיים מצות פריה ורביה והב\"ח איירי כשקיים:","\u0003כי היא מרחמת כו'. \u0004ולכן מותר אפי' בלא הפסד:"],["\u0003ומותר לקדש כו'. \u0004שמא יקדמנו אחר ברחמים:","\u0003ג' רגלים. \u0004לאו משום תוספת אבילות אלא כדי שתשתכח הראשונה מדעתו בשעה שיהיה עם השניה וע\"י שמחת הרגלים הוא שוכח הראשונה:","\u0003וראש השנה ויוה\"כ אינם כרגלים. \u0004באגודה פסק דחשיבי כרגלים אף לענין זה:\n\u0003כתוב \u0004בטור והיא שמת בעלה אינה מתאבלת אלא ל' יום עכ\"ל ולענין שתינשא לאחר מבואר בא\"ע סי' י\"ג והנשים נוהגות שמתאבלות שנה תמימה על בעליהן ואיני יודע להם סמך וראיה ואולי עושות בשביל בניהם שמתאבלין י\"ב חדש והטעם שאשה אינה צריכה להמתין ג' רגלים להנשא לאחר כמו האיש דאשה בכל דהו ניחא לה. כן כ' המרדכי:","\u0003מותר לקדש מיד ולכנוס אחר ז'. \u0004לטעמיה אזיל דפסק בסעיף א' כרמב\"ם דבכל גווני מותר לקדש מיד אבל למאי דפסק רמ\"א שם דאפי' לקדש אסור ה\"נ אסור לקדש עד אחר ז' ותימה על רמ\"א שלא כ' כאן כלום:","\u0003מי שלא קיים כו'. \u0004בטור איתא בלשון זה מעשה באחד ששידך ומת אחי המשודכת קרוב לחופה אחר שהזמין הקרואין והתיר ר\"ת שתכנס לחופה תוך ל' משום פריה ורביה שלו כיון ששידך זאת ואם לא ישאנה לא ישא אחרת אבל אם לא שידך אע\"פ שחפץ בזאת יותר מבאחרת אסור וכן הורה אדוני אבי הרא\"ש הלכ' למעשה לאחד ששידך והכין כל צרכי החופה ומתה אחות המשודכת והוא לא קיים פריה ורביה והתיר לו לכנוס ולבעול אחר ז' ימים שיהיה לו הפסד בדבר אם לא יכנוס אבל בלא הפסד אמר שלא היה מתיר עכ\"ל היתר זה הוא חידוש דאע\"פ שהיא אבילה ואינה חייבת בפריה ורביה מ\"מ התיר לה בשבילו שהוא יקיים פריה ורביה וזה לא מצינו בגמרא להיתר בהדיא אלא דמעשה שהיה כך היה סמוך לחופה והרא\"ש לא סמך על ר\"ת להתיר בזה אלא משום הפסד הסעודה שצירף לזה ומשים הכי במעשה דר\"ת לא זכר כלום מהכנת צרכי החופה כמו שזכר בהוראת הרא\"ש ובזה מתורץ מה שהקשה מו\"ח ז\"ל למה הצריך הטור לזכור שנית תורף המעשה בהוראת הרא\"ש ולא כ' בקיצור וכן הורה אדוני אבי ז\"ל למעשה משום הפסד דיש שינוי לשון בהוראת הרא\"ש ובאבן עזר סי' י\"ד כתב הטור סתם מי ששידך אשה ואירעה אבל כו' ולא זכר שם משום הפסד הסעודה והיינו לדינא הוא כן אבל למעשה אין היתר אלא משום הפסד סעודה וכהרא\"ש וכ\"פ בש\"ע כאן והא דכ' כאן מותר לכנסה ולבוא עליה אחר ז' הך לכנסה הוא נמי אחר ז' דוקא דאין לומר משום הפסד מותר לכנסה אפי' תוך ז' דהא כ' הרא\"ש פרק אלו מגלחין בשם ר\"ת אפי' במקום פסידא לא התירו לכנוס תוך ז' אף באין לו בנים דלא התירו אלא באביו של חתן ואמה של הכלה דוקא וכל שכן שהיא אבילה ואינה מחויבת בפריה ורביה אלא ודאי כמו שכתבתי ובפרישה האריך בזה ולא עיין בדברי ר\"ת שכ' הרא\"ש בשמו כמו שזכרתי:","\u0003מותר לכנסה כי היא מרחמת. \u0004פי' כניסה לחופה דוקא התירו אבל לא לבעול עד אחר ל' יום בדין זה דהרי אין כאן מצות פריה ורביה:"]],["אָבֵל, ג' יָמִים הָרִאשׁוֹנִים אֵינוֹ יוֹצֵא לְבֵית הָאָבֵל \u0010y0\u0011 וְלֹא לְבֵית הַקְבָרוֹת; מִכָּאן וָאֵילָךְ, אִם מֵת לַאֲחֵרִים מֵת בִּשְׁכוּנָתוֹ, יוֹצֵא אַחַר הַמִּטָּה לְבֵית הַקְבָרוֹת, וְאֵינוֹ יוֹשֵׁב בִּמְקוֹם הַמְנַחֲמִים אֶלָא בִּמְקוֹם הַמִּתְנַחֲמִים; וְאִם אֵין שָׁם כְּדֵי מִטָּה וְקוֹבְרֶיהָ, \u0010y1\u0011 יוֹצֵא אֲפִלוּ בְּיוֹם רִאשׁוֹן וַאֲפִלוּ בִּשְׁכוּנָה אַחֶרֶת. \u0005הַגָּה: וּמִקְצָת יוֹם ג' הֲרֵי הוּא כְּכֻלּוֹ (הַגָּהוֹת מַיְמוֹנִי פ\"ז)\u0006. וְלֹא רָאִיתִי נוֹהֲגִין כֵּן עַכְשָׁו, כִּי אֵין אָבֵל הוֹלֵךְ לְבֵית הַקְּבָרוֹת וְלֹא לְבֵית הָאָבֵל כָּל שִׁבְעָה; וְאֶפְשָׁר שֶׁלָּאו חִיּוּב הוּא, אֶלָּא רְשׁוּת, וּמֵאַחַר שֶׁעַכְשָׁו אֵין מִתְנַחֲמִין כְּמוֹ בִּימֵיהֶם, שֵׁב וְאַל תַּעֲשֶׂה עָדִיף.\nאָבֵל, שָׁבוּעַ הָרִאשׁוֹן אֵינוֹ יוֹצֵא מִפֶּתַח בֵּיתוֹ, \u0010y2\u0011 וַאֲפִלוּ לִשְׁמֹעַ בִּרְכוֹת חֻפָּה אוֹ בִּרְכוֹת הַמִּילָה. \u0005הַגָּה: מִיהוּ הַמֵּקֵל לָצֵאת בַּלַּיְלָה, מִפְּנֵי הַצֹּרֶךְ, לֹא הִפְסִיד (ת\"ה סִימָן ר\"צ)\u0006. וְהָא דְּאָסוּר לָצֵאת חוּץ לְבֵיתוֹ, הַיְנוּ דַּוְקָא לְטַיֵּל, אוֹ לְמַשָּׂא וּמַתָּן וְכַדּוֹמֶה, אֲבָל אִם שָׁלַח מוֹשֵׁל אַחֲרָיו \u0005(מָרְדְּכַי ה\"א)\u0006 אוֹ שֶׁצָּרִיךְ לֵילֵךְ בַּדֶּרֶךְ אוֹ לִשְׁאָר דְּבָרִים הַצְּרִיכִים לוֹ הַרְבֵּה, כְּגוֹן דָּבָר הָאָבֵד, מֻתָּר לוֹ לָצֵאת \u0005(תּוֹסָפוֹת סוֹף מ\"ק)\u0006, וְכֵן נוֹהֲגִין. וְדִין נְעִילַת סַנְדָּלָיו, עַיֵּן לְעֵיל סִימָן שפ\"ב. שְׁנִיָּה, יוֹצֵא וְאֵינוֹ יוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר; שְׁלִישִׁית, יוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר. \u0005הַגָּה: וְאִם רוֹצֶה שֶׁלֹּא לֵישֵׁב בִּמְקוֹמוֹ בְּשָׁבוּעַ שְׁלִישִׁית וּלְדַבֵּר, הָרְשׁוּת בְּיָדוֹ (הגמי\"י)\u0006. וְעַכְשָׁו נוֹהֲגִין שֶׁאֵין יוֹשְׁבִין בִּמְקוֹמָם כָּל שְׁלֹשִׁים; וְעַל אָבִיו וְאִמּוֹ כָּל י\"ב חֹדֶשׁ, וְאֵין לְמִנְהָג זֶה עִקָּר, מִכָּל מָקוֹם אֵין לְשַׁנּוֹת מִן הַמִּנְהָג, כִּי כָּל מָקוֹם לְפִי מִנְהָגוֹ; רְבִיעִית, הֲרֵי הוּא כִּשְׁאָר כָּל אָדָם. אֲפִלוּ לֹא שָׁלְמוּ שְׁלֹשָׁה שְׁבוּעוֹת, כְּגוֹן שֶׁמֵּת בְּאֶמְצַע שָׁבוּעַ, מִיָּד כְּשֶׁכָּלָה אוֹתוֹ שָׁבוּעַ וּשְׁנַיִם שֶׁאַחֲרָיו, חָשׁוּב שָׁבוּעַ הַבָּא רְבִיעִית.\nהָאָבֵל אֵינוֹ יוֹצֵא בַּחֹל לְבֵית הַכְּנֶסֶת, אֲבָל בְּשַׁבָּת יוֹצֵא. \u0005וְכֵן לְבֵית הַמִּדְרָשׁ (בֵּיתיוֹסֵף)\u0006. וְאָנוּ נוֹהֲגִים שֶׁבְּכָל יוֹם קְרִיאַת הַתּוֹרָה יוֹצֵא לב\"ה. \u0005הַגָּה: וּבִמְדִינוֹת אֵלּוּ נוֹהֲגִין שֶׁאֵין יוֹצֵא אֶלָּא בְּשַׁבָּת. וְאִם הָאָבֵל מוֹהֵל \u0010y3\u0011 אוֹ בַּעַל בְּרִית, לְאַחַר שְׁלֹשָׁה, מִתְפַּלֵּל בְּבֵיתוֹ, וּכְשֶׁמְּבִיאִין הַתִּינוֹק לָמוּל, הוֹלֵךְ הָאָבֵל לְבֵית הַכְּנֶסֶת (הַגָּהוֹת אֲשֵׁרִי)\u0006. אֲבָל, תּוֹךְ שְׁלֹשָׁה, לֹא יֵצֵא \u0010y4\u0011 אֶלָּא אִם כֵּן אֵין מוֹהֵל אַחֵר בָּעִיר \u0010y5\u0011 \u0005(אוֹר זָרוּעַ)\u0006 ; וְיֵשׁ מְקִלִּין אֲפִלּוּ תּוֹךְ שְׁלֹשָׁה, אֲפִלּוּ אִם יֵשׁ מוֹהֵל אַחֵר בָּעִיר \u0005(בֵּית יוֹסֵף)\u0006 ; וּמֻתָּר לוֹ לְתַקֵּן הַצִּפָּרְנַיִם וּלְגַלֵּחַ לְצֹרֶךְ הַמִּילָה, אֲבָל אִם יֵשׁ מוֹהֵל אַחֵר אָסוּר \u0005(סְבָרַת הָרַב דְּלֹא כְּאוֹר זָרוּעַ דְּמַתִּיר סְתָם)\u0006. וְכֵן כָּל דְּבַר מִצְוָה שֶׁאִי אֶפְשָׁר לַעֲשׂוֹת בְּלֹא הָאָבֵל, מֻתָּר לוֹ לָצֵאת לְקַיֵּם הַמִּצְוָה \u0005(סְבָרַת הָרַב וּבֵית יוֹסֵף)\u0006.\nהַנּוֹהֲגִים כְּשֶׁהֵם אֲבֵלִים שֶׁלֹּא לְשַׁנּוֹת מְקוֹמָם בְּבֵית הַכְּנֶסֶת בְּשַׁבָּת, יָפֶה הֵם עוֹשִׂים. \u0005הַגָּה: \u0010y6\u0011 וְיֵשׁ אוֹמְרִים שֶׁגַּם בְּשַׁבָּת יְשַׁנֶּה מְקוֹמוֹ (נִמּוּקֵי יוֹסֵף סוֹף פֶּרֶק הַמּוֹכֵר פֵּרוֹת)\u0006, וְכֵן הַמִּנְהָג פָּשׁוּט, וְאֵין לְשַׁנּוֹת הַמִּנְהָג.",["\u0003ולא לבה\"ק. \u0004אם מת לאחרים מת:","\u0003יוצא אפי' ביום ראשון. \u0004כצ\"ל:","\u0003אפילו לשמוע כו'. \u0004אף על גב דאבל חייב בכל המצות היינו במצות עשה שבגופו כגון ציצית ותפילין או למול את בנו אבל לילך לחופה או למילה לשמוע הברכות בשביל גמילות חסד אין לו לצאת מפתח ביתו. תשובת הרא\"ש:","\u0003או בעל ברית. \u0004פי' סנדק ולכן תוך שלשה לא יצא אבל אבי הבן פשיטא דאפילו תוך שלשה ימים יצא לכולי עלמא:","\u0003אא\"כ אין מוהל אחר בעיר. \u0004ואז מותר אפילו ביום ראשון:","\u0003ויש מקילין כו'. \u0004הוא הב\"י וק\"ק דהרי הבית יוסף כ' דלפי מנהגו שהאבל יוצא לב\"ה להתפלל בכל יום קריאת התורה כ\"ש שיצא כדי למול אפילו תוך שלשה ימים ראשונים ואפילו יש מוהל אחר בעיר עכ\"ל וא\"כ מאחר שכ' הרב דאנו נוהגין שאינו יוצא אלא בשבת למה כ' סברת היש מקילין כאן:","\u0003וי\"א שגם בשבת כו'. \u0004דס\"ל שאין זה דבר של פרהסיא שאין אבילות ניכר בזה כל כך שהרבה פעמים אדם מחליף מקומו אפילו אינו אבל עכ\"ל עט\"ז מהנ\"י ולמ\"ש לקמן ר\"ס ת' דאבלות הנוהג כל שלשים נוהג אפילו בשבת בלאו הכי ניחא:"],[]],["אֵין מִתְקַשִּׁין עַל הַמֵּת יוֹתֵר מִדַּאי; וְכָל הַמִּתְקַשֶּׁה עָלָיו יוֹתֵר מִדַּאי, עַל מֵת אַחֵר הוּא בּוֹכֶה; אֶלָא שְׁלֹשָׁה יָמִים לִבְכִי, שִׁבְעָה לְהֶסְפֵּד, שְׁלֹשִׁים לְתִסְפֹּרֶת וּלְגִהוּץ.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בִּשְׁאָר הָעָם. אֲבָל תַּלְמִידֵי חֲכָמִים, הַכֹּל לְפִי חָכְמָתָם; וְאֵין בּוֹכִים עֲלֵיהֶם יוֹתֵר מִל' יוֹם; וְאֵין מַסְפִּידִין עֲלֵיהֶם יוֹתֵר מִי\"ב חֹדֶשׁ; וְכֵן חָכָם שֶׁבָּא שְׁמוּעָתוֹ לְאַחַר י\"ב חֹדֶשׁ, \u0010y0\u0011 אֵין מַסְפִּידִין אוֹתוֹ.\nיוֹצְאִין לְבֵית הַקְבָרוֹת \u0010y1\u0011 וּפוֹקְדִים עַל הַמֵּתִים שְׁלֹשָׁה יָמִים, שֶׁמָּא עֲדַיִן הוּא חַי.\nכָּל שְׁלֹשָׁה יָמִים יִרְאֶה הָאָבֵל כְּאִלוּ חֶרֶב מֻנַּחַת לוֹ בֵּין כְּתֵפָיו; מִשִּׁלֹשָׁה וְעַד שִׁבְעָה, כְּאִלוּ זָקוּף כְּנֶגְדּוֹ בְּקֶרֶן זָוִית; מִשִּׁבְעָה וְעַד שְׁלֹשִׁים, כְּאִלוּ עוֹבֵר לְפָנָיו בַּשּׁוּק; וְכָל אוֹתָהּ הַשָּׁנָה הַדִּין מְתוּחָה כְּנֶגֶד אוֹתָהּ מִשְׁפָּחָה; וְאִם נוֹלָד בֵּן זָכָר בְּאוֹתָהּ מִשְׁפָּחָה, נִתְרַפֵּאת כָּל הַמִּשְׁפָּחָה.\nאֶחָד מֵהַחֲבוּרָה שֶׁמֵּת, תִּדְאַג כָּל הַחֲבוּרָה.\nכָּל מִי שֶׁאֵינוֹ מִתְאַבֵּל כְּמוֹ שֶׁצִּוּוּ חֲכָמִים, הֲרֵי זֶה אַכְזָרִי; אֶלָא יִפְחַד וְיִדְאַג וִיפַשְׁפֵּשׁ בְּמַעֲשָׂיו וְיַחֲזֹר בִּתְשׁוּבָה.",["\u0003אין מספידין אותו. \u0004אפילו ביום שמועה:","\u0003ופוקדים על המתים כו'. \u0004כתב הפרישה זה היה דוקא בימיהם שהיו מניחין את המת בכוכין () [אולי שייך זה בסי' זה סעיף ד' עמ\"ש ואם נולד בן זכר כו'. מראה כהן:] והיה אפשר לגלות את המת ולראותו וכתב עוד הדרישה בשם מהרש\"ל אדם שמת לו מת ובתוך שלשים נולד לו בן אין עושין שמחה ומשתה ביום המילה רוקח עכ\"ל וכמדומה שאין נוהגין כן:"],[]],["\u0010c0\u0011 כֵּיוָן שֶׁעָמְדוּ מְנַחֲמִים מֵאֵצֶל הָאָבֵל בְּיוֹם שְׁבִיעִי, מֻתָּר בְּכָל דְּבָרִים שֶׁאָסוּר בָּהֶם תּוֹךְ שִׁבְעָה, דְּמִקְצָת הַיּוֹם כְּכֻלוֹ, לֹא שְׁנָא מִקִצָת יוֹם שְׁבִיעִי לֹא שְׁנָא מִקְצָת יוֹם שְׁלֹשִׁים, \u0010y0\u0011 כֵּיוָן שֶׁהֵנֵץ הַחַמָּה בְּיוֹם שְׁלֹשִׁים, בָּטְלוּ מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים \u0005(רֹא\"שׁ וְרַבֵּנוּ יְרוּחָם)\u0006. \u0005הַגָּה: וּבִמְדִינוֹת אֵלּוּ שֶׁאֵין הַמְּנַחֲמִין רְגִילִין לָבוֹא בְּיוֹם ז', צָרִיךְ לְהַמְתִּין עַד שָׁעָה שֶׁרְגִילִין הַמְּנַחֲמִים לָבוֹא בִּשְׁאָר יָמִים, דְּהַיְנוּ לְאַחַר יְצִיאָה מִבֵּית הַכְּנֶסֶת שֶׁרְגִילִין לָבוֹא מְנַחֲמִין, כֵּן נִרְאֶה לִי, וּדְלֹא כְּמוֹ שֶׁרְגִילִין לְהַמְתִּין שָׁעָה עַל הַיּוֹם, דְּאֵין הַדָּבָר תָּלוּי רַק בַּעֲמִידַת הַמְּנַחֲמִין.\u0006 \u0005(וְכֵן מַשְׁמָע בַּאֲשֵׁרִי)\u0006.\nשָׁמַע שְׁמוּעָה רְחוֹקָה בַּלַיְלָה, כֵּיוָן דְּסָגֵי בְּשָׁעָה אַחַת, סַלְקָא, אֲפִלוּ בַּלַיְלָה.\nמִי שֶׁמֵּת אָבִיו אוֹ אִמּוֹ בְּרֹאשׁ חֹדֶשׁ נִיסָן, \u0010y1\u0011 \u0010c1\u0011 לֹא אַמְרִינָן בכ\"ט בַּאֲדָר שֶׁאַחֲרָיו מִקְצָת הַיּוֹם כְּכֻלוֹ, אֶלָא צָרִיךְ לִנְהֹג דְּבָרִים הָאֲסוּרִים בי\"ב חֹדֶשׁ עַד שֶׁיִּכָּנֵס רֹאשׁ חֹדֶשׁ נִיסָן. \u0005הַגָּה: \u0010y2\u0011 וְנָהֲגוּ \u0010c2\u0011 לְהוֹסִיף עוֹד הַיּוֹם שֶׁמֵּת בּוֹ הָאָב אוֹ הָאֵם לִנְהֹג בּוֹ דִּין י\"ב חֹדֶשׁ, וְנָכוֹן הוּא.\u0006",["\u0003כיון שהנץ כו'. \u0004דביום ל' שאין מנחמים מותר מיד כשהנץ החמה:","\u0003לא אמרינן כו'. \u0004כיון דתליא בחדשים:","\u0003ונהגו להוסיף. \u0004ואפי' חל אותו היום בשבת נוהג בו דין י\"ב חדש כן הוא בתרומת הדשן סי' רצ\"ב מיהו כשהשנה מעוברת דמותר ליכנס לבית המשתה לאחר י\"ב חדש כדלעיל סי' שצ\"א ס\"ק ב' אין נוהג דין י\"ב חודש ביום שמת בו אב או אם אע\"פ שאומר קדיש וברכו ומתענה בו ביום דמאחר דכבר הפסיק מאבלותו שוב אינו חוזר לאבלותו כ\"כ הב\"ח. ונראה דהיינו דוקא בשאר מיני אבילות אבל לאכול בסעודה של שמחה ומשתה אסור בכל שנה ביום שמת בו אב ואם וכדכ' הרב לקמן ס\"ס ת\"ב כ\"ש הכא:"],["\u0003כיון שעמדו כו'. \u0004עיין מה שכתבתי בטעם דין זה בסי' ת\"ב ויש בו נפקא מינה לדינא:","\u0003לא אמרינן בכ\"ט באדר כו'. \u0004הטעם בת\"ה שם סי' רצ\"ב דכל שתלוי במנין ימים אמרינן מקצת יום האחרון ככולו משא\"כ באבילות דתלוי בי\"ב חודש בכל דוכתי וא\"כ אם תאמר מקצת ככולו לא יצטרך להתאבל רק קצת מחודש האחרון וזה ודאי אינו:","\u0003להוסיף עוד יום שמת כו'. \u0004בת\"ה סי' רצ\"ב כתב הטעם משום דאמרינן קדיש וברכו ומתענין בו דיום מיתה הוא כו' ולכך נוהגין ענין אבילות באותו יום עכ\"ל. ולפי זה אפילו עד עולם כל יארציי\"ט שלו הוה הדין כן. ומו\"ח ז\"ל כ' דאם השנה מעוברת מותר ליכנס לבית המשתה לאחר י\"ב חודש כדלעיל סי' שצ\"א ואז אין נוהג דין י\"ב חודש ביום שמת בו אביו ואף על פי שמתענה בו כיון דכבר נכנס למשתה והפסיק אבילותו שוב אינו חוזר לאבילותו כו' עכ\"ל. ותמוהים דבריו דהא עד עולם צריך לנהוג כן ביום יארציי\"ט שלו וכ\"כ רמ\"א סי' ת\"ב סעיף י\"ב שלעולם אין לאכול בסעודה בלילה של יום היארציי\"ט וכתוב בלבוש אולי במקומו של רמ\"א נהגו כן כי ברוב המקומות שעברתי לא ראיתי נוהגים כן:"]],["אָבֵל שֶׁלֹּא נָהַג אֲבֵלוּתוֹ תּוֹךְ שִׁבְעָה, בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד, מַשְׁלִים אוֹתוֹ כָּל שְׁלֹשִׁים, \u0010c0\u0011 חוּץ מֵהַקְרִיעָה, שֶׁאִם לֹא קָרַע בִּשְׁעַת \u0010y0\u0011 חִמּוּם, אֵינוֹ קוֹרֵעַ, אֶלָא תּוֹךְ שִׁבְעָה, חוּץ מֵאָבִיו וְאִמּוֹ שֶׁקוֹרֵעַ \u0010y1\u0011 אֲפִלוּ לְאַחַר שִׁבְעָה.\nבַּמֶּה דְּבָרִים אֲמוּרִים, בְּשֶׁלֹּא נָהַג אֲבֵלוּת כְּלָל כָּל שִׁבְעָה; אֲבָל אִם זִלְזֵל בְּמִקְצָת הַיָּמִים, וְלֹא נָהַג בָּהֶם אֲבֵלוּת, כְּגוֹן מִי שֶׁאָמְרוּ לוֹ שֶׁמֵּת לוֹ מֵת בַּיּוֹם הָא', וְהָיָה בְּעִיר אַחֶרֶת וְלֹא נָהַג אֲבֵלוּת, וּבַיּוֹם הַשֵּׁנִי בָּא לְעִירוֹ וְנָהַג אֲבֵלוּת, אֵין צָרִיךְ לְהַשְׁלִים, וּמוֹנֶה שִׁבְעָה מִיּוֹם הָרִאשׁוֹן. \u0010c1\u0011\nקָטָן שֶׁמֵּת אָבִיו וְאִמּוֹ, \u0010y2\u0011 אֲפִלוּ הִגְדִּיל תּוֹךְ שִׁבְעָה, בָּטֵל מִמֶּנּוּ כָּל דִּין אֲבֵלוּת וְאֵינוֹ חַיָּב בּוֹ.",["\u0003אינו קורע כו'. \u0004כתב הב\"ח דהיכא שהיה אנוס כגון שהיה חולה ומסוכן שאי אפשר לקרוע או כגון שאין דעתו צלולה ומיושבת עליו וחזר לבוריו ולדעתו אחר שבעה שחשוב עכשיו כשעת חימום דל\"ד לשוגג או מזיד דעבר שעת חימום כיון שהיה בריא בשעה ששמע שמת לו מת וחייב באותה שעה אבל זה לא נתחמם אלא בשעה שחזר לבוריו ודעתו צלולה ומיושבת ובאות' שעה חל עליו חובת קריעה ע\"כ:","\u0003אפילו לאחר שבעה. \u0004כדלעיל סי' ש\"מ ס\"ח:","\u0003ואפילו הגדיל. \u0004והב\"ח פסק כדעת מהר\"ם דבהגדיל תוך ל' מונה ז' ול' משעה שהגדיל אבל אם הגדיל אחר ל' בטל ממנו גזירת ז' ול' ע\"ש מיהו מה שהקשה מלעיל סי' שמ\"א ס\"ב דמבדיל אחר שיקבר המת בקל יש לחלק ביניהם עיין שם:"],["\u0003חוץ מהקריעה כו'. \u0004לע\"ד נראה אם היה חולה ודעתו אינה מיושבת מחמת חולי לא אזלינן בזה בתר שעת חימום דהא אין יודע להתחמם אלא כשתבוא לו דעה צלולה כשאר כל אדם אז הוה חימום שלו אבל לא אכפת לן במה שהוא אינו יכול לקרוע מחמת שהוא מסוכן בחליו דסוף סוף ידע בחימום בעת ההיא ועל כן פטור אח\"כ מלקרוע כנ\"ל:","\u0003קטן שמת כו' ואפי' הגדיל כו'. \u0004דין זה הוא במחלוקת בין מהר\"ם להרא\"ש תלמידו בסוף מועד קטן דמהר\"ם סבירא ליה חייב להתאבל אחר שיגדיל שבעה ושלשים מיום שנעשה גדול והוה כשמע שמועה קרובה ברגל שמתאבל אחר הרגל ז' ול' ואע\"ג דהתם ימי הרגל עולין למנין שלשים היינו לפי שנהג בהם איסור גיהוץ ותספורת אבל כאן בקטנותו לא נהג כלום ואע\"פ שיש לחלק קצת בין שמע ברגל לנדון זה דהתם גברא בר חיובא הוא אלא דיומא הוא דקגרים אבל הכא גברא לאו בר חיובא הוא כלל וא\"כ נימא כיון דבשעת מיתה לא היה ראוי להתאבל יפטור עולמית הא ליתא דאין דיחוי אצל מצות כדאיתא פרק כיסוי הדם כו' והרא\"ש חולק ואומר תופס אני אותה סברא שיש לחלק בין היכא דגברא בר חיובא הוא ויומא גרים לקטן דבשעה שהיה לו להתאבל פטור מחמת קטנות פקע מיניה חיוב אבילות לעולם ודמי להא דאמר בפרק מי שהיה טמא קטן שהגדיל בין ב' פסחים דסבר רבי נתן שני תשלומין לראשון וכל שאינו זקוק לראשון אינו זקוק לשני וכן נמי הא דיושבים על שמועה קרובה ז' ול' אינה מצוה בפני עצמה אלא תשלום לאבלות שהיה לו לעשות מיד אחר הקבורה כשידע וכשלא ידע תקנו שיש לו תשלומין כל שלשים יום והיכא דידע ולא נתחייב לא שייך ביה תשלומין מידי דהוה אחיגר ביום ראשון ונתפשט ביום שני של חג דלא שייך ביה תשלומין כו' ע\"כ. וכ' רבינו ירוחם שיש לפסוק כמהר\"ם שהוא רבו של הרא\"ש והב\"י הכריע כהרא\"ש דהלכה כדברי המיקל באבל וכן פסק כאן בשו\"ע דפטור ובימי חרפי בא מעשה זה לידי בקטן שהגדיל תוך ז' ועיינתי בו והוקשה לי בדברי הרא\"ש שכתב דאבלות הוה בו משום תשלומין דבזה אין שייך תשלומין אלא כל יום מן הז' הוא מצוה בפ\"ע דהא פסקינן כאן סעיף ב' אם זלזל במקצת ז' הימים דא\"צ להשלים ולמה כתבו הטור והשו\"ע אפי' הגדיל בתוך שבעה. והרציתי הדברים הללו לפני מו\"ח ז\"ל והשיב לי שבלא\"ה סותרים דברי השלחן ערוך זה את זה דבפרק מי שמתו יש ג\"כ פלוגתא בין הרא\"ש ורבינו יהודה ובין מהר\"ם לענין הבדלה דרבינו יהודה היה אונן במ\"ש ולא הבדיל ולמחר ביום א' אחר הקבורה לא רצה ג\"כ להבדיל מאחר שהיה פטור בשעת חיוב הבדלה ודומה לחיגר שנתפשט ביום שני שזכרתי לעיל והואיל ונדחה ידחה ומהר\"ם חולק שם וס\"ל ביום המחרת חייב להבדיל דהא קי\"ל מי שלא הבדיל במ\"ש מבדיל והולך כל השבת כולה והרא\"ש כ' שם שהוא הסכים לרבינו יהודה דהא דאמרינן מי שלא הבדיל במ\"ש כו' היינו כשלא היה לו יין במ\"ש או אונס אחר שלא היה יכול להבדיל אבל אונן דבשעה שחל עליו חיוב הבדלה היה פטור לגמרי תו לא מתחייב ודמיא לחיגר דלעיל ע\"כ והנה לעיל סי' שמ\"א פסק השו\"ע שחייב להבדיל והיינו כמהר\"ם וכאן פסק דפטור כשהגדיל והיינו כהרא\"ש דטעם אחד לשתי הפלוגתות ואין ישוב לזה וע\"כ פסק הוא בכל מקום כמהר\"ם שהוא רבו של הרא\"ש וגם כאן חייב בז' ושלשים דלא כפסק הש\"ע וכן קבע הוא בחיבורו על היורה דעה כאן ואני בעניי תמהתי ונפלאתי על פסק זה שנחלקו בו אבות העולם מהר\"ם והרא\"ש ומתירא אני להכניס ראשי החלש בין הרים גדולים מאורי ישראל ומ\"מ עצור במלין לא אוכל כי תלמוד ערוך הוא פסק זה לפע\"ד שלא כדברי מהר\"ם ולא כדברי הרא\"ש במחילה מכבודם וע\"פ זה יתבאר שפסקי הש\"ע הם דברי אלהים חיים:\n\u0003אמרינן \u0004בפרק נגמר הדין (סנהדרין דף מ\"ז) בהא דאמרינן לא היו קוברין אותן הרוגי בית דין בקברות אבותם ואי ס\"ד כיון דאיקטל הוי ליה כפרה ליקברו ומשני מיתה וקבורה בעינן מתיב רב אדא לא היו מתאבלין על הרוגי ב\"ד אלא אוננין ואי ס\"ד כיון דאיקבר הוה ליה כפרה ליתאבלו ומשני בעינן נמי עיכול בשר. רב אשי אמר לעולם לא בעינן עיכול בשר אלא צערא דחיבוט הקבר פורתא וטעמא דלא היו מתאבלין משום דאבילות מסתימת הגולל חיילא כפרה מאימת הויא מכי חזי צערא דקברא פורתא הלכך הואיל ואידחו ידחו פירש\"י הואיל ונדחו שלא נראו להתאבל בשעת התחלת האבלות ידחו אף לאחר מכאן ואע\"ג דגבי קובר את מתו ברגל תנן מונה ז' ימים אחר הרגל ולא אמרינן הואיל ונדחו ידחו התם לא אידחו לגמרי שהרי אמרי' כל שהוא משום עיסקי רבים אין הרגל מפסיקן ורבים באים לנחמו עכ\"ל:\n\u0003והנה \u0004אתה רואה ק\"ו כאן דמה כאן בפרק נגמר הדין דאחר סתימת הגולל לא היה שום אבילות בעולם כיון דהמת לא חזי לכך דלא הוי ליה כפרה עדיין והיה מן הראוי לומר דאחר שיהיה קצת בקבר ויכופר אז יתחיל אבילות שלו כדרך שמתחיל בשאר מתים אחר סתימת הגולל אפ\"ה לא אמרינן כן אלא אמרינן הואיל ואידחי בשעה שמתחיל לשאר העולם לא יתאבלו עליו כלל אח\"כ ק\"ו כאן שהיה אבילות בעולם והמתאבל לא חל עליו החיוב פשיטא הואיל ואידחי בשעת החיוב ידחה לעולם ופשוט דהלכה כרב אשי דבתרא הוא ותו אני אומר דגם תירוץ הראשון בגמ' אינו חולק על האי סברא דאידחי אידחי דאל\"כ לדידיה נמי קשה יתאבלו על הרוגי ב\"ד דלאחר העיכול דאז יש להם בודאי כפרה אלא פשיטא דבזה אמרינן אידחי אידחי אלא דפליגי על רב אשי במה שאמר שיש להם כפרה בזמן קצר מכי חזו פורתא צערא דקברא בזה פליגי וס\"ל דאין הכפרה ממהרת כ\"כ אבל אי היתה ממהרת ודאי גם הם סבירא להו אידחי אידחי וכן מבואר שם בסוגיא לעיל מיניה דכ\"ע אית להו כיון שאידחו אידחו לפי המסקנא גם הב\"י בסי' שמ\"ה כ' ואסיקנא לענין הרוגי ב\"ד בפרק נגמר הדין דהוי ליה כפרה בקטלא וקבורה אלא היינו טעמא דאין מתאבלין עליהם דאבילות מתחיל מסתימת הגולל כו' והיינו כתירוץ רב אשי אלא דבנוסח דברי בית יוסף יש ט\"ס שכתב הרוגי מלכות וצ\"ל הרוגי ב\"ד א\"כ מבואר דלא כמהר\"ם שחייב לקטן והגדיל וגם דלא כהרא\"ש דאילו להרא\"ש הפטור משום דהוה תשלומין וכל שפטור בשעת החיוב אין עליו תשלומין משמע דאילו במקום שאין תשלומין הוה חיוב ומודה למהר\"ם והרי כאן בפרק נגמר הדין שאין שם תשלומין דהא לא היה ראוי לאבילות מתחלה ואפ\"ה אמרינן דפטור אח\"כ אלא דבר ברור הוא דהפטור לאו משום דלא שייך ביה תשלומין נגעו בו אלא משום שחכמים הטילו עליו אבילות מן שעה ראשונה שהמרירות עליו ביותר דהיינו משיסתום הגולל ומן אותה שעה הוא מתאבל והולך כפי דינו אבל כל שנפטר בשעת עיקר המרירות דהיינו אחר סתימת הגולל אין עליו שום חיוב אחר כך ומשום הכי הרוגי ב\"ד וכן קטן והגדיל פטורים לגמרי כיון שהיו פטורים בשעת עיקר המרירות ויפה מכוון לזה פי' רש\"י שהעתקתי שלא דמי לקובר מת ברגל שחייב בז' ול' אחר הרגל ששם בשעת עיקר המרירות לא נפטר שהרי יש עליו קצת אבילות גם ברגל ואין כאן דמיון להבדלה שחייב לעשות ביום המחרת אע\"פ שבליל מ\"ש היה פטור כמ\"ש השלחן ערוך בסי' שמ\"א דשם הוא עיקר זמן ההבדלה מתחלה כך שימשוך זמנה כל השבת או עד ליל ד' ולא אמרינן דאם לא הבדיל במ\"ש הוה ההבדלה שאח\"כ תשלומין על מ\"ש אלא עדיין זמנה ממש וזה דומה לתפלת ערבית וק\"ש שאחז\"ל במסכת ברכות שזמנה קודם אכילה וכל העובר חייב מיתה ואעפ\"כ זמנה כל הלילה כמ\"ש בפי' שזמנה כל הלילה והכי נמי ממש כן הוא בהבדלה וזהו נכלל במה שאמרו מי שלא הבדיל במ\"ש מבדיל והולך כל השבת כולה. וכן לא קשה ממה שמצינו בסוכה פרק הישן (סוכה דף כ\"ז) בקטן שנתגדל בימי הסוכות דחייב לעשות סוכה התם נמי זמנה כן הוא כל ז' הימים ואין בזה משום תשלומין על מה שלא ישב בסוכה בשעת קטנותו כדאמרינן במתני' שם שאין תשלומין למי שלא אכל בסוכה משא\"כ באבילות שהעיקר תלוי בהתחלת האבילות בשעת עיקר המרירות וכל שלא התחיל לא יגמור ע\"כ נראה להלכה ולמעשה כפסק הרא\"ש לענין אבילות דפטור כאן ולא מטעמיה אלא מטעם שאמרנו. ולענין הבדלה כדעת מהר\"ם וכפסק הש\"ע בב' המקומות והם צודקים וברורים ומקום הניחו לנו רבותינו אבות העולם לזכות בו בסייעתא דשמיא:"]],["\u0010y0\u0011 מִתְאַבְּלִין עַל פִּי עֵד אֶחָד, וְעֵד מִפִּי עֵד \u0010c0\u0011 וְעוֹבֵד כּוֹכָבִים מֵסִיחַ לְפִי תֻּמּוֹ.\nשְׁנַיִם אוֹמְרִים: מֵת, וּשְׁנַיִם אוֹמְרִים: לֹא מֵת, \u0010y1\u0011 \u0010c1\u0011 אֵינוֹ מִתְאַבֵּל.",["\u0003מתאבלים כו'. \u0004כתב הרמב\"ן זה הכלל כל עדות שמשיאים האשה על פיה הקרובים מתאבלים וכ\"פ הב\"ח ועיין בא\"ע סי' י\"ז נתבאר עדות שמשיאין האשה על פיה וכ' עוד הב\"ח היכא שכתבו לאחד שמת קרובו ואיכא ספק אם הוא תוך ל' חייב להתאבל דכל כמה דמצינן ליה לאוקמיה אחזקתיה מוקמינן ואמרינן השתא מקרוב מת וכן הוא בתשובת ן' לב מיהו היכא שהוא כתב יד של חכם אמרי' מסתמא לאחר ל' הוא דאם איתא דאפשר היה שיגיע הכתב לידו תוך ל' לא היה כותב בסתם אלא היה מבאר כ\"כ הב\"ח וכן כ' בתשו' ר\"מ מינץ סי' צ\"ה דצריך להתאבל מטעם דמוקמינן אחזקתיה וכ' דאם אירע שהורו דאין להתאבל מספק ואח\"כ נודע לו למפרע שמת תוך ל' צ\"ע אם יחזור ויתאבל או לא ע\"ש ולפעד\"נ דצריך להתאבל בכה\"ג וע\"ל ר\"ס שצ\"ו ודו\"ק:","\u0003אינו מתאבל. \u0004דמוקמינן ליה אחזקתיה דחי וע\"ל סי' של\"ט ס\"ב דבאמרו לו ראינו קרובך גוסס היום ג' ימים צריך להתאבל עליו:"],["\u0003ועובד כוכבים מסיח לפי תומו. \u0004כ' רש\"ל וז\"ל עובדת כוכבים שספרה לפי תומה לראובן שמתה אחותו פסק ראבי\"ה שמתאבל על פיה דנאמנת להחמיר וא\"מ פסק דהילכתא כדברי המיקל באבל ועובד כוכבים אינו נאמן להחמיר במילי דאבילות וה\"ר ישעיה אומר דאין עובד כוכבים נאמן במסיח לפי תומו אלא לעדות אשה או על פירות של עצמו מעיד דשל ערלה הן אבל בכל עדיות דעלמא אין עובד כוכבים נאמן במסיח לפי תומו בין להקל בין להחמיר. ע\"כ תשובת אור זרוע עכ\"ל:","\u0003אינו מתאבל. \u0004הטעם דכיון דספיקא היא אזלינן בה להקל כ' מהר\"ם מינץ סי' צ\"ה מי ששמע שמת לו מת ואינו יודע אם תוך ל' או לאחר ל' יום אם חייב להתאבל והאריך בזה וזה כלל דבריו דיש סברא לומר כיון דהקילו בענין אבילות כיון דספיקא דרבנן הוא והביא בשם הלכות שמחות דמהר\"ם דאין להחמיר באבילות בספק דחומרא דאתי לידי קולא היא שנוהג אבילות בשבת בדברים של צינעא ומבטל תלמוד תורה כל שבעה ימים אך מטעם חזקה נ\"ל להחמיר דתנן בפ' כל הגט המביא גט והניחו זקן או חולה נותנו לה בחזקת שהוא קיים כו' והביא הרבה דינים שהולכי' בתר חזקה ע\"כ י\"ל העמד המת על חזקתו והשתא הוא דמת ולא החליט הפסק ומסיק לבסוף דאין לו ראיה ברורה לא לחיוב ולא לפטור) ובתשו' מהר\"י ן' לב פסק לחיוב מכח ההיא דפ' כל הגט שזכרתי וכן פסק מו\"ח ז\"ל כאן ולפענ\"ד לא נראה כן מכח ראיות ברורות כאשר אבאר בסייעתא דשמיא:\n\u0003ראשונה \u0004דאמרינן במשנה בפסחים פרק האשה (ד' צ\"א) האונן והמפקח את הגל (מעל האדם ואין יודע אם ימצאנו חי או מת כו') שוחטין עליו את הפסח (מפני שעודנו בחזקת טהרה כו' לפיכך אם אירע בהם פסול פטורים מלעשות פסח שני כיון שבשעת זריקה ראוין הם) חוץ מן המפקח בגל ונמצא המת תחתיו שחייב לעשות פסח שני שהוא טמא מתחילתו פי' קודם שחיטה שהרי האהיל על הטומאה משעה שהתחיל לפקח וכתבו התוס' תימא לר\"י מפקח הגל נמי נימא חי היה כשהתחיל לפקח. וי\"ל כיון שנמצא מת אית לן למימר שמתחילתו היה מת שכל הטומאות כשעת מציאתן עכ\"ל הרי לפניך דלא אמרינן אוקים אותו בחזקת חי והשתא הוא דמת וא\"ל דלא ילפינן איסור מטומאה וכן שום חיוב או פטור דהא במתניתין ההיא ילפינן שחייב לעשות פסח שני ולא חשבינן ליה לספק דילמא מייתי חולין בעזרה אלא דבר ודאי חשבינן ליה דמת מעיקרא ויליף מטומאה הכי נמי נליף שפטור מאבילות דנימא כיון דהשתא מת מעיקרא מת חשבינן ליה וא\"ל דשאני במפקח הגל דתכף שנפל עליו הגל הזה סבר דודאי מת זה אינו דהא כתבו התוספות שכל הטומאות כשעת מציאתן משמע בכל גווני אמרינן כן ותו דודאי אינו הכרח שמת תיכף דשפיר מצינו לומר שהיה עדיין חי דהא תנא סתמא אמר המפקח את הגל דהיינו אפי' תיכף שנפל עליו:\n\u0003שנית \u0004מפרק המדיר (כתובות דף ע\"ז) אמר רב יהודא אמר שמואל המחליף פרה בחמור ומשך בעל החמור את הפרה ולא הספיק בעל הפרה למשוך את החמור עד שמת החמור על בעל החמור להביא ראיה שהיה חמורו קיים בשעת משיכת הפרה וקשה למה יביא ראיה לזה אמאי לא נוקים אותו בחזקת שהיה חי תחלה והשתא הוא דמת וכן במסקנא שם דאמר רמי בר יחזקאל על בעל הפרה להביא ראיה שמת תחלה כיון שהספק נולד ברשותו פי' שבעל החמור עשה כבר משיכה בפרה אמאי הוצרך לומר בשביל שהספק נולד ברשותו תיפוק ליה דמוקמינן לה בחזקת חי כההיא דפרק כל הגט דלעיל מ\"ש חזקת אדם חי או בהמה חיה:\n\u0003שלישית \u0004ממה שכתב הטור והשו\"ע באבן עזר סימן י\"ז מצאו הרוג ומכירין אותו בטביעת עין ואין יודעין מתי נהרג י\"א שתולין שנהרג תוך ג' ימים ומעידין עליו ויש אוסרין ומבואר בבית יוסף בשם הרשב\"א דאזלינן לחומרא דשמא כבר נהרג וקשה אמאי לא נימא דהשתא הוא דנהרג דנוקמיניה בחזקת חי כמעיקרא עד השתא כההיא דפרק כל הגט. וע\"כ לתרץ הנהו תלתא קושיות אלימתות דע\"כ לא אמרינן פרק כל הגט דמוקמינן ליה בחזקת חי אלא כל שלא ידענו עדיין שמת משא\"כ בהנך תלת מילי דהשתא ודאי מת שפיר אמרינן דכבר היה מת וכמשמעות לשון התוספות בפסחים שזכרנו שכתבו כיון שמצאוהו מת אית לן לומר שמתחלתו היה מת. ואין להקשות מ\"ש משאר חזקות שאמרינן חזקה אפי' בכה\"ג כגון במקוה דפרכינן בריש נדה דנימא השתא הוא דחסר וכן בסימן פ\"א לעיל בגבינות שנעשו מחלב בהמה ונמצאת טרפה דאמרינן השתא הוא דנטרפה וכן בהרבה דוכתי נלע\"ד לומר דשאני במיתה דכל חי עומד למות והוא מועד לכך בלי ספק ע\"כ שפיר אמרינן דודאי כל זמן שאינו מבורר שמת אמרינן עדיין חי הוא אבל כשמבורר שמת אזלא החזקה לענין שנאמר דהשתא הוא שמת דאדרבה אמרינן שמעיקרא היה מת כיון שעמד לכך וסברא זאת שאמרנו שעומד לכך מצינו אותו בטור ח\"מ סי' ס\"ה וז\"ל וא\"ל העמד השטר אחזקתו שלא נפרע לפי שהשטר עומד ליפרע עכ\"ל ש\"מ שסברא זאת מגרע כח החזקה הכי נמי נימא כן לענין חזקה זאת דהשתא הוא דמת שאין לך לומר כן וכיון שזכינו לזה נימא גם כאן דאין חייב להתאבל מכח ספק מחמת החזקה דאין לך לומר השתא הוא דמת דוקא ועל דברים אלו סמכתי עצמי ופסקתי הלכה למעשה כן שאין חיוב אבילות על זה הספק בפרט אחר היסוד הגדול שהולכין באבל להקל טפי מבשאר מילי דרבנן ואין מן הראוי להחמיר דאתי לידי קולא לחלל שבת כמו שזכרנו בתשובה דלעיל: עוד כתב מהר\"ם מינץ בתשוב' דלעיל וז\"ל ויען שאין לי ראיה ברורה לא לכאן ולא לכאן הגם אם יש מורה דפסק דאין להתאבל בכה\"ג דספק אם תוך ל' הוא אבאר איך דינה אם לא יוודע לו בבירור עד לאחר ל' ואח\"כ יוודע לו למפרע דהוה תוך שלשים כשבאה לו השמועה אם חשבינן אותה כשמועה רחוקה או אמרינן כיון דהיה לו ידיעה תוך שלשים אע\"ג דעבר שלשים צריך להתאבל ע\"כ ורצה שם ללמוד דין זה ממ\"ש בשמחות דמהר\"ם בתאומים שמת אחד מהם תוך שלשים והשני חי עד לאחר שלשים דמסתפק שם להר\"ם אם יתאבל על המת דאי נימא דהוה ג\"כ בר קיימא דאין אשה מתעברת וחוזרת ומתעברת נפלים לפי' ר\"ח או דילמא דהוה כשמועה רחוקה כיון דהשתא כבר עברו שלשים יום או דילמא לא דמי לשמועה רחוקה דהתם לא ידע כלל שמת אבל הכא דידע מיתלא תלא עד שיודע ספיקא כו' וצידד מהר\"ם דפטור דהוה כמו שמועה רחוקה ועדיין נסתפק מהר\"ם מינץ שם דשמא בזה לא הוה כשמועה רחוקה דבכל עת ראוי לחול האבילות אם ישמע עדיין אם הוא תוך ל' משא\"כ בההיא דתאומים שזכרנו שא\"א לו להוודע תוך ל' אם הראשון נפל או בר קיימא ומסיק דצ\"ע אם חייב להתאבל בזה ע\"כ ולעד\"נ דאין כאן אבילות כיון שעכ\"פ השתא עברו ל' יום מיום המיתה דלא גרע ממי ששגג או הזיד ולא נהג כלל אבילות עד לאחר ל' יום דודאי אח\"כ אין עליו אבילות כמ\"ש כאן בסעיף א' דמי ששגג או הזיד משלים כל ל' משמע אחר ל' אין שום שייכות תשלומין כנלע\"ד. ושוב ראיתי בתשובת מוהר\"ם מלובלין שהביא דברי הש\"ע האלו כהוייתן ופסק כן והוא אגב חורפיה לא עיין כל הצורך בזה:"]],["אֲבֵלוּת יוֹם רִאשׁוֹן, אִם הוּא \u0010c0\u0011 יוֹם מִיתָה וּקְבוּרָה, הָוֵי דְּאוֹרַיְתָא; וּשְׁאָר הַיָּמִים, מִדְּרַבָּנָן. בַּמֶּה דְּבָרִים אֲמוּרִים, \u0010y0\u0011 בְּשִׁבְעָה מֵתִים הַמְּפֹרָשִׁים בַּתּוֹרָה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, אֲבָל אוֹתָם שֶׁהוֹסִיפוּ עֲלֵיהֶם כִּדְאִיתָא בְּסִימָן שע\"ד, אֲפִלוּ בְּיוֹם רִאשׁוֹן הֵם מִדְּרַבָּנָן. \u0010y1\u0011 \u0010c1\u0011 וְיֵשׁ אוֹמְרִים שֶׁאַף אֲבֵלוּת יוֹם רִאשׁוֹן דְּמִיתָה וּקְבוּרָה הָוֵי דְּרַבָּנָן בְּכָל הַמֵּתִים.",["\u0003בז' מתים. \u0004שהם אביו ואמו בנו ובתו אחיו ואחותו בתולה ואשתו נשואה:","\u0003וי\"א כו'. \u0004והכי קי\"ל כדלקמן סימן שצ\"ט סי\"ג:"],["\u0003יום מיתה וקבורה. \u0004לאפוקי מת ביום א' ונקבר למחר או שמועה קרובה:","\u0003וי\"א שאף אבילות כו'. \u0004בטור סיים אלא אנינות לחוד ביום ראשון דהוה דאורייתא ואנינות לחוד ואבילות לחוד האסור בזה מותר בזה ואונן אינו אסור ביום ראשון מן התורה אלא באכילת קדשים ומעשר שני ועוד החמירו בו חכמים בדברים המפורשים בפרק מי שמתו עכ\"ל פי' אונן הוה ביום המיתה אפילו אחר שנקבר לענין אכילת קדשים ומעשר שני כדאיתא בפרק טבול יום (זבחים דף ק') וחכמים החמירו בו קודם שנקבר לענין אכילת בשר ויין ותשמיש ופטור מכל המצות והיינו מטעם שמתו מוטל לפניו לקברו ואז מותר בנעילת סנדל ורחיצה וגילוח וכל מה שאסור משום אבילות דלעיל עד שיסתום הגולל ואז מותר בבשר ויין וחייב בכל המצות זולת תפילין ביום ראשון ומ\"ש הטור האסור בזה מותר בזה לאו כללא הוא דהא תשמיש אסור בשניהם אלא על שאר החילוקים שזכרנו אמר כן:"]],["הַקוֹבֵר מֵתוֹ קֹדֶם הָרֶגֶל, בְּעִנְיָן שֶׁחָל עָלָיו אֲבֵלוּת, וְנָהַג בּוֹ \u0010y0\u0011 \u0010c0\u0011 אֲפִלוּ שָׁעָה אַחַת קֹדֶם הָרֶגֶל, מַפְסִיק הָאֲבֵלוּת וּמְבַטֵּל מִמֶּנּוּ גְזֵרַת שִׁבְעָה \u0010y1\u0011 וִימֵי הָרֶגֶל עוֹלִים לוֹ לִמִנְיַן שְׁלֹשִׁים, הֲרֵי שִׁבְעָה לִפְנֵי הָרֶגֶל, וִימֵי הָרֶגֶל, וּמַשְׁלִים עֲלֵיהֶם הַשְּׁלֹשִׁים. וְדַוְקָא שֶׁנָּהַג אֲבֵלוּת בְּאוֹתָהּ שָׁעָה, אֲפִלוּ לֹא נָהַג אֶלָא דְּבָרִים שֶׁבְּצִנְעָא, כְּגוֹן שֶׁשָּׁמַע שְׁמוּעָה קְרוֹבָה בְּיוֹם שַׁבָּת שֶׁחָל לִהְיוֹת בְּעֶרֶב הָרֶגֶל, שֶׁאַף עַל פִּי שֶׁאֵינוֹ נוֹהֵג אֶלָא דְּבָרִים שֶׁבְּצִנְעָא, הָרֶגֶל מַפְסִיק. אָבֵל אִם שָׁגַג אוֹ הֵזִיד וְלֹא נָהַג אֲבֵלוּת, \u0005אוֹ\u0006 שֶׁהָיָה קָרוֹב לַחֲשֵׁכָה וְלֹא הָיָה יָכוֹל לִנְהֹג, אֵין הָרֶגֶל מְבַטֵּל הָאֲבֵלוּת; וְכָל שֶׁכֵּן אִם לֹא יָדַע בְּמִיתַת הַמֵּת קֹדֶם הָרֶגֶל, שֶׁאֵין הָרֶגֶל מְבַטְּלוֹ, \u0010y2\u0011 אֶלָא נוֹהֵג בָּרֶגֶל דְּבָרִים שֶׁבְּצִנְעָא, וּמוֹנֶה שִׁבְעָה אַחַר הָרֶגֶל, וּבְאוֹתָהּ הַשִּׁבְעָה מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים, וַעֲבָדָיו וְשִׁפְחוֹתָיו עוֹשִׂים בְּצִנְעָה בְּתוֹךְ בֵּיתוֹ, דְּכֵיוָן דִּכְבָר נִתְבַּטֵּל בְּשִׁבְעַת יְמֵי הָרֶגֶל מִמְּלָאכָה, אַף עַל פִּי שֶׁלֹּא נִתְבַּטֵּל מֵחֲמַת הָאֵבֶל אֶלָא מֵחֲמַת הָרֶגֶל, סוֹף סוֹף נָהַג בְּדִין אֲבֵלוּת בְּעִנְיַן מְלָאכָה, הִלְכָּךְ אֵין לְהַחְמִיר בּוֹ כְּמוֹ בִּשְׁאָר אֲבֵלוּת וּמְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים. וְכָל יְמֵי הָרֶגֶל רַבִּים מִתְעַסְקִים בּוֹ לְנַחֲמוֹ, \u0010y3\u0011 הִלְכָּךְ אֵין מִתְעַסְקִין בּוֹ לְנַחֲמוֹ אַחַר הָרֶגֶל. וְרֶגֶל עוֹלֶה לְמִנְיַן שְׁלֹשִׁים, שֶׁהֲרֵי דִּין שְׁלֹשִׁים דְּהַיְנוּ גִהוּץ וְתִסְפֹּרֶת נוֹהֲגִים בָּרֶגֶל, \u0010c1\u0011 וְלֹא מִתּוֹרַת רֶגֶל בִּלְבַד אָסוּר בָּהֶם, אֶלָא אַף מִתּוֹרַת אֵבֶל, שֶׁהֲרֵי מִתּוֹרַת הָרֶגֶל מֻתָּר לִלְבֹּשׁ כֵּלִים מְגֹהֲצִים חֲדָשִׁים וּלְבָנִים, \u0010y4\u0011 וְנוֹטֵל צִפָּרְנָיו בְּמִסְפָּרַיִם וְשָׂמֵחַ שִׂמְחַת מְרֵעוּת, וְהַבָּא מִמְּדִינַת הַיָּם וּמִבֵּית הַשִּׁבְיָה וְהַשְּׁאָר שֶׁמָּנוּ חֲכָמִים, מֻתָּרִין לְסַפֵּר וּלְכַבֵּס, וּמִדִּין אֲבֵלוּת אָסוּר בְּכֻלָם כְּמוֹ בַּחֹל.\nהַקוֹבֵר מֵתוֹ \u0010c2\u0011 בָּרֶגֶל \u0010y5\u0011 בְּחֹל הַמּוֹעֵד, נֹהַג דִּין אֲנִינוּת כָּל זְמַן שֶׁלֹּא נִקְבַּר; וּלְאַחַר שֶׁנִּקְבַּר, נוֹהֵג דְּבָרִים שֶׁבְּצִנְעָא \u0005וּמִכָּל מָקוֹם מֻתָּר לְיַחֵד עִם אִשְׁתּוֹ (בֵּית יוֹסֵף בְּשֵׁם הָרַאֲבַ\"ד וְהָרֹא\"שׁ)\u0006 וְעַיֵּן לִעֵיל סִימָן שפ\"ג וּבְא\"ח סִימָן תקמ\"ח, וְהָרֶגֶל עוֹלֶה לְמִנְיַן שְׁלֹשִׁים, שֶׁמַּשְׁלִים עָלָיו שְׁלֹשִׁים; אֲפִלוּ קְבָרוֹ בְּחַג הַסֻכּוֹת, \u0010y6\u0011 \u0010c3\u0011 לֹא אַמְרִינָן דִּשְׁמִינִי עֲצֶרֶת מְבַטֵּל, וּמִתְעַסְקִים בָּרֶגֶל לְנַחֲמוֹ. \u0005הַגָּה: וְכָל מְלָאכָה הַמֻּתֶּרֶת לַעֲשׂוֹת לוֹ בַּמּוֹעֵד בְּדָבָר הָאָבֵד, מֻתָּר לַעֲשׂוֹת בְּעַצְמוֹ; וְאִם אֵין דָּבָר הָאָבֵד, נַעֲשֵׂית עַל יְדֵי אֲחֵרִים בְּבָתֵּיהֶם, וַעֲבָדָיו וְשִׁפְחוֹתָיו עוֹשִׂין בְּצִנְעָא תּוֹךְ בֵּיתוֹ (בֵּית יוֹסֵף בְּשֵׁם רַבֵּנוּ יְרוּחָם)\u0006, וּלְאַחַר הָרֶגֶל מַתְחִיל לִמְנוֹת שִׁבְעָה, וְלִכְשֶׁיִּכְלוּ שִׁבְעָה לְמִיתַת הַמֵּת אַף עַל פִּי שֶׁעֲדַיִן לֹא כָּלוּ שִׁבְעַת יְמֵי הָאֲבֵלוּת, מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים בְּבָתֵּיהֶם, וַעֲבָדָיו עוֹשִׂין לוֹ בְּצִנְעָא בְּתוֹךְ בֵּיתוֹ; וְאֵין רַבִּים מִתְעַסְקִים בּוֹ לְנַחֲמוֹ אַחַר הָרֶגֶל מִנְיַן הַיָּמִים שֶׁנִּחֲמוּהוּ בָּרֶגֶל, אֲבָל מַרְאִים לוֹ פָּנִים, כְּגוֹן אִם קְבָרוֹ בִּשְׁלֹשָׁה יָמִים הָאַחֲרוֹנִים שֶׁל רֶגֶל, מְלַאכְתּוֹ נַעֲשֵׂית עַל יְדֵי אֲחֵרִים בִּשְׁלֹשָׁה יָמִים אַחֲרוֹנִים שֶׁל אֵבֶל, \u0010y7\u0011 וּבִמְקוֹמוֹת שֶׁעוֹשִׂים שְׁנֵי יָמִים, מוֹנֶה הַשִּׁבְעָה מִיּוֹם טוֹב שֵׁנִי הָאַחֲרוֹן, הוֹאִיל וּמִדִּבְרֵיהֶם הוּא עוֹלֶה מֵהַמִּנְיָן, וּמוֹנֶה מֵאַחֲרָיו שִׁשָּׁה יָמִים בִּלְבַד.\nאִם קָבַר אֶת מֵתוֹ שִׁבְעָה יָמִים קֹדֶם הָרֶגֶל, וְנָהַג בָּהֶם גְזֵרַת שִׁבְעָה, הָרֶגֶל מְבַטֵּל מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים, אֲפִלוּ חָל יוֹם שְׁבִיעִי בְּעֶרֶב הָרֶגֶל, דְּמִקְצָת הַיּוֹם כְּכֻלוֹ וְעוֹלֶה לְכָאן וּלְכָאן, וּמֻתָּר לְכַבֵּס \u0010y8\u0011 וְלִרְחֹץ וּלְסַפֵּר בְּעֶרֶב הָרֶגֶל. \u0005הַגָּה: \u0010y9\u0011 סָמוּךְ לַחֲשֵׁכָה (טוּר)\u0006. \u0010y10\u0011 וּבְעֶרֶב פֶּסַח מֻתָּר בַּכֹּל אַחַר חֲצוֹת, דְּהַיְנוּ מִזְּמַן שְׁחִיטַת הַפֶּסַח וָאֵילָךְ; וְעָדִיף שֶׁיְּגַלֵּחַ קֹדֶם חֲצוֹת, \u0010y11\u0011 הוֹאִיל וַאֲחֵרִים אֲסוּרִים לְגַלֵּחַ אַחַר חֲצוֹת \u0005(תְּשׁוּבַת ר\"י מִינְ\u0006 ץ \u0005ס\"ד)\u0006. וְכֵן אִם חָל שְׁמִינִי בְּשַׁבָּת שֶׁבְּעֶרֶב הָרֶגֶל, מֻתָּר לְכַבֵּס וְלִרְחֹץ וּלְסַפֵּר בְּעֶרֶב שַׁבָּת, וְאִם לֹא גִלַח בְּעֶרֶב יוֹם טוֹב אוֹ בְּעֶרֶב שַׁבָּת, מֻתָּר לְגַלֵחַ אַחַר הָרֶגֶל, שֶׁכְּבָר נִתְבַּטֵּל מִמֶּנּוּ גְזֵרַת שְׁלֹשִׁים. אֲבָל בְּחֹל הַמּוֹעֵד לֹא יְגַלַח, כֵּיוָן שֶׁהָיָה אֶפְשָׁר לוֹ לְגַלֵחַ קֹדֶם הָרֶגֶל. וְאִם חָל שְׁבִיעִי שֶׁלוֹ בְּשַׁבַּת עֶרֶב הָרֶגֶל, אָסוּר לְגַלֵחַ בְּעֶרֶב שַׁבָּת, וּמֻתָּר לְגַלֵחַ אַחַר הָרֶגֶל, וְכֵן בְּחֹל הַמּוֹעֵד, כֵּיוָן שֶׁלֹּא הָיָה יָכוֹל לְגַלֵחַ קֹדֶם הָרֶגֶל.\nהָא דְּרֶגֶל מְבַטֵּל גְזֵרַת שְׁלֹשִׁים, בִּשְׁאָר מֵתִים. אֲבָל בְּאָבִיו וְאִמּוֹ, שֶׁאָסוּר \u0005לְסַפֵּר\u0006 \u0010y12\u0011 עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו, אֲפִלוּ פָּגַע בּוֹ הָרֶגֶל לְאַחַר ל' יוֹם, אֵינוֹ מְבַטֵּל.\nאִם חָל אֶחָד מִיְּמֵי הָאֲבֵלוּת, חוּץ מֵהַשְּׁבִיעִי, בְּעֶרֶב הָרֶגֶל, \u0010y13\u0011 מֻתָּר לְכַבֵּס, וְלֹא יִלְבְּשֶׁנּוּ עַד הַלַיְלָה. וְטוֹב לִזָּהֵר מִלְכַבֵּס עַד אַחַר חֲצוֹת, כְּדֵי שֶׁיְּהֵא נִכָּר שֶׁמִּפְּנֵי הָרֶגֶל הוּא מְכַבֵּס. אֲבָל \u0010y14\u0011 לִרְחֹץ, אָסוּר עַד הַלַיְלָה. וְיֵשׁ מַתִּירִין לִרְחֹץ אַחַר תְּפִלַת הַמִּנְחָה, סָמוּךְ \u0010y15\u0011 \u0010c4\u0011 לַחֲשֵׁכָה, \u0005וְכֵן נוֹהֲגִין.\u0006\nרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים חֲשׁוּבִים כִּרְגָלִים לְבַטֵּל הָאֲבֵלוּת.\nנָהַג שָׁעָה אַחַת לִפְנֵי הַפֶּסַח, אוֹתָהּ שָׁעָה חֲשׁוּבָה כְּז', וְח' יְמֵי הַפֶּסַח הֲרֵי ט\"ו, וּמַשְׁלִים עֲלֵיהֶם ט\"ו אֲחֵרִים.\nשָׁעָה אַחַת לִפְנֵי עֲצֶרֶת חֲשׁוּבָה כְּשִׁבְעָה. וַעֲצֶרֶת, כֵּיוָן שֶׁאִם לֹא הִקְרִיב קָרְבָּנוֹת עֲצֶרֶת בַּעֲצֶרֶת יֵשׁ לוֹ תַּשְׁלוּמִין כָּל שִׁבְעָה, חָשׁוּב כְּשִׁבְעָה, הֲרֵי י\"ד, וּמַשְׁלִים עֲלֵיהֶם ט\"ז אֲחֵרִים; \u0010y16\u0011 וְיוֹם שֵׁנִי שֶׁל עֲצֶרֶת עוֹלֶה לְמִנְיַן הַט\"ז.\nשָׁעָה אַחַת לִפְנֵי רֹאשׁ הַשָּׁנָה בָּטְלָה מִמֶּנּוּ גְזֵרַת שִׁבְעָה, מִפְּנֵי רֹאשׁ הַשָּׁנָה; וּגְזֵרַת ל' מְבַטֵּל מִמֶּנּוּ יוֹם כִּפּוּרִים; וּמְגַלֵחַ עֶרֶב יוֹם כִּפּוּרִים. וְהוּא הַדִּין לְקוֹבֵר מֵתוֹ בִּשְׁלֹשָׁה בְּתִשְׁרֵי, שֶׁמְגַלֵחַ בְּעֶרֶב יוֹם הַכִּפּוּרִים.\nשָׁעָה אַחַת לִפְנֵי יוֹם הַכִּפּוּרִים בְּטֵלָה מִמֶּנּוּ גְזֵרַת ז' מִפְּנֵי יוֹם כִּפּוּרִים, וּגְזֵרַת ל' מְבַטֵּל מִמֶּנּוּ הֶחָג, וּמְגַלֵחַ בְּעֶרֶב הֶחָג.\nשָׁעָה אַחַת לִפְנָי הֶחָג וְהֶחָג, הֲרֵי י\"ד; וּשְׁמִינִי עֲצֶרֶת שִׁבְעָה, הֲרֵי כ\"א; וְיוֹם שֵׁנִי שֶׁל שְׁמִינִי עֲצֶרֶת, \u0010c5\u0011 הֲרֵי כ\"ב; וּמַשְׁלִים עֲלֵיהֶם ח' אֲחֵרִים.\nהַקוֹבֵר אֶת מֵתוֹ שָׁעָה אַחַת לִפְנֵי הָרֶגֶל, אוֹתָהּ שָׁעָה וְהָרֶגֶל חֲשׁוּבִים כְּי\"ד, וּמִיָּד אַחַר הָרֶגֶל יֵשׁ לוֹ דִּין שָׁבוּעַ שְׁלִישִׁי \u0010y17\u0011 לְעִנְיָן שֶׁיּוֹשֵׁב בִּמְקוֹמוֹ וְאֵינוֹ מְדַבֵּר.\nבִּמְקוֹמוֹת שֶׁעוֹשִׂין שְׁנֵי יוֹם טוֹב, מִי שֶׁמֵּת לוֹ מֵת בְּיוֹם טוֹב שֵׁנִי שֶׁהוּא יוֹם טוֹב הָאַחֲרוֹן שֶׁל פֶּסַח אוֹ שֶׁל חַג, אוֹ בְּיוֹם טוֹב שֵׁנִי שֶׁל עֲצֶרֶת, \u0010c6\u0011 וּקְבָרוֹ בּוֹ בַּיּוֹם, נוֹהֵג בּוֹ אֲבֵלוּת, הוֹאִיל וְיוֹם טוֹב שֵׁנִי מִדִּבְרֵיהֶם, וַאֲבֵלוּת יוֹם רִאשׁוֹן שֶׁהוּא יוֹם מִיתָה וּקְבוּרָה שֶׁל תּוֹרָה, יִדָּחֶה עֲשֵׂה שֶׁל דִּבְרֵיהֶם מִפְּנֵי עֲשֵׂה שֶׁל תּוֹרָה. אֲבָל אִם מֵת בְּיוֹם טוֹב שֵׁנִי שֶׁל רֹאשׁ הַשָּׁנָה, וְקָבְרוּ בּוֹ בַּיּוֹם, אֵינוֹ נוֹהֵג בּוֹ אֲבֵלוּת, שֶׁשְּׁנֵי הַיָּמִים כְּיוֹם אָרֹךְ הֵם. בַּמֶּה דְּבָרִים אֲמוּרִים, בְּשִׁבְעָה מֵתִים הַמְּפֹרָשִׁים בַּתּוֹרָה שֶׁכֹּהֵן מִטָּמֵא לָהֶם, אֲבָל אוֹתָם שֶׁהוֹסִיפוּ עֲלֵיהֶם כִּדְאִיתָא בְּסִימָן שע\"ד, אֵין אֲבֵלוּתָם אֶלָא מִדְּרַבָּנָן, לְפִיכָךְ אֵינוֹ נוֹהֵג עֲלֵיהֶם אֲבֵלוּת בְּשׁוּם יוֹם טוֹב. וַאֲפִלוּ בְּאוֹתָם שֶׁאָמַרְנוּ שֶׁנּוֹהֵג אֲבֵלוּת בְּיוֹם טוֹב שֵׁנִי, אֵינוֹ קוֹרֵעַ. וְהָעוֹלָם נוֹהֲגִין שֶׁלֹּא לְהִתְאַבֵּל בְּיוֹם טוֹב שֵׁנִי שֶׁל גָלֻיּוֹת עַל שׁוּם מֵת, אֲפִלוּ הוּא יוֹם מִיתָה וּקְבוּרָה. \u0005הַגָּה: דְּסוֹבְרִין כְּדַעַת הָאוֹמְרִים שֶׁאֵין שׁוּם אֲבֵלוּת דְּאוֹרַיְתָא, וְכֵן הַמִּנְהָג פָּשׁוּט, וְאֵין לְשַׁנּוֹת (ר\"ת וְר\"י וְרֹא\"שׁ)\u0006.\nמֵת לוֹ מֵת בְּעֶרֶב יוֹם טוֹב, וְנִתְיָרֵא שֶׁמָּא לֹא יַסְפִּיק לְקָבְרוֹ מִבְּעוֹד יוֹם, וּמְסָרוֹ לְעוֹבְדֵי כּוֹכָבִים שֶׁיּוֹלִיכוּהוּ לְקָבְרוֹ, כֵּיוָן שֶׁהוֹצִיאוּהוּ מֵהָעִיר וְנִתְכַּסָה מֵעֵינֵי הַקְרוֹבִים \u0010y18\u0011 חָלָה עָלָיו אֲבֵלוּת; וְאִם הוּא שָׁעָה אַחַת קֹדֶם הָרֶגֶל, וְנָהַג בּוֹ אֲבֵלוּת, בָּטְלָה לָהּ גְזֵרַת שִׁבְעָה אַף עַל פִּי שֶׁנִּקְבַּר בְּיוֹם טוֹב.",["\u0003אפילו שעה אחת. \u0004פירוש כל שהוא ולא בעינן שעה זמניות וכ\"כ בתשובת משאת בנימין סי' ע\"ד:","\u0003וימי הרגל עולים כו' ומשלים כו'. \u0004היינו ע\"פ שנתבאר לקמן מסעיף ז' ואילך:","\u0003אלא נוהג ברגל דברים שבצינעא. \u0004ולענין מלאכה במועד דינו כמ\"ש הרב בסעיף ב':","\u0003הלכך אין מתעסקין בו לנחמו ורגל עולה למנין (ז') [שלשים]. \u0004היינו בנודע לו מיתת המת ברגל אע\"פ שלא נודע לו קודם הרגל והיינו שכתב ר' ירוחם דרגל עולה למנין (ז') [שלשים] מדלא גרע מקובר מתו ברגל עכ\"ל ולא כמ\"ש בב\"י דבנודע לו מיתת המת קודם הרגל מיירי ואולי ל\"ד קאמר או ט\"ס הוא וצ\"ל ברגל:","\u0003ונוטל צפרניו במספרים. \u0004היינו לדעת המחבר בא\"ח סי' תקל\"ב אבל אנן קי\"ל להחמיר כמ\"ש הרב שם וסתם כאן הדברים לפי שאין כאן מקום דיני מועד:","\u0003בח\"ה. \u0004ה\"ה ביו\"ט שני או ביום טוב ראשון כשרוצה לקברו ע\"י עממים חל עליו אנינות כדלעיל סימן שמ\"א סעיף א' ולאחר שיקבר כל אלו הדינים נוהגים בו:","\u0003לא אמרינן דשמיני עצרת מבטל. \u0004ואין ש\"ע עולה רק ליום אחד כשקברו ברגל כ\"כ הגהמי\"י ומביאה ב\"י ודוקא כשקברו קודם חג הסוכות הוא דעולה ש\"ע ג\"כ לז' לקמן סעיף י\"א משא\"כ הכא וכ\"כ הב\"ח בשם התוספות ומרדכי ופסק כן ודלא כמהרש\"ל בתשובה סימן ה' שכתב דמבטל הוא דאינו מבטל הא למנין ז' לענין הל' עולה ש\"ע אפי' קברו ברגל מיהו בתשובת משאת בנימין סימן ע\"א פסק כמהרש\"ל עיין שם וכן נראה דעת הדרישה:","\u0003ובמקומות שעושים ב' ימים כו'. \u0004כתב הב\"ח ס\"ס זה דה\"ה בשני י\"ט של ר\"ה כגון שמת לו מת ביו\"ט ראשון של ר\"ה מונה הז' מיו\"ט הב' דהוי ג\"כ מדבריהם וע\"ש:","\u0003ולספר. \u0004כלומר דאע\"ג דתספורת נוהג כל ל' וכדלעיל ר\"ס ש\"ץ הכא בטל ממנו גזרת ל':","\u0003סמוך לחשיכה. \u0004מה שנרשם כאן טור הוא טעות דבטור לא כתב ע\"ש ריב\"א אלא דבחל יום א' דאבילות או יום (ז') [ו] בערב הרגל דמותר דוקא סמוך לחשכה אבל נ\"ל שהוא מהגהת אשר\"י שהביא הב\"י בא\"ח סי' תקמ\"ח וז\"ל אפי' חל יום ח' או יום ט' בערב הרגל צריך להמתין עד סמוך ללילה שאז ניכר שבשביל הרגל הותר כ\"כ ראבי\"ה ע\"כ:","\u0003ובערב פסח כו'. \u0004זה הוציא הרב מתשובת מהר\"י מינץ סי' ד' וצ\"ע דאדרבה משמע שם דע\"פ שוה לכל ערב יו\"ט לענין כיבוס ורחיצה דלא הותר אלא סמוך לחשיכה דמסיים שם וא\"כ יכול לספר קודם חצות ול\"ד לרחיצה דאפשר מחשיכה כו' עיין שם רק דאיתא שם דבערב פסח יש לגלח קודם חצות הואיל ואחרים אסורים לגלח אחר חצות דאין עושין מלאכה בערב פסח אחר חצות מפני שהיה זמן שחיטת הפסח וכמו שנתבאר באורח חיים סי' תקמ\"ח עיין שם וראיתי בב\"ה שהעתיק דברי הרב והשמיט הא דבערב פסח מותר בכל וצריך עיון:","\u0003הואיל ואחרים אסורים לגלח לו. \u0004דאין עושין מלאכה בערב פסח אחר חצות ואם כן יצטרך לגלח על ידי עצמו להכי עדיף טפי קודם חצות וכן הוא בתשובת מהר\"ם מינץ שם ודלא כהעט\"ז שכתב הואיל ואחרים הרבה נהגו איסור לגלח אחר חצות גם הוא ינהוג איסור כו':","\u0003עד שיגערו בו חביריו. \u0004כדלעיל סימן ש\"ץ ס\"ד:","\u0003מותר לכבס. \u0004דכבר בטל ממנו גזרת ז' אבל לספר אסור דלא נתבטל ממנו גזרת ל' כיון דאין כאן ז' ימים קודם הרגל:","\u0003אסור עד הלילה. \u0004כיון דאפשר משחשכה:","\u0003וכן נוהגין. \u0004וכתוב בת\"ה סימן רפ\"ז דאפילו מת לו מת בע\"ש ואותו שבת הוא ערב הרגל מותר לרחוץ בע\"ש לפי מנהגינו ואין להקשות דהיאך כ' הרב וכן נוהגין דהא לעיל ר\"ס שפ\"א כתב הרב דאנן נהגינן איסור רחיצה כל ל' וכן לעיל ר\"ס שפ\"ט כתב דנהגינן איסור כביסה כל ל' י\"ל דאינו אלא חומרא ומדינא שרי וכדמשמע מדברי הרב שם והכא משום כבוד הרגל לא נהגו להחמיר וכ\"כ העט\"ז ותדע דהא בת\"ה שם כתוב בשם מהר\"מ אפילו לא נהג אבילות אלא שעה א' לפני הרגל מותר ברחיצה בחמין סמוך לערב והרי מהר\"מ ס\"ל דאסרי' רחיצה כל שלשים וכמ\"ש הגהמ\"י על שמו ומביא ב\"י סוף סי' ת' אלא ודאי כדאמרן ואע\"ג דבא\"ח סימן תקמ\"ח ס\"ח וס\"י כתב הרב דלדידן דנוהגים איסור רחיצה כל ל' אסור לרחוץ דהא הרגל לא בטל ממנו רק גזרת ז' וה\"ה לענין כיבוס במקום דנוהגין איסור כיבוס כל ל' עכ\"ל היינו משום דכך הוא ראוי להורות אי הוי איסור רחיצה וכיבוס כל ל' מן הדין אבל כאן כתב דמ\"מ המנהג אינו כן וכ\"כ הב\"ח אלא דצריך ליישב לאיזה צורך כ' הרב שם כן כיון דס\"ס המנהג אינו כן ונ\"ל דס\"ל דהא דהמנהג אינו כן היינו משום כבוד הרגל והלכך היכא דליכא משום כבוד הרגל אסור ונ\"מ דלאחר הרגל אסור רחיצה וכביסה עד ל' דהרגל לא בטל ממנו רק גזרת ז' כנ\"ל ודוק:","\u0003ויום שני של עצרת עולה למנין. \u0004כיון דיום טוב שני אינו אלא מדבריהם:","\u0003לענין שיושב כו'. \u0004כדלעיל סימן שצ\"ג סעיף ב' ואנן לא נהגינן הכי כמו שנתבאר שם:","\u0003חלה עליו אבילות. \u0004וכמו שנתבאר לעיל ר\"ס שס\"ה:"],["\u0003אפי' שעה אחת. \u0004פירוש אפי' חליצת מנעל לחוד שנהג מעט די בכך. כ\"פ מהר\"ר בנימין בתשובה:","\u0003ולא מתורת רגל לבד כו'. \u0004זהו סברת הרמב\"ן והוכיחה מדמיבעיא לן אי רגל עולה למנין ל' או לאו ולענין ז' לא מבעיא ליה דודאי אינו עולה כיון דלא נהגא מצות ז' ברגל דהא אין איסור בנעילת סנדל וכפיית מטה כי קא מבעיא ליה לענין ל' דקא נהגא מצות ל' ברגל פירש\"י דהא ברגל נמי אסור בגיהוץ ותספורת והקשה הרמב\"ן הא מקצת דין ז' נמי נוהג ברגל דהא אינו מכבס כסותו אפילו במים לחוד ורבים מתעסקים לנחמו כדין אבל אלא ודאי במנין ל' צריך להיות דכל דין ל' אף מה שאין אסור מחמת הרגל נוהג בו משא\"כ בדין ז' שאין נוהג בו אלא מעט והלכך כתב כאן שאף דין גיהוץ ותספורת נוהג באבל בלא דין הרגל וכמ\"ש כאן. והטור כ' שמדברי הרא\"ש נראה שאין איסורן מדין אבל יותר מאיסור דרגל והיינו דסבר אע\"פ שאין נוהג איסור מחמת אבילות טפי מרגל אלא מה שאסור ברגל מ\"מ עולה הרגל למנין ל' כיון דעכ\"פ נוהג בו איסור ופסק ב\"י כרמב\"ן דמסתבר טעמיה וכן פסק בש\"ע ובתשובת מהר\"ר בנימין חולק על הש\"ע דלא מסתבר לפסוק כרמב\"ן דדבריו דחוים דאין קושיתו קושיא ממנין ז' דעיקר דין ז' הוא פח\"ז נת\"ר סי' של ז' דהיינו פריעת ראש חליצת סנדל) כו' ואע\"ג שנוהג דין כיבוס במי' אין זה עיקר דין אבילות משא\"כ דין ל' שעיקר הדין הוא גיהוץ ותספורת והוא נוהג גם ברגל ע\"כ עולה ועוד מאן לימא לן שהקובר מתו ברגל אינו מכבס כסותו במים לבד דילמא אין ה\"נ דמותר עכ\"ד ואינם נראים כלל דמה שכ' דעיקר דין אבילות הוא פח\"ז נת\"ר מי הגיד לו שזה עיקר דלא הזכירו אלו בגמ' אלא לענין שבת דפח\"ז חוב ונת\"ר רשות אבל כיבוס במים אין שייך לענין שבת כלל ע\"כ לא חשביה בכלל פח\"ז נת\"ר ובאמת אין חילוק בין אלו לכיבוס כלל וכיבוס הוא נזכר בירושל' ואי ס\"ד דבמקצת דין ל' סגי ה\"נ היה לנו לומר בדין ז' במקצת ומ\"ש דילמא כיבוס במים ברגל אין אסור מחמת אבל לא דק כלל בזה דודאי איסור גמור הוא לכ\"ע דהא דבר שבצינעא נוהג בו איסור וזה ודאי צינעא הוא דמי ירגיש בזה שאין מכבס כסותו במים. והרא\"ש אין חולק אלא על תוספת דגיהוץ ותספורת דהויין מילי דפרהסיא ע\"כ אין בהם איסור נוסף על הרגל והרמב\"ן חשב גם זה לצינעא דהיינו מה שאין לובש בגד מגוהץ באותן ימים דמי יאמר שיש לו בגד מגוהץ ואינו לובשו גם מה שחשב עוד הרמב\"ן לאיסור נוסף במה שאינו מגלח אף שבא ממדינת הים אין זה מפורסם כ\"כ וכן שאר הדברים שחשבן כאן ובאמת דברים נכונים הם לומר כן ויפה דן הב\"י כרמב\"ן:\n\u0003וראיתי \u0004עוד בתשו' הנ\"ל שמעשה היה בחתן שנשא אשה בערב הרגל ובתוך הרגל מת לו מת פסק שם דאע\"ג דחתן דעלמא שאירע לו אבילות בתוך ז' ימי משתה אין מונה ל' אלא אחר ימי המשתה מטעם דהוא עדיף מימי הרגל דאיהו מותר בגיהוץ ותספורת כמ\"ש סי' שמ\"ב משא\"כ חתן זה דימי משתה שלו הם ברגל ממילא אסור בגיהוץ וכו' משום הכי להרמב\"ן דלעיל דס\"ל דהרגל עולה למנין ל' מטעם איסור נוסף ממילא זה החתן שמותר באותו תוספת ע\"כ [אין] עולין לו ימי המשתה שלו ולהרא\"ש (נמי) דעולה לו [נמי] אפי' אם ימי האבילות אין להם איסור יותר מן הרגל א\"כ הכי נמי דנוהג איסור גיהוץ מחמת הרגל עולה לו ג\"כ למנין שלשים וכ\"פ שם למעשה ובעיני יפלא מאד דברים אלו דודאי גם להרא\"ש אין עולה אלא כשיש איסור לאבל מחמת אבלותו אלא שאותו איסור הוא ג\"כ מחמת הרגל בזה אמר דשפיר עולה כיון דמ\"מ הוא נוהג באותו איסור דהוא יכול לומר אני עושה מחמת האבילות ואם יש איסור נוסף מה לי בכך משא\"כ בחתן זה שאין בו חיוב אבילות כלל וזה שנוהג איסור הוא מחמת הרגל לחוד היאך מצאנו ידינו ורגלינו לומר שיהיה זה נחשב לימי השלשים הלא אנו רואין שזה נהג איסור דוקא מחמת הרגל לא מחמת אבילות הא למה זה דומה לחתן שהוא תוך שבעת ימי משתה שלו במקום שאי אפשר לו לגהץ או שהיתה שבועה עליו שלא לגהץ וכי נימא שיהיה זה נחשב לו למנין ל' הא ודאי ליתא. על כן נראה דהאי מילתא שכתב דעולה לחתן ימי משתה שלו למנין ל' חידושא הוא ולא ילפינן מיניה ואינו עולה לכולי עלמא כמו בשאר חתן ואין זה דומה למ\"ש בסימן שמ\"א דיכול החתן לדחות שבעת ימי משתה ולהקדים שבעת ימי אבילות לטובתו דהתם בימי אבילות תליא מילתא בקום עשה שצריך לעשות מעשה להראות האבילות דהיינו חליצת סנדל וכפיית מטה וכיוצא בו שפיר אמרינן דעל ידי מעשה ההוא מבטל שבעת ימי המשתה שלו מה שאין כן בדין ל' שאין תלוי במעשה אלא במה שאנו אוסרין לו גיהוץ ותספורת בזה ודאי אנו אומרים שאין בידו לבטל ואם הוא אומר שרוצה לבטל מחמת שבלא\"ה יהיה אסור לו מחמת הרגל הרי אנו רואים בפירוש שהוא אינו רוצה לעשות שום אבילות רק מה שצריך לעשות מחמת הרגל ובזה ודאי אין עולה לו כן נראה לע\"ד בדבר זה:","\u0003ברגל בחול המועד. \u0004דאילו ביו\"ט עצמו יש חילוק ביו\"ט הראשון אינו נוהג אנינות אא\"כ רוצה לקברו ע\"י עממים ובשני נוהג אנינות בכל גווני אבל בחול המועד נוהג לעולם אנינות:","\u0003לא אמרינן דשמיני עצרת מבטל. \u0004פי' דהוה אמינא דשמיני עצרת שהוא רגל בפני עצמו אתי ומבטל האבילות כדלעיל ריש סי' זה היכא דנהג שעה אחת אבילות לפני הרגל והכי נמי נהג ברגל עצמו קודם שמיני עצרת קצת אבילות דהיינו גיהוץ ותספורת כמ\"ש בסוף סעיף א' קמ\"ל דלא אמרינן כן דליכא חשיבות לשמיני עצרת אלא אם כבר נסתלק משבעת ימי אבלות קודם הרגל מה שאין כן בזה. וכ' ב\"י בשם הגהת מיימונית דהוא הדין דאין חשיבות לשמיני עצרת להיות נחשב לשבעה ימים שנזכר בסעיף י\"א אלא אם נקבר קודם הרגל משא\"כ אם מת ברגל לא נחשב שמיני עצרת במנין ל' אלא ליום אחד וכן כתבו התוס' בפ' אלו מגלחין (מועד קטן דף כ\"ד) וכן כ' המרדכי בשם ריב\"ש דלא כדברי ה\"ר יוסף שסבירא ליה דשמיני עצרת וכן עצרת ויו\"כ הכל נחשב לשבעה ימים אם מת בו ביום ביום לענין ל' ורש\"ל בתשובה סי' ה' חולק ואומר דגם במת ברגל נחשב שמ\"ע למנין שבעה ימים לענין ל' ואין לו ראיה ברורה רק שמביא ראיה מדכתב הטור כאן שאין שמיני עצרת מבטל משמע דדוקא אינו מבטל לגמרי שבעת ימי אבילות אבל מ\"מ נחשב לשבעה לענין מנין שלשים אם כן סבירא ליה כה\"ר יוסף שזכרנו ואין מזה ראיה דהטור נקט ל' ביטול לאפוקי ממ\"ש תחילה שהרגל מבטל כמו שכתבתי. וכן משמע לי מדברי הרמב\"ם דלא כרש\"ל בזה מדכתב הקובר מתו בתוך הרגל כו' והעתיק לשונו בשלחן ערוך באורח חיים סימן תקמ\"ח וסיים שם ומונה שלשים מיום הקבורה משמע אפילו מת בסוף ימי הרגל מונה מיום הקבורה שלשים יום ולא אמרינן דאותן ימי הרגל יהיו נחשבים לשבעה ימים דמאי שנא ממת בעצרת או יום כפור לפי דעת ה\"ר יוסף שזכרנו אלא ודאי דאין שום עילוי לרגל כלל להיות נחשב לשבעה אלא אם כן נקבר קודם הרגל שעה אחת. וכן יראה לי מסוגית הגמרא דבעי מיניה אביי מרבה קברו ברגל עולה לו למנין שלשים או לא למנין שבעה לא מבעיא כו' אמר ליה אינו עולה ואחר כך מותבינן עליה ומסקינן ליה בתיובתא אלא אמרינן עולה מדאמר אביי מי עולה למנין שלשים שמע מיניה שמספקא ליה אי יהיו נחשבים ימי הרגל למנין הימים של שלשים דהיינו דימי הרגל יהיו תחת שאר ימים של שלשים ולא עלה על דעתו שיהיה להם מעלה יתירה שיהיו נחשבים לשבעה ימים ועל זה אמר לו רבה דאינן עולים והיינו אפילו בעד ימים אחרים לא יעלו וכל שכן שלא יהיו נחשבים לשבעה ומסקינן זה בתיובתא דלמנין שלשים עולים ולענין שיהיו נחשבים לשבעה לא מסקינן בהדיא שיהיה להם מעלה זאת ומנא לן בזה לומר לאפוקי מדרבה. ועוד ראיה מדברי ה\"ר זרחיה הלוי שכתבו בשמו בתשובת מיימון לספר שופטים סימן י\"ז לענין אם לא ידע שמת לו מת קודם החג עד אחר החג שלא נאמר דימי החג ושמיני עצרת יהיו נחשבים כל אחד לשבעה וממילא נעשית שמועה רחוקה אלא לזה אין לימי הרגל מעלה אלא נחשבים כשאר ימים וכתב שם לשון זה וכל שכן זה שלא ידע ולא שמע במות המת קודם הרגל היאך יעלה לו רגל לעשות יום א' לפני החג והחג ושמיני עצרת לכ\"א יום אם אמרו במי שהפסיק לו החג אבילותו יאמרו במי שלא ידע ושמע כו' עכ\"ל הרי שלא נתן מעלה לרגל להיות נחשב כז' אלא במפסיק אבילות ולא סגי בשמע ולא הפסיק כגון שמע ברגל דאל\"כ היה לו לומר אם אמרו במי ששמע יאמרו במי שלא שמע אלא כדפרישית ודרך כל שכן אמר כן דאם אמרו כן במי שהפסיק אבילות שבעה שלו פשיטא שלא יאמרו במלתא רחיקתא שלא ידע ולא שמע וה\"ה ששמע ברגל דלא מהני ליה להחשב לשבעה אלא שדין שלו התם קאי אלא ידע ולא שמע ורש\"ל בתשו' דלעיל כתב ועוד מאחר שהרב זרחיה הלוי כתב דכל אותן הרגלים לעולם נחשבים למנין שבעה ימים אפילו לענין שמועה רחוקה אף שלא נהג אבילות בעולם ויש מן החכמים שנסתפקו בזה כו' ואף דלא קי\"ל כהר\"ר זרחיה הלוי בזה היינו משום שלא מסתברא שיעלה למנין שבעה מי שלא שמע שמת משום הכי מסתבר להחמיר אבל במי שידע פשיטא שיעלה למנין שבעה עכ\"ל ותמוה הוא שכתב בשם הר\"ר זרחיה הלוי להקל ולא עיין בדברי ה\"ר זרחיה הלוי גופיה שהוא פוסק להחמיר כמו שהעתקתי ויותר מזה תמהתי על תשובה למהר\"ר בנימין שכתב שיש לפסוק כרש\"ל בדין זה שיש לו ראיה מדברי ה\"ר זרחיה הלוי ולא עיין אחר גוף דברי ה\"ר זרחי' הלוי וכן לא יעשה וכבר זכרנו אמתת דברי ה\"ר זרחיה הלוי שיש להוכיח איפכא וכמ\"ש וגם מו\"ח ז\"ל כתב דלא כרש\"ל בדין זה:","\u0003וכן נוהגין. \u0004יש לתמוה שבא\"ח סי' תקמ\"ח כתב רמ\"א בסעיף י' דלדידן אסור רחיצה אפילו סמוך לחשיכה ואפשר דהתם קאמר שראוי לפסוק כן אבל באמת אין נוהגין כן אלא מתירין סמוך לחשיכה. כן נראה לע\"ד ליישב דבריו:","\u0003הרי כ\"ב. \u0004קשה ליחשב שמיני עצרת כרגל בפ\"ע גם לענין ביטול ל' כיון דנתבטל ז' קודם החג והחג נחשב לשבעה הרי י\"ד כמו דאמרינן בי\"כ בסעיף י' תירץ הרא\"ש דשאני הכא שלא נהג דין ל' כלל ואע\"ג שנהג גיהוץ ותספורת מ\"מ הרי בלאו אבילות נמי אסור באלו מחמת הרגל וצ\"ע לתרץ זה אליבא דרמב\"ן דסבירא ליה דיש באבילות איסור נוסף על איסור הרגל כמוזכר לעיל סימן זה סעיף א' א\"כ קשה למה לא יבטל שמיני עצרת את שלשים כיון שכבר נהג בדין שלשים בתוספת האיסור ונראה דמ\"מ יש כאן שינוי משאר שלשים בחול דהתם יש היכר בעיקר הדין גיהוץ ותספורת משא\"כ כאן שאין היכר אלא בתוספת וזה אין הוכחה כל כך ודי בזה שנאמר שהרגל עולה למנין השלשים אבל לא לענין דליהוי כנהג מקצת שלשים ממש לענין שיבא שמיני עצרת ויבטל לגמרי שאר הל'. כנ\"ל:","\u0003וקברו בו ביום נוהג בו כו'. \u0004ברמב\"ם כאן לפני זה בבא אחרת דהיינו הקובר את מתו ברגל כו' המקומות שעושין ב' י\"ט מונה השבעה מיו\"ט שני האחרון אע\"ג שאין נוהג בו אבילות לפי שהוא מדבריהם ע\"כ עולה למנין ז' ומונה אחריו ששה בלבד והשלחן ערוך לא הזכירו כאן לפי שבאורח חיים סימן תקמ\"ח הזכירו:\n\u0003וכתוב \u0004במהרי\"ל וז\"ל יום שני של ראש השנה איני מורה שיעלה למנין שבעה ואמר שכן הוא במיימוני אבל בשאר יו\"ט מודה שעולה אע\"פ שלא מצא בהדיא היכא שקברו תוך המועד דלא הוה יו\"ט האחרון יום הקבורה שיעלה למנין ז' עכ\"ל וכ' רש\"ל ע\"ז ותימה לי הלא בהגה' מיי' חולק בזה החילוק ע\"ש עכ\"ל דהיינו מבואר שם בהגה' מיימוני בשם רב יהוד' הלכה למעשה באמו שנפטרה ביו\"ט א' של סוכות ונקברה ביו\"ט שני ולאחר סוכות נהג אבילות ו' ימים לבד ורא\"ה פסק גם הוא היכא שקברו ביו\"ט אחרון אבל קברו ברגל קודם לכן לא וזה לשונו הקובר מתו ביו\"ט אחרון או ביו\"ט שני דעצרת מונה ששה אחר הרגל דיום מיתה עולה לו מן המנין אע\"ג דלא נהיג ביה אבילות דדאורייתא היא כו' עכ\"ל ומ\"מ אין לנו אלא כפסק הש\"ע בא\"ח די\"ט ב' של גליות עולה אפילו מת ונקבר בראשון על ידי עממים וטעם שהחמיר מהרי\"ל בר\"ה לפי שהוא כיומא אריכתא עם היום הראשון וע\"כ אין סברא למנות מיום שני כל שמת ונקבר ביום הראשון דכשם שהראשון אינו עולה למנין ז' כך השני כחד יומא הם אבל אם נקבר ביום שני של ר\"ה נראה פשוט דמונה ממנו דהא עכ\"פ מדבריהם הוא כמ\"ש הטור לדעת הרמב\"ן והגאונים אין בזה עיכוב לומר דהא שייך ליום הראשון דזה ודאי דהא בכל דצריך מנין ימים ודאי מנינן ר\"ה לשני ימים רק באם הוה הקבורה ביו\"ט ראשון של ר\"ה ואז לא מנינן אותו הראשון אז גריר אבתריה גם יום השני מחמת דיומא אריכתא חשבינן ליה משא\"כ בנקבר ביום שני. כן נראה לי ברור:\n\u0003ראיתי \u0004להזכיר פה מה שראיתי במקצת מקומות כשקוברין מת ביום טוב ראשון ע\"י עממים באין ישראלים ומחזירים העפר לתוך הקבר על המת עד זיבולא בתרייתא והוא איסור גמור בעיני דהרי מלאכה גמורה היא ויש בזה משום בונה ופשיטא דאסור על ידי ישראל ע\"כ יש ליזהר בזה לעשות ע\"י עממים על כל צרה שלא תבוא:"]],["שַׁבָּת אֵינוֹ מַפְסִיק אֲבֵלוּת וְעוֹלֶה לְמִנְיַן שִׁבְעָה, שֶׁהֲרֵי קְצָת דִּינֵי אֲבֵלוּת נוֹהֲגִים בּוֹ, דְּהַיְנוּ דְּבָרִים שֶׁבְּצִנְעָא שֶׁהֵם: תַּשְׁמִישׁ הַמִּטָּה וּרְחִיצָה. \u0010y0\u0011 אֲבָל דְּבָרִים שֶׁבְּפַרְהֶסְיָא \u0005לֹא,\u0006 דְּהַיְנוּ לְהָסִיר עֲטִיפָתוֹ, \u0010y1\u0011 \u0005וְדַוְקָא כְּשֶׁהוּא מְעֻטָּף עֲטִיפוֹת יִשְׁמְעֵאלִים כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִימָן שפ\"ו, אֲבָל קְצָת עֲטִיפָה שֶׁנּוֹהֲגִים בִּקְצָת מְקוֹמוֹת כָּל ל', אֵין צָרִיךְ לְהָסִיר בְּשַׁבָּת, הוֹאִיל וְיֵשׁ לוֹ מִנְעָלִים בְּרַגְלָיו (מהרי\"ו סִימָן ה')\u0006, וְלִלְבֹּשׁ מִנְעָלָיו, וְלִזְקֹף הַמִּטָּה מִכְּפִיָּתָהּ, וְשֶׁלֹּא לִלְבֹּשׁ בֶּגֶד קָרוּעַ, אֶלָא מַחֲלִיפוֹ, וְאִם אֵין לוֹ לְהַחֲלִיף \u0010y2\u0011 מַחֲזִיר קִרְעוֹ לְאַחֲרָיו; וְתַלְמוּד תּוֹרָה הָוֵי דָּבָר \u0010y3\u0011 \u0010c0\u0011 שֶׁבְּצִנְעָא, אֲבָל לַחֲזֹר הַפָּרָשָׁה, כֵּיוָן שֶׁחַיָּב אָדָם לְהַשְׁלִים פָּרָשִׁיּוֹתָיו עִם הַצִּבּוּר, הָוֵי כְּקוֹרֵא אֶת שְׁמַע וּמֻתָּר. וְאִם קָרְאוּ אֶת הָאָבֵל לַעֲלוֹת לַתּוֹרָה, צָרִיךְ לַעֲלוֹת, שֶׁאִם הָיָה נִמְנָע הָיָה דָּבָר שֶׁל פַּרְהֶסְיָא; וְרַבֵּנוּ תָּם הָיוּ קוֹרִים אוֹתוֹ בְּכָל פַּעַם שְׁלִישִׁי, וְאֵרַע בּוֹ אֲבֵלוּת וְלֹא קְרָאוֹ הַחַזָּן, וְעָלָה הוּא מֵעַצְמוֹ וְאָמַר כֵּיוָן שֶׁהֻרְגַל לִקְרוֹתוֹ שְׁלִישִׁי בְּכָל שַׁבָּת, הָרוֹאָה שֶׁאֵינוֹ עוֹלֶה אוֹמֵר שֶׁבִּשְׁבִיל אֲבֵלוּת הוּא נִמְנָע, וְהָוֵי דְּבָרִים שֶׁל פַּרְהֶסְיָא. \u0005וְכֵן אִם הַכֹּהֵן אָבֵל וְאֵין כֹּהֵן אַחֵר בְּבֵית הַכְּנֶסֶת, מֻתָּר לִקְרוֹתוֹ; אֲבָל בְּעִנְיָן אַחֵר, אָסוּר (הַגָּהוֹת מַיְמוֹנִי פ\"ג מה\"א)\u0006.\nגְרָרַתּוּ חַיָּה אוֹ הֲרָגוּהוּ לִסְטִים, \u0010y4\u0011 \u0010y5\u0011 וּבְשַׁבָּת נִתְיָאֵשׁ מִלְבַקֵשׁ, כֵּיוָן דִּדְבָרִים שֶׁבְּצִנְעָא נוֹהֵג בְּשַׁבָּת עוֹלֶה לוֹ לְיוֹם אֶחָד. \u0005הַגָּה: אִם פָּגַע יוֹם ל' שֶׁל אֲבֵלוּת בְּשַׁבָּת וְיוֹם כ\"ט בְּעֶרֶב שַׁבָּת, מֻתָּר לוֹ לִרְחֹץ בְּעֶרֶב שַׁבָּת, אַף בִּמְקוֹמוֹת שֶׁנּוֹהֲגִין שֶׁלֹּא לִרְחֹץ כָּל שְׁלֹשִׁים, דְּהוֹאִיל וּמִדִּינָא שָׁרֵי לְאַחַר שִׁבְעָה, אֶלָּא שֶׁנָּהֲגוּ לְהַחְמִיר כָּל ל', בִּכְהַאי גַּוְנָא שָׁרֵי מִשּׁוּם כְּבוֹד שַׁבָּת (הַגָּהוֹת מַיְמוֹנִי בְּשֵׁם מַהֲרַ\"ם פ\"י ופ\"ו דְּיוֹם טוֹב)\u0006. וְהוּא הַדִּין כָּל כַּיּוֹצֵא בָּזֶה, כְּגוֹן לַחֲזֹר עַל מְקוֹמוֹ בְּלֵיל שַׁבָּת וְלִלְבֹּשׁ בִּגְדֵי שַׁבָּת, דְּהָא נָמִי אֵינוֹ אֶלָּא מִנְהָג בְּעָלְמָא \u0005(כֵּן נִרְאֶה מִדִּבְרֵי מַהַרַ\"שׁ)\u0006, כְּמוֹ שֶׁנִּתְבָּאֵר לְעֵיל סִי' שפ\"ט וש\"צ; וְאַף עַל פִּי שֶׁיֵּשׁ לְחַלֵּק בֵּין רְחִיצָה שֶׁאֲסוּרָה בְּשַׁבָּת וּבֵין דְּבָרִים אֵלּוּ שֶׁאֶפְשָׁר לוֹ לַעֲשׂוֹת בְּשַׁבָּת, מִכָּל מָקוֹם אֵין נ\"ל לְחַלֵּק בְּכָךְ.",["\u0003אבל דברים שבפרהסיא. \u0004דהיינו להסיר עטיפתו אינו נוהג וצריך ללבוש מנעליו ולזקוף המטה. כו' כן ראוי להיות:","\u0003ודוקא כו' הואיל ויש לו מנעלים ברגליו. \u0004לא ידעתי מה ענין מנעלים ברגליו לכאן דמאן דמתיר משום מנעלים ברגליו מתיר אפי' בעטיפת ישמעאלי' כדמשמע בש\"ס ורמב\"ן ובאמת במהרי\"ו כ' דהכא מותר מטעם כיון שנוהגים בעטיפה זו גם אחר ז' ימי אבילות דלא אסרינן דבר שבפרהסיא אלא מה שאינו רק תוך ז' ואח\"כ כתב דמותר ג\"כ מטעם דמנעלים ברגליו עיין שם ובעט\"ז השמיט האי סיומא דהואיל ויש לו מנעלים ברגליו:","הב\"ח בס\"ס שפ\"ו דמהרי\"ו מיירי באותה עטיפה שהוא לבוש שקורין קאפ\"א לפי מה ששמעתי שנוהגים להתעסק בה כל ל' אבל לשום הכובע לפני העינים שנוהגים במלכותינו כל ז' בלחוד דזהו נקרא עטיפה לדידן הוי פרהסיא בשבת אם לא יגביה הכובע כדרך כל אדם הילכך מיד שמתחיל הש\"ץ ברכו חייב להגביה הכובע ע\"כ:","\u0003מחזיר קרעו לאחריו. \u0004והאידנא לא נהגו לדקדק בזה ואפשר דמנעלים מוכיחים עליהן וכמ\"ש הגהמ\"י ומביאה בית יוסף דהיכא דמנעלים ברגליו אין צריך לחזרת קרע עיין שם:","\u0003אבל לחזור הפרשה כו'. \u0004כתוב בדרישה בשם מהרש\"ל דה\"ה לחזור שנים מקרא ואחד תרגום מותר ע\"ש:","\u0003ובשבת נתייאש לבקשו כו'. \u0004דכיון דנתייאשו לבקשו הוי ליה כנקבר כדלעיל סימן שע\"ה סעיף ז' ושבת עולה אפילו בתחלת המנין כדלקמן סימן ת\"ב ס\"ז:"],["\u0003אבל לחזור הפרשה. \u0004ובאגודה כתב ונראה לאיסור וכ' רש\"ל להכריע דבחול אסור ובשבת שרי שהוא זמנו והוא מחובת היום עד כאן לשונו. וכתב רש\"ל בתשובה סימן ע\"א דאבל שיום מילת בנו בשבת אין לו לעלות לתורה אע\"פ שנהגו בקצת מקומות שאבי הבן הוי חיוב לעלות ביום מילת בנו מכ\"מ לא מקרי פרהסיא:"]],["אֵין מַנִּיחִין אֶת הַמִּטָּה בָּרְחוֹב בְּחֹל הַמּוֹעֵד, שֶׁלֹּא לְהַרְגִיל אֶת הַהֶסְפֵּד, שֶׁאָסוּר לְהַרְגִיל אֶת הַהֶסְפֵּד בְּחֹל הַמּוֹעֵד, אֶלָא לִכְבוֹד תַּלְמִיד חָכָם; לְפִיכָךְ אֵין מוֹלִיכִין הַמֵּת לְבֵית הַקְבָרוֹת בְּחֹל הַמּוֹעֵד, עַד שֶׁיִּהְיֶה כָּל הַקֶבֶר מְתֻקָן וּמְזֻמָּן.\nאֵין קוֹרְעִין בְּחֹל הַמּוֹעֵד אֶלָא מִי שֶׁהוּא \u0010y0\u0011 חַיָּב לִקְרֹעַ כִּדְאִיתָא בְּסִימָן ש\"מ, אֲבָל מִי שֶׁאֵינוֹ חַיָּב, וְרוֹצֶה לִקְרֹעַ מִפְּנֵי הַכָּבוֹד, אָסוּר. \u0010y1\u0011\nשָׁמַע בְּחֹל הַמּוֹעֵד שְׁמוּעָה קְרוֹבָה, חַיָּב לִקְרֹעַ.\nאֵין חוֹלְצִין כָּתֵף בַּמּוֹעֵד, וְאֵין מַבְרִין בּוֹ אֶלָא קְרוֹבָיו שֶׁל מֵת; אֲבָל הַקְרוֹבִים, מַבְרִין. וְהוּא הַדִּין לַחֲנֻכָּה וּפוּרִים וְרֹאשׁ חֹדֶשׁ. וּכְשֶׁמַּבְרִין, אֵין מַבְרִין אֶלָא עַל מִטּוֹת זְקוּפוֹת, אֲבָל בְּיוֹם טוֹב, אֲפִלוּ בְּיוֹם טוֹב שֵׁנִי, אֵין קוֹרְעִין וְלֹא חוֹלְצִין וְלֹא מַבְרִין; וּבְחֹל הַמּוֹעֵד מַבְרִין הַכֹּל עַל הֶחָכָם לְתוֹךְ הָרְחוֹב, כְּדֶרֶךְ שֶׁמַּבְרִין אֶת הַקְרוֹבִים, שֶׁהַכֹּל כִּקְרוֹבָיו.\nנָשִׁים בְּחֹל הַמּוֹעֵד מְעַנּוֹת, דְּהַיְנוּ שֶׁכֻּלָן עוֹנוֹת כְּאַחַת; אֲבָל לֹא מְטַפְּחוֹת, דְּהַיְנוּ לְהַכּוֹת כַּף עַל כַּף. בְּרֹאשׁ חֹדֶשׁ, חֲנֻכָּה וּפוּרִים, מְעַנּוֹת וּמְטַפְּחוֹת, אֲבָל לֹא מְקוֹנְנוֹת, דְּהַיְנוּ שֶׁאַחַת מְדַבֶּרֶת וְכֻלָן עוֹנוֹת אַחֲרֶיהָ. נִקְבַּר הַמֵּת, לֹא מְעַנּוֹת וְלֹא מְטַפְּחוֹת; וְהָנֵי מִלֵי לְאִינַשׁ דְּעַלְמָא, אֲבָל לְתַלְמִיד חָכָם, בֵּין בְּחֹל הַמּוֹעֵד בֵּין בְּרֹאשׁ חֹדֶשׁ, חֲנֻכָּה וּפוּרִים, מְעַנּוֹת וּמְקוֹנְנוֹת כְּדַרְכָּן בַּחֹל; וְהָנֵי מִלֵי בְּפָנָיו, אֲבָל שֶׁלֹּא בְּפָנָיו, לֹא. וְיוֹם שְׁמוּעָה, אֲפִלוּ רְחוֹקָה, כִּבְפָנָיו דְּמֵי.\nאוֹמְרִים עַל הַמֵּת צִדּוּק הַדִּין וְקַדִּישׁ, כְּדַרְכָּן. וְכֵן בְּיוֹם טוֹב שֵׁנִי; אֲבָל בְּיוֹם טוֹב רִאשׁוֹן, כֵּיוָן שֶׁאֵין מִתְעַסְקִים בַּמֵּת אֵין אוֹמְרִים אוֹתוֹ. \u0005הַגָּה: וְיֵשׁ חוֹלְקִין שֶׁלֹּא לוֹמַר צִדּוּק הַדִּין בַּמּוֹעֵד (הַטּוּר הֵבִיא כַּמָּה רַבְּוָתָא)\u0006, וְכֵן הַמִּנְהָג פָּשׁוּט בִּמְדִינוֹת אֵלּוּ שֶׁלֹּא לוֹמַר צִדּוּק הדִּין בְּכָל הַיָּמִים שֶׁאֵין אוֹמְרִים בָּהֶם תַּחֲנוּן \u0005(בְּמִנְהָגִים)\u0006 ; וְלָכֵן אֵין אוֹמְרִים גַּם כֵּן כְּשֶׁקּוֹבְרִין \u0010y2\u0011 אַחַר חֲצוֹת בְּעֶרֶב שַׁבָּת. יֵשׁ אוֹמְרִים שֶׁאִם קוֹבְרִים הַמֵּת בַּלַּיְלָה, שֶׁאֵין אוֹמְרִים קַדִּישׁ וְלֹא צִדּוּק הדִּין \u0005(כָּל בּוֹ)\u0006.\nמֵת לוֹ מֵת קֹדֶם פּוּרִים, וּפָגַע בּוֹ פּוּרִים, אֵינוֹ מַפְסִיק \u0010y3\u0011 הָאֲבֵלוּת; וּמִכָּל מָקוֹם אֵין אֲבֵלוּת נוֹהֵג בּוֹ, לֹא בְּי\"ד וְלֹא בְּט\"ו, אֶלָא דְּבָרִים שֶׁבְּצִנְעָא נוֹהֵג, וְחַיָּב לִשְׁלֹחַ מָנוֹת. וְאַף עַל פִּי שֶׁאֵינוֹ מִתְאַבֵּל בָּהֶם, עוֹלִים לוֹ מִמִּנְיַן הַשִּׁבְעָה, כְּמוֹ שַׁבָּת.",["\u0003כדאיתא בסימן ש\"מ. \u0004כצ\"ל:","\u0003שמע כו'. \u0004ע\"ל סימן ש\"מ סל\"ב ובא\"ח סי' תקמ\"ז:","\u0003אחר חצות בע\"ש. \u0004(אע\"פ שבערב) [אבל בערב] ר\"ח ובערב חנוכ' אומרי' אפי' אחר חצות (לא) [דלא] עדיפי מע\"ש כ\"כ העט\"ז ומשמע דה\"ה בעי\"ט אחר חצות א\"א:","\u0003ומ\"מ אין אבילות נוהג בו כו'. \u0004ומהרש\"ל פסק דצריך לנהוג כל דיני אבילות ושכן המנהג והביאו הדרישה ע\"ש וכ\"כ המחבר בא\"ח סי' תרצ\"ו סעיף ד' ודרישה כתב ליישב דברי המחבר דלא סתרי אהדדי דבא\"ח מיירי שמת לו מת בו ביום וכאן מיירי שמת קודם לכן ודוחק והרב בהג\"ה שם פסק כהמחבר כאן) וכ' שכן נוהגין והב\"ח לא הביא אלא דברי מהרש\"ל ע\"ש:"],[]],["מִי שֶׁבָּאָה לוֹ שְׁמוּעָה שֶׁמֵּת לוֹ קָרוֹב, אִם בְּתוֹךְ ל' יוֹם הִגִיעָה הַשְּׁמוּעָה, אֲפִלוּ יוֹם ל' עַצְמוֹ, הֲרֵי זוֹ שְׁמוּעָה קְרוֹבָה וְחַיָּב לִנְהֹג שִׁבְעָה יְמֵי אֲבֵלוּת מִיּוֹם שֶׁהִגִיעַ הַשְּׁמוּעָה; וְקוֹרֵעַ וּמוֹנֶה ל' יוֹם \u0005מִיּוֹם הַשְּׁמוּעָה (כָּךְ מַשְׁמָע מֵהַרַמְבַּ\"ם וּמִנִּמּוּקֵי יוֹסֵף פא\"מ וּבְמָרְדְּכַי)\u0006 לְתִסְפֹּרֶת עִם שְׁאָר דְּבָרִים. \u0010c0\u0011 כְּלָלוֹ שֶׁל דָּבָר, יוֹם שְׁמוּעָתוֹ הַקְרוֹבָה כְּיוֹם הַקְבוּרָה. וְאִם שָׁמַע מִיּוֹם ל' וָאֵילָךְ, אֵין צָרִיךְ לִנְהֹג אֶלָא שָׁעָה אַחַת, לֹא שְׁנָא שָׁמַע בַּיּוֹם לֹא שְׁנָא שָׁמַע בַּלַיְלָה, שֶׁאִם שָׁמַע בַּלַיְלָה וְנָהַג מִקְצָת אֲבֵלוּת בַּלַיְלָה שָׁעָה אַחַת, עוֹלֶה לוֹ; וַאֲפִלוּ שָׁמַע עַל אָבִיו וְאִמּוֹ. וְהָנֵי מִלֵי לְעִנְיַן גְזֵרַת שִׁבְעָה, \u0010c1\u0011 אֲבָל לְעִנְיַן גְזֵרַת שְׁלֹשִׁים, נוֹהֵג עַל אָבִיו וְאִמּוֹ בְּתִסְפֹּרֶת עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו, וּבְגִהוּץ עַד שֶׁיַּגִיעַ הָרֶגֶל וְיִגְעֲרוּ בּוֹ, וְכֵן בִּשְׁאֵלַת שָׁלוֹם וְלִכָּנֵס לְבֵית הַמִּשְׁתֶּה; וּמוֹנֶה מִיּוֹם מִיתָה וְלֹא מִיּוֹם שְׁמוּעָה. \u0010y0\u0011 לְפִיכָךְ אִם בָּאָה לוֹ שְׁמוּעָה עַל אָבִיו וְאִמּוֹ לְאַחַר י\"ב חֹדֶשׁ, \u0010c2\u0011 אֵינוֹ נוֹהֵג אֶלָא יוֹם אֶחָד אַף בִּגְזֵרַת ל'.\nהַשּׁוֹמֵעַ שְׁמוּעָה רְחוֹקָה, אֵין צָרִיךְ לִנְהֹג כָּל דִּין אֲבֵלוּת, אֶלָא דַּיּוֹ בַּחֲלִיצַת מִנְעָל, וְאֵין צָרִיךְ לֹא עֲטִיפָה וְלֹא כְּפִיַּת הַמִּטָּה, וּמֻתָּר בִּמְלָאכָה, רְחִיצָה וְסִיכָה וְתַשְׁמִישׁ הַמִּטָּה וּבְתַלְמוּד תּוֹרָה, וְאִם אֵין לוֹ מִנְעָלִים בְּרַגְלָיו צָרִיךְ שֶׁיִּכְפֶה מִטָּתוֹ אוֹ יַעֲטֹף רֹאשׁוֹ, שֶׁצָּרִיךְ שֶׁיַּעֲשֶׂה מַעֲשֶׂה שֶׁנִּכָּר בּוֹ שֶׁעוֹשֶׂה מִשּׁוּם אֲבֵלוּת; וְאִם הָיָה עוֹסֵק בַּתּוֹרָה אוֹ בִּמְלָאכָה, אוֹ שֶׁהָיָה רוֹחֵץ וְסָךְ, וּבָאָה לוֹ שְׁמוּעָה, מַפְסִיק שָׁעָה אַחַת מִשּׁוּם אֲבֵלוּת, וְחוֹזֵר לְמַה שֶּׁבְּיָדוֹ, \u0010y1\u0011 אֲבָל אִם הָיָה לָבוּשׁ תְּפִלִין, אֵינוֹ צָרִיךְ לְחָלְצָן, וּמִכָּל מָקוֹם אֵינוֹ יוֹצֵא יְדֵי אֲבֵלוּת בְּהֶפְסֵק זֶה, וְצָרִיךְ שֶׁיַּעֲשֶׂה מַעֲשֶׂה שֶׁנִּכָּר שֶׁעוֹשֶׂה מִשּׁוּם אֲבֵלוּת, כְּגוֹן חֲלִיצַת מִנְעָל אוֹ כְּפִיַּת הַמִּטָּה וַעֲטִיפָה; וּמִיהוּ בְּחָדָא סָגֵי.\nאֵין מַבְרִין עַל שְׁמוּעָה רְחוֹקָה.\nאֵין קוֹרְעִין עַל שְׁמוּעָה רְחוֹקָה; וְעַל אָבִיו וְאִמּוֹ, קוֹרֵעַ לְעוֹלָם. \u0005וּבְמָקוֹם שֶׁאֵין לוֹ \u0010y2\u0011 לִקְרֹעַ, אָסוּר לְהַחְמִיר עַל עַצְמוֹ \u0010y3\u0011 וְלִקְרֹעַ (אוֹר זָרוּעַ)\u0006.\nהַשּׁוֹמֵעַ שְׁמוּעָה בְּשַׁבָּת אוֹ בָּרֶגֶל, וּלְמוֹצָאֵי שַׁבָּת וְרֶגֶל נַעֲשֵׂית רְחוֹקָה, אֵינוֹ נוֹהֵג \u0010c3\u0011 אֶלָא יוֹם אֶחָד, וּבְשַׁבָּת וְרֶגֶל אָסוּר בִּדְבָרִים שֶׁל צִנְעָא.\nהַשּׁוֹמֵעַ שְׁמוּעָה רְחוֹקָה בְּשַׁבָּת אוֹ בָּרֶגֶל, אֵינוֹ נוֹהֵג אֲפִלוּ דְּבָרִים שֶׁבְּצִנְעָא, וּלְמוֹצָאֵי שַׁבָּת וְרֶגֶל נוֹהֵג שָׁעָה אַחַת, וְדַיּוֹ.\nהַשּׁוֹמֵעַ שְׁמוּעָה קְרוֹבָה בְּשַׁבָּת הַשַּׁבָּת עוֹלָה לוֹ לְיוֹם אֶחָד, וּלְמָחָר קוֹרֵעַ, \u0010c4\u0011 וַהֲוָה לֵיהּ יוֹם שִׁשִּׁי שְׁבִיעִי לַאֲבֵלוּת.\nעֲשָׂרָה יָמִים אַחַר חַג הַסֻכּוֹת שָׁמַע שֶׁמֵּת לוֹ מֵת בְּעֶרֶב הֶחָג, אַף עַל פִּי שֶׁאִם נִמְנֶה שָׁעָה אַחַת לִפְנֵי הֶחָג ז' וְשִׁבְעַת יְמֵי הֶחָג וְיוֹם שְׁמִינִי עֲצֶרֶת כ\"א, וַעֲשָׂרָה יָמִים אֲחֵרִים הֲרֵי ל\"א, \u0010c5\u0011 אֵין לָזֶה דִּין שְׁמוּעָה רְחוֹקָה, \u0010y4\u0011 אֶלָא דִּין שְׁמוּעָה קְרוֹבָה, שֶׁאֵין הָרֶגֶל עוֹלֶה לְמִי שֶׁלֹּא נָהַג אֲבֵלוּת קֹדֶם לוֹ כְּלָל; וְכָל שֶׁכֵּן לְמִי שֶׁלֹּא הָיָה יוֹדֵעַ שֶׁמֵּת לוֹ מֵת \u0005(ר' יְרוּחָם בְּשֵׁם בַּעַל הַמָּאוֹר וְכ\"ד הָרַמְבַּ\"ן)\u0006.\nשָׁמַע שְׁתֵּי שְׁמוּעוֹת רְחוֹקוֹת בְּיוֹם אֶחָד, אֵינוֹ נוֹהֵג עֲלֵיהֶן \u0010y5\u0011 אֶלָא יוֹם אֶחָד. הָיוּ קְרוֹבוֹת, אוֹ שֶׁמֵּתוּ לוֹ שְׁנֵי מֵתִים כְּאֶחָד, מוֹנֶה לִשְׁתֵּיהֶם כְּאֶחָד שִׁבְעָה וּשְׁלֹשִׁים. \u0010y6\u0011 שָׁמַע לְזֶה הַיּוֹם וְלָזֶה לְמָחָר, מוֹנֶה לַשֵּׁנִי מִיּוֹם שְׁמוּעָה, שִׁבְעָה וּשְׁלֹשִׁים.\nשָׁמַע שְׁמוּעָה קְרוֹבָה בְּשַׁבָּת עֶרֶב הָרֶגֶל, כֵּיוָן דִּדְבָרִים שֶׁבְּצִנְעָא נוֹהֵג, \u0010y7\u0011 עוֹלֶה לוֹ אוֹתוֹ שַׁבָּת לִמִנְיַן שִׁבְעָה. \u0010y8\u0011\nמִי שֶׁהִתְפַּלֵל כְּבַר עַרְבִית וַעֲדַיִן יוֹם הוּא, וְשָׁמַע שְׁמוּעָה קְרוֹבָה, \u0010c6\u0011 מוֹנֶה מִיּוֹם מָחָר, וְאוֹתוֹ יוֹם אֵינוֹ עוֹלֶה לוֹ.\nמִי שֶׁמֵּת לוֹ מֵת וְלא נוֹדַע לוֹ, אֵינוֹ חוֹבָה שֶׁיֹאמְרוּ לוֹ; וַאֲפִלוּ בְּאָבִיו וְאִמּוֹ; וְעַל זֶה נֶאֱמַר: מוֹצִיא דִּבָּה הוּא כְּסִיל \u0005(מִשְׁלֵי י, יח)\u0006 וּמֻתָּר לְהַזְמִינוֹ לִסְעֻדַּת אֵרוּסִין וְנִשּׂוּאִין וְכָל שִׂמְחָה, כֵּיוָן שֶׁאֵינוֹ יוֹדֵעַ. מִיהוּ אִם שׁוֹאֵל עָלָיו, \u0010c7\u0011 אֵין לוֹ לְשַׁקֵר וְלוֹמַר: חַי הוּא, שֶׁנֶּאֱמַר: מִדְּבַר שֶׁקֶר תִּרְחָק \u0005(שְׁמוֹת כג, ז)\u0006. \u0005הַגָּה: וּמִכָּל מָקוֹם בְּבָנִים זְכָרִים, נָהֲגוּ לְהוֹדִיעַ, כְּדֵי שֶׁיֹּאמְרוּ קַדִּישׁ; אֲבָל בְּבָנוֹת, אֵין מִנְהָג כְּלָל לְהוֹדִיעָם\u0006 \u0005(מהרי\"ו סי' י\"ג)\u0006. \u0005מִצְוָה לְהִתְעַנּוֹת יוֹם שֶׁמֵּת בּוֹ אָבִיו אוֹ אִמּוֹ\u0006 \u0005(כָּל בּוֹ בְּשֵׁם הר\"מ וְעוֹד פּוֹסְקִים)\u0006, \u0005וּמִתְעַנִּין \u0010c8\u0011 יוֹם הַמִּיתָה וְלֹא יוֹם הַקְּבוּרָה\u0006 \u0005(מהרי\"ו סִימָן קכ\"א ומהרא\"י סִימָן רצ\"ו וְהָאַחֲרוֹנִים)\u0006, \u0010y9\u0011 \u0005אִם לֹא מִי שֶׁהָיָה אֵצֶל הַקְּבוּרָה וְלֹא אֵצֶל הַמִּיתָה.\u0006 \u0005(בְּקַבָּלָה מִפִּי זָקֵן מֻפְלָג מַהֲרַ\"ם לַנְדֹּא)\u0006 ; \u0005וְאִם אֵרַע יוֹם זֶה בְּיוֹם שֶׁאֵין אוֹמְרִים בּוֹ תַּחֲנוּן, אֵין מִתְעַנִּין כְּלָל. וְאִם מֵתוּ בַּאֲדָר וְנִתְעַבְּרָה הַשָּׁנָה, \u0010y10\u0011 הָעִקָּר לְהִתְעַנּוֹת בָּאֲדָר הָרִאשׁוֹן\u0006 \u0005(ת\"ה סִימָן רצ\"ד ומהר\"י מִינְ ץ)\u0006, אַף עַל פִּי שֶׁיֵּשׁ חוֹלְקִין, כָּךְ הוּא \u0010y11\u0011 עִקָּר. וְאִם מֵתוּ בִּשְׁנַת הָעִבּוּר בָּאֲדָר הַשֵּׁנִי, מִתְעַנֶּה גַּם כֵּן בְּעִבּוּר בָּאֲדָר הַשֵּׁנִי \u0005(ג\"ז שָׁם)\u0006. \u0005וְעַיֵּן בְּאֹרַח חַיִּים סִימָן תקס\"ח סָעִיף ז'. וְעַיֵּן לְעֵיל סִימָן שצ\"א שֶׁאֵין לֶאֱכֹל בִּסְעֻדָּה בְּלֵיל יוֹם שֶׁמֵּת בּוֹ אָב וָאֵם. וְאִם חָל תַּעֲנִית זֶה בְּעֶרֶב שַׁבָּת, דִּינוֹ כִּשְׁאָר תַּעֲנִית. וְעַיֵּן בא\"ח סִימָן רמ\"ט. מִיהוּ אִם בְּפַעַם רִאשׁוֹן הִשְׁלִים, יִנְהֹג כֵּן כָּל יָמָיו.\u0006",["\u0003לפיכך אם כו' אלא יום אחד. \u0004כלומר שעה אחת:","\u0003אבל אם היה לבוש תפילין א\"צ לחלצן. \u0004לפי שאף בשעת אבילות מניח תפילין ואינו חולץ אלא ביום ראשון לבד ולא תהא שמועה רחוקה חמורה מיום ב' של אבילות קרובה עכ\"ל רמב\"ן:","\u0003אסור להחמיר כו'. \u0004אם לא על אביו ואמו או אדם גדול שהיה רגיל להקשות לו בדבר הלכה דהוי מסתפי מיניה אם בא לעשות מילתא יתירה לכבודו מותר כ\"כ הב\"ח בסימן ש\"מ סעיף כ\"ה בשם א\"ז:","\u0003השומע כו' אלא יום אחד. \u0004כלומר שעה אחת ומכאן פסק הב\"ח לישב במוצאי שבת שעה א' על הארץ ולנהוג אבילות ואפי' אם חל יום הז' בשבת צריך לנהוג אבילות שעה אחת במוצ\"ש דהא הכא אף על גב דדברים שבצנעא נוהג בשבת לא נפטר בזה וצריך לעשות במו\"ש מעשה שניכר בו משום אבילות עכ\"ד ולפע\"ד ל\"ד כלל דהכא כיון שחכמים חייבו לנהוג אבילות כראוי עכ\"פ שעה אחת וביום השבת אין נוהגין אבילות רק במקצת א\"כ מעולם לא נהג זה דין אבילות כראוי אפי' שעה אחת לכן חייב למוצאי שבת או למוצאי הרגל לנהוג אבילות שעה א' אבל מי שנהג אבילות ז' ימים ובתוך הז' חל יום השבת למה יתחייב באבילות במו\"ש ואפילו זלזל במקצת הימים ולא נהג אבילות קי\"ל לעיל סי' שצ\"ז דאין צריך להשלים וכ\"ש יום השבת דנהג אבילות כדינו. עוד האריך הב\"ח להוציא דברי הר' יחיאל מפשטן ופסק דאם חל יום ז' של אבילות בשבת צריך לנהוג דברים שבצינעא כל היום כיון שאינו נוהג בשבת אלא דברים שבצינעא והביא ראיה ממאי דקי\"ל בסעיף ב' דצריך שיעשה מעשה הניכר משום אבילות וכל מעיין ישפוט בצדק דדעת הר\"ר יחיאל דגם בשבת אמרינן מקצת יום ככולו ונוהג מקצת יום השבת ותו לא ואין חולק עליו בזה והכי משמע פשט לישנא דש\"ס ופוסקים דלא לישתמיט חד לפלוגי בהכי ול\"ד לדלעיל סעיף ב' מטעם שכתבתי בסמוך:","\u0003אלא דין שמועה קרובה. \u0004ומתחיל למנות ז' ול' משעה ששמע וכתבו הב\"ח והדרישה בסי' שצ\"ט בשם מהרש\"ל דלפי זה היכא דמת ביום א' ונקבר ביום ב' אע\"פ שהקרובים שהיו אצל הקבורה מונים מיום הקבורה כי אז היתה סתימת הגולל מ\"מ אותן שלא היו אצל הקבורה ולא נודע להן שמת עד שהגיע יום ל' מיום הקבורה א\"צ לנהוג אבילות כיון דיום שמועה דידהו הוא יום ל\"א מיום המית' וה\"ל שמועה רחוקה דלגבי דין שמועה יום המיתה הוא עיקר ע\"כ:","\u0003אלא יום א'. \u0004כלומר שעה א':","\u0003שמע לזה היום כו'. \u0004וכן במתו לו שנים זה אחר זה כדלעיל סימן שע\"ה ס\"י:","\u0003עולה לו אותו שבת למנין שבעה. \u0004ושוב הרגל מבטל ממנו גזרת ז' כדלעיל ר\"ס שצ\"ט:","\u0003מי שהתפלל כו'. \u0004ע\"ל ס\"ס שע\"ה מ\"ש בזה:","\u0003אם לא מי שהיה אצל הקבורה ולא אצל המיתה. \u0004והעט\"ז השיג על זה דהא טעמא הוא דמתענין מפני הסכנה דריע מזליה ביום זה שמת אביו או אמו וא\"כ אין חילוק ולעולם יש להתענות יום המיתה עכ\"ד וכן משמע בתשובות מהר\"י ברין שהביא בב\"ח גם בתשובת משאת בנימין סימן פ\"ד הקשה על דברי הרב דאטו שני אחים שדרים בעיר אחת א' מהן היה אצל מיתת אביו והב' לא היה בעיר כשמת אביו וקודם הקבורה בא גם הב' שאז הא' יעשה יאר ציי\"ט ביום המיתה והב' למחרתו ואיכא משום לא תתגודדו וגם דמי לחוכא ואיטלולא ואנן בעי' דרכיה דרכי נועם עכ\"ל גם מדברי שאר אחרונים משמע דלעולם מתענין יום המיתה ולא יום הקבורה ובתשו' מ\"ב שם כתב דדוקא משנה ראשונה ואילך אבל בשנה א' לעולם עושין יא\"צ מיום הקבורה דאל\"כ לפעמים לא ישלים אבילות י\"ב חודש כגון אם מת בע\"ש בר\"ח שבט סמוך לשבת שאין פנאי לקברו קודם שבת ויקבר ביום א' שאחריו שהוא ג' שבט ואם אתה עושה היארציי\"ט ביום המיתה בר\"ח שבט גם האבלות יפסוק באותו יום כי כבר נהוג עלמא שלא להתאבל רק עד היאר ציי\"ט וזה ודאי לאו שפיר הוי דהאבילות מתחיל מיום הקבורה ולא מיום המיתה וצריך להשלים האבילות עד ג' שבט עכ\"ל ומעולם לא שמענו ולא ראינו לחלק שנות היאר ציי\"ט ולומר דבשנה ראשונה יש לעשות מיום הקבורה ואחר כך מיום המיתה גם מדברי כל האחרונים שכתבו סתמא דיש לעשות ביום המיתה משמע גם שנה ראשונה וכן משמע בת\"ה דלקמן דגם בשנה ראשונה עושים היאר ציי\"ט ביום המיתה ולענין קושייתו נראה לי דבלאו הכי נמי קשה דהא לפעמים משכחת לה דיום המיתה יהא מרוחק הרבה מיום הקבורה כגון שהוליכו למקום אחרת וכה\"ג כגון שמת בר\"ח ניסן ונקבר בי\"ד בניסן דאין האבילות מתחיל אלא מיום הקבורה וכדלעיל סימן שע\"ה והיאר ציי\"ט מתחיל מיום המיתה ודוחק לומר דלענין אבילות די\"ב חודש אזלינן בתר יום המיתה וגם דוחק לומר דאם אירע בכהאי גוונא יש לעשות היארציי\"ט קודם י\"ב חודש וכן משמע בת\"ה דלעולם עושים היאר ציי\"ט בסוף תשלום האבלות ולעולם מונים האבלות די\"ב חודש משעת הקבורה שכתב על מי שמת אביו בר\"ח ניסן דמן הדין מיד שיכנס אח\"כ ר\"ח ניסן שלים האבילות דהא כבר כלו י\"ב חודש אלא שהעולם נוהגין דאפי' בר\"ח ניסן כל אותו היום אין מבטלין דין אבילות די\"ב חודש ואפשר משום דאמרינן קדיש וברכו ומתענים כיום שמת בו אביו הוא לכן נוהגין ענין אבילות באותו היום אבל מן הדין אין צריך וגם נ\"מ למי שמתענה ואומר קדיש וברכו ביום המיתה והוא מת ביום ונקבר למחר דאבילות לעולם מיום קבורה מנינן עכ\"ל ע\"כ נראה דלעולם יש להתענות יום המיתה אלא דאם אירע דיום המיתה מרוחק מיום הקבורה ג' או ד' ימים או יותר יש להתענות בשנה ראשונה ביום הקבורה כדי שיעשה היאר ציי\"ט בתשלום האבלות כיון דלא אפשר בענין אחר וגם כיון דמילתא דלא שכיחא היא יש לסמוך בכה\"ג אמ\"ד לעשות ביום הקבורה ומשנה ראשונה ואילך יתענה ביום המיתה אבל מי שמת אביו ונקבר בו ביום או ביום שלאחריו יש להתענות ביום המיתה אף בשנה ראשונה כנ\"ל ודו\"ק:","\u0003העיקר להתענות באדר ראשון. \u0004ובא\"ח סימן תקס\"ח מסיים הרב מיהו יש מחמירין להתענות בשניהם וכ\"כ מהרש\"ל שכן נוהגין והביאו הבית חדש:","\u0003ואם מתו בשנת העיבור כו'. \u0004וה\"ה אם מתו בשנת העיבור באדר הראשון מתענים בשנת העיבור באדר הראשון וכן כתב מהרש\"ל שם דפשוט שאם מת בראשון או בשני שכך מתענין בשנים המעוברות:"],["\u0003כללו של דבר יום שמועתו כו'. \u0004מבואר בבית יוסף סימן זה בשם הרמב\"ן דביום השמועה קרובה לא יניח תפילין כמו ביום הקבורה:","\u0003אבל לענין גזירת שלשים. \u0004פירוש מה שתלוי בשאר קרובים במנין שלשים דהיינו גיהוץ ותספורת זה נוהג באביו עד שיגערו כו' ומה שכתב ומונה מיום המיתה רצונו לומר דברים האסורים בי\"ב חדש:","\u0003אינו נוהג אלא יום אחד. \u0004ואף אותו יום אמרינן מקצתו ככולו וכן ברמב\"ן וכ\"כ בא\"ח סימן תקמ\"ח:","\u0003אלא יום אחד. \u0004ר\"ל שעה אחת אבל אם שמע שמועה בשבת שהוא כ\"ט אז נוהג לאחר השבת שבעה ושלשים. רש\"ל. וטעם לזה שאינו נוהג אבילות אחר השבת אע\"ג דביום השבת התחיל והוא ביום השלשים דכיון שאינו מתאבל אבילות גמור באותו שבת רק בדברים שבצינעא על כן אין גזירת אבילות אחריו כך כתב ב\"י בשם רשב\"א וכ' הרמב\"ן דבאותו שבת ורגל אסור בדבר שבצינעא כל אותו יום ולא אמרינן בזה מקצתו ככולו כיון שיש עליו חוב ליום שאחריו שעה אחת היאך נאמר שיפסיק מאבילות ויחזור לו:","\u0003והוי ליה יום ששי שביעי. \u0004בטור כתב אחר זה וה\"ר יחיאל כתב שאין שבת עולה לו בתחילת המנין אלא יתחיל למנות ביום א' והוי ליה יום שביעי שביעי לאבילות ונוהג בו דברים שבצינעא במקצת היום עכ\"ל ופסק ב\"י כדעה הראשונה ומ\"מ הבאתי כאן דברי ה\"ר יחיאל ללמוד ממנו שאם מת באחד בשבת דהוי ליה יום ז' בשבת דאין לנהוג בו איסור בדברים שבצינעא אלא במקצת היום דהיינו בשחרית בהנץ החמה כמ\"ש ה\"ר יחיאל כאן לענין מת בשבת דבזה לא מצינו חולק עליו ואין להקשות הא אמרינן בסימן שצ\"ה בענין מקצת היום ככולו של יום השביעי דתלוי דוקא בעמדו המנחמים מאצלו והכי איתא להדיא בפ' אלו מגלחין ולא סגי בהנץ החמה כמו ביום שלשים הא לאו קושיא היא כלל דבכל ענין שאמרו מקצתו ככולו היינו שאותו מקצת צ\"ל בו מאותו ענין שחייב בשאר ימים בכולו דהיינו במקום שתלוי האבילות בקום עשה כגון במנין שבעה שצריך לעשות מעשה בחליצת סנדל וזקיפת המטה וכיוצא בהם בזה אמרינן דצריך באותו מקצת של יום השביעי לעשות מעשה החיוב עליו ולא סגי בשב ואל תעשה ונתנו גבול לזה המקצת עד קימת המנחמים מאצלו שעד אותה שעה ראוי להיות בקום עשה מה שמוטל עליו בעת ההיא מה שאין כן לדין ל' שאין עליו חיוב בקום עשה רק בשב ואל תעשה דהיינו דאסור גיהוץ ותספורת בזה סגי בהנץ החמה כיון דכבר נהג איסור בשב ואל תעשה די בכך ומשום הכי בשמע שמועה דחוקה שנוהגת שעה אחת היינו נמי בקום עשה שצריך לעשות מעשה דוקא כעין שצריך לעשות בשמועה קרובה שבעה ימים כן יעשה ברחוקה אותה שעה וכמ\"ש בסעיף ב' בסי' זה ומשום הכי כשחל יום שביעי של שבעה ימים בשבת סגי במקצת אע\"ג דאין עושה מעשה באותו מקצת דהא גם ביום השבת כולו לא יעשה מעשה הניכר אלא דעולה למנין משום דנוהג בו דבר שבצינעא ובזה סגי במקצת ממנו והוי כיום השלשים ממש שזכרנו כנ\"ל ברור אלא שראיתי למו\"ח ז\"ל שרוצה לחלוק על ה\"ר יחיאל ולומר דלא אמרי' ביום השבת יום שביעי מקצתו ככולו ורוצה לאסור לאותו אבל לקרות בתורה אפי' במנחה כיון שאין עושה מעשה הניכר בו משום אבילות ועפ\"ז כ' ליישב מה שנהגו איזה אנשים כשחל יום ז' בשבת לישב במוצאי שבת שעה אחת על הארץ כדי לעשות היכר לאבילות שביום השבת לא עשה היכר ודרך זה הוא רחוק מאד דהיאך ישלים ביום השמיני מה שהיה חייב בז' אין זה אלא תימה ותו דא\"כ אם יש שבת באמצע שבוע של אבילות היאך ישלים במ\"ש מה שחייב לעשות בשבת הלא אותו אבלות מה שעושה במוצאי שבת הוא משום חיוב יומא גופיה והיאך תצרפו לעבר ולעתיד. ואין ראיה מאותן אנשים דלאו דסמכי נינהו אלא יום השבת של ז' הוא ממש בדין ז' כמו דין ל' לענין שלשים דהיינו בשב ואל תעשה בדברים שבצינעא כמו בשלשים לגיהוץ ותספורת כן הוא ברור ונכון ודברי ה\"ר יחיאל שהביא הטור הם נכונים להלכה לענין זה שאם חל יום השביעי בשבת שאין צריך אלא מקצת בשחרית ואפי' בשחרית יש היתר לקרותו בתורה אלא כיון שבחול ממתין עד אחר התפלה של שחרית גם בשבת יעשה כן אבל במנחה יש היתר גמור לקרותו לתורה ואין עליו דין שביעי לגמרי כדעת ה\"ר יחיאל ואין חולק עליו בזה. ועוד כתב מו\"ח ז\"ל דאפשר דה\"ר יחיאל לא התיר אלא בתשמיש המטה וכיוצא בדברים דהויין בצינעא ואין שם פרסום כלל אבל לקרותו לתורה מודה ה\"ר יחיאל דאסור כיון שלא עשה מעשה הניכר לאבילות ומאד תמוהין דברים אלו דאנן איפכא תפסינן בכל מקום שאסור להתאבל בפרהסיא מ\"מ יעשה אבילות בצינעא וכאן היאך נימא דבצינעא יהא מותר ובפרהסיא אסור אין זה נכון כלל אלא גם בשבת מותר אחר תפלת שחרית בכל ואין עליו שום איסור מחמת אבילות לגמרי ואותן האנשים שיושבים על הארץ במוצאי שבת אחר יום השבת שהוא שביעי לאבילות הם עושים מדעתם ומוסיפים אבילות שלא מדברי חכמים כלל ואפשר שבא הטעות ההוא ממה שראו בסעיף ו' שבמוצאי שבת ורגל נוהג אבילות שעה אחת נמשך להם הטעות שבכל שבת של אבילות הם סוברים לעשות כן והוא טעות גמור דשם הוה החיוב הגמור במוצאי שבת משום שמועה רחוקה משא\"כ בזה ואדרבה משם ראיה למה שכתבתי שהרי כתב שם הרמב\"ן דבכל אותו שבת אסורים בדבר שבצינעא כמו שזכרתי בסעיף ה' והיינו משום שיש עליו עדיין חיוב אבילות במוצאי שבת משמע הא בלאו הכי לא אסור כל השבת אלא מקצתו ככולו וכן הוא עיקר בלי ספק:","\u0003אין לזה דין שמועה רחוקה. \u0004ה\"ה למי שמת ביום אחד ונקבר ביום שלאחריו חשבינן לענין שמועה קרובה מיום המיתה דבתר יום המיתה אזלינן בכל מילי זולת לענין אבילות דמתחיל מסתימת הגולל:","\u0003מונה מיום מחר. \u0004הטעם דהוי תרי קולי דסתרי אהדדי כיון דעשה אותו לילה לתפלת ערבית אל תעשהו יום ונראה לי דאם שמע שמועה קרובה בסוף יום ל' אחר תפלת ערבית ועדיין יום הוא ודאי לא אמרינן דהוה לילה מכח התפלה דלהחמיר אמרינן כן לענין שלא יעלה יום שעבר למנין ז' אבל לא להקל לומר שהוא שמועה רחוקה אלא צריך להתאבל) ודומה למ\"ש בסימן רס\"ב לענין מילה דלא איכפת לן בתפלה ובזה ודאי מונה מיום שעבר ולא ממחרת דאל\"כ הוה עושה תרי מילי דסתרי דכיון דחשבת ליה יום דלהוי שמועה קרובה היאך יתחיל למנות מיום המחרת דא\"כ הוי לילה ואין כאן אבילות לגמרי:","\u0003אין לו לשקר כו'. \u0004נראה דיש לומר בלשון דמשתמע לתרי אפי דהיינו שאין מבואר בפירוש בדבריו שהוא מת אלא הלשון סובל לחיים ולמיתה וראיה מדאיתא ברבי חייא ששאל לרב אבא קיים א\"ל אימא קיימת ופירשו התוס' דבלשון בתמיה אמר עד שאתה שואלני על אבי שאלני על אמי ומתוך זה הבין ר' חייא שמת אביו שמע מיניה שלא אמר בפירוש שמת:","\u0003יום המיתה ולא יום הקבורה. \u0004) כתוב בתשובת מהר\"ר בנימין נראה דהיינו דוקא משנה ראשונה ואילך אבל בשנה ראשונה לעולם עושין היאר ציי\"ט ביום הקבורה ולא ביום המיתה דאל\"כ לפעמים לא ישלים אבילות של י\"ב חדש כגון אם מת בע\"ש בר\"ח שבט ואין פנאי לקברו עד יום א' שהוא ג' שבט ואם יהיה לו יאר ציי\"ט ביום המיתה בר\"ח שבט גם האבילות יפסוק באותו היום כי כבר נהוג עלמא שלא להתאבל רק עד היאר ציי\"ט וזה ודאי לאו שפיר דהאבילות התחיל מיוה הקבורה ולא מיום המיתה וצריך להשלים האבילות עד יום הקבורה שהוא ג' שבט עכ\"ל. ולא אאמין שיצאו דברים אלו מפי אותו צדיק דודאי לא מונה שום אדם י\"ב חודש רק מיום המיתה דאטו מי שלא שמע שמת אביו עד חצי שנה ודאי לא ימנה רק חצי שנה באבילות דמ\"ש בסימן שצ\"ד דכל אותה שנה הדין מתוח כו' היינו מן מיתת המת לא מיום התחלת האבילות והכי נמי ודאי יסיים האבילות ביום ו' בר\"ח שבט ואז יהיה לו יאר ציי\"ט ומה לנו במה שלא יתאבל י\"ב חודש במילואם אם אי אפשר בכך ואדרבה לדידיה יש לתמוה דהא עכ\"פ לא יתאבל יותר מיום ו' שהוא היום דאז כלו י\"ב חודש ימי הדין שלו וירחיק היא\"ר ציי\"ט מן סיום אבילות שלו אלא לית מאן דחש לזה. הרחמן יגדור פרצת עמו ישראל וינחם אותם בבנין ירושלים במהרה בימינו אמן כן יהי רצון:"]],["הַמְלַקֵט עַצְמוֹת אָבִיו, אוֹ שֶׁל שְׁאָר קְרוֹבִים שֶׁמִּתְאַבְּלִים עֲלֵיהֶם, מִתְאַבֵּל עֲלֵיהֶם כָּל הַיּוֹם כֻּלוֹ, בְּכָל הַדְּבָרִים הַנּוֹהֲגִים בְּאָבֵל, בִּכְפִיַּת הַמִּטָּה וַעֲטִיפַת הָרֹאשׁ וּנְעִילַת הַסַנְדָּל וְתַשְׁמִישׁ הַמִּטָּה וּרְחִיצָה וְסִיכָה; וְלָעֶרֶב אֵין מִתְאַבֵּל עֲלֵיהֶם, אֲפִלוּ צְרוּרִים לוֹ בִּסְדִינוֹ. הָיָה עוֹמֵד וּמְלַקֵט, וְחָשְׁכָה לוֹ, מֻתָּר בַּיּוֹם שֶׁלְאַחֲרָיו. לְפִיכָךְ אֵין מְלַקְטִין אוֹתָם סָמוּךְ לַחֲשֵׁכָה, כְּדֵי שֶׁלֹּא יִהְיֶה נִמְצָא שֶׁלֹּא הִתְאַבֵּל עַל לִקוּט עַצְמוֹת אָבִיו. \u0010y0\u0011 \u0005וְאֵין אֲנִינוּת בְּלִקּוּט עֲצָמוֹת, רַק חָל עָלָיו אֲבֵלוּת מִיָּד (טוּר בְּשֵׁם הָרֹא\"שׁ)\u0006.\nכָּל שֶׁקוֹרֵעַ עָלָיו בִּשְׁעַת מִיתָתוֹ, קוֹרֵעַ עָלָיו בִּשְׁעַת לִקוּט עֲצָמוֹת. וְכָל שֶׁאֵינוֹ מִתְאַחֶה בִּשְׁעַת מִיתָתוֹ, אֵינוֹ מִתְאַחֶה בִּשְׁעַת לִקוּט עֲצָמוֹת.\nעֲצָמוֹת, אֵין עוֹמְדִין עֲלֵיהֶם בְּשׁוּרָה, אֲבָל אוֹמְרִים עֲלֵיהֶם תַּנְחוּמִין לְעַצְמָם. וְאֵין מַבְרִין עֲלֵיהֶם בְּחֶבֶר עִיר, אֲבָל מַבְרִין עֲלֵיהֶם בְּבֵיתוֹ. וְאֵין אוֹמְרִים עֲלֵיהֶם קִינָה וּנְהִי, אֲבָל אוֹמְרִים עֲלֵיהֶם קִלוּסִין. \u0005דְּהַיְנוּ שִׁבְחוֹ שֶׁל מֵת, וּמְשַׁבְּחִין לְהקב\"ה שֶׁמֵּמִית וּמְחַיֶּה (בַּטּוּר תִּמְצָא מְבֹאָר)\u0006.\nאֵין מְלַקְטִין עַצְמוֹת אָבִיו בַּמּוֹעֵד, וְאֵין צָרִיךְ לוֹמַר עַצְמוֹת שְׁאָר קְרוֹבִים.\nשָׁמַע שֶׁהַיּוֹם לִקְטוּ עַצְמוֹת אֶחָד מִקְרוֹבָיו שֶׁהוּא מִתְאַבֵּל עֲלֵיהֶם, אַף עַל פִּי שֶׁלֹּא הָיָה שָׁם, מִתְאַבֵּל עֲלֵיהֶם. \u0005אֲבָל שָׁמַע שֶׁנִּלְקְטוּ אֶתְמוֹל, אֵין מִתְאַבֵּל עֲלֵיהֶם (טוּר בְּשֵׁם הַיְּרוּשַׁלְמִי)\u0006.\nאֵין מְפָרְקִין אֶת הָעֲצָמוֹת וְלֹא מַפְסִיקִין אֶת הַגִידִים.\nלִקוּט עֲצָמוֹת \u0010y1\u0011 אֵינוֹ אֶלָא מִשֶּׁיִּכְלֶה הַבָּשָׂר; כָּלָה הַבָּשָׂר, אֵין הַצּוּרָה נִכֶּרֶת בָּעֲצָמוֹת, לְפִיכָךְ יָכוֹל לְלַקֵט בְּיָדוֹ עַצְמוֹת אָבִיו וְאִמּוֹ; וְאַף עַל פִּי כֵן נָכוֹן הַדָּבָר שֶׁלֹּא יִלְקְטֵם הוּא עַצְמוֹ, מֵהַהִיא דְּרַבִּי אֱלִיעֶזֶר בַּר צָדוֹק דִּבְסָמוּךְ.\nמְלַקֵט אָדָם עַצְמוֹת שְׁנֵי מֵתִים כְּאֶחָד בְּרֹאשׁ אֲפַרְסְקָל מִכָּאן, וּבְרֹאשׁ אֲפַרְסְקָל מִכָּאן, דִּבְרֵי רַבִּי יוֹחָנָן בֶּן נוּרִי. ר\"א אוֹמֵר: סוֹף אֲפַרְסְקָל לְהִתְעַכֵּל, וְסוֹף עֲצָמוֹת לְהִתְעַכֵּל, וְנִמְצְאוּ עַצְמוֹת שְׁנֵי מֵתִים מִתְעָרְבִים, אֶלָא מְלַקְטִין וְנוֹתְנִין כָּל אֶחָד לְעַצְמוֹ בְּאָרוֹן שֶׁל אֲרָזִים. אָמַר רַבִּי אֱלִיעֶזֶר בַּר צָדוֹק: כָּךְ אָמַר לִי אַבָּא בִּשְׁעַת מִיתָתוֹ: מִתְּחִלָה קִבְרוּנִי בְּבִקְעָה, וּלְבַסוֹף לְקֹט עַצְמוֹתַי וּתְנֵם בָּאֲרָזִים, וְאַל תִּלְקְטֵם אַתָּה בְּיָדְךָ, שֶׁלֹּא יִהְיוּ בְּזוּיוֹת עָלֶיךָ.\nהַמְלַקֵט עֲצָמוֹת, וְהַמְשַׁמֵּר אֶת הַמֵּת, וְהַמּוֹלִיךְ אוֹתָם מִמָּקוֹם לְמָקוֹם, פָּטוּר מִקְרִיאַת שְׁמַע וּמִתְּפִלָה וּמֵהַתְּפִלִין, וּמִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה, בֵּין בְּחֹל בֵּין בְּשַׁבָּת, לֹא שְׁנָא עַצְמוֹת קְרוֹבִים לֹא שְׁנָא עַצְמוֹת רְחוֹקִים, בֵּין אִם הוּא בִּסְפִינָה אוֹ בַּדֶּרֶךְ, \u0010y2\u0011 וַאֲפִלוּ אִם הֵם מְלַקְטִים רַבִּים. וְאִם רָצָה לְהַחְמִיר עַל עַצְמוֹ, לֹא יַחְמִיר, מִפְּנֵי כְּבוֹד עֲצָמוֹת.\nהַמּוֹלִיךְ עֲצָמוֹת מִמָּקוֹם לְמָקוֹם, הֲרֵי זֶה לֹא יִתְּנֵם בְּשַׂק אוֹ בְּדִסְקִיָּא וְיַנִּיחֵם עַל הַחֲמוֹר וְיִרְכַּב עֲלֵיהֶם, \u0010y3\u0011 מִפְּנֵי שֶׁנּוֹהֵג בָּהֶם מִנְהַג בִּזָּיוֹן; אֲבָל אִם מַפְשִׁילוֹ לַאֲחוֹרָיו עַל הַחֲמוֹר, שַׁפִּיר דָּמֵי. וְאִם הָיָה מִתְיָרֵא מִפְּנֵי הַגַנָּבִים וְהַלִסְטִים, מֻתָּר. \u0005הַגָּה: וְהַחַי יִתֵּן אֶל לִבּוֹ דְּבָרִים שֶׁל מִיתָה; דְּיִסְפַּד, יִסְפְּדוּנֵהּ; דְּיִקְבַּר, יִקְבְּרוּנֵהּ; דְּיִטְעֹן, יַטְעִינֵהּ; דְּיִדַּל, יַדְלוּנֵהּ; וְגָדוֹל הַשָּׁלוֹם שֶׁנִּתַּן לַצַּדִּיקִים, שֶׁבְּשָׁעָה שֶׁהַצַּדִּיק נִפְטָר ג' כִּתּוֹת שֶׁל מַלְאָכִים נוֹתְנִים לוֹ שָׁלוֹם. (הַכֹּל בַּטּוּר וְהָרֹא\"שׁ וְכָל בּוֹ)\u0006 \u0005(וְאוֹמְרִים יָבֹא שָׁלוֹם כָּל הַכָּתוּב לַחַיִּים קָדוֹשׁ יֵאָמֶר לוֹ)\u0006. בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים. \u0005(יְשַׁעְיָה כה, ח')\u0006.",["\u0003ואין אנינות כו'. \u0004כלומר שיאסר קודם שיקברו העצמות באכילת בשר ושתיית יין כדין אונן לעיל סימן שמ\"א אלא מיד חל עליו האבלות אף קודם שקברם וע\"ל סימן שע\"ה ס\"ז. כהן אינו רשאי ללקוט עצמות אביו דשמא נחסר אביו סא\"ז מ\"ו פירוש אם נחסר כל שהוא מאביו אסור ליטמא לו כדלעיל סוף סי' שע\"ג עכ\"ל דרישה:","\u0003אינו אלא משיכלה הבשר. \u0004כלומר לענין זה שילקטם הוא בעצמו וכדמפרש ואזיל אבל אה\"נ דאף כשלא כלה הבשר חייב להתאבל כל היום כדלעיל סימן שע\"ה סעיף ז' ודוק:","\u0003ואפי' הם מלקטים רבים. \u0004דוקא מלקטים רבים אבל משמרים רבים זה משמר וזה קורא וכמ\"ש בא\"ח סימן ע\"א ס\"ד:","\u0003מפני שנוהג בהם כו'. \u0004עיין לעיל סימן רפ\"ב סעיף ג':"],[]]]};
